    \begin{proposition}[{\cite[Theorem 1]{bergomi-steady-ranging}}]\label{prop_stability-balanced}
        \add{If $\pi$ is an ip-generator that is balanced for weighted graph filtrations, then it is stable for weighted graph filtrations.}
