\section{Preliminaries}\label{sec:prelim}

In this section we collect the necessary definitions and facts needed for the sequel.  Much of this material is taken from the works of Aougab--Clay--Rieck~\cite{ar:ACR23}, Parry--Pollicott~\cite{ar:PP90}, and Pollicott--Sharp~\cite{ar:PS14}.  We refer to those sources for motivation and further discussion on these topics.  
In addition, we give a computation in Section~\ref{subsec:computations} that will be used in the proof of Theorem~\ref{thm:main}.

\subsection{Graphs}\label{subsec:graphs}

A \emph{graph} is a tuple $G = (V,E,o,\tau,\bar{\phantom{e}})$ where:
\begin{enumerate}
    \item $V$ and $E$ are sets, called the \emph{vertices} and the \emph{directed edges}, 
\item  $o,\tau \from E \to V$ are functions that specify the \emph{originating} and \emph{terminating} vertices of an edge, and
\item $\bar{\phantom{e}} \from E \to E$ is a fixed-point free involution such that $o(e) = \tau(\bar{e})$.
\end{enumerate}
Given a graph, we fix a subset $E_+ \subset E$ that consists of exactly one edge from each pair $\{e,\overline{e}\}$.

A \emph{length function} on $G$ is a function $\ell \from E_+ \to \RR_{>0}$.  The moduli space of all such functions is denoted $\calM(G)$.  A length function $\ell$ extends to a function on $E$ by defining $\ell(e) = \ell(\bar{e})$ if $e \notin E_+$.

A \emph{\textup{(}based\textup{)} circuit} is a finite sequence of edges $(e_1,\ldots,e_n)$ where:
\begin{enumerate}
\item $t(e_i) = o(e_{i+1})$ for $i = 1, \ldots, n-1$ and $t(e_n) = o(e_1)$, and
\item $e_i \neq \bar{e}_{i+1}$ for $i = 1, \ldots, n-1$ and $e_n \neq \bar{e}_1$.
\end{enumerate}
Given a length function $\ell \in \calM(G)$, the length of a circuit $\gamma = (e_1,\ldots,e_n)$ is defined as:
\begin{equation*}
\ell(\gamma) = \sum_{i=1}^n \ell(e_i).
\end{equation*}
The set of all circuits in $G$ is denoted by $\calC(G)$.  For a given length function $\ell \in \calM(G)$, the subset of circuits whose length is at most $t$ is denoted $\calC_{G,\ell}(t)$.

\subsection{Entropy}\label{subsec:entropy}

The \emph{entropy} of a length function $\ell \in \calM(G)$ is defined as:
\begin{equation*}
\entropy_{G}(\ell) = \lim_{t \rightarrow \infty} \frac{1}{t} \abs{\calC_{G,\ell}(t)}.
\end{equation*}
This function $\entropy_{G} \from \calM(G) \to \RR_{\geq 0}$ is real analytic and strictly convex~\cite[Proposition~A.4]{ar:McMullen15}.  It is readily verified that $\entropy_G$ is homogeneous of degree $-1$.  That is:


\begin{equation} \label{homogeneous}
\entropy_G(\alpha\ell) = \frac{1}{\alpha}\entropy_G(\ell), 
\end{equation}


for any $\alpha > 0$~\cite[Lemma~3.4]{ar:ACR23}.


The subset of length functions with unit entropy is denoted $\calM^1(G)$.  That is:
\begin{equation*}
\calM^1(G) = \{ \ell \in \calM(G) \mid \entropy_G(\ell) = 1\}.
\end{equation*}

We associate to the graph $G$ a matrix that records the incident relations.  Specifically, we define an $\abs{E} \times \abs{E}$ matrix $A_{G}$ by
\begin{equation*}
A_{G}(e,e') = \begin{cases} 1 & \mbox{ if } \tau(e) = o(e') \mbox{ and } \bar{e} \neq e', \\
0 & \mbox{ else. }
\end{cases}
\end{equation*}
Given a length function $\ell \in \calM(G)$, we set $A_{G,\ell}$ to be the matrix obtained by multiplying the row of $A_G$ corresponding to $e \in E$ by $\exp(-\ell(e))$ for each edge.  That is:
\begin{equation*}
A_{G,\ell}(e,e') = \exp(-\ell(e))A_G(e,e').
\end{equation*}

This matrix is irreducible.  Moreover, we have that:
\begin{equation}\label{eq:entropy 1}
\entropy_G(\ell) = 1 \Leftrightarrow \spec(A_{G,\ell}) = 1
\end{equation}  
where $\spec(\param)$ denotes the spectral radius (cf.~\cite[Lemma~3.1(2)]{ar:PS14}).  

One can use \ref{eq:entropy 1} to prove easily that a lower bound on entropy implies an upper bound on the length of the shortest cycle: 

\begin{lemma} \label{lem:bers for graphs} Given $n$ and $\delta >0$, there is $\epsilon$ so that if $G$ is a metric graph of rank $n$ and has entropy at least $\delta$, then $G$ admits a cycle $\gamma$ with $\ell(G) < \epsilon$. 
\end{lemma}
\begin{proof}
If the lemma is false, then there exists a sequence of metric graphs  $\left\{G_{n} \right\}_{n \in \mathbb{N}}$ all of the same rank so that $\entropy(G_{n}) \ge \delta$ and so that the length of the shortest cycle on $G_{n}$ is at least $n$. Since there are only finitely many graphs of a given rank, we can assume each $G_{n}$ is of the same topological type; therefore we instead refer to a single graph $G$ with a sequence of metrics $\left\{ \ell_{n} \right\}$. 

We first prove that there must be an edge, $e$, with uniformly bounded length over all $\ell_{n}$. If not, then we can assume that every edge has length at least $n$ with respect to $\ell_{n}$. Also, by an application of \ref{homogeneous} we can assume that $\entropy(\ell_{n}) = 1$. But this is an immediate contradiction, because the entries of $A_{G, \ell_{n}}$ converge uniformly to $0$, whence it follows that the spectral radii also converge to $0$, but \ref{eq:entropy 1} implies that they must in fact all be $1$. 

Thus, there is some uniform $\epsilon_{1} >0$ and an edge $e$ so that $\ell_{n}(e) < \epsilon_{1}$, for all $n$. If $e$ is a self-loop, we are done. If not, it follows quite readily from the definitions that the metric graph $(G', \ell'_{n})$ obtained by contracting $e$ to a point and keeping all other edge lengths the same, has entropy at least that of $(G, \ell_{n})$. We can therefore apply the same argument, and induct on the number of edges of $G$: we eventually arrive at a sequence of edges $e_{i}$, each of length at most some $\epsilon_{i}$ (for some $\epsilon_{i}$ depending only on $G$) for all $\ell_{n}$, which form a cycle on $G$. It follows that there is some cycle of uniformly bounded length on $G$, over all $\ell_{n}$, as desired. 

\end{proof}

We will now use Lemma \ref{lem:bers for graphs} to verify Theorem \ref{thm:BersForGraphs} from the introduction, reproduced here for clarity:

\begin{theorem} There is a constant $\eta_{g} >0$ such that if $X$ is a closed hyperbolic surface of genus $g$, there is a proper essential subsurface $Y \subsetneq X$ with entropy at least $\eta_{g}$. Furthermore, the existence of $\eta_{g}$ is equivalent to the existence of $\beta_{g}$. 
\end{theorem}

\begin{proof} We first note that the existence of $\beta_{g}$ is equivalent to the existence of a single non-boundary-parallel simple closed geodesic of bounded length, which we will denote by $\beta'_{g}$; indeed, assuming that every hyperbolic surface that is not a three-holed sphere admits such a geodesic, we obtain Bers' theorem by applying this assertion iteratively, cutting along the short geodesic whose existence we assume, and inducting on the topology of the surface. 

Now, suppose that $X$ admits a proper essential subsurface $Y$ with entropy at least $\eta_{g}$. 
We claim that without loss of generality, there is some metric graph $\Gamma$ with a $1$-Lipschitz map into $Y$ and a constant $K\ge 1$ (depending only on $g$) with the property that  $\Gamma \hookrightarrow Y$ induces an isomorphism between fundamental groups, and so that if $\alpha \subset Y$ is some closed geodesic, then there is a cycle on $\Gamma$ homotopic to $\alpha$ and with length at most $K \cdot \ell_{X}(\alpha)$. Indeed, a simple hyperbolic geometry argument using the Gauss-Bonnet theorem implies that such a $\Gamma$ and a $K$ exists so that $K$ depends on $g$ and on the diameter of $Y$, which can not be arbitrarily large if there are no short curves in $Y$.

The definitions immediately imply that $\entropy(\Gamma)$ is uniformly comparable to $\entropy(Y)$, and thus by Lemma \ref{lem:bers for graphs}, $\Gamma$ must admit a cycle of length at most some $\beta'$ which we can take to depend only on $g$ because there are only finitely many topological types of graph that can arise as $\Gamma$. 


Conversely, assume that any hyperbolic surface $X$ admits a non-boundary-parallel simple closed geodesic $\alpha$ with length at most some $\beta'_{g}$. Then, cutting along $\alpha$, we obtain a subsurface $Y$ (which may be disconnected-- in the event that it is, choose one component at random). Applying the assumption again, we obtain a second simple closed geodesic $\gamma$ in $Y$, also with length at most $\beta'_{g}$. Using a similar application of the Gauss-Bonnet theorem as we did above, it follows that either there is a path from $\alpha$ to $\gamma$ through $Y$ of uniformly bounded length, or, there is some other short simple closed geodesic $\gamma'$ whose distance to $\alpha$ is less than the distance between $\gamma$ and $\alpha$. Applying this argument iteratively yields a metric graph embedded within $Y$ that has the form of a barbell with both self-loops having uniformly bounded length, and with the separating edge \textit{also} having uniformly bounded length in terms only of $g$. Thus the entropy of this barbell is bounded below in terms of some $\eta_{g}$, and therefore so is that of $Y$. 

\end{proof}




It follows from \ref{eq:entropy 1} and the Perron-Frobenius theorem that when $\entropy_G(\ell) = 1$, there are positive vectors $\bu,\bv \in \RR^{2\abs{E}}$ such that:
\begin{equation}\label{eq:PF vectors}
\bu^TA_{G,\ell} = \bu^T, \quad A_{G,\ell}\bv = \bv, \text{ and } \bu^T\bv = 1. 
\end{equation}
Moreover, these vectors are unique up to scale.  The \emph{equilibrium measure} $\mu$ is defined by taking the entry-wise products of $\bu$ and $\bv$, i.e., $\mu(e) = \bu(e)\bv(e)$.  This determines a measure on the set of bi-infinite lines in $G$ in the usual way, c.f.~\cite[Section~6.6]{bk:Walters82}.  We remark that, by symmetry, one has $\mu(e) = \mu(\bar{e})$.

\begin{notation}\label{notation:entropy}
For use later on, we define the following quantities:
\begin{align*}
\entropysup_G(\ell) & = \max\left\{ \entropy_{G'}\left(\ell\big|_{G'}\right) \mid G' \subset G \text{ is a proper subgraph}\right\} \\
\entropyinf(G) &= \inf\left\{ \entropysup_G(\ell) \mid \ell \in \calM^1(G)\right\} \\
\entropy_r &= \inf \left\{ \entropyinf(G) \mid \rk\pi_1 G = r \right\}
\end{align*}
\end{notation}
Theorem~\ref{thm:main} can be restated as $\entropy_r > 0$.  As there are only finitely many finite graphs of any given rank without valence one or two vertices, the infimum in the definition of $\entropy_r$ is actually a minimum.

We define a function $F_G \from \calM(G) \to \RR$ by:
\begin{equation}\label{eq:hypersurface}
F_G(\ell) = \det\left(I - A_{G,\ell}\right).
\end{equation}
From~\eqref{eq:entropy 1}, it follows that $F_G(\ell) = 0$ if $\entropy_G(\ell) = 1$.  Furthermore, we have the following relation between $F_G$ and the equilibrium measure $\mu$. 

\begin{lemma}\label{lem:proportion}
Let $\ell \in \calM^1(G)$ and let $\mu$ be the corresponding equilibrium measure.  Then $\nabla F(\ell)$ is proportional to $\mu$.  That is, there is a nonzero constant $C$ such that $\mu(e) = C\partial_eF(\ell)$ for all $e \in E_+$.
\end{lemma}

\begin{proof}
This follows as $\calM^1(G)$ is a component of $F_G^{-1}(0)$ and also the zero locus of $\log \spec(A_{G,\ell})$ since the gradient of the latter function is $\mu$.  See the proofs of Lemmas 3.9 and 4.4 in~\cite{ar:ACR23} for complete details.
\end{proof}

Finally, we note that $\entropy_G$ extends to a continuous function where we allow $\infty$ as a value for the length of an edge.  Indeed, this follows from the implicit function theorem as entropy is characterized by $\spec(A_{G,\entropy_G(\ell)\ell}) = 1$, and since characteristic functions and the Perron--Froebinous eigenvalue depend continuously on the matrix entries.

