We will provide a condition on the length of the edges in $\calB_2$ that ensures entropy of at least $\frac{1}{5}$.  The following lemma will allow us to compare the entropy of a given barbell to that of a certain rose: 

\begin{lemma}\label{lem:rose barbell compare}
For any positive constants, $a$, $b$, and $c$, we have that $\entropy_{\calB_2}(a,b,c) \geq \entropy_{\calR_2}(a,b+2c)$.
\end{lemma}

\begin{proof}
Fix a length function $\ell = (a,b,c) \in \calM(\calB_2)$ and let $\ell' \in \calM(\calR_2)$ be the length function defined by $\ell' = (a, b+2c)$.  

By identifying the initial and terminal segments of length $c$ of the edge $e_2$ in $\calR_2$, we get a map $\calR_2 \to \calB_2$ that induces a length decreasing bijection on cycles $\calC(\calR_2) \to \calC(\calB_2)$.  Hence we find that $\abs{\calC_{\calR_2,\ell'}(t)} \leq \abs{\calC_{\calB_2,\ell}(t)}$ and from this the lemma follows from the definition of entropy.
\end{proof}

Using this comparison, we can now prove a lemma that will be used in the proof of Theorem~\ref{thm:main} to produce a subgraph of definite entropy. 

\begin{lemma}\label{lem:barbell estimate}
Let $\ell \in \calM(\calB_2)$ be a length function where $\ell(e_1) = 3\exp(-c/2)$, $\ell(e_2) = c/4$ and $\ell(e_3) = c$ for any $c > 0$.  Then $\entropy_{\calB_2}(\ell) \geq \frac{1}{5}$.
\end{lemma}

\begin{proof}
Fix a positive constant $c$ and let $\ell \in \calM(\calB_2)$ be as in the statement.  Let $a = 3\exp(-c/2)$.  Then $\ell(e_2) = -\frac{1}{2}\log(a/3)$ and $\ell(e_3) = -2\log(a/3)$.  By Lemma~\ref{lem:rose barbell compare}, we find that:
\begin{equation}\label{eq:rose barbell comparison}
\entropy_{\calB_2}(\ell) = \entropy_{\calB_2}(a,-\frac{1}{2}\log(a/3), -2\log(a/3)) \geq \entropy_{\calR_2}(a,-5\log(a/3)).
\end{equation}  

Let $R_2(a) = -\log\left(\frac{1-\exp(-a)}{1+3\exp(-a)}\right)$ as in~\eqref{eq:R2}.  Then $\entropy_{\calR_2}(a,R_2(a)) = 1$ as explained in Section~\ref{subsec:rose}. 

\begin{claim*}
For $0 < a < 3$, we have $-5\log(a/3) \leq 5R_2(a)$.
\end{claim*}

\begin{proof}[Proof of Claim]
This is equivalent to
\begin{equation}\label{eq:inequality}
\exp(a)(1-a/3) \leq 1+a.
\end{equation}  
The inequality~\eqref{eq:inequality} is true for $a = 0$.  The derivative of the left hand side of~\eqref{eq:inequality} is $\frac{1}{3}(2-a)\exp(a)$.  We observe that 
\begin{equation}\label{eq:inequality 2}
\frac{1}{3}(2-a)\exp(a) \leq 1
\end{equation} 
for $0 \leq a \leq 3$, hence proving the claim, as 1 is the derivative of the right hand side of~\eqref{eq:inequality}.  Indeed, the function $\frac{1}{3}(2-a)\exp(a)$ on $0 \leq a \leq 3$ is maximized at $a= 1$ and we observe that $\frac{1}{3}\exp(1) \leq 1$ holds. 
\end{proof}

Therefore, by the claim, we find that:
\begin{equation*}
\entropy_{\calR_2}(a,-5\log(a/3)) \geq \entropy_{\calR_2}(a,5R_2(a)) \geq \entropy_{\calR_2}(5a,5R_2(a)) = \frac{1}{5}.
\end{equation*}  
The lemma now follows by combining this with~\eqref{eq:rose barbell comparison}.
\end{proof}



