As $\bu^T A = \bu^T$, we find that:
\begin{equation}\label{eq:u_e}
\bu(e) = 2\exp(-\ell(\gamma_1))\bu(\gamma_1) + \sum_{i=1}^n \exp(-\ell(e_i))\bu(e_i).
\end{equation}
We will denote the right-hand side of~\eqref{eq:u_e} by $X_\bu$ so that $\bu(e) = X_\bu$.  Similarly, as $A\bv = \bv$, we find that:
\begin{equation}\label{eq:v_e}
\bv(e) = \exp(-\ell(e))\left(2\bv(\gamma_2) + \sum_{i=1}^m \bv(e'_i)\right).
\end{equation}
We denote $2\bv(\gamma_2) + \sum_{i=1}^n \bv(e_i)$ by $X_\bv$ so that $\bv(e) = \exp(-\ell(e))X_\bv$.  Thus combining \eqref{eq:u_e} and \eqref{eq:v_e} we have
\begin{equation}\label{eq:mu_e}
\mu(e) = \bu(e)\bv(e) = \exp(-\ell(e))X_\bu X_\bv.
\end{equation}

We record the same calculations for $\bar{e}$ and find:
\begin{align*}
\bu(\bar{e}) & = 2\exp(-\ell(\gamma_2))\bu(\gamma_2) + \sum_{i=1}^m \exp(-\ell(e'_i))\bu(e'_i) = Y_\bu \\
\bv(\bar{e}) & = \exp(-\ell(e))\left(2\bv(\gamma_1) + \sum_{i=1}^n \bv(e_i)\right) = \exp(-\ell(e))Y_\bv
\end{align*}
Thus again we have that:
\begin{equation}\label{eq:mu_bare}
\mu(\bar{e}) = \exp(-\ell(e))Y_\bu Y_\bv.
\end{equation}

Next, we look at $\mu(\gamma_1)$ and $\mu(\gamma_2)$. We can compute them as above and compare these expressions to those for $\mu(e)$ and $\mu(\bar{e})$.  First we look at $\mu(\gamma_1) = \bu(\gamma_1)\bv(\gamma_1)$ and estimate these quantities.
\begin{align}
\bu(\gamma_1) &= \exp(-\ell(\gamma_1))\bu(\gamma_1) + \exp(-\ell(e))\bu(e) + \sum_{i=1}^n \exp(-\ell(e_i))\bu(e_i) \geq \frac{X_\bu}{2}\label{eq:u_gamma1} \\
\bv(\gamma_1) &= \exp(-\ell(\gamma_1))\left(\bv(\gamma_1) + \bv(e) + \sum_{i=1}^n \bv(e_i)\right) \geq \exp(-\ell(\gamma_1))\frac{Y_\bv}{2}\label{eq:v_gamma1}
\end{align}
In a similar manner, we also can estimate that $\bu(\gamma_2) \geq \frac{Y_\bu}{2}$ and $\bv(\gamma_2) \geq \exp(-\ell(\gamma_2))\frac{X_\bv}{2}$.  

Combining \eqref{eq:u_gamma1} and \eqref{eq:v_gamma1} together with these related inequalities, we find:
\begin{align*}
\mu(\gamma_1) + \mu(\gamma_2) & = \bu(\gamma_1)\bv(\gamma_1) + \bu(\gamma_2)\bv(\gamma_2) \\
& \geq \exp(-\ell(\gamma_1))\frac{X_\bu Y_\bv}{4} + \exp(-\ell(\gamma_2))\frac{X_\bv Y_\bu}{4} \\
& \geq \frac{1}{4}\exp(-\ell(\gamma_1)-\ell(\gamma_2))\left(X_\bu Y_\bv + X_\bv Y_\bu\right)
\end{align*}
As $\mu(e) = \mu(\bar{e})$, we have that $X_\bu X_\bv = Y_\bu Y_\bv$ by \eqref{eq:mu_e} and \eqref{eq:mu_bare}.  Hence $X_\bv = \frac{Y_\bu Y_\bv }{X_\bu}$ and $Y_\bv = \frac{X_\bu X_\bv}{Y_\bu}$.  Continuing the above inequalities, we find:
\begin{align*}
\mu(\gamma_1) + \mu(\gamma_2) &\geq \frac{1}{4}\exp(-\ell(\gamma_1)-\ell(\gamma_2))\left(X_\bu\left(\frac{X_\bu X_\bv}{Y_\bu}\right) + Y_\bu \left(\frac{Y_\bu Y_\bv }{X_\bu}\right)\right) \\
& = \frac{1}{4}\exp(-\ell(\gamma_1)-\ell(\gamma_2))\left(X_\bu X_\bv\left(\frac{X_\bu}{Y_\bu}\right) + Y_\bu Y_\bv \left(\frac{Y_\bu}{X_\bu}\right)\right) \\
& =  \frac{X_\bu X_\bv}{4}\exp(-\ell(\gamma_1)-\ell(\gamma_2))\left(\frac{X_\bu}{Y_\bu} + \frac{Y_\bu}{X_\bu}\right) \\
& \geq \frac{X_\bu X_\bv}{2} \exp(-\ell(\gamma_1) - \ell(\gamma_2)).
\end{align*}
The last inequality holds as $x + \frac{1}{x} \geq 2$ for $x \in (0,\infty)$.  Rewriting, we have:
\begin{equation}\label{eq:xx < gg}
X_\bu X_\bv \leq 2\exp(\ell(\gamma_1) + \ell(\gamma_2))(\mu(\gamma_1) + \mu(\gamma_2))
\end{equation}

The inequality \eqref{eq:xx < gg} together with \eqref{eq:mu_e} gives:
\begin{equation*}
\exp(\ell(e))\mu(e) = X_\bu X_\bv  \leq 2\exp(\ell(\gamma_1) + \ell(\gamma_2))(\mu(\gamma_1) + \mu(\gamma_2))
\end{equation*}
as desired.
\end{proof}

\section{The Proof of Theorem~\ref{thm:main}}\label{sec:proof}

In this section, we assemble the proof of Theorem~\ref{thm:main} and show that $\entropy_r > 0$.  To this end, suppose the theorem is false, that is $\entropy_r = 0$ for some fixed $r \geq 3$.  Let $G$ be the graph with witnessing sequence $(\ell_i) \subset \calM^1(G)$ as given by Proposition~\ref{prop:reduction}.  Fix a non-loop edge $e$ in $G$ and loop edges, $\gamma_{1}, \gamma_{2}$, incident to the vertices $o(e)$ and $t(e)$ respectively. Recall that by~\eqref{item:short loops} in Proposition \ref{prop:reduction}, we can assume that 
\[ \ell_i (\gamma_j) \leq \frac{1}{4} \ell_i (e), \text{ for } j= 1,2. \]

For each $i$, let $\psi_t^{(i)}$ be the linear time blow-up of $\ell_i$ along $e$ and let $j_i \from \RR_{\geq 0} \to \RR_{\geq 0}$ be the corresponding scaling function.  Denote the equilibrium measure at $\psi_t^{(i)}$ by $\mu^{(i)}_t$.  Let $G' = G - e$.  By Proposition~\ref{prop:estimate} we have that:
\begin{equation}\label{eq:witnessing entropy}
\entropy_{G'}\left(\ell_i\big|_{G'}\right) = 1 - \int_0^\infty \abs{j'_i(t)} \, dt = 1 - \int_0^\infty \frac{\mu_t^{(i)}(e)}{\sum_{e' \neq e} \ell_i(e')\mu_t^{(i)}(e')} \, dt.
\end{equation}

By Lemma~\ref{lem:estimate} and the definition of $\psi^{(i)}_t$, we find that:
\begin{align*}
\int_0^\infty \frac{\mu_t^{(i)}(e)}{\sum_{e' \neq e} \ell(e')\mu_t^{(i)}(e')} \, dt & \leq \int_0^\infty \frac{2\exp(\psi^{(i)}_t(\gamma_1) + \psi^{(i)}_t(\gamma_2) - \psi^{(i)}_t(e))(\mu_t^{(i)}(\gamma_1) + \mu_t^{(i)}(\gamma_2))}{\sum_{e' \neq e} \ell_i(e')\mu_t^{(i)}(e')} \, dt \\ 
&=  \int_0^\infty \frac{2\exp(j_i(t)\ell_i(\gamma_1) + j_i(t)\ell_i(\gamma_2) - \ell_i(e) - t)(\mu_t^{(i)}(\gamma_1) + \mu_t^{(i)}(\gamma_2))}{\sum_{e' \neq e} \ell_i(e')\mu_t^{(i)}(e')} \, dt
\end{align*}

Let $m^{(i)} = \min\{ \ell_i(\gamma_1), \ell_i(\gamma_2) \}$.  Then the final integral in the above inequality can be rewritten, using the fact that 
\[ m^{(i)}(\mu_t^{(i)}(\gamma_1) + \mu_t^{(i)}(\gamma_2)) \leq \sum_{e' \neq e} \mu_t^{(i)}(e') \ell_i(e'), \]   as follows:
\begin{multline*}
\int_0^\infty \frac{2\exp(j_i(t)\ell_i(\gamma_1) + j_i(t)\ell_i(\gamma_2) - \ell_i(e) - t)(\mu_t^{(i)}(\gamma_1) + \mu_t^{(i)}(\gamma_2))}{\sum_{e' \neq e} \ell_i(e')\mu_t^{(i)}(e')} \, dt \\ = 2\int_0^\infty \frac{\exp(j_i(t)\ell_i(\gamma_1) + j_i(t)\ell_i(\gamma_2) - \ell_i(e) - t)}{m^{(i)}}\frac{m^{(i)}(\mu_t^{(i)}(\gamma_1) + \mu^{(i)}(\gamma_2))}{\sum_{e' \neq e} \ell_i(e')\mu_t^{(i)}(e')} \, dt \\
\leq 2\int_0^\infty \frac{\exp(j_i(t)\ell_i(\gamma_1) + j_i(t)\ell_i(\gamma_2) - \ell_i(e) - t)}{m^{(i)}} \, dt.
\end{multline*}

As $j_i(t)\ell_i(\gamma_1) \leq \ell_i(\gamma_1) \leq \frac{1}{4}\ell_i(e)$, we have that $\ell_i(e) - j_i(t)\ell_i(\gamma_1) - j_i(t)\ell(\gamma_2) \geq \frac{1}{2}\ell_i(e)$.  Therefore, we find:
\begin{equation*}
2\int_0^\infty \frac{\exp(j_i(t)\ell_i(\gamma_1) + j_i(t)\ell_i(\gamma_2) - \ell_i(e) - t)}{m^{(i)}} \, dt \leq \frac{2\exp(-\ell_i(e)/2)}{m^{(i)}}\int_0^\infty \exp(-t) \, dt = \frac{2\exp(-\ell_i(e)/2)}{m^{(i)}}
\end{equation*}  

This now gives:
\begin{equation*}
\entropy_{G'}\left(\ell_i\big|_{G'}\right) = 1 - \int_0^\infty \frac{\mu_t^{(i)}(e)}{\sum_{e' \neq e} \ell_i(e')\mu_t^{(i)}(e')} \, dt \geq 1 - \frac{2\exp(-\ell_i(e)/2)}{m^{(i)}}.
\end{equation*}
Since $\entropy_{G'}\left(\ell_i\big|_{G'}\right) \to \entropyinf(G) = 0$ as $i \to \infty$ by assumption, we must have that $\frac{2\exp(-\ell_i(e)/2)}{m^{(i)}} \to 1$ as $i \to \infty$.  In particular, for large enough $i$, we find that $m^{(i)} \leq 3\exp(-\ell_i(e)/2)$.  

Therefore, the edges $e, \gamma_1, \gamma_2$ form a sub-barbell $\calB \subset G$ so that one of $\gamma_1, \gamma_2$ has length at most $3 \exp(- \ell_i(e)/2)$ and so that the other self-loop has length at most $\frac{1}{4} \ell_i (e)$. Lemma~\ref{lem:barbell estimate} applies and we conclude that for all sufficiently large $i$ we have $\entropy_{\calB}\left(\ell_i \big|_{\calB}\right) \ge \frac{1}{5}$ and hence $\entropysup_{G} (\ell_i) \geq \frac{1}{5}$ as well.
This is a contradiction.

