\section{Rose - Old} \label{Rose}

\begin{proposition}[{\cite[Proposition~7.3~\&~7.5]{ar:ACR23}}]\label{prop:Frose}
For any $r \geq 2$ and any length function $\ell \in \calM^1(\calR_r)$,
\begin{enumerate}[itemsep=5pt]
\item $\oF_{r}(\ell) = \sum_{S \subseteq [r]} (1 - 2\abs{S})\exp\left(-\ell^S\right)$;
\item $\oF_r(\ell) = 0$ if and only if $\entropy_{\calR_r}(\ell) = 1$.
\end{enumerate}
\end{proposition}


\begin{proposition}\label{prop:rose old}
For each $r \geq 3$, there is a constant $B_r > 0$ such that $\entropyinf(\calR_r) \geq B_r$.
\end{proposition}

\begin{proof}
Consider the following function:
\begin{equation}\label{eq:E_r}
E_r(L) = \log\left(\frac{1 + (2r-1)\exp(-L)}{1 - (2r-3)\exp(-L)}\right).
\end{equation}

\begin{claim}\label{claim:E_r}
For $r \geq 3$ we have that:
\begin{equation*}
\lim_{L \to \infty} \frac{E_2(L)}{E_r(L)} = \frac{1}{r-1}.
\end{equation*}
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:E_r}]
L'Hospital's rule.
\end{proof}

Without loss of generality, we assume that $\ell^1 \leq \ell^2 \leq \ell^i$ for $3 \leq i \leq r$.  Then, we find that (using the results from \cite{ar:ACR23}, essentially Lemma 7.7):
\begin{equation*}
\ell^1 \leq E_r(\ell^2)
\end{equation*}
Moreover, this is an equality in $r = 2$.

Let $L_0$ be such that for $L \geq L_0$ we have $\frac{E_2(L)}{E_r(L)} \geq \frac{1}{2r-2}$.  (I think $L_0 = \log(4r^2)$ works)

Now take the subgraph $R_2 \subset \calR_r$ which is the union of $e_1$ and $e_2$ and let $\ell\big|_{R_2}$ be the restriction of $\ell$ to $R_2$.    

If $\ell^2 < L_0$, then we find:
\begin{equation*}
\entropy_{R_2}(\ell\big|_{R_2}) > \entropy_{\calR_2}(L_0 \cdot \One) = \frac{\log(3)}{L_0}.
\end{equation*} 

Otherwise, we scale the metric $\ell\big|_{R_2}$ on $R_2$ by the ratio $\alpha = \frac{E_2(\ell^2)}{E_r(\ell^2)}$ and let $\ell_0$ be the resulting metric.  Then $\ell_0^1 \leq E_2(\ell^2)$ and $\ell_0^2 \leq \ell^2$, therefore $\entropy_{\calR_2}(\ell_0) > 1$.  Hence we find that:
\begin{equation*}
\entropy_{R_2}(\ell\big|_{R_2}) = \alpha\entropy(\ell_0) > \alpha \geq \frac{1}{2r-2}. 
\end{equation*}

Therefore $\entropysup_{\calR_r}(\ell) \geq \min\{\frac{\log(3)}{L_0},\frac{1}{2r-2}\}$.
\end{proof}

Conjecture: $B_r = \log(2)/\log(3)$??

Now, as done in Section \ref{Blow up}, we consider a smooth family $\psi_{t}$ of graphs so that the length of $e$ in $\psi_{t}$ equals $\ell_{G}(e) +t$ and so that the length of all other edges $e'$ equals $j(t) \cdot \ell_{G}(e')$, for some $j(t)$ chosen to normalize entropy. 

We claim that 
\begin{equation} \label{entropy of complement}
 \entropy(G \setminus e) = 1 + \int_{0}^{\infty} j'(t) dt. 
 \end{equation}

Indeed, the indefinite integral on the right hand side equals 
\[ \lim_{t \rightarrow \infty} j(t) - 1, \]
because $j(0) = 1$ since $\entropy(G)= 1$. Note that this limit exists because $j$ is monotonically decreasing and bounded below by $0$. Therefore, the right hand side of \ref{entropy of complement} is simply
\[ \lim_{t \rightarrow \infty} j(t). \]
Let $\lim_{t \rightarrow \infty} j(t) \cdot (G \setminus e)$ denote the metric graph whose underlying space is $G \setminus e$ and so that the length of an edge $e'$ is simply $\lim_{t \rightarrow \infty} j(t)\cdot \ell_{G}(e')$.   

Then by definition of $j$, 
\[ \entropy( \lim_{t \rightarrow \infty} j(t) \cdot (G \setminus e)) = 1\]
\[ \Rightarrow \entropy(G \setminus e) = \lim_{t \rightarrow \infty} j(t),  \]
as desired. 

Therefore, the theorem is proved if we can show that $\lim_{t \rightarrow \infty} j(t)$ is bounded away from $0$ in terms only of the rank of $G$, or equivalently, that 
\[ \int_{0}^{\infty} j'(t) dt \]
has absolute value bounded away from $1$.

