\section{Algorithm}
\label{appendix:algorithm}
\begin{algorithm}[H]
   \caption{\CLAP algorithm}
   \label{alg:example}
\begin{algorithmic}
    \State {\bfseries Input:} batch size $b$, number of views $m$, number of optimization steps $n$,\\
   size scaling factor $r_s$\\
   initialize feature extractor network $f_\theta$ \\
   initialize projection head $g_\phi$ \\
   initialize the distribution of random transforms $\mathcal{T}_1$ and  $\mathcal{T}_2$
    \For{$t=1$ {\bfseries to} $n$}
    \State sample a batch from the dataset $x_1,x_2,...x_b $ 
        \For{$i=1$ {\bfseries to} $b$} 
            \State \# for each image, augment half of the views with $\mathcal{T}_1$
            \State $x_i^1,...x_i^{m/2} = t^1(x_i)...,t^{m/2}(x_i). \quad t^1...t^{m/2} \sim \mathcal{T}_1$
            \State \#augment the other half of the views with $\mathcal{T}_2$ 
            \State $x_i^{m/2+1},...x_i^{m} = t^{m/2+1}(x_i)...,t^{m}(x_i). \quad t^{m/2+1}...t^m \sim \mathcal{T}_2$
            \State $y_i^1,...y_i^m = f_\theta(x_i^1),...f_\theta(x_i^m)$ \# extract features
            \State $z_i^1,...z_i^m = g_\phi(y_i^1),...g_\phi(y_i^m)$ \# projection
        \EndFor
        \State \# normalization
        \State $c = \frac{1}{mb} \sum_{i=1}^{b} \sum_{k=1}^{m} z_i^k$
        \State $\Tilde{z}_i^k = (z_i^k - c)/\norm{z_i^k - c}$ for $i=1...b,k=1...m$
        \For{$i=1$ {\bfseries to} $b$}
            \State $q_i = \frac{1}{m} \sum_k \Tilde{z}_i^k$ \ \# center of each sub-manifold
            \State $\Lambda_i = \frac{1}{m} \sum_k (\Tilde{z}_i^k - q_i)^T(\Tilde{z}_i^k - q_i)$ \# covariance matrix
            \State $r_i = r_s\sqrt{\frac{1}{m}\mathrm{Tr}(\Lambda_i)}$ \# manifold size
        \EndFor
    \State calculate the loss function
    {\small
    %\STATE $\mathcal{L}_{size} = \frac{1}{b} \sum_i r_i$ 
    \State $\mathcal{L}_{overlap}  = 
    \begin{cases}
    \sum\limits_{i\neq j}^{} \left( 1 - \frac{\norm{q_i - q_j}}{r_i + r_j} \right)^2 \text{,if } \norm{q_i - q_j} < r_i + r_j\\
    0 \text{,\quad otherwise } 
    \end{cases}$
   }
   \State  $\mathcal{L} = \log(\mathcal{L}_{overlap} )$
   \State update the network $f_\theta,g_\phi$ to minimize $\mathcal{L}$
   \EndFor
   \State {\bf return} $f_\theta$ and discard $g_\phi$
\end{algorithmic}
\end{algorithm}

