\section{Work and Memory Traffics of Modules in LLMs from the LLaMa Family}
\label{appendix:est}
In this section, we list out the amount of work and memory traffics that we have estimated for each modules of LLaMa in both phases. We reserved the following symbols for the following model parameters:
\begin{itemize}[noitemsep]
    \item $b$: batch size,
    \item $s$: sequence length,
    \item $h$: hidden size of dimension,
    \item $h_0$: intermediate size of MLP,
    \item $h_{kv}$: number of key-value heads,
    \item $h_q$: number of query heads.
\end{itemize}
We also reserve the following symbols for hardware specification and efficiency parameters:
\begin{itemize}[noitemsep]
    \item $S_c$: peak flop,
    \item $S_m$: peak memory bandwidth,
    \item $S_+$: peak communication bandwidth,
    \item $e_c$: MFU,
    \item $e_m$: MBU,
    \item $e_+$: communication efficiency.
\end{itemize}

\subsection{Normalization}
LLaMa adopts root mean square normalization (RMSNorm) \cite{zhang2019rootmeansquarelayer}.
\begin{itemize}
    \item For prefill phase, we count the amount of works and memory traffics as in Table \ref{tab:rms-est-p}.

    \begin{table}[!ht]
        \centering
        \small
        \begin{tabular}{| c | c | c | c |} 
        \hline
        $i$ & \textbf{Description}  & $W_i$ (unit: FLOP) & $Q_i$ (unit: byte) \\ 
        \hline\hline
        1 & \texttt{POW} & $bsh$ & $4bsh$ \\ \hline
        2 & \texttt{MEAN} & $bsh$ & $2bsh+2bs$ \\ \hline
        3 & \texttt{ADD} & $bs$ & $4bs$ \\ \hline
        4 & \texttt{RSQRT} & $bs$ & $4bs$ \\ \hline
        5 & \texttt{MUL} & $bsh$ & $4bsh+2bs$ \\ \hline
        6 & \texttt{MUL} & $bsh$ & $4bsh+2h$ \\ \hline
        \end{tabular}
        \caption{Works and memory traffics of each operation in the prefill phase of a LLaMa RMSNorm module.}
        \label{tab:rms-est-p}
    \end{table}

    We use the following formula to estimate the computation time of the prefill phase of RMSNorm module:
    \begin{equation} \label{eq:rms-est}
        T_{\text{RMSNorm}} = \frac{W_1}{P_1} + \frac{W_2}{P_2} + \frac{W_3}{P_3} + \frac{W_4}{P_4} + \frac{W_5}{P_5} + \frac{W_6}{P_6},
    \end{equation}
    where $P_i := \min\{I^*, I_i\}e_mS_m$, $I_i := W_i/Q_i$ for all $i = 1,2,3,4,5,6$.

    \item For decode phase, we modify the amount of works and memory traffics as in Table \ref{tab:rms-est-d}.
    \begin{table}[!ht]
        \centering
        \small
        \begin{tabular}{| c | c | c | c |} 
        \hline
        $i$ & \textbf{Description}  & $W_i$ (unit: FLOP) & $Q_i$ (unit: byte) \\ 
        \hline\hline
        1 & \texttt{POW} & $bh$ & $4bh$ \\ \hline
        2 & \texttt{MEAN} & $bh$ & $2bh+2b$ \\ \hline
        3 & \texttt{ADD} & $b$ & $4b$ \\ \hline
        4 & \texttt{RSQRT} & $b$ & $4b$ \\ \hline
        5 & \texttt{MUL} & $bh$ & $4bh+2b$ \\ \hline
        6 & \texttt{MUL} & $bh$ & $4bh+2h$ \\ \hline
        \end{tabular}
        \caption{Works and memory traffics of each operation in the decode phase of a LLaMa RMSNorm module.}
        \label{tab:rms-est-d}
    \end{table}

    We use the same formula \eqref{eq:rms-est} as in the prefill phase to estimate the computation time of the prefill phase of RMSNorm module.
\end{itemize}

