\subsection{Derivation of FIM}
By applying the Parseval’s theorem for the transition from the time domain to the frequency domain in (\ref{crb_derive}), the time-domain signals $x_\text{SO}(t)$ and $x_\text{ISAC}(t)$ are transformed into their frequency-domain representations, denoted as $X_\text{SO}(f)$ and $X_\text{ISAC}(f)$, respectively. Therefore, the FIM with respect to the unknown parameter $\tau$ can be derived as 
\begin{equation}
\begin{aligned}
     &J(\alpha,\mathbf{f})\hspace{-3pt}=\hspace{-3pt}\frac{2\lVert a \rVert^2}{\sigma^2}\big[\int_{B_O-\frac{B}{2}}^{B_O-\frac{B}{2}+\alpha B}\hspace{-25pt}p_\text{SO}\langle X_\text{SO}(f)X_\text{SO}^*(f)\rangle(2\pi f)^2df\\&+\int_{B_O-\frac{B}{2}+\alpha B}^{B_O+\frac{B}{2}}p_\text{ISAC}\langle X_\text{ISAC}(f)X_\text{ISAC}^*(f)\rangle(2\pi f)^2df\bigg]\\
     &=\dfrac{8\pi^2 N^2 \beta_{\textrm{s}}^2 | \mathbf{f}^H\mathbf{a}_\text{AP,s} |^2 T B}{3\sigma^2}\times\\&\bigg[\alpha\rho_\textrm{SO}\bigg(\big(B_O-\frac{B}{2}+\alpha B\big)^3-\big(B_O-\frac{B}{2}\big)^3\bigg)\\&-(1-\alpha)\rho_\textrm{ISAC}\bigg(\big(B_O-\frac{B}{2}+\alpha B\big)^3-\big(B_O+\frac{B}{2}\big)^3\bigg)\bigg],
\end{aligned}
\end{equation}
where $B_O$ is a free parameter and is determined based on the reduced FIM as presented in \cite{Bliss}.

\subsection{Proof of Lemma 2}
Let the FIM function in (\ref{FIM_eq}) be redefined as
\begin{equation}
\begin{split}
     J(\alpha,\mathbf{f})&=A\bigg[\alpha\rho_\textrm{SO}\bigg(\big(B_O-\frac{B}{2}+\alpha B\big)^3-\big(B_O-\frac{B}{2}\big)^3\bigg)-\\&(1-\alpha)\rho_\textrm{ISAC}\bigg(\big(B_O-\frac{B}{2}+\alpha B\big)^3-\big(B_O+\frac{B}{2}\big)^3\bigg)\bigg],
\end{split}
\end{equation}
where $A\triangleq {8\pi^2 N^2 \beta_{\textrm{s}}^2 | \mathbf{f}^H\mathbf{a}_\text{AP,s} |^2 T B}/{3\sigma^2}$. To analyze the convexity of $J(\alpha)$, we compute the second derivative with respect to $\alpha$, which yields
\begin{equation}
\begin{aligned}
    &\frac{d^2J(\alpha)}{d\alpha^2}=A\bigg(4B \rho_\text{SO}(B_O-\frac{B}{2}+\alpha B)^2\\&+6\alpha B\rho_\text{SO}(B_O-\frac{B}{2}+\alpha B)+4B \rho_\text{ISAC}(B_O-\frac{B}{2}+\alpha B)^2\\&\quad\quad\quad\quad\quad\quad\quad+6(1-\alpha)B\rho_\text{ISAC}(B_O-\frac{B}{2}+\alpha B)\bigg).
\end{aligned}
\end{equation}
Since all coefficients $A,B,\rho_\textrm{SO}, \rho_\textrm{ISAC}$ and $\alpha$ are positive, and the squared terms involving $(B_0-{B}/{2}+B_0)$ dominate the linear components, the second derivative is strictly positive for $\alpha \in [0,1]$. Therefore, $J(\alpha)$ is convex with respect to $\alpha$ for $0 \leq \alpha \leq 1$.

