       Define for each $t \in [0,1]$ an automorphism $\tau_{m,0}^{(t)}$ on $A_{\mathbb{U}}^{m,0}$ by
       $$
       \tau_{m,0}^{(t)}(u_{ij}) = u_{ij} \text{ for } 1 \leq i < j \leq m+1, \quad \tau_{m,0}^{(t)}(s_i) = u_{i,m+1}^{-t} s_i \text{ for } 1 \leq i \leq m.
       $$
       Then $\tau_{m,0}^{(0)} = \mathrm{id}$ and $\tau_{m,0}^{(1)} = \tau_{m,0}$, so the continuous family $\tau_{m,0}^{(t)}$, $t\in [0,1]$ defines a homotopy between $\mathrm{id}$ and $\tau_{m,0}$. This implies that $\mathrm{id}_* - (\tau_{m,0})_*^{-1} = 0$. By exactness of the Pimsner-Voiculescu sequence and freeness of the $K$-groups, we obtain
       \begin{align*}
       	K_0\left(A_{\mathbb{U}}^{m,0} \rtimes_{\tau_{m,0}} \mathbb{Z}\right) \cong K_1\left(A_{\mathbb{U}}^{m,0} \rtimes_{\tau_{m,0}} \mathbb{Z}\right) \cong K_0\left(A_{\mathbb{U}}^{m,0}\right) \oplus K_1\left(A_{\mathbb{U}}^{m,0}\right) &\cong \mathbb{Z}^{2^{2m + \binom{m}{2}}}\\
       	&= \mathbb{Z}^{2^{(m+1) + \binom{m+1}{2} - 1}}.
       \end{align*}
       Since $C_{\mathbb{U}}^{m+1,0} \cong A_{\mathbb{U}}^{m,0} \rtimes_{\tau_{m,0}} \mathbb{Z}$, the formula holds for $m+1$. By induction, the result follows for all $m \in \mathbb{N}$.
       \qed

       Let $A$ be a unital $C^*$-algebra, and let $\alpha$ be an automorphism of $A$. Consider the $C^*$-subalgebra $\mathcal{T}\left(A, \alpha\right)$ of $\left(A \rtimes_\alpha \mathbb{Z}\right) \otimes \mathcal{T}$ generated by $A \otimes 1$ and $w \otimes v$, where $w$ denotes the adjoint unitary in $A \rtimes_\alpha \mathbb{Z}$, and $v$ is an isometry generating the Toeplitz algebra $\mathcal{T}$. Then, as shown in \cite[Page~98]{PimVoi-1980aa}, there exists a short exact sequence
       $$
       0 \longrightarrow \mathcal{K} \otimes A \xrightarrow{i} \mathcal{T}\left(A, \alpha\right) \xrightarrow{\psi} A \rtimes_\alpha \mathbb{Z} \longrightarrow 0.
       $$

       The following proposition will play a key role in the computation of the $K$-groups for all $m,n$.

       \begin{ppsn}\label{Toeplitz identification}
       	Let $m,n \in \mathbb{N}_0$ with $m+n \geq 1$. Then there exists a $^*$-isomorphism $\phi : C_{\mathbb{U}}^{m,n+1} \longrightarrow \mathcal{T}\left(A_{\mathbb{U}}^{m,n}, \tau_{m,n}\right)$ satisfying $\phi(u_{ij}) = u_{ij} \otimes 1 \quad \text{for all } 1 \leq i < j \leq m+n+1$, and for $1 \leq i \leq m+n+1$,
       	$$\phi(s_i^{m,n+1}) =
       	\begin{cases}
       		s_i^{m+1,n}\otimes 1 & \text{if } i \neq m+1, \\
       		s_i^{m+1,n} \otimes v & \text{if } i = m+1.
       	\end{cases}$$
       \end{ppsn}

       \begin{proof}
       	\begin{figure}[h]
       		\centering
       		\[
       		\begin{tikzcd}[
       			column sep=large,
       			row sep=large,
       			execute at end picture={
       				% First \circlearrowright at (x1,y1)
       				\node at (-0.4, 0.0) {\scalebox{3.0}{$\circlearrowright$}};
       			}
       			]
       			C_{\mathbb{U}}^{m,n+1}
       			\arrow[r, "\phi"] 
       			\arrow[d, "\pi_x"']        			
       			& \mathcal{T}\left(A_{\mathbb{U}}^{m,n},\tau_{m,n}\right) 
       			\arrow[d, "\pi_x^{(1)}\otimes id|_{\mathcal{T}\left(A_{\mathbb{U}}^{m,n},\tau_{m,n}\right)}"] 
       			\\
       			C_x^{m,n+1} 
       			\arrow[r, "\phi_x", "\sim"'] 
       			& C
       		\end{tikzcd}
       		\]
       		\caption{Diagram corresponding to Proposition \ref{Toeplitz identification}}
       		\label{fig:commutative_diagram1}
       	\end{figure}

       	It is immediate from the definition that the map $\phi$ is a surjective $^*$-homomorphism. To prove injectivity, by Proposition~\ref{injective representation}, it suffices to show that for each nondegenerate point $x \in \mathbb{T}^{\binom{m+n+1}{2}}$, the canonical representation $\pi_x : C_{\mathbb{U}}^{m,n+1} \to C_x^{m,n+1}$ factors through $\phi$.

       	Let $\pi_x^{(1)} : C_{\mathbb{U}}^{m+1,n} \to C_x^{m+1,n}$ be the canonical surjection. Define $C := \left(\pi_x^{(1)} \otimes \mathrm{id}\right)\left[ \mathcal{T}(A_{\mathbb{U}}^{m,n}, \tau_{m,n}) \right]$. Note that $C$ is the $C^*$-subalgebra of $C_x^{m+1,n} \otimes \mathcal{T}$ generated by the elements $s_i^{m+1,n} \otimes 1$ for $i \neq m+1$, and $s_{m+1}^{m+1,n} \otimes v$. Define a $^*$-homomorphism $\phi_x : C_x^{m,n+1} \to C$ by
       	\[
       	\phi_x\left(s_i^{m,n+1}\right) =
       	\begin{cases}
       		s_i^{m+1,n} \otimes 1 & \text{if } i \neq m+1, \\
       		s_i^{m+1,n} \otimes v & \text{if } i = m+1,
       	\end{cases}
       	\]
       	for $1 \leq i \leq m+n+1$. Let $\mathcal{P} := \displaystyle\prod_{i=m+1}^{m+n+1} \left(1 - s_i^{m,n+1}\left(s_i^{m,n+1}\right)^*\right)$, and let $D$ be the $C^*$-subalgebra of $C_x^{m,n+1}$ generated by the elements $\mathcal{P}s_i$, for $1 \leq i \leq m$. We compute:
       	$$\phi_x(\mathcal{P}) =
       	\begin{cases}
       		1 \otimes (1 - vv^*) & \text{if } n = 0, \\
       		\left( \displaystyle\prod_{i = m+2}^{m+n+1} \left(1 - s_i^{m+1,n}\left(s_i^{m+1,n}\right)^*\right) \right) \otimes (1 - vv^*) & \text{if } n \neq 0,
       	\end{cases}$$
       	which is nonzero. Hence, $\phi_x|_D$ is nonzero. Since $x$ is nondegenerate, it follows that $\phi_x|_D$ is faithful. By Corollary~\ref{faithful homomorphism m,n}, $\phi_x$ is injective, and thus an isomorphism.

       	Therefore, the map $\pi_x$ factors as $\pi_x = \phi_x^{-1} \circ (\pi_x^{(1)} \otimes \mathrm{id}) \circ \phi$ (see Figure \ref{fig:commutative_diagram1}), which shows that $\phi$ is injective. Hence, $\phi$ is a $^*$-isomorphism.
       \end{proof}

       \begin{thm}
       	Let $m,n\in\mathbb{N}_0$ with $m+n\geq 2$. Then the $K$-groups of the $C^*$-algebra $C_{\mathbb{U}}^{m,n}$ are given by
       	$$K_0\left(C_{\mathbb{U}}^{m,n}\right) \cong K_1\left(C_{\mathbb{U}}^{m,n}\right) \cong \mathbb{Z}^{2^{m+\binom{m+n}{2}-1}}.$$
       \end{thm}  

       \begin{proof}
       	We proceed by induction on $n \in \mathbb{N}_0$.

       	\textbf{Base case:} For $n = 0$, the assertion follows from Proposition~\ref{K1 general 1}.

       	\textbf{Inductive step:} Assume that for some $n \geq 0$ and all $m \in \mathbb{N}_0$ with $m + n \geq 2$, we have
       	\[
       	K_0\left(C_{\mathbb{U}}^{m,n}\right) \cong K_1\left(C_{\mathbb{U}}^{m,n}\right) \cong \mathbb{Z}^{2^{m + \binom{m+n}{2} - 1}}.
       	\]
       	We now show that for all $m \in \mathbb{N}_0$ with $m+n \geq 1$, it holds that
       	\[
       	K_0\left(C_{\mathbb{U}}^{m,n+1}\right) \cong K_1\left(C_{\mathbb{U}}^{m,n+1}\right) \cong \mathbb{Z}^{2^{m + \binom{m+n+1}{2} - 1}}.
       	\]
       	By Proposition~\ref{Toeplitz identification}, we have $C_{\mathbb{U}}^{m,n+1} \cong \mathcal{T}\left(A_{\mathbb{U}}^{m,n}, \tau_{m,n}\right)$, and by Lemma~2.3 together with the proof of Theorem~2.4 in \cite{PimVoi-1980aa}, we obtain $K_i\left(\mathcal{T}\left(A_{\mathbb{U}}^{m,n}, \tau_{m,n}\right)\right) \cong K_i\left(A_{\mathbb{U}}^{m,n}\right), \, i=0,1$. Hence,
       	\[
       	K_i\left(C_{\mathbb{U}}^{m,n+1}\right) \cong K_i\left(A_{\mathbb{U}}^{m,n}\right), \quad i=0,1.
       	\]

       	\textit{\textbf{Case 1:} $m+n = 1$.} Then $(m,n) = (0,1)$ or $(1,0)$.

       	If $(m,n) = (0,1)$, then $A_{\mathbb{U}}^{0,1} \cong \mathcal{T} \otimes C\left(\mathbb{T}\right)$, so
       	\[
       	K_i\left(C_{\mathbb{U}}^{0,2}\right) \cong K_i\left(A_{\mathbb{U}}^{0,1}\right) \cong K_0\left(\mathcal{T}\right) \oplus K_1\left(\mathcal{T}\right) \cong \mathbb{Z}, \quad i = 0,1.
       	\]

       	If $(m,n) = (1,0)$, then $A_{\mathbb{U}}^{1,0} \cong C\left(\mathbb{T}\right) \otimes C\left(\mathbb{T}\right)$, so
       	\[
       	K_i\left(C_{\mathbb{U}}^{1,1}\right) \cong K_i\left(A_{\mathbb{U}}^{1,0}\right) \cong K_0\left(C\left(\mathbb{T}\right)\right) \oplus K_1\left(C\left(\mathbb{T}\right)\right) \cong \mathbb{Z}^2, \quad i = 0,1.
       	\]
       	In both cases, the result agrees with the stated formula.

       	\textit{\textbf{Case 2:} $m+n \geq 2$.} Then $A_{\mathbb{U}}^{m,n} \cong C_{\mathbb{U}}^{m,n} \otimes C\left(\mathbb{T}\right)^{\otimes (m+n)}$. By repeated application of the Pimsner-Voiculescu six-term exact sequence for crossed products of the form $A \rtimes_{\mathrm{id}} \mathbb{Z} \cong A \otimes C\left(\mathbb{T}\right)$, we get
       	\[
       	K_i\left(C_{\mathbb{U}}^{m,n+1}\right) \cong K_i\left(A_{\mathbb{U}}^{m,n}\right) \cong K_0\left(C_{\mathbb{U}}^{m,n}\right)^{\oplus 2^{m+n}} \oplus K_1\left(C_{\mathbb{U}}^{m,n}\right)^{\oplus 2^{m+n}}, \quad i = 0,1.
       	\]
       	Using the induction hypothesis, $K_0\left(C_{\mathbb{U}}^{m,n}\right) \cong K_1\left(C_{\mathbb{U}}^{m,n}\right) \cong \mathbb{Z}^{2^{m + \binom{m+n}{2} - 1}}$, we obtain
       	\[
       	K_i\left(C_{\mathbb{U}}^{m,n+1}\right) \cong \left(\mathbb{Z}^{2^{m + \binom{m+n}{2} - 1}}\right)^{\oplus 2^{m+n}} \cong \mathbb{Z}^{2^{m + \binom{m+n+1}{2} - 1}}, \quad i = 0,1.
       	\]

       	This completes the induction and the proof.
       \end{proof}

\section{Twisted isometries with finite dimensional wandering spaces}

In this section, we classify the universal $C^{*}$-algebra generated by a pair $(T_{1},T_{2})$ of doubly non commuting isometries with respect to the parameter $\theta$ under the assumption that all the wandering subspaces are finite dimensional. 

\bppsn \label{KK}
Let $\xi$ and  be two full essential extensions of $\cla_{\theta}^2$ by $\mathcal{K}^{\oplus n}$ given by;
\[
\xi:0\rightarrow \mathcal{K}^{\oplus n} \rightarrow \mathbf{C} \rightarrow \mathcal{A}_{\theta}^{2}\rightarrow  0, \qquad \xi^{\prime}:0\rightarrow \mathcal{K}^{\oplus n} \rightarrow \mathbf{C}^{\prime} \rightarrow \mathcal{A}_{\theta}^{2}\rightarrow  0.
\]
If $[\xi]=[\xi^{\prime}]$ in $KK^1\left(\cla_{\theta},\, \mathcal{K}^{\oplus n} \right)$ then $\mathbf{C}$ is isomorphic to $\mathbf{C}^{\prime}$.
\eppsn 
\prf Note that $ \mathcal{A}_{\theta}^{2}$ satisfies  the Universal Coeﬃcient
Theorem.  Moreover, $\mathcal{K}^{\oplus n} \cong C(I_n)\otimes \clk$, and therefore, $Q\left(\mathcal{K}^{\oplus n}\right)$ has property $(P)$. From Theorem $2.4$ in \cite{Lin-2009aa}, it follows that $\xi$ and $\xi^{\prime}$  are unitary equivalent, hence weakly isomorphic (see page 67). Hence $C$ and $C^{\prime}$ are isomorphic. 

\qed

\begin{rmrk} \label{remark 1}
	Consider the operators $T_{1}=S^{*}\otimes 1$ and $T_{2}=e^{2\pi\mathrm{i}\theta N}\otimes S^{*}$ on $\ell^{2}(\mathbb{N})^{\otimes 2}$. Let $\mathfrak{A}_{\theta}$ denote the $C^{*}$-subalgebra of $\cll\left(\ell^2(\bbn)^{\otimes 2} \right)$ generated by $T_{1}$ and $T_{2}$. Since the representation mapping $s_1 \mapsto T_1$ and $s_2 \mapsto T_2$ is a faithful representation of $C_{\theta}^{0,2}$, it follows that  $\mathfrak{A}_{\theta}$ is isomorphic to $C_{\theta}^{0,2}$. Moreover, we have $K_{0}(\mathfrak{A}_{\theta})=\mathbb{Z}$ and $K_{1}(\mathfrak{A}_{\theta})=0$. 
\end{rmrk}

\bdfn Let $\Gamma_n=\{(\lambda_1,\cdots, \lambda_n)\in \bbbt^n: \lambda_{i}\neq\lambda_{j} \mbox{ for all } 1\leq i\neq j\leq n\}$.  Take $\Lambda \in \Gamma_n$. Consider the operators $T_{1}$ and $T_{2}$ on $\ell^2(\mathbb{N})^{\oplus n}$ defined as 
$$T_{1}=\left(S^*\right)^{\oplus n},\,\quad  T_{2}=\bigoplus_{i=1}^n \left(\lambda_i e^{-2\pi\mathrm{i}\theta N}\right).$$  
The $C^*$-algebra $\mathfrak{D}_{n,\theta}^{\Lambda}$ is defined to be the $C^{*}$-subalgebra  of $\cll\left(\ell^2(\mathbb{N})^{\oplus n}\right)$ generated by $T_{1}$ and $T_{2}$.
\edfn
It is clear that for $n=1$,  $\mathfrak{D}_{n,\theta}^{\Lambda}$  does not depend on $\Lambda$. In what follows, we will show that for higher values of $n$, $\mathfrak{D}_{n,\theta}^{\Lambda}$ is independent of $\Lambda$, and thereby, we denote it by $\mathfrak{D}_{n,\theta}$. 

\bppsn \label{short exact sequence 1} Let $\Lambda\in \Gamma_n$ and $\theta \in \bbr \setminus \bbq$.  Then 
 there is the following short exact sequence
\[
\xi^{\Lambda}_n: \quad 0\longrightarrow \mathcal{K}^{\oplus n} \xrightarrow{i}\mathfrak{D}_{n,\theta}^{\Lambda} \xrightarrow{\eta} \mathcal{A}_{\theta}^{2}\longrightarrow  0.
\]
where $\eta$ maps the generators $T_1$ and $T_2$ of $\mathfrak{D}_{n,\theta}^{\Lambda}$ to the  generators $s_1$ and $s_2$, respectively, of $\mathcal{A}_{\theta}^{2}$.
\eppsn 
\prf We have 
$$ I-T_{1} T_{1}^{*}=p^{\oplus n} \quad \mbox{ and }  \quad T_2\left(I-T_{1} T_{1}^{*}\right)= \bigoplus_{r=1}^n\left(\lambda_rp\right). $$
This shows that $0\oplus\left(\bigoplus_{j=2}^n \left(\alpha_j p\right)\right) \in \mathfrak{D}_{n,\theta}^{\Lambda}$, where $\alpha_j =1- \overline{\lambda_1}\lambda_j \notin \{0,1\}$.
Proceeding in this way, we get $0^{ \oplus (n-1)} \oplus  p \in \mathfrak{D}_{n,\theta}^{\Lambda}$. Similarly, we have $0^{\oplus (r-1)} \oplus p \oplus 0^{\oplus (n-r)}  \in \mathfrak{D}_{n,\theta}^{\Lambda}$ for all $1\leq r \leq n$.
By multiplication  with $T_{1}^{i}$ on left and ${T_{1}^{*}}^{j}$ on right in each of the above elements, we have 
$0^{\oplus (r-1)}\oplus p_{ij}\oplus 0^{\oplus (n-r)} \in \mathfrak{D}_{n,\theta}^{\Lambda}$ for all $1\leq r \leq n$. This proves that $\mathcal{K}^{\oplus n} \subset  \mathfrak{D}_{n,\theta}^{\Lambda}$ as a closed ideal.  Moreover,  the generators $[T_1]$ and $[T_2]$ of the quotient $C^*$-algebra $\mathfrak{D}_{n,\theta}^{\Lambda} / {\mathcal{K}^{\oplus n}}$ satisfy the defining relations of $\mathcal{A}_{\theta}^2$. By simplicity of $\mathcal{A}_{\theta}^2$, we get $\mathfrak{D}_{n,\theta}^{\Lambda} / \mathcal{K}^{\oplus n} \cong \mathcal{A}_{\theta}^2$. Hence we have the following short exact sequence
\[
\quad 0\longrightarrow \mathcal{K}^{\oplus n} \xrightarrow{i} \mathfrak{D}_{n,\theta}\xrightarrow{\pi} \mathcal{A}_{\theta}^{2}\longrightarrow  0.
\]
\qed 
\blmma  \label{full} 
Let $\Lambda\in \Gamma_n$ and $\theta \in \bbr \setminus \bbq$. 
Then the  short exact sequence
$\xi^{\Lambda}_n$ is a full essential extension of $\mathcal{A}_{\theta}^{2}$ by  $\mathcal{K}^{\oplus n}$.
\elmma 
\prf 
Let $\tau^{\Lambda}_n:\mathcal{A}_{\theta}^{2} \rightarrow Q\left(\mathcal{K}^{\oplus n}\right)$ be the Busby invariant corresponding to $\xi^{\Lambda}_n$.  Since $\mathcal{A}_{\theta}^{2}$  is simple, $\tau^{\Lambda}_n$ is injective, proving that   the extension $\xi^{\Lambda}_n$ is essential. To prove $\xi^{\Lambda}_n$ is full, first observe that  $Q\left(\mathcal{K}^{\oplus n}\right)\cong Q^{\oplus n} \cong C(I_n) \otimes Q$, and hence all the ideals  are of the form $\mathfrak{J}_F; \, F \subset I_n$, where $\mathfrak{J}_F=\{f:I_n \rightarrow Q: f(x)=0 \mbox{ for all } x \in F\}$.   Take a nonzero element $a \in \mathcal{A}_{\theta}^{2}$.  Then $\langle a \rangle =\mathcal{A}_{\theta}^2$ as $\mathcal{A}_{\theta}^2$ is simple, and hence we have 
\[
 \tau^{\Lambda}_n(\mathcal{A}_{\theta}^2)=  \tau^{\Lambda}_n( \langle a \rangle )\subset   \langle \tau^{\Lambda}_n(a) \rangle. 
\]
Since  $\tau^{\Lambda}_n(s_1)=\left[\left(S^*\right)^{\oplus n}\right]$, the only ideal containing  $\tau^{\Lambda}_n(a)$ is $Q\left(\mathcal{K}^{\oplus n}\right)$, proving the claim.
\qed 
\begin{ppsn}\label{General 1}
Let $\Lambda\in \Gamma_n$ and $\theta \in \bbr \setminus \bbq$.  Then one has the following: $$K_{0}\left(\mathfrak{D}_{n,\theta}^{\Lambda}\right)\cong \mathbb{Z}^{n+1} \mbox{ and } K_{1}\left(\mathfrak{D}_{n,\theta}^{\Lambda}\right)\cong\mathbb{Z}.$$
\end{ppsn}



\begin{proof}

	The six term short exact sequence of $K$-groups corresponding to the short exact sequence $\xi^{\Lambda}_n$ is given by the following.
