	Since the generators $s_{1},s_{2}$ of $\mathcal{A}_{\theta}^{2}$ lift to the generators $T_{1},T_{2}$ of $\mathfrak{D}_{n,\theta}^{\Lambda}$, respectively, we have $\delta\left(s_1\right)=p^{\oplus n}$, and $\delta\left(s_2\right)=0$. Using this, and the fact that $K_1\left(\mathcal{K}^{\oplus n}\right)=0$, we get the claim.
\end{proof}
\bthm   \label{homotopy} Let $n \in \bbn$ and $\Lambda, \Lambda^{\prime} \in \Gamma_n$. Then $\mathfrak{D}_{n,\theta}^{\Lambda}$ is isomorphic to $\mathfrak{D}_{n,\theta}^{\Lambda^{\prime}}$.
\ethm 
\prf  Since $\Gamma_n$ is path-connected, one gets a path $f(t); \, 0\leq t \leq 1,$ joining $\Lambda$ and  $\Lambda^{\prime}$. For $t \in [0,1]$, define a homomorphism $G_t:\mathcal{A}_{\theta}^{2} \rightarrow Q\left(\mathcal{K}^{\oplus n}\right)$ by 
$$ G_t(s_1)=s_1, \mbox{ and } G_t(s_2)=f(t)s_2. $$  Consider the map $G:[0,1]\times \mathcal{A}_{\theta}^{2} \rightarrow Q\left(\mathcal{K}^{\oplus n}\right)$ given by $G(t,s_1)=G_t(a)$ for $a \in \mathcal{A}_{\theta}^{2}$.  The map $G$ constitutes a homotopy between $\xi^{\Lambda}_n$ and $\xi^{\Lambda^{\prime}}_n$, thus, 
$[\xi^{\Lambda}_n]=[\xi^{\Lambda^{\prime}}_n]$ in $KK^1\left(\cla_{\theta},\,\mathcal{K}^{\oplus n} \right)$. Hence the claim follows by Propositions (\ref{full}, \ref{KK}).
\qed 

\bdfn \label{Fmn}  Let $\Lambda^1\in \Gamma_m$, and $ \Lambda^2\in \Gamma_n$. Consider the operators $T_{1}$ and $T_{2}$ on $\ell^2(\mathbb{N})^{\oplus (m+n)}$ defined as follows: 
$$T_{1}= \left(S^*\right)^{\oplus m}\oplus \left(\bigoplus_{j=1}^n \left(\lambda_j e^{2\pi\mathrm{i}\theta N}\right)\right),\quad  T_{2}= \bigoplus_{i=1}^m \left(\lambda_i^{'} e^{2\pi\mathrm{i}\theta N}\right)\oplus \left(S^*\right)^{\oplus n}.$$
The $C^*$-algebra $\mathfrak{F}_{m,n,\theta}^{\Lambda^1,\Lambda^2}$ is defined to be the $C^{*}$-subalgebra  of $\cll\left(\ell^2(\mathbb{N})^{\oplus (m+n)}\right)$ generated by $T_{1}$ and $T_{2}$.
\edfn 

\bppsn \label{short exact sequence 2} Then 
there is the following short exact sequence
\[
\chi^{\Lambda^1,\Lambda^{2}}_{m,n}: \quad 0\longrightarrow \mathcal{K}^{\oplus (m+n)} \xrightarrow{i} \mathfrak{F}_{m,n,\theta}^{\Lambda^1,\Lambda^2} \xrightarrow{\zeta} \mathcal{A}_{\theta}^{2}\longrightarrow  0.
\]
where $\zeta$ maps the generators $T_1$ and $T_2$ of $\mathfrak{F}_{m,n,\theta}^{\Lambda^1,\Lambda^2}$ to the  generators $s_1$ and $s_2$, respectively, of $\mathcal{A}_{\theta}^{2}$. Moreover, $\chi^{\Lambda^1,\Lambda^{2}}_{m,n}$ is a full essential extension of $\mathcal{A}_{\theta}^{2}$ by  $\mathcal{K}^{\oplus (m+n)}$.
\eppsn 
\prf 
We have 
$I- T_{1} T_{1}^{*}= p^{\oplus m}\oplus 0^{\oplus n}$ and $I-T_{2} T_{2}^{*}= 0^{\oplus m}\oplus p^{\oplus n}$. Also, 
$$T_2\left(I- T_{1}T_{1}^{*}\right)= \oplus_{i=1}^m \left(\lambda_i^{'} p\right)\oplus 0^{\oplus n} \mbox{ and }  \,T_1\left(I-T_{2}T_{2}^{*}\right)= 0^{\oplus m}\oplus\left(\oplus_{j=1}^n \left(\lambda_j p\right)\right).$$
Using this and proceeding along the lines of the proofs of Proposition \ref{short exact sequence 1} and Lemma \ref{full}, we obtain the claim.
\qed 
