Let $\mathbf{T}=(T_{1},T_{2})$ be a pair of doubly non-commuting isometries on a Hilbert space $\mathcal{H}$ with finite-dimensional wandering spaces. Since $T_{2}$ is an isometry and $\mathcal{W}_{\{1\}}$ is finite dimensional, $T_{2}|_{\mathcal{W}_{\{1\}}}$ is a unitary. Thus $T_{2}^{m_{2}}\mathcal{W}_{\{1\}}=\mathcal{W}_{\{1\}}$. Similarly, we  have $T_{1}^{m_{1}}\mathcal{W}_{\{2\}}=\mathcal{W}_{\{2\}}$. Hence, in the  von Neumann-Wold decomposition of $\mathbf{T}$,  we get  $$\mathcal{H}=\oplus_{A\subseteq\{1,2\}}\mathcal{H}_{A},$$ where
\begin{enumerate}[(i)]
	\item $\mathcal{H}_{\phi}=\cap_{m_{1},m_{2}}T_{1}^{m_{1}}T_{2}^{m_{2}}\mathcal{H}$
	\item $\mathcal{H}_{\{1\}}=\oplus_{m_{1}}T_{1}^{m_{1}}(\cap_{m_{2}}T_{2}^{m_{2}}\textrm{ker}T_{1}^{*})
	=\oplus_{m_{1}}T_{1}^{m_{1}}(\cap_{m_{2}}T_{2}^{m_{2}}\mathcal{W}_{\{1\}})	=\oplus_{m_{1}}T_{1}^{m_{1}}\mathcal{W}_{\{1\}}$
	\item $\mathcal{H}_{\{2\}}=\oplus_{m_{2}}T_{2}^{m_{2}}(\cap_{m_{1}}T_{1}^{m_{1}}\textrm{ker}T_{2}^{*})=\oplus_{m_{2}}T_{2}^{m_{2}}(\cap_{m_{1}}T_{1}^{m_{1}}\mathcal{W}_{\{2\}})
	=\oplus_{m_{2}}T_{2}^{m_{2}}\mathcal{W}_{\{2\}}$
	\item $\mathcal{H}_{\{1,2\}}=\oplus_{m_{1},m_{2}}T_{1}^{m_{1}}T_{2}^{m_{2}}(\textrm{ker}T_{1}^{*}\cap\textrm{ker}T_{2}^{*})=\oplus_{m_{1},m_{2}}T_{1}^{m_{1}}T_{2}^{m_{2}}\mathcal{W}_{\{1,2\}}$
\end{enumerate}
The following theorem gives a classification of the algebra $C^{*}(\mathbf{T})$ for a tuple $\mathbf{T}$ of doubly non commuting isometries.

\begin{thm}\label{Classification}
	Let $\mathbf{T}=(T_{1},T_{2})$ be a pair of  doubly-twisted   isometries with  parameter $\theta\in\mathbb{R}\setminus \bbq$ acting  on a Hilbert space $\clh$. Assume that all the wandering subspaces are finite dimensional. Then we have the following cases.
	\begin{enumerate}[(i)]
		\item If $\mathcal{H}_{\{1,2\}}\neq0$, then $C^{*}(\mathbf{T})\cong C_{\theta}^{0,2}.$
		\item If $\mathcal{H}_{\{1,2\}}=\mathcal{H}_{\{2\}}=0$ and $\mathcal{H}_{\{1\}}\neq 0$ then $C^{*}(\mathbf{T})\cong \mathfrak{D}_{n,\theta}$, where  $n$ is the number of distinct eigenvalues of $\restr{T_2}{\mathcal{W}_{\{1\}}}$.
		\item If $\mathcal{H}_{\{1,2\}}=\mathcal{H}_{\{1\}}=0,\mathcal{H}_{\{2\}}\neq 0$, then $C^{*}(\mathbf{T})\cong \mathfrak{D}_{n,\theta}$, where  $n$ is the number of distinct eigenvalues of $\restr{T_1}{\mathcal{W}_{\{2\}}}.  $
		\item If $\mathcal{H}_{\{1,2\}}=0$ and $\mathcal{H}_{\{1\}},\mathcal{H}_{\{2\}}\neq 0$, then $C^{*}(\mathbf{T})\cong \mathfrak{F}_{m,n,\theta}$, where  $m$ and $n$ are the number of distinct eigenvalues of $\restr{T_2}{\mathcal{W}_{\{1\}}}$ and $\restr{T_1}{\mathcal{W}_{\{2\}}}$, respectively.
		\item Suppose $\mathcal{H}_{\{1,2\}}=\mathcal{H}_{\{1\}}=\mathcal{H}_{\{2\}}=0$ and  $\mathcal{H}_{\phi}\neq 0$. Then $C^{*}(\mathbf{T})\cong \mathcal{A}^2_{\theta}$.
	\end{enumerate}	
\end{thm}
\begin{proof}
We split the proof into different cases.
	\begin{enumerate}[(i)]
		\item Let $\mathcal{H}_{\{1,2\}}\neq0$. Let $\{l_{k}\}_{k=1}^{n}$ be an orthonormal basis for $\mathcal{W}_{\{1,2\}}$. Define the following subspace for $1\leq k\leq n$. $$\mathcal{H}_{\{1,2\}}^{k}=\oplus_{n,m}T_{1}^{n}T_{2}^{m}(l_{k}).$$ Thus $\mathcal{H}_{\{1,2\}}=\oplus_{k}\mathcal{H}_{\{1,2\}}^{k}$. Moreover,  the set $\{T_{1}^{m_{1}}T_{2}^{m_{2}}(l_{k}):m_{1},m_{2}\in\mathbb{N}\}$ is an orthonormal basis for $\mathcal{H}_{\{1,2\}}^{k}$. Consider the following map.
		$$\psi:\mathcal{H}_{\{1,2\}}^{k}\rightarrow \ell^{2}(\mathbb{N})\otimes\ell^{2}(\mathbb{N})\,\,;\,\,T_{1}^{n}T_{2}^{m}(l_{k})\mapsto e_{n}\otimes e_{m}.$$
		Hence  $\mathcal{H}_{\{1,2\}}^{k}\cong \ell^{2}(\mathbb{N})\otimes\ell^{2}(\mathbb{N})$ for every $1\leq k\leq n$. With this identification, we have 
		\begin{eqnarray*}
			T_{1}(e_{n}\otimes e_{m})
			&=&T_{1}(T_{1}^{n}T_{2}^{m}(l_{k}))\\
			&=&T_{1}^{n+1}T_{2}^{m}(l_{k})\\
			&=&(e_{n+1}\otimes e_{m})\\
			&=&(S^{*}\otimes 1)(e_{n}\otimes e_{m})
		\end{eqnarray*}
		Similarly, one has 
		\begin{eqnarray*}
			T_{2}(e_{n}\otimes e_{m})
			&=&T_{2}(T_{1}^{n}T_{2}^{m}(l_{k}))\\
			&=&e^{-2\pi\mathrm{i}\theta n}T_{1}^{n}T_{2}^{m+1}(l_{k})\\
			&=&e^{-2\pi\mathrm{i}\theta n}e_{n}\otimes e_{m+1}\\
			&=&(e^{-2\pi\mathrm{i}\theta N}\otimes S^{*})(e_{n}\otimes e_{m})
		\end{eqnarray*}
	This implies that
		\[
		T_{1}|_{\mathcal{H}_{\{1,2\}}}= \left(S^{*}\otimes 1\right)^{\oplus n},  \quad  \mbox{ and }  \quad 	T_{2}|_{\mathcal{H}_{\{1,2\}}}= 	\oplus_{k=1}^n \left(e^{-2\pi\mathrm{i}\theta N}\otimes S^{*}\right)^{\oplus n}.\]
Hence we get
		$$
		T_{1}=	(S^{*} \otimes 1)	 \oplus T_{1}^{\{1\}}  \oplus T_{1}^{\{2\}} \oplus T_{1}^{\phi}  \mbox{ and } 
	T_{2}=	(e^{-2\pi\mathrm{i}\theta N}\otimes S^{*}) \oplus T_{2}^{\{1\}}  \oplus T_{2}^{\{2\}} \oplus T_{2}^{\mathcal{H}_{\phi}}
		$$
		For $A \subset \{1,2\}$, define $C^A=C^*(\{T_1^A,T_2^A\})$.  By the defining relations of $C^{0,2}_{\theta}$, one has a homomorphism $\phi_A: C^{0,2}_{\theta} \rightarrow C^A$ mapping $s_1 \mapsto  T_1^A, \,\,  s_2 \mapsto T_2^A$. Moreover, for $A=\{1,2\}$, the map $\phi_A$ is an isomorphism. 
		By Proposition \ref{isomdirectsum}, the homomorphism 
		\begin{eqnarray*} 
			\psi &:C^{0,2}_{\theta} &\longrightarrow C^{*}(\mathbf{T})\\
			& & s_1 \mapsto T_{1}= (S^{*} \otimes 1)	 \oplus T_{1}^{\{1\}}  \oplus T_{1}^{\{2\}} \oplus T_{1}^{\phi}\\
			& & s_2 \mapsto T_{2}=(e^{-2\pi\mathrm{i}\theta N}\otimes S^{*}) \oplus T_{2}^{\{1\}}  \oplus T_{2}^{\{2\}} \oplus T_{2}^{\mathcal{H}_{\phi}}
		\end{eqnarray*} 
		is an isomorphism. 

		\item Let $\alpha_1, \cdots \alpha_n$ be eigenvalues of  $\restr{T_2}{\mathcal{W}_{\{1\}}}$, and $\{l_{r_j}\}_{j=1}^{n_r}$ be an orthonormal basis for eigenspace corresponding to $\alpha_r$. Define
		 $$\mathcal{H}_{\{1\}}^{r,j}=\oplus_{m\in\mathbb{N}}T_{1}^{m}(l_{r_j}) \quad  \mbox{ and }\quad  \mathcal{H}_{\{1\}}^{r}=\oplus_{j=1}^{n_r}\mathcal{H}_{\{1\}}^{r,j}.$$ 
		 Then we have  $\mathcal{H}_{\{1\}}=\oplus_{r=1}^n\mathcal{H}_{\{1\}}^{r}.$  Identifying $T_{1}^{m}(l_{r_j})$ with $e_m$, one can view $\mathcal{H}_{\{1\}}^{r,j}$ as $\ell^2(\bbn)$, and thus 
		$$T_{1}|_{\mathcal{H}_{\{1\}}^{r,j}}=S^{*} \mbox{ and } T_{2}|_{\mathcal{H}_{\{1\}}^{r,j}}=\alpha_r e^{-2\pi\mathrm{i}\theta N}.$$ 
		This implies that 
		\[
		T_{1}|_{\mathcal{H}_{\{1\}}}= \oplus_{r=1}^n\, \oplus_{j=1}^{n_r} S^* \quad \mbox{ and } \quad 	T_{2}|_{\mathcal{H}_{\{1\}}}= \oplus_{r=1}^n\, \oplus_{j=1}^{n_r} \alpha_r e^{-2\pi\mathrm{i}\theta N}.
		\]
		Hence we have 
		\[
		T_1=	T_{1}|_{\mathcal{H}_{\{1\}}}\oplus T_1^{\phi}=\big( \oplus_{r=1}^n\, \oplus_{j=1}^{n_r} S^* \big) \oplus T_1^{\phi} \mbox{ and } T_2=	T_{2}|_{\mathcal{H}_{\{1\}}}\oplus T_2^{\phi}= \big(\oplus_{r=1}^n\, \oplus_{j=1}^{n_r} \alpha_r e^{-2\pi\mathrm{i}\theta N}\big) \oplus T_2^{\phi}.
		\]
		By Proposition (\ref{isomdirectsum1}, \ref{isomdirectsum2}), the $C^*$-algebra  $C^*(\mathbf{T})$ is isomorphic to the $C^*(\{R_1,R_2\})$, where 
		$$R_1=\oplus_{r=1}^n\ S^*  \mbox{ and } R_2= \oplus_{r=1}^n\, \alpha_r e^{-2\pi\mathrm{i}\theta N}.$$ 
		This proves the claim. 
		\item The proof of this case is exactly along the lines of part $(ii)$.
			\item Let $\alpha_1, \cdots \alpha_m$ be eigenvalues of  $\restr{T_2}{\mathcal{W}_{\{1\}}}$, and $\{l_{r_j}\}_{j=1}^{m_r}$ be an orthonormal basis for eigenspace corresponding to $\alpha_r$. Let $\beta_1, \cdots \beta_n$ be eigenvalues of  $\restr{T_1}{\mathcal{W}_{\{2\}}}$, and $\{k_{r_j}\}_{j=1}^{n_r}$ be an orthonormal basis for eigenspace corresponding to $\beta_r$. Define
		$$\mathcal{H}_{\{1\}}^{r,j}=\oplus_{m\in\mathbb{N}}T_{1}^{m}(l_{r_j}) \quad  \mbox{ and }\quad  \mathcal{H}_{\{1\}}^{r}=\oplus_{j=1}^{n_r}\mathcal{H}_{\{1\}}^{r,j}.$$ 
		Then we have  $\mathcal{H}_{\{1\}}=\oplus_{r=1}^n\mathcal{H}_{\{1\}}^{r}.$  Identifying $T_{1}^{m}(l_{r_j})$ with $e_m$, one can view $\mathcal{H}_{\{1\}}^{r,j}$ as $\ell^2(\bbn)$, and thus 
		$$T_{1}|_{(\mathcal{H}_{\{1\}}^{r,j})}=S^{*} \mbox{ and } T_{2}|_{(\mathcal{H}_{\{1\}}^{r,j})}=\alpha_r e^{-2\pi\mathrm{i}\theta N}.$$ 
		This implies that 
		\[
		T_{1}|_{\mathcal{H}_{\{1\}}}= \oplus_{r=1}^n\, \oplus_{j=1}^{n_r} S^* \quad \mbox{ and } \quad 	T_{2}|_{\mathcal{H}_{\{1\}}}= \oplus_{r=1}^n\, \oplus_{j=1}^{n_r} \alpha_r e^{-2\pi\mathrm{i}\theta N}.
		\]
		Hence we have 
		\[
		T_1=	T_{1}|_{\mathcal{H}_{\{1\}}}\oplus T_1^{\phi}=\big( \oplus_{r=1}^n\, \oplus_{j=1}^{n_r} S^* \big) \oplus T_1^{\phi} \mbox{ and } T_2=	T_{2}|_{\mathcal{H}_{\{1\}}}\oplus T_2^{\phi}= \big(\oplus_{r=1}^n\, \oplus_{j=1}^{n_r} \alpha_r e^{-2\pi\mathrm{i}\theta N}\big) \oplus T_2^{\phi}.
		\]
		By Proposition (\ref{isomdirectsum1}, \ref{isomdirectsum2}), the $C^*$-algebra  $C^*(\mathbf{T})$ is isomorphic to the $C^*(\{R_1,R_2\})$, where 
		$$R_1=\oplus_{r=1}^n\ S^*  \mbox{ and } R_2= \oplus_{r=1}^n\, \alpha_r e^{-2\pi\mathrm{i}\theta N}.$$ 
		This proves the claim. 
		\item This follows from the fact that $T_1$ and $T_2$ satisfy the defining relations of $\mathcal{A}^2_{\theta}$, and that $\mathcal{A}^2_{\theta}$ is simple.
	\end{enumerate}	
\end{proof}   
The following theorem says that $K$-theory is a complete invariant for 	a $C^*$-algebra generated by  a pair of  doubly-twisted   isometries  with finite wandering spaces.
\bthm Let $\mathbf{T}=(T_{1},T_{2})$ and   $\mathbf{T}^{\prime}=(T_{1}^{\prime},T_{2}^{\prime})$ be two pairs of  doubly-twisted   isometries with  parameter $\theta\in\mathbb{R}\setminus \bbq$ acting  on a Hilbert space $\clh$. Assuming both $\mathbf{T}$ and $\mathbf{T}^{\prime}$ have finite-dimensional wandering spaces. Then 
$$C^*(\mathbf{T})\cong C^*(\mathbf{T}^{\prime}) \mbox{ if and only if } K_*(C^*(\mathbf{T}))\cong K_*(C^*(\mathbf{T}^{\prime})).$$
\ethm 
\prf This is a straightforward consequence of Theorem \ref{Classification}, Propositions (\ref{General 1}, \ref{General 2}), and Theorem $6.8$ in \cite{Web-2013aa}.
\qed 
\bdfn Let \( \Delta_{\theta} \) be the set of \( C^* \)-algebras generated by doubly twisted isometries \( (T_1, T_2) \leadsto C^{0,2}_{\theta} \), with finite-dimensional wandering spaces, considered up to isomorphism.  
We call a \( C^* \)-algebra \( C \) of \textbf{type I}, \textbf{type II}, \textbf{type III}, or \textbf{type IV} if it is isomorphic to \( C^{0,2}_{\theta} \), \( \mathfrak{D}_{n,\theta} \), \( \mathfrak{F}_{m,n,\theta} \), or \( \mathcal{A}_{\theta}^2 \), respectively.
\edfn 
Let $\mathbf{T}=(T_{1},T_{2})$ be a pair of doubly twisted isometries with respect to a unitary operator $U$ on a Hilbert space $\mathcal{H}$. In the Wold decomposition of $\mathbf{T}$, assume that for every  $A\subseteq\{1,2\}$, the wandering subspace $\mathcal{W}_{A}$ is finite dimensional. 

\begin{lmma}
Under the above set-up,	the spectrum $\sigma(U)$ is a finite set.	
\end{lmma}

\begin{proof}
	For every $A\subseteq\{1,2\}$, $U|_{\mathcal{W}_{A}}$ is diagonalisable and the spectrum $\sigma(U|_{\mathcal{W}_{A}})$ is finite. 
	By definition of $\mathcal{H}_{A}$, and the map $$ \phi:\mathcal{H}_{A}\longrightarrow \ell^{2}(\mathbb{N})^{\otimes\,|A^{c}|}\otimes\mathcal{W}_{\{1,2\}}\,;\,\overrightarrow{\prod_{i\in A^{c}}}T_{i}^{m_{i}}w \longrightarrow \overrightarrow{\otimes_{i\in A^{c}}}e_{m_{i}}\otimes w.$$ 
	Since $U$ commutes with $T_{1}$ and $T_{2}$,  one has $$U|_{\mathcal{H}_{A}}=U(\overrightarrow{\oplus_{i\in A^{c}}}T_{i}^{m_{i}}\mathcal{W}_{A})=\overrightarrow{\oplus_{i\in A^{c}}}T_{i}^{m_{i}}U(\mathcal{W}_{A}).$$ Therefore we have
	$$U|_{\mathcal{H}_{A}}\cong 1^{\otimes\,|A^{c}|} \otimes U|_{\mathcal{W}_{A}}.$$ This implies that  $\sigma(U|_{\mathcal{H}_{A}})=\sigma(U|_{\mathcal{W}_{A}})$. Therefore $$\sigma(U)=\sigma(\oplus_{A\subseteq\{1,2\}}U^A)=\cup_{A\subseteq\{1,2\}}\sigma(U|_{\mathcal{H}_{A}})=\cup_{A\subseteq\{1,2\}}\sigma(U|_{\mathcal{W}_{A}}).$$ 
	This proves the claim.
\end{proof}



\begin{thm} \label{U-twisted}
	Let $U$ be a unitary operator acting on a Hilbert space $\mathcal{H}$ having finite spectrum $\{e^{2\pi\mathrm{i}\theta_{1}}, \cdots, e^{2\pi\mathrm{i}\theta_{k}}\}$, where $\theta_i \in \bbr \setminus\bbq$ for $1\leq i \leq k$.	Let $\mathbf{T}=(T_{1},T_{2})$ be a pair  of isometries  on  $\mathcal{H}$ such that $\mathbf{T} \leadsto C^{0,2}_U$. Assume that all the wandering subspaces in the Wold decomposition of $\mathbf{T}$ are finite dimensional. Then  $$C^{*}(\mathbf{T}) \cong \oplus_{i=1}^{k}C_{\theta_i},$$ 
	where   $C_{\theta_i} \in \Delta_{\theta_i}$ for all $1 \leq i \leq k$.
\end{thm}	  

\prf 
For each $1\leq i\leq k$, the functions $\chi_{e^{2\pi\mathrm{i}\theta_{i}}}\in C(\sigma(U))$ maps to  orthogonal projections $P_{i}\in C^{*}(\{U\})$ under continuous functional calculus  such that 
$$\sum_{i=1}^{k}P_{i}=1 \mbox{ and } \sum_{i=1}^k\, e^{2\pi\mathrm{i}\theta_{i}}P_i=U.$$  
Moreover, since $U \in \mathcal{Z}(C^*(\mathbf{T}))$, it follows that $P_i \in \mathcal{Z}(C^*(\mathbf{T}))$, and  we have  
 $$a=\sum_{i=1}^{k}P_{i}aP_{i}, \quad  \mbox{ and }  \quad (P_iaP_i)(P_jaP_j)=0 \mbox{ if } i \neq j, $$ 
for all  $a \in  C^*(\mathbf{T})$.
Hence
$$C^*(\mathbf{T})=
C^{*}(\{T_{1},T_{2}\})=C^{*}\Big(\big\{\sum_{i=1}^{k}P_iT_1P_i,\sum_{i=1}^{k}P_iT_2P_i\big\}\Big)=
\oplus_{i=1}^{k}C^{*}(P_{i}T_{1}P_i,P_{i}T_{2}P_i).$$
Note that $$(P_iT_1P_i)^*(P_iT_2P_i)=P_iT_1^*T_2P_i=P_iU^*T_2T_1^*P_i %=(P_kU^*P_k)(P_kT_2P_k)(P_kT_1^*P_k)
=e^{2\pi\mathrm{i}\theta_{i}}(P_iT_2P_i)(P_iT_1^*P_i).$$
Define $\mathbf{T}^i=(P_{j}T_{1}P_i,P_{j}T_{2}P_i)$ for $1\leq i \leq k$. Then $\mathbf{T}^i \leadsto C^{0,2}_{\theta_i}$.  Moreover, all the wandering subspaces of each $\mathbf{T}^i$ are finite-dimensional, since the same holds for $\mathbf{T}$.
Define $C_{\theta_i}=C^{*}(P_{j}T_{1}P_i,P_{j}T_{2}P_i)$ for $1\leq i \leq k$. Then $C_{\theta_i} \in  \Delta_{\theta_i}$ and 
 $C^{*}(\mathbf{T}) \cong \oplus_{i=1}^{k}C_{\theta_i},$  proving  the claim.  
\qed 
\brmrk We call $C_{\theta}$'s the $\theta$-component  of $C^*(\mathbf{T})$ with respect to $U$.  Observe  that $\theta$-component  and  $(\theta+n)$-component are the same for any $n \in \bbz$. 
\ermrk
\bppsn \label{maximal ideal}
Let \( J_{n}^{\mu} = \langle 1 - T_1T_1^* \rangle \). 
Then \( J_{n}^{\mu}= \mathcal{K}^{\oplus n} \). 
If \( \mu \) is irrational, then \( J_{n}^{\mu}\) is the unique maximal ideal of \( \mathfrak{D}_{n,\mu} \).
\eppsn


\prf That  \( J_{n}^{\mu}= \mathcal{K}^{\oplus n}\) follows from the calculations done in the proof of Proposition \ref{short exact sequence 1}. To prove the rest, consider the surjective $*$-homomorphism $\varPsi: C^{0,2}_{\theta} \rightarrow  \mathfrak{D}_{n,\mu}$ sending $s_1 \mapsto T_1$ and $s_2 \mapsto T_2$.  Let $J=\langle 1-s_1s_1^*, 1-s_2s_2^*\rangle$. Then, by Proposition $3.2$ in \cite{Web-2013aa}, it follows that $J$ is the unique maximal ideal of  $C^{0,2}_{\theta}$, and hence $\ker \varPsi\subset J$.  Since $\varPsi(J)=J_{n}^{\mu}$, the claim follows.  
\qed 
\bppsn \label{maximal ideal1}
Let \( J_{m,n}^{\mu} = \langle 1 - T_1T_1^*,\ 1 - T_2T_2^* \rangle \). 
Then \( J_{m,n}^{\mu} = \mathcal{K}^{\oplus (m+n)} \). 
If \( \theta \) is irrational, then \( J_{m,n}^{\mu} \) is the unique maximal ideal of \( \mathfrak{F}_{m,n,\mu} \).
\eppsn
\prf The proof is similar to that of Proposition \ref{maximal ideal}, and is therefore omitted.
\qed

\bppsn \label{plusminus}
 Let $\mu, \nu \in \bbr \setminus \bbq$. Then one has the following.
\begin{enumerate}[(i)]
	\item $\mathfrak{D}_{n,\mu}\cong \mathfrak{D}_{n,\nu} \iff  \mu =\pm \nu \mbox{ mod } \bbz. $
	\item $\mathfrak{F}_{m,n,\mu}\cong\mathfrak{F}_{m,n,\nu} \iff  \mu =\pm \nu \mbox{ mod } \bbz. $
\end{enumerate}
\eppsn 
\prf
To prove the forward implication of part (i), let  
\[
\varpi: \mathfrak{D}_{n,\mu} \rightarrow \mathfrak{D}_{n,\nu}
\]  
be an isomorphism. Then, by Proposition \ref{maximal ideal}, we have \( \varpi(J_{n}^{\mu}) = J_{n}^{\nu} \). This induces an isomorphism between  
\[
\mathfrak{D}_{n,\mu} / J_{n}^{\mu} \cong \mathcal{A}_{\mu}^2 \quad \text{and} \quad \mathfrak{D}_{n,\nu} / J_{n}^{\nu} \cong \mathcal{A}_{\nu}^2,
\]  
and hence we conclude that \( \mu = \pm \nu \mod \mathbb{Z} \).
For the converse, note that  
\[
\mathfrak{D}_{n,\mu} = C^*(\{T_1, T_2\}) = C^*(\{T_1, T_2^*\}) = \mathfrak{D}_{n,-\mu}.
\]

For part (ii), we will prove the necessary condition, as the sufficient one follows as in the previous case.  
For that, let \( \mathbf{T}^{+} = (T_1^+, T_2^+) \) and \( \mathbf{T}^{-} = (T_1^-, T_2^-) \) denote the corresponding generators as given in Definition \ref{Fmn}. It is straightforward to verify that all wandering data of \( \mathbf{T}^{+} \) and \( \mathbf{T}^{-} \) are the same. Hence, by Theorem 5.2 in \cite{RakSarSur-2022aa}, the tuples \( \mathbf{T}^{+} = (T_1^+, T_2^+) \) and \( \mathbf{T}^{-} = (T_1^-, T_2^-) \) are unitarily equivalent, and thus  
\[
\mathfrak{F}_{m,n,\mu} = C^*(\mathbf{T}^{+}) \cong C^*(\mathbf{T}^{-}) \cong \mathfrak{F}_{m,n,-\mu}.
\]
\qed
 \brmrk \label{plusminus1}
By Proposition 3.6 in \cite{Web-2013aa}, the above result holds for \( C^{0,2}_{\theta} \). The same result holds for \( \mathcal{A}_{\theta}^2 \).  
\ermrk

\blmma \label{plusminus2}
  Let $\mu, \nu \in \bbr \setminus \bbq$. Let $B_{\mu}$ and $C_{\nu}$ be two $C^*$-algebras such that  $B_{\mu} \in  \Delta_{\mu}$ and $C_{\nu} \in  \Delta_{\nu}$. If 
$ B_{\mu} \cong C_{\nu} $, then $ \mu =\pm \nu \mbox{ mod } \bbz. $ 
\elmma 
\prf By comparing the \( K \)-groups, one concludes that both \( B_{\mu} \) and \( C_{\nu} \) are of the same type. The claim then follows directly from Proposition \ref{plusminus} and Remark \ref{plusminus1}.  
\qed

		\bthm \label{U-twisted 1}
	Let $U$ be a unitary operator acting on a Hilbert space $\mathcal{H}$ with finite spectrum $\{e^{2\pi\mathrm{i}\theta_{1}}, \ldots, e^{2\pi\mathrm{i}\theta_{k}}\}$, where $\theta_i \in \bbr \setminus \bbq$ for $1 \leq i \leq k$. Let $\mathbf{T} = (T_{1}, T_{2})$ and $\mathbf{T}^{\prime} = (T_{1}^{\prime}, T_{2}^{\prime})$ be two pairs of isometries on $\mathcal{H}$ such that
$	\mathbf{T}, \mathbf{T}^{\prime} \leadsto ^*C^{0,2}_U $. 
	Assume that for \( 1 \leq i \leq k \), the algebras \( C_{\theta_i} \) and \( C'_{\theta_i} \) are the \( \theta_i \)-components of \( C^*(T) \) and \( C^*(T') \), respectively, with respect to \( U \). Then the following holds:
	\begin{enumerate}[(i)]
		\item If \( e^{2\pi i \theta_i} \in \sigma(U) \) but \( e^{-2\pi i \theta_i} \notin \sigma(U) \), then \( C_{\theta_i} \cong C'_{\theta_i} \).
		\item If both \( e^{2\pi i \theta_i}, e^{-2\pi i \theta_i} \in \sigma(U) \), then either \( C_{\theta_i} \cong C'_{\theta_i} \) or \( C_{\theta_i} \cong C'_{-\theta_i} \).
	\end{enumerate}
	\ethm 
\prf It suffices to prove the forward implication, thanks to Theorem \ref{U-twisted}. Let 
$$ \phi: C^*(\mathbf{T}) \rightarrow   C^*(\mathbf{T}^{\prime}) $$
be an isomorphism. Let $\phi(U) = U^{0}$. Then we have 
$$\sigma(U)=\sigma(U^0) \mbox{  and } UU^{0}=U^{0}U \mbox{  as } U, U^{0}\in \mathcal{Z}(C^*(\mathbf{T}^{\prime})).$$ 
Observe that  $\mathbf{T}^{\prime}$ is a $U^{0}$-doubly twisted tuple of isometries with finite dimensional wandering spaces. Let $C^0_{\theta_i}$ be the $\theta_i$-component of $C^*(\mathbf{T}^{\prime})$ with respect to $U^0$.  Let $P_i$ and $P_i^0$ be the orthogonal projection onto the eigenspace of $U$ and $U^0$, respectively, corresponding to eigenvalue $e^{2\pi i \theta_i}$. Then $\phi(P_i) = P_i^0$ for all $1 \leq i \leq k$. Hence we have 
$$ C^0_{\theta_i}= P_i^0C^*(\mathbf{T}^{\prime})P_i^0
=\phi(P_i)\phi\left( C^*(\mathbf{T})\right)\phi(P_i)= \phi\left(P_iC^*(\mathbf{T})P_i\right) = \phi(C_{\theta_i}).$$
Further, for each $1\leq i \leq k$, there exists a unique  $1 \leq j \leq k$ such that $P_i^0=P_j$, as $U$ and $U^0$ commute, therefore, we get
$$C^0_{\theta_i}= P_i^0C^*(\mathbf{T}^{\prime})P_i^0= P_jC^*(\mathbf{T}^{\prime})P_j= C^{\prime}_{\theta_j}.$$
This proves that $\phi(C_{\theta_i}) = C^{\prime}_{\theta_j}$, and hence $C_{\theta_i} \cong C_{\theta_j}^{\prime}$. By Lemma \ref{plusminus2}, we get $\theta_j=\pm \theta_i$, proving the claim. 
\qed 
\brmrk
For a unitary operator \( U \) with finite spectrum, Theorems \ref{U-twisted} and \ref{U-twisted 1}, along with Lemma \ref{plusminus} and Remark \ref{plusminus1}, provide a complete classification of the \( C^* \)-algebras generated by a pair of \( U \)-doubly twisted isometries with finite-dimensional wandering spaces.
\ermrk
