\vskip .1cm

%-------------------

\begin{proposition}\label{Prop:2.6} Let $\omega\colon [0,1]\to\mathbb{R}_{+}$ be a real function such that $\omega(0)=0$, $\omega'(t)\geq 0$ and $\omega''(t)\leq 0$ for $t\in [0,1]$. Then $\omega_\omega= \omega$. 
\end{proposition}

\begin{proof} By assumption $\omega$ is nondecreasing and subadditive. By \cite[Lemma 5]{Breneis} the result follows. %Let $r< s$ be arbitrary points in $[0,1]$ and set $s-r=\delta$. Then
%\[
%|\omega(r)- \omega(s)|=\omega(s)- \omega(r)=\int_0^{\delta} \omega'(r+t)dt\leq \int_0^\delta \omega'(t)dt= \omega(\delta). 
%\]
\end{proof}

