The following lemma complements a result of Breneis \cite[Theorem 7]{Breneis} proved only for moduli with derivative at $0$ infinite, i.e. $\omega'(0)=\infty$. 

%--------------------------

\begin{lemma}\label{lem:3.3} Assume that $\omega\colon \mathbb{R}_+\to \mathbb{R}_+$ is a modulus of continuity which is nondecreasing on $[0,b]$ for some $b>1$ and satisfies
\[
M=\lim_{\delta\to 0}\frac{\omega(\delta)}{\delta}\in (0,+\infty).
\]
Then there exists a non-negative function $f\colon [0,1]\to [0, M]$ such that $f(0)=0$ and $\omega_f\leq \omega$. 
\end{lemma}
\begin{proof} The construction of the function $f$ follows as an adaptation of the arguments in \cite{Breneis}. Fix $\varepsilon\in (0,M)$ and pick a $\delta_0>0$ so that 
\begin{equation}\label{eqn:1lem}
(M-\varepsilon)\delta\leq \omega(\delta)\leq (M+\varepsilon)\delta\quad\forall \delta\in [0,\delta_0]. 
\end{equation}
Fix any increasing modulus of continuity $\tilde{\omega}$ on $\mathbb{R}_+$ which is $M-\varepsilon$-Lipschitz on $[0,1]$ and satisfies $\tilde{\omega}(h)=\tilde{\omega}(1)$ for $h\geq 1$ and $\omega_{\tilde{\omega}}=\tilde{\omega}$. Following \cite[]{Breneis} we will construct $f$ by induction on the intervals $[x_1, x_0]$, $[x_2, x_1],\dots$, where $x_0=1$ and $(x_n)$ is a strictly decreasing sequence in $[0,1]$ with $x_n\to 0$. 

Assume we have already constructed $f$ on the interval $[x_n, 1]$. If $x_n=0$, we have already defined $f$ on the entire interval $[0,1]$. Otherwise, we define $x_{n+1}$ and construct $f$ on the interval $[x_{n+1}, x_n]$. First, to every $x\in [0,x_n]$, we assign a point $y_x\in [x, x_n]$ with the property that
\[
\tilde{\omega}(y_x)= \frac{\tilde{\omega}(x) + \tilde{\omega}(x_n)}{2}. 
\]
Such a point $y_x$ exists, since $\tilde{\omega}$ is increasing and continuous. Define the set
\[
A_{n+1}=\Big\{ x\in [0,x_n]\colon \tilde{\omega}(x + h) -\tilde{\omega}(x)\leq \omega(h)\text{ for all } h\in [0,y_x - x]\Big\}.
\]
Clearly, $A_{n+1}$ is compact. Also, $x_n \in A_{n+1}$ since $y_{x_n}=x_n$. Let $x_{n+1}:=\inf A_{n+1}\in A_{n+1}$ and define $y_{n+1}:=y_{x_{n+1}}$. Furthermore,  for $z\in [x_{n+1}, x_n]$ set 
\[
f(z)=\left\{ 
\begin{aligned}
&\tilde{\omega}(z) - \tilde{\omega}(x_{n+1}) & \text{if } &\,z\in [x_{n+1}, y_{n+1}],\\
&\tilde{\omega}(x_n) - \tilde{\omega}(z)\,   & \text{if } &\,z\in [y_{n+1}, x_n]. 
\end{aligned}
\right.
\]
It follows that on the interval $[x_n, y_n]$, $f(z)= \tilde{\omega}(z)-\tilde{\omega}(x_n)$, and on the interval $[y_n, x_{n-1}]$, $f(z)= - \tilde{\omega}(z) +\tilde{\omega}(x_{n-1})$. In particular, we have $f(z)\leq M$ for all $z\in [0,1]$. In addition, the following properties were displayed in \cite[p.8]{Breneis}:
\begin{itemize}\setlength\itemsep{1mm} 
\item $f(x_n)=0$\;and\, $f(y_n)=2^{-1}\big( \tilde{\omega}(x_{n-1}) - \tilde{\omega}(x_n)\big)$.
\item $f$ is increasing (respectively, concave) on the intervals $[x_n, y_n]$ and decreasing (respectively, convex) on the intervals $[y_{n+1}, x_n]$. 
\end{itemize}

By construction the sequence $(x_n)$ is decreasing and bounded. The key, but different point here, is the proof that  $x=\lim_n x_n=0$. The proof of this fact is given below. 
\vskip .2cm 
\noindent{\bf Claim.} $x=0$. \\

Assume on the contrary that $x\neq 0$. Let $A_{n+1}$ be the sets defined on the bottom of the page $7$ in \cite{Breneis}. We know from (\ref{eqn:1lem}) that $\omega(h)\geq (M-\varepsilon)h$ for all $h\in [0,\delta_0]$. Pick a $n\in\mathbb{N}$ sufficiently large so that $0\leq x - x_n\leq \delta_0/2$. Define $z_{n+1}=\max\{ x/2, x_n -\delta_0\}$. Then 
\[
\tilde{\omega}(z_{n+1} +h) - \tilde{\omega}(z_{n+1})\leq (M-\varepsilon)h\leq \omega(h)\quad \forall h\in [0,\delta_0]. 
\]
Hence, $z_{n+1}\in A_{n+1}$ and $x_{n+1}=\min A_{n+1}\leq z_{n+1}< x$, a contradiction. 
\vskip .2cm 
\noindent Therefore $x=0$ and, in particular, $(x_n)$ is strictly decreasing. Notice that this also shows that $f$ is defined on the interval $(0,1]$. The proofs that $f(0+)=0$ and $\omega_f\leq \omega$ are exactly the same as that given in \cite[p.8-9]{Breneis}.  
\end{proof}

\vskip .1cm 

We close this section with an easy proposition whose proof is based on a classical argument of Goebel \cite[p.147]{Go2002}. 

%----------------

\vskip .1cm 

%-----------------

\begin{proposition}\label{prop:2.7} Let $K$ be a nonempty convex subset of a Banach space $X$. If $S\colon K\to K$ is $L_0$-$\omega$-lipschitzian then for every $\varepsilon\in (0,1)$ there exists a $1+\varepsilon$-$\omega$-Lipschitz mapping $T\colon K\to K$ such that $\digamma(S)=\digamma(T)$ and $\mathrm{d}(T,K)=\lambda \mathrm{d}(S,K)$ for some $\lambda>0$. 
\end{proposition}

\begin{proof} It suffices to define 
\[
T(x) = \delta Sx + (1-\delta )x,
\]
where $0<\delta <1\wedge \dfrac{\varepsilon}{L_0-1}$.
\end{proof}

