\section{Examples} As we already mentioned in the Introduction, our results concern the AFPP and FPP for the class of $L$-$\omega$-nonexpansive maps. Before delving into the details of the results, it is convenient to highlight some non-trivial examples of such mappings. Henceforth we will denote by $\digamma(T)$ the fixed point set of a mapping $T$. 

%---------------

\vskip .1cm 

%--------------------

\begin{ex}\label{ex:4.1} Define the function $f\colon [0,1]\to [0,1]$ by $f(r)= r|\log(r^{\sigma})|$ where $\sigma\in (0,1]$. Then $\omega_f(\delta)\leq \omega(\delta):=\delta(L +|\log \delta|)$ for some $L\in (0,1)$. Indeed, for $r<s$ in $[0,1]$ we have
\[
\begin{split}
|f(r) - f(s)|&%=\Big|\int_0^1 \frac{d}{dt}f( r + t(s- r))dt\Big|
=|r-s|\Big|\int_0^1 f'(r+ t(s-r))dt\Big|\\
&=|r- s|\Big|\int_0^1\big( - \frac{\sigma}{\ln 10} - \log( r + t(s-r))^{\sigma}\big)dt\Big| \\[1mm]
&\leq |r-s|\Big( \frac{\sigma}{\ln 10} - \int_0^1 \log\big(t(s-r)\big)dt\Big)\\[1mm]
&\leq |r-s|\Big( \frac{2\sigma}{\ln 10} + \big|\log|r-s|^{\sigma}\big|\Big)\leq |r-s|\Big( \frac{2\sigma}{\ln 10} + \big|\log|r-s|\big|\Big).
\end{split}
\]
\end{ex}

%---------------------

\vskip .1cm 

%-------------------

\begin{ex}\label{ex:4.2} The function $f(r)=(1-r)\cos(r|\log r|)$ is $2$-log-Lipschitz on $[0,1]$. Indeed, for $r< s$ in $[0,1]$ we have
\[
\begin{split}
|f(r) - f(s)|&\leq  |r - s| + \big|\cos(r|\log r|) - \cos(s|\log s|)\big|\\[1mm]
&\leq |r-s| + \big| r|\log r| - s|\log s|\big|\\[1mm]
 &\leq |r-s|\Big( 1 + \frac{2}{\ln 10} + \big|\log|r-s|\big|\Big).\hskip 1cm (\textrm{by Example \ref{ex:4.1}})
\end{split}
\]
\end{ex}

%-----------------------------------------------------

\vskip .1cm 

%-----------------------------------------------

\begin{ex}\label{ex:4.3} Let $d\geq 3$ and consider the Newtonian potential 
\[
\Phi(x)= \frac{|x|^{2-d}}{d(d-2)\omega_d },
\]
where $x\in\mathbb{R}^d$ and $\omega_d$ is the volume of the unit ball in $\mathbb{R}^d$. Here $|\cdot|$ denotes the Euclidean norm. It is known that $\Phi$ satisfies Laplace's equation $\Delta \Phi=0$ on $\mathbb{R}^d\setminus\{0\}$. In addition, one has $-\Delta_x \Phi =\delta_0$ in the sense of distributions, where $\delta_0$ is the Dirac function. Assume now that $f\in L^1\cap L^\infty(\mathbb{R}^d)$ and consider the vector field ${\bf v}\colon \mathbb{R}^d \to\mathbb{R}^d$ given by
\[
{\bf v}_i(x)=\int_{\mathbb{R}^d} \partial_{x_i}\Phi(x- y){f}(y)dy,\quad i=1,\dots, d.
\] 
Taking advantage of some estimates of the Newtonian potential (cf. \cite[Lemma 2.2]{CGK}), ${\bf v}$ is bounded and $L$-log-Lipschitz on $x$ with constant $L$ depending only on $\|f\|_{L^1}$ and $\|f\|_{L^\infty}$. 
\end{ex}

%----------------------

\vskip .1cm 

%-------------------------------

\begin{ex}\label{ex:4.4} Let 
\[
K=\Bigg\{ x=\sum_{n=1}^\infty t_n e_n\in \ell_1\colon t_n \geq 0,\, \sum_{n=1}^\infty t_n\leq 1 \Bigg\},
\] 
where $(e_n)_{n=1}^\infty$ denotes the unit basis of $\ell_1$. Using that $r\mapsto r(2/\ln(10) + |\log r|)$ is increasing on $[0,1]$, it is easy to check that the mapping $T\colon K\to K$ given by 
\[
T(x)=\sum_{n=1}^\infty \frac{1}{2^n}t_n|\log t_n|e_n 
\]
is $L$-log-nonexpansive for some $L\in (0,1)$. Clearly, $0\in \digamma(T)$. 
\end{ex}

%-------------------


%--------------------

\begin{ex}\label{ex:4.5} Let $K=\big\{ x=\sum_{n=1}^\infty t_n e_n\colon t_n \geq 0,\, \sum_{n=1}^\infty t_n \leq \epsilon\big\}\subset \ell_1$, where $\epsilon\in (.1, .2)$ is such that $r\mapsto r|\log r|$ is nondecreasing on $[0,2\epsilon]$ and $\epsilon|\log\epsilon|<\epsilon$. Then for every $L\in (0,1]$, $K$ fails the FPP for $L$-log-nonexpansive maps. To check this fix $0<\theta < \min(1/2, L\ln 10)$ and $0<\eta<\min(\epsilon(1-\theta), L- \theta/\ln 10)$. Now define $T\colon K\to K$ by
\[
T(x)= \eta\Big(1 - \sum_{n=1}^\infty t_n\Big)e_1 + \theta\sum_{n=1}^\infty t_n |\log\sqrt{t_n}| e_{n+1}. 
\]
We are going to show that $T$ is well-defined and leaves $K$ invariant. First, note that if $(a_i)_{i=1}^N$ and $(b_i)_{i=1}^N$ are nonnegative numbers with $\sum_{i=1}^N a_i >0$ then by Jensen's inequality (cf. \cite[p. 202]{HStro}) we have
\begin{equation}\label{eqn:2.3}
\sum_{i=1}^N a_i b_i\cdot\log(b_i)\geq \Big(\sum_{i=1}^N a_i b_i \Big)\cdot \log\Bigg( \frac{\sum_{i=1}^N a_i b_i}{\sum_{i=1}^N a_i}\Bigg).
\end{equation}
Now, take any $x=\sum_{n=1}^\infty t_n e_n\in K$. Then $1-\sum_{n=1}^\infty t_n\geq 0$. Of course, we may assume that $\sum_{n=1}^\infty t_n>0$. Thus letting $a_i=t_i^{1/2}$ and $b_i=t_i^{1/2}$ in (\ref{eqn:2.3}) we get
\[
\begin{split} 
-\sum_{n=1}^N t_n \log\sqrt{t_n }&\leq -\Big( \sum_{n=1}^N t_n\Big)\cdot \log\Big( \sum_{n=1}^N t_n\Big)\leq \|x\|_1\big|\log\|x\|_1\big|,
\end{split}
\]
for all $N$ sufficiently large. Consequently,
\[
\begin{split}
\eta\Big(1 - \sum_{n=1}^\infty t_n\Big) + \theta\sum_{n=1}^\infty t_n |\log\sqrt{t_n} |&\leq %\eta - \sum_{n=1}^\infty \log(\theta_n t_n)^{\theta_n t_n}\\[1mm]
%&=
\eta + \theta \epsilon\leq \epsilon.
\end{split}
\]
This shows that $T(x)\in K$ and hence $T(K)\subset K$. We proceed now to show that $T$ is fixed-point free. Let us assume for a contradiction that $x= T(x)$ for some $x=\sum_{n=1}^\infty t_n e_n\in K$. Then 
\[
t_1 = \eta\Big( 1 - \sum_{n=1}^\infty t_n\Big),\qquad t_{n+1}= \theta t_n|\log\sqrt{t_n}|\; \text{ for all } n\in\mathbb{N}.
\]
It is a simple matter to check that these equalities are incompatible. In fact, $t_1=0$ implies that all remaining $t_n$ are  zeros, contradicting thus the first equality. If $t_1>0$ then all numbers $t_n$ are also positive. But, since $t_n\to 0$ one may find an integer $n_0$ such that $\theta |\log\sqrt{t_n}|>1$ for all $n\geq n_0$, and hence $t_n\geq t_{n_0}>0$ for all $n\geq n_0$. It turns out that this contradicts $t_n\to 0$. We finally proceed to show that $T$ is $L$-log-nonexpansive. Take arbitrary points $x=\sum_{n=1}^\infty t_n e_n$ and $y=\sum_{n=1}^\infty s_n e_n$ in $K$. Then 
\[
\begin{split}
\| T(x) - T(y)\|_1&\leq \eta \| x- y\|_1 + \theta\sum_{n=1}^\infty \big| t_n |\log\sqrt{t_n}| - s_n|\log\sqrt{s_n}|\big|\\[1.2mm]
&\leq \eta \| x- y\|_1 + \theta\sum_{n=1}^\infty |t_n -s_n|\Big( \frac{1}{\ln 10} + \big|\log\sqrt{|t_n -s_n|}\big|\Big)\\[1.2mm]
&\leq \Big(\eta+ \frac{\theta}{\ln 10}\Big)\|x - y\|_1 + \theta\sum_{n=1}^\infty  |t_n - s_n|\big|\log\sqrt{|t_n - s_n|}\big|\\[1.2mm]
%&\leq \Big(\eta+ \frac{\theta}{\ln 10}\Big)\|x - y\|_1 + \theta \|x - y\|_1 \cdot\big|\log\|x - y\|_1\big|\\[1.2mm]
&\leq \|x - y\|_1\big( L + \big|\log\|x - y\|_1\big|\big),
\end{split}
\]
where in the second inequality we employed Example \ref{ex:4.1} with $\sigma=1/2$ and in the last inequality we used again (\ref{eqn:2.3}) in a convenient way. 
\end{ex}

