\section{Results}\label{sec:3}

%---------------------------------------

%-----------------------------------

We first prove the following general result. 

\begin{theorem}\label{thm:M1} Let $X$ be a Banach space. Then there exists a closed convex set $K\subset B_X$ such that for every $\varepsilon\in (0,1)$ and every modulus $\omega\in \mathcal{H}$, $K$ fails the FPP for $1+\varepsilon$-$\omega$-Lipschitz maps with null minimal displacements. In addition, if $X$ contains a complemented basic sequence then $K$ can be taken to be $B_X$. 
\end{theorem}


\begin{proof} The proof follows \cite[Theorem 4.1]{BF}. Let $(x_n)_{n=1}^\infty$ be a normalized basic sequence and let $\llbracket x_n \rrbracket$ denote its closed linear span. By taking an equivalent renorming on $\llbracket x_n \rrbracket$, we may assume that $(x_n)_{n=1}^\infty$ is normalized and premonotone, that is, $\|Q_Nx\|\leq \|x\|$ for all $x=\sum_{n=1}^\infty t_n x_n \in \llbracket x_n\rrbracket$ and $N\in \mathbb{N}$, where $Q_N(x)= \sum_{n=N}^\infty t_n x_n$. As for example, consider the norm $\vertiii{x}=\sup_n\|Q_n(x)\|$. Fix a decreasing sequence $\beta_n\to 0$ in $(0,1)$ so that $\sum_{n=1}^\infty \beta_n\leq 1$. For $n\in\mathbb{N}$, set $\alpha_n= 1-\beta_n$. Then $\|\sum_{n=1}^\infty \alpha_n t_n x_n\|\leq \|x\|$ for all $x=\sum_{n=1}^\infty t_nx_n \in \llbracket x_n \rrbracket$. Pick a nonconstant function $f\colon [0,1]\to\mathbb{R}_+$ such that $\omega_f\leq \omega$. Now, let $K=B_{\llbracket x_n\rrbracket}$ and define $S\colon K\to K$ by 
\[
S(x)= \sum_{n=1}^\infty \alpha_n t_n x_n + (1- \|x\|)\cos\big( f(\|x\|)-f(0)\big)\sum_{n=1}^\infty \beta_n x_n.
\]
It is easy to see that $S$ does not have fixed points in $K$. In addition, note that $x_k - S(x_k)= \beta_k x_k$ for all $k\in\mathbb{N}$. So, $\mathrm{d}(S,K)=0$. Finally, a direct calculation using Example \ref{ex:4.2} shows
\[
\|S(x)- S(y)\|\leq 2\| x - y\|+ \omega(\|x - y\|),\quad \forall x, y\in K.
\]
In view of Proposition \ref{prop:2.7} the result follows. 
\end{proof}

%-----------------------------

\vskip .1cm 

\begin{remark} We want to point out that unlike what occurs in \cite{BF}, the previous result shows that in general the construction of the mapping $S$ above may not result in a Lipschitz map.
\end{remark}

%---------------------------

The following proposition shows that ($\omega_2$) is not sufficient to ensure AFPP under $L$-$\omega$-nonexpansiveness. 

%------------------------------------------

\begin{proposition}\label{thm:M2} Let $C$ be a bounded closed noncompact convex subset of a Banach space $X$. Assume that $\omega$ satisfies ($\omega_2$). Then there exists a closed convex subset $K$ of $C$ such that for every $L\in (0,1]$, $K$ fails the AFPP for $L$-$\omega$-nonexpansive maps. 
\end{proposition}

\begin{proof} We first assume that $0\in C$. Fix $L\in (0,1]$ and take $\varepsilon \in (0,1)$ such that $\varepsilon \leq L$. By Lin-Sternfeld's result \cite{LS} and an easy shrinking's Lipschitz constant argument due to Goebel (cf. \cite[p. 147]{Go2002}), there exists a $1+\varepsilon$-Lipschitz mapping $P\colon C\to C$ with $\mathrm{d}(P,C)>0$. Now pick a number $\delta_0\in (0,1)$ so that $\omega(\delta)\geq \delta$ for all $\delta\in (0, \delta_0]$. Let $R:=\sup_{x\in C}\|x\|$ and choose $\eta\in (0,1)$ so that $2\eta R< \delta_0$. Set $K=\eta C$ and define $T\colon K\to K$ by $T(u)= \eta P(u/\eta)$. Notice that $K\subset C$, $\diam K\leq \delta_0$ and
\[
\begin{split}
\|T(u) - T(v)\|&\leq (1 + \varepsilon)\| u - v\|\leq L\|u - v\| + \|u- v\|\leq L\| u- v\| + \omega(\| u - v\|),
\end{split}
\] 
for all $u, v\in K$. Assume now that $0\not\in C$. Fix $x_0\in C$ and set $C_0:=C-\{x_0\}$. Applying the previous argument to $C_0$ we obtain a number $\eta>0$ and a $L$-$\omega$-nonexpansive mapping $T_0\colon \eta C_0\to \eta C_0$ with positive minimal displacement. Consider the mapping $T\colon \eta C\to \eta C$ given by $T(u) = T_0(u - \eta_0) + \eta x_0$. It is easy to check that $T$ is $L$-$\omega$-nonexpansive and has positive minimal displacement. 
\end{proof}

%-------------------



%-------------------------

\begin{remark} The above leads us to ask under which condition on $\omega$:
\begin{itemize}
\item[($\mathcal{Q} 1$)] Does convex subsets of a Banach space have the AFPP for $\omega$-nonexpansive maps? 
\item[($\mathcal{Q} 2$)] Does the closed unit ball of any Banach space have the AFPP for $L$-$\omega$-nonexpansive maps?
\end{itemize}
\end{remark}

%-------------------------------------------------


\vskip .1cm 

%------------------------------------------------

We do not know whether these questions have a full affirmative answer. However, as we shall see later on, some positive results can be obtained in certain moduli of continuity.  Our next result illustrates how the AFPP for log-nonexpansive maps lifts to unbounded sets.

%--------------------

\vskip .1cm 

%--------------------

\begin{proposition}\label{prop:5.5} Let $C$ be an unbounded convex subset of a Banach space $X$. Assume that $\omega$ is a modulus of continuity in which $\omega(1)=0$ and every bounded convex subset of $C$ has the AFPP for $\omega$-nonexpansive maps. Then $C$ has the same property. 
\end{proposition} 

\begin{proof} Assume that $T\colon C\to C$ is $\omega$-nonexpansive. %By Lemma \ref{lem:2.2} we can suppose that $C$ is unbounded. 
We may assume without loss of generality that $0\in C$, as shown by a simple translation argument. Define $C_1= B_X\cap C$ and for every $n\geq 2$ let 
\[
C_n = \{ x\in C\colon n-1 < \| x\|\leq n\}. 
\]
Clearly, we have that $C=\bigcup_{n=1}^\infty C_n$. Take $x\in C_2$ and consider on $[0,1]$ the function $f_x(r)= (1-r)\|x\|$. Since $f_x(0)=\|x\|>1$ and $f_x(1)=0$, by the Intermediate Value Theorem there is $r_0\in (0,1)$  such that $f_x(r_0)=1$. Let $y_0= r_0 x$. Clearly $\|y_0 - x\|=(1-r_0)\|x\|=1$ and $y_0\in C_1$. Since $T$ is $\omega$-nonexpansive, we have $\|T x - Ty_0\|=0$ and this in turn implies $Tx\in T(C_1)$ and $T(C_2)\subset T(C_1)$. Assume that for some $n$, we have already proved that $T(C_{n+1})\subset T(C_n)$. Let $x\in C_{n+2}$. Similarly as before, there is $r_0\in (0,1)$ so that $(1-r_0)\|x\|=1$. Let $y_0=r_0 x$ and note that $\| y_0 -x\|= \|x\| - \|y_0\|=1$ and $y_0\in C$. Moreover, $y_0\in C_{n+1}$. Indeed, since $n+1< \|x\|\leq n+2$ and $\|x \|- \|y_0\|=1$ we have $n< \| y_0\|\leq n+1$, so $y_0\in C_{n+1}$ as claimed. Now because $T$ is $\omega$-nonexpansive, $\|Ty_0 - Tx\|=0$. So, $Tx= Ty_0\in T(C_{n+1})$, that is, $T(C_{n+2})\subset T(C_{n+1})$. Therefore $T(C)\subset T(C_1)$. Consequently, if $K=\mathrm{conv}(TC_1)$, $K$ is a convex and bounded subset of $C$ which is $T$-invariant. By assumption the result follows. 
\end{proof}

