In general, the FPP is not implied by hyperconvexity in our context. 

\vskip .2cm 

%--------------------------

\begin{proposition}\label{prop:5.9} The following statements hold:
\begin{itemize}
\item There exists $\epsilon\in (0,1)$ so that the closed ball $B_{\ell_\infty}(\epsilon)$ of center $0$ and radius $\epsilon$ fails the FPP for $L$-log-nonexpansive maps no matter what $L\in (0,1]$. 
\item $B_{\ell_\infty}$ fails the FPP for $1+\delta$-log-Lipschitz maps for all $\delta\in (0,1)$. 
\end{itemize}
\end{proposition}

\begin{proof} The proof is inspired by an example of S. Prus (cf. \cite[p.373]{KLS} see also \cite[Example 3.2]{Bar}). Let $\mathfrak{L}$ be a Banach limit on $\ell_\infty$ with $\|\mathfrak{L}\|\leq 1$. Next pick numbers $\sigma, \epsilon \in (0,1)$ such that $2\sigma\leq L \ln 10$,  $|\log r^\sigma|\geq 1$ for all $r\leq \epsilon$, $\epsilon^\sigma<\frac{1}{10}$  and $r|\log r^\sigma|<\epsilon$ for $r\in [0,\epsilon]$. Let $K=B_{\ell_\infty}(\epsilon)$ denote the closed ball in $\ell_\infty$ of center $0$ and radius $\epsilon$.  Note that for $x\in K$, $\vert\mathfrak{L}(x)\vert\leq\epsilon$. Now define $S\colon K\to K$ by 
\[
S(x)= \big(\epsilon - |\mathfrak{L}(x)| |\log|\mathfrak{L}(x)|^\sigma|,  |t_1||\log|t_1|^\sigma|, |t_2||\log|t_2|^\sigma|, \dots\big),
\]
for $x=(t_n)_{n=1}^\infty \in K$. Then $S$ is fixed point free and satisfies
\[
\|S(x) - S(y)\|_\infty\leq  \|x - y\|_\infty(L + |\log \|x - y\|_\infty|),\quad\forall x, y\in K.
\]
Indeed, if there were $x\in K$ so that $x=T(x)$ then we would have 
\[
t_1 = \epsilon - |\mathfrak{L}(x)||\log \vert\mathfrak{L}(x)\vert^\sigma,\quad t_{n+1} =  t_n |\log|t_n|^\sigma|\;\;\;\forall n\in\mathbb{N}.
\]
Thus $t_n\geq 0$ for all $n\in\mathbb{N}$. Moreover, $t_1>0$ and this implies that for all $n\in\mathbb{N}$, $t_{n+1}\geq t_n$. Let $a=\lim_{n\to\infty} t_n$. Since $a=a |\log|a|^\sigma| $ and $r|\log r^\sigma|<\epsilon$ for $r\in [0,\epsilon],$ one readily sees that 
$10^{-1}<\epsilon^\sigma$, which contradicts the initial election for $\epsilon$ and $\sigma$.  Let's prove now that $S$ is $L$-log-nonexpansive. Fix arbitrary $x=(t_n)_{n=1}^\infty$ and $y=(s_n)_{n=1}^\infty$ in $K$. In view of Example \ref{ex:4.1}, we have
\[
 \big| |\mathfrak{L}(x)||\log|\mathfrak{L}(x)|^\sigma| - |\mathfrak{L}(y)||\log|\mathfrak{L}(y)|^\sigma|\big|\leq  |\mathfrak{L}(x- y)|\big( L + |\log| \mathfrak{L}(x- y)|^\sigma|\big)
\]
and
\[
\big| |t_n| |\log |t_n|^\sigma| -  |s_n| |\log |s_n|^\sigma|\big|\leq |t_n - s_n|\big(L + |\log|t_n - s_n|^\sigma|\big),
\]
for all $n\in\mathbb{N}$. Then 
\[
\begin{split}
\| S(x) - S(y)\|_\infty &\leq \|x - y\|_\infty \big( L + \big|\log\|x - y\|_\infty^\sigma\big|\big)\\[1mm]
&\leq \|x - y\|_\infty \big(L + \big|\log\|x - y\|_\infty\big|\big),
\end{split}
\]
where we used that $\varphi(r)= r(\frac{2\sigma}{\ln 10} + |\log r^\sigma|)$ is nondecreasing on $[0,1]$ for all $\sigma\in (0,1)$. This proves the first statement. In order to prove the second one, it suffices to define $T\colon B_{\ell_\infty} \to B_{\ell_\infty}$ by $T(x)= (1/\epsilon) S(\epsilon x)$ and do $L=\delta$ in above calculations. The proof of proposition is complete. 
\end{proof}


