An open question in metric fixed point theory asks whether or not the space $\co$ can be equivalently renormed to have the FPP for nonexpansive maps. As an application of James distortion result \cite{James1}, our next result particularly solves the corresponding problem for log-nonexpansive maps in every Banach space containing a subspace isomorphic to $\co$. Interestingly, this also shows that not every log-nonexpansive mapping is constant.

\vskip .2cm 

\begin{theorem}\label{thm:5.10} Let $X$ be a Banach space containing an isomorphic copy of $\co$. Assume that $\omega$ is subadditive on $[0,1]$, satisfies ($\omega_2$) and which is nondecreasing on $[0,\eta]$ where $\eta\in (0,1)$ is such that $\omega(\eta)\leq \eta$. Then there exists a closed convex subset of $B_X$ which fails the fixed point property for $\omega$-nonexpansive maps with null minimal displacement. 
\end{theorem}

\begin{proof} Let $\varepsilon\in (0,1)$. By James's distortion result \cite[Lemma 2.2]{James1} there exists a basic sequence $(x_n)_{n=1}^\infty\subset B_X$ equivalent to the standard unit basis of $\co$ so that 
\begin{equation}\label{eqn:3}
\varepsilon \sup_n |a_n |\leq \Bigg\|\sum_{n=1}^\infty a_n x_n\Bigg\|\leq \sup_n|a_n|, 
\end{equation}
for all $(a_n)_{n=1}^\infty \in \co$. Let $\beta_n\to 0$ be a decreasing sequence in $(0,1)$ and set $\alpha_n= 1 - \beta_n$. Now consider the set $K=\big\{ \sum_{n=1}^\infty t_n x_n \colon 0\leq t_n \leq \eta\big\}$. By Proposition \ref{prop:2.5} there exists a nonzero function $f\colon [0,1]\to\mathbb{R}_+$ such that $\omega_f \leq \omega$ on $[0,\eta]$ and $\lim_{r\to 0^+} r^{-1} f(r)=+\infty$. Let us define a mapping $T\colon K\to K$ by
\[
T\Bigg( \sum_{n=1}^\infty t_n x_n\Bigg) = \sum_{n=1}^\infty \alpha_n f(\varepsilon t_n) x_n + \eta\sum_{n=1}^\infty \beta_n x_n.
\]
It is easy to see that 
\[
\alpha_n f(\varepsilon t_n) + \eta\beta_n \leq \alpha_n \omega(\varepsilon t_n)+\eta \beta_n\leq \eta,
\]
for all $n\in\mathbb{N}$, showing that $T$ is well-defined. Let us prove now that $T$ is fixed-point free. If there holds that $T(x)=x$ for some $x=\sum_{n=1}^\infty t_n x_n\in K$ then, for every $n\in\mathbb{N}$, we have
\[
t_n = \alpha_n f(\varepsilon t_n)  + \eta\beta_n.
\]
It turns out that as $t_n\to 0$ we can find an integer $n_0=n_0(\varepsilon, f)\in \mathbb{N}$ so that
\[
f(\varepsilon t_n) \geq t_n\quad \forall n\geq n_0.
\]

\noindent Consequently, $t_n\geq \alpha_n t_n  + \eta\beta_n$ and hence $t_n\geq \eta$ for sufficiently large $n$. But this contradicts the fact that $t_n\to 0$ as $n$ goes to infinity. Finally, we prove that $T$ is $\omega$-nonexpansive. Let $x=\sum_{n=1}^\infty t_n x_n,\, y=\sum_{n=1}^\infty s_n x_n\in K$ and set $a_n = t_n -s_n$ ($n\in\mathbb{N}$). Then by (\ref{eqn:3}) we get
\[
\begin{split}
\|T(x) - T(y)\|&=\Bigg\| \sum_{n=1}^\infty \alpha_n\big( f(\varepsilon t_n) - f(\varepsilon s_n)\big)x_n \Bigg\|\\[1.2mm]
&\leq\sup_{n\in\mathbb{N}} \alpha_n \big| f(\varepsilon t_n) - f(\varepsilon s_n)\big|\\[1.2mm]
&\leq  \sup_{n\in\mathbb{N}} \omega_f( \varepsilon |t_n - s_n|)\leq \omega(\|x - y\|).
\end{split}
\]
It remains to show that $\mathrm{d}(T,K)=0$. To check this, for $i\in\mathbb{N}$, define the function $g_i\colon [\beta_i\eta, \eta]\to [\beta_i \eta, \eta]$ by $g_i(t)= \alpha_i f(\varepsilon t) + \beta_i \eta$. Notice $g_i$ is well-defined and is continuous. By Brower's fixed point theorem there is $t_i \in [\beta_i \eta, \eta]$ so that $g_i(t_i)=t_i$. Define a sequence $(y_n)\subset K$ by putting $y_n:=\sum_{i=1}^n t_i x_i$. Now observe that
\[
T(y_n) = \sum_{i=1}^n g_i(t_i) x_i + \eta \sum_{i=n+1}^\infty \beta_i x_i,
\]
and hence $\|T(y_n) - y_n\|\to 0$ as $n\to\infty$. 
\end{proof}

\vskip .2cm 

%--------------------------------------------------

\begin{cor}
Let $\omega$ be as in previous theorem. Then $(\co,\|\cdot\|_\infty)$ cannot be equivalent renormed to have the FPP for $\omega$-nonexpansive maps with null minimal displacement. 
\end{cor}


