\bigskip

\section{Structurable algebras and \texorpdfstring{$J$}{J}-ternary algebras}\label{se:structurable}

This section is devoted to study the connection of structurable algebras with some $J$-ternary algebras.

Structurable algebras were defined in \cite{Allison78} over fields of characteristic $\neq 2,3$. The
definition over arbitrary fields, or even commutative rings, requires an extra condition 
\cite[\S 5]{AllisonFaulkner_Steinberg}. 

\begin{definition}\label{df:structurable}
A unital algebra with involution $(\cA,-)$  is a \emph{structurable algebra} if the following
two conditions hold:
\begin{subequations}
\begin{gather}
[V_{a,b},V_{c,d}]=V_{V_{a,b}(c),d}-V_{c,V_{b,a}(d)}\label{eq:str1}\\
(a-\overline{a},b,c)=(b,\overline{a}-a,c)\label{eq:str2}
\end{gather}
\end{subequations}
for any $a,b,c,d\in\cA$, where $(a,b,c)\bydef (ab)c-a(bc)$ is the associator of $a,b,c$, and 
$V_{a,b}(c)=(a\overline{b})c+(c\overline{b})a-(c\overline{a})b$.
\end{definition}

Note that \eqref{eq:str1} shows that any structurable algebra satisfies \eqref{eq:FK1} with $\epsilon=-1$
for the triple product
\begin{equation}\label{eq:triple_str}
\{a,b,c\}\bydef V_{a,b}(c)=(a\overline{b})c+(c\overline{b})a-(c\overline{a})b.
\end{equation}
Also, \eqref{eq:str2} may be written as $(s,x,y)=-(x,s,y)$ for any 
$s\in \cS=\{x\in\cA\mid \overline{x}=-x\}$ and $x,y\in\cA$. Applying 
the involution we also have $(x,y,s)=-(x,s,y)$. These equations will be referred to as the 
skew-alternativity of $(\cA,-)$.

Our first aim in this section is to show that the construction of the Lie algebra $\cK(\cA,-)$ in 
\cite{Allison_Isotropic}, defined over fields of characteristic $\neq 2,3$, makes sense too in characteristic
$3$.

Recall that a Lie triple system is a vector space $\cT$ endowed with a trilinear product $[a,b,c]$ 
satisfying the following equations:
\begin{subequations}
\begin{gather}
[u,u,v]=0,\label{eq:LTS1}\\
[u,v,w]+[v,w,u]+[w,u,v]=0,\label{eq:LTS2}\\
[a,b,[u,v,w]]=[[a,b,u],v,w]+[u,[a,b,v],w]+[u,v,[a,b,w]],\label{eq:LTS3}
\end{gather}
\end{subequations}
for any $a,b,u,v,w\in\cT$. Also, for any Lie triple system $\cT$, its \emph{standard embedding} is the
($\ZZ/2$-graded) Lie algebra $L(\cT,\cT)\oplus\cT$, where $L(x,y)(z)=[x,y,z]$, $L(\cT,\cT)$ is the span of the operators
$L(x,y)$ (a Lie subalgebra of $\End_\FF(\cT)$ because of \eqref{eq:LTS3}), with the Lie bracket given by
\[
[A+x,B+y]=\bigl([A,B]+L(x,y)\bigr)+\bigr(A(y)-B(x)\bigr)
\]
for $x,y\in\cT$ and $A,B\in L(\cT,\cT)$.

\smallskip


As in \cite{Faulkner_triples}, given a structurable algebra, consider the triple product $[.,.,.]$ defined on
the direct sum of two copies of $\cA$: $KT(\cA)\bydef \cA_+\oplus \cA_{-}$, as follows:
\begin{equation}\label{eq:KTA}
\begin{split}
[a_\delta,b_{-\delta},c_\delta]&=\{a,b,c\}_\delta,\\ 
[a_\delta,b_\delta,c_\delta]&=0,\\
[a_{-\delta},b_{\delta},c_\delta]&=-\{b,a,c\}_\delta,\\
[a_\delta,b_{\delta},c_{-\delta}]&=\{a,c,b\}_\delta-\{b,c,a\}_\delta,
\end{split}
\end{equation}
for $a,b,c\in\cA$, $\delta=\pm$.

\begin{proposition}\label{pr:KTA}
Let $(\cA,-)$ be a structurable algebra. Then, with the triple product in \eqref{eq:KTA}, $KT(\cA)$ is 
a Lie triple system.
\end{proposition}
\begin{proof}
This is a consequence of \cite[Lemma 1.8 and Corollary 1.4]{Faulkner_triples}.
\end{proof}

\smallskip

\begin{remark}\label{re:KAA}
Let $(\cA,-)$ be a structurable algebra. Consider the triple product $\{a,b,c\}=V_{a,b}(c)$ 
in \eqref{eq:triple_str} and, as in \eqref{eq:LK}, the operators $K_{a,b}:z\mapsto \{a,c,b\}-\{b,c,a\}$.
A simple computation gives:
\begin{equation}\label{eq:Kab_str}
\begin{split}
K_{a,b}(c)&=\{a,c,b\}-\{b,c,a\}=V_{a,c}(b)-V_{b,c}(a)\\
 &=(a\overline{c})b+(b\overline{c})a-(b\overline{a})c
                   -(b\overline{c})a-(a\overline{c})b+(a\overline{b})c\\
 &=(a\overline{b}-b\overline{a})c=L_{a\overline{b}-b\overline{a}}(c),
\end{split}
\end{equation}
for any $a,b,c\in \cA$, where $L_x$ denotes the left multiplication by $x$. Hence, $K(\cA,\cA)$ (the
linear span of the operators $K_{a,b}$) is just $L_\cS$, where $\cS=\{a\in\cA\mid \overline{a}=-a\}=
\espan{x-\overline{x}\mid x\in\cA}$ is the subspace of skew-symmetric elements for the involution.

\cite[Corollary 1.4]{Faulkner_triples} shows that the following equation, which is equation (STS2) in
\cite{Faulkner_triples}, holds:
\begin{equation}\label{eq:KV}
K_{a,b}V_{u,v}+V_{v,u}K_{a,b}=K_{K_{a,b}(u),v}
\end{equation}
for any $a,b,u,v\in\cA$. Equations \eqref{eq:str1} and \eqref{eq:KV} show that $\cA$ is a 
$(-1,1)$ Freudenthal-Kantor triple system, i.e., a Kantor triple system.
\end{remark}

\smallskip

Given a structurable algebra $(\cA,-)$, consider the Lie triple system $\cT=KT(\cA)=\cA_+\oplus\cA_-$ in
\eqref{eq:KTA}. This Lie triple system $\cT$ is graded by $\ZZ$ with $\cT_{1}=\cA_+$ and 
$\cT_{-1}=\cA_-$. As a consequence, its standard embedding $\cL=L(\cT,\cT)\oplus\cT$ is $\ZZ$-graded
with:
\[
\cL_{\pm 1}=\cT_{\pm 1},\quad \cL_2=L(\cT_1,\cT_1),\quad \cL_{-2}=L(\cT_{-1},\cT_{-1}),\quad
\cL_0=L(\cT_1,\cT_{-1}).
\]
In what follows we will identify $\End_\FF(\cT)$ with the algebra of matrices 
$\Mat_2\bigl(\End_\FF(\cA)\bigr)$. With this identification, we compute elements in $L(\cT,\cT)$:

\begin{itemize}
\item 
For $a,b,c\in \cA$ we have $[a_+,b_-,c_+]=\{a,b,c\}_+=V_{a,b}(c)_+$ and
$[a_+,b_-,c_-]=-[b_-,a_+,c_-]=-V_{b,a}(c)_-$. Hence, the operator $L(a_+,b_-)$, when considered
as an element in $\Mat_2\bigl(\End_\FF(\cA)\bigr)$ is
\[
L(a_+,b_-)=\begin{pmatrix} V_{a,b}&0\\ 0&-V_{b,a}\end{pmatrix}.
\]
We may consider, as in \cite{Allison78}, the linear endomorphism $\varepsilon$ on $\End_\FF(\cA)$ given
by \[
T^\varepsilon=T-L_{T(1)+\overline{T(1)}}.
\] 
For $x,y,z\in\cA$ we have
\[
\begin{split}
V_{x,y}(z)+V_{y,x}(z)&=(x\overline{y})z+(z\overline{y})x-(z\overline{x})y +
                                      (y\overline{x})z+(z\overline{x})y-(z\overline{y})x\\
      &=(x\overline{y}+y\overline{x})z=L_{x\overline{y}+y\overline{x}}(z).
\end{split}
\]
but $V_{x,y}(1)=x\overline{y}+\overline{y}x-\overline{x}y$, $\overline{V_{x,y}(1)}=
y\overline{x}+\overline{x}y-\overline{y}x$, so 
$x\overline{y}+y\overline{x}=V_{x,y}(1)+\overline{V_{x,y}(1)}$, and hence we get
$V_{x,y}+V_{y,x}=L_{V_{x,y}(1)+\overline{V_{x,y}(1)}}$, or 
\[
V_{x,y}^\varepsilon=-V_{y,x}.
\]
Therefore, $\varepsilon$ restricts to a linear automorphism of order $2$ of the
Lie algebra (\emph{inner structure Lie algebra})
$\mathfrak{instrl}(\cA,-)=\espan{V_{a,b}\mid a,b\in\cA}$. Equation \eqref{eq:str1} shows that
$\varepsilon$ becomes an order two automorphism of the Lie algebra $\mathfrak{instrl}(\cA,-)$.

With this notation, we get
\begin{equation}\label{eq:La+b-}
L(a_+,b_-)= \begin{pmatrix} V_{a,b}&0\\ 0&V_{a,b}^\varepsilon\end{pmatrix},
\end{equation}
and hence $\cL_0=L(\cT_1,\cT_{-1})$ is isomorphic to $\mathfrak{instrl}(\cA,-)$, by means of the
map $T\mapsto \begin{pmatrix} T&0\\ 0&T^\varepsilon\end{pmatrix}$.

\smallskip

\item
Again, for $a,b,c\in\cA$, we have 
$[a_+,b_+,c_-]=\{a,c,b\}_+-\{b,c,a\}_+=\bigl(L_{a\overline{b}-b\overline{a}}\bigr)(c)$
because of \eqref{eq:Kab_str}, which shows
\begin{equation}\label{eq:La+b+}
L(a_+,b_+)=\begin{pmatrix} 0&L_{a\overline{b}-b\overline{a}}\\ 0&0\end{pmatrix},
\end{equation}
so that $\cL_2$ is just $\begin{pmatrix} 0&L_{\cS}\\ 0&0\end{pmatrix}$, which can be identified with
$\cS$ by means of the map $s\mapsto \begin{pmatrix} 0&L_{s}\\ 0&0\end{pmatrix}$.

\smallskip

\item
In the same vein, 
\begin{equation}\label{eq:La-b-}
L(a_-,b_-)=\begin{pmatrix} 0& 0\\ L_{a\overline{b}-b\overline{a}}&0\end{pmatrix},
\end{equation}
and $\cL_{-2}$ can be identified too with $\cS$: 
$s\mapsto \begin{pmatrix} 0&0\\L_{s}&0\end{pmatrix}$.
\end{itemize}

\smallskip

Our next result shows that the Lie algebra $\cK(\cA,-)$ constructed in \cite{Allison_Isotropic} makes 
sense too assuming only that the characteristic is not $2$. It must be remarked that in characteristic 
$3$ it is
no longer true that $\mathfrak{instrl}(\cA,-)$ is the direct sum of $V_{\cA,1}$ and $\Der(\cA,-)$, a result
which is crucial in \cite{Allison_Isotropic} and that we cannot use here.

\begin{proposition}\label{pr:KantorLieAlgebra}
Let $(\cA,-)$ be a structurable Lie algebra. Consider the Lie triple system $\cT=KT(\cA)$ in 
\eqref{eq:KTA} and let $\cL$ be its standard embedding. Then $\cL$ is isomorphic, as a $\ZZ$-graded
Lie algebra, to the algebra defined on the vector space
\[
\cK(\cA,-)=\cN^\sim\oplus\mathfrak{instrl}(\cA,-)\oplus \cN,
\]
where $\cN=\cA\times\cS=\{(x,s)\mid x\in\cA,\, s\in\cS\}$, $\cN^\sim$ is a copy of $\cN$, and 
the bracket is given by imposing that $\mathfrak{instrl}(\cA,-)$ is a subalgebra, together with
 the following formulas:
\begin{equation}\label{eq:KA-}
\begin{aligned}
\relax [T,(x,s)]&=\bigl(T(x),T^\delta(s)\bigr),\\ 
       [T,(x,s)^\sim]&=\bigl(T^\varepsilon(x),T^{\varepsilon\delta}(s)\bigr)^\sim,\\
[(x,s),(y,t)]&=(0,x\overline{y}-y\overline{x}), \\
     [(x,s)^\sim,(y,t)^\sim]&= (0,x\overline{y}-y\overline{x})^\sim,\\
[(x,s),(y,t)^\sim]&=-(tx,0)^\sim+\bigl(V_{x,y}+L_sL_t\bigr)+(sy,0),
\end{aligned}
\end{equation}
for $x,y\in\cA$, $s,t\in\cS$, $T\in\mathfrak{instrl}(\cA,-)$, where $T^\delta=T+R_{\overline{T(1)}}$, 
that is, $T^\delta(x)=T(x)+x\overline{T(1)}$ for any $T\in\mathfrak{instrl}(\cA,-)$ and $x\in\cA$.
\end{proposition}

Note that for $s,t\in\cS$, $L_sL_t=\frac{1}{2}\bigl(V_{st,1}-V_{s,t}\bigr)$ is indeed in 
$\mathfrak{instrl}(\cA,-)$, so the bracket above is well defined. The $\ZZ$-grading on $\cK=\cK(\cA,-)$
is given by $\cK_{2}=\{(0,s)\mid s\in \cS\}$, $\cK_1=\{(x,0)\mid x\in\cA\}$, 
$\cK_0=\mathfrak{instrl}(\cA,-)$, $\cK_{-1}=\{(x,0)^\sim\mid x\in\cA\}$, and 
$\cK_{-2}=\{(0,s)^\sim\mid s\in\cS\}$.

\begin{proof}
Define the degree-preserving linear isomorphism $\varphi:\cL\rightarrow \cK$ as follows:
\begin{itemize}
\item 
$\varphi(x_+)=(x,0)$ and $\varphi(x_-)=(x,0)^\sim$, for $x\in\cA$,

\item
$\varphi\left(\begin{pmatrix} T&0\\ 0&T^\varepsilon\end{pmatrix}\right)=T$, for 
$T\in\mathfrak{instrl}(\cA,-)$,

\item 
$\varphi\left(\begin{pmatrix} 0&L_s\\ 0&0\end{pmatrix}\right)=(0,s)$ and
$\varphi\left(\begin{pmatrix} 0&0\\ L_s &0\end{pmatrix}\right)=(0,s)^\sim$, for $s\in\cS$.
\end{itemize}

Equations \eqref{eq:La+b-}, \eqref{eq:La+b+}, and \eqref{eq:La-b-} prove that 
$\varphi([X,Y])=[\varphi(X),\varphi(Y)]$ for $X,Y\in\cL_1\cup\cL_{-1}$. This is also trivially true for
$X\in\cL_1$ and $Y\in\cL_{-2}$ or $X\in\cL_{-1}$ and $Y\in\cL_2$.

For $s\in\cS$, \eqref{eq:Kab_str} gives $K_{s,1}(x)=(s\overline{1}-1\overline{s})x=2sx$, so we get
$K_{s,1}=2L_s$. Equations
\eqref{eq:KV} and \eqref{eq:Kab_str} give
\[
L_sV_{x,y}+V_{y,x}L_s=K_{sx,y}=L_{(sx)\overline{y}-y(\overline{sx})}.
\]
Hence, for $x,y\in\cA$ and $s\in \cS$ we get the following bracket in $\cL$:
\[
\left[\begin{pmatrix} V_{x,y}&0\\ 0&-V_{y,x}\end{pmatrix}, 
   \begin{pmatrix} 0&L_s\\ 0&0\end{pmatrix}\right]=
 \begin{pmatrix} 0& V_{x,y}L_s+L_sV_{y,x}\\ 0&0\end{pmatrix}=
 \begin{pmatrix} 0& L_{(sy)\overline{x}-x(\overline{sy})}\\ 0&0\end{pmatrix},
\]
but, since $\overline{s}=-s$, we compute
\[
\begin{split}
(sy)\overline{x}-x(\overline{sy})&= (sy)\overline{x}+x(\overline{y}s)\\
  &=(s,y,\overline{x})+s(y\overline{x})-(x,\overline{y},s)+(x\overline{y})s\\
 &=V_{x,y}(s)-(s,\overline{y},x)-s(\overline{y}x)+(s,\overline{x},y)+s(\overline{x}y)\\
 &\qquad +(s,y,\overline{x})+s(y\overline{x})-(s,x,\overline{y})\\
 &=V_{x,y}(s)+s(y\overline{x}+\overline{x}y-\overline{y}x)\\
 &\qquad +(s,\overline{x},y)+(s,y,\overline{x})-(s,\overline{y},x)-(s,x,\overline{y})\\
&=V_{x,y}(s)+s(\overline{x\overline{y}+\overline{y}x-\overline{x}y})\\
 &=V_{x,y}(s)+s\overline{V_{x,y}(1)}=V_{x,y}^\delta(s),
\end{split}
\]
because
\begin{multline*}
(s,\overline{x},y)+(s,y,\overline{x})-(s,\overline{y},x)-(s,x,\overline{y})\\
 = (s,\overline{x}-x,y)+(s,y,\overline{x}-x)-(s,\overline{y}-y,x)-(s,x,\overline{y}-y)=0,
\end{multline*}
by skew-alternativity.
Thus, for $x,y\in\cA$ and $s\in\cS$ we obtain the following bracket in $\cL$:
\[
\left[\begin{pmatrix} V_{x,y}&0\\ 0&-V_{y,x}\end{pmatrix}, 
   \begin{pmatrix} 0&L_s\\ 0&0\end{pmatrix}\right]=
 \begin{pmatrix} 0& V_{x,y}^\delta(s)\\ 0&0\end{pmatrix},
\]
which shows that $\varphi([X,Y])=[\varphi(X),\varphi(Y)]$ also for $X\in\cL_0$ and $Y\in \cL_2$.

In the same vein we compute, for $x,y\in\cS$ and $s\in\cS$,
\begin{multline*}
\left[\begin{pmatrix} V_{x,y}&0\\ 0&-V_{y,x}\end{pmatrix}, 
   \begin{pmatrix} 0&0\\ L_s&0\end{pmatrix}\right]
  =\begin{pmatrix} 0&0\\ -V_{y,x}L_s-L_sV_{x,y}&0\end{pmatrix}\\
   =\begin{pmatrix} 0&0\\ -L_{V_{y,x}(s)+s\overline{V_{y,x}(1)}}&0\end{pmatrix}
=\begin{pmatrix} 0&0\\ L_{V_{x,y}^\varepsilon(s)+s\overline{V_{x,y}^\varepsilon(1)}}  0\end{pmatrix}
=\begin{pmatrix} 0&0\\ L_{V_{x,y}^{\varepsilon\delta}(s)}&0\end{pmatrix}
\end{multline*}

and this shows that $\varphi([X,Y])=[\varphi(X),\varphi(Y)]$ also for $X\in\cL_0$ and $Y\in \cL_{-2}$.

Finally, for $s,t\in\cS$ we get the bracket
\[
\left[\begin{pmatrix} 0&L_s\\ 0&0\end{pmatrix},\begin{pmatrix} 0&0\\ L_t&0\end{pmatrix}\right]
  =\begin{pmatrix} L_sL_t&0\\ 0&-L_tL_s\end{pmatrix}.
\]
But easy computations give
\[
\begin{split}
V_{st,1}(x)&-V_{s,t}(x)=(st)x+x(st)-x(\overline{st})-(s\overline{t})x-(x\overline{t})s+(x\overline{s})t\\
&=(st)x+x(st)-x(ts)+(st)x+(xt)s-(xs)t\\
&=2(st)x-(x,s,t)+(x,t,s)\\
&=2\bigl((st)x-(s,t,x)\bigr)\quad\text{by skew-alternativity}\\
&=2s(tx)=2L_sL_t(x),
\end{split}
\]
so that $L_sL_t=\frac{1}{2}(V_{st,1}-V_{s,t})$. Also, for any $x,y\in\cA$, 
$V_{x,1}(y)=xy+yx-y\overline{x}=V_{1,\overline{x}}(y)$, and hence
\begin{equation}\label{eq:LsLtepsilon}
(L_sL_t)^\varepsilon=\frac{1}{2}(-V_{1,st}+V_{t,s})=\frac{1}{2}(-V_{ts,1}+V_{t,s})=-L_tL_s.
\end{equation}
We conclude that $\varphi([X,Y])=[\varphi(X),\varphi(Y)]$ also for $X\in\cL_2$ and $Y\in \cL_{-2}$.
\end{proof}

\smallskip

\begin{remark}\label{re:KA-2}
A slightly different version of $\cK(\cA,-)$ is given in \cite[\S 6.4]{AllisonBenkartGao}, the bracket in
\eqref{eq:KA-} is substituted by
\begin{equation}\label{eq:KA-2}
\begin{aligned}
\relax [T,(x,s)]&=\bigl(T(x),T^\delta(s)\bigr),\\ 
       [T,(x,s)^\sim]&=\bigl(T^\varepsilon(x),T^{\varepsilon\delta}(s)\bigr)^\sim,\\
[(x,s),(y,t)]&=\bigl(0,2(x\overline{y}-y\overline{x})\bigr), \\
     [(x,s)^\sim,(y,t)^\sim]&=\bigl(0,2(x\overline{y}-y\overline{x})\bigr)^\sim,\\
[(x,s),(y,t)^\sim]&=-(tx,0)^\sim+\bigl(2V_{x,y}+L_sL_t\bigr)+(sy,0).
\end{aligned}
\end{equation}
As remarked in \cite[\S 6.4]{AllisonBenkartGao}, the map
\[
(y,t)^\sim + T + (x,s)\mapsto (y,\frac{1}{2}s)^\sim + T + (2x,2s)
\]
gives an isomorphism from the Lie algebra in \eqref{eq:KA-2} to the Lie algebra in \eqref{eq:KA-}.
\end{remark}

\bigskip

The next results are taken from \cite[\S 4.2]{BCCE}, but one has to be a bit careful as the characteristic
of the ground field here is just $\neq 2$. First, an easy lemma.

\begin{lemma}\label{le:5graded}
Let $\cL$ be a $5$-graded Lie algebra: $\cL=\cL_{-2}\oplus\cL_{-1}\oplus\cL_0\oplus\cL_1\oplus\cL_2$,
 and assume that there are elements $E\in\cL_2$ and 
$F\in\cL_{-2}$, such that $\espan{E,F,H=[E,F]}$ is a subalgebra isomorphic to $\frsl_2$, with 
$\cL_i=\{X\in\cL\mid [H,X]=iX\}$, for $i=-2,-1,0,1,2$.  (In particular $[H,E]=2E$ and 
$[H,F]=-2F$.) Then the following properties hold:
\begin{romanenumerate}
\item
The linear map $\ad_F\vert_{\cL_i}$ is one-to-one for $i=1,2$. Actually, the map 
$\cL_1\rightarrow \cL_{-1}$, $X\mapsto [F,X]$, is bijective with inverse $\cL_{-1}\rightarrow \cL_1$,
$Y\mapsto [E,Y]$; and the map $\cL_2\rightarrow \cL_{-2}$, $X\mapsto [F,[F,X]]$, is bijective
with inverse $\cL_{-2}\rightarrow\cL_2$, $Y\mapsto \frac{1}{4}[E,[E,Y]]$.

\item
Denote by $\frsl_2$ the subalgebra spanned by $H$, $E$, and $F$. Then we have
\[
\Cent_{\cL}(\frsl_2)=\{X\in\cL_0\mid [F,X]=0\}=\{X\in \cL_0\mid [E,X]=0\},
\]
where $\Cent_{\cL}(\frsl_2)$
denotes the centralizer in $\cL$ of the subalgebra $\frsl_2$. 

\item 
 The subalgebra $\cL_0$ splits as 
\[
\cL_0=\Cent_{\cL}(\frsl_2)\oplus [F,\cL_2].
\]

\item
The Lie algebra $\cL$ splits as
\[
\cL=\bigl(\cL_2\oplus [F,\cL_2]\oplus \cL_{-2}\bigr)\oplus \bigl(\cL_1\oplus\cL_{-1}\bigr)
\oplus \Cent_\cL(\frsl_2),
\]
and the subspace $\cL_2\oplus [F,\cL_2]\oplus \cL_{-2}=\sum_{X\in\cL_2}\espan{X,[F,X],[F,[F,X]]}$
is a sum of copies of the adjoint module for $\frsl_2$, the subspace 
$\cL_1\oplus\cL_{-1}=\sum_{X\in\cL_1}\espan{X,[F,X]}$ is a sum of copies of its natural two-dimensional 
module, and $\Cent_{\cL}(\frsl_2)$ is a sum of copies of the one-dimensional trivial module.

In particular the dimension of $\cL$ coincides with $3\dim\cL_2+2\dim\cL_1+\dim\Cent_{\cL}(\frsl_2)$.

\item
If the conditions $\cL_2=[\cL_1,\cL_1]$ and $\cL_0=[\cL_1,\cL_{-1}]$ hold, then we get
\begin{gather*}
\Cent_{\cL}(\frsl_2)=\espan{[X,[F,Y]]+[Y,[F,X]]\mid X,Y\in\cL_1},\\
[F,\cL_2]=\espan{[X,[F,Y]]-[Y,[F,X]]\mid X,Y\in\cL_1}.
\end{gather*}
\end{romanenumerate}
\end{lemma}

\begin{proof}
If $X\in\cL_i$, $i=1,2$, and $[F,X]=0$, then we get $0=[E,[F,X]]=[[E,F],X]=[H,X]=iX$, because $[E,X]$ 
belongs to $\cL_{i+2}=0$. For $X\in\cL_1$, this argument, together with the analogous argument
with $F$ changed by $E$ and $i$ by $-i$, shows that the linear maps 
$\ad_F\colon \cL_1\rightarrow \cL_{-1}$ and $\ad_E:\cL_{-1}\rightarrow\cL_1$ are bijective and one is
the inverse of the other. Also, for $X\in\cL_2$, we get
\begin{multline*}
[E,[E,[F,[F,X]]]]=[E,[F,[E,[F,X]]]]\\
=[E,[F,[H,X]]]=2[E,[F,X]]=2[H,X]=4X,
\end{multline*}
where we have used that $[F,X]$ lies in $\cL_0=\{Z\in\cL\mid [H,Z]=0\}$ and that $[E,X]=0$. 
Assertion (i) follows.

It is clear that $\Cent_{\cL}(\frsl_2)$ lies in the centralizer of $F$, or of $E$. On the other hand,
$\Cent_{\cL}(\frsl_2)$ lies in the centralizer of $H$, which is $\cL_0$. Now, for $X\in\cL_0$ with $[F,X]=0$
we get $0=[E,[F,X]]=[F,[E,X]]$, but $\ad_F\vert_{\cL_2}$ is one-to-one, so $[E,X]=0$ follows. This proves
(ii).

For (iii), if $X$ lies in the intersection $\Cent_{\cL}(\frsl_2)\cap [F,\cL_2]$, then there is an element
$Y\in\cL_2$ such that $X=[F,Y]$ and $[E,X]=0$, so that $0=[E,X]=[E,[F,Y]]=[H,Y]=2Y$, and hence $Y=0$,
and also $X=0$. On the other hand, for $X\in\cL_0$, an easy computation gives:
\[
\begin{split}
[F,[F,[E,X]]]&=-[F,[H,X]]+[F,[E,[F,X]]]\\
   &=[F,[E,[F,X]]]\quad\text{because $[H,X]=0$,}\\
 &=-[H,[F,X]]+[E,[F,[F,X]]]\\
 &=2[F,X]\quad\text{because $[F,X]\in\cL_{-2}$ and $[F,[F,X]]\in\cL_{-4}=0$.}
\end{split}
\]
Hence, we have
\[
X=\left(X-\frac{1}{2}[F,[E,X]]\right)+ \frac{1}{2}[F,[E,X]]\in\Cent_{\cL}(\frsl_2)+[F,\cL_2],
\]
and (iii) follows. 

The assertion in (iv) follows at once from the previous ones.

Finally, in  case $\cL_2=[\cL_1,\cL_1]$ and $\cL_0=[\cL_1,\cL_{-1}]$, we get
\[
\cL_0=[\cL_1,\cL_{-1}]=[\cL_1,[F,\cL_1]]=\espan{[X,[F,Y]]\mid X,Y\in\cL_1},
\]
but for $X,Y\in\cL_1$ we have
\[
[X,[F,Y]]-[Y,[F,X]]=[[F,X],Y]+[X,[F,Y]]=[F,[X,Y]]\in [F,\cL_2],
\]
and 
\[
[F,[X,[F,Y]]+[Y,[F,X]]]=[[F,X],[F,Y]]+[[F,Y],[F,X]]=0,
\]
because $[F,[F,\cL_1]]\in\cL_{-3}=0$. This means that $[X,[F,Y]]+[Y,[F,X]]$ belongs to 
$\Cent_{\cL}(\frsl_2)$. The assertion in (v) follows at once from (iii) because 
$[X,[F,Y]]=\frac12([X,[F,Y]]+[Y,[F,X]])+\frac12([X,[F,Y]]-[Y,[F,X]])$.
\end{proof}





\begin{proposition}\label{pr:5graded}
Let $\cL$ be a $5$-graded Lie algebra: $\cL=\cL_{-2}\oplus\cL_{-1}\oplus\cL_0\oplus\cL_1\oplus\cL_2$,
 and assume that there are elements $E\in\cL_2$ and 
$F\in\cL_{-2}$, such that $\espan{E,F,H=[E,F]}$ is a subalgebra isomorphic to $\frsl_2$, with 
$\cL_i=\{X\in\cL\mid [H,X]=iX\}$, for $i=-2,-1,0,1,2$.   Then $\cL_1$ is a $J$-ternary algebra with the triple product
\[
\ptriple{X,Y,Z}=\frac{1}{2}[[X,[F,Y]],Z]
\]
for $X,Y,Z\in\cL_1$.
\end{proposition}
\begin{proof}
$\cL$ splits, as a module for the Lie subalgebra $\frsl_2=\espan{E,F,H}$, as a direct sum of copies
of the adjoint module, the natural module, and the trivial module, as shown in Lemma \ref{le:5graded}.
 Actually, for any  $X\in\cL_2$, 
$\espan{X,[F,X],[F,[F,X]]}$ is (isomorphic to) the adjoint module, while for any $X\in\cL_1$, 
$\espan{X,[F,X]}$ is (isomorphic to) the natural module. The sum of the trivial modules, that is, the 
centralizer of $\frsl_2$, is contained in $\cL_0$. 
Therefore, $\cL$ is endowed with a short 
$\SLs_2$-structure and can be written as in \eqref{eq:shortA1_isotypic}, with $V=\FF p\oplus\FF q$, 
$(p\mid q)=1$, $H,E,F\in\frsl(V)$ with coordinate matrices 
$\left(\begin{smallmatrix} 1&0\\ 0&-1\end{smallmatrix}\right)$,
$\left(\begin{smallmatrix} 0&1\\ 0&0\end{smallmatrix}\right)$, and
$\left(\begin{smallmatrix} 0&0\\ 1&0\end{smallmatrix}\right)$, respectively, 
 in the basis $\{p,q\}$. In particular $\cT$ can be identified with $\cL_1=p\otimes\cT$.

Now, $\cT$ is a $J$-ternary algebra by Theorem \ref{th:JTernarySL2}, with triple product
in \eqref{eq:xyzdxy}, and for $X=p\otimes x$, $Y=p\otimes y$, and $Z=p\otimes z$ in $\cL_1$, we use
 \eqref{eq:shortA1bracket} to get
\[
\begin{split}
[[X,[F,Y]],Z]&=[[p\otimes x,[F,p\otimes y]],p\otimes z]\\
  &=[[p\otimes x,q\otimes y],p\otimes z]\\
&=[\gamma_{p,q} \otimes \langle x\mid y\rangle + d_{x,y},p\otimes z]\\
&=\gamma_{p,q}(p)\otimes\Bigl( \langle x\mid y\rangle\bullet z + d_{x,y}(z)\Bigr)\\
&=p\otimes\Bigl(d_{x,y}(z)-\langle x\mid y\rangle\bullet z\Bigr)\\
&=p\otimes 2\ptriple{x,y,z},
\end{split}
\]
thus proving our result.
\end{proof}

\begin{theorem}\label{th:structurable_Jternary}
Let $(\cA,-)$ be a structurable algebra and let $s\in\cS$ be a skew-symmetric element such that the left
multiplication $L_s$ is bijective. Then $\cA$ is a $J$-ternary algebra with the triple product
\[
\ptriple{x,y,z}=V_{x,sy}(z)
\]
for $x,y,z\in\cA$.

Moreover, $\cS$ is a Jordan algebra with multiplication
\[
a\cdot b=\frac12\bigl(a(sb)+b(sa)\bigr),
\]
for $a,b\in\cS$;
$\cA$ is a special Jordan $\cS$-module with
\[
a\bullet x=a(sx),
\]
for $a\in\cS$ and $x\in\cA$; and $\cA$ is an $\cS$-ternary algebra with the triple product above and with
\[
\langle x\mid y\rangle=y\overline{x}-x\overline{y},
\]
for $x,y\in\cA$.

Moreover, if $t$ is the element in $\cA$ with $L_s(t)=1$, then $t$ is in $\cS$ and the Lie algebra 
$S(\cA,\cA)\leq\End_\FF(\cA)^{(-)}$ in \eqref{eq:STT} is given by
\[
S(\cA,\cA)=\{T\in\mathfrak{instrl}(\cA,-)\mid T^\delta(t)=0\}.
\]
\end{theorem}
\begin{proof}
Since $L_s$ is invertible, if $t\in\cA$ is the element such that $st=1$ then, by skew-alternativity, 
we have
$s(ts)=(st)s=s=s1$, which gives $L_s(ts-1)=0$ and $ts=1$. Taking conjugates we get 
$-s\overline{t}=1$, so $L_s(t+\overline{t})=0$ and $t\in\cS$. Moreover, by skew-alternativity, we
have the Moufang identity (proof as in \cite[\S 2.1]{Schafer}) $s(t(sx)=(sts)x=sx$ for any $x\in\cA$. 
Thus $L_sL_tL_s=L_s$ and the invertibility of $L_s$ gives $L_sL_t=L_tL_s=\id$.

Now, the elements $E=(0,t)$ and $F=(0,s)^\sim$ in $\cK(\cA,-)$ (Proposition \ref{pr:KantorLieAlgebra})
satisfy the hypotheses of Proposition \ref{pr:5graded}, which imply that 
$\cK(\cA,-)_1=\{(x,0)\mid x\in\cA\}$ 
is a $J$-ternary
algebra with the triple product
\begin{multline*}
\ptriple{(x,0),(y,0),(z,0)}=\frac12 [[(x,0),[F,(y,0)]],(z,0)]=\frac12 [[(x,0),(sy,0)^\sim],(z,0)]\\
     =\frac12 [V_{x,sy},(z,0)]=\frac12 (V_{x,sy}(z),0),
\end{multline*}
for $x,y,z\in\cA$, and hence we obtain that $\cA$ is a $J$-ternary algebra with the given triple product
 after scaling  by $2$. (Alternatively, 
the version of $\cK(\cA,-)$ in Remark \ref{re:KA-2} can be used to avoid the appearance of $\frac12$ in
the formula above.)


Let us consider now the operators in \eqref{eq:LK} for this $J$-ternary algebra (i.e., special $(1,1)$ 
Freudenthal-Kantor triple system), where
$\ptriple{x,y,z}=V_{x,sy}(z)$. To distinguish it from the $K$-operators $K_{a,b}$ in 
\eqref{eq:Kab_str} we will
denote them by $K^s$ remarking its dependence on the fixed element $s\in\cS$. For $x,y,z\in\cA$,
we get
\begin{multline*}
K^s(x,y)(z)=\ptriple{x,z,y}-\ptriple{y,z,x}
  = V_{x,sz}(y)-V_{y,sz}(x)=K_{x,y}(sz)\\
  =L_{x\overline{y}-y\overline{x}}(sz)=L_{x\overline{y}-y\overline{x}}L_s(z),
\end{multline*}
so that $K^s(\cA,\cA)=L_{\cS}L_s$. As $L_tL_s=\id$, the Jordan algebra $\cJ=\FF\id+K^s(\cA,\cA)$
is just $\cJ=K^s(\cA,\cA)=L_{\cS}L_s$. 

For any $a\in\cS$, by skew-alternativity we have, as before, the Moufang identity $L_aL_sL_a=L_{a(sa)}$, 
and hence, for any $a,b\in\cS$, $L_aL_sL_b+L_bL_sL_a=L_{a(sb)+b(sa)}$, so that the Jordan product 
in $\cJ=L_{\cS}L_s$ becomes
\[
\frac12\bigl((L_aL_s)(L_bL_s)+(L_bL_s)(L_aL_s)\bigr)=\frac12L_{a(sb)+b(sa)}L_s,
\]
for $a,b\in\cS$. Transferring this Jordan product to $\cS$ through the linear bijection 
$\cS\rightarrow \cJ$, $a\mapsto L_aL_s$, shows that $\cS$ is a Jordan algebra with the product
\[
a\cdot b=\frac{1}{2}\bigl(a(sb)+b(sa)\bigr),
\] 
and that $\cA$ is a special module for $\cS$ with $a\bullet x=L_aL_s(x)=a(sx)$,
for $a\in\cS$ and $x\in \cA$.

Theorem \ref{th:JTHein_Allison} shows that $\cA$ is an $\cS$-ternary algebra with the
given triple product and with
\[
\langle x\mid y\rangle =y\overline{x}-x\overline{y}
\]
for $x,y\in\cA$, because 
$-K^s(x,y)=-L_{x\overline{y}-y\overline{x}}L_s=L_{y\overline{x}-x\overline{y}}L_s$, which corresponds,
through the linear bijection above, to the element $y\overline{x}-x\overline{y}\in\cS$.

Finally, from the definition of the Lie algebra $S(\cA,\cA)$ we get
\[
\begin{split}
S(\cA,\cA)&=\espan{V_{x,sy}+V_{y.sx}\mid x,y\in\cA}\\
 &=\espan{[(x,0),[(0,s)^\sim,(y,0)]]+[(y,0),[(0,s)^\sim,(x,0)]]\mid x,y\in\cA}\\
 &=\Cent_{\cK(\cA,-)}(\frsl_2)\quad \text{($\frsl_2=\espan{(0,t),\id,(0,s)^\sim}$)}\\
 &=\{T\in\mathfrak{instrl}(\cA,-)\mid [(0,t),T]=0\}\\
 &=\{T\in\mathfrak{instrl}(\cA,-)\mid T^\delta(t)=0\},
\end{split}
\]
where we have used items (v) and (ii) of Lemma \ref{le:5graded}. (Note that 
$\cK(\cA,-)_0=\mathfrak{instrl}(\cA,-)=[\cK(\cA,-)_1,\cK(\cA,-)_{-1}]$ and
$\cK(\cA,-)_2=[\cK(\cA,-)_1,\cK(\cA,-)_1]$.)
\end{proof}

\smallskip

\begin{example}\label{ex:hermitian_prototypical}
Let $(\cA=\cE\oplus\cW,-)$ be a structurable algebra of a hermitian form 
(see \cite[Example 6.5]{AllisonFaulkner_Steinberg}), that is,
\begin{itemize}
\item 
$(\cE,-)$ is an associative algebra with involution, with multiplication denoted by juxtaposition,

\item 
$\cW$ is a left $\cE$-module with action denoted by $e\circ x$ for $e\in\cE$ and $x\in\cW$,

\item 
$\cW$ is endowed with a hermitian form $\hup:\cW\times\cW\rightarrow \cE$, so that 
$\hup(y,x)=\overline{\hup(x,y)}$ and $\hup(e\circ x,y)=e\hup(x,y)$, for any $x,y\in\cW$ and $e\in\cE$,

\item 
the involution on $\cA$ is defined by $\overline{e+x}=\overline{e}+x$, for $e\in\cE$ and $x\in\cW$, 
that is, the involution on $\cE$ is extended to an order $2$ linear automorphism of $\cA$ by
imposing that $\cW$ consists of symmetric elements.

\item
The multiplication in $\cA$ is defined as follows:
\[
(e_1+x_1)(e_2+x_2)=\bigl(e_1e_2+\hup(x_2,x_1)\bigr)+\bigl(\overline{e_1}\circ x_2+e_2\circ x_1\bigr)
\]
for $e_1,e_2\in\cE$ and $x_1,x_2\in\cW$.
\end{itemize}
Take an element $s\in\cS=\{x\in\cA\mid \overline{x}=-x\}=\{a\in\cE\mid\overline{a}=-a\}$, 
with $L_s$ invertible. Theorem \ref{th:structurable_Jternary} shows that $\cS$ is a Jordan algebra
with $a\cdot b=\frac12 (asb+bsa)$ for $a,b\in\cS$ ($\cE$ is associative, so there is no need 
of parentheses), and that $\cA$ is a $\cS$-ternary algebra with 
\[
a\bullet x=a(sx),\quad \langle x\mid y\rangle =y\overline{x}-x\overline{y},\quad
\ptriple{x,y,z}=V_{x,sy}(z),
\]
for $a\in\cS$, $x,y,z\in\cA$.

Let us show that this ternary triple product is prototypical (Example \ref{ex:prototypical}).

To begin with, consider the \emph{isotope} $\cE^{(s)}$, which is the associative algebra defined on
$\cE$ with new multiplication $a*b\bydef asb$ for any $a,b\in\cE$ and with involution 
$\tau(a)=-\overline{a}$ for any $a\in\cE$. Note that $\tau$ is indeed an involution because 
$\overline{s}=-s$. The unit element of $\cE^{(s)}$ is $t=s^{-1}$, and the Jordan algebra of
symmetric elements is $H(\cE^{(s)},\tau)=\{a\in\cE\mid \tau(a)=a\}=\cS$, with the product
$\frac12 (a*b+b*a)=\frac12(asb+bsa)=a\cdot b$ for $a,b\in\cS$.

Moreover, $\cW$ is a left $\cE^{(s)}$-module with 
\[
a* x\bydef (as)\circ x=a\circ(s\circ x)
\]
for any $a\in \cE$ and $x\in\cW$. Hence, for any $a\in\cS$, $x\in\cW$, and $e\in\cE$,
$a\bullet x=a(sx)=\overline{a}\circ(\overline{s}\circ x)=a\circ(s\circ x)=a* x$, while 
$a\bullet e=ase=a*e$. We conclude that $\cA$ is a left $\cE^{(s)}$-module with action given by
$a\bullet x$ for $a\in\cE$ and $x\in\cA$.

For $x,y\in\cW$ and $a,b\in\cE$, we have
\[
\begin{split}
\langle x\mid y\rangle &=y\overline{x}-x\overline{y}=yx-xy=\hup(x,y)-\hup(y,x),\\
\langle a\mid x\rangle &=x\overline{a}-a\overline{x}=\overline{a}\circ x-\overline{a}\circ x=0,\\
\langle a\mid b\rangle &=b\overline{a}-a\overline{b}.
\end{split}
\]
Define a bilinear form 
\[
\tilde \hup:\cA\times\cA\rightarrow \cE^{(s)}
\]
by imposing $\tilde\hup(\cE,\cW)=\tilde\hup(\cW,\cE)=0$,
$\tilde\hup(x,y)=\hup(x,y)$ for $x,y\in\cW$, and $\tilde \hup(a,b)=-a\overline{b}$ for $a,b\in\cE$. 
By its own definition we get
\[
\langle x\mid y\rangle =\tilde \hup(x,y)-\tilde \hup(y,x),
\]
for any $x,y\in\cA$. For $x,y\in\cW$, $e,f\in\cE$, and $a\in\cS$, we have:
\[
\begin{split}
\tilde \hup(y,x)&=\hup(y,x)=\overline{\hup(x,y)}=-\tau\bigl(\tilde \hup(x,y)\bigr),\\
\tilde \hup(f,e)&=-f\overline{e}=-\overline{e\overline{f}}
      =\tau\bigl(e\overline{f}\bigr)=-\tau\bigl(\hup(e,f)\bigr),\\
\tilde \hup(a\bullet x,y)&=\hup((as)\circ x,y)=(as)\hup(x,y)=a\bullet \hup(x,y)=a\bullet\tilde \hup(x,y),\\
\tilde \hup(a\bullet e,f)&=-ase\overline{f}=a\bullet\tilde \hup(e,f).
\end{split}
\]
This shows that $\tilde h$ is a skew-hermitian form. We must finally check that 
$\ptriple{x,y,z}=\tilde \hup(x,y)\bullet z+\tilde \hup(z,x)\bullet y +\tilde \hup(z,y)\bullet x$ for any $x,y,z\in\cA$.
We split this into several cases.

For $x,y,z\in\cW$ we get
\[
\begin{split}
\ptriple{x,y,z}&=V_{x,sy}(z)
      =\bigl(x(\overline{sy})\bigr)z+\bigl(z(\overline{sy})\bigr)x-\bigl(z\overline{x}\bigr)(sy)\\
 &=-\bigl(x(ys)\bigr)z-\bigl(z(ys)\bigr)x-(zx)(sy)\\
 &=-\hup(s\circ y,x)z-\hup(s\circ y,z)x-\hup(x,z)(sy)\\
 &=-\hup(x,s\circ y)\circ z-\hup(z,s\circ y)\circ x+\hup(z,x)\circ(s\circ y)\quad 
                        \text{(as $ex=\overline{e}\circ x$)}\\
 &=\bigl(\hup(x,y)s\bigr)\circ z+\bigl(\hup(z,y)s\bigr)\circ x+\hup(z,x)\circ(s\circ y)\\
 &=\tilde\hup(x,y)\bullet z+\tilde\hup(z,y)\bullet x+\tilde\hup(z,x)\bullet y,
\end{split}
\]
as desired.

For $e,f,g\in\cE$ we get 
\[
\begin{split}
\ptriple{e,f,g}&=V_{e,sf}(g)
       =\bigl(e(\overline{sf})\bigr)g+\bigl(g(\overline{sf})\bigr)e-(g\overline{e})(sf)\\
  &=-e\overline{f}sg-g\overline{f}se-g\overline{e}sf\\
  &=\tilde\hup(e,f)\bullet g+\tilde\hup(g,f)\bullet e+\tilde\hup(g,e)\bullet f.
\end{split}
\]

Now, for $x,y\in\cW$ and $e\in\cE$,
\[
\begin{split}
\ptriple{x,e,y}&=V_{x,se}(y)
      =\bigl(x(\overline{se})\bigr)y+\bigl(y(\overline{se})\bigr)x-(y\overline{x})(se)\\
 &=-\bigl((\overline{e}s)\circ x\bigr)y-\bigl((\overline{e}s)\circ y\bigr)x-(yx)(se)\\
 &=-\hup(y,(\overline{e}s)\circ x)-\hup(x,(\overline{e}s)\circ y)-\hup(x,y)se\\
 &=-\hup(y,x)\overline{s}e-\hup(x,y)\overline{s}e-\hup(x,y)se\\
 &=\tilde\hup(y,x)\bullet e,
\end{split}
\]
as required, because $\tilde\hup(\cW,\cE)=0$. We also have
\[
\ptriple{e,x,y}=\ptriple{x,e,y}+\langle e\mid x\rangle\bullet y=\ptriple{x,e,y}=\tilde\hup(y,x)\bullet e
\]
using \eqref{eq:JTAllison4}, and
\[
\ptriple{x,y,e}=\ptriple{e,y,x}-\langle x\mid e\rangle\bullet y=\ptriple{e,y,x}=\ptriple{y,e,x}
 =\tilde\hup(x,y)\bullet e
\]
using \eqref{eq:JTAllison3}, \eqref{eq:JTAllison4}, and $\langle\cW\mid\cE\rangle=0$.

Finally, for $e,f\in\cE$ and $x\in\cW$, we get
\[
\begin{split}
\ptriple{x,e,f}&=V_{x,se}(f)
     =\bigl(x(\overline{se}\bigr)f+\bigl(f(\overline{se}\bigr)x-(f\overline{x})(se)\\
 &=-\bigl((\overline{e}s)\circ x)f-(f\overline{e}s)x-(se)\circ(fx)\\
 &=-f\circ\bigl((\overline{e}s)\circ x)+(se\overline{f})\circ  x -(se\overline{f})\circ x\\
 &=-(f\overline{e})\bullet x=\tilde\hup(f,e)\bullet x
\end{split}
\]
as desired, and also, using \eqref{eq:JTAllison4}, \eqref{eq:JTAllison3}, and 
$\langle\cW\mid\cE\rangle=0$ we have
\[
\ptriple{e,x,f}=\ptriple{x,e,f}+\langle e\mid x\rangle \bullet f=\ptriple{x,e,f}=\tilde\hup(f,e)\bullet x
\]
and 
\[
\ptriple{e,f,x}=\ptriple{x,f,e}-\langle e\mid x\rangle\bullet f=\ptriple{x,f,e}=\tilde\hup(e,f)\bullet x.
\]

We conclude that indeed, $\cA$ is an $\cS$-ternary algebra of prototypical type.

Also note that the structurable algebras of hermitian forms include the associative algebras with
involution ($\cW=0$).
\end{example}

