\section{Introduction}\label{sec:intro}



 An effective action of $S^1$ on a symplectic manifold $(M,\omega)$ is \textbf{Hamiltonian} if it admits a \textbf{momentum map}: a smooth function $\mu\colon M\to \R \cong (\Lie(S^1))^{*}$ with 
\begin{equation} \label{eq:mu}
d\mu(\cdot)=-\omega(\xi,\cdot),
\end{equation} where $\xi$ is the fundamental vector field
of the action. 
The space $(M,\omega,\mu)$ 
is called a \textbf{Hamiltonian $S^1$-manifold}.
An \textbf{isomorphism} between Hamiltonian $S^1$-manifolds is an equivariant symplectomorphism that intertwines the momentum maps. 
The $S^1$-action is \textbf{semi-free} if all stabilizers are connected, i.e., they are either the circle or the trivial group.\\




Let $(M,\omega,\mu)$  be a connected semi-free Hamiltonian $S^1$-manifold.
 Assume that $\mu$ is {proper} and that 
the momentum image is bounded, so $\mu$ has finitely many critical values $\lambda_0<\hdots < \lambda_k$.
 By \eqref{eq:mu}, the set of critical points of $\mu$ coincides with the fixed point set $M^{S^1}$.
    The assumption that the $S^1$-action is semi-free implies that it is free on
    \[
    \mu^{-1}((-\infty,\lambda_0)) \cup \mu^{-1}((\lambda_0,\lambda_1))\cup \hdots \cup \mu^{-1}((\lambda_{k-1},\lambda_k)) \cup \mu^{-1}((\lambda_k,\infty)). 
    \]
    Therefore, one can think of $M$ as the union of the above sets with
    $\mu^{-1}((\lambda_0-\eps_0,\lambda_0+\eps_0))$, $\mu^{-1}((\lambda_1-\eps_1,\lambda_1+\eps_1))$, and so on, for positive $\eps_i$, $i=0,\hdots,k$, small enough such that $\lambda_i$ is the only critical value in 
    $(\lambda_i-\eps_i,\lambda_i+\eps_i)$. 
        This observation motivated Gonzales' definition in \cite{Go11} of {\bf local data}: an atlas of compatible Hamiltonian charts; see Appendix \ref{Local Data}.\\
 Gonzales observed that a 'rigidity assumption' is needed in order to recover the local data from the {\bf fixed point data}, as defined below. 
  The {rigidity assumption} 
     will ensure that the equivariant symplectomorphism type 
of $\mu_1^{-1}((\lambda,\lambda'))$, for $\lambda<\lambda'$ two consecutive critical values, is determined by the equivariant symplectomorphism type of $\mu_1^{-1}((\lambda,t))$ for arbitrary $t\in (\lambda,\lambda')$. 
 We will use the following notation and definitions.

\begin{Notation}\label{not:semifreeHamiltonian}
 For a regular value $t$ of the momentum map $\mu \colon M \to \R$,
   the level set
   $P_t:=\mu^{-1}(t)$
   is a manifold of dimension $\dim M-1$, by the implicit function theorem; compact since $\mu$ is proper. It is  connected because $\mu$
 is Morse-Bott with even indices and $M$ is connected \cite{At82}.
  Since the $S^1$-action on $P_t$ is free, the {\em orbit space} $M_t:=P_t/S^1$ is a manifold 
   of dimension $\dim M-2$ and 
   $S^1\to P_t\to M_t$ is a principal $S^1$-bundle. Since $P_t$ is compact, there is a unique closed form $\omega_t$ on $M_t$ such that $\pi_{P_t \to M_t}^{*}{\omega_t}=\iota_{P_t \hookrightarrow M}^{*}\omega$. The form $\iota_{P_t \hookrightarrow M}^{*}\omega$ is basic, since $\omega$ is invariant and ${\iota_{P_t \hookrightarrow M}^{*}\omega}(\xi,\cdot)=d \mu \circ {\iota_{P_t \hookrightarrow M}}=0$. Moreover, the {\em reduced form} $\omega_t$ is symplectic by \cite{MW74}.

    If $M$ is of dimension six  and the action is semi-free, it turns out that even for non-extremal critical values $\lambda$, the orbit space $\mu^{-1}(\lambda)/S^1$, which we also call $M_{\lambda}$, can be given a smooth structure such that the symplectic form on $M$ descends to a symplectic form on the four-dimensional manifold $M_{\lambda}$.
    The case in which the fixed points at $\lambda$ are isolated is proven in \cite[Section 3.2]{Mc09}. The case in which there are also fixed surfaces 
    at $\lambda$ is in \cite[Section 3.3.1]{Go11}. 

    If $\lambda$ is an extremal critical value, then $M_{\lambda}$ coincides with the fixed point set $F$ at level $\lambda$; it is again connected. The symplectic form $\omega_{\lambda}$ is then the restriction of the symplectic form on $M$ to $F$.

    We endow the manifold $M_t$ with the orientation induced by the symplectic form $\omega_t$, for $t$ regular or critical.


    \end{Notation}


 \begin{definition}\label{def:rigid}\cite[Definition 1.4]{Go11}.
        Let $B$ be a smooth manifold and $\{\omega_t\}$ a smooth family of symplectic forms on $B$, parametrized by real values $t\in I=[t_0,t_1]$ in a closed interval. We say that $(B,\{\omega_t\})$ is \textbf{rigid} if
        \begin{itemize}
            \item Symp$(B,\omega_{t})\cap \text{Diff}_{0}(B)$ is path-connected for all $t\in I$, where $\text{Diff}_0(B)$ is the identity component of the diffeomorphism group of $B$.
            \item Any deformation between any two cohomologous symplectic forms  that are symplectic deformation equivalent to $\omega_{t_0}$
             on $B$ may be homotoped through symplectic deformations with fixed endpoints into an isotopy, i.e., a symplectic deformation through cohomologous forms.
        \end{itemize}
    \end{definition}
   Let $I=[t_0,t_1]\subset \mu(M)$ be an interval of regular values. Using the normalized gradient flow of $\mu$, we obtain a smooth family of diffeomorphisms $M_{t_0}\cong M_t$, $t\in I$, and use this family to view all reduced forms $\omega_t$ of $M_t$ to be defined on $M_{t_0}$.
    \begin{definition}\label{def:rigidityassumption}
        We say that $M$ satisfies the \textbf{rigidity assumption} if for all closed intervals $I=[t_0,t_1]\subset \R$ of regular values, $(M_{t_0},\{\omega_t\})$ is rigid in the sense of \Cref{def:rigid}.
    \end{definition}

     \begin{definition}\label{def:fixedpointdata}
   \cite[Definition 3.9]{Go11}.
 Assume that $\lambda$ is a common critical value of $M^1=(M^1,\omega^1,\mu_1)$ and $M^2=(M^2,\omega^2,\mu_2)$, non-extremal for both or extremal for both.  If $\lambda$ is non-extremal, assume moreover that $\lambda$ is \emph{simple}, meaning that all fixed point components at $\lambda$ have the same index.
         $M^1$ and $M^2$ have the \textbf{same fixed point data at a non-extremal critical value $\lambda$} if there is a symplectomorphism $f\colon M^1_{\lambda}\to M^2_{\lambda}$  between the reduced spaces at $\lambda$ that
        \begin{itemize}
            \item[(i)] sends the fixed point set of $M^1$ at $\lambda$ to the fixed point set of $M^2$ at $\lambda$;
            \item[(ii)] intertwines the index function on the fixed point sets; 
           \item[(iii)] intertwines $e(P_{\lambda}^-)$ \footnote{As we will see, there is a map $M_{\lambda-\eps}\to M_{\lambda}$ for $\eps>0$ small, under which the Euler class of the $S^1$-bundle over $\mu^{-1}(\lambda-\eps)/S^1=M_{\lambda-\eps}$ has a unique preimage, called $e(P_{\lambda}^-)$. For details, see \Cref{not:elambda}.}.
        \end{itemize}
        $M^1$ and $M^2$ have the \textbf{same fixed point data at an extremal critical value $\lambda$} if there is a symplectomorphism between the
        the corresponding extremal fixed point sets with the restrictions of the symplectic forms that intertwines the symplectic normal bundles in $M^1$ and $M^2$.\\
        We say that $M^1$ and $M^2$ have the \textbf{same fixed point data}\footnote{This data is different from the fixed point data that Hui Li defines in \cite[Definition 2]{Li03}. In Li's definition, and article, the emphasis is placed on the diffeomorphism type of the underlying symplectic manifold as opposed to its equivariant symplectomorphism type.} if they have the same critical values and the same fixed point data at each critical value.
    \end{definition}

Moreover, Gonzales argued \cite[Theorem 1.6]{Go11} that, in dimension six, 
the fixed point data can be further reduced to the {\bf small fixed point data}, if the fixed point sets at each critical level are either surfaces or isolated fixed points, 
assuming rigidity as above.
For $M^1$ and $M^2$ to have the {\bf same small fixed point data}, the requirement at a common non-extremal critical value $\lambda$ is that there is a diffeomorphism $f\colon M^1_{\lambda}\to M^2_{\lambda}$ that
        preserves the fixed point sets, the index function and the symplectic form on them (see \cite[Definition 3.11]{Go11}); the requirement at the maximum is that the maxima are symplectomorphic (\cite[Definition 1.3]{Go11}); the requirement at the minimum is as in the definition of $M^1$ and $M^2$ having the same fixed point data (\cite[Definition 1.3]{Go11}).\\





In this paper we follow Gonzales' vision. However, we show that for the fixed point data, or local data,  to determine the isomorphism type of a semi-free Hamiltonian $S^1$-manifold, more assumptions are required. 
We first highlight the subtleties in gluing Hamiltonian charts when more than one non-extremal critical level occurs. We give an example of closed, semi-free Hamiltonian $S^1$-manifolds of dimension six,  with only one fixed component at each critical level,  
that have the same local and fixed point data, and satisfy the rigidity assumption, but are not isomorphic. Thus, it is a counter example to \cite[Theorems 1.5, 1.6, and 2.6]{Go11}. Indeed, these manifolds are not even {\bf $\mu-S^1$-diffeomorphic}, meaning that there is no equivariant diffeomorphism between them that intertwines the momentum maps.
See \Cref{examp:main} and the following discussion. 

We then give an example of semi-free Hamiltonian $S^1$-manifolds of dimension six that satisfy the rigidity assumption, have the same small fixed point data, are isomorphic below a critical level $\lambda$, but for which there is no isomorphism of preimages of neighborhoods of the critical value.
This contradicts \cite[Lemma 3.13]{Go11}, used prominently in the proof of \cite[Theorem 1.6]{Go11}. See \Cref{ex:openDpoly}. The counter example shows that, even under Gonzales' assumptions, the small fixed point data do not necessarily determine the local data.

\begin{noTitle}\label{nt:proof-problem}
We sketch the problem in the proof of \cite[Lemma 3.13]{Go11}. Assume that we have an isomorphism $f$ between two semi-free Hamiltonian manifolds $M^1$ and $M^2$ below a common critical level $\lambda$. In order to extend the isomorphism over the critical level $\lambda$, Gonzales removes neighborhoods $U^1$ and $U^2$ around the fixed points of $M^1$ resp.\ $M^2$ at level $\lambda$ such that the flow of the gradient vector field of the momentum map induces a well defined map on $\mu_1^{-1}((\lambda-\eps,\lambda+\eps))\smallsetminus U^1$ and on $\mu_2^{-1}((\lambda-\eps,\lambda+\eps))\smallsetminus U^2$. If $f$ maps the neighborhoods $U^1_t:=U^1\cap \mu_1^{-1}(t)$ and $U^2_t:=U^2\cap \mu_2^{-1}(t)$ into each other, one could indeed obtain a $\mu-S^1$-diffeomorphism
\[
\mu_1^{-1}((\lambda-\eps,\lambda+\eps))\smallsetminus U^1 \cong
\mu_2^{-1}((\lambda-\eps,\lambda+\eps)) \smallsetminus U^2.
\]
However, $f$ does not need to map $U^1_t$ and $U^2_t$ into each other, nor does there need to exist an isotopy from $f$ through $\mu-S^1$-diffeomorphisms to a map $f'$ that intertwines the neighborhoods.
There might be topological obstructions to do so. For example, $U^1_t/S^1$ and $U^2_t/S^1$
might be 
neighborhoods of embedded 2-spheres in $M^1_t$ and $M^2_t$,
as
happens if some fixed point component at $\lambda$ is a $2$-sphere  but also when there is an isolated fixed point at $\lambda$ with  Morse index $4$, and $U^1_t/S^1$ and $f^{-1}(U^2_t/S^1)$ 
represent different homology classes in $M^1_t$.
\end{noTitle}

We prove a variation of \cite[Lemma 3.13]{Go11}. 
We assume that reduced spaces below $\lambda$ are symplectic rational surfaces, as defined in \Cref{not:rationalmanifold}. In such symplectic manifolds, we have a characterization of exceptional classes using the theory of $J$-holomorphic curves, as in  \cite[Lemma 2.12 and Theorem 3.12]{KK17}.  
 We apply these results to show that $f \colon {\mu_1^{-1}(t)}/{S^1} \to {\mu_2^{-1}(t)}/{S^1}$ intertwines the sets of classes of the spheres that are sent to fixed points of Morse index $4$ at $\lambda$.
Further assuming that the fixed points at a non-extremal critical level are isolated, we deduce that $f$
can be isotoped through $\mu-S^1$-diffeomorphisms to a $\mu-S^1$-diffeomorphism that maps $U_t$ into $U'_t$, thus avoiding the problem described in \ref{nt:proof-problem}.\\
However, even if it is possible to extend $f$ as a $\mu-S^1$-diffeomorphism, it is not clear why it can be extended as an isomorphism. For that, the assumption that reduced spaces are symplectic rational surfaces also comes in handy: we will find an isomorphism $g$ between neighborhoods of the critical sets at $\lambda$ whose induced map on homology of the reduced spaces right below $\lambda$ agrees with the induced map of $f$. Then, we apply results on symplectic rational surfaces and the rigidity assumption on $M$ to conclude that these symplectomorphisms are isotopic through symplectomorphisms, which allows us to piece $g$ and $f$ together.

\begin{Notation}\label{not:rationalmanifold}
We consider the smooth manifold $\C \PP^2 \# k \overline{\C \PP^2}$ as the
manifold obtained from the complex projective plane $\C \PP^2$ by complex blowups at distinct points $q_1, \ldots , q_k$ in $\C \PP^2$. 
We have a
decomposition
$$H_2(\C \PP^2 \# k \overline{\C \PP^2};\Z) = \Z L \oplus \Z E_1 \oplus \cdots \oplus \Z E_k$$
where $L$ is the image of the homology class of a line $\C \PP^1$ in $\C \PP^2$ under the inclusion
map $H_2(\C \PP^2;\Z) \hookrightarrow H_2(\C \PP^2 \# k \overline{\C \PP^2};\Z)$ and $E_1, \ldots , E_k$ are the homology classes of the
exceptional divisors. 
A {\bf blowup form} on $\C \PP^2 \# k \overline{\C \PP^2}$ is a symplectic form for which there
exist pairwise disjoint embedded symplectic spheres in the classes 
$L, E_1, \ldots , E_k$.  


If a symplectic manifold $(B,\omega)$ is symplectomorphic to $S^2\times S^2$ endowed with a positive multiply of the form $\omega^{\lambda}_{S^2 \times S^2}:=(1+\lambda)\omega_{\operatorname{SF}}\oplus \omega_{\operatorname{SF}}$ for $\lambda \geq 0$\footnote{By 
\cite{Gr85,LL95,LM96,Mc90,Ta95,Ta00}, every symplectic form on $S^2 \times S^2$  is of this form, up to rescaling.} or to some $\C \PP^2 \# k \overline{\C \PP^2}$ endowed with a blowup form, we say that $(B,\omega)$ is a \textbf{symplectic rational surface}. 
\end{Notation}
We relate isolated fixed points of Morse index $4$ and fixed spheres in the reduced space of an interior critical value $\lambda$ to spheres in the reduced space at a regular level below $\lambda$. For that, we use the \textit{Morse flow} $f_{\Morse}\colon M_{\lambda-r}\to M_{\lambda}$ induced from the flow of the normalized gradient vector field of the momentum map, defined in \S \ref{rem:criticalvalue}. We denote by $C'\subset M^i_{\lambda-r}$ the preimage of a fixed sphere $C\subset M^i_{\lambda}$ under $f^{i}_{\Morse}$. Also, we define $\mathcal{D}^i_{\sph}\subset H_2(M^i_{\lambda-r})$ to be the set \footnote{There will be no double count of classes due to our assumption that all fixed spheres are exceptional.} of homology classes corresponding to the set of spheres $C'\subset M^i_{\lambda-r}$.\\

We weaken the "same small fixed point data" (at a critical value $\lambda$) of $M^1$ and $M^2$ to the {\bf same $*$-small fixed point data} (at a critical value $\lambda$) of $M^1$ and $M^2$, as follows:
\begin{itemize}
    \item If $\lambda$ is extremal, we assume that the dimensions of the corresponding fixed point sets are the same.
    \item If $\lambda$ is not extremal, we require that there is a diffeomorphism $\eta_{\lambda}$ between the fixed point sets at level $\lambda$ that intertwines the index function (at level $\lambda$).
\end{itemize}
Moreover, we no longer assume that a non-extremal $\lambda$ is simple.
\begin{Setting}
\label{set:intro}

Let $(M,\omega,\mu)$ be a connected semi-free Hamiltonian manifold of dimension six whose momentum map $\mu$ is proper and with a bounded image, and $\lambda$ a critical value of $\mu$.
 We assume that
 \begin{itemize}
    \item for all $t$  below or equal to $\lambda$, the reduced space $(M_t,\omega_t)$ is a symplectic rational surface
    whenever it is of dimension four;

    \item   for any interval $I=[t_0,t_1]$ of regular values below $\lambda$,
    the family $(M_{t_0},\omega_{t\in I})$ is rigid.
 \end{itemize}








\end{Setting}
\begin{theorem}\label{thm:extending-g}
    For $i=1,2$, let $M^i=(M^i,\omega^i,\mu_i)$ and $\lambda$
 be as in 
    \Cref{set:intro}. Assume that $M^1$ and $M^2$ have the same $*$-small fixed point data at the critical value $\lambda$, and that $\lambda$ is the only critical value of $\mu_i$ for $i=1,2$.
    Assume that
 \begin{itemize}       
     \item[(i)] if $\lambda$ is {non-extremal}, then 
there are only isolated fixed points and exceptional spheres in $M^i_{\lambda}$.
\item[(ii)] if $\lambda$ is maximal and the fixed point set  at $\lambda$ in $M^i$ is of $\dim<4$, then it is either a point or a sphere.
    \end{itemize}
  Let $r>0$ be such that there is no critical value in $[\lambda-r,\lambda)$ with respect to both $\mu_1$ and $\mu_2$. Consider an isomorphism 
 $$f \colon \mu_1^{-1}((-\infty,\lambda-r]) \to \mu_2^{-1}((-\infty,\lambda-r])$$
 such that $f_{\lambda-r}$ sends $\mathcal{D}^1_{\sph}$ bijectively into $\mathcal{D}^2_{\sph}$.\\
 Then there is $\eps'>0$ that can be chosen arbitrarily small, such that $f$ restricted to $\mu_1^{-1}((-\infty,\lambda-(\eps'+r)])$ extends over the level $\lambda$ as an isomorphism, meaning that there is $\delta>0$ and an isomorphism
 $$h\colon \mu_1^{-1}((-\infty,\lambda+\delta)) \to \mu_2^{-1}((-\infty,\lambda+\delta))$$
 such that $h=f$ on $\mu_1^{-1}((-\infty,\lambda-(r+\eps')])$.\\
 The statement is true if we replace $-\infty$ everywhere with $\alpha$ for any $\alpha<\lambda-r$.
\end{theorem}

 Note that in our counter example, \Cref{ex:openDpoly}, all the assumptions but (i) hold.\\

We deduce a variation of \cite[Theorem 1.6]{Go11}. 





\begin{theorem}\label{thm:mainresult}
 Let $M^1=(M^1,\omega^1,\mu_1)$ and $M^2=(M^2,\omega^2,\mu_2)$ 
 be compact, simply-connected semi-free Hamiltonian manifolds of dimension six. Assume that $M^1$ and $M^2$ have the same $*$-small fixed point data, and that for every critical value $\lambda$ and $i=1,2$, $M^i$ and $\lambda$ are as in \Cref{set:intro}.
  Suppose that one of the following is true. 
 \begin{itemize}
    \item[(i)] $M^1$ and $M^2$ contain non-extremal fixed surfaces,  these surfaces are all mapped to the same $\lambda_S$ by $\mu_1$ and $\mu_2$, and $M^1$ and $M^2$ have the same fixed point data at $\lambda_S$. In that case, assume that $\lambda_S$ is simple. 
   \item[(ii)] All non-extremal fixed points of $M^1$ and $M^2$ are isolated, and $M^1$ and $M^2$ have the same fixed point data at some non-extremal critical value $\lambda_S$. In that case, $\lambda_S$ does not have to be simple.
   \item[(iii)] All non-extremal fixed points of $M^1$ and $M^2$ are isolated, and neighborhoods of the minima of $M^1$ and $M^2$ are equivariantly symplectomorphic. In that case, we call the minimal level $\lambda_S$.
   \end{itemize}
   Then $M^1$ and $M^2$ are isomorphic.
\end{theorem}
The additional assumptions in \Cref{thm:mainresult}, compared to \cite[Theorem 1.6]{Go11}, are that reduced spaces are symplectic rational surfaces  and the restriction on interior fixed surfaces.  However, we dropped the assumption of \cite[Theorem 1.6]{Go11} that the fixed point sets at each critical
level are either surfaces or isolated fixed points; we allow the extrema to be four-dimensional. We note that in our counter example, \Cref{examp:main}, 
all the theorem's assumptions except for the restriction on the interior fixed surfaces hold. 
 \begin{proof}[Proof of \Cref{thm:mainresult}, assuming 
  \Cref{thm:extending-g}]
In either case (i) or (ii) or (iii), we find $\eps>0$ and an isomorphism $$f \colon \mu_1^{-1}((\lambda_S-\eps,\lambda_S+\eps)) \to \mu_2^{-1}((\lambda_S-\eps,\lambda_S+\eps))$$
of open sets in $(M^1,\omega^1,\mu_1)$ and $(M^2,\omega^2,\mu_2)$. 
This is clear by assumption in case (iii), is by \cite[Lemma 3.4]{Mc09} in case (ii), and by \cite[Theorem 13.1]{GS89} whenever $\lambda_S$ is simple.\\

    In any case, it is enough to extend the isomorphism iteratively over the critical values of $\mu_i$ above $\lambda_S$ to an isomorphism
    \[
    \mu_1^{-1}((\lambda_S-\eps,\infty))\to \mu_2^{-1}((\lambda_S-\eps,\infty)).
    \]
    This is since extending the isomorphism over the critical values of $\mu_i$ below $\lambda_S$, if they exist, amounts to extending $f$ as an isomorphism 
    $$(-\mu_1)^{-1}((-\lambda_S-\eps,-\lambda_S+\eps)) \to (-\mu_2)^{-1}((-\lambda_S-\eps,-\lambda_S+\eps))$$
    of open sets in $(M^1,-\omega^1,-\mu_1)$ and $(M^2,-\omega^2,-\mu_2)$
    over the critical values of $-\mu_i$ above $-\lambda_S$ to an isomorphism 
   \[
    (-\mu_1)^{-1}((-\lambda_S-\eps,\infty))\to (-\mu_2)^{-1}((-\lambda_S-\eps,\infty)).
    \]

  So let $\lambda>\lambda_S$ be a critical value such that there is no critical value in $(\lambda_S,\lambda)$. By 
    \Cref{thm:extending-g},
    we find $\delta>0$ and an isomorphism
    \[
     \mu_1^{-1}((\lambda_S-\eps,\lambda+\delta))\to \mu_2^{-1}((\lambda_S-\eps,\lambda+\delta))
    \]
    extending the isomorphism $f$.
    If $\lambda$ is maximal, we are done. If $\lambda$ is not maximal, we let $\lambda'$ be a critical value such that there is no critical value in $(\lambda,\lambda')$ and apply \Cref{thm:extending-g} to extend the isomorphism to $\mu_1^{-1}((\lambda_S-\eps,\lambda'+\delta'))\to \mu_2^{-1}((\lambda_S-\eps,\lambda'+\delta'))$ with $\delta'>0$. We repeat this argument till we reach the maximal value. 
    \end{proof}



 \subsection{Application to Cho's classification of positive monotone semi-free Hamiltonian $S^1$-manifolds}
 Gonzales' results were pivotal in Cho's classification 
 of six-dimensional positive monotone symplectic manifolds admitting semi-free Hamiltonian circle actions. 
 A compact symplectic manifold $(M,\omega)$ is called \textbf{positive monotone} if the cohomology class $[\omega]$ is a multiple by a positive real number of the first Chern class of $TM$ with respect to an almost complex structure compatible with $\omega$.
A positive monotone symplectic manifold is the symplectic analogue of a \textbf{Fano manifold}: a compact complex manifold $X$ whose anticanonical line bundle $K_X^{-1}$ is ample.
The ampleness of $K_X^{-1}$ means that there is a holomorphic embedding
$ i \colon X \hookrightarrow \mathbb{C}P^N $  such that $(K_X^{-1})^k=i^* \mathcal{O} (1)$ for some $N>0$ and $k>0$.
The almost complex structure induced 
by the complex analytic atlas on $X$ is compatible with the symplectic form $i^*(\omega_{FS})$.
Since $c_1(TX)=c_1(K_X^{-1})$ and $c_1(i^* \mathcal{O} (1))=[i^*(\omega_{FS})]$,  the symplectic manifold $(X, i^*(\omega_{FS}))$ is positive monotone. 

In dimensions two and four, it was proven that a  positive monotone symplectic manifold is symplectomorphic to a Fano manifold (with a positive multiple of $i^{*}\omega_{FS}$) \cite{Gr85, Mc90, Ta00}.
In dimension greater than or equal to twelve, there are examples of positive monotone symplectic manifolds that are not simply connected \cite{FP10}. 
Since Fano manifolds are simply connected \cite[Corollary 6.2.18]{IP99}, 
these examples are not even homotopy equivalent to Fano manifolds. 
In dimensions six, eight, and ten, it is not known if any positive monotone symplectic manifold is diffeomorphic, or homotopy equivalent, to a Fano manifold.
However, if the {\bf complexity} $\frac{1}{2} \dim M-\dim T$ of a positive monotone Hamiltonian $T$-space is $0$, then it
is equivariantly symplectomorphic to a Fano manifold with a holomorphic torus action, as follows from \cite{De88}.
In higher complexity the question is still open.


\begin{conjecture}Fine-Panov 2015 \cite{FP15}.
Let $(M, \omega)$ be a positive monotone symplectic manifold of dimension six that admits a Hamiltonian circle action.
Then $M$ is diffeomorphic to a Fano manifold.
\end{conjecture}







  In \cite{Ch19}, \cite{Ch21.1} and \cite{Ch21.2}, Cho classified the so-called 'topological fixed point data' of {positive monotone} semi-free Hamiltonian $S^1$-spaces of dimension six. Cho showed that these data determine the fixed point data as in \Cref{def:fixedpointdata}, and then used  \cite[Theorem 1.5]{Go11} in order to conclude that all of these spaces  are isomorphic as Hamiltonian $S^1$-manifolds to Fano manifolds with holomorphic $S^1$-actions. 
   The fact that \cite[Theorem 1.5]{Go11} is not correct, as we show in \Cref{examp:main}, raises question on the validity of Cho's result.
    Nevertheless, we deduce from \Cref{thm:mainresult} that in the examples that occur in Cho's classification, the fixed point data \textbf{do} determine the isomorphism type of the underlying Hamiltonian $S^1$-manifold. \\


The key is the implication of the positive monotone assumption on the distribution of fixed point components.
We assume that the positive monotone symplectic manifold 
is \textbf{normalized}, i.e., $[\omega]=c_1(TM)$.
For a normalized positive monotone Hamiltonian $S^1$-space,  there is a momentum map
$\mu \colon M \rightarrow \R$ such that 
$$\mu(p)=-(\alpha^1_p+\alpha^2_p+\alpha^3_p)$$ for any fixed point $p$, where the $\alpha^i_p$ 
are the weights of the $T$-representation 
on the tangent space $T_pM$ \cite[Proposition 3.5]{CSS23}. 
Combining with the local normal form for a semi-free Hamiltonian $S^1$-action in dimension six, recalled in \Cref{nt:local6}, we conclude the following lemma.
    \begin{lemma} \label{lem:keym}
        Let $M$ be a normalized positive monotone semi-free Hamiltonian $S^1$-manifold of dimension six.
        Then \begin{itemize}
        \item all non-extremal fixed point components of dimension zero are located at level $\pm 1$;
        \item there are at most two critical values larger than $0$;
        \item all non-extremal fixed point components of dimension two are located at level $0$ and have the same index.
    \end{itemize}
    \end{lemma}

 We will also use the fact that rigidity holds for a big family of symplectic manifolds in dimension four. The next theorem is a collection of many results, see (\cite{Gr85}, \cite{AM00}, \cite{LP04}, \cite{Pin08}, \cite{Ev11},  \cite{LLW15}).
    \begin{theorem}\label{thm:rigid}
        Let $(B,\{\omega_t\}_{t \in I})$ be $S^2\times S^2$ or a $k$-fold blowup of $\C \PP^2$ with $0\leq k\leq 4$, endowed with a family of symplectic forms smoothly parametrized by $t$. Then $(B,\{\omega_t\}_{t \in I})$ is rigid.
    \end{theorem}
    We deduce that Cho's theorem \cite[Theorem 1.2]{Ch19} still holds. 

\begin{theorem} \cite[Theorem 1.2]{Ch19}.
    Any  positive monotone, compact,  connected six-dimensional symplectic manifold $M$ with a semi-free Hamiltonian $S^1$-action is equivariantly symplectomorphic to a Fano manifold $M'$ with a positive multiple of $i^{*}\omega_{FS}$ and a Hamiltonian $S^1$-action induced from a holomorphic $\C^*$-action.
\end{theorem}
\begin{proof}
    By \cite[Section 6,7,8]{Ch19}, given a positive monotone, compact, connected six-dimensional symplectic manifold $M$ with a semi-free Hamiltonian $S^1$-action, there is a Fano manifold $M'$ with a positive multiple of $i^{*}\omega_{FS}$ and a Hamiltonian $S^1$-action induced from a holomorphic $\C^{*}$-action such that $M$ and $M'$  have the same {topological fixed point data}, as defined in \cite[Definition 5.7]{Ch19}. Moreover, the topological fixed point data already determine the fixed point data (see \cite[Lemma 9.7]{Ch19} and the proof of \cite[Theorem 1.2]{Ch19}). If, in Cho's notation, $M$ is of type \textbf{(II-1-4.$k$)} with $k\geq 5$, then the proof of \cite[Theorem 1.2]{Ch19} shows that $M$ and $M'$ are isomorphic without using the result of Gonzales.

    If $M$ is not of type \textbf{(II-1-4.$k$)} with $k\geq 5$, then each four-dimensional reduced space of $M$ is either $S^2\times S^2$ or an $m$-fold blowup of $\C \PP^2$ with $0\leq m\leq 4$ (see the statement right after \cite[Theorem 9.1]{Ch19}). It remains to check that $M$ and $M'$ satisfy the assumptions needed to apply \Cref{thm:mainresult}, since then $M$ and $M'$ would be equivariantly symplectomorphic.
    Indeed, that the rigidity assumption on $M$ (or $M'$) holds follows from \Cref{thm:rigid}; the fact that all fixed surfaces not corresponding to an extremal critical value are mapped to the same value $\lambda_S$ is by \Cref{lem:keym}. 
\end{proof}





{\bf The structure of the paper.} 
In \Cref{sec:examples}, we construct two counter examples showing that \cite[Theorem 1.5]{Go11} and \cite[Lemma 3.13]{Go11} are incorrect as stated. We then proceed towards proving \Cref{thm:extending-g}.  In \Cref{sec:pre} we describe the effect on the smooth and symplectic structures on the reduced spaces when 'flowing into' a critical level by the map induced from the gradient flow of the momentum map. In \Cref{sec:almostsymplectic} we describe piecing  together of isomorphisms, and, for that, introduce the notion of almost symplectic $\mu-S^1$-diffeomorphism. In \Cref{sec:neighborhoods} we establish the implications
of having the same $*$-small fixed point data on isomorphisms of neighborhoods of critical
levels, assuming that reduced spaces of dimension four are symplectic rational surfaces. Finally, in \Cref{sec:extend} we prove the theorem.
In general, we try to avoid repetition of Gonzales' arguments and proofs, but we fill in details when they are required. 

