\section{Preliminaries: the Morse flow}\label{sec:pre}
We describe the map from a reduced space at a regular value to a reduced space at a non-extremal critical value above it, induced from the flow of the gradient vector field of the momentum map w.r.t.\ an invariant metric. We call it the Morse flow. It will play an important role in extending an isomorphism beyond a non-extremal critical level.\\

 Let $(M,\omega,\mu)$ be a connected, semi-free Hamiltonian $S^1$-manifold. Assume that $\mu$ is proper and its image is bounded.


\begin{noTitle}\label{nt:morse1}
     Let $\lambda$ be a critical value of the momentum map $\mu$. Let $\eps>0$ be such that there is no critical value in $[\lambda-\eps,\lambda)$. The normalized flow $\Phi_t$ of the gradient vector field of $\mu$ with respect to some invariant metric gives an equivariant diffeomorphism
     \begin{equation} \label{eq:phiti}
     \mu^{-1}(\lambda-\eps)\times [\lambda-\eps,\lambda)\to \mu^{-1}([\lambda-\eps,\lambda)), \quad (p,t)\mapsto \Phi_t(p)
     \end{equation}
     under which $\mu$ pulls back to $
     (p,t)\mapsto t.$  

     Choosing a different invariant metric does not change the equivariant isotopy type of the  equivariant diffeomorphism \eqref{eq:phiti}.
\end{noTitle}  

To define the Morse flow, we first review the implications of the local normal form for a Hamiltonian $S^1$-action in case  the action is semi-free and the manifold is of dimension six. 
Recall that we use the convention that the \textbf{index} of $\mu$ at a fixed point is the number of negative weights \footnote{This convention differs from that of \cite{Go11}, where the index is the usual index of a Morse-Bott function, that is, double our index.}. The {\bf co-index} is the number of positive weights.


\begin{noTitle}\label{nt:localnormalform}{\bf Local normal form for a Hamiltonian $S^1$-action on $(M^{2n},\omega)$.} For an integer $w$, denote by $\C_w$ the $S^1$-representation $\chi$ on $\C$ given by $\chi(t)(z)=t^w\cdot z$. By the local normal form theorem for Hamiltonian group actions, there is a local chart around any fixed point $p$ given by $n$ complex coordinates $(z_1,\hdots,z_n)$ defined on a suitably small ball ${\ball}^{2n} \subset \C^n$ centered at the origin, and $n$ integers $w_1,\hdots,w_n$ called \textbf{the weights of the action at $p$}, such that the pullback of the $S^1$-action is given by
       \[
      {\ball}^{2n}\subset \C_{w_1}\oplus \hdots \oplus \C_{w_n},
      \]
the pullback of $\omega$ is given by the standard form on  
 ${\ball}^{2n}$, and the pullback of the momentum map is the corresponding standard momentum map of said representation, up to adding a constant.
      \end{noTitle} 



      \begin{noTitle}\label{nt:local6}{\bf Local normal form for a semi-free Hamiltonian $S^1$-action on $(M^6,\omega)$.}
      Using the local normal form, we see that for an effective Hamiltonian circle action in dimension six, fixed point components are symplectic submanifolds of dimension $0$, $2$, or $4$.
      If the action is semi-free, weights can only be $-1$, $0$ or $1$. We list the possible triples of weights, up to ordering.
      \begin{itemize}
          \item For isolated fixed points, the weights are $(1,1,1)$ for a minimal, $(-1,-1,-1)$ for a maximal, or $\pm (1,1,-1)$ for a non-extremal fixed point.
          \item For fixed surfaces, the weights are either $\pm (0,1,1)$ corresponding to an extremal fixed point, or $\pm (0,1,-1)$ corresponding to non-extremal fixed points.
          \item For fixed four-manifolds, the weights are given by $\pm(0,0,1)$. In particular, a fixed four-manifold is always extremal.
      \end{itemize}
      \end{noTitle}

   In the rest of the section, $\lambda$ is a non-extremal critical value and $M$ is of dimension six.
\begin{noTitle}\label{rem:criticalvalue}
Since $\mu$ is a Morse-Bott function, for a fixed point component $C$ at the level $\lambda$, we can describe the corresponding \textbf{stable submanifold}, defined by
$$\{p\in M \,|\, \lim_{t \to \infty} \Phi_{t}(p) \in C\}.$$
Consider an isolated fixed point $p$ with index $1$ and the local normal form ${\ball}^6\subset \C_{-1}\oplus \C_{1}\oplus \C_1$, with the standard momentum map
    $$(z_1,z_2,z_3) \mapsto -|z_1|^2+|z_2|^2+|z_3|^2$$
    and the standard metric $g$, around it.
    The time-$T$-flow $\Phi_T$ beginning in $\mu^{-1}(\lambda-\eps)\cap {\ball}^6$, $T\geq \eps$, is well-defined in
    $$U:={\ball}^6\cap (\mu^{-1}(\lambda-\eps)\smallsetminus \{\mu^{-1}(\lambda-\eps)\cap (\C_{-1}\oplus \{0\}\oplus \{0\})\}).$$
    We define $f_{\Morse}(\eps)\colon {\ball}^6\cap \mu^{-1}(\lambda-\eps)\to {\ball}^6\cap \mu^{-1}(\lambda)$ by $\Phi_{\eps}$ on $U$ and by $z\mapsto p$ on $\C_{-1}\oplus \{0\}\oplus \{0\}$.\\
    In other words, we define $f_{\Morse}(\eps)$ as the limit of $\Phi_{\delta}$ as $\delta$ goes to $\eps$. This converges uniformly, since for all $p$ in the domain, $d(\Phi_{\delta}(p),f_{\Morse}(\eps)(p))\leq \eps-\delta$, where $d$ is the metric on $M$ defined by geodesic distance with respect to $g$. Therefore $f_{\Morse}(\eps)$ is continuous and clearly equivariant.


    Similarly, for an isolated fixed point $p$ with index $2$, and the local normal form ${\ball}^{6} \subset \C_{-1}\oplus \C_{-1}\oplus \C_1$, with the standard momentum map
    $$(z_1,z_2,z_3) \mapsto -|z_1|^2-|z_2|^2+|z_3|^2$$
    and the standard metric $g$, around it,
    we set 
     $$U:={\ball}^6\cap (\mu^{-1}(\lambda-\eps)\smallsetminus \{\mu^{-1}(\lambda-\eps)\cap (\C_{-1}\oplus \C_{-1} \oplus \{0\})\}).$$
    We define $f_{\Morse}(\eps)\colon {\ball}^6\cap \mu^{-1}(\lambda-\eps)\to {\ball}^6\cap \mu^{-1}(\lambda)$ by $\Phi_{\eps}$ on $U$ and by $z\mapsto p$ on $\C_{-1}\oplus \C_{-1} \oplus \{0\}$. 
    Again, $f_{\Morse}(\eps)$ is continuous and equivariant.\\

    In case there is a fixed surface $\Sigma$ at $\lambda$, an explicit description like that is not possible anymore. But here, by \cite[Proposition 3.2]{AB95}, the unstable submanifold belonging to $\Sigma$ is indeed a smooth submanifold. This is necessarily $S^1$-invariant if the metric is. In fact, if there is a symplectic $G$-action on a neighborhood of $\Sigma$, for any compact Lie group $G$, then the unstable submanifold is also (locally) $G$-invariant. Further, the map $u(\Sigma)\colon \mathcal{U}(\Sigma)\to \Sigma$ mapping a point to the limit of its flow under $\Phi$ is smooth and defines a fiber bundle near $\Sigma$ whose fiber is a ball of dimension twice the index of $\Sigma$; the fiberwise $S^1$-action gives a fiberwise complex structure on that bundle.\\
    In our case, the fiber is of dimension two, so we call this bundle the \textbf{negative normal bundle}; similarly, we define the positive normal bundle.
    In both cases, we define $e({\Sigma})_-$ resp.\ $e(\Sigma)_+$ to be the Euler class of the negative resp.\ positive normal bundle of $\Sigma$.
    The intersection $S_{-\eps}$ of $\mathcal{U}(\Sigma)$ with a level set $\lambda-\eps$ is then an $S^1$-bundle over $\Sigma$, so that its orbit space $S_{-\eps}/S^1$ is diffeomorphic to $\Sigma$. A diffeomorphism is given by restricting $u(\Sigma)$ to $S_{-\eps}/S^1$, so that $S_{-\eps}/S^1$ is a symplectic submanifold of $M_{\lambda-\eps}$ for $\eps$ small enough. Note that then $e(\Sigma)_-$ pulls back to the restriction of the Euler class of $S^1\to \mu^{-1}({\lambda-\eps})\to M_{\lambda-\eps}$ to $\Sigma_{-\eps}$ under $\Sigma_{-\eps}\to \Sigma$.\\
    For the same reasons as above, we can define (near $\Sigma$) the continuous, equivariant map $f_{\Morse}(\eps)\colon \mu^{-1}({\lambda-\eps})\to \mu^{-1}(\lambda)$ to be the limit of $\Phi_{\delta}$ as $\delta$ goes to $\eps$.\\

    All in all, for a choice of metric that, near the fixed components, is as specified above and $\eps>0$ small enough, we get a well-defined, equivariant continuous map 
    by    
    \begin{equation} \label{eq:morse}
         f_{\Morse}=f_{\Morse}(\eps)\colon \mu^{-1}({\lambda-\eps})\to \mu^{-1}({\lambda}), \quad f_{\Morse}(p)=\lim\limits_{\delta \to \eps_-} \Phi_{\delta}(p).
    \end{equation}
    We call this map the {\bf Morse flow}. Since this map is equivariant, it descends to a continuous map $M_{\lambda-\eps}\to M_{\lambda}$ that we will also call $f_{\Morse}$.\\
    For a fixed point of index $1$ considered to be in $M_{\lambda}$, the preimage under $f_{\Morse}(\eps)$ in $M_{\lambda-\eps}$ is a point, whereas for a fixed point $p$ of index $2$, the preimage in $M_{\lambda-\eps}$ is an embedded symplectic 2-sphere $S_{-\eps}$ of size $\eps$ and self-intersection $-1$. 
    As the preimages of different points, the spheres corresponding to the fixed points of index $2$ are pairwise disjoint.
    The preimage of a fixed surface $\Sigma\subset M_{\lambda}$ is an embedded symplectic surface $\Sigma_{-\eps}$ of the same genus. 
    \end{noTitle}

\begin{Notation}\label{not:FF'}
    Denote by $F$ the set of fixed points in $M_{\lambda}$, by $F_{\iso}$ its subset of isolated fixed points, and by $F_{\iso, 2}$ its subset of isolated fixed points of index $2$. 
Denote by $F'$, $F'_{\iso}$ and $F'_{\iso,2}$ the preimages of $F$, $F_{\iso}$ and $F_{\iso,2}$ in $M_{\lambda-\eps}$ under $f_{\Morse}(\eps)$.
\end{Notation}


Since the restriction of $f_{\Morse}$ to $M_{\lambda-\eps}\smallsetminus F'$ coincides with the gradient flow $\Phi_t$ of $\mu$, we get the following corollary.
\begin{corollary}\label{cor:restdiffeo}
    The restriction of $f_{\Morse}(\eps)$ to $M_{\lambda-\eps}\smallsetminus F'$ induces a diffeomorphism
      \begin{equation} \label{eq:morsediffeo}
        M_{\lambda-\eps}\smallsetminus F'\hookrightarrow M_{\lambda}\smallsetminus F.
    \end{equation}
\end{corollary}

Moreover, the definition of $f_{\Morse}$ also implies the following corollary.


\begin{corollary}\label{cor:reshomeo}
The restrictions of $f_{\Morse}(\eps)$ to $M_{\lambda-\eps}\smallsetminus F'_{\iso}$ and to $M_{\lambda-\eps}\smallsetminus F'_{\iso,2}$ induce homeomorphisms 
     \begin{equation} \label{eq:morsehomeo1}
        M_{\lambda-\eps}\smallsetminus F'_{\iso}\to M_{\lambda}\smallsetminus F_{\iso}
    \end{equation}
    and
    \begin{equation} \label{eq:morsehomeo}
        M_{\lambda-\eps}\smallsetminus F'_{\iso,2}\to M_{\lambda}\smallsetminus F_{\iso,2}.
    \end{equation}
\end{corollary}

\begin{proof}
It is clear that the maps are bijective and continuous.
    The inverse restricted to $M_{\lambda}\smallsetminus F$ is continuous since  \eqref{eq:morsediffeo} is a diffeomorphism. Moreover, for a small open neighborhood $U=U'_{\iso}$ or $U'=U'_{\iso,2}$ around $F'_{\iso}$ and $F'_{\iso,2}$, resp., the restriction of $f_{\Morse}(\eps)$ to $M_{\lambda-\eps}\smallsetminus U' \to M_{\lambda}\smallsetminus f_{\Morse}(\eps)(U')$
    is a bijective, continuous map from a compact space into a Hausdorff space, hence a homeomorphism. In particular the inverse of  each of the maps \eqref{eq:morsehomeo1} and \eqref{eq:morsehomeo} is continuous at each point in $F \smallsetminus F_{\iso}$ and in  $F \smallsetminus F_{\iso,2}$, respectively.
\end{proof}
    We call the topological connected sum of a topological manifold $M$ of dimension four with $\overline{\C\PP}^2$ the \textbf{blowup in the topological category} at a point. 
    The following claim is immediate from the definitions.
    \begin{claim}\label{cl:top-bup}
     The Morse flow $f_{\Morse} \colon M_{\lambda-\eps} \to M_{\lambda}$ induced by  \eqref{eq:morse} 
      coincides in the topological category with the map $M_{\lambda-\eps} \to M_{\lambda}$ of the blowup at the isolated fixed points of co-index $1$. 
      \end{claim}

    \begin{remark} 
    The definition and properties of $f_{\Morse}$ presented above 
    still hold if we let $\mu$ be an $S^1$-invariant Morse-Bott function whose critical set is precisely the set of $S^1$-fixed points and assume that in a neighborhood of the fixed point set, $\mu$ is a momentum map for the $S^1$-action on $(M,\omega)$. Of course, $M_t$ is to be understood as the 'reduced space' with respect to the Morse-Bott function $\mu$. 
    To justify this, we note that for a critical level $\lambda$ of $\mu$, $M_{\lambda}$ can still be given a smooth structure using the same arguments as for an actual momentum map. This is because $M_{\lambda}\smallsetminus F$ is clearly smooth, and $\mu$ is a momentum map near $F$.
\end{remark}


     Note that $f_{\Morse}(\eps) \colon M_{\lambda-\eps} \to M_{\lambda}$ is orientation-preserving w.r.t.\ the orientation induced by the symplectic forms $\omega_{\lambda-\eps}$ and $\omega_{\lambda}$.
      We will further look at the effect of the Morse flow on the symplectic form in case $\mu$ is a momentum map. First we strengthen \Cref{cor:restdiffeo}; again, this is since the
   restriction of $f_{\Morse}$ to $M_{\lambda-\eps}\smallsetminus F'$ coincides with the gradient flow of the momentum map.

\begin{corollary}\label{cor:restdiffeo1}
For the diffeomorphism \eqref{eq:morsediffeo} induced by the
   restriction of $f_{\Morse}(\eps)$ to $M_{\lambda-\eps}\smallsetminus F'$, the form $(f_{\Morse}(\eps)|_{M_{\lambda-\eps}\smallsetminus F'})_{*}{\omega_{\lambda-\eps}}$, as a form on $M_{\lambda}\smallsetminus F$, converges to $\omega_{\lambda}$ as $\eps$ goes to $0$.

       In particular, 
        the symplectic volume of $(M_{\lambda-\eps},\omega_{\lambda-\eps})$ approaches that of $(M_{\lambda},\omega_{\lambda})$ as $\eps$ approaches $0$.

\end{corollary}



   Next, recall that the Morse flow $f_{\Morse}(\eps)$ is a homeomorphism onto its image $M_{\lambda} \smallsetminus F_{\iso,2}$ when restricted to $M_{\lambda-\eps}\smallsetminus F'_{\iso,2}$, by \Cref{cor:reshomeo}. We will also use the following fact, which is a simple application of Stokes.
   \begin{lemma}\label{lem:volumedisk}
       Let $B$ be a closed symplectic ball of radius $\delta$ in $\C^2$, that is, the set $\{(z_1,z_2)\in \C^2\colon |z_1|^2+|z_2|^2\leq \delta^2\}$ endowed with the standard symplectic form $\omega$. Then for any smooth embedding $\iota\colon D^2\to B$ such that $\partial D^2\subset \partial B$ is an orbit of the diagonal $S^1$-action, we have that $\int_{D^2}\iota^*\omega=\pm \pi\delta^2$.
   \end{lemma}
        \begin{lemma}\label{lem:cohomologyconverges}
           The class $(f_{\Morse}|_{M_{\lambda-\eps}\smallsetminus F'_{\iso,2}})_{*}[\omega_{\lambda-\eps}]$ converges to $[\omega_{\lambda}]$ on $M_{\lambda} \smallsetminus F_{\iso,2}$ as $\eps$ goes to $0$.
        \end{lemma}
\begin{proof}
For a primitive homology class $A$ in $H_2(M_{\lambda}\smallsetminus F_{\iso,2})$, and $t \in (\lambda-\eps,\lambda)$, denote by $A_t$ the preimage of $A$  under  $$f_{\Morse}\colon M_t\smallsetminus F'_{\iso,2}\to M_\lambda\smallsetminus F_{\iso,2}.$$
We will show that  as $t<\lambda$ goes to $\lambda$, the evaluation $\omega_t(A_t)$ goes to $\omega_{\lambda}(A)$.

As a primitive homology class in $H_2(M_{\lambda}\smallsetminus F_{\iso,2})$, the class $A$ is represented by an immersed sphere $\iota_A(S^2)$. Up to homotopy, $\iota_A$ is transverse to $F$ (see \cite[Theorem 2.4]{MH76}). In particular, $\iota_A(S^2)$ is disjoint from the isolated fixed points and meeting the fixed surfaces only a finite number of times in $m$ distinct points $p_1,\hdots,p_m$. For $\delta>0$ small enough, there exists an embedding of $m$ disjoint, closed balls $\mathcal{B}_i$, all of radius $\delta/\sqrt{\pi}$, such that $p_i$ is only contained in $\mathcal{B}_i$ and $\mathcal{B}_i \cap \iota_A(S^2)$ is a disk, implying that $\partial \mathcal{B}_{i} \cap \iota_A(S^2) \cong S^1$ is the unknot in $\partial \mathcal{B}_i\cong S^3$. Therefore, up to isotopy, we may assume that $\partial \mathcal{B}_{i} \cap \iota_A(S^2)$ is an orbit of the diagonal $S^1$-action on $S^3$. We denote by $\mathcal{D}_i\subset S^2$ the preimage of $\mathcal{B}_i\cap\iota_A(S^2)$ under $\iota_A$.\\
 For $\mathcal{B}:= \mathcal{B}_1\cup \hdots \cup \mathcal{B}_m$, we then have
    $$\int\limits_{A\smallsetminus \mathcal{B}} \omega_{\lambda}\in [\omega_{\lambda}(A)-m\delta^2,\omega_{\lambda}(A)+m\delta^2]$$
    by \Cref{lem:volumedisk}.
    For $t\in (\lambda-\eps,\lambda)$, denote by $\mathcal{B}^t,\mathcal{B}^t_i$ the preimage of $\mathcal{B},\mathcal{B}_i$ under
    $$f_{\Morse}\colon M_t\smallsetminus F'_{\iso,2}\to M_\lambda\smallsetminus F_{\iso,2}.$$
    Denote by $\iota_{A_t}=f_{\Morse}^{-1}\circ \iota_A\colon S^2\to M_t$ the induced map. This might not be smooth near $f_{\Morse}^{-1}(\{p_1,\hdots,p_m\})$, but we may 
    redefine $\iota_{A_t}$ by replacing $(\iota_{A_t})_{|\mathcal{D}_i}\colon \mathcal{D}_i\to \mathcal{B}^t_i$ with a smooth embedding $j_i\colon \mathcal{D}_i\to 
    \mathcal{B}^t_i$ such that $j_i=\iota_{A_t}$ near $\partial \mathcal{D}_i$; this is possible because $\iota_{A_t}(\partial \mathcal{D}_i)$ is the unknot in $\partial 
    \mathcal{B}^t_i$. Since $j_i$ and $(\iota_{A_t})_{|\mathcal{D}_i}$ are certainly homotopic rel boundary, we do not change $\omega_t([\iota_{A_t}(S^2)])$ when doing so.\\
    Also, we may again assume that $\iota_{A_t}(\partial \mathcal{D}_i)$ is an $S^1$-orbit of the diagonal action on $S^3$.\\

    Then, in $M_t$, for $t \in (\lambda-\eps,\lambda)$ with $\eps$ small enough, $\mathcal{B}_t$ is contained in a symplectic ball of radius $2\delta/\sqrt{\pi}$, so the symplectic volume of $\mathcal{B}_t\cap A_t$ with respect to $\omega_t$ is in $[-4m\delta^2,4m\delta^2]$ by \Cref{lem:volumedisk}. This implies that $\int\limits_{A_t\smallsetminus \mathcal{B}_t} \omega_t$ is in $[\omega_t(A_t)-4m\delta^2,\omega_t(A_t)+4m\delta^2]$. We now have
    \begin{equation}\label{eq:limit}
        \lim\limits_{t\to \lambda} \int\limits_{A_t\smallsetminus \mathcal{B}_t} \omega_t=
    \int\limits_{A\smallsetminus \mathcal{B}} \omega_{\lambda},
    \end{equation}
    because of 
    \Cref{cor:restdiffeo1}.
    Therefore, if $\omega_t(A_t)$ did not approach $\omega_{\lambda}(A)$, then we could choose $\delta$ and $\theta>0$ small enough such that
    $$[\omega_{\lambda}(A)-m\delta^2,\omega_{\lambda}(A)+m\delta^2] \cap [\omega_t(A_t)-4m\delta^2,\omega_t(A_t)+4m\delta^2]=\emptyset$$
    whenever $t\in (\lambda-\theta,\lambda)$, contradicting \cref{eq:limit}.
\end{proof}    


         A similar statement to
         \Cref{lem:cohomologyconverges} with index $1$ replacing co-index $1$ 
         holds for $(M_{\lambda+\eps},\omega_{\lambda+\eps})$.




\begin{Notation}\label{not:elambda}

We denote by $e(P_t)\in H^2(M_t;\Z)$ the Euler class of the principal $S^1$-bundle $S^1\to P_t\to M_t$. The equivariant diffeomorphism  \eqref{eq:phiti} gives an identification of $e(P_{t_0})$ and $e(P_{t_1})$ for $t_0,t_1\in [\lambda-\eps,\lambda)$ independent of the metric chosen, allowing us to write $e(P)$ for $e(P_t)$ when it is clear in which interval of regular values $t$ is contained.

The 'Euler class' $e_-$ at $M_{\lambda}$ is defined as follows: 
First, the pushforward of the usual Euler class $e(P_{\lambda-\eps})$ as a class on $M_{\lambda-\eps} \smallsetminus F'_{\iso}$ by the homeomorphism \eqref{eq:morsehomeo1} 
 is a class $\tilde{e}(P_{\lambda})$ in $H^{2}(M_{\lambda}\smallsetminus F_{\iso};\Z)$.
 Now, the inclusion $M_{\lambda}\smallsetminus F_{\iso}\hookrightarrow M_{\lambda}$ induces an isomorphism in the second cohomology groups, so we define $e_-$  to be the image of $\tilde{e}(P_{\lambda})$ under that isomorphism.\\
That way, it is clear that the restriction of $e(P^{-}_{\lambda})$ to $M_{\lambda}\smallsetminus F$ is the actual Euler class of the principal bundle $S^1\to P_{\lambda}\smallsetminus F \to M_{\lambda}\smallsetminus F$.\\
Similarly, replacing $M_{\lambda-\eps}$ with $M_{\lambda+\eps}$, we can define $e_+$. In general, $e_-\neq e_+$.
\end{Notation}





\section{Almost symplectic $\mu-S^1$-diffeomorphisms of free Hamiltonian $S^1$-manifolds}\label{sec:almostsymplectic} 

In the proof of \Cref{thm:extending-g}, we will piece an isomorphism below a critical level with an isomorphism of 
neighborhoods of the critical level. 
In this section, we describe this operation. We will also use piecing of isomorphisms to show that the rigidity assumption allows to extend an equivariant symplectomorphism below a critical level to arbitrarily close to the critical level. 

The result of piecing together equivariant symplectomorphisms might no longer be an equivariant symplectomorphism. 
However, we will show that it is an almost symplectic $\mu-S^1$-diffeomorphism. 
Recall that a {\bf $\mu-S^1$-diffeomorphism} is an equivariant diffeomorphism that respects the momentum maps. 

\begin{definition}
We call a diffeomorphism $\psi$ from a symplectic manifold $(X,\omega^{X})$ to a symplectic manifold $(Y,\omega^{Y})$ \textbf{almost symplectic} if $\psi^*{\omega^Y}$ and $\omega^X$ are \emph{isotopic} under the standard homotopy
\begin{equation*}\label{eq:omegas}
\omega(s):=s \psi^*{\omega^Y}+(1-s){\omega^X}, \,\,\,s\in [0,1].
\end{equation*}
That is, all $\omega(s)$ are symplectic forms that represent 
the cohomology class $[\omega^X]$ in 
$H^2(X;\R)$.
\end{definition}
\begin{remark}\label{rem:almostsymplecticopen}
   We will use frequently that the non-degeneracy of $\omega(s):=s \psi^*{\omega^Y}+(1-s){\omega^X}$ is an open condition in the following sense: if $\omega^X_t$, $\omega^Y_t$ and $\psi^t$ are smooth paths with $\omega^X_0=\omega^X$, $\omega^Y_0=\omega^Y$ and $\psi^0=\psi$, then there is $\eps>0$ such that ${\psi^s}^{*}{\omega^Y_{s'}}$ and $\omega^X_{s''}$ are isotopic under the standard homotopy, provided that $|s|,|s'|,|s''|<\eps$.

   That is to say, working with almost symplectic diffeomorphisms as opposed to symplectomorphisms gives us more flexibility. This will be more concrete in the next lemmata.
\end{remark}



Since the piecing of the isomorphisms will take place at a regular level, we first study almost symplectic $\mu-S^1$-diffeomorphisms
between \emph{free} Hamiltonian $S^1$-manifolds with proper momentum maps. 
Recall the notation $P_t,\,M_t,\,e(P_t),e(P)$ from Notations \ref{not:semifreeHamiltonian} and \ref{not:elambda}. 
\begin{Notation}
    For any $\mu-S^1$-diffeomorphism $f$ on $S^1 \acts (M,\mu)$ (into $M$ or another Hamiltonian $S^1$-manifold), we denote by $f^t$ the map it induces on $P_t$, and by $f_t$ the map it induces on $M_t$.
\end{Notation}

Let $(M,\omega=\omega^M,\mu=\mu_M)$ be a connected Hamiltonian $S^1$-manifold; assume that 
the circle action is {free} and the 
momentum map is a proper surjective map $\mu\colon M \to [0,1]$. Through this section, as in \eqref{eq:phiti}, we use the flow of the gradient vector field of the momentum map (w.r.t.\ some invariant metric) to identify $M\cong P_0\times [0,1]$ as $S^1$-manifolds such that the momentum map becomes projection onto the $[0,1]$-factor.
Recall the Duistermaat-Heckman formula
\begin{equation}\label{eq:dh}
[\omega_t]=[\omega_{t'}]+(t-t')e(P),
    \end{equation}
where $t,t'$ are abritrary values in $[0,1]$.\\


By \cite[Section 2]{GS89}, for each $t\in [0,1]$ there is $\delta>0$  and a one-form $\alpha^M$ that is a connection on the principal $S^1$-bundle $S^1\to P_t\to M_t$ such that $\mu^{-1}((t-\delta,t+\delta))$ is isomorphic to 
\begin{equation}\label{Udelta}
U=U_{\delta}:=P_t\times (t-\delta,t+\delta)
\end{equation}
endowed with the symplectic form 
\begin{equation}\label{omegaU}
\omega^{U,M}=(\omega_t+(t'-t)d\alpha^M)+\alpha^M\wedge dt',
\end{equation}
where  $t'$ is the coordinate in the $(t-\delta,t+\delta)$-factor\footnote{Here, it is understood that $(-\delta,\delta)=[0,\delta)$, for example.}
 in $U$.
We make the same assumptions and notation for $(N,\omega^N,\mu_N)$.\\







A $\mu-S^1$-diffeomorphism $f \colon M \to N$ gives an identification of $P_t^M=\mu_M^{-1}(t)$ and $P_t^N=\mu_N^{-1}(t)$.
We show that for a $\mu-S^1$-diffeomorphism $f$ such that $[f^{*}\omega^N]=[\omega^M]$, being almost symplectic can be checked at the reduced spaces. 
\begin{lemma}\label{lem:isotopybase}
    Consider a $\mu-S^1$-diffeomorphism $f$ from $(M,\omega^M)$ to $(N,\omega^N)$ 
    such that the induced diffeomorphism $M_t\to N_t$ is almost symplectic for every $t$ and $[f^*\omega^N]=[\omega^M]$ in $H^2(M;\R)$. Then $f$ is almost symplectic: the family
    \begin{equation}\label{eq:iso1}
    \omega(s):=sf^*\omega^N+(1-s)\omega^M, \,\, s \in [0,1]
    \end{equation}
    is an isotopy between $f^{*}\omega^N$ and $\omega^M$.
\end{lemma}
\begin{proof}
Since $[f^{*}{\omega^N}]=[\omega^M]$,
we only need to show that each $\omega(s)$ is a symplectic form on $M$.
This is a local statement, so we may restrict to a neighborhood 
$U=U^{\delta}$ with the symplectic form $\omega^{U,M}=(\omega^M_t+(t'-t)d\alpha^M)+\alpha^M\wedge dt'$ (and similarly for $\omega^{U,N}$), as in \eqref{Udelta} and \eqref{omegaU}.

 Since $f$ is a $\mu-S^1$-diffeomorphism between $M$ and $N$, we have $f_{*}(\xi_M)=\xi_N$, where $\xi_M$ and $\xi_N$ are the fundamental vector fields of the $S^1$-action. So we can write $\xi$ for both $\xi_M$ and $\xi_N$. Moreover, using $f$ to identify $P^M_t=\mu_M^{-1}(t)$ and $P^N_{t}=\mu_N^{-1}(t)$, 
 we have $f_*({\partial}_{t'})={\partial}_{t'}+v$, where $v\in T{P}_{t'}$. So, since $\omega^{U,N}(\xi,v)=\mu_N(v)=0$,
 $$\omega^{U,N}(f_*(\xi),f_*({\partial}_{t'}))=\omega^{U,N}(\xi,{\partial}_{t'}+v)=\omega^{U,N}(\xi,{\partial}_{t'}).$$
 This implies that $\omega^{U}(s)(\xi,{\partial}_{t'})$ does not depend on $s$. Since it is not $0$ for $s=0$, it is never $0$.


   Due to $TM_{|\mu_M^{-1}(t')}=\ker {\alpha}_{|P_{t'}}\oplus \R \xi \oplus \partial_{t'}$ for any $t'$, it remains to check that $\omega^{U}(s)$ does not degenerate on $\ker \alpha_{|P_{t'}}\cong T M_{t'}$ to deduce that $\omega^{U}(s)$ is symplectic. This follows from the assumption that ${\omega}_{t'}(s)$ is a symplectic form, since $$\omega^{U}(s)_{|TP_{t'}}=\pi^{*}\omega^{U}_{t'}(s).$$
\end{proof}
Under the identifications $M\cong \mu_M^{-1}(0)\times [0,1]$ and $N\cong \mu_N^{-1}(0)\times [0,1]$ obtained from the normalized gradient flow of the momentum map, any almost symplectic $\mu-S^1$-diffeomorphism $f\colon M\to N$ naturally gives rise to a smooth family $f^t \colon P^M_0 \to P^N_0$ of equivariant diffeomorphisms. This smooth family descends to a smooth family of almost symplectic diffeomorphisms $f_t\colon (M_0,\omega^M_t)\to (N_0,\omega^N_t)$ between the reduced spaces such that $f_t^*(e(P^N_0))=e(P^M_0)$. \Cref{lem:isotopybase} implies that the converse is true.
    \begin{lemma}\label{lem:lift}
        Any smooth family of (almost symplectic) diffeomorphisms (or homeomorphisms)
        $f_t \colon (M_0,\omega^M_t)\to (N_0,\omega^N_t) \,\, t \in [0,1]$
        such that $f_t^*(e(P^N_0))=e(P^M_0)$ lifts to a(n almost symplectic) $\mu-S^1$-diffeomorphism (or homeomorphism) $f\colon M\to N.$ More precisely, given a lift $\tilde{f}^0$ of $f_0$ to $P^M_0$, $f$ may be assumed to restrict to $\tilde{f}^0$ on $P^M_0$.

      If $f_t(s)$ depends smoothly on a parameter $s$ (from some smooth manifold), then $f_t(s)$ lifts to a smooth family of (almost symplectic) $\mu-S^1$-diffeomorphisms $f(s)\colon M\to N$. If $\partial_s f_t(s)\equiv 0$ for $t\in [0,\eps]$, then it may be assumed that $\partial_s f(s)\equiv 0$ on $\mu_M^{-1}([0,\eps])$.
    \end{lemma}
    \begin{proof}
        We view $f_0(s)$ as a map $M_0\times [0,1]\to N_0\times [0,1]$ and lift the family $f_0(s)$ to a family $f^0(s)$ on $P_0$. Such a lift exists because $f_0(s)$ was assumed to intertwine the Euler classes; we prove this for completeness in \Cref{lem:Eulerclasses}. If needed, we can take the lift to be a specified one.\\
        Assume at first that the $f_t$ are homeomorphisms. Given a lift a lift $f^0$ of $f_0$, we directly obtain a continuous family $f^t\colon P_0^M\to P_0^N$ of equivariant maps using the homotopy lifting property of principal bundles. These are indeed bijective (and hence homeomorphisms), since $f^t(p)=f^t(p')$ implies that $p$ and $p'$ are in the same $S^1$-orbit, and due to equivariance of $f^t$ and the freeness of the action this implies $p=p'$.\\

        Now assume the $f_t$ are diffeomorphisms. For fixed $s$, we now view $f_t(s)$ as a $t$-flow on the manifold $P^N_0/S^1$ and consider the time-dependent vector field $Y_t(s)$ it generates. We can lift $Y_t(s)$, using any connection of the principal $S^1$-bundle $P^N_0\to P^N_0/S^1$, horizontally to the total space. For a fixed $s$, we consider the $t$-flow $f^t(s)$ of the lifted vector field, starting at $f^0(s)$.\\
        Define $f(s)\colon M\to N$ by
        \[
        f(s)\colon P^M_0\times [0,1]\to P^N_0\times [0,1], \quad f(s)(p,t'):=(f^{t'}(s)(p),t').
        \]
        By definition, $f(s)\colon M\to N$ is a $\mu-S^1$-diffeomorphism. Also, each $f(s)$ satisfies $[f(s)^*\omega^N]=[\omega^M]$, since $[f(s)_t^*\omega_t^N]=[\omega_t^M]$ for all $t\in [0,1]$ by assumption. Therefore by \Cref{lem:isotopybase}, if each $f_t(s)$ is almost symplectic, then so is $f(s)$.

        Finally, if $f_t(s)$ does not depend on $s$ for $t\in [0,\eps]$, then $f^0(s)$ may be assumed not to depend on $s$. Since $Y_t(s)$ does not depend on $s$ and $f^t(s)$ is just the $t$-flow of $Y_t(s)$ starting at $f^0(s)$, $f^t(s)$ and hence $f(s)$ on $\mu_M^{-1}([0,\eps])$ do not depend on $s$. 
    \end{proof}



     The following corollary of \Cref{lem:lift} will allow us to 'extend' an (almost symplectic) $\mu-S^1$-diffeomorphism $f_1 \colon \mu_M^{-1}([0,1/2]) \to \mu_N^{-1}([0,1/2])$, for example, to $M$ by giving an extension $f_2$ only of $f_1^{1/2}\colon \mu_M^{-1}(1/2)\to \mu_N^{-1}(1/2)$ to $\mu_M^{-1}([1/2,1]) \to \mu_N^{-1}([1/2,1])$. This is not clear a priori because the homeomorphism obtained by piecing $f_1$ and $f_2$ together might not be smooth at $\mu_M^{-1}(1/2)$.\\
    We will formulate this corollary in a more general setting than in the rest of this section.

\begin{corollary}\label{cor:smoothing}
    Let $M$ and $N$ be connected semi-free Hamiltonian $S^1$-manifolds with proper momentum maps onto $[0,1]$, possibly with fixed points.
    For some $0<t<1$ and arbitrarily small $\eps>0$ such that $[t-\eps,t+\eps]$ is a regular interval for $M$, let $f_1$ and $f_2$ be (almost symplectic) $\mu-S^1$-diffeomorphisms 
    $$f_1 \colon \mu_M^{-1}([0,t+\eps/2]) \to \mu_N^{-1}([0,t+\eps/2]),$$
    $$f_2 \colon \mu_M^{-1}([t+\eps/2,1]) \to \mu_N^{-1}([t+\eps/2,1]).$$
    Assume that $(f_1)_{t+\eps/2}$ and $(f_2)_{t+\eps/2}$ are isotopic on $M_{t+\eps/2}$ through (almost symplectic) diffeomorphisms. Assume also that $M_t$ and hence any reduced space is simply-connected.

    Then
    there exists a $\mu$-$S^1$-diffeomorphism $f \colon M \to N$ that agrees with $f_1$ on $\mu_M^{-1}([0,t])$ and with $f_2$ on $\mu_M^{-1}([t+\eps,1])$.
    Moreover, in case $f_1$ and $f_2$ are almost symplectic, $sf^*\omega_N+(1-s)\omega_M$ is non-degenerate for all $s\in [0,1]$. 
  In that case, $f$ is almost symplectic, that is, also $[f^*\omega_N]=[\omega_M]$.


\end{corollary}

\begin{proof}
Denote by  ${\{\Psi'_{r}\}_{r \in [0,1]}}$  the given isotopy from $(f_1)_{t+\eps/2}$ to $(f_2)_{t+\eps/2}$.
Let $\Psi_r\colon N_{t+\eps/2}\to N_{t+\eps/2}$ be the flow defined by $\{\Psi'_{r}\}$, that is, $$\Psi_r:=\Psi'_r\circ (\Psi'_0)^{-1}.$$
First, we extend $\Psi$  to  a path of isotopies $\{F_{s}\}_{s \in[0,t+\eps/2]}$ between $(f_1)_{s}$ and $(f'_1)_{s}$ for  a $\mu-S^1$-diffeomorphism 
\begin{equation}\label{eq:f'1}
f'_1 \colon \mu_{M}^{-1}([0,t+\eps/2]) \to \mu_{N}^{-1}([0,t+\eps/2]) \text{ such that }{f_{1}}|_{\mu_{M}^{-1}([0,t])}={f'_{1}}|_{\mu_{M}^{-1}([0,t])},
\end{equation}
and $f'_1$ is almost symplectic if $f_1$ and $f_2$ are.

For $0<\delta<\eps/2$, define a monotone smooth function 
$$\rho=\rho(\delta)\colon [0,t+\eps/2]\to [0,1]$$
that equals $1$ near $t+\frac{\eps}{2}$ and $0$ on $[0,t+\eps/2-\delta]$. Under the identification $M_s\cong M_{t+\eps/2}$ resp.\ $N_s\cong N_{t+\eps/2}$, $s\in [0,t+\eps/2]$ 
obtained from the normalized gradient flow of the momentum map,
we set
$$(f_1)'_{s}:=\Psi_{\rho(s)} \circ (f_1)_{s}\colon M_s\to N_s.$$
If $f_1$, $f_2$, and the $\Psi'_{r}$s are almost symplectic, the forms 
\[
    \omega(a)=a(f_1)_s^* \Psi_{\rho(s)}^* \omega^N_s+(1-a)\omega^M_s, \quad a\in [0,1],
    \]
    are non-degenerate for $s \in [0,t+\eps/2]$. Moreover,
    this is true for
    \[
    a(f_1)_{t+\eps/2}^* \Psi_{s'}^*\omega^N_{t+\eps/2}+(1-a)\omega^M_{t+\eps/2}, \quad a\in [0,1],
    \]
    and arbitrary $s'$ in $[0,1]$. Hence, since non-degeneracy is an open condition (see \Cref{rem:almostsymplecticopen}), there is $\delta>0$ small enough so that
    \[
    a(f_1)_{s}^* \Psi_{s'}^*\omega^N_{s}+(1-a)\omega^M_{s}, \quad a\in [0,1],
    \]
    is non-degenerate for all $s\in [t+\eps/2-\delta,t+\eps/2]$ and $s'$ in $[0,1]$.
    \\
    Further, there is an isotopy $F_s(s')$, $s'\in [0,1]$, between $(f_1)_s$ and $(f_1)'_s$ given by
    \[
    F_s(s'):=\Psi_{s'\rho(s)}\circ (f_1)_s.
    \]
     So, by \Cref{lem:lift}, we can lift $(f_1)'_{s}$ to an (almost symplectic) $\mu-S^1$-diffeomorphism $f'_1$ as in \eqref{eq:f'1}.
The  maps $f'_1$ and $f_2$ differ on $\mu_M^{-1}(t+\eps/2)$ only by a map $M_{t+\eps/2}\to S^1$, but since $M_{t+\eps/2}$ is simply-connected, any such map is nullhomotopic via some homotopy $h_s$. We define $f_1''$ by
    $$f_1''(x):=h_{\rho(\mu_M(x))}\cdot f_1'(x).$$ 

Next,  we apply the same fact on non-degeneracy and \Cref{lem:isotopybase} to show that we can locally modify both $f_1''$ and $f_2$ to (almost symplectic) $\mu-S^1$-diffeomorphisms whose restriction to $V_{\delta}:=P_{t+\eps/2} \times (t+\eps/2-\delta,t+\eps/2+\delta)$, for some $\delta>0$, factors as 
$(p,t') \mapsto ({{f_2}|_{P_{t+\eps/2}}}(p),t')$.
See \Cref{lem:smoothing} below.
This allows us to paste the maps to get a $\mu-S^1$-diffeomorphism $f \colon M \to N$.

Moreover, if $f_1$ and $f_2$ are almost symplectic, then we get  a $\mu-S^1$-diffeomorphism $f$ such that $sf^*\omega_N+(1-s)\omega_M$ is non-degenerate for all $s\in [0,1]$. 
If the $S^1$-action on $M$ and $N$ is free, the Duistermaat-Heckman formula implies that $[f^{*}\omega_N]=[\omega_M]$. Otherwise, the equality $[f^{*}\omega_N]=[\omega_M]$ is by \Cref{lem:cohomologyclass}, saying that for two symplectic forms to be cohomologous on $M$, it is enough that they are cohomologous on   $\mu_M^{-1}([0,t+\eps/2])$ and on $\mu_M^{-1}([t+\eps/2,1])$.
\end{proof}


In the proof, we used the following lemma.
\begin{lemma}\label{lem:smoothing}
Let $(M,\omega^M,\mu_M)$ and $(N,\omega^N,\mu_N)$ be connected Hamiltonian $S^1$-manifolds; assume that the circle action is {free} and the 
momentum maps are proper and onto $[0,1]$.
    Let $f \colon M \to N$ be a(n almost symplectic) $\mu-S^1$-diffeomorphism. For any $t\in [0,1]$ there are $0<\delta<\eps$
    and a(n almost symplectic) $\mu-S^1$-diffeomorphism $g\colon M\to N$ such that
    \begin{itemize}
        \item $g$ and $f$ agree outside $V_{\eps}:=P^M_t\times (t-\eps,t+\eps)$;
        \item when restricted to $P^M_t$, $f$ and $g$ are equal to the same map $h\colon P^M_t\to P^N_t$;
        \item $g$ is of the form $g(p,t')=(h(p),t')$ on $V_{\delta}:=P^M_t\times (t-\delta,t+\delta)$.
    \end{itemize}
\end{lemma}
  Again, it is understood that $(0-\eps,0+\eps)=[0,\eps)$ and $P^M_0\times (0-\eps,0+\eps)=P^M_0\times [0,\eps)$, for example.

  We will only prove the
  case that $f$ is also almost symplectic. 
  The arguments required for the case that the maps are $\mu-S^1$-diffeomorphisms 
are included in the proof.
\begin{proof}


  For some $0<\delta<\eps$, let $\rho\colon [0,1]\to [0,1]$ be a monotone smooth function with the properties:
    \begin{itemize}
        \item $\rho(t')=t$ for all $t'\in [t-\delta,t+\delta]$,
        \item $\rho$ is the identity outside $[t-\eps,t+\eps]$.
    \end{itemize}
    Note that $\rho$ can be chosen arbitrarily close under the maximum norm to the identity map when $\eps$ is chosen to be small enough.\\
   Viewing $f$ as a smooth family $f^s$, $s\in [0,1]$, of $S^1$-equivariant diffeomorphisms $P^M_s\to P^N_s$, we define $g$ to be
    \[
    g\colon M\to N, \quad g(p,s)=(f^{\rho(s)}(p),s).
    \]
   For fixed $s$, $f_s^*\omega^N_s$ and $\omega^M_s$ are isotopic under the standard homotopy, so there is $r>0$ such that $f_s^*\omega^N_{s'}$ and $\omega^M_{s'}$ are isotopic under the standard homotopy, provided that $|s-s'|<r$. Since $s\in [0,1]$, we may choose $r$ to be universal for all $s$. So if we choose $\eps$ such that $\rho$ is closer than $r$ to the identity with respect to the maximum norm, then each $$g_s\colon (M_s,\omega^M_s)\to (N_s,\omega^N_s)$$ on the reduced spaces at level $s$ has the property that $g_s^*(\omega^N_s)$ is isotopic to $\omega^M_s$ under the standard homotopy. We are done in view of \Cref{lem:isotopybase}.
\end{proof}



The next proposition highlights the main application of rigidity in the proof of \Cref{thm:mainresult}. It will allow us to extend an isomorphism below a critical level to a level arbitrarily close to the critical level.

\begin{proposition}\label{prop:extension}
 Assume that $M$ and $N$ are connected free Hamiltonian $S^1$-manifolds with proper momentum maps onto $[0,1]$.
 The following statements hold.
 \begin{itemize}
     \item Given any $\mu-S^1$-diffeomorphism $f\colon \mu_M^{-1}([0,\eps])\to \mu_N^{-1}([0,\eps])$ for any $\eps\in (0,1)$, we find a $\mu-S^1$-diffeomorphism $M\to N$ that agrees with $f$ near the $0$-level set.
     \item Assume that $(M_0,\omega^M_{t\in [0,1]})$ is rigid (as in \Cref{def:rigid}). Given any isomorphism $f\colon \mu_M^{-1}([0,\eps])\to \mu_N^{-1}([0,\eps])$ for any $\eps\in (0,1)$, we find an isomorphism $M\to N$ that agrees with $f$ near the $0$-level set.
 \end{itemize}
\end{proposition}

In the proof of the proposition we will use Gonzales' definition of equivalence for families of symplectic forms on a compact manifold.


\begin{definition}\label{def:equivalent}\cite[Definition 1.4]{Go11}
        Let $B$ be a compact manifold. Let $\omega_t$ and $\omega'_t$, $t\in I=[t_0,t_1]$, be families of symplectic forms on $B$ such that $[\omega_t]=[\omega'_t]$ in $H^2(M;\R)$ for all $t\in I$. We say that $\omega_t$ and $\omega'_t$ are \textbf{equivalent} if there exists a smooth family $\omega_{s,t}$ of symplectic forms such that
        \begin{equation} \label{eq:equiv}
        \partial_s [\omega_{s,t}]=0,\quad \text{and} \quad \omega_{0,t}=\omega_{t}, \,\, \omega_{1,t}=\omega'_{t}
        \text{
        for all }(s,t)\in [0,1]\times I.
        \end{equation}
    \end{definition}


\begin{lemma}\label{lem:equivalent} (cf. \cite[Lemma 3.4]{Go11}.)
     Let $(B,\omega_t)$ be rigid, and let $\omega'_t$ be any family of symplectic forms on $B$ such that $[\omega_t]=[\omega'_t]$ in $H^2(M;\R)$, for all $t\in I=[t_0,t_1]$, and $\omega_{t_0}=\omega'_{t_0}$.
     \begin{enumerate}
         \item Then $\omega_t'$ is equivalent to $\omega_t$. 
         \item Furthermore, if there exists $R>t_0$ such that $\omega_t=\omega'_t$ for all $t_0\leq t\leq R$, then there exists a smooth family $\omega_{s,t}$ such that $\partial_s\omega_{s,t}=0$ for all $t_0\leq t\leq R$. 
         \item If case (2) holds, there also exists a smooth family $f_{s,t}$ of diffeomorphisms $B\to B$ such that $f_{s,t}=\id$ for $t_0\leq t\leq R-\eps$ and $f_{s,t}^*\omega_{s,t}=\omega_{t_0,t}$.
     \end{enumerate}
\end{lemma}
 Item (1) is simply the statement in \cite[Lemma 3.4]{Go11}. The proof of Item (2) is similar to the proof of \cite[Lemma 3.4]{Go11}. Item (3) is by Moser's method.
      We prove Items (2) and (3) in \Cref{app:extrafour}.\\



To prove the proposition we will also use Moser's trick. 
 Since the action is free and the manifold is not closed, we need to argue that Moser's method still works. For the application of Moser's trick in case fixed points exist, see \Cref{rem:moserwithfixedpoints}.

\begin{lemma}\label{lem:moserwithoutfp}
Let $f$ be an almost symplectic $\mu-S^1$-diffeomorphism from $(M,\omega^M)$ to $(N,\omega^N)$.
     The isotopy of forms $\omega(s)=sf^*\omega^N+(1-s)\omega^M$  between $f^{*}\omega^N$ and $\omega^M$ integrates to an isotopy of $\mu-S^1$-diffeomorphisms 
  $$\Psi_s\colon M\to M \text{ such that }\Psi_s^*\omega(s)=\omega(0)=\omega^M.$$
  In particular, $f(s):=f\circ \Psi_s$ is an isotopy of $\mu-S^1$-diffeomorphisms $M \to N$ such that $f(1)^*\omega^N=\omega^M$.\\
    If, moreover, $f$ is a symplectomorphism when restricted to $V:=\mu_M^{-1}([0,\eps])$ with $\eps>0$, then the isotopy $\omega(s)$ is constant on $V$, and the corresponding isotopies $\Psi_s$ respectively $f(s)$ on $M$ may be chosen to have support outside $V$ as well.
\end{lemma}
\begin{proof}
    We will treat both cases ($f$ being a symplectomorphism on $V$ or not) at the same time. We set
    $$\Omega:=\partial_s \omega(s)=f^*(\omega^N)-\omega^M.$$
    Note that $\Omega$ descends to a form $\omega'$ on $M/S^1$, since it is invariant under the $S^1$-action and $$f^*(\omega^N)(\xi)-\omega^M(\xi)=df^*(\mu_N)-d\mu_M=0.$$
    Since $f$ is almost symplectic, each $f_t \colon M_t \to N_t$ is almost symplectic, and so $0=[\omega']\in H^2(M/S^1;\R)$. If, moreover, $f$ is a symplectomorphism on $V$, then $\omega'$ vanishes on $V/S^1$, so it defines an element in the relative deRham cohomology group $H^2(M/S^1,V/S^1;\R)$. Since the inclusions $V\cong M_0\times [0,\eps]\hookrightarrow M\cong M_0\times [0,1]$ resp.\ $V/S^1\hookrightarrow  M/S^1$ are homotopy equivalences, it follows that $0=[\omega']\in H^2(M/S^1,V/S^1;\R)$. So there is a one-form $\beta'$ on $M/S^1$ with 
    $$d\beta'=\omega'$$
    that vanishes on $V/S^1$ if $\omega'$ does. The pullback $\beta$ of $\beta'$ under $\pi\colon M\to M/S^1$ is then a one-form whose differential is $\Omega$. 
    Define a vector field $X_s$ by 
    $$\beta=\omega(s)(\cdot,X_s).$$ We get that $X_s$ is a Moser vector field for $\omega(s)$, i.e., $\partial_{s}\omega(s)+\mathcal{L}_{X_s}\omega(s)=0$.
   The vector field $X_s$ leaves the momentum map $\mu_M=(1-s)\mu_M+sf^*\mu_N$ invariant, since
    $$d((1-s)\mu_M+sf^*\mu_N)(X_s)=\omega(s)(\xi,X_s)=\beta(\xi)=0.$$
   Since $\mu_M$ is proper, this implies that the flow $\{\Psi_s\}$ of $X_s$ on $M$ is well-defined. Since $X_s$ is a Moser vector field for $\omega(s)$, we have $${\Psi}_s^{*}\omega(s)=\omega^M.$$ Also, the flow preserves the momentum map and thus is a $\mu-S^1$-diffeomorphism. 
   If, moreover, $\beta$ vanishes on $V$, the flow is supported away from $V$. This completes the proof.
\end{proof}








\begin{proof}[Proof of \Cref{prop:extension}]
Consider an isomorphism (or $\mu-S^1$-diffeomorphism) $f\colon \mu_M^{-1}([0,\eps])\to \mu_N^{-1}([0,\eps])$, with $\eps\in (0,1)$.
    Using the gradient flow of $\mu$ to identify $M\cong P_0\times [0,1]$, we can extend $f^{\eps}\colon \mu_M^{-1}(\eps)\to \mu_N^{-1}(\eps)$ to a $\mu-S^1$-diffeomorphism $\mu_M^{-1}([\eps,1])\to \mu_N^{-1}([\eps,1])$. 
    By \Cref{cor:smoothing}, we can piece the latter map and $f$ to obtain a $\mu-S^1-$diffeomoprhism $$f''\colon M\to N$$ that agrees with $f$ near $\mu_M^{-1}(0)$, already showing the first item.\\

     For the second, now consider the two families of reduced forms: $\omega^M_t$ and $$\omega'_t:=(f'')^*\omega^N_t,$$ with $t\in I$. By the setting of $f''$ we have $\omega_0=\omega'_0$.  
     Moreover, the Duistermaat-Heckman formula $[\omega_{t}]=[\omega_{t'}]+(t'-t)e(P)$ implies that $[\omega_t]=[\omega'_t]$ for $t\in I$. 
     Hence, since by assumption $(M_0,\omega^M_{t \in [0,1]})$ is rigid, \Cref{lem:equivalent} applies. We deduce that the two families
     are equivalent in the sense of \Cref{def:equivalent},  i.e., there is a smooth family $\omega_{s,t}$ on $M_0$ such that \eqref{eq:equiv} holds.
Moreover, by the second part of the lemma, since $\omega^M_t$ and $\omega'_t$ agree for $t$ near $0$, it may be assumed that the smooth familiy $\omega_{s,t}$ does not depend on $s$ for $t$ near $0$, and furthermore, there is a smooth family of diffeomorphisms $f_{s,t} \colon M_0  \to M_0$ such that $f_{s,t}$ is the identity near $0$ and $f_{s,t}^{*}{\omega_{s,t}}=\omega_{0,t}$. In particular 
      $$f_{1,t}^{*}{\omega'_t}=f_{1,t}^{*}{\omega_{1,t}}=\omega_{0,t}=\omega^M_t.$$
      By \Cref{lem:lift}, the $2$-parameter family $f_{s,t}$ lifts smoothly in $s$ to a  smooth family of $\mu-S^1$-diffeomorphisms $g(s)\colon M\to M$ that is the identity near level $0$. The lift $g(1)$ of the $1$-parameter family $f_{1,t}$ is almost symplectic with respect to $\omega^M$ and $\omega'$. So 
     $$f':=f''\circ g(1)$$ is almost symplectic with respect to $\omega^M$ and $\omega^N$, and equals $f$ near level $0$.
     We now apply \Cref{lem:moserwithoutfp} to get an isotopy $f'(s)$ of $\mu-S^1$-diffeomorphisms $M \to N$ such that $f'(1)^{*}\omega^N=\omega^M$. Moreover, the isotopy $f'(s)$ has support away from level $0$ so $f'(1)$ equals $f$ near $\mu_M^{-1}(0)$, and is an extension as required.


\end{proof}






\section{Isomorphisms of neighborhoods of critical levels}\label{sec:neighborhoods}


Another ingredient in our proof of \Cref{thm:extending-g} is understanding the implications of having the same $*$-small fixed point data on extending a symplectomorphism of reduced spaces below the critical level to a neighbourhood of the critical level, 
as we do in \Cref{lem:psi_textremum}, \Cref{lem:connected<4}, and \Cref{lem:nonextremal-2}. We assume the following setting.

\begin{Setting}
\label{set:merged}

Let $M^1=(M^1,\omega^1,\mu_1)$ and $M^2=(M^2,\omega^2,\mu_2)$ be connected symplectic semi-free Hamiltonian manifolds of dimension six whose momentum maps $\mu_1$ and $\mu_2$ are proper and have bounded images.

Assume that $\lambda$ is a critical value for both $\mu_1$ and $\mu_2$, either non-extremal for both or maximal (minimal) for both.
Assume that $M^1$ and $M^2$ have the same $*$-small fixed point data at $\lambda$.

  If $\lambda$ is {\bf non-extremal}, assume that the connected components of the fixed point set at $\lambda$ are either points or \textbf{exceptional spheres}, that is, symplectically embedded spheres of self-intersection $-1$ in $M^{i}_{\lambda}$.\\  
If $\lambda$ is {\bf extremal} assume that the fixed point set is simply connected.
\end{Setting}







In some of the claims, we assume that the reduced space of dimension four at the critical level is a symplectic rational surface. 
This assumption  allows us to apply the 
Gromov-Seiberg-Witten-Taubes theory.


\begin{theorem} \cite{Mc96}, \cite[Conclusion in p.\ 17]{Sa13}. \label{thm:cohomologousformsarediffeomorphic}
    Let $(N^1,\omega^1)$ and $(N^2,\omega^2)$ be symplectic rational surfaces and $f\colon N^1\to N^2$ a diffeomorphism that satisfies $f^*[\omega^2]=[\omega^1]$. Then there is a symplectomoprhism $(N^1,\omega^1)\to (N^2,\omega^2)$ whose induced map on homology agrees with that of $f$.
\end{theorem}



 \subsection*{Case I: the critical value is extremal.}
If $\lambda$ is an extremal critical value, then $M^{i}_{\lambda}$ coincides with the fixed point set $F_i$ at level $\lambda$. 
 First, we describe a neighborhood of $F_i$ as an equivariant symplectic vector bundle.  
  For that, we use the construction of a symplectic form on a $D^{2n}$-bundle with structure group $\U(n)$ over a compact symplectic manifold.
\begin{noTitle}\label{nt:normalbundle}
Let $(B,\omega_B)$ be a compact, simply-connected symplectic manifold. Let $$\pi\colon D\to B$$ be a $D^{2n}$-bundle with structure group $\U(n)$ over $B$. We consider $D^{2n}$ as a subset of $\C^n$ and endow $D$ with any $S^1$-action that fixes $B$ and acts linearly fiberwise linearly; such an action always exists because the structure group is $\U(n)$, for example $\rho(t)( z_1,\hdots,z_n)=(t^{-1}z_1,\hdots,t^{-1}z_n)$.\\

 Let $\{U_1,\hdots,U_k\}$ be an open cover of $B$ such that $\phi_i\colon U_i\times D^{2n}\to \pi^{-1}(U_i)$ is a trivialization of $D$. This gives fiber inclusions $\iota_p\colon D^{2n}\hookrightarrow \pi^{-1}(p)$ for all $p\in B$ that are well-defined up to the action of $\U(n)$. In particular, we can endow $D$ with a fiber metric $\langle \cdot,\cdot \rangle$ that is just the standard Euclidean scalar product on each fiber, such that
$\langle v,v \rangle \leq 1$ for all $v\in D$.\\

 Since the disk fiber is contractible, the cohomology class of the fiber form is $0$. Hence, by a theorem of Thurston (see \cite{Th76} and \cite[Theorem 6.1.4]{MS98}), there exists a closed $2$-form $\eta$ on $D$ that restricts to the standard symplectic form on each fiber, and represents the class $0$ in $H^2(D;\R)\cong H^2(B;\R)$, i.e., its restriction to the $0$-section $B$ is exact\footnote{In general, we can not guarantee that its restriction is $0$.}. By averaging $\eta$ w.r.t. the $S^1$-action on $D$, we further have that $\eta$ is $S^1$-invariant. Moreover, for $c>0$ small enough (to be fixed from now on), the invariant closed form 
 $$\omega=\pi^*(\omega_B)+c\eta$$
 restricts to a symplectic form on $B$. Also, it is clear that $\omega$ is non-degenerate in vertical directions, i.e., on $\ker d\pi(x)$ for all $x$. It follows that there is $r>0$ sufficiently small such that $\omega$ is symplectic in a neighborhood $U$ of $B$ consisting of those $v$ with $\langle v,v\rangle \leq r$. Since $[\eta]=0\in H^2(B;\R)$, the form $\omega$ is isotopic to $\omega_B$ under the standard homotopy.\\

 Since $B$ is simply-connected, there is always a momentum map $\mu$ for this symplectic form that restricts to the standard momentum map on each fiber (because $\omega$ restricts to the standard symplectic form on the fiber), which is a disk of radius $r$ with respect to the standard Euclidean metric.\\
 Therefore, if the action is of the form $\rho(t)( z_1,\hdots,z_n)=(t^{-1}z_1,\hdots,t^{-1}z_n)$, there is a surjective, proper momentum map $$\mu\colon U\to [\lambda-\delta,\lambda]$$
 such that $\mu(B)=\lambda$ (for some $\lambda\in \R$) and $\delta={r^2}/2$. After renaming $U$ as $D$, we denote the reduced space at $t\in [\lambda-\delta,\lambda]$ by
$$D_t=\mu^{-1}(t)/S^1.$$
If $n=1$, each reduced space is diffeomorphic to $B$, and scalar multiplication in the $D^{2}$-fiber gives a fixed identification $D/S^1\cong B\times [\lambda-\delta,\lambda]$ that intertwines $\mu$ and the projection $B\times [\lambda-\delta,\lambda]\to [\lambda-\delta,\lambda]$.
\end{noTitle}


In case $\dim F_i=4$, we use the above construction with $n=1$, Weinstein's symplectic neighbourhood theorem (\Cref{thm:Weinstein}), \Cref{thm:cohomologousformsarediffeomorphic}, and Moser's method to get an equivariant symplectomorphism of neighborhoods of the maximal (minimal) level that agrees on homology with a given symplectomorphism of a level below (above) the maximal (minimal) level.
\begin{theorem}\label{thm:Weinstein}{\cite{We71}, \cite{Ca08}}.
    Let $M$ be a manifold equipped with two symplectic forms $\omega_1$ and $\omega_2$ on which a compact Lie group $G$ acts symplectically. Further, let $N$ be a compact, connected manifold also acted on by $G$ smoothly, together with a smooth, equivariant embedding $f\colon N\to M$ such that $f^*\omega_1=f^*\omega_2$.

    Then there exist two open $G$-invariant neighborhoods $U_1,U_2$ of $N=f(N)$ as well as an equivariant diffeomorphism $\psi\colon U_1\to U_2$ such that $\psi^*\omega_2=\omega_1$ and $\psi_{|N}=\text{id}_{|N}$.
    \end{theorem}
    \begin{remark}\label{rem:Weinstein}
        Often times \Cref{thm:Weinstein} is used in a slightly different setting. Suppose that two symplectic manifolds $(M_i,\omega_i)$ as well as another symplectic manifold $(N,\omega_N)$, all acted on symplectically by $G$, together with equivariant symplectic embeddings $f_i\colon N\to M_i$ are given. Suppose further that the pullback of the normal bundles of the images are equivariantly isomorphic as vector bundles. Therefore, by the usual equivariant tubular neighborhood theorem, there are open neighborhoods $V_1$ and $V_2$ of $N\subset M_1$ resp.\ $N\subset M_2$ as well as an equivariant diffeomorphism $\psi'\colon V_1\to V_2$ such that $\psi\circ f_1=f_2$. By pulling back $\omega_2$ along $\psi'$, we obtain two symplectic forms $\omega_1$ and $(\psi')^*\omega_2$ on $V_1$ that agree on $N$; therefore, by \Cref{thm:Weinstein}, there exist $G$-invariant neighborhoods $U_1$ and $U_2$ of $N\subset V_1$ as well as an equivariant symplectomorphism $\psi\colon (U_1,\omega_1)\to (U_2,(\psi')^*\omega_2)$ that is the identity on $N$. By concatenating $\psi$ and $\psi'$, we find an equivariant symplectomorphism
        $$\psi\colon (U_1,\omega_1)\to (\psi'(U_1),\omega_2) \text{ such that }\psi\circ f_1=f_2.$$
    \end{remark}
\begin{lemma}\label{lem:psi_textremum}
Let $M^1$, $M^2$ be as in \Cref{set:merged}  with momentum images $[\lambda-\eps,\lambda]$ for $\eps>0$, and assume that the critical value $\lambda$ is both maximal and the only critical value of $\mu_1$ and $\mu_2$. Assume that $F_1$ and $F_2$ are of dimension four. Let
$$f_{\lambda-\eps} \colon M^1_{\lambda-\eps} \to M^2_{\lambda-\eps}$$
be a homoemorphism  that intertwines the Euler classes.\\
Then there is $0< \delta\leq \eps$ and an equivariant homeomorphism 
$$g \colon \mu_1^{-1}([\lambda-\delta,\lambda]) \to \mu_2^{-1}([\lambda-\delta,\lambda])$$ such 
that 
$g_{\lambda-\delta}$ and $f_{\lambda-\eps}$, the latter seen as a map $M^1_{\lambda-\delta}\to M^2_{\lambda-\delta}$ using the normalized gradient flow of the momentum map, induce the same map on homology.\\
Moreoever, if the $(F_i,\omega^i)$s are symplectic rational surfaces and $f_{\lambda-\eps}$ is a symplectomorphism then there is such $g$ that is an equivariant symplectomorphism.
\\
The statement holds when $\lambda$ is minimal and $\lambda-\eps$, $\lambda-\delta$ and $[\lambda-\delta,\lambda]$ are replaced with $\lambda+\eps$, $\lambda+\delta$, and $[\lambda,\lambda+\delta]$.
\end{lemma}


\begin{proof}
  We construct $(D^i,\omega,\mu)$  as in \Cref{nt:normalbundle} with $n=1$ and $(B,\omega_B)=(F_i,\omega^{i})$. That way, we have two symplectic embeddings $(F_i,\omega_i)\to (M^i,\omega^i)$ and $(F_i,\omega_i)\to (D^i,\omega)$; the latter is \textbf{not} the standard embedding $(F_i,\omega^{i})=(B,\omega_B)\hookrightarrow D^i$ (because $\omega$ does not necessarily restrict to $\omega_B$ on $B$), but isotopic to it as explained in  \Cref{nt:normalbundle}. Therefore, due to the equivariant symplectic tubular neighborhood theorem \Cref{thm:Weinstein} resp.\ \Cref{rem:Weinstein}, there is $\delta>0$ small enough such that
\begin{align}\label{eq:weinstein}
\mu_i^{-1}([\lambda-\delta,\lambda]) & \text{ is equivariantly symplectomorphic to }\mu^{-1}([\lambda-\delta,\lambda])\subset D^i \nonumber
\end{align}
 and this equivariant symplectomorphism is isotopic to the identity on $F_i$.\\
Thus, $M_{\lambda-\eps}^{i}$ is diffeomorphic to $D_{\lambda-\eps}^{i}$.
   Moreover, using the identifications $D^{i}/S^1\cong F_i\times [\lambda-r,\lambda]$, we get a diffeomorphism from $D^{i}_{\lambda-\eps}$ to $F_i=M_{\lambda}^{i}$.
   Hence, and by the setting of $f_{\lambda-\eps}$, 
   we have a  homeomorphism (diffeomorphism, if $f_{\lambda-\eps}$ is a diffeomorphism)
     $$\psi' \colon F_1\to D^{1}_{\lambda-\eps}\to D^{2}_{\lambda-\eps} \to F_2.$$ 
     The map $\psi'$ intertwines the Euler classes of the normal bundles of $F_1$ and $F_2$ in $M^1$ and $M^2$, since these are just the Euler classes of the principal $S^1$-bundles over $D^{1}_{\lambda-\eps}$ and over $D^{2}_{\lambda-\eps}$ under the identifications 
     $F_i\to D^{i}_{\lambda-\eps}$. 
     So, by \Cref{lem:Eulerclasses}, $\psi'$ lifts to an equivariant  isomorphism (smooth, if $f_{\lambda-\eps}$ is a diffeomorphism) $g$ between the normal bundles and therefore to an equivariant homeomorphism (diffeomorphism) between the neighborhoods $\mu_{i}^{-1}([\lambda-\delta,\lambda])$ of $F_i$.\\

     Moreover, if $f_{\lambda-\eps}$ is a symplectomorphism, it follows that $\psi'$ also preserves the cohomology classes of the symplectic forms on $F_1$ and $F_2$. Indeed, by the DH formula \eqref{eq:dh}, these are determined by the Euler class $e(P)$ and the cohomology classes of the symplectic forms on $M^1_{\lambda-\eps}$ resp.\ $M^2_{\lambda-\eps}$, which are intertwined by $f_{\lambda-\eps}$.  If the $(F_i,\omega^i)$s are symplectic rational surfaces, then, by  \Cref{thm:cohomologousformsarediffeomorphic}, there is a symplectomorphism $\psi_{\lambda}\colon F_1\to F_2$ that acts in the same fashion as $\psi'$ on homology. In particular, $\psi_{\lambda}$ intertwines the Euler classes of the normal bundles of $F_i$ in $M^i$ and therefore lifts to an equivariant bundle isomorphism $\psi\colon D^1\to D^2$ by \Cref{lem:Eulerclasses}. Since we can identify $D^i$ with $\mu_i^{-1}([t,\lambda])$ as Hamiltonian $S^1$-manifolds for $t$ sufficiently close to $\lambda$, it is only left to show that $\psi\colon D^1\to D^2$ (after possibly shrinking $D^1$ and $D^2$) can be isotoped into an equivariant symplectomorphism.\\

     The homotopy $\omega(s):=s\omega^1+(1-s)\psi^*\omega^2$ does not degenerate on $TD^1_{|F_1}$. This is since $\omega^1$ and $\psi^*\omega^2$ agree on $F_1$, and for a vertical vector $v\in TD^1_{|F_1}$ we have that $\omega^1(v,i\cdot v)>0$, where $i\in S^1$ is the imaginary unit. Since $\psi_*(v)$ is also vertical in $TD^2_{|F_2}$ and $\psi_*$ commutes with the circle action, we obtain similarly that $\omega^2(\psi_*(v),i\cdot \psi_*(v))>0$, yielding that $\omega(s)$ is indeed non-degenerate.
     Therefore, $s\omega^1+(1-s)\psi^*\omega^2$ does not degenerate near $F_1$, so it defines an isotopy near $F_1$. This implies that there is $0<\delta'\leq\delta$ such that $\mu_1^{-1}([\lambda-\delta',\lambda])$ and $\mu_2^{-1}([\lambda-\delta',\lambda])$ are equivariantly symplectomorphic, using Moser's method as in \Cref{rem:moserwithfixedpoints}. This completes the proof.

\end{proof}

\begin{remark}\label{rem:moserwithfixedpoints}
    If the $S^1$-action on $M$ has a fixed point and the momentum map is proper, it is standard that Moser's method works as usual. We sketch the proof. Consider a  smooth one-parameter family $\omega_t$ of symplectic forms, $t\in [0,1]$, of the form $\omega_t=t\omega_1+(1-t)\omega_0$ for $S^1$-invariant, cohomologuous symplectic forms $\omega_0$ and $\omega_1$. Assume that $\omega_0$ and $\omega_1$ admit momentum maps $\mu_0$ and $\mu_1$ that agree on the components of the fixed point set. This gives rise to an $S^1$-invariant time-dependent vector field $X_t$ such that 
\begin{equation}\label{eq:moser}
    \frac{d}{dt}\omega_t+\mathcal{L}_{X_t}\omega_t=0,
    \end{equation}
    as usual. Moreover, if $\frac{d}{dt}\omega_t\equiv 0$ on $U:=\mu^{-1}(-\infty,r)$  for a certain level $r\in \mu(M)$ such that $H^1(U;\R)=0$, then it may be assumed that $X_t\equiv 0$ on $U$ as well; this is due to the fact that $\Omega:=\frac{d}{dt}\omega_t=\omega_1-\omega_0$ is not only $0$ in $H^2(M;\R)$, but even represents the $0$-class in $H^2(M,U;\R)$. Indeed, the long exact relative cohomology sequence
    \[
    \hdots \to H^1(M;\R)\to H^1(U;\R)\to H^2(M,U;\R)\to H^2(M;\R) \to \hdots
    \]
    tells us that $\Omega$ is in the image of $H^1(U;\R)\to H^2(M,U;\R)$, but $H^1(U;\R)=0$ by assumption. Hence, we may write $\Omega=d\beta$ for an invariant one-form $\beta$ vanishing on $U$, implying that $X_t\equiv 0$ on $U$.\\
    Now, around each point in $M$, the flow $\Psi_t$ of $X_t$, defined by $\frac{d}{d_t}{\Psi_t}=X_t \circ \Psi_t$, is still defined for small $t$. The flow $\Psi_t$ necessarily preserves fixed point components. By \eqref{eq:moser}, $\Psi_t^{*}\omega_t=\omega_0$.
  Denote $\mu_t:=t \mu_1+(1-t)\mu_0$. Note that $\mu_t$ is a momentum map for $\omega_t$ and that the $\mu_t$s agree on the components of the fixed point set.
   We claim that $$\Psi_t^*\mu_t=\mu_0.$$ Indeed, $\Psi_t^*\mu_t$ is \textbf{a} momentum map for $\omega_0(=\Psi_t^{*}\omega_t)$, meaning that $\Psi_t^*\mu_t$ and $\mu_0$ agree up to a shift by a constant. Since $\Psi_t$ leaves fixed point components invariant, the constant has to be zero.\\
    It follows that the vector field $X_t$ leaves the momentum map levels invariant.
   Thus, since we assumed that the momentum map is proper, the flow integrates on $M$; we get an equivariant diffeomorphim $\Psi_1$ such that $\Psi_1^{*}\omega_1=\omega_0$.
Note that if there are no fixed points, $X_t$ might not leave the momentum map levels invariant.
\end{remark}
In case the extremal submanifolds are spheres, 
we let $n=2$ in \cref{nt:normalbundle}. We need further preliminary observations about Hirzebruch surfaces.
\begin{noTitle}\label{nt:Hirzebruch}
Let $E\to S^2$ be a complex vector bundle of rank $2$. It is well-known that there is an integer $k$ such that $E\cong S^3\times_{S^1} (\C_{k}\oplus \C_{0})$ as complex bundles, where $S^1$ acts on $S^3\subset \C^2$ via the standard diagonal action and on each $\C$-summand according to the index. We endow $E$ with the anti-diagonal, fiberwise $S^1$-action. Using \cref{nt:normalbundle} for $n=2$ and $(B,\omega_B)=(S^2,\omega_{S^2})$, where $\omega_{S^2}$ is some  symplectic form on $S^2$, we can endow a neighborhood $U$ of the $0$-section of $E$ with an $S^1$-invariant symplectic form $\omega^E$ that restricts to the standard symplectic form on each disk fiber. For the momentum map $\mu_E\colon U\to \R$ such that the $0$-section of $E$ is sent to $\lambda$, we let $t<\lambda$  such that $\mu^{-1}([t,\lambda])\subset U$. Therefore, $\mu^{-1}([t,\lambda])$ is a closed tubular neighborhood of $E_0$, and $\mu^{-1}(t)$ is the total space of an $S^3$-bundle over $S^2$, and the circle acts on the $S^3$-fiber, only. It follows that the reduced space $E_{t}=\mu^{-1}(t)/S^1$ is an $S^2$-bundle over $S^2$ with structure group $\SO(3)$. Since $\pi_1(\SO(3))=\Z_2$, $E_t$ is diffeomorphic to either $H_0:=S^2\times S^2$, the total space of the trivial bundle, or  $H_1:=\C\PP^2\# \overline{\C\PP^2}$ (the blowup of $\C \PP^2$), which is the total space of the non-trivial $S^2$-bundle over $S^2$. In particular, $E_t$ is simply-connected.\\

    Now, since $E\cong L_k\oplus \underline{\C}$, $\underline{\C}$ being the trivial $\C$-bundle and $L_k=S^3\times_{S^1} \C_k$, there is a section
    \begin{equation}\label{eq:section}
        s'\colon S^2\to \mu^{-1}(t)
    \end{equation}
    coming from the section of the trivial $\C$-bundle. 
    We will use the following facts on the section in the proof of the next lemma.
    \begin{itemize}
        \item The Euler class $e$ of the $S^1$-bundle $S^1\to \mu^{-1}(t) \overset{\pi}{\to} E_{t}$  evaluated on the image of $s\colon S^2\overset{s'}{\to} \mu^{-1}(t)\overset{\pi}{\to} E_{t}$ is $0$.
        \item Therefore, $\int_{s(S^2)}\omega^E_{t'}$ does not depend on $t'\in [t,\lambda]$ due to the DH formula, \cref{eq:dh}.
        \item The normal bundle of $s(S^2)$ in $E_{t}$ can be identified with the complex line bundle $S^3\times_{S^1} (\{0\}\oplus \C_k)$, which, with the orientations on base and fiber induced by the symplectic form $\omega^E_t$, has Chern class $-k$. This is because the tautological bundle $S^3\times_{S^1} (\{0\}\oplus \C_1)$ has Chern class $-1$.
        \item The image $s(S^2)$ and the $S^2$-fiber $F$ generate $H_2(E_{t};\Z)$. This can be seen by looking at the Serre spectral sequence of the bundle, which collapses at the second page because neither base nor fiber have odd integer cohomology; therefore we have a short exact sequence $0\to H_2(F;\Z)\to H_2(E_t;\Z)\to H_2(S^2;\Z)\to 0$ for which the map induced by $s\colon S^2\to E_t$ on $H_2$ is a split.
        \item As always, we give any  symplectic submanifold of $E_t$ (including $E_t$ itself) the orientation induced by the symplectic form $\omega^E_t$, and take intersection numbers of homology classes in $H_2(E_t)$ with respect to these orientations. Then, the intersection number of $s(S^2)$ and any $S^2$-fiber is $1$, and the intersection number of any $S^2$-fiber with itself is $0$, because the fiber has trivial normal bundle. The intersection number of $s(S^2)$ with itself is the Chern class of its normal bundle and hence $-k$.
    \end{itemize}
\end{noTitle}


