% \begin{align}
% 0= -\int \left\langle \frac{d}{dt}\begin{bmatrix}
%     m\\
%     n
% \end{bmatrix}  + \begin{bmatrix}
% \operatorname{ad}_{\xi_h}^* & 0\\
% 0&\operatorname{ad}_{\xi_k}^{*} 
% \end{bmatrix}
% \begin{bmatrix}
%     m\\
%     n
% \end{bmatrix} ,
% \begin{bmatrix}
%     \eta_h\\
%     \eta_k
% \end{bmatrix}\right\rangle_{\mathfrak{g}^*\times\mathfrak{g}} dt, \quad (m,n)=(\frac{\delta\ell}{\delta\xi_h},\frac{\delta\ell}{\delta\xi_k}) \in \mathfrak{h}^*\times\mathfrak{k}^*.
% \end{align}
\begin{remark}
These resulting uncoupled equations on $\mathfrak{h}^*$, $\mathfrak{k}^*$ do not interact. Whilst these equations are uncoupled, it is possible to consider a coupled system by modifying the Lagrangian, to include an interaction term. If $\ell(u,v) = \ell^1(u) + \ell^2(v) + \ell^{12}(u,v)$, then the resulting system takes the form 
\begin{align}
\partial_t (m+l) + \operatorname{ad}^*_{u}(m +l) = 0 ,\quad m =\frac{\delta \ell^1}{\delta u},\quad l =\frac{\delta \ell^{12}}{\delta u},\\
\partial_t (n+o) + \operatorname{ad}^*_{v}(n+o) = 0, \quad n = \frac{\delta \ell^1}{\delta v},\quad o =\frac{\delta \ell^{12}}{\delta v}.
\end{align}
Coupling of this type will be referred to as Direct Product Lagrangian Coupling since the coupling comes from modifying the Lagrangian, and leads to Euler-Poincaré equations in transformed momentum variables. 
\end{remark}

\subsection{Semidirect products \texorpdfstring{$H\ltimes K$}
{}}\label{sec: semidirect products}
The semidirect product of groups is an example of a nontrivial group extension and the semidirect product action is motivated in \cref{sec: composition of maps}. 

Let $G = H\ltimes K$ be the outer semidirect product of two Lie groups $(H,\cdot_H)$, $(K,\cdot_K)$, with group multiplication given by 
\begin{align}
(h_1,k_1)\cdot_{\ltimes}(h_2,k_2) &= \left(h_1 h_2, k_1 \phi_{h_{1}} (k_{2})\right) =  (h_1 h_2, k_1 (h_{1} \cdot k_{2}) ), \label{eq:group product structure}
\end{align} 
where the left homomorphism action 
\begin{align}
    \phi_h(k):= h \cdot k :=  hkh^{-1}, \quad H\times K \mapsto K,\label{eq:phihk}
\end{align}  
has the key properties
\begin{align}
\phi_{h_1}(\phi_{h_2}k) = \phi_{(h_1 \cdot_{H} h_2)} k = h_1 \cdot (h_2 \cdot k) &= (h_1 h_2) \cdot k, \label{eq:property1}\\
\phi_{h}(k_1 k_2) = \phi_{h} (k_1) \cdot_{K} \phi_{h}(k_2)  = h\cdot(k_1 k_2) &= (h\cdot k_1)(h\cdot k_2).\label{eq:property2}
\end{align}
The first of these, is the homomorphism property, and the second is the automorphism property. The group $G=H\ltimes K$, inherits the usual Lie-group properties from the previously assumed Lie-Group structures in $H,K$, and the homomorphism properties of $\phi$. More specifically, the identity is $e_{G} = (e_H,e_K)$ and inverse $g^{-1} = (h,h^{-1}\cdot k^{-1})$, and associativity are verified in \cref{sec:group-axioms}. 
We shall now suppose $H$ is a copy of $K$, and by a calculation elaborated upon in \cite{marsden2007hamiltonian} and \cref{sec:adjoints for H semi K} we attain the following AD-Ad-ad-ad*-joint actions. Where it is assumed that the inner product structure is of the form
\begin{align}
    \langle (m,n),(u,v) \rangle_{\mathfrak{g}^*\times\mathfrak{g}} = \langle m,u\rangle_{\mathfrak{h}^*\times\mathfrak{h}}+ \langle n,v\rangle_{\mathfrak{k}^*\times\mathfrak{k}}.
\end{align}

\begin{proposition}[AD-Ad-adjoint for semidirect product of groups]\label{prop:adjoint actions for a semidirect product}
Let $G=H\ltimes K$, where $K$ is a copy of $H$ then the AD-Ad-ad-ad$^*$-joint actions are
\begin{align}
\operatorname{AD}_{g_1}g_2 = \operatorname{AD}_{(h_1,k_1)}(h_2,k_2)
&= \left(\operatorname{AD}_{h_1}h_2,k_1 \cdot_{K} (\phi_{h_1} k_2 ) \cdot_{K}(\phi_{\operatorname{AD}_{h_{1}} h_{2} } k_{1}^{-1} )\right),\\ 
\operatorname{Ad}_{g}{\eta_g} = \operatorname{Ad}_{(h,k)}{(\eta_h,\eta_k)} &= (\operatorname{Ad}_{h}\eta_{h},\operatorname{Ad}_{kh}(\eta_k+\eta_h) -\operatorname{Ad}_{h}\eta_h),\\
\operatorname{ad}_{\xi_{g}}\eta_{g} = \operatorname{ad}_{(\xi_{h},\xi_{k})}(\eta_{h},\eta_{k})
&= (\operatorname{ad}_{\xi_h}\eta_h, \operatorname{ad}_{\xi_h+\xi_k} (\eta_{h}+\eta_{k})- \operatorname{ad}_{\xi_h}\eta_h ),\\
\operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) &= (\operatorname{ad}^{*}_{\xi_h} m+ \operatorname{ad}_{\xi_k}^{*} n, \operatorname{ad}_{(\xi_k + \xi_h)}^{*} n  ). 
\end{align}
\end{proposition}


The resulting Euler-Poincaré equations are then given by 
\begin{align}
\pm \partial_t (m,n) + \operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) = (\pm \partial_t m + \operatorname{ad}^{*}_{\xi_h} m+ \operatorname{ad}_{\xi_k}^{*} n,\pm\partial_t n + \operatorname{ad}_{(\xi_k + \xi_h)}^{*} n  ), \label{eq:euler_arnold}
\end{align}
which we can write in co-adjoint matrix form and Lie-Poisson form respectively as, 
\begin{align}
\mp
\partial_t \begin{bmatrix}
    m\\
    n
\end{bmatrix} 
=
\left(\operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) \right)^{T}= \begin{bmatrix}
\operatorname{ad}_{\xi_h}^*(\cdot) & \operatorname{ad}_{\xi_k}^*(\cdot)\\
0&\operatorname{ad}_{\xi_h+\xi_k}^{*} (\cdot)
\end{bmatrix}
\begin{bmatrix}
    m\\
    n
\end{bmatrix} 
= 
\begin{bmatrix}
\operatorname{ad}_{(\cdot)}^*m & \operatorname{ad}_{(\cdot)}^*n \\
\operatorname{ad}_{(\cdot)}^*n& \operatorname{ad}_{(\cdot)}^*n
\end{bmatrix}
\begin{bmatrix}
    \xi_h\\
    \xi_k
\end{bmatrix}. \label{eq:euler_arnold_matrix}
\end{align}
Here, the positive/negative choice arises from whether the group acts on the left or the right. The diffeomorphism group acts by right action and corresponds to the upper choice of operation of $\pm,\mp$ in \cref{eq:euler_arnold,eq:euler_arnold_matrix}, and will be chosen as default throughout the rest of this paper for readability. One can diagonalise the co-adjoint matrix representation and the Lie-Poisson representation, as follows,
\begin{align}
- \partial_t
\begin{bmatrix}
    m-n\\
    n
\end{bmatrix} 
=
\begin{bmatrix}
\operatorname{ad}_{\xi_h}^*(\cdot) & 0\\
0&\operatorname{ad}_{\xi_h+\xi_k}^{*} (\cdot)
\end{bmatrix}
\begin{bmatrix}
    m-n\\
    n
\end{bmatrix}
= 
\begin{bmatrix}
\operatorname{ad}_{(\cdot)}^*(m-n) & 0 \\
        0       & \operatorname{ad}_{(\cdot)}^*n
\end{bmatrix}
\begin{bmatrix}
    \xi_h\\
    \xi_h+\xi_k
\end{bmatrix}. 
\label{eq:euler_arnold_matrix2}
\end{align}

