\section{Numerical Experiments}\label{sec:Numerical methodology}
We now turn back to the previous two examples, the Camassa-Holm equation and Euler's equation, to numerically model their self-semidirect product extensions in comparison with the direct product. 

\subsection{Geodesics on \texorpdfstring{$\operatorname{Diff}(S^1)\ltimes \operatorname{Diff}(S^1)$}{}}\label{sec:geodesics_on_diff_semi_diff}
The geodesic associated with $\operatorname{Diff}(S^1)\ltimes \operatorname{Diff}(S^1)$, with metric $\ell(u,v) = \frac{1}{2}\left( ||u||^2_{H^1_{\alpha}}+||v||^2_{H^1_{\beta}}\right)$, can be derived by combining \cref{sec: semidirect products,sec: volume preserving diffeomorphisms} and corresponds to a semidirect product coupled Camassa Holm - Camassa Holm (CHCH) system
\begin{align}
\partial_t m + (um)_x +u_x m + (vn)_x +v_x n &= 0,\label{eq:SDP_CH_1}\\
m - (u-\alpha^2 u_{xx}) &=0,\label{eq:SDP_CH_2}\\
\partial_t n  + ((u+v)n)_x +(u+v)_x n &= 0,\label{eq:SDP_CH_3}\\
n -( v - \beta^2 v_{xx}) &=0.\label{eq:SDP_CH_4}
\end{align}

This set of equations has been considered in \cite{escher2011euler}, where it is shown analytically that the system admits peakon solutions. We wish to verify this numerically and determine what type of nonlinear interactions occur between the peakons. By starting from non-peakon initial conditions, we investigate whether peakons are an emergent behaviour of the coupled system. We consider a Monolythic Continuous Galerkin(CG) Finite Element(FE) energy-preserving discretisation of the weak form of the above CHCH system, following the numerical approach in \cite{bendall2021perspectives}. 

Let $L^2(\Omega)$ denote the space of square integrable
functions on domain $\Omega$, whose norm and inner product are denoted $||\cdot||_{2},\langle a,b\rangle_{2}$. Let $H^1(\Omega)$ to refer to the Sobolev space $W^{1,2}(\Omega)$, whose norm and inner product are denoted $||\cdot||$, $\langle \cdot , \cdot \rangle_{H^1}$. Let $H^1_{\alpha}(\Omega)$ refer to a weighted Hilbert space with norm $||\cdot||_{H^1_{\alpha}} := \int u^2 + \alpha^2  u^2_x \mathrm{d}x$ with a weighted inner product
\begin{align}
\langle q, u\rangle_{H^{1}_{\alpha}} = \int qu + \alpha^2 q_x u_x \mathrm{d}x.
\end{align}


We define a weak solution $(m,u,n,v)\in [H^1(S^1)]^4 = V$ of the semidirect product system, by testing against arbitrary functions $(p,q,s,t) \in V$.
\begin{align}
\langle \partial_t m , p\rangle_{2} + \langle m u_x + n v_x, p \rangle_{2} - \langle  m u + n v, p_x \rangle_{2} &= 0,\quad \forall p \in H^1(S^1),\\
\langle m, q\rangle_{2} - \langle u, q\rangle_{H^{1}_{\alpha}}   &= 0, \quad \forall q \in H^1(S^1),\\
\langle \partial_t n, t\rangle_{2} + \langle  (u_x +v_x) n, t\rangle_{2} - \langle (u + v)n,t_x\rangle_{2} &= 0, \quad \forall t \in H^1(S^1),\\
\langle  n,s \rangle_{2} - \langle v,s\rangle_{H^{1}_{\beta}}  &= 0,\quad \forall s\in H^1(S^1).
\end{align}





To discretise in time we define the intermediate (implicit) variables, 
$m^{av} = \frac{1}{2}(m^{n+1} + m^{n})$,
$u^{av} = \frac{1}{2}(u^{n+1} + u^{n})$,
$n^{av} = \frac{1}{2}(n^{n+1} + n^{n})$,
$v^{av} = \frac{1}{2}(v^{n+1} + v^{n})$
and use a monolithic trapesium-rule time integration with first-order continuous Galerkin finite elements $
\text{CG}_{1}(\mathbb{T}):=\left\{v \in H^1(\mathbb{T}):\left.v\right|_K \in P_1(K),\quad \forall K \in \mathcal{M}_h\right\}
$. Where $\mathcal{M}_h$ denote an equispaced mesh of the periodic line $S^1=\mathbb{T}$ and $P_{i}(K)$ denote the $i$-th order polynomial, on the cell $K\in M$. 

\begin{align}
\langle ( m^{n+1}-m^{n})\Delta t^{-1} , p\rangle_{2} + \langle m^{av} u^{av}_x + n^{av} v^{av}_x, p \rangle_{2} - \langle  m^{av} u^{av} + n^{av} v^{av}, p_x \rangle_{2} &= 0,\quad \forall p \in \operatorname{CG}_1(\mathbb{T}),\\
\langle m^{n+1}, q\rangle_{2} - \langle u^{n+1}, q\rangle_{H^{1}_{\alpha}} &= 0, \quad \forall q \in \operatorname{CG}_1(\mathbb{T}),\\
\langle (n^{n+1}-n^{n})\Delta t^{-1}, t\rangle_{2} + \langle  (u^{av}_x +v^{av}_x) n^{av}, t\rangle_{2} - \langle (u^{av} + v^{av})n^{av},t_x\rangle_{2} &= 0, \quad \forall t \in \operatorname{CG}_1(\mathbb{T}),\\
\langle n^{n+1},s \rangle_{2} - \langle  v^{n+1},s\rangle_{H^{1}_{\beta}}  &= 0,\quad \forall s\in \operatorname{CG}_1(\mathbb{T}).
\end{align}


Where we have let $(m,u,n,v)\in \operatorname{CG}_1(\mathbb{T})^4$, and the test functions
$(q,p,s,t)\in \operatorname{CG}_1(\mathbb{T})^4$, and the inner products are understood in a discrete setting. 
Newton's iteration treats nonlinearity.
The initial conditions considered are 
$v = \frac{1}{5}\cosh(x-\frac{403}{15})$, $u =\frac{1}{2}\cosh(x-\frac{203}{15})$, and defined on the periodic interval $[0,40]$. The trapezium rule preserves quadratic invariants and the total energy of the system. The trapezium rule is doubly mutually conjugate to the symplectic implicit midpoint rule \cite{hairer2006geometric}. We consider parameters $\alpha = 1$, $\beta = \frac{1}{2}$, and use $1000$ elements, with a time increment of $\Delta t =0.0005$, over $nt = 64000$ timesteps. In order to facilitate a comparison, we also numerically solve the uncoupled direct-product $\operatorname{Diff}(S^1)\times \operatorname{Diff}(S^1)$ system
\begin{align}
\partial_t m + (u m)_x +u_x m &= 0,\label{eq:DP1}\\
m - (u-\alpha^2 u_{xx}) &=0,\label{eq:DP2}\\
\partial_t n  + (v n)_x +v_x n &= 0,\label{eq:DP3}\\
n -( v - \beta^2 v_{xx}) &=0,\label{eq:DP4}
\end{align}
using the same numerical method, parameters and initial conditions. Snapshots of the \textbf{\emph{direct product}} system \cref{eq:DP1,eq:DP2,eq:DP3,eq:DP4} are shown in \cref{FIG:DP_snapshots} as profiles in $(u,v)$ as the solution evolves, at $t = 0,4,8,...,32$. Snapshots of the \textbf{\emph{Semidirect}} product coupled system \cref{eq:SDP_CH_1,eq:SDP_CH_2,eq:SDP_CH_3,eq:SDP_CH_4} are shown in \cref{FIG:snapshots} as the solution evolves, at $t = 0,4,8,...,32$. Spacetime solution and energy-time plots of the \textbf{\emph{direct product}} system are plotted in \cref{fig:DP_CH-spacetime-and-energy}. Spacetime solution and energy-time plots of the \textbf{\emph{semidirect product}} system are plotted in \cref{fig:CH-spacetime-and-energy}.



