\section{Further extensions}\label{sec:Further extensions}
We will discuss how one can use the structure of the semidirect product of groups to infer the geodesic equations of centrally extended groups $\widehat{G}\ltimes \widehat{G}$, and semidirect product groups of the type $(G\ltimes V)\ltimes (G\ltimes V)$. 

\subsection{Central extension \texorpdfstring{$\widehat{G}$}{} and \texorpdfstring{$\widehat{G} \ltimes \widehat{G}$}{}}\label{sec: semidirect product of centrall extension}

The central extension of the Lie group $(G,\cdot_{G})$, by the normal abelian Lie group $(N,+)$ is denoted $(\widehat{G},\hat{\cdot})$ and is formalised in terms of a short exact sequence $0 \rightarrow N \xhookrightarrow{i} \widehat{G} \overset{s}{\rightarrow} G \rightarrow e_G$, where $\xhookrightarrow{i}$ denotes injective homomorphism, $\overset{s}{\rightarrow}$ denotes surjective homomorphism, $0$ is the identity of $N$, $e_G$ is the identity of $G$. Such that the normal subgroup $N$ lies in the centre, where the centre of $G$ is defined as $\mathrm{Z}(G)=\lbrace z \in G | \quad \forall g \in G, z g=g z\}$, such that $N$ is invariant under left conjugation by group action (inner automorphism). The group multiplication structure is given by
\begin{align}
(g,a)\hat{\cdot}(h,b) = (gh,a + b + \Sigma(g,h)),\quad g,h\in G,\quad a,b \in \mathbb{R}.\label{eq:group product central extension}
\end{align}

Conditions on $\Sigma:G\times G \mapsto N$ are required for the centrally extended group to satisfy the usual group axioms.
\begin{proposition}\label{proposition:necessary sufficient conditions}
It is necessary and sufficient  for $\Sigma$, to satisfy the 2-co-boundary condition $\Sigma(h, e)=\Sigma(e, h)=\Sigma(e,e) = 0$ for the group $\widehat{G}$ to have identity. It is necessary and sufficient that $\Sigma\left(f, f^{-1}\right)=\Sigma\left(f^{-1},f\right)$ for all $f \in G$ for $\widehat{G}$ to have inverse.
Associativity of $\widehat{G}$ requires $\Sigma$ to satisfy the following group 2-cocycle identity
\begin{align}
\Sigma(g,h)+\Sigma(f,gh) = \Sigma(f,g)+\Sigma(fg,h). \label{eq:2cocycle identity}
\end{align}
\end{proposition}
\begin{proof}
These facts are known \cite{cendra2001lagrangian}, the details for necessary and sufficient conditions are presented in \cref{sec:GroupAxiomsCentral}.
\end{proof}



\begin{proposition}[AD-Ad-ad-joint relations on a centrally extended group and coadjoint representation.]\label{thm:Ad-central-extension}
Let $(g,a)\in \widehat{G}$, $(h,b)\in \widehat{G}$. Let $(\eta,\beta) = \frac{d}{d\epsilon}\big|_{\epsilon=0}(h_{\epsilon},b_{\epsilon})\in \widehat{\mathfrak{g}}$, $(\xi,\alpha) = \frac{d}{ds}\big|_{s=0}(g_{s},a_{s})\in \widehat{\mathfrak{g}}$ belong in the Lie algebra of $\widehat{G}$ denoted $\widehat{\mathfrak{g}} = \mathfrak{g}\oplus \mathfrak{n}$. 
Assuming the pairing between Lie-algebra and its dual as
$\langle (\xi,\alpha),(m,n)\rangle_{\widehat{\mathfrak{g}}^*} = \langle \xi,m\rangle_{\mathfrak{g}^*} + \langle \alpha ,n\rangle_{\mathfrak{n}}$. Then the adjoint and coadjoint operators are given by  
\begin{align}
\operatorname{AD}_{(g,a)}(h,b)&:= (g,a)(h,b)(g,a)^{-1} = (ghg^{-1}, b + \Sigma(g,h) -\Sigma(g,g^{-1})+ \Sigma(gh,g^{-1})), \label{eq:ADCE}\\
\operatorname{Ad}_{(g,a)}(\eta,\beta) & = (\operatorname{Ad}_{g} \eta , \beta + \partial_{2} \Sigma(g,e_G)\cdot \eta + \partial_1\Sigma(g,g^{-1})\cdot g \cdot \eta ),\label{eq:AdCE}\\
\operatorname{ad}_{(\xi,\alpha)}(\eta,\beta) &= [(\xi,\alpha),(\eta,\beta)]_{\widehat{\mathfrak{g}}} = ([\xi,\eta]_{\mathfrak{g}}, \sigma(\xi,\eta)),\label{eq:adCE}\\
\operatorname{ad}^{*}_{(\xi,a)}(m,n) &=  (\operatorname{ad}_{\xi}^{*}m + \sigma^*(\xi,n),0).\label{eq:coadCE}
\end{align}
In these equations, $[\xi,\eta]_{\mathfrak{g}}$ denotes the Lie algebra bracket (the negative commutator of vector-fields if $G$ is the diffeomorphism group), $\Sigma(g,h)$ denotes the group 2-cocycle and $\sigma(\xi,\eta):\mathfrak{g}\times\mathfrak{g}\rightarrow \mathfrak{n}$ is the Lie algebra 2-cocycle. The Lie algebra 2-cocycle can sometimes be related or calculated from a group 2-cocycle by the relation 
\begin{align}
    \sigma(\xi,\eta) = \partial_1 \partial_2 \Sigma(e_G,e_G) \cdot \eta \cdot\xi  - \partial_2\partial_1 \Sigma(e_G,e_G) \cdot\eta \cdot\xi 
    \label{eq:2cocycle-algebra-group-relationship}
    \end{align}
    where 
\begin{align}
& \partial_1 \partial_2 \Sigma(e_G,e_G) \cdot \eta \cdot \xi=\left.\left.\frac{\partial}{\partial t}\right|_{t=0} \frac{\partial}{\partial s}\right|_{s=0} \Sigma(g_t, h_s), \quad \partial_2 \partial_1 \Sigma(e_G,e_G) \cdot \eta \cdot \xi=\left.\left.\frac{\partial}{\partial t}\right|_{t=0} \frac{\partial}{\partial s}\right|_{s=0} \Sigma(h_s,g_t) .
\end{align}
Here we have used $e_G$ to denote the identity of $G$, and $\cdot$ denotes multiplication.
Note that the Lie algebra 2-cocycle $\sigma:\mathfrak{g}\times\mathfrak{g}\rightarrow \mathfrak{n}$ may exist without a corresponding group 2-cocycle. See, e.g., \cite{kriegl1997convenient} pg 506. In this case, the Lie algebra 2-cocycle is defined as algebraically satisfying sufficient conditions for the Lie algebra extension $\widehat{\mathfrak{g}}$, to remain a Lie algebra. Namely, the bilinear map $\sigma: \mathfrak{g} \times \mathfrak{g} \rightarrow \mathfrak{n}$ must be continuous, skew-symmetric and satisfy the 2-Cocycle condition 
\begin{align}
\sigma(u,[v,w]) + \sigma(v,[w,u]) + \sigma(w,[u,v]) = 0 , \quad \forall u,v,w \in \mathfrak{g} \label{eq:Algebra-2cocycle-Jacobi},
\end{align}  
which is equivalent to the centrally extended algebra satisfying Jacobi's identity.
The coadjoint contribution of the centrally extended algebra 2-cocycle is denoted $\sigma^*$ and is defined through the pairing 
\begin{align}
\langle (0, \sigma(\xi,\eta)),(m,n)\rangle_{\widehat{\mathfrak{g}}^*} = \langle n,\sigma(\xi,\eta)\rangle_{\mathfrak{n}}= \langle (\sigma^*(\xi,n),0),(\eta,\beta)\rangle_{\widehat{\mathfrak{g}}^*}. \label{eq:coadjoint contribution calculation}
\end{align} 
\end{proposition}
Proposition \ref{thm:Ad-central-extension} is exemplified in the following series of direct calculations, using a collection of standard material  \cite{michor1998geometry,arnol'd2009topological,cendra2001lagrangian,arnold2014topological,kriegl1997convenient}. Using the definition of the inverse \cref{eq:Inverse Group extension} and group action \cref{eq:group product central extension}, we attain
the ADjoint action as
\begin{align}
\operatorname{AD}_{(g,a)}(h,b) = (ghg^{-1},  b + \Sigma(g,h) -\Sigma(g,g^{-1})+ \Sigma(gh,g^{-1})),
\end{align} 
given in \cref{eq:ADCE}.
The Ad-joint action \cref{eq:AdCE} is derived, by linearising the ADjoint action \cref{eq:ADCE} on the identity of the group,
\begin{align}
\operatorname{Ad}_{(g,a)}(\eta,\beta) = \frac{d}{d\epsilon}\bigg|_{\epsilon=0} \operatorname{AD}_{(g,a)}(h(\epsilon),b(\epsilon))\quad\text{where}\quad (\eta,\beta) = (\dot{h}(0),\dot{b}(0)) \in \widehat{\mathfrak{g}}.
\end{align}
This is computed by using the chain rule to differentiate the 2-cocycle, where $h(0)=e_G$, $b(0)=0$, and $\partial_{1}\Sigma$, $\partial_{2}\Sigma$ denotes the partial derivative in the first and second component of the group 2-cocycle
\begin{align}
\frac{d}{d\epsilon} \bigg|_{\epsilon=0}\Sigma(g,h_{\epsilon}) &= \partial_{2} \Sigma(g,e_G)\cdot \eta, \quad \frac{d}{d\epsilon} \bigg|_{\epsilon=0}\Sigma(gh_{\epsilon},g^{-1}) = \partial_1\Sigma(g,g^{-1})\cdot g \cdot \eta .
\end{align}
Giving
\begin{align}
\operatorname{Ad}_{(g,a)}(\eta,\beta) = (\operatorname{Ad}_g \eta, \beta + \partial_{2} \Sigma(g,e_G)\cdot \eta + \partial_1\Sigma(g,g^{-1})\cdot g \cdot \eta ).
\end{align}

The adjoint action \cref{eq:adCE} is computed by differentiating \cref{eq:AdCE} as follows, 
\begin{align}
\operatorname{ad}_{(\xi,\alpha)}(\eta,\beta) = \frac{d}{d\epsilon}\bigg|_{\epsilon=0} \operatorname{Ad}_{(g_{\epsilon}
,a_{\epsilon})}(\eta,\beta)\quad\text{where}\quad (\xi,\alpha) = (\dot{g}(0),\dot{a}(0)) \in \widehat{\mathfrak{g}}.
\end{align}

From direct calculation one derives the adjoint relationship 
\begin{align}
\operatorname{ad}_{(\xi,\alpha)}(\eta,\beta) = \left(\operatorname{ad}_{\xi} \eta, \partial_1 \partial_2  \Sigma(e_G,e_G) \cdot \eta \cdot\xi  + \partial_1\partial_1 \Sigma(e_G,e_G) \cdot \eta \cdot \xi -\partial_2\partial_1 \Sigma(e_G,e_G) \cdot\eta \cdot\xi +\partial_1 \Sigma(e_G,e_G)\cdot \xi \cdot \eta \right).
\end{align}
Taking the derivative of the 2-co-boundary condition $\Sigma(g_{\epsilon},e_G) = \Sigma(h_{\epsilon},e_G)=0$, reveals the identities
\begin{align}
\partial_1 \Sigma(e_G,e_G)\cdot \eta=\partial_1 \Sigma(e_G,e_G)\cdot \xi  = 0.
\end{align}
Simplifying the adjoint relationship to the following
\begin{align}
\operatorname{ad}_{(\xi,\alpha)}(\eta,\beta) = (\operatorname{ad}_{\xi}\eta , \partial_1 \partial_2  \Sigma(e_G,e_G) \cdot \eta \cdot\xi  - \partial_2\partial_1 \Sigma(e_G,e_G) \cdot\eta \cdot\xi ),
\end{align}
and can be denoted as follows
\begin{align}
\operatorname{ad}_{(\xi,\alpha)}(\eta,\beta) = [(\xi,\alpha),(\eta,\beta)]_{\widehat{\mathfrak{g}}} = ([\xi,\eta]_{\mathfrak{g}}, \sigma(\xi,\eta)) = (\operatorname{ad}_{\xi} \eta, \sigma(\xi,\eta)).
\label{co-cycle ad notation}\end{align} 
Defining $\sigma^{*}(\xi,n):\mathfrak{g}\times \mathfrak{n}^{*}\rightarrow\mathfrak{g}^{*}$ as the coadjoint contribution of the 2-cocycle (\cref{eq:coadjoint contribution calculation}), one can compute
\begin{align}
\langle (m,n), \operatorname{ad}_{(\xi,a)}(\eta,\beta)\rangle_{\widehat{\mathfrak{g}}} &= \langle m , \operatorname{ad}_{\xi}\eta \rangle_{\mathfrak{g}} + \langle n, \sigma(\xi,\eta)\rangle_{\mathfrak{n}} \\
&= \langle \operatorname{ad}_{\xi}^{*}m + \sigma^*(\xi,n), \eta \rangle_{\mathfrak{g}} \\
&= \langle \operatorname{ad}_{\xi}^{*}m + \sigma^*(\xi,n), \eta \rangle_{\mathfrak{g}} + \langle 0 , \beta \rangle_{\mathfrak{n}} \\
&= \langle (\operatorname{ad}_{\xi}^{*}m + \sigma^*(\xi,n) , 0) , (\eta, \beta) \rangle_{\widehat{\mathfrak{g}}} 
\end{align}
to deduce the central extension equips the usual coadjoint operator with  $\sigma^*$ as follows, 
\begin{align}
\operatorname{ad}^{*}_{(\xi,a)}(m,n) =  (\operatorname{ad}_{\xi}^{*}m + \sigma^*(\xi,n),0).
\end{align}


The Euler-Poincaré variational principle for a centrally extended algebra is calculated, as follows.

\begin{align}
0 & =\delta \int \ell(u, a) d t  =\int\left\langle\frac{\delta \ell}{\delta(u, a)}, \delta(u, a)\right\rangle_{\widehat{\mathfrak{g}}^* \times \widehat{\mathfrak{g}}} d t \\
&=\int\left\langle\frac{\delta \ell}{\delta(u, a)}, \frac{d}{d t}(v, b)-\operatorname{a d}_{(u, a)}(v, b)\right\rangle d t \\
& =\int\left\langle-\frac{d}{d t} \frac{\delta \ell}{\delta(u, a)}-\operatorname{a d}_{(u, a)}^* \frac{\delta \ell}{\delta(u, a)},(v, b)\right\rangle d t+\left.\left\langle(v, b), \frac{\delta \ell}{\delta(u, a)}\right\rangle\right|_ 0 ^T \\
& =\int\left\langle-\frac{d}{d t}\left(\frac{\delta \ell}{\delta u}, \frac{\delta \ell}{\delta a}\right)-\operatorname{a d}_{(u, a)}^*\left(\frac{\delta \ell}{\delta u}, \frac{\delta \ell}{\delta a}\right),(v, b)\right\rangle d t+\left.\left\langle(v, b),\left(\frac{\delta \ell}{\delta u}, \frac{\delta \ell}{\delta a}\right)\right\rangle\right|_ 0 ^T
\end{align}

Here, the momentum is $(m, c)=\left(\frac{\delta \ell}{\delta u}, \frac{\delta \ell}{\delta a}\right)$ and the Euler-Poincaré equations are given by $\frac{d}{d t}(m, c) + \operatorname{ad}_{(u, a)}^*(m, c)=0$. By using \cref{co-cycle ad notation}, one finds
\begin{align}
    \frac{d}{dt} m + \operatorname{ad}^{*}_{\xi} m +\sigma^{*}(\xi,c) = 0
    \quad \hbox{and} \quad \frac{d}{dt}c= 0.
\label{eq:EP-centrally etended}
\end{align}


\begin{remark}
In matrix form \cref{eq:coadCE,eq:EP-centrally etended} can be written as a coadjoint operator acting on the dual space or in Lie Poisson form on the Lie algebra, as follows
\begin{align}
\left(\operatorname{ad}^{*}_{(\xi,a)}(m,n)\right)^{T} = 
\begin{bmatrix}
\operatorname{ad}^{*}_{\xi}(\cdot) &\sigma^{*}(\xi , \cdot)\\
0&0
\end{bmatrix}
\begin{bmatrix}
m\\
n
\end{bmatrix}
= 
\begin{bmatrix}
\operatorname{ad}^{*}_{(\cdot)}m+\sigma^{*}(\cdot,n)&0\\
0&0
\end{bmatrix}
\begin{bmatrix}
\xi\\
a
\end{bmatrix}.
\end{align}
\end{remark}
We can inspect the coadjoint and Lie-Poisson structure for the semidirect product $(\widehat{G}\ltimes \widehat{G})$ Euler-Poincaré equations following \cref{sec: semidirect products} 
as follows
\begin{align}
\frac{d}{dt}
\begin{bmatrix}
m\\
l\\
n\\
o
\end{bmatrix}
&= -
\begin{bmatrix}
\operatorname{ad}_{(\cdot)}^*m + \sigma^*(\cdot,l)& 0& \operatorname{ad}_{(\cdot)}^*n + \sigma^*(\cdot,o)&0\\
0&0&0&0\\
\operatorname{ad}_{(\cdot)}^*n+ \sigma^*(\cdot,o)& 0&\operatorname{ad}_{(\cdot)}^*n+ \sigma^*(\cdot,o)&0\\
0&0&0&0
\end{bmatrix}
\begin{bmatrix}
    \xi_h\\
    \alpha\\
    \xi_k \\
    \beta
\end{bmatrix}
= -
\begin{bmatrix}
\operatorname{ad}^{*}_{\xi_{h}}(\cdot) &
\sigma^{*}(\xi_h,\cdot)
&\operatorname{ad}^{*}_{\xi_{k}}(\cdot)
&\sigma^{*}(\xi_k,\cdot)\\
0&0&0&0\\
0&0&\operatorname{ad}^{*}_{\xi_{h}+\xi_{k}}(\cdot)& \sigma^*(\xi_{h} + \xi_{k},\cdot)\\
0&0&0&0
\end{bmatrix}
\begin{bmatrix}
m\\
l\\
n\\
o
\end{bmatrix}\label{eq:semidirectproduct_of_central_extension}
\end{align}



\subsection{Example 0: Geodesics on \texorpdfstring{$\widehat{\operatorname{Diff}}(S^1)$}{}}\label{sec:Example 0: Geodesics}
It is known, that the diffeomorphism group on the circle admits the central extension
$
\widehat{\operatorname{Diff}}(S^1)=\operatorname{Diff}\left(S^1\right) \times S^1
$, through the Thurston-Bott group 2-cocycle \cite{bott1977characteristic}, 
\begin{align}
\Sigma\left(g_1, g_2\right):=\frac{1}{2} \int_{S^1} \log \left(\frac{\partial}{\partial x}\left(g_1 \circ g_2\right)\right) \mathrm{d} \log \left(\frac{\partial g_2}{\partial x}\right). \label{eq:TB-2cocycle}
\end{align}
The Virasoro algebra $\mathfrak{vir}(S^1) = \operatorname{Vect}(S^1)\oplus S^1$ is a unique (up to isomorphism) non-trivial (modulo 2-co-boundaries) central extension of $\operatorname{Vect}(S^1)$, it also is the Lie algebra of the Lie group $\widehat{\operatorname{Diff}}\left(S^1\right)$. The Virasoro algebra has the Gefland-Fuchs algebra 2-cocycle \begin{align}
\sigma(\xi,\eta) = \int_{S^1} \xi_x \eta_{xx}\mathrm{d} x.  \label{eq:GF-2cocycle}
\end{align}
The relationship between the Thurston-Bott group 2-cocycle $\Sigma$, and the Gefland-Fuchs algebra 2-cocycle $\sigma$ is given in \cref{eq:2cocycle-algebra-group-relationship} and calculated explicitly in \cite{khesin2009geometry} (proposition 2.4). By direct calculation (integration by parts) under the pairing in \cref{eq:coadjoint contribution calculation}, the coadjoint contribution of the algebra 2-cocycle is 
\begin{align}
    \sigma^{*}(\xi,n) = n\xi_{xxx}.
\end{align} 
This is well established, see for example \cite{holm2018new,segal1991geometry,ovsienko1987korteweg,michor1998geometry,holm2018new,khesin2009geometry}, and leads to the following equation
\begin{align}
\partial_t m + (um)_x + u_x m + lu_{xxx} =0,
\quad m = \frac{\delta \ell}{\delta u}.
\end{align}
Where $\partial_t l = 0$, examples include the KdV and Camassa-Holm wave models.



