\begin{align}
\partial_t {m} + (um)_x + u_x m + lu_{xxx} + (vn)_x + v_x n + o v_{xxx} = 0, \quad
\partial_t{l}=0,\\
\partial_t{n} + ((u+v)n)_x + (u+v)_x n + o (u+v)_{xxx} = 0, \quad \partial_t{o}=0.
