\subsection{Semidirect products \texorpdfstring{$G\ltimes V$}{}, and \texorpdfstring{$(G\ltimes V)\ltimes (G\ltimes V)$}{}} \label{sec:semi_direct_GV}

Adjoint actions associated with the group $G\ltimes V$ can be found in detail in \cite{marsden1984semidirect,guillemin1982geometric}, we briefly recall how these are used in the construction of the Euler-Poincaré equations on $G\ltimes V$, as to introduce notation required for its further self-semidirect product extension. 


Let $G$ be a Lie group acting on the left on the vector space $V$. The outer semidirect product group $G\ltimes V$ can be constructed from the semidirect product group action
\begin{align}
(g,v)\cdot_{\ltimes} (h,w) = (g h,v + g w).
\end{align}
Where we employ concatenation notation to denote left group action of $G$ on $G$ by $gh := g\cdot_{G}h$, and $gw=g\cdot w = \rho(g)w$, is the left action of $G$ on $V$. The identity of the group is $(e_G,0)$. The inverse of the group is $(g^{-1},-g^{-1}v)$. One can directly compute the $\operatorname{AD}$joint action
\begin{align}
\operatorname{AD}_{(g,v)}(h,w) = (g,v)\cdot_{\ltimes} (h,w)\cdot_{\ltimes}(g^{-1},-g^{-1}v) &= (ghg^{-1}, v+g\cdot w + (gh)\cdot (-g^{-1}\cdot v))\\
&= (\operatorname{AD}_{g}h, v+ g\cdot w - (\operatorname{AD}_{g}h) \cdot v ).
\end{align}
We have used the fact that the left representation $\rho$ has the following property
\begin{align}
\rho(g_1)\rho(g_2)v = \rho(g_1 g_2)v.
\end{align}

By differentiating $\operatorname{AD}_{(g,v)}(h(t),w(t))$, with respect to $t$, and evaluating at $t=0$, where $(h(0),w(0)) = (e_G,0)$ is the identity of the group, and $(\dot{h}(0),\dot{w}(0)) = (\eta_{h},\eta_{w})\in \mathfrak{g}\ltimes V$ is in the algebra we can find the $\operatorname{Ad}$joint representation of the group on the algebra,
\begin{align}
\operatorname{Ad}_{(g,v)}(\eta_{h},\eta_{w}) = (\operatorname{Ad}_{g}\eta_{h}, g\cdot \eta_{w} - \operatorname{Ad}_{g}\eta_{h} \cdot v),
\end{align}
where the first dot in $g\cdot \eta_{w}$ denotes how $G$, acts on $V$, specified by the representation $\rho$. The second dot denotes how $\mathfrak{g}$ acts on $V$, this is an induced representation denoted $\alpha$. 
We now denote the left representation of the group on the vector space, and the induced Lie algebra representation on the vector space as follows,
\begin{align}
\rho: G \times V \rightarrow V, \quad  \rho (g, v) = \rho (g) v = (g \cdot v),\\
\alpha: \mathfrak{g} \times V \rightarrow V,\quad \alpha (\eta, v)= \alpha(\eta) v=(\eta \cdot v).
\end{align}

Next we compute the adjoint action
\begin{align}
\operatorname{ad}_{(\xi_g,\xi_v)}(\eta_h,\eta_w) &= \frac{d}{dt}\bigg|_{t=0} \operatorname{Ad}_{(g(t),v(t))}(\eta_h,\eta_w) \\ 
&=\frac{d}{dt}\bigg|_{t=0}\left( \operatorname{Ad}_{g(t)}\eta_h , g(t) \cdot \eta_{w} - (g(t)\eta_h g^{-1}(t)) \cdot v(t) \right),\\
&= (\operatorname{ad}_{\xi_g}\eta_h, \xi_{g}\cdot \eta_{w} - \frac{d}{dt}\bigg|_{t=0}(g(t)\eta_h g^{-1}(t)) \cdot v(t))\\
&= (\operatorname{ad}_{\xi_g}\eta_h, \xi_{g}\cdot \eta_{w} - \alpha([\xi_g,\eta_h]) 0 - \eta_h  \cdot \xi_v)\\
&= (\operatorname{ad}_{\xi_g}\eta_h , \xi_{g}\cdot \eta_{w} - \eta_h  \cdot \xi_v)
\end{align}
Where the induced Lie algebra representation on the vector space identity element gives no contribution. For notational convenience denote $\xi_v,\eta_w = v,w\in V$ and $\xi_g,\eta_h=\xi,\eta \in \mathfrak{g}$, and write the adjoint action as
\begin{align}
\operatorname{ad}_{(\xi,v)}(\eta,w)  
&= (\operatorname{ad}_{\xi}\eta , \xi \cdot w -\eta \cdot v).
\end{align}

Let $(m,n)\in \mathfrak{g}^{*}\times V^*$, $(\xi,v)\in \mathfrak{g}\times V$, $(\eta,w)\in \mathfrak{g}\times V$,
then defining $\diamond:V^*\times V\mapsto \mathfrak{g}$ as the operator satisfying $\langle n,\alpha(\eta)v\rangle_{V^*\times V} = -\langle n\diamond v,\eta \rangle_{\mathfrak{g}^*\times\mathfrak{g}}$ and denote $\alpha^*:\mathfrak{g}\times V^* \mapsto V^*$ as the operator satisfting $\langle n,\alpha(\xi)w\rangle_{V^*\times V} = \langle \alpha^*(\xi)n,w\rangle_{V^*\times V}$, then with the pairing 
\begin{align}
\langle (m,n),(\xi,v) \rangle_{\mathfrak{g}\times V} = \langle m,\xi \rangle_{\mathfrak{g}} + \langle n,v \rangle_{V},
\end{align}
one attains the coadjoint motion
\begin{align}
\langle \operatorname{ad}^{*}_{\xi,v}(m,n),(\eta,w)\rangle &= \langle (m,n),\operatorname{ad}_{\xi,v}(\eta,w) \rangle\\
&=\langle (m,n),(\operatorname{ad}_{\xi}\eta , \xi \cdot w -\eta \cdot v)\rangle\\
&=\langle m ,\operatorname{ad}_{\xi}\eta\rangle +\langle n, \xi \cdot w -\eta \cdot v)\rangle\\
&=\langle m ,\operatorname{ad}_{\xi}\eta\rangle_{\mathfrak{g}^*\times \mathfrak{g}} +\langle n, \alpha(\xi) w\rangle_{V^*\times V} -\langle n,\alpha(\eta)v\rangle_{V^*\times V}\\
&=\langle \operatorname{ad}^*_{\xi} m ,\eta\rangle_{\mathfrak{g}^*\times \mathfrak{g}} +\langle \alpha^*(\xi)n,  w\rangle_{V^*\times V} + \langle n \diamond v,\eta\rangle_{\mathfrak{g}^*\times \mathfrak{g}}\\
&=\langle (\operatorname{ad}^*_{\xi} m +n \diamond v ,\alpha^*(\xi)n ),(\eta,w)\rangle_{(\mathfrak{g}^*\times V^*)\times(\mathfrak{g}\times V)}
\end{align}


The contragradient representation $\alpha^*$ of $\xi\in \mathfrak{g}$ on $n\in V^*$ and the $\diamond:V^*\times V\mapsto \mathfrak{g}^*$ operator are typically determined in a case-by-case setting, dependent on the Lie algebra and vector space. 
%One can derive $\diamond$ must be anti-symmetric, through an integration by parts.

% For example if $G=\operatorname{SDiff}(M)$, the induced representation of $\mathfrak{g}=\operatorname{SVect}(M)$ on $V=C^{\infty}(M)$ is the Lie derivative, such that the contragradient representation is the negative Lie derivative acting upon densities (divergence), this is verifiable by an integration by parts. Note that the group action is by right, and
\begin{remark}
In matrix form the coadjoint operator \cref{eq:coadCE} can be written as acting on the dual space $\mathfrak{g}^* \ltimes V^*$ or in Lie Poisson form on $\mathfrak{g} \ltimes V$ as follows
\begin{align}
\left(\operatorname{ad}^{*}_{(\xi,v)}(m,n)\right)^{T} = 
\begin{bmatrix}
\operatorname{ad}^{*}_{\xi}(\cdot) & (\cdot)\diamond v\\
0&\alpha^*(\xi)(\cdot)
\end{bmatrix}
\begin{bmatrix}
m\\
n
\end{bmatrix}
= 
\begin{bmatrix}
\operatorname{ad}^{*}_{(\cdot)}m& n \diamond (\cdot) \\
\alpha^*(\cdot)n&0
\end{bmatrix}
\begin{bmatrix}
\xi\\
v
\end{bmatrix}.
\end{align}
\end{remark}



% \begin{remark}
% To derive symmetry broken Euler-Poincaré-Poisson equations \cite{holm1998euler}, one replaces the momentum $n$ with an element of the co-vector space. Since $\rho(g)$ and $\alpha(g)$ acts on element of $\mathfrak{g}^*$ and $V^*$, in the same way. One replaces $n= \frac{\delta \ell}{\delta v}\in \mathfrak{g}^*$ with a chosen element $n=n \in V^*$, to get symmetry broken EP equations. 
