\subsection{Group Homomorphism}

A fundamental construction in this work is a group homomorphism, it is defined as follows.
\begin{definition}[Group Homomorphism]\label{def:group homomorphism}
Let $(H,\cdot_H)$,$(K,\cdot_K)$ be groups, a Group Homomorphism from $(H,\cdot_H)$, to $(K,\cdot_K)$, is a function $\phi:H\rightarrow K$, such that $\forall h_1,h_2\in H$ we have
\begin{align}
    \phi(h_1\cdot_H h_2) = \phi(h_1)\cdot_K \phi(h_2).
\end{align}
\end{definition}
Group Homomorphisms inherit the following properties, 
\begin{enumerate}
    \item $\phi\left(e_H\right)=e_K$.
    \item $\phi\left(h^{-1}\right)=\phi(h)^{-1}$.
\end{enumerate}
from the group homomorphism property. $\phi$ maps the unit element $e_H$ of $H$ to the unit element $e_K$ of $K$, this property follows from the homomorphism property $
\phi \left(e_H\right)=\phi\left(e_H \cdot_{H} e_H\right)=\phi\left(e_H\right) \cdot_K \phi \left(e_H\right)
$. $\phi$ maps the inverse in $H$ to inverse in $K$, this follows from the previous property since
$
\phi(h) \cdot_{K} \phi\left(h^{-1}\right)=\phi\left(h \cdot_{H} h^{-1}\right)=\phi\left(e_H\right)=e_K.$


\subsection{Group Axioms: Centrally extended group}\label{sec:GroupAxiomsCentral}
We verify that group 2-cocycle conditions on $\Sigma$, are necessary and sufficient for $\widehat{G}$ to satisfy the group axioms. 
\begin{enumerate}
\item Identity. 
For $(g,b)$ to be the left and right identity of $\widehat{G}$, the following conditions must hold
\begin{align}
(f,a)=(f,a)\hat{\cdot}(g,b) = (fg,a+b+\Sigma(f,g)) \iff g=e_G,\quad \text{and}\quad b=-\Sigma(f,e),\\
(f,a)= (g,b)\hat{\cdot}(f,a) = (gf,b+a + \Sigma(g,f)) \iff g=e_G,\quad \text{and} \quad b = -\Sigma(e,f).
\end{align}
Therefore $-b=\Sigma(f,e)=\Sigma(e,f),\quad\forall f\in G$. Consider the following property of the identity
\begin{align}
(e,-\Sigma(e,f)) = (e,-\Sigma(e,f))\hat{\cdot}(e,-\Sigma(e,f)) = (ee,-\Sigma(e,f) -\Sigma(e,f) + \Sigma(e,e))\quad \iff \quad \Sigma(e,e)=\Sigma(e,f).
\end{align} 
Therefore $(e,-\Sigma(e,e))$ is the identity, and $-b=\Sigma(e,e)=\Sigma(e,f)=\Sigma(f,e)$. Now consider the element $(e,0)\in \widehat{G}$.
\begin{align}
(e,0)= (e,0)\hat{\cdot}(e,-\Sigma(e,e)) = (e,-\Sigma(e,e)).
\end{align}
So that $\Sigma(e,e)= 0 = \Sigma(e,f)=\Sigma(f,e)$ is a neccessary and sufficient condition on the Group 2-cocycle for the group $\widehat{G}$ to have a unique identity element
\begin{align}
e_{\widehat{G}} = (e_G,0)
\end{align}. 

\item Inverse. 
From the group composition $(f,a)\hat{\cdot}(g,b) = (fg,a+b+\Sigma(f,g))$, right identity of $(g,b)$ requires $g=f^{-1}$, and then $a+b+\Sigma(f,f^{-1})=0$. Left identity of $(g,b)\hat{\cdot}(f,a) = (gf,b+a+\Sigma(g,f))$ requires $g = f^{-1}$ and $0=b+a+\Sigma(f^{-1},f)$. Therefore, since
$b = -a -\Sigma(f,f^{-1})$ and $b = -a -\Sigma(f^{-1},f)$, we must require that for uniqueness of the inverse $\Sigma(f^{-1},f)=\Sigma(f,f^{-1})$.
So the inverse is \begin{align}
(f,a)^{-1}  = (f^{-1},-a - \Sigma(f,f^{-1}))\in \widehat{G}. \label{eq:Inverse Group extension}
\end{align}
\item Associativity. Associativity in $\widehat{G}$ requires
\begin{align}
(f,a)\hat{\cdot}((g,b)\hat{\cdot}(h,c)) = ((f,a)\hat{\cdot}(g,b))\hat{\cdot}(h,c) \label{eq:associativity of central extension}
\end{align}
Consider the right hand side of \cref{eq:associativity of central extension} 
\begin{align}
(fg,a+b+\Sigma(f,g))\hat{\cdot}(h,c) = (fgh,a+b+c+\Sigma(f,g)+\Sigma(fg,h))
\end{align}
and equate it to the left hand side of \cref{eq:associativity of central extension}, 
\begin{align}
 (f,a)\hat{\cdot}(gh,b+c+\Sigma(g,h)) = (fgh,a+b+c+\Sigma(g,h)+\Sigma(f,gh))
\end{align}
observe the 2cocycle condition \cref{eq:2cocycle identity}.
\end{enumerate} 


\subsection{Group Axioms: Semidirect product group}\label{sec:group-axioms}
We verify that group identity, inverse and associativity of the semidirect product group
\begin{enumerate}
    \item Identity. $e_{G} = (e_H,e_K)$, is the identity, as can be verified through the group homomorphism properties 
\begin{align}
(e_H,e_K)\cdot_{\ltimes}(h,k) = (e_{H}\cdot_{H} H , e_K \cdot_{K}\phi_{e_H}k)= (h,k) \\
(h,k)\cdot_{\ltimes}(e_H,e_K) = (h\cdot_{H}e_H , k \cdot_{K}\phi_{h}e_k)= (h,k) 
\end{align}
\item Inverse.
The inverse can be infered from the group multiplication structure \cref{eq:group product structure}
\begin{align}
    g^{-1} = (h,k)^{-1} = (h^{-1},h^{-1}\cdot k^{-1}) \label{eq:inverse}
\end{align}
The right inverse property is verified using \cref{eq:property1} as follows
$gg^{-1} = (h,k)(h^{-1},h^{-1}\cdot k^{-1}) = (e,k (h\cdot (h^{-1}\cdot k^{-1}))) = (e,e)$. The left inverse property is verified using \cref{eq:property2} as follows $g^{-1}g = (h^{-1},h^{-1}\cdot k^{-1})(h,k) = (e,h^{-1}\cdot k^{-1}(h^{-1} \cdot k) )= (e,(h^{-1}\cdot k^{-1})(h^{-1} \cdot k ) ) = (e,e)$. 
\item Associativity.
The group associativity property holds by direct computation
\begin{align}
g_1(g_2 g_3) &= g_1(h_2,k_2)(h_3,k_3) = g_1 (h_2 h_3 , k_2 (h_2 \cdot k_3) ) =  (h_1 h_2 h_3 , k_1 h_1 \cdot ( k_2 (h_2 \cdot k_3) ) ) \\
(g_1 g_2) g_3 &= (h_1,k_1)(h_2,k_2)g_3 = (h_1 h_2 , k_1 (h_1 \cdot k_2))g_3
= (h_1 h_2 h_3 , k_1 (h_1 \cdot k_2) (h_1 h_2 \cdot k_3)), \label{eq:SDP_associativity_eq2}
\end{align}
the right hand sides are equivalent under the use of \cref{eq:property2}. 
\end{enumerate}

\subsection{Adjoint calculations for a semidirect product of groups}\label{sec:adjoints for H semi K}


\begin{proposition}
[AD-Ad-adjoint for semidirect product of groups]
Let $G=H\ltimes K$, then the AD-Ad-ad-joint actions are
\begin{align}
\operatorname{AD}_{(h_1,k_1)}(h_2,k_2)
&= (\operatorname{AD}_{h_1}h_2,k_1 \cdot_{K} (\phi_{h_1} k_2 ) \cdot_{K}(\phi_{\operatorname{AD}_{h_{1}} h_{2} } k_{1}^{-1} )),\label{eq:AD_new1}\\
\operatorname{Ad}_{(h,k)}{(\eta_h,\eta_k)} 
&=(\operatorname{Ad}_{h}\eta_{h}, \operatorname{Ad}_{k}(\Phi_{h}\eta_{k})  + \Psi_{k} (\operatorname{Ad}_{h}\eta_h)  - \operatorname{Ad}_{h}\eta_h),\label{eq:AD_new2}\\
\operatorname{ad}_{(\xi_{h},\xi_{k})}(\eta_h,\eta_k) &= ( \operatorname{ad}_{\xi_h} \eta_h, \xi_h \cdot \eta_k + \xi_k \cdot \eta_h + \operatorname{ad}_{\xi_k} \eta_k)\label{eq:AD_new3}.
\end{align}
Here the $\cdot$ denotes Lie algebra action. 
If it is assumed $K = H$, then the Adjoint action simplifies as follows
\begin{align}
\operatorname{Ad}_{g}{\eta_g} &= (\operatorname{Ad}_{h}\eta_{h},\operatorname{Ad}_{kh}(\eta_k+\eta_h) -\operatorname{Ad}_{h}\eta_h) \\
\operatorname{ad}_{\xi_{g}}\eta_{g} 
&= (\operatorname{ad}_{\xi_h}\eta_h, \operatorname{ad}_{\xi_k+\xi_h} (\eta_{h}+\eta_{k})- \operatorname{ad}_{\xi_h}\eta_h )
\end{align}

If it is assumed that the inner product structure is of the form
\begin{align}
    \langle (m,n),(u,v) \rangle_{\mathfrak{g}^*\times\mathfrak{g}} = \langle m,u\rangle_{\mathfrak{h}^*\times\mathfrak{h}}+ \langle n,v\rangle_{\mathfrak{k}^*\times\mathfrak{k}}.
\end{align}
Then the co-adjoint action is 
\begin{align}
\operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) &= (\operatorname{ad}^{*}_{\xi_h} m+ \operatorname{ad}_{\xi_k}^{*} n, \operatorname{ad}_{(\xi_k + \xi_h)}^{*} n  ). \label{eq:adstar}
\end{align}
\end{proposition}
The above proposition is known in the more general case and detailed exposition on \cref{eq:AD_new1,eq:AD_new2,eq:AD_new3} can be found in \cite{hochschild1965structure,marsden2007hamiltonian,ortega2013momentum}, below we detail calculations required for the case $H=K$ derivation of \cref{eq:adstar}.
The ADjoint action of $G$ on $G$ can be calculated from recalling the group associative identity \cref{eq:SDP_associativity_eq2} $g_1 g_2 g_3 = (h_1 h_2 h_3 , k_1 (h_1 \cdot k_2) (h_1 h_2 \cdot k_3))$, where $g_3=g_1^{-1}$ and substituting in \cref{eq:inverse} by
setting $h_3=h_1^{-1}$ and $k_{3} = h^{-1}_1\cdot k^{-1}_1$, gives the following $\operatorname{AD}$joint action
\begin{align}
\operatorname{AD}_{g_1}g_2 &= g_1 g_2 g^{-1}_1 = (h_1,k_1)(h_2,k_2)(h_1,k_1)^{-1}\\
&=(h_1,k_1)(h_2,k_2)(h^{-1}_1,h^{-1}_1\cdot k^{-1}_1)\\
& = (h_1 h_2 h_1^{-1} , k_1 (h_1 \cdot k_2) (h_1 h_2 \cdot (h^{-1}_1\cdot k^{-1}_1)))\\
& = (h_1 h_2 h_1^{-1} , k_1 (h_1 \cdot k_2) (h_1\cdot h_2) \cdot (k^{-1}_1)))\\
&= (\operatorname{AD}_{h_1}h_2,k_1 \operatorname{AD}_{h_1}k_2 \phi_{\operatorname{AD}_{h_1}h_2} k_1^{-1})
\end{align}
Where we have used the homomorphism property \cref{eq:property1}.
We now compute the Adjoint action
\begin{align}
\operatorname{Ad}_{(h_1,k_1)}(\eta_{h},\eta_{k}) := \frac{d}{d\epsilon}\bigg\vert_{\epsilon=0} \operatorname{AD}_{(h_1,k_1)}(h_{2,\epsilon},k_{2,\epsilon}), \quad\text{where}\quad (\eta_h,\eta_k) := \frac{d }{d\epsilon}\bigg|_{\epsilon=0} (h_{2,\epsilon},k_{2,\epsilon}) \in \mathfrak{g}=T_e G.
\end{align}
where for notational convenience $\eta_{g} = (\eta_{h},\eta_k):= (\dot{h}_2(0),\dot{k}_2(0)) \in \mathfrak{g}$ and $e_G = (e_h,e_K) = (h_2(0),k_2(0))$. The first component of $\operatorname{Ad}_{g_{1}} \eta_{2}$ is trivially given by $\operatorname{Ad}_{h_1}\eta_{h}$. For the second component of $\operatorname{Ad}_{g_{1}} \eta_{2}$ we expand out the conjugations
\begin{align}
k_1 \operatorname{AD}_{h_1}k_2 \phi_{\operatorname{AD}_{h_1}h_2}k_1^{-1} = k_1 \cdot_{K} h_1 k_2(\epsilon) h_1^{-1} \cdot_{K} (h_1h_2(\epsilon)h_1^{-1}) k^{-1}_{1} (h_1 h^{-1}_2(\epsilon) h_1^{-1}),
\end{align}
and take the derivative at the group identity
\begin{align}
    \frac{d}{ds}\bigg|_{s=0} [k_1 (h_1 k_2(s) h_1^{-1}) (h_1 h_2(s) h_1^{-1} k_1^{-1} h_1 h_2(s)^{-1} h_1^{-1})]
    &= k_1 (h_1 \dot{k}_2(0) h_1^{-1}) (h_1 e_{H} h_1^{-1} k_1^{-1} h_1 e_H h_1^{-1})  \\
    & + k_1 (h_1 e_K h_1^{-1}) (h_1 \dot{h}_2(0) h_1^{-1} k_1^{-1} h_1 e_H h_1^{-1})  
    \\
    & - k_1 (h_1 e_K h_1^{-1}) (h_1 e_H h_1^{-1} k_1^{-1} h_1 e_H \dot{h}_2(0) e_H h_1^{-1}).
\end{align}
Group homomorphisms have special properties on evaluation at identities and inverses, and the above expression simplifies to
\begin{align}
\frac{d}{ds}\bigg|_{s=0} k_1 \operatorname{AD}_{h_1}k_2 \phi_{\operatorname{AD}_{h_1}h_2}k_1^{-1}&= k_1 (h_1 \dot{k}_2(0) h_1^{-1}) ( k_1^{-1})  + k_1 (h_1 \dot{h}_2(0) h_1^{-1} k_1^{-1}) - (h_1 \dot{h}_2(0)  h_1^{-1})\\
    &= k (h\cdot \eta_k) k^{-1} + k(h \cdot \eta_h )k^{-1} - h \cdot \eta_h\\
    &= k \cdot(h\cdot \eta_k)  + k\cdot(h \cdot \eta_h ) - h \cdot \eta_h.
\end{align}
The above conjugate actions have all been denoted by $\cdot$, we briefly recall how these could be informally reinterpreted for general Lie groups $H,K$. 
Here $h\cdot\eta_k$ denotes the induced (by $\phi$) conjugate action of $h\in H$ on $\eta_{k}\in \mathfrak{k}$, denoted more explicitly as $\Phi_{h}(\eta_k)$. Similarly $h\cdot \eta_h$ is Adjoint action of $H$ on $\mathfrak{h}$, denoted $\operatorname{Ad}_h\eta_h$. Finally, $k\cdot \eta_h$ is the induced conjugate action of $k\in K$ on $\eta_h\in \mathfrak{h}$ denoted by $\Psi_k h$. In the specific instance $H=K$, simplification can be achieved, as all group actions and representations are Lie group homomorphisms given by conjugation, and elements in the Lie algebras can be added. For example
\begin{align}
 k \cdot (h\cdot \eta_k)  + k \cdot (h \cdot \eta_h ) - h \cdot \eta_h = kh \cdot (\eta_k + \eta_h) - h\cdot \eta_h = \operatorname{Ad}_{kh}(\eta_k+\eta_h) -\operatorname{Ad}_{h}\eta_h.
\end{align}

The adjoint action can be computed similarly by expanding the conjugation mappings and taking the derivative and evaluating at the identity 
\begin{align}
\frac{d}{dt}\bigg|_{t=0}\left(k_t \cdot (h_t\cdot \eta_k)  + k_t \cdot (h_t \cdot \eta_h ) - h_t \cdot \eta_h\right) &= [\xi_k ,\eta_k] + [\xi_h , \eta_k] + [\xi_k,\eta_h] + [\xi_h,\eta_h] - [\xi_h,\eta_h]\\ &=  [\xi_k+\xi_h,\eta_k+\eta_h] - [\xi_h,\eta_h].
\end{align}
verifying 
\begin{align}
\operatorname{ad}_{(\xi_h,\xi_k)} (\eta_h,\eta_k) =(\operatorname{ad}_{\xi_h} \eta_h,\operatorname{ad}_{(\xi_k+\xi_h)} (\eta_k+\eta_h)  - \operatorname{ad}_{\xi_h} \eta_h).
\end{align}



We now define an element of the dual space $(m,n)\in \mathfrak{g}^* \equiv (\mathfrak{h}\ltimes \mathfrak{k})^{*}$, and derive coadjoint motion. 
\begin{align}
\langle \operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n), (\eta_h,\eta_k)\rangle &= \langle (m,n),\operatorname{ad}_{(\xi_h,\xi_k)} (\eta_h,\eta_k) \rangle \\
&= \langle (m,n) , (\operatorname{ad}_{\xi_h} \eta_h ,\operatorname{ad}_{(\xi_k+\xi_h)} (\eta_k+\eta_h)  - \operatorname{ad}_{\xi_h} \eta_h )\rangle \\
&= \langle (m,n) , (\operatorname{ad}_{\xi_h} \eta_h ,\operatorname{ad}_{(\xi_k+\xi_h)} \eta_k + \operatorname{ad}_{(\xi_k+\xi_h)}\eta_h  - \operatorname{ad}_{\xi_h} \eta_h )\rangle \\
&= \langle (m,n) , (\operatorname{ad}_{\xi_h} \eta_h ,\operatorname{ad}_{(\xi_k+\xi_h)} \eta_k + \operatorname{ad}_{\xi_k}\eta_h   )\rangle\label{eq:coadstarderivation}
\end{align}
We now assume that there exists a pairing with the following  inner product structure
\begin{align}
    \langle (m,n),(u,v) \rangle_{\mathfrak{g}^*\times\mathfrak{g}} = \langle m,u\rangle_{\mathfrak{h}^*\times\mathfrak{h}}+ \langle n,v\rangle_{\mathfrak{k}^*\times\mathfrak{k}}.
\end{align}
Following on the calculation from \cref{eq:coadstarderivation}, we have that
\begin{align}
\langle (m,n) , (\operatorname{ad}_{\xi_h} \eta_h ,\operatorname{ad}_{(\xi_k+\xi_h)} \eta_k + \operatorname{ad}_{(\xi_k )}\eta_h  )\rangle &= 
\langle m , \operatorname{ad}_{\xi_h} \eta_h \rangle + \langle n,\operatorname{ad}_{(\xi_k+\xi_h)} \eta_k\rangle +\langle n,\operatorname{ad}_{\xi_k}\eta_h   \rangle\\
&= 
\langle \operatorname{ad}_{\xi_h}^{*} m ,  \eta_h \rangle + \langle \operatorname{ad}_{(\xi_k+\xi_h)}^{*}n , \eta_k \rangle +\langle \operatorname{ad}_{\xi_k}^{*}n,\eta_h   \rangle.
\end{align}
Giving the following representation, 
\begin{align}
\operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) = (\operatorname{ad}^{*}_{\xi_h} m+ \operatorname{ad}_{\xi_k}^{*} n, \operatorname{ad}_{(\xi_k + \xi_h)}^{*} n  ),
\end{align}
which we can write informally in co-adjoint matrix form or block diagonal Lie-Poisson form respectively as, 
\begin{align}
\left(\operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) \right)^{T}= \begin{bmatrix}
\operatorname{ad}_{\xi_h}^*(\cdot) & \operatorname{ad}_{\xi_k}^*(\cdot)\\
0&\operatorname{ad}_{\xi_h+\xi_k}^{*} (\cdot)
\end{bmatrix}
\begin{bmatrix}
    m\\
    n
\end{bmatrix} 
= 
\begin{bmatrix}
\operatorname{ad}_{(\cdot)}^*m & \operatorname{ad}_{(\cdot)}^*n \\
\operatorname{ad}_{(\cdot)}^*n& \operatorname{ad}_{(\cdot)}^*n
\end{bmatrix}
\begin{bmatrix}
    \xi_h\\
    \xi_k
\end{bmatrix}.
\end{align}


\begin{remark}
If one assumes a more general pairing (assuming $\mathfrak{h}=\mathfrak{k}$)
as follows
\begin{align}
    \langle (m,n),(u,v) \rangle_{\mathfrak{g}^*\times\mathfrak{g}} := a\langle m,u\rangle+b\langle m,v\rangle+
    c\langle n,u\rangle
    +d\langle n,v\rangle,
\end{align}
one attains the coadjoint motion
\begin{align}
\operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) = (\operatorname{ad}^{*}_{\xi_h} (am+cn) + \operatorname{ad}_{\xi_k}^{*} (dn+bm) , \operatorname{ad}_{(\xi_k + \xi_h)}^{*} (bm+dn)  ).
\end{align}
Which we can write informally in co-adjoint matrix form or Lie-Poisson form, respectively as, 
\begin{align}
\left(\operatorname{ad}^{*}_{(\xi_h,\xi_k)} (m,n) \right)^{T}= \begin{bmatrix}
\operatorname{ad}_{\xi_h}^*(\cdot) & \operatorname{ad}_{\xi_k}^*(\cdot)\\
0&\operatorname{ad}_{\xi_h+\xi_k}^{*} (\cdot)
\end{bmatrix}\left(
\begin{bmatrix}
    a&c\\
    b&d
\end{bmatrix} 
\begin{bmatrix}
    m\\
    n
\end{bmatrix} 
\right)
= 
\begin{bmatrix}
\operatorname{ad}_{(\cdot)}^*(am+cn) & \operatorname{ad}_{(\cdot)}^*(bm+dn) \\
\operatorname{ad}_{(\cdot)}^* (bm+dn)& \operatorname{ad}_{(\cdot)}^* (bm+dn)
\end{bmatrix}
\begin{bmatrix}
    \xi_h\\
    \xi_k
\end{bmatrix}.
\end{align}
The variational principle gives the same geodesic equations but for the transformed momentum variables 
\begin{align}
\begin{bmatrix}
    \widehat{m}\\
    \widehat{n}
\end{bmatrix}
=
\begin{bmatrix}
    a&c\\
    b&d
\end{bmatrix} 
\begin{bmatrix}
    m\\
    n
\end{bmatrix}. 
\end{align}
For an inner product it is typically required that $b=c, ad>b^2, a>0, d>0$. Considering the parametrised metric associated with $a=d=1/2$, $c=d=\theta/2$, one attains the semidirect product equations considered in this paper when $\theta = 0$, and two copies of the original Euler-Poincaré equations when $\theta=1$. 
\end{remark}


\subsection{Modelling framework, composition of maps}\label{sec: composition of maps}
We now provide some additional motivation for studying the semidirect product of groups. 
Suppose that $g_t \in \operatorname{Diff}(M)$ describes the action of a fluid taking a position at initial time to a later time $x_t = g_t  x_0$. Then taking the time derivative of position (denoted $\dot{x}_t$) and transforming into the current frame gives $\dot{x}_t = \dot{g}_t x_0 = \dot{g}_t  g^{-1}_t  x_t$, identifying
the Eulerian velocity as $\tilde{u}:=\dot{g}g^{-1}$. We suppose that the diffeomorphism $g$ is written as a composition of two other diffeomorphisms such that $x_t = (h\circ k) x_0$. One can naturally attain a decomposition of the Eulerian velocity through the chain rule, 
$\dot{x}_t = \dot{g}g^{-1}x_0 = \partial_t(h\circ k) (h\circ k)^{-1} x_0 = [\dot{k}  (h\circ k)+\dot{h}\circ k)]( k^{-1}\circ h^{-1})x_0  =(\dot{h}h^{-1} + h_{*}\dot{k}k^{-1})x_0$. The Eulerian velocity can be written as $\tilde{u} = u + v$ where $u:= \dot{h}h^{-1}$ is the velocity of $h$ and $v := h_{*}\dot{k}k^{-1}$ denotes the velocity of $k$ pushed-forward by $h$.
Supposing through a reduction by stages (see for example \cite{holm202431,marsden2007hamiltonian,ortega2013momentum}) there exists a reduced Lagrangian consisting of the velocity $u$ and the push forwarded velocity $v$, Hamilton's principle of critical action can be written as
\begin{align}
0=\delta \int \ell(\dot{h}h^{-1},h_{*}\dot{k}k^{-1})dt = \delta\int\ell(u,v)dt.
\end{align}
Let the flow maps $(h,k)$ be parametrised by $\epsilon$, and denote $h':=\partial_{\epsilon}|_{\epsilon=0}h_{\epsilon}$, and $k':=\partial_{\epsilon}|_{\epsilon=0}k_{\epsilon}$, the constrained variations are calculated \cite{holm202431,bruveris2012mixture} to be
\begin{align}
\delta u =\frac{d}{d\epsilon}\bigg|_{\epsilon=0}\dot{h}h^{-1} &= \dot{w}_1 -\operatorname{ad}_{u}w_1,\quad w_1:=h'h^{-1},\label{eq:constrained variations1} \\
\delta v = \frac{d}{d\epsilon}\bigg|_{\epsilon=0} (h_{*}\dot{k}k^{-1}) &= \dot{w}_2 -\operatorname{ad}_{u+v}w_2 -\operatorname{ad}_{u}w_1, \quad w_2 := h_*(k'k^{-1}).\label{eq:constrained variations2}
\end{align}
This reveals a $\mathfrak{g}\ltimes \mathfrak{g}$ semidirect product structure to the resulting Euler-Poincaré equations
\begin{align}
\partial_t (m,n) + (\operatorname{ad}^*_{u}(m) + \operatorname{ad}^*_{v}n,\operatorname{ad}^*_{u+v}(n)) = 0,\quad\quad \quad (m,n):= \left(\frac{\delta \ell}{\delta u},\frac{\delta \ell}{\delta v}\right),\label{eq:semidirect_product}
\end{align}
since the constrained variations align exactly with the adjoint actions of the semidirect product of groups in \cref{prop:adjoint actions for a semidirect product}. 



If one defines the kinetic energy as the square of the total velocity  
\begin{align}
\ell(\tilde{u})= \frac{1}{2}\int\tilde{u}^2d^n x = \frac{1}{2}\int(\dot{h}h^{-1}+ h_{*}\dot{k}k^{-1})^2= \frac{1}{2}\int (u + v)^2 d^n x=\ell(u,v),
\end{align}
the momenta are equal 
\begin{align}
   \frac{\delta \ell}{\delta v}=\frac{\delta \ell}{\delta u} =m=n=(u+v)^{\flat}.
\end{align}
Hamilton's principle, subject to the constrained variations \cref{eq:constrained variations1,eq:constrained variations2} gives semidirect product Euler-Poincaré equations \cref{eq:semidirect_product}, with equal momenta becomes
\begin{align}
\partial_t (\tilde{m},\tilde{m}) + (\operatorname{ad}^*_{u+v}(\tilde{m}),\operatorname{ad}^*_{u+v}(\tilde{m})) = 0.
\end{align}
Recalling the definition of total fluid velocity $\tilde{u} = u+v$ and total momentum $\tilde{m}= \frac{\delta \ell(\tilde{u})}{\delta\tilde{u}}=(u+v)^{\flat}$, we recover two copies the usual Euler-Poincaré equation
\begin{align}
    \partial_t \tilde{m} + \operatorname{ad}^*_{\tilde{u}}\tilde{m}= 0.
\end{align}
Revealing that the decomposition of the diffeomorphism attains the original Euler-Poincaré equations, as one would expect. In this work, we consider the same constrained variations, but numerically investigate equations arising from Lagrangian's when one neglects the contribution of the cross terms in the Lagrangian, where an inner product of the form $\langle (,),(,)\rangle_{\mathfrak{h}\times \mathfrak{k}} = \langle, \rangle_{\mathfrak{h}} + \langle ,\rangle_{\mathfrak{k}}$ gives rise to a diagonal Lagrangian. This gives distinct equations to the Euler-Poincaré equations.


\subsection{Centrally extending the semidirect product}\label{Centrally extending the semidirect product group}
Defining $\tilde{\sigma}$ as 
\begin{align}
\tilde{\sigma}((\xi_1,\xi_2),(\eta_1,\eta_2)) := (\sigma(\xi_1,\eta_1),\sigma(\xi_2,\eta_2)),
\end{align}
where $\sigma:\mathfrak{g}\times \mathfrak{g}\mapsto \mathfrak{n}$ denotes the algebra 2-cocycle on $\mathfrak{g}$. 
One can verify that $\tilde{\sigma}$ satisfies the 2-cocycle relationship 
\begin{align}
\tilde{\sigma}((a_1,a_2),[(b_1,b_2),(c_1,c_2)]_{\mathfrak{g}\ltimes \mathfrak{g}}) + \text{cyclic permutations of a,b,c} = 0,\quad \forall a,b,c \in \mathfrak{g}\ltimes\mathfrak{g}\\ 
\tilde{\sigma}((a_1,a_2),[(b_1,b_2),(c_1,c_2)]_{\mathfrak{g}\times \mathfrak{g}}) + \text{cyclic permutations of $a$,b,c} = 0,\quad \forall a,b,c \in \mathfrak{g}\times\mathfrak{g}
\end{align}
for both the semidirect product Lie bracket and the direct product Lie bracket, from the original 2-cocycle condition on $\sigma$. Continuity and skew-symmetry similarly follow from $\sigma$. Therefore, assuming a canonical pairing
\begin{align}
\langle(m,n,l,o),(\xi_1,\xi_2,\alpha_1,\alpha_2)\rangle = \langle m,\xi_1 \rangle_{\mathfrak{g}} + \langle n,\xi_2 \rangle_{\mathfrak{g}} + \langle l,\alpha_1 \rangle_{\mathfrak{n}} + \langle o,\alpha_2 \rangle_{\mathfrak{n}},
\end{align}
one can derive the following co-adjoint operator for this central extension of the semidirect product, as follows
\begin{align}
\left\langle\operatorname{ad}^*_{(\xi_1,\xi_1,\alpha_1,\alpha_2)}(m,n,l,o),(\eta_1,\eta_2,\beta_1,\beta_2) \right\rangle &= \langle (m,n),\operatorname{ad}_{(\xi_1,\xi_2)} (\eta_1,\eta_2) \rangle + \langle (l,o),\tilde{\sigma}((\xi_1,\xi_2),(\eta_1,\eta_2))\rangle\\ &= \langle \operatorname{ad}_{(\xi_1,\xi_2)}^*(m,n) , (\eta_1,\eta_2,\beta_1,\beta_2) \rangle + \langle l,\sigma(\xi_1,\eta_1)\rangle+ \langle o,\sigma(\xi_2,\eta_2)\rangle\\
& = \langle\operatorname{ad}^*_{\xi_1}m + \operatorname{ad}^*_{\xi_2}n + \sigma^*(\xi_1,l), \eta_1 \rangle + \langle\operatorname{ad}^*_{\xi_1+\xi_2}n + \sigma^*(\xi_2,o), \eta_2\rangle \\
&= \langle \left( \operatorname{ad}_{\xi_1}^{*} m + \operatorname{ad}_{\xi_2}^{*} n + \sigma^*(\xi_1,l), \operatorname{ad}^*_{\xi_1+\xi_2}n + \sigma^*(\xi_2,o),0,0 \right),(\eta_1,\eta_2,\beta_1,\beta_2)\rangle.
\end{align}
This can be written (in terms of the previous notation in \cref{sec: semidirect product of centrall extension} ($\xi_1 = \xi_h$, $\xi_2=\xi_k$, $\alpha_1 = \alpha$, $\alpha_2=\beta$) ) in Lie-Poisson or coadjoint operator form as
\begin{align}
\frac{d}{dt}
\begin{bmatrix}
m\\
l\\
n\\
o
\end{bmatrix}
&= -
\begin{bmatrix}
\operatorname{ad}_{(\cdot)}^*m + \sigma^*(\cdot,l)& 0& \operatorname{ad}_{(\cdot)}^*n & 0\\
0&0&0&0\\
\operatorname{ad}_{(\cdot)}^*n & 0&\operatorname{ad}_{(\cdot)}^*n+ \sigma^*(\cdot,o)&0\\
0&0&0&0
\end{bmatrix}
\begin{bmatrix}
    \xi_h\\
    \alpha\\
    \xi_k \\
    \beta
\end{bmatrix}
= -
\begin{bmatrix}
\operatorname{ad}^{*}_{\xi_{h}}(\cdot) &
\sigma^{*}(\xi_h,\cdot)
&\operatorname{ad}^{*}_{\xi_{k}}(\cdot)
&0\\
0&0&0&0\\
0&0&\operatorname{ad}^{*}_{\xi_{h}+\xi_{k}}(\cdot)& \sigma^*(\xi_{k},\cdot)\\
0&0&0&0
\end{bmatrix}
\begin{bmatrix}
m\\
l\\
n\\
o
\end{bmatrix}\label{eq:central_extension_of_semidirectproduct}.
\end{align}
The coadjoint contribution of the 2-cocycle is strictly diagonal in the Lie-Poisson form, and not involved in the coupling of the equations. Choosing $\mathfrak{g}= \operatorname{Vect}(S^1)$, one attains the following coupled systems of equations as examples of centrally extended semidirect product EP-equations, without dispersive coupling where $(o,l)$ are constants.
\begin{example}
CH-CH, $\ell  = 1/2||u||_{H^1_{\alpha}}^2 + 1/2||v||_{H^1_{\beta}}^2 + 1/2 \alpha^2 + 1/2 \beta^2$
\begin{align}
    \partial_t m + (um)_x + u_x m + lu_{xxx} + (vn)_x + v_x n  &= 0, \quad m = u-\alpha u_{xx},\\
\partial_t n + ((u+v)n)_x + (u+v)_x n + o (v)_{xxx} &= 0,\quad n = v-\beta v_{xx},
\end{align}
\end{example}

\begin{example}
KdV-Burgers, $\ell  = 1/2||u||_{L^2}^2 + 1/2||v||_{L^2}^2 + 1/2 \alpha^2$
\begin{align}
\partial_t u + 3uu_x + lu_{xxx} + 3vv_x  &= 0, \\
\partial_t v + ((u+v)v)_x + (u+v)_x v  &= 0.
\end{align}
\end{example}

\begin{example}
Burgers-KdV, $\ell  = 1/2||u||_{L^2}^2 + 1/2||v||_{L^2}^2 + 1/2 \beta^2$
\begin{align}
\partial_t u + 3uu_x   + 3vv_x  &= 0, \\
\partial_t v + ((u+v)v)_x + (u+v)_x v + o v_{xxx} &= 0.
\end{align}
\end{example}
These equations are EP-equations on a centrally extended semidirect product Lie algebra, but it is not clear what the group action is. The previous EP-equations on a semidirect product of centrally extended Lie algebras would have arisen if one introduced
$
\bar{\sigma}((\xi_1,\xi_2),(\eta_1,\eta_2)) := (\sigma(\xi_1,\eta_1),\sigma(\xi_2,\eta_2) + \sigma(\xi_1,\eta_2) + \sigma(\xi_2,\eta_1))
$ instead.

