\subsection{Ideal Incompressible MHD}\label{sec:MHD}

\begin{example}[Ideal Incompressible MHD]
A magnetic extension is a particular subcase of vector space extension constructed using the dual of the Lie algebra $G\ltimes \mathfrak{g}^*$. When $G=\operatorname{SDiff}(M)$,
the Lie algebra action of
$\mathfrak{g}\ltimes \mathfrak{g}^* = \operatorname{SVect}(M) \ltimes\left(\Lambda^1(M) / \mathrm{d} \Lambda^0(M)\right)$ on itself is given by 
\begin{align}
\operatorname{ad}_{(u,[b])} (v,[c]) = (\operatorname{ad}_{u}v, \operatorname{ad}^*_{v}[b]-\operatorname{ad}^*_u [c] )=(-\mathcal{L}_u v,\mathcal{L}_v [b] - \mathcal{L}_{u}[c]). %=(-\mathcal{L}_u v,\rho_R(v) [b] - \rho_R(u)[c])
\end{align}
So the co-adjoint action is calculable to be $(\mathcal{L}_u [m] - \mathcal{L}_B[b],\mathcal{L}_{u}B)$, as follows
\begin{align}
\langle\operatorname{ad}^*_{(u,[b])}([m],B),(v,[c])\rangle &= \langle \operatorname{ad}_{u}v, [m]\rangle - \langle \operatorname{ad}^*_{u}[c],B\rangle +\langle\operatorname{ad}_v^*[b],B\rangle\\
%&= \langle v, \operatorname{ad}_{u}^*[m]\rangle - \langle [c],\operatorname{ad}_u B\rangle +\langle\mathcal{L}_v [b],B\rangle\\
&= \langle  \operatorname{ad}_{u}^*[m],v\rangle - \langle \operatorname{ad}_u B,[c]\rangle +\langle B,\mathcal{L}_v [b]\rangle\\
&= \langle  \operatorname{ad}_{u}^*[m],v\rangle + \langle \mathcal{L}_u B,[c]\rangle -\langle B \diamond [b],v \rangle\\
&= \langle \left( \operatorname{ad}_u^* [m] - \mathcal{L}_{B}[b],\mathcal{L}_{u}B \right),  \left(v,[c]\right) \rangle.
\end{align}

To compute the operator $\diamond:V^*\times V\mapsto \mathfrak{g}^*$ (defined previously as $\langle n,\alpha(\eta)v \rangle_{\mathfrak{g}\times\mathfrak{g}^*} :=-\langle n\diamond v, \eta\rangle_{\mathfrak{g}^*\times
\mathfrak{g}})$, we used the contragradient representation of the Lie derivative as follows $-\langle B\diamond [b],v  \rangle = \langle \mathcal{L}_v [b], B\rangle = -\langle [b],\mathcal{L}_v B\rangle =  \langle [b],\mathcal{L}_{B}v \rangle = -\langle \mathcal{L}_{B}[b],v \rangle$. The resulting Euler-Poincaré equation is expressible in matrix form, as 
\begin{align}
\frac{d}{dt}
\begin{bmatrix}
    [m]\\
    B
\end{bmatrix}
&= 
- 
\begin{bmatrix}
    \mathcal{L}_{u}(\cdot) & -\mathcal{L}_{(\cdot)}[b] \\
    0 &  \mathcal{L}_{u}(\cdot)  \\
\end{bmatrix}
\begin{bmatrix}
    [m]\\
    B\\
\end{bmatrix}\label{2D-incompressible-MHD}=
-
\begin{bmatrix}
    \mathcal{L}_{(\cdot)}[m] & -\mathcal{L}_{B}(\cdot) \\
 \mathcal{L}_{(\cdot)}B & 0  \\
\end{bmatrix}
\begin{bmatrix}
     u  \\
    [b] 
\end{bmatrix}.
\end{align}
Here, the Lie derivative of the one-form is denoted $\mathcal{L}_{u}[m]$, and the Lie derivative of a vector field is the commutator of vector fields and denoted $\mathcal{L}_{u}B$. 
\end{example}

\begin{example}[Ideal Incompressible Hall MHD]
By combining \cref{sec:Direct products,2D-incompressible-MHD} the coordinate free Incompressible Hall-MHD equations can be constructed in arbitrary dimensions from the direct product \cite{holm1987hall}, and takes the following coadjoint and Lie-Poisson form 
\begin{align}
\frac{d}{dt}
\begin{bmatrix}
    [m]\\
    B\\
    [n]\\
    C
\end{bmatrix}
&= 
- 
\begin{bmatrix}
    \mathcal{L}_{u}(\cdot) & -\mathcal{L}_{(\cdot)}[b] & 0 & 0\\
    0 &  \mathcal{L}_{u}(\cdot) & 0 & 0 \\
    0&0&\mathcal{L}_{v}(\cdot)&-\mathcal{L}_{(\cdot)}[c]\\
    0&0&0&\mathcal{L}_{v}(\cdot)
\end{bmatrix}
\begin{bmatrix}
    [m]\\
    B\\
    [n]\\
    C
\end{bmatrix}\label{incompressible-HMHD}=
-
\begin{bmatrix}
    \mathcal{L}_{(\cdot)}[m] & -\mathcal{L}_{B}(\cdot) & 0& 0\\
     \mathcal{L}_{(\cdot)}B & 0 & 0 & 0 \\
    0&0&\mathcal{L}_{(\cdot)}[n]&-\mathcal{L}_{C}(\cdot)\\
    0&0&\mathcal{L}_{(\cdot)}C&0
\end{bmatrix}
\begin{bmatrix}
     u  \\
    [b] \\
     v  \\
    [c]
\end{bmatrix}.
\end{align}
These are geodesic equations for $(G\ltimes \mathfrak{g}^*)\times (G\ltimes \mathfrak{g}^*)$ where $G=\operatorname{SDiff}(M)$. 
\end{example}

\begin{example}[Self-Semi-direct product] 
Using the general form in \cref{eq:semidirectproduct_of_semidirect_products,2D-incompressible-MHD} one can inspect Euler-Poincaré equations for the self-semidirect product extension of the magnetically extended volume preserving group $\operatorname{SDiff}(M)$ group given by $
(\operatorname{SDiff}(M) \ltimes\left(\Lambda^1(M) / \mathrm{d} \Lambda^0(M)\right))\ltimes (\operatorname{SDiff}(M) \ltimes\left(\Lambda^1(M) / \mathrm{d} \Lambda^0(M)\right))
$. The Lie algebra is $$(u,[b],v,[c])\in 
(\operatorname{SVect}(M) \ltimes\left(\Lambda^1(M) / \mathrm{d} \Lambda^0(M)\right))\ltimes (\operatorname{SVect}(M) \ltimes\left(\Lambda^1(M) / \mathrm{d} \Lambda^0(M)\right))
$$ and it acts on the dual space $$([m],B,[n],C)\in \left(\left(\Lambda^1(M) / \mathrm{d} \Lambda^0(M)\right)
\times\operatorname{SVect}(M)\right)\times\left(\left(\Lambda^1(M) / \mathrm{d} \Lambda^0(M)\right)
\times\operatorname{SVect}(M)\right).
$$
Assuming a Lagrangian with canonical pairing between vector space and dual space gives the Euler-Poincaré equations in coadjoint and Lie-Poisson form
\begin{align}
\frac{d}{dt}
\begin{bmatrix}
    [m]\\
    B\\
    [n]\\
    C
\end{bmatrix}
&= 
- 
\begin{bmatrix}
    \mathcal{L}_{u}(\cdot) & -\mathcal{L}_{(\cdot)}[b] & \mathcal{L}_{v}(\cdot) & -\mathcal{L}_{(\cdot)}[c]\\
    0 &  \mathcal{L}_{u}(\cdot) & 0 &  \mathcal{L}_{v}(\cdot) \\
    0&0&\mathcal{L}_{u+v}(\cdot)&-\mathcal{L}_{(\cdot)}([b]+[c])\\
    0&0&0&\mathcal{L}_{u+v}(\cdot)
\end{bmatrix}
\begin{bmatrix}
    [m]\\
    B\\
    [n]\\
    C
\end{bmatrix}\label{incompressible-MHD}=
-
\begin{bmatrix}
    \mathcal{L}_{(\cdot)}[m] & -\mathcal{L}_{B}(\cdot) & \mathcal{L}_{(\cdot)}[n] & -\mathcal{L}_{C}(\cdot)\\
     \mathcal{L}_{(\cdot)}B & 0 & \mathcal{L}_{(\cdot)}C & 0 \\
    \mathcal{L}_{(\cdot)}[n]&-\mathcal{L}_{C}(\cdot)&\mathcal{L}_{(\cdot)}[n]&-\mathcal{L}_{C}(\cdot)\\
    \mathcal{L}_{(\cdot)}C&0&\mathcal{L}_{(\cdot)}C&0
\end{bmatrix}
\begin{bmatrix}
     u  \\
    [b] \\
     v  \\
    [c]
\end{bmatrix}
\end{align}
 The magnetic extension of $\operatorname{SDiff}(M)$ gives the incompressible MHD equations (given in the upper left $2\times 2$ block), discussed in \cite{khesin2009geometry,arnol'd2009topological} where $u$ denotes velocity field and $B$ denotes magnetic field. The system \cref{incompressible-MHD} denotes the self-semidirect product extension with another incompressible magnetic fluid with velocity $v$ and magnetic field $C$. 
\end{example}


