\subsection{Information Ellipsoid for 3D Localization}
In practical applications, only a subset of $\boldsymbol{\eta}$  is of interest. Let us define the following parameter subsets:
Effective position part $\boldsymbol{\eta}_{\rm pos} = [\tau_{\rm r},\phi_{\rm r}^{\rm az},\phi_{\rm r}^{\rm el}]^{\rm T}$, effective orientation part $\boldsymbol{\eta}_{\rm ori} = [\tilde{\phi}_{\rm r}^{\rm az},\tilde{\phi}_{\rm r}^{\rm el},\tilde{\theta}_{\rm r}^{\rm az},\tilde{\theta}_{\rm r}^{\rm el}]^{\rm T}$, and redundant part $\boldsymbol{\eta}_{\rm red} = [\theta_{\rm r}^{\rm az},\theta_{\rm r}^{\rm el},{\Re}\{g_{\rm r}\},{\Im}\{g_{\rm r}\}]^{\rm T}$.
We define the Jacobian matrix as
 $\mathbf{J}_{\rm A}  = {\partial\boldsymbol{\eta}_{\rm pos}^{\rm T}}/{\partial \mathbf{r}}$, and the submatrix of the FIM as 
\begin{align} \label{D1FIMA}
	\mathbf{F}_{\rm A} &=\left[\begin{array}{ccc}
		F_{\tau_{\rm r} \tau_{\rm r}}  & 0 & 0 \\
		0 & F_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm az}} & F_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}} \\
		0 & F_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}} & F_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm el}}
	\end{array}\right].
\end{align}
Thus, the partitioned structure of $\mathbf{F}(\boldsymbol{\eta})$ and $\mathbf{J}$ is expressed as
\begin{equation} %\label{D1FIM0}
    \mathbf{F}(\boldsymbol{\eta}) =\left[\begin{array}{cc}
	\mathbf{F}_{\rm A} & \mathbf{F}_{\rm B}\\
	\mathbf{F}_{\rm B}^{\rm T} & \mathbf{F}_{\rm C}
\end{array}\right] 
\text{~and~}  %\label{D1J0}
	\mathbf{J} =\left[ \mathbf{J}_{\rm A} ,\mathbf{J}_{\rm C} \right],
\end{equation}
where $\mathbf{F}_{\rm B}=\mathbf{0}$ in accordance with \cite{FIM2}, \cite{FIM1}. Consequently, the FIM can be rewritten as
\begin{equation} \label{D1FIM3}
\mathbf{J} \mathbf{F}(\boldsymbol{\eta})  \mathbf{J}^{\rm H} = \mathbf{J}_{\rm A} 	\mathbf{F}_{\rm A}  \mathbf{J}_{\rm A}^{\rm H} + \mathbf{J}_{\rm C} 	\mathbf{F}_{\rm C}  \mathbf{J}_{\rm C}^{\rm H}.
\end{equation}
When the orientation and redundant parameters, $\boldsymbol{\eta}_{\rm ori}$ and $\boldsymbol{\eta}_{\rm red}$, are not estimated, their contributions to the localization FIM are zero. According to \eqref{FIM5}, we have
\begin{equation} \label{D1FIM4}
\mathbf{F}(\mathbf{r})= \mathbf{J}_{\rm A} 	\mathbf{F}_{\rm A}  \mathbf{J}_{\rm A}^{\rm H}.
\end{equation}
The element-wise expression of $\mathbf{J}_{\rm A} $ is provided in Appendix \ref{B}. 


\begin{theorem}\label{T0}
	The EFIM for 3D localization is given by 
\begin{align}\label{THE1}
	\mathbf{F}_{\rm e}(\mathbf{r})& = \lambda_{\tau_{\rm r}} \mathbf{u}_{\tau_{\rm r}}\mathbf{u}_{\tau_{\rm r}}^{\rm H} + (\lambda_{\phi_{\rm r}^{\rm az}} - \chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}) \mathbf{u}_{\phi_{\rm r}^{\rm az}}\mathbf{u}_{\phi_{\rm r}^{\rm az}}^{\rm H} \nonumber\\
	&~~~+ (\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}} )\mathbf{u}_{\phi_{\rm r}^{\rm el}}\mathbf{u}_{\phi_{\rm r}^{\rm el}}^{\rm H},
\end{align}
	where $\mathbf{u}_{\tau_{\rm r}}$, $\mathbf{u}_{\phi_{\rm r}^{\rm az}}$, and $\mathbf{u}_{\phi_{\rm r}^{\rm el}}$ are unit direction vectors for range, azimuth AOA, and elevation AOA information, respectively. Their expressions are given by 
	\begin{subequations}\label{unitv}
		\begin{align}
			\mathbf{u}_{\tau_{\rm r}} &=  [ \cos\phi_{\rm r}^{\rm az}\cos\phi_{\rm r}^{\rm el},\sin\phi_{\rm r}^{\rm az}\cos\phi_{\rm r}^{\rm el},\sin\phi_{\rm r}^{\rm el} ]^{\rm T},   \\
			\mathbf{u}_{\phi_{\rm r}^{\rm az}} &=  [-\sin\phi_{\rm r}^{\rm az},\cos\phi_{\rm r}^{\rm az}, 0]^{\rm T}, \\
			\mathbf{u}_{\phi_{\rm r}^{\rm el}} &= [-\cos\phi_{\rm r}^{\rm az}\sin\phi_{\rm r}^{\rm el},-\sin\phi_{\rm r}^{\rm az}\sin\phi_{\rm r}^{\rm el},\cos\phi_{\rm r}^{\rm el} ]^{\rm T}.
		\end{align}
	\end{subequations}
	Furthermore, the terms $ \lambda_{\tau_{\rm r}} $, $(\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}})$, and $(\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}})$ represent the information intensities for range, azimuth AOA, and elevation AOA, respectively. The terms $\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}$ and $\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}$ denote mutual spatial information intensity. These are expressed as follows:
	\begin{subequations}\label{intensity}
		\begin{align}
			\lambda_{\tau_{\rm r}} &= \frac{ 2\pi^2 B^2 }{3c^2}  N_{\rm R}{\rm SNR}, \label{intensityT} \\
			\lambda_{\phi_{\rm r}^{\rm az}} &= \frac{ 8 \pi^2 }{3 \lambda^2} \frac{G_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm az}}}{\| \mathbf{r}-\mathbf{b}_{\rm R} \|_2^2\cos^2 \phi_{\rm r}^{\rm el}}   N_{\rm R}{\rm SNR}, \label{intensityAZ}\\
			\lambda_{\phi_{\rm r}^{\rm el}} &=\frac{ 8 \pi^2 }{3 \lambda^2 } \frac{G_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm el}} } {\| \mathbf{r}-\mathbf{b}_{\rm R} \|_2^2} N_{\rm R}{\rm SNR}, \label{intensityEL} \\
			\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}} &= \frac{8 \pi^2}{3 \lambda^2 }\frac{G_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}G_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}}{G_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm el}}\| \mathbf{r}-\mathbf{b}_{\rm R} \|_2^2\cos^2 \phi_{\rm r}^{\rm el}} N_{\rm R}{\rm SNR}, \\
			\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}} &= \frac{8 \pi^2}{3 \lambda^2 }\frac{G_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}G_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}}{G_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm az}}\| \mathbf{r}-\mathbf{b}_{\rm R} \|_2^2} N_{\rm R}{\rm SNR}.\label{intensityMU}
		\end{align}
	\end{subequations}
\end{theorem}
The proof is provided in Appendix \ref{B}. 



As illustrated in Fig. \ref{ellips}(a), the vectors $\mathbf{u}_{\tau_{\rm r}}$, $\mathbf{u}_{\phi_{\rm r}^{\rm az}}$ and $\mathbf{u}_{\phi_{\rm r}^{\rm el}}$ are mutually orthogonal. Specifically, the vector $\mathbf{u}_{\tau_{\rm r}}$ points along the line connecting the reference point $\mathbf{b}_{\rm R}$ to $\mathbf{r}$, while $\mathbf{u}_{\phi_{\rm r}^{\rm az}}$ and $\mathbf{u}_{\phi_{\rm r}^{\rm el}}$ span a plane perpendicular to $\mathbf{u}_{\tau_{\rm r}}$.
An ellipsoid characterized by these axes, with corresponding ``radii'' (information intensities)  $ \lambda_{\tau_{\rm r}} $, $(\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}})$, and $(\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}})$, is referred to as the \emph{information ellipsoid}.
Several observations regarding the information ellipsoid are noted: 
\begin{itemize}
 \item It can be shown that the values of $ \lambda_{\tau_{\rm r}} $, $\lambda_{\phi_{\rm r}^{\rm az}}$, $\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}$, $\lambda_{\phi_{\rm r}^{\rm el}}$, and $\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}$ are non-negative. Moreover, the non-negativity of $(\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}})$, and $(\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}})$ can be rigorously established through detailed calculations involving equations \eqref{fim-az2}, \eqref{fim-el2}, and \eqref{fim-azel2}. Specifically, by computing the product of \eqref{fim-az2} and \eqref{fim-el2}, and subtracting the square of \eqref{fim-azel2}, it can be shown that these expressions are inherently non-negative (Appendix \ref{A3}).

 \item In range estimation, the information intensity is proportional to the square of the signal bandwidth, as indicated by \eqref{intensityT}. This relationship is typically exploited by observing the phase differences among the various subcarriers in OFDM systems. In contrast, for absolute carrier phase estimation, $F_{\tau_{\rm r} \tau_{\rm r}}$ is given by \eqref{fim-e22}. Consequently, the range information intensity (RII) $ \lambda_{\tau_{\rm r}} $ becomes ${ 8\pi^2 f^2}  {\rm SNR}/{c^2}$, which is proportional to the square of the carrier frequency. Since the carrier frequency is generally much higher than the signal bandwidth, absolute phase estimation facilitates more precise range measurements, albeit at the expense of requiring specialized estimation techniques.

 \item In angle estimation, \eqref{intensityAZ} to \eqref{intensityMU} demonstrate that the angle information intensity (AII) is determined by the effective aperture of the antenna array. When the distance between the receiving antenna and the target is constant, increasing the number of antennas or enlarging their spacing enhances the effective aperture. Conversely, if the number of antennas and their spacing remain fixed, the effective aperture decreases as the target distance increases or as the angular offset grows. Therefore, angle measurement is generally more suitable for short-range sensing, whereas the RII  is unaffected by the sensing distance.

 \item The TOA and AOAs at the receiver provide sufficient information to estimate the RIS position. If the AOA and AOD at the RIS are also available, it is possible to estimate the RIS orientation using, e.g., \eqref{GR3} and \eqref{GR4}. When analyzing \eqref{D1FIM4}, one could in principle include the derivatives of the TOA and AOA with respect to the orientation in $\mathbf{J}_{\rm A}$. However, since these derivatives are zero, the final result is unaffected. For simplicity, orientation is therefore not considered in the present analysis. The Fisher information related to RIS orientation can be examined using the same methodology, which is an interesting direction for future research.
\end{itemize}


\subsection{Structure State Identification}
To determine whether the RIS position has changed, we compare the estimated RIS position with its initial value, $\mathbf{r}_0$. This problem can be formulated as a classical hypothesis testing problem: 
\begin{align} \label{HT}
	\mathcal{H}_0 & : \mathbf{r} = \mathbf{r}_{0},\\
	\mathcal{H}_1 & : \mathbf{r} \ne \mathbf{r}_{0}.
\end{align}
Under the null hypothesis 
$\mathcal{H}_0$, the RIS is assumed to remain at its initial position, while the alternative hypothesis $\mathcal{H}_1$ indicates that a positional change has occurred.
To account for measurement uncertainties and distinguish them from genuine positional changes, we employ the Wald test. Specifically, the test decides in favor of $\mathcal{H}_1$ if the following condition is satisfied:
\begin{equation} \label{wt} 
	T_W = (\hat{\mathbf{r}}-\mathbf{r}_{0})^{\rm T}\mathbf{F}(\hat{\mathbf{r}})(\hat{\mathbf{r}}-\mathbf{r}_{0}) > \kappa,
\end{equation}
where $\kappa$ is an empirically determined threshold,\footnote{For example, a displacement change of $50$ mm is set as the threshold ($\kappa=50$ mm) for the ``Damaged" state in ordinary buildings and structures, as stated in \cite{SHM}. Generally, the threshold $\kappa$ can be set in accordance with industry standards for structural engineering \cite{ISO4553_2022}. } and $\hat{\mathbf{r}}$ represents the maximum likelihood estimate of $\mathbf{r}$ under $\mathcal{H}_1$. 

In practice, beyond simply detecting a change in the reference point position, the structure state is defined in terms of the serviceability limit state as outlined in \cite{ISO4553_2022}. We assume that the structure state $S$  takes values from a discrete set $\mathbb{S}=\{S_1={\sf U},\ S_2={\sf D} \}$, where ``${\sf U}$'' represent ``Unchanged'' and ``${\sf D}$'' represent ``Damaged'' \cite{Detect}. Based on the Wald test in \eqref{wt}, we define the weighted displacement as
\begin{equation}
	d(\hat{\mathbf{r}}) = (\hat{\mathbf{r}}-\mathbf{r}_{0})^{\rm T}\mathbf{F}(\hat{\mathbf{r}})(\hat{\mathbf{r}}-\mathbf{r}_{0}).
\end{equation}	
The defined weighted displacement not only considers the discrepancy between the measured value and the true value $(\hat{\mathbf{r}}-\mathbf{r}_{0})$, but also takes the reliability of this measurement $\mathbf{F}(\hat{\mathbf{r}})$ into account.
When $d(\hat{\mathbf{r}})$ exceeds the serviceability limit threshold $\kappa$ specified in \cite{ISO4553_2022}, damage is inferred; thus, $\mathcal{H}_0$ corresponds to the state ${\sf U}$ and $\mathcal{H}_1$ to state ${\sf D}$.

The identification of the structure state can be approached as an inference problem. Using Bayes' theorem, the posterior probability is calculated as 
\begin{equation} \label{posterior}
	{\rm P}\big(S_l | d(\hat{\mathbf{r}})\big) =  \frac{f\big(d(\hat{\mathbf{r}})|S_l\big){\rm P}\big(S_l\big)}{f\big(d(\hat{\mathbf{r}})\big)},
\end{equation}
where ${\rm P}(S_l)$ is the prior probability, determined by the structure's attributes, and $f\big( d(\hat{\mathbf{r}})|S_l \big)$ is the likelihood function, which is derived from the parameter estimation implementation. The denominator, $f\big(d(\hat{\mathbf{r}})\big)$, is computed as $  \sum_{l=1}^{2} f\big(d(\hat{\mathbf{r}})|S_l\big){\rm P}\big(S_l\big)$.

\begin{figure}
	\centering
	\includegraphics[width=0.34\textwidth]{detect.pdf}
	\caption{The tradeoff between false alarm probability and detection probability in SHM.}
	\label{detect}
\end{figure}

The likelihood function is designed based on the derivation of the PEB.
Initially, we encode knowledge of the ${\sf U}$ state into the likelihood function for $\mathcal{H}_0$, which provides the probability density $f\big(d(\hat{\mathbf{r}})|{\sf U}\big)$ of $d(\hat{\mathbf{r}})$.
We assume that $f\big(d(\hat{\mathbf{r}})|{\sf U}\big)$ follows a Gaussian distribution with zero mean and variance $\sigma^2_{\rm p}(\mathbf{r}_0)$.
The likelihood function under   $\mathcal{H}_1$, $f(d(\hat{\mathbf{r}})|{\sf D})$, is modeled as a Gaussian distribution with a mean of $d(\hat{\mathbf{r}})$ and variance $\sigma^2_{\rm p}(\hat{\mathbf{r}})$.

The PEB governs the shapes of the likelihood functions $f\big(d(\hat{\mathbf{r}})|{\sf U}\big)$ and $f\big(d(\hat{\mathbf{r}})|{\sf D}\big)$, thereby impacting the detection probability of the damaged state, as illustrated in Fig. \ref{detect}. 
Our observations are twofold:
\begin{itemize}
	\item {\bf PEB:} When the threshold $\kappa$ remains constant, a smaller PEB results in a sharper distribution function, reducing the overlap between the two functions. This reduction in overlap lowers the false alarm probability and increases the detection probability.

	\item {\bf Threshold Selection Trade-off:} As the deformation detection requirements become more stringent (i.e., with a lower $\kappa$), the overlap between the two distributions increases. This introduces a trade-off between detection probability and false alarm probability. A lower threshold ($d_{\rm small}$) increases the false alarm rate, whereas a higher threshold ($d_{\rm large}$) reduces the detection probability.
\end{itemize}
Consequently, our objective is to minimize the PEB through the optimal configuration of the cellular system to achieve the required structure state detection performance.
In addition, by combining displacement monitoring from multiple reference points, more complex types of deformation, such as roll, torsion, and bending [Fig. \ref{scenario}(b)-(g)], can be identified. Furthermore, continuous monitoring can incorporate Bayesian principles for multistage decision-making. These are all worth exploring in future research.


\section{Spatiotemporal Cooperation in ISAC Networks}\label{sec-Reference-Point-Localization}
In this section, we explore the opportunities for spatiotemporal cooperation in ISAC networks. Specifically, we analyze the 3D localization performance of the reference point (i.e., the RIS) under three distinct scenarios, which are discussed in the following subsections: (A) increasing the number of observation time instants, (B) increasing the number of cooperative receivers, and (C) increasing the number of cooperative receivers with self-positioning errors. 


\subsection{Increasing Observation Time Instants}

Since structural changes often occur gradually, the idle resources of the transceivers during off-peak periods can be effectively utilized. This study aims to investigate whether extending the observation time instants can enhance the sensing performance.

For $T$ observation time instants, the accumulated measurements are expressed as
\begin{equation} \label{y--1}
	\bar{\mathbf{y}}_{[2:T]}= {\left[\mathbf{y}_{2,1}^{\rm T},\ldots, \mathbf{y}_{T,{T-1}}^{\rm T}\right]}^{\rm T},
\end{equation}
where $\bar{\mathbf{y}}_{[2:T]} \in \mathbb{C}^{N_{\rm R}(T-1)\times1}$.
The FIM for localization over $T$ periods is given by
\begin{align} \label{FIM21}
\mathbf{F}_{[2:T]}(\mathbf{r})&=\frac{2 }{\sigma^2 }\Re\left\{  \frac{\partial \bar{\mathbf{y}}^{\rm T}_{[2:T]}}{\partial \mathbf{r}}\left(\frac{\partial \bar{\mathbf{y}}^{\rm T}_{[2:T]}}{\partial \mathbf{r}}\right)^{\rm H}\right\} \notag \\
&= \frac{2 }{\sigma^2 } \mathbf{J}  \Re\left\{ \sum_{i=2}^{T}\frac{\partial \mathbf{y}^{\rm T}_{i,{i-1}}}{\partial \boldsymbol{\eta}} \left(\frac{\partial \mathbf{y}^{\rm T}_{i,{i-1}}}{\partial \boldsymbol{\eta}}\right)^{\rm H} \right\} \mathbf{J}^{\rm H}.
\end{align}
According to Theorem \ref{T0}, the following corollary holds.

\begin{corollary}\label{CO1}
The EFIM for increased observation time instants is given by	
\begin{align}\label{EFIM4}  
	\mathbf{F}_{{\rm e }{[2:T]}}(\mathbf{r}) &= \sum_{i=2}^{T}  \lambda_{i,\tau_{{\rm r}}} \mathbf{u}_{\tau_{\rm r}}\mathbf{u}_{\tau_{\rm r}}^{\rm H}   \nonumber\\
	&~~+ \sum_{i=2}^{T} (\lambda_{i,\phi_{{\rm r}}^{\rm az}} -\chi_{i,\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}})  \mathbf{u}_{\phi_{\rm r}^{\rm az}}\mathbf{u}_{\phi_{\rm r}^{\rm az}}^{\rm H}  \nonumber\\
	&~~~~+ \sum_{i=2}^{T}(\lambda_{i,\phi_{{\rm r}}^{\rm el}}-\chi_{i,\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}) \mathbf{u}_{\phi_{\rm r}^{\rm el}}\mathbf{u}_{\phi_{\rm r}^{\rm el}}^{\rm H}.
\end{align}
In \eqref{EFIM4}, the range and angle information at different time instants are aligned along consistent directions.
Moreover, time accumulation yields localization performance gains regardless of the RIS phase configurations. If the RIS phases are optimized,\footnote{The optimal phase configuration alternates between $\mathbf{\Omega}_{-}$ and $\mathbf{\Omega}_{+}$ for consecutive observation periods.} according to \eqref{THE1}, the EFIM simplifies to 
\begin{equation} \label{FIM22}
	\mathbf{F}_{{\rm e }{[2:T]}}(\mathbf{r}) =(T-1)\mathbf{F}_{\rm e }(\mathbf{r}) .
\end{equation}
\end{corollary}

Corollary \ref{CO1} implies that increasing the number of observation time instants expands the information ellipsoid, as shown in Fig. \ref{ellips}(a), thereby effectively reducing localization errors. 


\subsection{Increasing the Number of Receivers}\label{mr} 
A key advantage of cellular systems compared to other sensing systems is their dense network coverage.
By utilizing multiple base stations cooperatively, more accurate sensing results can be achieved.

For $K$ cooperative receivers, the accumulated measurements can be expressed as 
\begin{equation} \label{y--2}
	\bar{\mathbf{y}}^{[1:K]}= \left[({\mathbf{y}_{i,i-1}^1})^{\rm T},\ldots, ({\mathbf{y}_{i,i-1}^K})^{\rm T} \right]^{\rm T}.
\end{equation}
The total channel parameters for $K$ receivers are extended as
\begin{equation}
\bar{\boldsymbol{\eta}}=[\boldsymbol{\eta}_1^{\rm T}, \ldots,\boldsymbol{\eta}_K^{\rm T}]^{\rm T},
\end{equation}
where $\boldsymbol{\eta}_k\!=\![\tau_{{\rm r},k},\!\phi_{{\rm r},k}^{\rm az},\!\phi_{{\rm r},k}^{\rm el},\!\tilde{\phi}_{{\rm r},k}^{\rm az},\!\tilde{\phi}_{{\rm r},k}^{\rm el},\!\tilde{\theta}_{{\rm r},k}^{\rm az},\!\tilde{\theta}_{{\rm r},k}^{\rm el},\! \theta_{{\rm r},k}^{\rm az},\!\theta_{{\rm r},k}^{\rm el},\!{\Re}\{g_{{\rm r},k}\}\!,\\ {\Im}\{g_{{\rm r},k}\}]^{\rm T}.$
Consequently, the FIM for $\bar{\boldsymbol{\eta}}$ is given by
\begin{equation} \label{FIMeta1}
	\mathbf{F}^{[1:K]}(\bar{\boldsymbol{\eta}})=\frac{2 }{\sigma^2 }\Re\left\{ \frac{\partial (\bar{\mathbf{y}}^{[1:K]})^{\rm T}}{\partial \bar{\boldsymbol{\eta}} }\left(\frac{\partial (\bar{\mathbf{y}}^{[1:K]})^{\rm T}}{\partial \bar{\boldsymbol{\eta}} }\right)^{\rm H} \right\}.
\end{equation}
Define $	\bar{\mathbf{J}} =\big[\mathbf{J}_1,  \mathbf{J}_2,  \ldots , \mathbf{J}_K\big]$,
where $ \mathbf{J}_k = {\partial\boldsymbol{\eta}_k^{\rm T}}/{\partial \mathbf{r}}$.
Therefore, the resulting FIM is
\begin{equation} \label{FIM66}
\mathbf{F}^{[1:K]}(\mathbf{r})=\bar{\mathbf{J}}	F(\bar{\boldsymbol{\eta}})  \bar{\mathbf{J}} ^{\rm H}.
\end{equation} 
According to Theorem~\ref{T0}, we have the following corollary.
\begin{corollary}\label{C3}
	The EFIM for an increased number of receivers is given by	
\begin{align}\label{EFIM44}
	\mathbf{F}_{\rm e }^{[1:K]}(\mathbf{r}) & = \sum_{k=1}^{K} \lambda_{\tau_{\rm r}}^{k} \mathbf{u}^{k}_{\tau_{\rm r}}\mathbf{u}^{k{\rm H}}_{\tau_{\rm r}} \nonumber\\
	&~~+ \sum_{k=1}^{K} (\lambda_{\phi_{{\rm r}}^{\rm az}}^{k}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}^{k}) \mathbf{u}^{k}_{\phi_{\rm r}^{\rm az}}\mathbf{u}^{k{\rm H}}_{\phi_{\rm r}^{\rm az}} \nonumber\\
	&~~+ \sum_{k=1}^{K} (\lambda^{k}_{\phi_{{\rm r}}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}^{k})\mathbf{u}^{k}_{\phi_{\rm r}^{\rm el}}\mathbf{u}^{k{{\rm H}}}_{\phi_{\rm r}^{\rm el}},
\end{align}
where the range and angle information from different receivers generally point in different directions. 
\end{corollary}



\begin{figure*}[htbp]
	\centering
	\includegraphics[width=0.9\textwidth]{Fig1-scale1.pdf}
	\caption{Relationship among scene scale, bandwidth, and (a) RII and AII, and (b) PEB.}
	\label{fig1} 
    \vspace{-0.3cm}
\end{figure*}

Since the directional matrix associated with each receiver depends on its position, as shown in Fig. \ref{ellips}(b), optimizing receiver placement can make the information ellipsoid more isotropic, resembling a uniform sphere, particularly when the number of cooperative receivers is limited. This ensures that the reference point has a uniform localization capability in 3D space.
The claim that the CRLB decreases with an increasing number of receivers is supported by the following corollary.
\begin{corollary}\label{C2}
	Given $\bar{\mathbf{y}}^{[1:K+1]}$, the CRLB satisfies the following inequality:
	\begin{equation} \label{eq:th2} 
		{\rm CRLB}^{[1:K+1]}(\mathbf{r})  \leq {\rm CRLB}^{[1:K]}(\mathbf{r}).
		\end{equation}
\end{corollary}

\begin{proof}
According to \eqref{EFIM44}, we have 
\begin{equation} \label{EFIM35}
	\mathbf{F}_{\rm e }^{[1:K+1]}(\mathbf{r}) \!=\!\!\! \sum_{k=1}^{K+1}\!\! \mathbf{U}^k 	\!\!
	\left[\!\!\begin{array}{ccc}
	\!	\lambda_{\tau_{\rm r}}^{k} \!\!& 0                                  & 0  \\		
		0                          & \!\!\lambda_{\phi_{{\rm r}}^{\rm az}}^{k}\!-\!\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}^{k}  \!\!  & 0  \\
		0                          & 0                                  &\!\! \lambda^{k}_{\phi_{{\rm r}}^{\rm el}}\!-\!\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}^{k}\!\!\\
	\end{array}\!\!\right] \!\!\mathbf{U}^{k{\rm H}}, 	
\end{equation}
where $\mathbf{U}^k = [\mathbf{u}_{\tau_{\rm r}}^k,\mathbf{u}_{\phi_{\rm r}^{\rm az}}^k,\mathbf{u}_{\phi_{\rm r}^{\rm el}}^k]$.
Since each summation matrix in \eqref{EFIM35} is positive semi-definite, it follows that
\begin{equation} \label{EFIM45}
	\mathbf{F}_{\rm e }^{[1:K+1]}(\mathbf{r}) \succcurlyeq 	\mathbf{F}_{\rm e }^{[1:K]}(\mathbf{r}). 	
\end{equation}
Therefore, we have
\begin{equation} \label{EFIM65}
	\big[\mathbf{F}_{\rm e }^{[1:K+1]}(\mathbf{r})\big]^{-1} \preccurlyeq	\big[\mathbf{F}_{\rm e }^{[1:K]}(\mathbf{r})\big]^{-1}. 		
\end{equation}
Taking the trace on both sides yields
\begin{equation} \label{EFIM75}
		\Tr\big(\mathbf{F}_{\rm e }^{[1:K+1]}(\mathbf{r})\big)^{-1} \leq \Tr\big(\mathbf{F}_{\rm e }^{[1:K]}(\mathbf{r})\big)^{-1}.
\end{equation}
Recalling that ${\rm CRLB}^{[1:K+1]}(\mathbf{r}) =\Tr\big(\mathbf{F}_{\rm e }^{[1:K+1]}(\mathbf{r})\big)^{-1}$ and $ {\rm CRLB}^{[1:K]}(\mathbf{r})=\Tr\big(\mathbf{F}_{\rm e }^{[1:K]}(\mathbf{r})\big)^{-1}$, the result follows.
\end{proof}


\subsection{Increasing Receivers with Self-Positioning Errors} 

In cellular networks, mobile users can also serve as cooperative receivers.\footnote{In practice, the RIS typically lacks knowledge of the UE's position, and the UE can only engage in cooperative sensing by opportunistically receiving reflected signals from the RIS during movement. To increase the chances of such reflections, the RIS can use random phase configurations or beam-scanning strategies for spatial diversity. Since SHM does not demand real-time sensing, the UE can accumulate these signals over time to achieve cooperative sensing gains.} However, their mobility introduces position uncertainties that must be taken into account. Moreover, even when the receiver is a fixed base station, external environmental disturbances (such as wind or structural vibrations) may cause slight movements or vibrations of the antenna array, which also lead to self-positioning errors. In this subsection, we analyze how such self-positioning errors of the receivers affect the sensing accuracy.

We begin by considering a scenario with a single receiver at a specific time instant, where the receiver's position is subject to errors.
Let $\mathbf{b}_{\rm R}={[x_{\rm R},y_{\rm R},z_{\rm R}]}^{\rm T}$ denote the true position of the cooperative receiver. The measured position, $\hat{\mathbf{b}}_{\rm R}$, is modeled as 
\begin{equation} \label{tr}
	\hat{\mathbf{b}}_{\rm R}=\mathbf{b}_{\rm R}+ \boldsymbol{\epsilon}_{\rm R},
\end{equation}
where $\boldsymbol{\epsilon}_{\rm R}$ represents the position error, which follows a Gaussian distribution with a mean of zero and a diagonal covariance matrix $\mathbf{Q}_{\rm R}$.
Let $\mathbf{J}_{\rm R} = {\partial\boldsymbol{\eta}^{\rm T}}/{\partial \mathbf{b}_{\rm R}}$. Noting the relationship between the derivatives, we have $\mathbf{J}_{\rm R} = -\mathbf{J}$. Consequently, the FIM for the system that accounts for the receiver position error is given by 
\begin{align} \label{FIM9}
	\mathbf{F}(\mathbf{r}, \mathbf{b}_{\rm R})  &=\left[\begin{array}{cc}
		\mathbf{J} \mathbf{F}(\boldsymbol{\eta})  \mathbf{J}^{\rm H}  &  \mathbf{J} \mathbf{F}(\boldsymbol{\eta}) \mathbf{J}_{\rm R}^{\rm H}  \\		
		\mathbf{J}_{\rm R} \mathbf{F}(\boldsymbol{\eta}) \mathbf{J}^{\rm H}              & \mathbf{J}_{\rm R} \mathbf{F}(\boldsymbol{\eta}) \mathbf{J}_{\rm R}^{\rm H}+\mathbf{Q}_{\rm R}^{-1}\\
	\end{array}\right].
\end{align}
Let $\mathbf{U} = [\mathbf{u}_{\tau_{\rm r}}, \mathbf{u}_{\phi_{\rm r}^{\rm az}}, \mathbf{u}_{\phi_{\rm r}^{\rm el}}]$. By performing a unitary transformation on $ \mathbf{Q}_{\rm R}^{-1}$, we can write $\mathbf{Q}_{\rm R}^{-1} = \mathbf{U}\tilde{\mathbf{Q}}_{\rm R}^{-1}\mathbf{U}^{\rm H} $, where 
\begin{align}\label{tildeQ}
	\tilde{\mathbf{Q}}_{\rm R}^{-1} = \left[\begin{array}{ccc}
		\epsilon_{\tau}^{-1}  & 0                                  & 0  \\		
		0                      & \epsilon_{\phi^{\rm az}}^{-1}    & 0  \\
		0                      & 0                                  & \epsilon_{\phi^{\rm el}}^{-1} \\
	\end{array}\right].
\end{align}  
Here, $\epsilon_{\tau}^{-1}$, $\epsilon_{\phi^{\rm az}}^{-1}$, and $\epsilon_{\phi^{\rm el}}^{-1}$ represent the information intensities along the directions of $\mathbf{u}_{\tau_{\rm r}}$, $\mathbf{u}_{\phi_{\rm r}^{\rm az}}$, and $\mathbf{u}_{\phi_{\rm r}^{\rm el}}$, respectively, as shown in Fig. \ref{ellips}(b). 
Based on these developments, we state the following theorem.
\begin{theorem}\label{T1}
The EFIM for 3D RIS localization in the presence of receiver self-positioning errors is given by
%\begin{align} \label{EFIM55} 
%		\tilde{\mathbf{F}}_{\rm e }(\mathbf{r}) \! = \!\! \mathbf{U} \!\!\left[\begin{array}{ccc}
%			\!\!\!\frac{\lambda_{\tau_{\rm r}}\epsilon_{\tau}}{\lambda_{\tau_{\rm r}}+\epsilon_{\tau}}  & 0                                  & 0  \\		
%			0                      & \!\!\frac{(\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az},\phi_{\rm r}^{\rm el}})\epsilon_{\phi^{\rm az}}}{\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az},\phi_{\rm r}^{\rm el}}+\epsilon_{\phi^{\rm az}}}    & 0  \\
%			0                      & 0                                  & \!\! \frac{(\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el},\phi_{\rm r}^{\rm az}})\epsilon_{\phi^{\rm el}}}{\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el},\phi_{\rm r}^{\rm az}}+\epsilon_{\phi^{\rm el}}}\!\!\!  \\
%		\end{array}\right]\!\!\mathbf{U}^{\rm H}\!\!.
%\end{align}
%That is
\begin{align} \label{EFIM55} 
	\tilde{\mathbf{F}}_{\rm e }(\mathbf{r})& = \frac{\lambda_{\tau_{\rm r}}\epsilon_{\tau}^{-1}}{\lambda_{\tau_{\rm r}}+\epsilon_{\tau}^{-1}}  \mathbf{u}_{\tau_{\rm r}}\mathbf{u}_{\tau_{\rm r}}^{\rm H} \nonumber\\
	& ~~+ \frac{(\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}})\epsilon_{\phi^{\rm az}}^{-1}}{\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}+\epsilon_{\phi^{\rm az}}^{-1}} \mathbf{u}_{\phi_{\rm r}^{\rm az}}\mathbf{u}_{\phi_{\rm r}^{\rm az}}^{\rm H} \nonumber\\
&~~ + \frac{(\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}})\epsilon_{\phi^{\rm el}}^{-1}}{\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}+\epsilon_{\phi^{\rm el}}^{-1}}\mathbf{u}_{\phi_{\rm r}^{\rm el}}\mathbf{u}_{\phi_{\rm r}^{\rm el}}^{\rm H}.
\end{align}
\end{theorem}
The proof is provided in Appendix \ref{A2}.

Theorem \ref{T1} reveals that when a cooperative receiver exhibits large position errors, i.e.,  $\epsilon_{\tau}^{-1}$, $\epsilon_{\phi^{\rm az}}^{-1}$, $\epsilon_{\phi^{\rm el}}^{-1} \rightarrow 0$, the EFIM reduces to $\tilde{\mathbf{F}}_{\rm e }(\mathbf{r})=\mathbf{0}$. This implies that the cooperative receiver provides no useful information.
Building upon the results from Section~\ref{mr}, we state the following corollary.
\begin{corollary}\label{CO2}	
	Introducing an additional receiver with limited position uncertainty can still reduce the CRLB. Furthermore, the CRLB satisfies the following inequality:
	\begin{multline} \label{eq:th4} 		
		{\rm CRLB}^{[1:K+1]}(\mathbf{r})  \\
		\overset{(a)}{\leq}  {\rm CRLB}^{[1:K+1]}(\mathbf{r},\mathbf{b}_{\rm R}) \\
		 \overset{(b)}{\leq} {\rm CRLB}^{[1:K]}(\mathbf{r}),
	\end{multline}
	where
	\begin{equation}
	{\rm CRLB}^{[1:K+1]}(\mathbf{r},\mathbf{b}_{\rm R})= \Tr\Big(\big(\mathbf{F}_{\rm e }^{[1:K]}(\mathbf{r})+\tilde{\mathbf{F}}_{\rm e }^{[K+1]}(\mathbf{r})\big)^{-1}\Big),
    \end{equation}
    and $\tilde{\mathbf{F}}_{\rm e }^{[K+1]}(\mathbf{r})$ is obtained from \eqref{EFIM55} by replacing the parameters $ \lambda_{\tau_{\rm r}} $, $\lambda_{\phi_{\rm r}^{\rm az}}$, $\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}$, $\lambda_{\phi_{\rm r}^{\rm el}}$, and $\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}$ with their respective values for the ${(K+1)}$-th receiver.  ${\rm CRLB}^{[1:K+1]}(\mathbf{r})$ and ${\rm CRLB}^{[1:K]}(\mathbf{r})$ represent the CRLB obtained from the cooperation of ${K+1}$ and $K$ receivers with perfectly known positions, respectively. 
\end{corollary}
\begin{proof}
	According to \eqref{EFIM55}, we can infer that $\mathbf{0}  \preccurlyeq \tilde{\mathbf{F}}_{\rm e }^{[K+1]}(\mathbf{r}) \preccurlyeq {\mathbf{F}}_{\rm e }^{[K+1]}(\mathbf{r})$. Thus, inequalities (a) and (b) follow directly.
\end{proof}

Corollary~\ref{CO2} indicates that a cooperative receiver with large positioning errors does not degrade the overall Fisher information of the network.


