	\subsection{Geometric Relationship}\label{A0}
	According to the system model, the RIS position is given by $\mathbf{r} = [x_{\rm r},y_{\rm r},z_{\rm r}]^{\rm T}$, and the receiver position is $\mathbf{b}_{\rm R}=[x_{\rm R},x_{\rm R},x_{\rm R}]^{\rm T}$. Their geometric relationship is as follows: 
	\begin{subequations}
		\begin{align}
		x_{\rm r} - x_{\rm R} &= c(\tau_{\rm r}-\tau_{\rm tr})\cos \phi_{\rm r}^{\rm el} \cos\phi_{\rm r}^{\rm az}, \label{GR0}\\ 
		y_{\rm r} - y_{\rm R} &= c(\tau_{\rm r}-\tau_{\rm tr})\cos \phi_{\rm r}^{\rm el} \sin\phi_{\rm r}^{\rm az},\label{GR1}\\
		z_{\rm r} - z_{\rm R} &= c(\tau_{\rm r}-\tau_{\rm tr})\sin \phi_{\rm r}^{\rm el}\label{GR2}.
		\end{align}
	\end{subequations}
	Given the RIS orientation $\boldsymbol{\alpha}_{\rm r}=[ \alpha_{\rm r}^{\rm x},\alpha_{\rm r}^{\rm z}]^{\rm T}$, we define a local coordinate system where the RIS serves as the origin and the RIS array plane aligns with the $y'$-$z'$ plane. In this coordinate system, the receiver position is represented as $\mathbf{b}'_{\rm R}=[x'_{\rm R},y'_{\rm R},z'_{\rm R}]^{\rm T}$, which satisfies
	\begin{equation}\label{GR3}
    \mathbf{b}'_{\rm R}= -\mathbf{R}^{-1}( \alpha_{\rm r}^{\rm x},\alpha_{\rm r}^{\rm z})(\mathbf{r}-\mathbf{b}_{\rm R}),
	\end{equation}
	where the rotation matrix is given by
	\begin{equation}\label{GR4}
    \mathbf{R}( \alpha_{\rm r}^{\rm x},\alpha_{\rm r}^{\rm z})\!\!=\!\!\left[\!\!\begin{array}{ccc}
    \cos\alpha_{\rm r}^{\rm z} & -\sin\alpha_{\rm r}^{\rm z}\cos \alpha_{\rm r}^{\rm x} & -\sin\alpha_{\rm r}^{\rm z} \sin\alpha_{\rm r}^{\rm x} \\
    \sin\alpha_{\rm r}^{\rm z} & \cos\alpha_{\rm r}^{\rm z}\cos\alpha_{\rm r}^{\rm x} & \cos\alpha_{\rm r}^{\rm z}\sin\alpha_{\rm r}^{\rm x}\\
    0 & -\sin\alpha_{\rm r}^{\rm x} & \cos\alpha_{\rm r}^{\rm x}
    \end{array}\!\!\right]\!\!,
	\end{equation}
	with $\mathbf{R}^{-1}( \alpha_{\rm r}^{\rm x},\alpha_{\rm r}^{\rm z}) = \mathbf{R}^{\rm T}( \alpha_{\rm r}^{\rm x},\alpha_{\rm r}^{\rm z}) $.
	Furthermore, we have
	\begin{subequations}\label{GR5}
		\begin{align}
		x'_{\rm R} &= c(\tau_{\rm r}-\tau_{\rm tr})\cos \tilde{\phi}_{\rm r}^{\rm el} \cos\tilde{\phi}_{\rm r}^{\rm az}, \\ 
		y'_{\rm R} &= c(\tau_{\rm r}-\tau_{\rm tr})\cos \tilde{\phi}_{\rm r}^{\rm el} \sin\tilde{\phi}_{\rm r}^{\rm az},\\
		z'_{\rm R} &= c(\tau_{\rm r}-\tau_{\rm tr})\sin \tilde{\phi}_{\rm r}^{\rm el}.
		\end{align}
	\end{subequations}	
    By combining \eqref{GR3} and \eqref{GR5}, we establish the relationship between the AOD measurement at the RIS, the RIS state, and the receiver position. A similar geometric relationship holds between the RIS and the transmitter. 





