\begin{align}\label{A1}
	a &= \frac{F_{ \tau_{\rm r} \tau_{\rm r}}}{c^2} \\
	b &= \frac{F_{  \phi_{\rm r}^{\rm az} \phi_{\rm r}^{\rm az}} }{c^2(\tau_{\rm r}-\tau_{\rm tr})^2\cos^2 \phi_{\rm r}^{\rm el}}\\ 
	c &= \frac{F_{  \phi_{\rm r}^{\rm el} \phi_{\rm r}^{\rm el}} }{c^2(\tau_{\rm r}-\tau_{\rm tr})^2}\\
	d &= \frac{F_{  \phi_{\rm r}^{\rm el} \phi_{\rm r}^{\rm az}}  }{c^2(\tau_{\rm r}-\tau_{\rm tr})^2\cos\phi_{\rm r}^{\rm el}}. 
\end{align}
Then, we define 
\begin{align}\label{A2}
	\mathbf{A} &=\left[\!\begin{array}{ccc}
		a & 0 & 0 \\
		0 & b & d \\
		0 & d & c
	\end{array}\right], 
\end{align}	
and
\begin{align}\label{B1}
	\mathbf{B} &= \left[\begin{array}{ccc}
		a & 0 & 0 \\
		0 & b-\dfrac{d^2}{c} & 0 \\
		0 & 0 &  c-\dfrac{d^2}{b}
	\end{array}\!\!\right].
\end{align}	
The inverse can be easily derived 
\begin{align}\label{invA}
	\mathbf{A}^{-1} &=\left[\!\begin{array}{ccc}
		a^{-1} & 0 & 0 \\
		0 & \dfrac{c}{bc-d^2} & \dfrac{-d}{bc-d^2} \\
		0 & \dfrac{-d}{bc-d^2} & \dfrac{b}{bc-d^2}
	\end{array}\right], 
\end{align}	
and
\begin{align}\label{invB}
	\mathbf{B}^{-1} &= \left[\begin{array}{ccc}
		a^{-1} & 0 & 0 \\
		0 & \dfrac{c}{bc-d^2} & 0 \\
		0 & 0 &  \dfrac{b}{bc-d^2}
	\end{array}\!\!\right].
\end{align}				
Utilizing the unitary property of the matrix, i.e., $\mathbf{U}^{\rm H} \mathbf{U} = \mathbf{I}$, we have
\begin{equation}
	\tr(\mathbf{F}^{-1}(\mathbf{r})) = \tr(\mathbf{U}\mathbf{A}^{-1}\mathbf{U}^{\rm H})=\tr(\mathbf{A}^{-1}),
\end{equation}
and
\begin{equation}
	\tr(\mathbf{F}^{-1}_{\rm e}(\mathbf{r})) = \tr(\mathbf{U}\mathbf{B}^{-1}\mathbf{U}^{\rm H})=\tr(\mathbf{B}^{-1}).
\end{equation}
Acoording to \eqref{invA} and \eqref{invB}, we have $\tr(\mathbf{A}^{-1})=\tr(\mathbf{B}^{-1})$, thus, the expression of $\mathbf{F}_{\rm e}(\mathbf{r})$ provided in \eqref{expandEFIM} holds true.


Defining
\begin{subequations}\label{define}
	\begin{align}
		\lambda_{\tau_{\rm r}} &= \frac{F_{\tau_{\rm r}\tau_{\rm r}}}{c^2},  \\
		\lambda_{\phi_{\rm r}^{\rm az}}  &= \frac{F_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm az}}}{c^2(\tau_{\rm r}-\tau_{\rm tr})^2\cos^2\phi_{\rm r}^{\rm el}}, \\
		\lambda_{\phi_{\rm r}^{\rm el}} &= \frac{F_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm el}}}{c^2(\tau_{\rm r}-\tau_{\rm tr})^2}, \\
		\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}} &= \frac{F_{  \phi_{\rm r}^{\rm el} \phi_{\rm r}^{\rm az}}F_{  \phi_{\rm r}^{\rm az} \phi_{\rm r}^{\rm el}} }{c^2(\tau_{\rm r}-\tau_{\rm tr})^2\cos^2 \phi_{\rm r}^{\rm el}F_{  \phi_{\rm r}^{\rm el} \phi_{\rm r}^{\rm el}}}, \\
		\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}} &=\frac{F_{  \phi_{\rm r}^{\rm az} \phi_{\rm r}^{\rm el}} F_{  \phi_{\rm r}^{\rm el} \phi_{\rm r}^{\rm az}}}{c^2(\tau_{\rm r}-\tau_{\rm tr})^2F_{  \phi_{\rm r}^{\rm az} \phi_{\rm r}^{\rm az}}},
	\end{align}
\end{subequations}
we have
\begin{align}
	\mathbf{F}_{\rm e}(\mathbf{r})& = \lambda_{\tau_{\rm r}} \mathbf{u}_{\tau_{\rm r}}\mathbf{u}_{\tau_{\rm r}}^{\rm H} + (\lambda_{\phi_{\rm r}^{\rm az}} - \chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}) \mathbf{u}_{\phi_{\rm r}^{\rm az}}\mathbf{u}_{\phi_{\rm r}^{\rm az}}^{\rm H} \nonumber \\
	&~~+ (\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}} )\mathbf{u}_{\phi_{\rm r}^{\rm el}}\mathbf{u}_{\phi_{\rm r}^{\rm el}}^{\rm H}.
\end{align}
Finally, the \eqref{THE1} is proven.


\subsection{Proof of Non-negativity}\label{A3}
We take $\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}$ as an example to prove its non-negativity. 
According to \eqref{fim-az2}, \eqref{fim-el2}, and \eqref{fim-azel2}, we can calculate that
\begin{align}
\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}} & = \kappa_1^2 \big(\mu_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm az}}\mu_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm el}}-\mu_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}\mu_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}\big)\nonumber\\
& = \kappa_2^2 \cos^2 \!\phi_{\rm r}^{\rm el}(N_{\rm R}^{\rm el}\!-\!1)(7N_{\rm R}\!+\!N_{\rm R}^{\rm az}\!+\!N_{\rm R}^{\rm el}\!-\!5),
\end{align}
where $\kappa_1$ and $\kappa_2$ are real coefficients. Since $N_{\rm R}^{\rm az},N_{\rm R}^{\rm el} \ge 1$, we have $\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}} \ge 0$. 

\subsection{Proof of Theorem 5}\label{A2}
We derive the EFIM from \eqref{FIM9} as
\begin{equation} \label{EFIM14} 
		\tilde{\mathbf{F}}_{\rm e }(\mathbf{r})\! =\! \mathbf{J} \mathbf{F}(\boldsymbol{\eta})  \mathbf{J}^{\rm H} \!-\! \mathbf{J} \mathbf{F}(\boldsymbol{\eta}) \mathbf{J}_{\rm R}^{\rm  H\!}\! \big(\! \mathbf{J}_{\rm \!R\!} \mathbf{F}(\boldsymbol{\eta}) \mathbf{J}_{\rm R}^{\rm H}+\mathbf{Q}_{\rm R}^{-1}\! \big)^{\!-1}\! \mathbf{J}_{\rm\! R\!} \mathbf{F}(\boldsymbol{\eta}) \mathbf{J}^{\rm H}.		
\end{equation}
Let 
\begin{align}\label{FIM15}
	\tilde{\mathbf{F}}_{\rm A}  =  \diag(\lambda_{\tau_{\rm r}},\lambda_{\phi_{\rm r}^{\rm az}} - \chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}},\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}),
\end{align}
thus, we have 
\begin{align} \label{EFIM17} 
	\tilde{\mathbf{F}}_{\rm e }(\mathbf{r}) =  \mathbf{U} \tilde{\mathbf{F}}_{\rm A}  \mathbf{U}^{\rm H} -\mathbf{U} \tilde{\mathbf{F}}_{\rm A} \left( \tilde{\mathbf{F}}_{\rm A}+  \tilde{\mathbf{Q}}^{-1}_{\rm R} \right)^{-1}  \tilde{\mathbf{F}}_{\rm A}\mathbf{U}^{\rm H}.
\end{align}
Substituting \eqref{tildeQ} and \eqref{FIM15} into \eqref{EFIM17}, we obtain 
\begin{align} \label{EFIM5} 
	\tilde{\mathbf{F}}_{\rm e }(\mathbf{r}) \! = \!\! \mathbf{U} \!\! \left[\begin{array}{ccc}
		\!\!\!\frac{\lambda_{\tau_{\rm r}}\epsilon^{-1}_{\tau}}{\lambda_{\tau_{\rm r}}+\epsilon^{-1}_{\tau}}  & 0                                  & 0  \\		
		0                      &   \!\!\!\!\frac{(\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}})\epsilon^{-1}_{\phi^{\rm az}}}{\lambda_{\phi_{\rm r}^{\rm az}}-\chi_{\phi_{\rm r}^{\rm az}\phi_{\rm r}^{\rm el}}+\epsilon^{-1}_{\phi^{\rm az}}}    & 0  \\
		0                      & 0                                  &   \!\!\!\! \frac{(\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}})\epsilon^{-1}_{\phi^{\rm el}}}{\lambda_{\phi_{\rm r}^{\rm el}}-\chi_{\phi_{\rm r}^{\rm el}\phi_{\rm r}^{\rm az}}+\epsilon^{-1}_{\phi^{\rm el}}}\!\!\!  \\
	\end{array}\right]\!\!\!\mathbf{U}^{\rm H}\!\!.
