\begin{remark}
    The characterization of Theorem~\ref{T:main_martingality} still holds if, instead of $\sig$, we consider the signature of a time-extended Ornstein--Uhlenbeck process $\widehat{Y}_t = (t, Y_t)$ for the volatility process, where $Y$ satisfies  
    \[
    dY_t = a Y_t dt + b dW_t, \quad t \geq 0,
    \]
    for some $a, b \in \mathbb{R}$. Although slight modifications in the proof of Lemma~\ref{lem:expYV} are needed, the proof of this extension follows the same ideas presented later in this paper. The case of the Ornstein--Uhlenbeck process is important for practical applications as it includes the Quintic model of \citet*{quintic2022} and can be seen as a particular case of the multi-factor signature volatility model proposed by \citet*{cuchiero2023spvix}.
\end{remark}

\begin{remark}
Theorem~\ref{T:main_martingality}  provides useful insights into the practical use of the signature volatility model \eqref{eq:price_model}. Specifically, when performing a linear regression of the volatility process against the driving Brownian motion, using its exact signature representation, or calibrating the model, a suitable truncation order must be chosen. Our result offers clear and simple guidelines for selecting hyperparameters: $N$ should be chosen to be odd, while the condition on $ \rho\sigma^{\word{2}\conpow{N}} $ can be easily incorporated as a constraint in the optimization problem. Failing to do so could have dramatic consequences for martingality, as illustrated in Figure~\ref{fig:sig_smiles}.
\end{remark}

\begin{remark}\label{R:spotvolcorrel}
    We note that the condition $ \rho\sigma^{\word{2}\conpow{N}} \leq 0 $ does not imply that the spot-volatility correlation must be negative. Indeed, as shown in \cite[Subsection 3.2]{abijaber2024signature}, the spot-volatility correlation is given by
    $$
    \frac{d[\log S, |\sigma|]_t}{\sqrt{d[\log S]_t}\sqrt{d[|\sigma|]_t}} = \rho \cdot \sign{\bracketsig{\bsigma\proj{2}}},
    $$
    where $ \bsigma\proj{2} = \sum\limits_{n=0}^N \sum\limits_{|\word{v}| \leq n} \bsigma^{\word{v2}} \word{v} $. Since the sign depends on the other coefficients of $ \bsigma $, the spot-volatility correlation can be positive while still ensuring the price martingality. In this way, the model can be applied to markets with a positive implied volatility skew, such as FX or commodity markets.
\end{remark}


\subsection{Moments}\label{sect:main_res_mom}

In this subsection, we present our main result concerning the moment explosions of the process $S$ in the signature volatility model \eqref{eq:price_model}. Under the assumptions ensuring true martingality stated in Theorem~\ref{T:main_martingality}, we identify the threshold value of $m$ for which $\mathbb{E}[S_T^m]$ is finite.

\begin{theorem} \label{thm:moments} Let $S$ be given by \eqref{eq:price_model}. 
    Suppose that the order $N \geq 2$ is odd and $\rho\sigma^{\word{2}\conpow{N}} < 0$. 
    \begin{enumerate}
        \item[(i)] If $|\rho| < \sqrt{1 - \frac{1}{m}}$, then $\E[S_T^m] = + \infty$ for any $T>0$.
        \item[(ii)] If $|\rho| > \sqrt{1 - \frac{1}{m}}$, then $\E[S_T^m] < + \infty$ for any $T>0$.
    \end{enumerate}
\end{theorem}

\begin{proof}
    The proof is given in Section \ref{sect:moments}.
\end{proof}

\subsection{Extension of the martingality result to multidimensional setting}\label{sect:multid_extension}
Theorem~\ref{T:main_martingality} was stated for the signature volatility model \eqref{eq:price_model}, where the volatility process was constructed based on the signature of a one-dimensional Brownian motion $W$ correlated with $B$. Consider now a model
\begin{equation}
\begin{aligned}\label{eq:price_model_multid}
    \dfrac{dS_t}{S_t} &= \sigma_t dB_t, \quad t \geq 0, \\
    \sigma_t &= \bracketsigX[t][\widehat{Y}]{\bsigma},
\end{aligned}
\end{equation}

where $\sigX[t][\widehat Y]$ denotes the signature of $\widehat Y = (t, B, Z^1, \ldots, Z^d)$, $Z = (Z^1, \ldots, Z^d)$ is a $d$-dimensional Brownian motion independent from $B$ and $\bsigma\in\tTA[d+2]{N}$. Theorem~\ref{T:main_martingality} can be generalized as follows.

\begin{theorem}\label{T:main_martingality_multid}
 Let $S$ be given by \eqref{eq:price_model_multid}.      Suppose that the leading coefficient $\sigma^{\word{2}\conpow{N}} \not= 0$.
     \begin{enumerate}
         \item[(i)] If the order $N = 1$, then $S$ is a martingale. 
         \item[(ii)] If the order $N \geq 2$, then $S$ is a martingale if and only if $N$ is odd and $\sigma^{\word{2}\conpow{N}} \leq 0.$
     \end{enumerate}
\end{theorem}
\begin{proof}
    \textit{(i)} and sufficiency in \textit{(ii)} are proved in Section~\ref{sect:martingality_expec}, while necessity in \textit{(ii)} is proved in Subsection~\ref{section:proof_local_mart_mulitiD}.
\end{proof}

\begin{remark}\label{rmk:multid_model}
    The price model \eqref{eq:price_model} is indeed a special case of the model \eqref{eq:price_model_multid}, since the elements of the signature of $\widehat{W} = (t, W) = (t, \rho B + \sqrt{1 - \rho^2} B^\perp)$ can be written as a linear combination of elements of the signature of $\widehat{Y} = (t, B, B^\perp)$, such that $\bracketsig{\bsigma} = \bracketsigX[t][\widehat{Y}]{\tilde\bsigma}$ for some $\tilde\bsigma \in \tTA[3]{N}$ with the same order $N$. Moreover, the coefficient of $\tilde\bsigma$ corresponding to $\word{2}\conpow{N}$ equals $\rho^N\bsigma^{\word{2}\conpow{N}}$.
\end{remark}

\begin{remark}
    Although Theorem~\ref{T:main_martingality} directly follows from Theorem~\ref{T:main_martingality_multid} when $ \rho \neq 0 $, we chose to present the multidimensional framework after the one-dimensional one for several reasons. First, the model in \eqref{eq:price_model} is more natural and efficient in practice, as it uses a two-dimensional alphabet instead of the three-dimensional one used in its multidimensional counterpart. Moreover, the link between Theorems~\ref{T:main_martingality} and~\ref{thm:moments} and their Markovian counterparts, is much clearer when the one-dimensional model is introduced first. Finally, the methods used in the proof of Theorem~\ref{thm:moments} rely heavily on the structure of the equations in model \eqref{eq:price_model} and would be difficult to generalize to the multidimensional framework.
\end{remark}

