\section{Key lemmas for bounds on the signatures}\label{sect:bounds}
In this section, we state some bounds on signature elements which will be of crucial use throughout the rest of the paper. The first result states that terms in the signature of $\widehat X_t = (t,X_t)$ may be bounded in terms of the supremum norm of $X$.

\begin{lemma}\label{lemma:linear_from_upper_bound}
    Let $X\colon [0,T] \to \R$ be a continuous path, and let $\widehat{\mathbb{X}}_t$ denote the signature of  $\widehat{X}$.    
    Let $N_{\word{2}}(\word{w})$ denote the number of occurrences of letter $\word{2}$ in $\word{w}$. Then, for any word $\word{w}$, there exists a constant $C_{\word{w}} > 0$, such that
    \begin{equation}\label{eq:linear_form_as_bound}
     \sup_{t \in [0, T]}\left|\bracketsigX[t][\widehat{X}]{\word{w}} \right| \leq C_{\word{w}}T^{|\word{w}|-N_{\word{2}}(\word{w})}\max_{t \in [0, T]}\left|X_t\right|^{N_{\word{2}}(\word{w})}.
    \end{equation}
\end{lemma}
\begin{proof}
    The proof is given in Subsection~\ref{sect:first_lemma_proof}.
\end{proof}

We then consider the signature of the extended process $\widehat Y^X_t = (t, X_t, Z^1_t, \ldots, Z^d_t)$, where $Z_t = (Z^1_t, \ldots, Z^d_t)$ is a $d$-dimensional Brownian motion and $X$ is an arbitrary Itô process. While the terms of the signature no longer satisfy an almost sure bound as in the previous lemma, we show that a similar result still holds in a probabilistic sense.

\begin{lemma} \label{lem:expYV}
Let $Z = (Z^{1},\ldots,Z^d)$ be a $d$-dimensional Brownian motion, and let $X$ be an Itô process defined on the same probability space and such that $\langle Z^i, X\rangle \equiv 0$ for any $i = 1, \ldots, d$.
Let $\widehat{\mathbb{Y}}^X_t$ denote the signature of $\widehat Y_t^X$.  
Then, for any word $\word{w}$, any $q \geq 2$, $\epsilon > 0$, and any stopping time $\tau$ taking values in $[0,T]$, there exists a constant $C = C_{\word{w}, q, \epsilon, T}$ such that  
\begin{equation}\label{eq:second_bound}
\E\left[\int_0^{\tau} \left\langle \word{w}, \widehat{\mathbb{Y}}^X_t \right\rangle^{q} dt\right] \leq C \cdot \E \left[\int_0^{\tau} X_t^{q (N_{\word{2}}(\word{w}) + \epsilon)} dt\right],
\end{equation}
where $N_{\word{2}}(\word{w})$ denotes the number of occurrences of the letter $\word{2}$ in $\word{w}$.
\end{lemma}
\begin{proof}
    The proof is given in Subsection~\ref{sect:second_lemma_proof}.
\end{proof}
{\begin{remark}
    The statement of Lemma~\ref{lem:expYV} remains true if, for some $C_0 > 0$ and for any $i = 1, \ldots, d$,  
    \begin{equation*}\label{eq:covariation_assumption}
        \left| d \langle Z^i, X \rangle_t \right| \leq C_0 \, dt.
    \end{equation*}  
    In this case, the same proof is applicable since the cross-variation term appearing in the bounds can be controlled in exactly the same way as the drift term.
\end{remark}
}

\section{A general martingality criterion}\label{section:general_crit}

In this section, we derive a general criterion to establish the martingality of the price process in signature volatility models. Similarly to the Markovian setting, lack of martingality is seen by a Girsanov transform to be equivalent to the explosion of a certain SDE of signature drift form.

We let $S$ be given by \eqref{eq:price_model_multid}, i.e. the volatility process is given by
\begin{equation}
    \sigma_t = \left\langle \bsigma, \widehat{\mathbb{Y}} _t\right\rangle, \quad t \geq 0
\end{equation}
where $\widehat{\mathbb{Y}}_t$ is the signature of the process $\widehat Y_t = (t, B_t, Z^1_t, \ldots, Z^d_t)$, and $\bsigma \in \tTA[d+2]{N}$ for some $N \geq 1$.
% with the $W^i$, $i=1,\ldots, d$ and $B$ independent Brownian motions, and $\bsigma \in T^{(N)}(\R^{d+2})$ for some $N \geq 1$.

The criterion will be stated, in Theorem~\ref{T:explosion_criterion},  in terms of the solution to the SDE
\begin{equation} \label{eq:sdeX}
    X_t =  \int_0^t \left\langle \bsigma, \widehat{\mathbb{Y}}^X_s \right\rangle ds + B_t,
\end{equation}
where $\widehat{\mathbb{Y}}^X_t$ denotes the signature of $\widehat{Y}^X_t = (t, X_t, Z^1_t, \ldots, Z^d_t)$.

\subsection{Signature SDE}

In this subsection, we show the signature SDE \eqref{eq:sdeX}
is well-defined (up to an explosion time) for arbitrary $\bsigma$ in the truncated tensor algebra $\tTA[d+2]{N}$. 

We note that $X$ may explode in finite time, so the solution is understood as a process satisfying equation \eqref{eq:sdeX} on {$[[0,\tau^X_{\infty}[[$, where the explosion time $\tau^X_{\infty}$ is a stopping time defined by
\begin{equation}\label{eq:def_rau_inf_tau_n_X}
    \tau^X_{\infty} := \lim_{n \to\infty} \tau_n^X, \quad \tau_n^X:= \inf\{t \geq 0\colon\, |X_t| = n\},
\end{equation}
such that, on the event $\{\tau^X_{\infty} < \infty\}$, we have $\lim\limits_{t \to \tau^X_{\infty}} |X_t| = +\infty$ a.s.}

\begin{proposition} \label{prop:sigODE}
    The SDE \eqref{eq:sdeX} admits a unique strong solution. In addition, it holds that
    \begin{equation} \label{eq:explT}
        \tau^X_{\infty} = \inf \left\{ t \geq 0 , \;\; \int_0^t \langle\bsigma, \widehat{\mathbb{Y}}^X_s \rangle^2 ds = + \infty\right\}.
    \end{equation}
\end{proposition}

\begin{proof}
    For the well-posedness of the SDE, we note that it can be equivalently written as a system of classical (Markovian) SDEs. Indeed, setting $\widehat{\mathbb{Y}}^{X, \word{w}}_t = \langle\word{w}, \widehat{\mathbb{Y}}^X_t \rangle$, the signature SDE \eqref{eq:sdeX} is equivalent to $X = \widehat{\mathbb{Y}}^{X, \word{2}}$, where the $(\widehat{\mathbb{Y}}^{X, \word{w}})_{\word{w}:\, |\word{w}| \leq N}$ satisfy $\widehat{\mathbb{Y}}^{X, \emptyword} \equiv 1$ and for $|\word{u}| < N$, 
    \begin{align*}
    \widehat{\mathbb{Y}}^{X, \word{u}\word{1}}_t =& \int_0^t \widehat{\mathbb{Y}}^{X, \word{u}}_s ds, \\  
    \widehat{\mathbb{Y}}^{X, \word{u}\word{2}}_t =& \int_0^t \widehat{\mathbb{Y}}^{X, \word{u}}_s \left( \sum_{|\word{w}|\leq N} \bsigma^{\word{w}} \widehat{\mathbb{Y}}^{X, \word{w}}_s \right) ds + \int_0^t \widehat{\mathbb{Y}}^{X, \word{u}}_s \circ dB_s, \\
    \widehat{\mathbb{Y}}^{X, \word{u}\word{i}}_t =& \int_0^t \widehat{\mathbb{Y}}^{X, \word{u}}_s {\circ} dZ^{i - 2}_s,  \;\; i=3,\ldots, d + 2.\\
    \end{align*}
    This is a Stratonovich SDE with locally Lipschitz coefficients, for which existence and uniqueness up to an explosion time are standard.

    It remains to prove \eqref{eq:explT}. 
    {Since on the event $\{\tau^X_{\infty} < \infty\}$, we have $\int_0^{\tau^X_{\infty}}\langle\bsigma, \widehat{\mathbb{Y}}^X_s \rangle\, ds = X_{\tau^X_{\infty}} - B_{\tau^X_{\infty}} = \pm\infty$, it follows that
    \begin{equation*}
        \int_0^{\tau^X_{\infty}}\langle\bsigma, \widehat{\mathbb{Y}}^X_s \rangle^2 ds \geq \left(\int_0^{\tau^X_{\infty}}\langle\bsigma, \widehat{\mathbb{Y}}^X_s \rangle\, ds\right)^2 = +\infty,
    \end{equation*}
    we have  $\int_0^{\tau^X_{\infty}}\langle\bsigma, \widehat{\mathbb{Y}}^X_s \rangle^2 ds = +\infty $ on $\{\tau^X_{\infty} < \infty\}$}. Conversely, using Lemma~\ref{lem:expYV}, we obtain that for each word $\word{w}$,
    \[ \E\left[\int_0^{\tau_n^X\wedge T} \langle \word{w}, \widehat{\mathbb{Y}}^X_t \rangle^2 dt\right]\leq { C_{\word{w},T} n^{2|\word{w}|+1}} < \infty.  \]
    Since $\tau^X_{\infty} = \sup\limits_{n \geq 1} \tau^X_n$, this implies that $\int_0^t \langle\bsigma, \widehat{\mathbb{Y}}^X_s \rangle^2 ds < \infty$ for each $t<\tau^X_{\infty}$.
\end{proof}

\subsection{Martingality and explosion}
By the results of the previous subsection, equation \eqref{eq:sdeX} admits a unique strong solution up to an explosion time $\tau^X_{\infty}$, satisfying \eqref{eq:explT}.

\begin{theorem}\label{T:explosion_criterion}
For each $T>0$, for $S$ defined by \eqref{eq:price_model_multid}, it holds that
\[
S \mbox{ is a martingale on $[0,T]$} \; \Leftrightarrow \P(\tau^X_{\infty} < T ) = 0,
\]
where $\tau^X_{\infty}$ is the explosion time of $X$ defined by \eqref{eq:sdeX}.
\end{theorem}


 \begin{proof}
Since $S$ is a nonnegative local martingale, it is a supermartingale by Fatou's Lemma, so that $\E[S_T] \leq S_0$ for all $T \geq 0$. Hence, for a given $T>0$, it is a martingale on $[0,T]$ if and only if $\E\left[S_T\right] = S_0$. Let
\[ 
\tau_n = \inf\left\{ t > 0\colon\, \int_0^t \left\langle \bsigma, \widehat{\mathbb{Y}}_s\right\rangle^2 ds =n \right\}.
\]
As the stopped process $\left(\int_0^{t\land\tau_n} \left\langle \bsigma, \widehat{\mathbb{Y}}_s\right\rangle^2 ds\right)_{t \geq 0}$ is bounded by $n$, the stopped price process $S^{\tau_n} = (S_{t \land \tau_n})_{t \geq 0}$ is an exponential martingale by Novikov's criterion and it follows that
$$
S_0 = \E\left[S^{\tau_n}_T \right] = \E \left[S_{T\land\tau_n}\right] = \E\left[S_T\indic{T \leq \tau_n}\right] + \E \left[S_{\tau_n}\indic{\tau_n < T}\right] = \E\left[S_T\indic{T \leq \tau_n}\right] + S_0\widehat{\P}_n\left({\tau_n < T}\right),
$$
where $\dfrac{d\hat{\P}_n}{d\P} = \dfrac{S_{T\land \tau_n}}{S_0}$.

By the monotone convergence theorem, the term $\E\left[S_T\indic{T \leq \tau_n}\right]$ converges to $\E\left[S_T\right]$ as $n \to \infty$. Thus,
$$
S_0 - \E\left[S_T\right] = \lim_{n \to\infty} \E \left[S_{\tau_n}\indic{\tau_n < T}\right] = \lim_{n \to\infty} S_0\widehat{\P}_n\left({\tau_n < T}\right).
$$
On the other hand, by Girsanov theorem, for each $n$, it holds that for each $t \leq T$,
\[
B_t = \int_{0}^{t \wedge \tau_n} \left\langle \bsigma, \widehat{\mathbb{Y}}_s\right\rangle ds + \widehat{B}_t,
\]
where $\widehat{B}$ is a Brownian motion under $\widehat{\P}_n$. This implies that, under $\widehat{\P}_n$, $B$ is a solution to \eqref{eq:sdeX} on $[[0,\tau_n]]$, so that by (weak) uniqueness for \eqref{eq:sdeX}, the law of $(B_{t \wedge \tau_n})_{t \geq 0}$ under $\widehat{\P}_n$ is the same as the law of $(X_{t \wedge \tilde{\tau}_n})_{t \geq 0}$ under $\P$, with
\[ \tilde{\tau}_n = \inf \left\{t > 0\colon\, \int_0^t\left\langle \bsigma, \widehat{\mathbb{Y}}^X_s \right\rangle^2 ds = n \right\}, \]
so that 
\[
\lim_{n \to \infty}  \widehat{\P}_n\left({\tau_n < T}\right) = \lim_{n \to \infty}{\P}\left({\tilde{\tau}_n < T}\right) = \P\left(\tau^X_{\infty} < T\right),
\]
since $\lim\limits_{n \to \infty} \tilde{\tau}_n = \tau^X_{\infty}$.

 \end{proof}

\begin{corollary}\label{cor:one_d_criterion}
    The same proof applied to the one-dimensional model implies that $S$ given by \eqref{eq:price_model} is a martingale on $[0, T]$ if and only if $\P(\tau^X_{\infty} < T)$, where $\tau^X_{\infty}$ is the explosion time of $X$ defined by
    \begin{equation}\label{eq:sig_SDE_1D}
        X_t =  \rho\int_0^t \left\langle \bsigma, \widehat{\mathbb{X}}_s \right\rangle ds + W_t,
    \end{equation}
    and $\widehat{\mathbb{X}}_t$ denotes the signature of $\widehat{X}_t = (t, X_t)$, for $t \in [0, T]$.
\end{corollary}

