\section{Proof of bounds on signature elements}\label{sect:bounds_proofs}

\subsection{Polynomial representations in the shuffle algebra}\label{sect:polynomial_repr}

In this subsection, we recall the notion of \cite{Lyndon1954}  words which will help us prove the bounds given by Lemma~\ref{lemma:linear_from_upper_bound} and Lemma~\ref{lem:expYV}.
The extended tensor algebra $\eTA$ can be considered as an algebra endowed with a shuffle product. We define a shuffle multivariate polynomial $P\shupow{}$ of $n$ arguments as
$$
P\shupow{}: \eTA^n \to \eTA, \quad (\word{v_1}, \ldots, \word{v_n}) \mapsto 
 \sum_{\substack{p_1, \ldots, p_n}} c_{p_1, \ldots, p_n} \, \word{v_1}\shupow{p_1}\shuprod\word{v_2}\shupow{p_2}\ldots\shuprod\word{v_n}\shupow{p_n},
$$
where the sum is finite and taken over some set of positive natural numbers $p_1, \ldots, p_n$.
% \sout{As usual, we call $p_1 + \ldots + p_n$ the degree of monomial $\word{v_1}\shupow{p_1}\shuprod\word{v_2}\shupow{p_2}\ldots\shuprod\word{v_n}\shupow{p_n}$. The degree of polynomial $P\shupow{}$ denoted by $\deg(P\shupow{})$ is then a maximal degree over all monomials in $P\shupow{}$ with non-zero coefficients.}

The Lyndon words defined below are useful to construct the polynomial representations of the shuffle algebra elements.

\begin{definition}
    A Lyndon  word in an alphabet $\alphabet$ is a non-empty word that is strictly lexicographically greater than any of its non-trivial cyclic rotations. A set of all Lyndon words in the alphabet $\alphabet$ will be denoted by $\mathcal{L}(\alphabet)$, and $\mathcal{L}_N(\alphabet)$ will denote the Lyndon words of length not greater than $N$.
\end{definition}

\begin{example}
    The first Lyndon words in the alphabets $\alphabet[2]$ and $\alphabet[3]$ are given by
    \begin{itemize}
        \item $\mathcal{L}(\alphabet[2]) = \{\word{2}, \word{1}, \word{21}, \word{221}, \word{211}, \word{2221}, \word{2211}, \word{2111}, \ldots\}.$
        \item $\mathcal{L}(\alphabet[3]) = \{\word{3}, \word{2}, \word{1}, \word{32}, \word{31}, \word{21}, \word{332}, \word{331}, \word{322}, \word{321}, \word{312}, \word{311}, \word{221}, \word{211}, \ldots\}.$
    \end{itemize}
\end{example}


An important property of the Lyndon words is given by the  \cite{Radford1979ANR} Theorem. It states that the Lyndon words generate the shuffle algebra, i.e.~each element $\bell \in \TA$ can be represented by a shuffle polynomial $P_{\bell}\shupow{}$:
\begin{equation}
    \bell = P_{\bell}\shupow{}(\word{v_1}, \ldots, \word{v_{n_{\bell}}}), \quad \word{v_1}, \ldots, \word{v_{n_{\bell}}} \in \mathcal{L}.
\end{equation}
Moreover, if $\bell \in \tTA{N}$, then $\word{v_1}, \ldots, \word{v_{n_{\bell}}} \in \mathcal{L}_N$ and $\sum_{i = 1}^{n_{\bell}}p_i|\word{v_i}| \leq N$ {for all terms $\word{v_1}\shupow{p_1}\shuprod\ldots\shuprod\word{v_n}\shupow{p_n}$ in the polynomial $P_{\bell}\shupow{}$.} 


The following example provides explicit polynomial representations for {the words over alphabet $\{\word{1},\word{2}\}$} of length up to $3$ that can be easily verified.

\begin{example}
    \begin{enumerate}
        \item $\mathcal{L}_1 = \{\word{1}, \word{2}\}$ contains all the words of length $1$.
        \item $\mathcal{L}_2 = \{\word{1}, \word{2}, \word{21}\}$. The remaining words of length $2$ can be obtained as the following polynomials:
        \begin{align}
            \word{11} &= \dfrac{1}{2}\cdot\word{1}\shupow{2}, \\
            \word{12} &= \word{1}\shuprod\word{2} - \word{21}, \\
            \word{22} &= \dfrac{1}{2}\cdot\word{2}\shupow{2}.
        \end{align}
        \item $\mathcal{L}_3 = \{\word{1}, \word{2}, \word{21}, \word{211}, \word{221}\}$. The words of length $2$ were constructed above.  The remaining words of length $3$ can be obtained as polynomials:
    \begin{equation}
    \begin{aligned}
        \word{111} &= \dfrac{1}{6} \cdot\word{1}\shupow{3},  
        &\word{122} &= \dfrac{1}{2}\cdot\word{1}\shuprod\word{2}\shupow{2} - \word{21}\shuprod\word{2} + \word{221}, \\
        \word{112} &= \word{11}\shuprod\word{2} - \word{21}\shuprod\word{1} + \word{211}, 
        &\word{212} &= \word{21}\shuprod\word{2} - 2\cdot\word{221}, \\
        \word{121} &= \word{21}\shuprod\word{1} - 2\cdot\word{211}, 
        &\word{222} &= \dfrac{1}{6}\cdot\word{2}\shupow{3}.
    \end{aligned}
    \end{equation}
    \end{enumerate}
\end{example}
We note that no Lyndon word ends with the lexicographically greatest letter $\word{d}$, except for the word $\word{d}$ itself. Together with Radford's theorem, and noting that the letters in the alphabet can be ordered arbitrarily, this implies the following result.

\begin{proposition} \label{prop:nod}
Let $\word{w}$ be a word in $A_d$, and fix $\word{k} \in A_d$. Then $\word{w}$ can be expressed as a shuffle polynomial  
\[
\word{w} = P^{\shuprod}_{\word{w}}(\word{v_1}, \ldots, \word{v_k}),
\]
where each $\word{v_i}$ either does not end with the letter $\word{k}$ or is equal to $\word{k}$.
\end{proposition}

\begin{remark}
    {In the subsequent proofs, we will often deal with the signatures of \( \widehat{Y}^X_t = (t, X_t, Z_t^1, \ldots, Z_t^d) \), where \( X_t \) is an arbitrary Itô process and \( Z_t \) is a \( d \)-dimensional Brownian motion. It is then beneficial, in proofs using induction on word length, to represent an arbitrary word \( \word{w} \) as a polynomial of words that do not end with \( \word{2} \) (except for \( \word{2} \conpow{k} \)), corresponding to the process \( X \). This representation reduces the analysis to standard Riemann integrals and Stratonovich integrals with respect to the Brownian motion.}
\end{remark}

%Until other wise is stated, we consider the alphabet $\alphabet[2]$ and denote the Lyndon words simply by $\mathcal{L}$ and $\mathcal{L}_N$.


\subsection{Proof of Lemma~\ref{lemma:linear_from_upper_bound}}\label{sect:first_lemma_proof}

We will prove the result by induction on the length $ |\word{w}| $ of the word $\word w$.  
For $ |\word{w}| = 1 $, the result holds trivially with $ C_{\word{w}} = 1 $.  For $ |\word{w}| > 1 $, {we assume that \eqref{eq:linear_form_as_bound} holds for words of length strictly less than $|\word{w}|$.}  
By Proposition~\ref{prop:nod}, the word $ \word{w} $ can be written as a linear combination of monomials of the form  
\begin{equation}
    \word{2}\shupow{k}\shuprod\word{u_11}\shuprod\ldots\shuprod\word{u_m1},
\end{equation}
where 
\begin{equation}\label{eq:lengths_eq}
    k + \sum_{i=1}^mN_{\word{2}}(\word{u_i}) = N_{\word{2}}(\word{w}), \quad  k + m + \sum_{i=1}^m|\word{u_i}|= |\word{w}|.
\end{equation}
Hence, it suffices to bound each monomial:
\begin{align}
\left|\bracketsigX[t][\widehat{X}]{\word{2}\shupow{k}\shuprod\word{u_11}\shuprod\ldots\shuprod\word{u_m1}}\right| &= \left|X_t^k\prod_{i=1}^m\int_0^t\bracketsigX[s][\widehat{X}]{\word{u_i}}ds\right| \\
    &\leq \max_{t \in [0, T]}|X_t|^k\prod_{i=1}^m \left(T \max_{t \in [0, T]} \left|\bracketsigX[t][\widehat{X}]{\word{u_i}}\right|\right) \\
    &\leq T^m\max_{t \in [0, T]}|X_t|^k \prod_{i=1}^m\left(C_{\word{u_i}}T^{|\word{u_i}| - N_{\word{2}}(\word{u_i})}\max_{t \in [0, T]}|X_t|^{N_{\word{2}}(\word{u_i})}\right) \\
    &=  \left(\prod_{i=1}^mC_{\word{u_i}}\right) T^{m + \sum\limits_{i=1}^m\left(|\word{u_i}| - N_{\word{2}}(\word{u_i})\right)}\max_{t \in [0, T]}|X_t|^{k + \sum\limits_{i=1}^{m}N_{\word{2}}(\word{u_i})},
\end{align}
where we have used for the second inequality the induction hypothesis \eqref{eq:linear_form_as_bound} on the words $\word{u_i}$,  since $|\word{u_i}|<|\word w|$. It remains to observe that, by
\eqref{eq:lengths_eq},
\begin{equation}
    k + \sum\limits_{i=1}^{m}N_{\word{2}}(\word{u_i}) = N_{\word{2}}(\word{w}), \quad
    m + \sum\limits_{i=1}^m\left(|\word{u_i}| - N_{\word{2}}(\word{u_i})\right) = |\word{w}| - N_{\word{2}}(\word{w}),
\end{equation}
which yields \eqref{eq:linear_form_as_bound} for the word $\word w$ and ends the proof.

\subsection{Proof of Lemma~\ref{lem:expYV}}\label{sect:second_lemma_proof}
We proceed by induction on the length $n$ of the word $\word{w}$. For $n=1$, \eqref{eq:second_bound} holds trivially. For $n\geq 2$, we assume the  bound to hold for all words of length strictly less than $n$.

If $\word{w} = \word{2}^{\otimes n}$, the claim is obvious, as equality holds in \eqref{eq:second_bound} for {$ C = (n!)^{-q}$} and $\epsilon=0$.

Otherwise, by Proposition \ref{prop:nod}, one can write $\word{w}$ as
\[
\word{w} = \sum_{k=1}^{m} \alpha_k \word{w_{k,1}} \shuprod \ldots \shuprod \word{w_{k,i_k}}
\]
where the words $\word{w_{k,j}}$ contain at least one letter and satisfy
\[
|\word{w_{k,1}}|+ \ldots + |\word{w_{k,i_k}}| = |\word{w}| = n,
\]
\[
N_{\word{2}}(\word{w_{k,1}})+ \ldots + N_{\word{2}}(\word{w_{k,i_k}}) = N_{\word{2}}(\word{w}),
\]
and for each $k,j$, $\word{w_{k,j}}$ is either of length not greater than $n-1$ or ending with a letter different from $\word{2}$.

By the elementary inequality  
$$
(x_1 + \ldots + x_m)^q \leq C_{q,m} \left(|x_1|^q + \ldots + |x_m|^q\right),
$$  
it suffices to bound each term corresponding to the summands separately.  

We then distinguish two cases. First, assume that $i_k \geq 2$, meaning that each of the words has length less than $n$. In this case, we apply Young's inequality to write  
$$
  \prod_{j=1}^{i_k} \left|\left\langle\word{w_{k,j}}, \widehat{\mathbb{Y}}^X_t\right\rangle\right|^{q}  \lesssim \sum_{j=1}^k   \left|\left\langle\word{w_{k,j}}, \widehat{\mathbb{Y}}^X_t\right\rangle\right|^{q \frac{N_{\word{2}}(\word{w}) + \epsilon}{N_{\word{2}}(\word{w_{k,j}})+\epsilon_j}},
$$
where $\epsilon_j >0$ are arbitrary such that $\sum_j \epsilon_j = \epsilon$. We then conclude by the induction hypothesis applied to each $\word{w_{k,j}}$ since $|\word{w_{k,j}}| < n$.

In the case where $i_k=1$, we know that $\word{w_{k,1}}$ is of the form $\word{u}\word{1}$ or $\word{u}\word{j}$ for $3\leq j \leq d + 2$ . In the first case, this means that
\begin{align*}
    \E \left[ \int_0^{\tau} \left|\left\langle\word{w_{k,1}}, \widehat{\mathbb{Y}}^X_t\right\rangle\right|^{q} dt\right] = 
    \E\left[ \int_0^{\tau}\left|\int_0^t \left\langle\word{u}, \widehat{\mathbb{Y}}^X_s\right\rangle ds\right|^{q} dt \right] 
    \leq T^{\bl q - 1} \E \left[\int_0^{\tau} \left| \left\langle\word{u}, \widehat{\mathbb{Y}}^X_s\right\rangle\right|^{q} ds  \right],
\end{align*}
where we have used H\"older's inequality, and we conclude by the induction hypothesis applied to $\word{u}$ since $|\word{u}| = n - 1$.

For the case $\word{w_{k, 1}}=\word{u}\word{j} = \word{u'u_nj}$, $j \geq 3$, this means that
\begin{align*}
\left\langle\word{w_{k,1}}, \widehat{\mathbb{Y}}^X_t\right\rangle &= \int_0^t \left\langle\word{u}, \widehat{\mathbb{Y}}^X_s\right\rangle \circ dZ^{j - 2}_s \\
&= \int_0^t \left\langle\word{u}, \widehat{\mathbb{Y}}^X_s\right\rangle dZ^{j - 2}_s + \indic{\word{u_n} = \word{j + 2}}\int_0^t \left\langle\word{u'}, \widehat{\mathbb{Y}}^X_s\right\rangle ds + \indic{\word{u_n} = \word{2}}\int_0^t \left\langle\word{u'}, \widehat{\mathbb{Y}}^X_s\right\rangle d\langle X_s, Z^{j - 2}_s\rangle.
\end{align*}
Again, it is enough to bound separately the integrals of each of the three terms. The second one follows exactly as in the case $\word{w_{k,1}}=\word{u}\word{1}$, and the third one vanishes, as follows {from the assumption $\langle Z^i, X\rangle \equiv 0$}. For the first term, using the Burkholder--Davis--Gundy inequality, we obtain
\begin{align*}
     \E \left[\int_0^{\tau} \left|\int_0^t \left\langle\word{u}, \widehat{\mathbb{Y}}^X_s\right\rangle dZ^{j - 2}_s\right|^{q} dt \right] &\leq T  \E \left[\sup_{0\leq t \leq \tau}  \left|\int_0^t \left\langle\word{u}, \widehat{\mathbb{Y}}^X_s\right\rangle dZ^{j - 2}_s\right|^{q}\right] \\
     &\leq C_{T,q} \E\left[\left(\int_0^{\tau} \left\langle\word{u}, \widehat{\mathbb{Y}}^X_s\right\rangle^2 ds \right)^{\frac{q}{2}} \right]\\
    & \leq C'_{T,q} \E \left[ \int_0^{\tau} \left|\left\langle\word{u}, 
     \widehat{\mathbb{Y}}^X_s\right\rangle\right|^q ds  \right]
\end{align*}
Using Hölder's inequality, recalling that $q \geq 2$, and applying the induction hypothesis to $\word{u}$ since $|\word{u}| = n - 1$, we establish \eqref{eq:second_bound} for the word $\word{w}$, thereby completing the proof.


\section{Proof of martingality in Theorem~\ref{T:main_martingality} and Theorem~\ref{T:main_martingality_multid}}\label{sect:martingality_expec}

As noted in Remark~\ref{rmk:multid_model}, Theorem~\ref{T:main_martingality} follows immediately from Theorem~\ref{T:main_martingality_multid} when $\rho \neq 0$.
The case $\rho = 0$ is trivial, as $X$, given by \eqref{eq:sig_SDE_1D}, is a Brownian motion. Consequently, we have $\tau_\infty^X = +\infty$ almost surely, and $S$ is a martingale by Corollary~\ref{cor:one_d_criterion}.
Hence, we turn directly to the more general model \eqref{eq:price_model_multid} and proceed with the proof of Theorem~\ref{T:main_martingality_multid}.

If $N = 1$, the equation \eqref{eq:sdeX} is a linear SDE, which admits a unique strong solution on $\mathbb{R}^+$. This ensures that $\tau_\infty^X = +\infty$ almost surely. We conclude that $S$ is a martingale by Theorem~\ref{T:explosion_criterion}. This establishes \textit{(i)} of Theorem~\ref{T:main_martingality_multid}.

We now consider the non-trivial case $N \geq 2$, corresponding to point \textit{(ii)} of Theorem~\ref{T:main_martingality_multid}.
By Theorem~\ref{T:explosion_criterion}, we need to prove that the solution $X$ to \eqref{eq:sdeX} does not explode in finite time. Specifically, defining
\[
\tau^X_n = \inf \left\{ t \geq 0,\, |X_t| = n \right\},
\]
we will show that 
\[
\lim\limits_{n \to \infty}\mathbb{P}(\tau^X_n < T) = \P(\tau^X_\infty < T)  =  0.
\]

The probabilities on the left-hand side are controlled by
\[
\P(\tau^X_n \leq T) \leq \dfrac{1}{n^{2N}}\E\left[X_{T\wedge \tau_n^X}^{2N}\right],
\]
since
$$
\E\left[X_{T\wedge \tau_n^X}^{2N}\right] \geq \E\left[n^{2N}\indic{\tau_n^X \leq T}\right] = n^{2N}\P(\tau^X_n \leq T),
$$
so that it is enough to obtain a uniform bound (in $n$)  for $\E\left[X_{T\wedge \tau_n^X}^{2N}\right]$.

By Itô's formula, we have on $t \in [[0, \tau_n^X]]$
\begin{equation}
    dX_t^{2N} = 2NX_t^{2N-1}dX_t + N(2N-1)X_t^{2N-2}dt = 2NX_t^{2N-1}\bracketsigX[t][\widehat{Y}^X]{\bsigma}dt + 2NX_t^{2N-1}dB_t+ N(2N-1)X_t^{2N-2}dt
\end{equation}
Integration from $0$ to $T\wedge \tau_n^X$, taking the expectation and denoting $\tilde\bsigma = \bsigma - \sigma^{\word{2}\conpow{N}} \word{2}\conpow{N}$, we obtain
\begin{align}
    \E\left[X_{T\wedge \tau_n^X}^{2N}\right] &=  \E \left[\int_0^{T\wedge \tau_n^X} \left(2NX_s^{2N-1}\bracketsigX[s][\widehat{Y}^X]{\bsigma} + N(2N-1)X_s^{2N-2}\right)\,ds \right]\\
    &= \E \left[\int_0^{T\wedge \tau_n^X}\left(\dfrac{2N}{N!} \sigma^{\word{2}\conpow{N}} X_s^{3N-1} + \dfrac{2N}{N!} X_s^{2N-1} \bracketsigX[s][\widehat{Y}^X]{\tilde\bsigma}+N(2N-1)X_s^{2N-2}\right)\,ds \right] \\
    &\leq \E \left[\int_0^{T\wedge \tau_n^X} \left( \dfrac{2N}{N!} \sigma^{\word{2}\conpow{N}} X_s^{3N-1} + \delta X_s^{3N-1} + C(N, \delta) \bracketsigX[s][\widehat{Y}^X]{\tilde\bsigma}^{\frac{3N - 1}{N}}+N(2N-1)X_s^{2N-2}\right]\right)\,ds \\
    &\leq \E \left[\int_0^{T\wedge \tau_n^X} \left(\left(\dfrac{2N}{N!}+ \delta\right)\sigma^{\word{2}\conpow{N}} X_s^{3N-1} + \tilde C(N, \delta, T) \left(|X_s|^{(3N - 1)\frac{N - 1}{N} + \epsilon} + 1\right)+N(2N-1)X_s^{2N-2}\right)\,ds\right],
\end{align}
where we have applied Young's inequality to obtain the first inequality and Lemma \ref{lem:expYV} for the second one. Choosing $\delta \in \left(0,  -\dfrac{2N}{N!}\sigma^{\word{2}\conpow{N}}\right)$ and $\epsilon$ such that ${(3N - 1)\frac{N - 1}{N} + \epsilon} < 3N - 1$, we ensure that the integrand is bounded from above uniformly in $n$ since $3N - 1$ is even and $\left(\dfrac{2N}{N!}+ \delta\right)\sigma^{\word{2}\conpow{N}} < 0$. This finishes the proof.

\section{Proofs of strict local martingality}\label{section:proof_local_martingality}

In this section, we prove the necessity in Theorem~\ref{T:main_martingality} \textit{(ii)} and Theorem~\ref{T:main_martingality_multid} \textit{(ii)}. Unlike the ``one-shot'' proof of the martingale property in Section~\ref{sect:martingality_expec}, we first prove strict local martingality in the simpler one-dimensional case and then extend it to the multidimensional setting.

\subsection{Proof of necessity in Theorem~\ref{T:main_martingality} \textit{(ii)}}\label{section:proof_local_mart_1D}

The proof of the theorem follows the ideas used by \cite{Lions2007} in the Markovian setting. 

    Fix $T > 0$. According to Corollary~\ref{cor:one_d_criterion}, it is enough to prove than $\P(\tau_\infty^X < T) > 0$, where
    \begin{equation}
        \tau_\infty^X = \lim_{n\to\infty}\tau_n^X, \quad \tau_n^X := \inf\{t \geq 0\colon  |X_t| = n\},
    \end{equation}
    and $X = (X_t)_{t\geq 0}$ satisfies
    \begin{equation}
        dX_t = d W_t +\bracketsig[t][X]{\rho \bsigma}dt, \quad t \in [[0, \tau_\infty^X]], \quad X_0 = 0.
    \end{equation}

    For the linear form of signature, the following inequality is a direct consequence of Lemma~\ref{lemma:linear_from_upper_bound}:
    \begin{equation}\label{eq:vol_remainder_ineq}
        \sup_{t \in [0,\, T]}\left| \bracketsigX[t][\widehat{X}]{\bsigma - \sigma^{\word{2}\conpow{N}}\word{2}\conpow{N}} \right| \leq C_{\bsigma, T}\left(1 + \sup_{t \in [0,\, T]}\left|X_t\right|^{N-1}\right) \quad a.s.
    \end{equation}
    for some positive $C_{\bsigma, T} > 0$ depending only on $T$ and the coefficients $\bsigma$. This implies
    \begin{equation}\label{eq:vol_domination_ineq}
        \dfrac{\sigma^{\word{2}\conpow{N}}}{N!}X_t^N - C_{\bsigma, T}\left(1 + \sup_{s \in [0,\, t]}\left|X_s\right|^{N-1}\right) \leq \bracketsigX[t][\widehat{X}]{\bsigma} \leq \dfrac{\sigma^{\word{2}\conpow{N}}}{N!}X_t^N + C_{\bsigma, T}\left(1 + \sup_{s \in [0,\, t]}\left|X_s\right|^{N-1}\right) \quad a.s.
    \end{equation}
    for all $t \in [0,\, \tau^X_\infty]$.

    In particular, it follows that $\lim\limits_{X_t \to \infty}\bracketsig[t][X]{\bsigma}^2 = +\infty$, so it is sufficient to show that $\P(\tau_\infty^X < T) > 0$.

    For an arbitrary $\lambda \in \R$, define the event
    \begin{equation}
    \mathcal{A}_\lambda = \left\{\omega\colon \sup_{t \in [0, T]}\left| W_t - \lambda t \right| \leq 1\right\}, \quad \P(\mathcal{A}_\lambda) > 0.
    \end{equation}
    If $\bracketsig[t][X]{\bsigma_t}$ was a deterministic function of $X_t$, so that $X_t$ was Markovian, we would write on $\mathcal{A}_\lambda$
    \begin{equation}
        X_t \geq \lambda t - 1 + \rho \int_0^t \bracketsig[s][X]{\bsigma}\, ds
    \end{equation}
    and apply the comparison theorem for ODEs to establish the explosion of $X_t$.
    However, in general, it is not true, and the equation becomes path-dependent. Our strategy consists of isolating the term \(\frac{\sigma^{\word{2}\conpow{N}}}{N!}X_t^N\)
    \begin{equation}
        \bracketsig[t][X]{\bsigma} = \dfrac{\sigma^{\word{2}\conpow{N}}}{N!}X_t^N + \bracketsig[t][X]{\bsigma - \sigma^{\word{2}\conpow{N}}\word{2}\conpow{N}}
    \end{equation}
    and bounding the remainder using \eqref{eq:vol_domination_ineq}. Then, we compare the solutions on $[ \tau_n^X, \tau_{n+1}^X )$, bounding $\max\limits_{s \in [0, t]} |X_s|^{N-1}$ by $(n + 1)^{N-1}$, and apply the comparison principle for ODEs on this interval. This leads to a bound on $(\tau_{n+1}^X - \tau_n^X)$, which is used in its turn to bound $\tau_\infty^X$ on $\mathcal{A}_\lambda$.

    Assume first that $\rho\sigma^{\word{2}\conpow{N}} > 0$. 
    By \eqref{eq:vol_domination_ineq}, for $t \in [\tau_n^X, \tau_{n+1}^X)$, we have on $\mathcal{A}_\lambda$
    \begin{align}
        X_{t} &\geq X_{\tau_n^X} + (W_t - W_{\tau_n^X}) + \dfrac{\rho\sigma^{\word{2}\conpow{N}}}{N!}\int_{\tau_n^X}^tX_s^N\,ds - |\rho|C_{\bsigma, T}\int_{\tau_n^X}^t \left(1 + \sup_{u \in [0,\, s]} \left|X_u\right|^{N-1}\right)\,ds \\
        &\geq n + \lambda (t - \tau_{n}^X) - 2 + \dfrac{\rho\sigma^{\word{2}\conpow{N}}}{N!}\int_{\tau_n^X}^t X_s^N \,ds - |\rho|C_{\bsigma, T} \left(1 + (n+1)^{N-1}\right)(t - \tau_n^X).
    \end{align}
    This allows us to apply the comparison theorem for ODEs, so that $X_t \geq Y_n(t)$ on $[\tau_n^X, \tau_{n+1}^X)$, where $Y_n(t)$ satisfies
    \begin{equation}
        \dot Y_n(t) = \lambda - |\rho|C_{\bsigma, T} \left(1 +  (n+1)^{N-1}\right) + \dfrac{\rho\sigma^{\word{2}\conpow{N}}}{N!} Y_n(t)^N , \quad Y(\tau_n^X) = n - 2.
    \end{equation}
    Since $\rho\sigma^{\word{2}\conpow{N}} > 0$, we can choose $\lambda$ large enough to guarantee that for all $n \geq 0$, the right-hand side is positive and $Y_n(t)$ is increasing. Then, since $Y_n(t) \geq n - 2$, for $t \in [\tau_n^X, \tau_{n+1}^X)$,
    \begin{equation}
        Y_n(t) \geq n - 2 + \left(\lambda + \dfrac{\rho\sigma^{\word{2}\conpow{N}}}{N!}(n-2)_+^N - |\rho|C_{\bsigma, T} \left(1 + (n+1)^{N-1}\right)\right)(t - \tau_n^X).
    \end{equation}
    Hence, on $\mathcal{A}_\lambda$, the following estimate holds
    \begin{equation}
        \tau_{n+1}^X - \tau_{n}^X \leq \tau_{n+1}^Y - \tau_{n}^X \leq \dfrac{3}{\lambda + \frac{\rho\sigma^{\word{2}\conpow{N}}}{N!}(n-2)_+^N - |\rho|C_{\bsigma, T} \left(1 + (n+1)^{N-1}\right)}
    \end{equation}
    and
    \begin{equation}
        \tau_{\infty}^X = \sum_{n \geq 0}(\tau_{n+1}^X - \tau_{n}^X) \leq
         \sum_{n \geq 0} \dfrac{3}{\lambda + \frac{\rho\sigma^{\word{2}\conpow{N}}}{N!}(n-2)_+^N - |\rho|C_{\bsigma, T} \left(1 + (n+1)^{N-1}\right)}.
    \end{equation}
    The series converges since $N \geq 2$ and the its sum can be made arbitrary small by choosing $\lambda$ large enough.

    For the remaining case of even $N$ and $\rho\sigma^{\word{2}\conpow{N}} < 0$, we take $\lambda < 0$ large enough, so that $X_{\tau_{n}^X} = -n$ on $\mathcal{A}_\lambda$, and we have on $[\tau_{n}^X, \tau_{n+1}^X)$
    \begin{align}
        X_{t} &\leq X_{\tau_n^X} + (W_t - W_{\tau_n^X}) + \dfrac{\rho\sigma^{\word{2}\conpow{N}}}{N!}\int_{\tau_n^X}^tX_s^N\,ds + |\rho|C_{\bsigma, T}\int_{\tau_n^X}^t \left(1 + \sup_{u \in [0,\, s]} \left|X_u\right|^{N-1}\right)\,ds \\
        &\leq -n + \lambda (t - \tau_{n}^X) + 2 + \dfrac{\rho\sigma^{\word{2}\conpow{N}}}{N!}\int_{\tau_n^X}^t X_s^N \,ds + |\rho|C_{\bsigma, T} \left(1 + (n+1)^{N-1}\right)(t - \tau_n^X).
    \end{align}
    As $\dfrac{\rho\sigma^{\word{2}\conpow{N}}}{N!}X_s^N < 0$, using the same argument as before, we can choose $\lambda(T)$ in order to ensure that $X_t$ blows up to $-\infty$ on $\mathcal{A}_\lambda$ before $T$ for any $T > 0$.

\subsection{Proof of necessity in Theorem~\ref{T:main_martingality_multid} \textit{(ii)}}\label{section:proof_local_mart_mulitiD}

We prove the result for the case where $ \sigma^{\word{2}\conpow{N}} > 0$ showing that $ X $ blows up to $ +\infty $ with positive probability. The case where $ \sigma^{\word{2}\conpow{N}} < 0 $ and $ N $ is even is treated similarly by showing that $ X $ blows up to $ -\infty $.

{The idea of this proof is to extend the proof of strict local martingality in Section~\ref{section:proof_local_martingality} by finding a suitable event $\mathcal{A}$ of positive probability such that the solution of \eqref{eq:sdeX} blows up before $T > 0$ on $\mathcal{A}$. We achieve this by keeping the elements of the signature containing $Z$ (i.e., those corresponding to words containing the letters $\word{3}, \ldots, \word{d + 2}$) small, so that the solution of the SDE remains close to the one considered in the one-dimensional case. More precisely, we define  
$$
\tau_n^X = \inf\{t \geq t_0\colon X_t = n\},
$$
and we fix $t_0 > 0$, $M \in \mathbb{N}$, and $\epsilon$ such that $N\epsilon < 1$. We require that on $\mathcal{A}$, the following inequalities hold:
\begin{align}
X_{t_0} &\geq M, \label{eq:cond1}\\
| \langle \word{w},\widehat{\mathbb{Y}}^X_{t_0} \rangle | &\leq 1, \quad \text{for all $\word{w}$ containing at least one of the letters $\word{3}, \ldots, \word{d + 2}$;} \label{eq:cond2}\\
\sup_{s \in [\tau_n^X, \tau_{n+1}^X]} | \langle \word{w} , \widehat{\mathbb{Y}}^X_{s} \rangle | &\leq n^{N_{\word{2}}(\word{w})+\epsilon |\word{w}|}, \quad \text{for $n \geq M$ and for all words $\word{w}$ such that $|\word{w}| \leq N$;} \label{eq:cond3}\\
\sup_{s \in [\tau_n^X, \tau_{n+1}^X]} |B_s - B_{\tau_n}| &\leq n^{-N/2+\epsilon}, \quad \text{for $n \geq M$.} \label{eq:cond4}
\end{align}
\paragraph{Step 1: Proving the explosion on $\mathcal{A}$.} 
Conditional on this event, we can use ODE comparison on the dynamics of $X$ to obtain that 
\begin{equation}\label{eq:d_tau_bound}
    \tau_{n+1}^X-\tau_n^X \leq C n^{-N}, \quad n \geq M,
\end{equation}
for some positive constant $C = C_{\bsigma, N} > 0$ to be determined later. Indeed, for $t \in [\tau_n^X, \tau_n^X + C n^{-N}]$, we have 
\begin{align*}
X_t &= X_{\tau_n^X} + \int_{\tau_n^X}^t \bracketsigX[s][\widehat{Y}^X]{\bsigma}\,ds + B_t - B_{\tau_n^X}\\ 
&\geq X_{\tau_n^X} + \frac{\sigma^{\word{2}^{\otimes N}}}{N!} \int_{\tau_n^X}^t X_s^N ds - C_{\bsigma} n^{(N - 1) + \epsilon N} (t-\tau_n^X) - n^{-N/2 + \epsilon} \\
&\geq n - \left(C_{\bsigma} C n^{N\epsilon - 1} + n^{-N/2 + \epsilon}\right) + \frac{\sigma^{\word{2}^{\otimes N}}}{N !} \int_{\tau_n^X}^t X_s^N ds,
\end{align*}
where we used conditions \eqref{eq:cond3} and \eqref{eq:cond4} in the first inequality. For $n$ large enough, we have 
$$
C_{\bsigma} C n^{N\epsilon - 1} + n^{-N/2 + \epsilon} < 1,
$$
since $N\epsilon < 1$, so that
$$
X_t \geq (n-1) + \frac{\sigma^{\word{2}^{\otimes N}}}{N !} \int_{\tau_n^X}^t X_s^N ds.
$$
By the comparison theorem for ODEs, this implies that $\tau_{n+1}^X - \tau_n^X\leq {\tau}_{(n-1) \to (n+1)}^x$, where ${\tau}_{(n-1) \to (n+1)}^x$ is the time needed for the ODE 
$$\dot{x}(t) =\frac{\sigma^{\word{2}^{\otimes N}}}{N !} x^N(t),$$ 
to go from $(n-1)$ to $(n+1)$. Since the coefficient $\sigma^{\word{2}^{\otimes N}}$ is positive, a straightforward computation gives
\begin{equation} \label{eq:tildetauandc}
{\tau}_{(n-1) \to (n+1)}^x =  \left( \frac{N !}{(N-1) \sigma^{\word{2}^{\otimes N}}}\right) \left((n-1)^{1-N} - (n+1)^{1-N} \right)\leq C n^{-N}
\end{equation}
for a suitable choice of $C > 0$. It then follows that, on the event $\mathcal{A}$, we have 
$$
\tau_\infty \leq t_0 + C \sum\limits_{n\geq M} n^{-N}.
$$ 
Since $t_0$ and $M$ in \eqref{eq:cond1}--\eqref{eq:cond2} are arbitrary, they can be chosen so that $\tau_\infty < T$ on $\mathcal{A}$.
It remains to show that $\P(\mathcal{A}) > 0$.
\paragraph{Step 2: Showing that $\P(\mathcal{A}) > 0$.} 
First, we note that 
\begin{equation*}
    \mathcal{A} = A_M \cap \bigcap_{n\geq M}\left(A_n^B \cap \bigcap_{\word{w}:\, |\word{w}| \leq N}A_n^{\word{w}}\right), 
\end{equation*}
where the event $A_M$ corresponds to the inequalities \eqref{eq:cond1}--\eqref{eq:cond2}, $A_n^{\word{w}}$ corresponds to \eqref{eq:cond3} for fixed $n$ and $\word{w}$, and $A_n^B$ corresponds to \eqref{eq:cond4} for a given $n$.

{We first claim that $\P\left(A_M\right) > 0$. By the support theorem of \cite{SV72}, it suffices to show that, for a suitable choice of $(w,z^1,\ldots, z^d)$ (deterministic smooth functions on $[0,T]$), the corresponding deterministic dynamics (i.e. where $W$, $Z^i$ are replaced by $w, z^i$ in \eqref{eq:sdeX}) satisfy the conditions. Taking $z^1 \equiv \cdots \equiv z^d \equiv 0$ clearly leads to \eqref{eq:cond2}. Further taking $w_t = \lambda t$ leads to \eqref{eq:cond1} by the analysis of Section \ref{section:proof_local_mart_1D}. It follows that   $\P\left(A_M\right) > 0$.
}

We define 
$$
A_{n + 1} := A_n \cap \left(\bigcap_{|\word{w}| \leq N} A^{\word{w}}_{n + 1}\right) \cap A^B_{n + 1}, \quad n \geq M.
$$
It is enough to prove that, if $M$ is large enough, for each $n \geq M$, we have
\begin{equation} \label{eq:cond}
    \P(A_{n+1}^c|A_n) \leq c e^{-c n^{\delta}},
\end{equation}
for some $c,\delta>0$. Indeed, since $A_{n+1} \subset A_n$ and $\mathcal{A} = \bigcap\limits_{n \geq M} A_n$, we write
\begin{equation}
    \P(\mathcal{A}) = \P(A_M)\prod_{n \geq M}\P(A_{n+1} | A_n),
\end{equation}
so that, if \eqref{eq:cond} is verified, we have
$$
    \log(\P(\mathcal{A})) = \log(\P(A_M)) + \sum_{n \geq M}\log(\P(A_{n+1} | A_n)) \geq  \log(\P(A_M)) + \sum_{n \geq M}\log(1 - c e^{-c n^{\delta}}).
$$
As $n \to \infty$, $\log(1 - c e^{-c n^{\delta}}) \sim c e^{-c n^{\delta}}$, and the series converges. Thus, we obtain $\P(\mathcal{A}) > 0$.

Note that since
\begin{equation*}
    \P(A_{n+1}^c|A_n) = \P\left(\bigcup_{\word{w}:\, |\word{w}| \leq N} (A_{n+1}^{\word{w}})^c \cup (A_{n+1}^B)^c  \Bigg|\, A_n\right)
    \leq \P((A_{n+1}^B)^c | A_n) + \sum_{\word{w}:\, |\word{w}| \leq N} \P((A_{n+1}^{\word{w}})^c |A_n),
\end{equation*}
the condition \eqref{eq:cond} is stable under finite intersections, and it suffices to prove \eqref{eq:cond} for $\P((A_{n+1}^B)^c|A_n)$ and for each of the $\P((A_{n+1}^{\word{w}})^c|A_n)$.

The bound \eqref{eq:cond} for $\P(A_{n+1}^B|A_n)$ follows from Gaussian scaling and Gaussian tail estimates for the Brownian motion $B$.
Thus, it remains to establish \eqref{eq:cond} for the events $A_{n+1}^{\word{w}}$, which we proceed to do via induction on the length of the word $|\word{w}|$. 

For $|\word{w}| = 1$, we consider three cases. If $\word{w} = \word{1}$, \eqref{eq:cond3} holds for sufficiently large $n$ due to the bound \eqref{eq:d_tau_bound} on $\tau_n^X$. If $\word{w} = \word{2}$, \eqref{eq:cond3} follows directly from the definition of $\tau_n^X$ for large $n$. In the remaining case, where $\word{w} \in \{\word{3}, \ldots, \word{d + 2}\}$, \eqref{eq:cond} follows from Gaussian tail estimates, as was previously done for the probability $\P(A_{n+1}^B|A_n)$. 

Now, suppose that $|\word{w}| > 1$ and that \eqref{eq:cond} holds for all words $\word{u}$ such that $|\word{u}| < |\word{w}|$.

By Proposition~\ref{prop:nod}, we can write $\word{w}$ as a linear combination of shuffle products and we consider three cases.

The first case consists of words of the form $\word{w} = \word{w_{1}} \shuprod \ldots \shuprod \word{w_k}$ with $k \geq 2$. The result then follows from the induction hypothesis for $\word{w_j}$, since on $\bigcap\limits_{j = 1}^kA_{n+1}^{\word{w_j}}$ we have
\begin{equation*}
    \sup_{s \in [\tau_n^X, \tau_{n+1}^X]} | \langle \word{w} , \widehat{\mathbb{Y}}^X_{s} \rangle| \leq \prod_{j=1}^k \sup_{s \in [\tau_n^X, \tau_{n+1}^X]} | \langle \word{w_j} , \widehat{\mathbb{Y}}^X_{s} \rangle| \leq \prod_{j=1}^k n^{N_{\word{2}}(\word{w_j})+\epsilon |\word{w_j}|} = n^{N_{\word{2}}(\word{w})+\epsilon |\word{w}|}.
\end{equation*}
This implies that $A_{n+1}^{\word{w}} \subset \bigcap\limits_{j = 1}^kA_{n+1}^{\word{w_j}}$. 

The second case concerns words of the form $\word{u} \word{1}$, which is again handled by the induction hypothesis for $\word{u}$. Indeed, conditional on $A_n$ and $A_{n+1}^{\word{u}}$, we have
\begin{align*}
    \sup_{s \in [\tau_n^X, \tau_{n+1}^X]} | \langle \word{w} , \widehat{\mathbb{Y}}^X_{s} \rangle| &= \sup_{s \in [\tau_n^X, \tau_{n+1}^X]} \left| \langle \word{w} , \widehat{\mathbb{Y}}^X_{\tau_n^X}\rangle + \int_{\tau_n^X}^s\langle \word{u} , \widehat{\mathbb{Y}}^X_{s} \rangle ds\right| \\
    &\leq (n - 1)^{N_{\word{2}}(\word{w})+\epsilon |\word{w}|} + (\tau_{n+1}^X - \tau_n^X)n^{N_{\word{2}}(\word{u})+\epsilon |\word{u}|} \\
    &\leq (n - 1)^{N_{\word{2}}(\word{w})+\epsilon |\word{w}|} + Cn^{-N + N_{\word{2}}(\word{u})+\epsilon |\word{u}|} \\
    &\leq (n - 1)^{N_{\word{2}}(\word{w})+\epsilon |\word{w}|} + Cn^{-1+\epsilon (N - 1)},
\end{align*}
which is bounded by $n^{N_{\word{2}}(\word{w})+\epsilon |\word{w}|}$ for sufficiently large $n$ (recall that $M$ can be chosen large enough).

The last case corresponds to $\word{w} = \word{u} \word{i}$ for $i \in\{3, \ldots, d + 2\}$. 
We write
\begin{align*}
    \P((A_{n+1}^{\word{w}})^c|A_n) &= \P((A_{n+1}^{\word{w}})^c, (A_{n+1}^{\word{u}})^c|A_n) + \P((A_{n+1}^{\word{w}})^c, A_{n+1}^{\word{u}}|A_n) \\
    &\leq \P((A_{n+1}^{\word{u}})^c|A_n) + \P((A_{n+1}^{\word{w}})^c, A_{n+1}^{\word{u}}|A_n),
\end{align*}
and note that \eqref{eq:cond} holds for the first term by the induction hypothesis for $\word{u}$.
For $s \geq \tau_n$, we have
\[
\langle \word{w} , \widehat{\mathbb{Y}}^X_{s} \rangle = \langle \word{w} , \widehat{\mathbb{Y}}^X_{\tau_n^X} \rangle  + \int_{\tau_n}^s \langle \word{u} , \widehat{\mathbb{Y}}^X_{s}\rangle {\circ} dZ^{i - 2}_s.
\]
The first term and the Stratonovich correction are bounded on $A_n$ and $A_{n+1}^{\word{u}}$ as in the previous case. Thus, it suffices to prove the bound for the conditional probability of the event
\[
\left\{\sup_{t \in [\tau_n^X, \tau_{n+1}^X]}  \int_{\tau_n^X}^{t} \langle \word{u} , \widehat{\mathbb{Y}}^X_{s}\rangle dZ^{i - 2}_s \geq n^{N_{\word{2}}(\word{w}) + \epsilon |\word{w}|-1}\right\}.
\]
We use the concentration inequality %\textcolor{red}{(**provide a reference or a one-line proof**)}
\[ \P\left( \sup_{t \in [\tau, \tau + h]}\left|\int_{\tau}^{t} \gamma_s dW_s \right|\geq \lambda, \; \sup_{t \in [\tau, \tau + h]} |\gamma_t| \leq \eta\right) \leq \exp\left(- \frac{\lambda^2}{2 \eta^2 h}\right),\]
which follows from the Gaussian tails of Brownian motion and the Dambis–-Dubins–-Schwarz theorem and holds for any stopping time \(\tau\), any \(h > 0\), and any progressively measurable \(\gamma\).
\begin{align*}
    \P &\left(\sup_{t \in [\tau_n^X, \tau_{n+1}^X]}  \int_{\tau_n}^{t} \langle \word{u} , \widehat{\mathbb{Y}}^X_{s}\rangle dZ^i_s \geq n^{N_{\word{2}}(\word{w}) + \epsilon |\word{w}|-1}, A^{\word{u}}_{n+1} \Big| A_n\right) \\
     &\leq \P\left( \sup_{t \in [\tau_n^X, \tau_{n+1}^X]}  \int_{\tau_n}^{t} \langle \word{u}, \widehat{\mathbb{Y}}^X_{s}\rangle {\circ} 
     dZ^i_s \geq n^{N_{\word{2}}(\word{w}) + \epsilon |\word{w}|-1}, \; \sup_{t \in [\tau_n^X, \tau_{n+1}^X]} \left| \langle \word{u} , \widehat{\mathbb{Y}}^X_{t}\rangle \right| \leq n^{N_{\word{2}}(\word{w}) + \epsilon (|\word{w}|-1)} \Big| A_n \right) \\
     &\leq \exp\left(- \frac{n^{N-2(1-\epsilon)}}{2}\right).
\end{align*}
Thus, \eqref{eq:cond} holds for $\word{w}$. This completes the proof.
}

\section{Proof of Theorem \ref{thm:moments}: Moments explosion}\label{sect:moments}

Without loss of generality, we will assume that $N$ is odd and
\[
\sigma^{\word{2}\conpow{N}}  > 0 \mbox{ and }\rho < 0.
\]
The proof for the remaining case $ \sigma^{\word{2}\conpow{N}} < 0 $ and $ \rho > 0 $ is analogous.  
% {\bl In the remaining case of $\sigma^{\word{2}\conpow{N}} < 0 \mbox{ and } \rho > 0$, we can replace $W$ with $-W$ and reduce the problem to the first case after explicitly computing the coefficients corresponding to the signature of $(t, -W)$.
% }

By It\^o's formula,
\begin{align}
    S_T^m &= S_0^m \exp\left( m\int_0^T\sigma_s\,dB_s - \dfrac{m}{2}\int_0^T\sigma_s^2\,ds \right) \\ &= S_0^m \exp\left( \rho m\int_0^T\sigma_s\,dW_s + \bar\rho m\int_0^T\sigma_s\,dW_s^\perp - \dfrac{m}{2}\int_0^T\sigma_s^2\,ds \right),
\end{align}
As $\sigma_t = \bracketsig{\bsigma}$ is adapted to the filtration generated by $W$, conditioning with respect to $W$ implies
\begin{align*}
S_0^{-m} \E\left[S_T^m\right] &=   \;\E \left[ \exp\left(\rho m \int_0^T \bracketsig[s]{\bsigma} \,d W_s + \frac{\bar{\rho}^2 m^2 - m}{2} \int_0^T \bracketsig[s]{\bsigma}^2 \, ds\right)\right].
\end{align*}
{We then proceed as in \cite{Gassiat2018OnTM} and apply the \cite{BD98} formula {(more precisely, a variant allowing unbounded functionals, see Appendix \ref{sec:BD})}
to obtain}
\begin{equation}\label{eq:BD}
\begin{aligned} 
 \ln {\E}\left[S_T^m/S^m_0\right]  &= \sup_{(u_t)_{t\geq0} \in \mathcal{U}_q} {\E} \left[ \int_0^T  \left( - \frac{u_s^2}{2} + \rho m  \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle u_s +   \frac{\bar{\rho}^2 m^2 - m}{2} \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2 \right)ds\right] \\
 & = \sup_{(u_t)_{t\geq0} \in \mathcal{U}_q} {\E} \left[ \int_0^T   \left( \frac{ m^2 - m}{2} \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2 - \frac{\left(u_s - \rho m \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle\right)^2}{2} \right)ds\right]  \\
 & =: \sup_{u \in \mathcal{U}_q}\mathcal{J}(u;\rho,m,T) \; =: \mathcal{V}(\rho,m,T),
\end{aligned}
\end{equation}
where 
\begin{align}\label{eq:Uq}
\mathcal{U}_{q}=\left\{ (u_t)_{t \geq 0} \mbox{ progressively measurable with }{\E}\left[ \int_0^T |u_t|^{q} dt \right] < +\infty \right\},
    \end{align}
for some fixed  $q \geq 2N$, 
and $\widehat{\mathbb{X}}^u_t$ denotes the signature of $\widehat{X}^u_t = (t, X^u_t)$ with $X^u_t$ defined by
\[
X^u_t = W_t + \int_0^{t} u_s ds.
\]

The finiteness of the moments is therefore equivalent to the control problem having a finite value. We now proceed to prove that, depending on the position of $ \rho $ relative to $ -\sqrt{1 - \frac{1}{m}} $, the value will either be finite or infinite.

\subsection{Proof of Theorem \ref{thm:moments} (i): negative result}

In this subsection we assume that
\[
- \sqrt{1-\frac{1}{m}} < \rho < 0,
\]
and we will show that $\mathcal{V}(\rho,m,T) = + \infty$. 
The idea is simple: we take $u$ of feedback form
\[u_t = \lambda \left\langle \bsigma, \widehat{\mathbb{X}}^u_t \right\rangle \]
for $\lambda \in \R$.

In that case, we denote by $X^\lambda$ the solution of the ODE
\[
dX^\lambda_t = dW_t +  \lambda \left\langle \bsigma, \widehat{\mathbb{X}}^\lambda_t \right\rangle dt,
\]
and we denote its signature by $\widehat{\mathbb{X}}^\lambda_t$. This solution exists (up to a possible explosion time) by Proposition \ref{prop:sigODE},
the value \eqref{eq:BD} corresponding to the control is simply
\[
 P (\lambda) \E \left[ \int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^\lambda_s \right\rangle^2 ds \right], 
\]
with
\[ P(\lambda) = \frac{m^2 - m}{2} - \frac{(\lambda - \rho m)^2}{2}.
\]
The assumption on $\rho$ is exactly equivalent to $P(0)>0$, which guarantees that there exists $\lambda$ s.t. 
\begin{equation} \label{eq:lambda}
\lambda > 0 \mbox{ and } P(\lambda) >0. 
\end{equation}
As shown in the proof in Section \ref{section:proof_local_martingality}, the first inequality $\lambda > 0$ will imply that $X^\lambda$ blows up with positive probability, which with the help of the second one implies that the problem value \eqref{eq:BD} is infinite.

The above argument is not completely rigorous, since the feedback control is only defined up to the explosion time and clearly not in $\mathcal{U}_q$. This can be dealt with by a simple truncation argument : for $R>0$, let 
{\[
\tau_{R,\lambda} = \inf\{ t \geq 0 :  |X_t^\lambda|= R \}
\]
and take 
\[
u^{\lambda,R}_t =  \begin{cases} \lambda \left\langle \bsigma, \widehat{\mathbb{X}}^\lambda_t \right\rangle, & t < \tau_{R,\lambda} \\
0, & t \geq \tau_{R,\lambda} \end{cases} 
\]

Then, by Lemma \ref{lem:expYV}, $u^{\lambda,R}$ is in $\mathcal{U}_q$ (for any $q \geq 2$), and 
\begin{align*}
   \mathcal{V}(\rho,m,T) \geq \mathcal{J}(u^{\lambda,R};\rho,m,T) &= P(\lambda) \E\left[\int_0^{T \wedge \tau_{R,\lambda}} \left\langle \bsigma, \widehat{\mathbb{X}}^\lambda_s \right\rangle^2 ds \right] + P(0) \E \left[ \int^T_{T \wedge \tau_{R,\lambda}} \left\langle \bsigma, \widehat{\mathbb{X}}_s^{u^{\lambda,R}} \right\rangle^2 ds\right]. %\\
%      & \geq P(\lambda) R \P\left( \tau_{\infty,\lambda} < T \right).
\end{align*}
Taking the supremum over $R$, we obtain
\[\mathcal{V}(\rho,m,T) \geq P(\lambda) E\left[\int_0^{T \wedge \tau_{\infty,\lambda}} \left\langle \bsigma, \widehat{\mathbb{X}}^\lambda_s \right\rangle^2 ds \right] \]
where $\tau_{\infty,\lambda}$ is the explosion time of $X^{\lambda}$. However, the r.h.s is infinite since the event $\{\tau_{\infty,\lambda} < T \}$ has positive probability (by the results of Section~\ref{section:proof_local_mart_1D}), and on this event $\int_0^{\tau_{\infty,\lambda}}  \left\langle \bsigma, \widehat{\mathbb{X}}^\lambda_s \right\rangle^2 ds = +\infty$ (by Proposition \ref{prop:sigODE}).
}
\subsection{Proof of Theorem \ref{thm:moments} (ii): positive result}

We assume now that the condition
\begin{equation}\label{eq:corr_condition_pos}
    \rho < - \sqrt{1-\frac{1}{m}},
\end{equation}
is verified and fix $(u_t)_{t\geq0} \in \mathcal{U}_q$. We want to bound
\begin{align}\label{eq:value_to_bound}
{\E} \left[ \int_0^T  \left( - \frac{u_s^2}{2} + \rho m \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle u_s +   \frac{\bar{\rho}^2 m^2 - m}{2} \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2 \right)ds\right].
\end{align}
Define 
\begin{equation}
    U_t := \int_0^{t} u_s\, ds.
\end{equation}
We denote by $\widehat Y^U_t=(t, U_t, W_t)$ and we denote its signature by $\widehat{\mathbb{Y}}^U_t$. Since this is a $3$-dimensional process, this signature is in the dual of the tensor algebra over words with letters $\word{1},\word{2},\word{3}$. Since $X = U + W$, we can rewrite the linear forms in terms of $\widehat{\mathbb{Y}}^U_t$. Namely, there exists $\tilde{\bsigma} \in \tTA[3]{N}$, such that $\left\langle \bsigma, \widehat{\mathbb{X}}^u_t \right\rangle = \left\langle \tilde\bsigma,\widehat{\mathbb{Y}}^U_t \right\rangle$.

In the expectation \eqref{eq:value_to_bound}, the term with the highest degree in $U$ is  
\[
\frac{\bar{\rho}^2 m^2 - m}{2} \left(\frac{\bsigma^{\word{2}\conpow{N}}}{N!}\right)^2 \mathbb{E} \left[\int_0^T U_t^{2N} dt\right].
\]  
Note that ${\bar{\rho}^2 m^2 - m}$ is strictly negative by assumption.  

We return to the value in \eqref{eq:value_to_bound} and bound the three terms in the integrand separately. The first one is non-positive and can therefore be ignored.

\paragraph{Step 1. Bounding the third term.} Using the same techniques as in the proof of Theorem~\ref{T:main_martingality_multid}, we can bound the third term $\frac{\bar{\rho}^2 m^2 - m}{2} \E\left[\int_0^T\left\langle\tilde\bsigma, \widehat{\mathbb{Y}}^U_s \right\rangle^2ds\right]$ from above by
\begin{equation}\label{eq:third_term_bound}
    - c_1 \E\left[\int_0^T  U_t^{2N} dt\right] + \sum_{\substack{|\word{w}| \leq N,\\ N_{\word{2}}(\word{w})<N}} c_{\word{w}} \E\left[\int_0^T\left\langle\word{w}, \widehat{\mathbb{Y}}^U_t\right\rangle^{2}\, dt\right]
\end{equation}
for some positive $c_1$ and $c_{\word{w}}$. By Lemma \ref{lem:expYV}, it is further bounded from above by
\[
\E \left[\int_0^T \left(- c_1 U_t^{2N} + c_2 U_t^{2N-1}\right)dt\right] + c_3 < +\infty.
\]

\paragraph{Step 2. Bounding the second term.} For the second term $\rho m{\E} \left[ \int_0^T \left\langle \tilde\bsigma, \widehat{\mathbb{Y}}^U_s \right\rangle u_s ds\right]$, we note that, for suitable coefficients $c_{\word{w}}$,
\begin{equation}\label{eq:second_term_bound}
    \rho m{\E} \left[ \int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle u_s ds\right] = \rho m{\E} \left[ \int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle dU_s\right] = -c_4 \E[U_T^{N+1}] + \sum_{\substack{|\word{w}| \leq N,\\ N_{\word{2}}(\word{w})<N}} c_{\word{w}} \E\left[ \left\langle  \word{w} \word{2},\widehat{\mathbb{Y}}^U_T\right\rangle \right],
\end{equation}
where $c_4 = -\dfrac{\rho m\bsigma^{\word{2}\conpow{N}}}{(N + 1)!}$.
We note that the Itô and Stratonovich integrals with respect to $ U $ coincide since $ U $ has bounded variation.  
By the assumption of the theorem, $c_4 > 0$, so that the first term in \eqref{eq:second_term_bound} is negative.

For the second term, we claim that it holds, for any $\word{w}$ with $|\word{w}| \leq N+1$ and $N_{\word{2}}(\word{w}) \leq N$, for arbitrary $\epsilon>0$,
\begin{equation} \label{eq:term2}
    \E\left[ \left\langle  \word{w},\widehat{\mathbb{Y}}^U_T\right\rangle \right]  \lesssim 1+ \E[ |U_T|^{N+\epsilon}] + \int_0^T \E[|U_t|^{2(N-1)+\epsilon}] \, dt
\end{equation}
We first consider separately the case where $|\word{w}| = N + 1$ and $N_{\word{2}}(\word{w}) = N $, i.e., only one letter differs from $ \word{2} $, say $ \word{j} $. By Proposition~\ref{prop:nod}, we can express $ \word{w} $ in the form
\begin{equation}\label{eq:w_decomp_1}
    \word{w} = \sum_{k=0}^N \alpha_k \word{2}\shupow{k}\shuprod \word{2}\conpow{N - k}\word{j}
\end{equation}

If $\word{j} = \word{3}$, then \eqref{eq:w_decomp_1} takes the form
\[
\E\left[ \left\langle  \word{w},\widehat{\mathbb{Y}}^U_T\right\rangle \right] =\sum_{k=1}^N \alpha_k \E \left[U_T^k \left(\int_0^T U_t^{N-k} dW_t\right)\right]
\]
Note that we omitted the term for $ k = 0 $, as it has zero expectation.  
Applying Young's inequality and the Burkholder--Davis--Gundy inequality to each term, we obtain   
{\begin{align}
    \E \left[U_T^k \left(\int_0^T U_t^{N-k} dW_t\right)\right] &\lesssim \E\left[ |U_T|^{N+\epsilon}\right] + \E \left[\left(\int_0^T U_t^{(N-k)}dW_t\right)^{\frac{N+\epsilon}{(N -k + \epsilon) }}\right]
    \\ 
    &\lesssim \E\left[ |U_T|^{N+\epsilon}\right] + \E \left[\left(\int_0^T U_t^{2(N-k)}dt\right)^{\frac{N+\epsilon}{2(N -k + \epsilon) }}\right]
    \\ 
    &\lesssim 1 + \E\left[ |U_T|^{N+\epsilon}\right] + \E \left[\left(\int_0^T U_t^{2(N-k)}dt\right)^{\max\left\{\frac{N+\epsilon}{2(N -k + \epsilon) }, 1\right\}}\right]
    \\
    &\lesssim 1 + \E \left[|U_T|^{N+\epsilon}\right] + \E \left[\int_0^T |U_t|^{\max\left\{ N+\epsilon, 2(N-k)\right\}} dt\right],
    \\
    &\lesssim 1 + \E \left[|U_T|^{N+\epsilon}\right] + \E \left[\int_0^T |U_t|^{2(N - 1) + \epsilon
} dt\right],
\end{align}
}
which proves the claim \eqref{eq:term2} in this case.

If $\word{j} = \word{1}$, a similar but simpler computation yields
\[
\E \left[U_T^k \left(\int_0^T U_t^{N-k} dt\right)\right] \lesssim \E\left[ |U_T|^{N}\right] +  \E\left[ \int_0^T |U_t|^{N} dt\right],
\]
We then assume that $N_{\word{2}}(\word{w}) \leq N-1$. In this case, by Proposition~\ref{prop:nod}, we can write $\word{w}$ as shuffle polynomial with monomials of the form
\begin{equation}\label{eq:w_decomp_2}
    \word{2}\shupow{k}\shuprod \word{u_11} \shuprod \ldots  \shuprod \word{u_m1} \shuprod \word{v_13}  \shuprod \ldots  \shuprod \word{v_n3},
\end{equation}
so that it remains to prove estimates on
\[
\E\left[U_T^{k} \prod_{i=1}^{m} \left(\int_0^T  \left\langle  \word{u_i},\widehat{\mathbb{Y}}^U_t\right\rangle dt\right)\prod_{j=1}^{n} \left(\int_0^T  \left\langle  \word{v_j},\widehat{\mathbb{Y}}^U_t\right\rangle \circ dW_t\right)\right].
\]
Again, an application of Young's inequality yields that this expectation is bounded by
 \[
 \E[|U_T|^{N_{\word{2}}(\word{w})+\epsilon}] + \sum_{i=1}^m \E\left[\left|\int_0^T \left\langle  \word{u_i},\widehat{\mathbb{Y}}^U_t\right\rangle  dt\right|^{\frac{N_{\word{2}}(\word{w})+\epsilon}{N_{\word{2}}(\word{u_i})+\epsilon_{1,i}}}\right] + \sum_{j=1}^{n} \E\left[\left|\int_0^T \left\langle  \word{v_j},\widehat{\mathbb{Y}}^U_t \right\rangle  \circ dW_t\right|^{\frac{N_{\word{2}}(\word{w})+\epsilon}{N_{\word{2}}(\word{v_j})+\epsilon_{2,j}}}\right],
 \]
where $\epsilon_{1,i}, \epsilon_{2,j} > 0$ are arbitrary, with $\sum\limits_{i=1}^m \epsilon_{1,i} + \sum\limits_{j=1}^{n} \epsilon_{2,j} = \epsilon$. The first term is of the correct order since $N_{\word{2}}(\word{w}) \leq N$. For the second one, we use H\"older's inequality and Lemma~\ref{lem:expYV} to obtain
{\begin{align*}
\E\left[\left|\int_0^T \left\langle  \word{u_i},\widehat{\mathbb{Y}}^U_t\right\rangle  dt\right|^{\frac{N_{\word{2}}(\word{w})+\epsilon}{N_{\word{2}}(\word{u_i})+\epsilon_{1,i}}}\right] 
    &\lesssim 
    \int_0^T \E \left|\left\langle  \word{u_i},\widehat{\mathbb{Y}}^U_t\right\rangle\right|^{\frac{N_{\word{2}}(\word{w})+\epsilon}{N_{\word{2}}(\word{u_i})+\epsilon_{1,i}}} dt
    \\ &\lesssim
    1 + \int_0^T \E \left|\left\langle  \word{u_i},\widehat{\mathbb{Y}}^U_t\right\rangle\right|^{\max\left\{\frac{N_{\word{2}}(\word{w})+\epsilon}{N_{\word{2}}(\word{u_i})+\epsilon_{1,i}}, 2\right\}} dt
    \\ & \lesssim 
    1 + \int_0^T \E \left[|U_t|^{\max\left\{N_{\word{2}}(\word{w})+\epsilon, 2(N_{\word{2}}(\word{u_i})+\epsilon_{1,i})\right\}}\right]dt
    \\ & \lesssim 
    1 + \int_0^T \E \left[|U_t|^{2(N - 1) + \epsilon}\right]dt.
\end{align*}
}
For the second term, the It\^o--Stratonovich correction is treated as in the inequality above, and for the It\^o integral, we use the Burkholder--Davis--Gundy inequality and Lemma~\ref{lem:expYV} to obtain that
{\begin{align*}
\E\left[\left|\int_0^T \left\langle  \word{v_j},\widehat{\mathbb{Y}}^U_t \right\rangle   dW_t\right|^{\frac{N_{\word{2}}(\word{w})+\epsilon}{N_{\word{2}}(\word{v_j})+\epsilon_{2,j}}}\right] &\lesssim \E\left[\left|\int_0^T \left\langle  \word{v_j},\widehat{\mathbb{Y}}^U_t \right\rangle^2   dt\right|^{\frac{N_{\word{2}}(\word{w})+\epsilon}{2(N_{\word{2}}(\word{v_j})+\epsilon_{2,j})}}\right] \\
&\lesssim 1 + \E\left[\left|\int_0^T \left\langle  \word{v_j},\widehat{\mathbb{Y}}^U_t \right\rangle^2   dt\right|^{\max\left\{\frac{N_{\word{2}}(\word{w})+\epsilon}{2(N_{\word{2}}(\word{v_j})+\epsilon_{2,j})}, 1\right\}}\right] \\
&\lesssim 1 + \E\left[ \int_0^T \left|\left\langle  \word{v_j},\widehat{\mathbb{Y}}^U_t \right\rangle\right|^{\max\left\{\frac{N_{\word{2}}(\word{w})+\epsilon}{N_{\word{2}}(\word{v_j})+\epsilon_{2,j}}, 2\right\}} dt\right]
\\
&\lesssim 1 + \E\left[ \int_0^T \left|U_t\right|^{\max\left\{{N_{\word{2}}(\word{w})+\epsilon}, 2(N_{\word{2}}(\word{v_j})+\epsilon_{2,j})\right\}} dt\right]
\\ & \lesssim 
1 + \int_0^T \E \left[|U_t|^{2(N - 1) + \epsilon}\right]dt.
\end{align*}
}
This proves \eqref{eq:term2}. 

{To conclude, combining \eqref{eq:third_term_bound}, \eqref{eq:second_term_bound}, and \eqref{eq:term2}, we observe that we have proven the existence of polynomial functions $P$ and $Q$ of orders strictly less than $2N$ and $N + 1$, respectively, such that, for any $u \in \mathcal{U}_q$,  
\begin{align*}
    {\E} \left[ \int_0^T  \left(\frac{\bar{\rho}^2 m^2 - m}{2} \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2 +  \rho m  \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle u_s - \frac{u_s^2}{2} \right)ds\right] \leq \E\left[\int_0^T \left(-c_1 U_t^{2N} + P(|U_t|)\right) dt +  \left(- c_4U_T^{N+1} + Q(|U_T|)\right)\right].
\end{align*}
Note that the polynomials under the expectation are bounded from above uniformly in $u$. This implies the finiteness of $\mathcal{V}(\rho,m,T)$, and by \eqref{eq:BD}, this proves the finiteness of $\E[S_T^m]$.
}
