{\section{Boué-Dupuis formula and proof of (\ref{eq:BD})} \label{sec:BD}


We will use the following variant of the Boué-Dupuis formula, which is a minor extension on recent results of \cite{HW22}.

In this section, $W=(W_t)_{0\leq t \leq T}$ is a ($d$-dimensional) Brownian motion under the measure $\P$, $(\mathcal{F}_t)_{t \geq 0}$ is its augmented natural filtration, and for any $q \geq 2$, we let
\[
\mathcal{U}_q = \left\{ (u_t)_{t \geq 0} (\mathcal{F}_t)-\mbox{progressively measurable with }{\E}\left[ \int_0^T |u_t|^q dt \right] < +\infty \right\}.
\]
\begin{proposition} \label{prop:BDext}
    Let $q\geq 2$ be fixed, and $F : C([0,T],\R^d) \to \R$ be (Borel-)measurable and such that 
   \begin{equation} \label{eq:asnBDq}
        \E \left[\left| F\left(W+\int_0^{\cdot} u\right) \right|\right] < \infty, \quad  u \in \mathcal{U}_q.
   \end{equation}
Then it holds that
\[
\ln \E\left[e^{F(W)}\right] = \sup_{u \in \mathcal{U}_q} \E \left[F\left(W+\int_0^{\cdot}u\right) - \frac{1}{2} \int_0^T u_s^2 ds\right].
\]
\end{proposition}

\begin{proof}
We proceed as in \cite[Remark 1.2 (1)]{HW22} by a truncation argument. For $n \geq 0$, let $F_n = F \wedge n$, then it holds that $\E[|F_n(W)|]$ and $\E[e^{F_n(W)}]$ are finite, so that we can apply the results of \cite{HW22} to obtain
\[
\ln \E\left[e^{F_n(W)}\right] = \sup_{u \in \mathcal{U}_q} \E \left[F_n\left(W+\int_0^{\cdot}u\right) - \frac{1}{2} \int_0^T u_s^2 ds\right]
\]
(They prove that the above formula holds for the supremum taken over both $\mathcal{U}_2$ and the set of bounded controls $\mathcal{U}_b$, see Theorem 1.1 and Corollary 2.11 therein. This implies the case of arbitrary $q \geq 2$ since $\mathcal{U}_b \subset \mathcal{U}_q \subset \mathcal{U}_2$).

We then have by monotone convergence that
\begin{align*}
 \ln  \E\left[e^{F(W)}\right] &= \sup_{n} \ln \E\left[e^{F_n(W)}\right] \\
   &= \sup_{n \geq 0} \sup_{u \in \mathcal{U}_q} \E \left[F_n\left(W+\int_0^{\cdot}u\right) - \frac{1}{2} \int_0^T u_s^2 ds\right] \\
   &= \sup_{u \in \mathcal{U}_q} \sup_{n \geq 0} \E \left[F_n\left(W+\int_0^{\cdot}u\right) - \frac{1}{2} \int_0^T u_s^2 ds\right]\\
   &= \sup_{u \in \mathcal{U}_q} \E \left[F\left(W+\int_0^{\cdot}u\right) - \frac{1}{2} \int_0^T u_s^2 ds\right]
\end{align*}
where the last equality follows from \eqref{eq:asnBDq} and dominated convergence.
\end{proof}

\begin{proof}[Proof of \eqref{eq:BD}]
    We let 
    \[
    F(W)=\rho m \int_0^T \bracketsig[s]{\bsigma} \,d W_s + \frac{\bar{\rho}^2 m^2 - m}{2} \int_0^T \bracketsig[s]{\bsigma}^2 \, ds
    \]
    and check that it satisfies \eqref{eq:asnBDq} for $q \geq 2N$.
    For $u \in \mathcal{U}_q$, letting $\widehat{\mathbb{X}}^u_t$ denote the signature of $\widehat{X}^u_t = (t, X^u_t)$ with $X^u_t$ defined by
\[
X^u_t = W_t + \int_0^{t} u_s ds,
\]
one has that
\[
F\left(W+ \int_0^{\cdot} u\right) =\rho m \int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle\,(d W_s+u_s ds) + \frac{\bar{\rho}^2 m^2 - m}{2} \int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2 \, ds
\]
As in Section 10.2, there exists $\tilde{\bsigma} \in \tTA[3]{N}$, such that $\left\langle \bsigma, \widehat{\mathbb{X}}^u_t \right\rangle = \left\langle \tilde\bsigma,\widehat{\mathbb{Y}}^U_t \right\rangle$ where $\widehat{\mathbb{Y}}^U_t$ is the signature of $Y^U_t=(t, \int_0^{t} u_s ds, W_t)$. By Lemma \ref{lem:expYV} and Hölder's inequality, this implies that
\begin{equation} \label{eq:boundBDq}
  \E \left[\int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2 \, ds\right] \leq C \left( 1 + \E\left[\int_0^T |u_s|^{2N} ds\right] \right) < \infty  
\end{equation}
since $q \geq 2N$. Since it holds that
\[\E \left[ \left| F\left(W+ \int_0^{\cdot} u\right) \right| \right] \leq C \left( 1 + \E\left[ \int_0^T u_s^2 ds\right] + \E\left[ \int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2  ds\right]\right)
\]
(using It\^o isometry for the term in $dW$ and Young's inequality for the term in $u_s ds$), we see that \eqref{eq:asnBDq} holds.

We then use Proposition \ref{prop:BDext} to obtain that
\begin{align*}
   \ln \E\left[e^{F(W)}\right] &=  \sup_{u \in \mathcal{U}_q} {\E} \left[- \int_0^T\frac{u_s^2}{2} ds + \int_0^T \rho m  \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle (dW_s + u_sds) +   \frac{\bar{\rho}^2 m^2 - m}{2}\int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2ds\right] \\
&=  \sup_{u \in \mathcal{U}_q} {\E} \left[- \int_0^T\frac{u_s^2}{2} ds + \int_0^T \rho m  \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle  u_s ds +   \frac{\bar{\rho}^2 m^2 - m}{2}\int_0^T \left\langle \bsigma, \widehat{\mathbb{X}}^u_s \right\rangle^2ds\right],
\end{align*}
where we have used that the stochastic integral has zero expectation by \eqref{eq:boundBDq}.
\end{proof}
}



