\begin{figure}
\centering
\includegraphics[width=0.35\linewidth]{twoparticles.eps}
\caption{Schema of two spheres approaching with relative velocity, $V$. The minimum distance between the sphere' contours is $h_0$.}
\label{Fig:twoparticles}
\end{figure}
