\section*{Appendix A. Analytic solution for velocity profile} \label{appA}

Here, the velocity profile derivation is given. The solution is calculated solving (\ref{Eq:ODEu}) using a reduction-order method, The Spanish State Research Agency through where $-\frac{d P'}{d R}(T) = \psi$, $\alpha(T) = \alpha$, $\phi = \frac{du}{dZ}$, and $\frac{d\phi}{dZ} = \frac{d^2u}{dZ^2}$. Considering such definitions, (\ref{Eq:ODEu}) becomes:

\begin{equation}
\psi + \frac{d \phi}{d Z} + \alpha \phi ^2 = 0.
\label{Eq:EDO2nL_1}
\end{equation}
\
Integration and application of the separation-of-variables method in (\ref{Eq:EDO2nL_1}), renders the solution:

\begin{equation}
\frac{-1}{2 \sqrt{-\alpha \psi}} Ln\left( \frac{\alpha \phi - \sqrt{-\alpha \psi}}{\alpha \phi + \sqrt{-\alpha \psi}} \right) = Z + C_1.
\label{Eq:EDO2nL_3}
\end{equation}
\
Solving for $\phi$ from (\ref{Eq:EDO2nL_3}):

\begin{equation}
\phi = \frac{d u}{d Z} = \frac{\sqrt{-\alpha \psi}}{\alpha} \frac{1 + e^{-2\sqrt{-\alpha \psi}(Z + C_1)}}{1 - e^{-2\sqrt{-\alpha \psi}(Z + C_1)}}.
\label{Eq:EDO2nL_4}
\end{equation}
\
Applying the separation of variables, the solution of (\ref{Eq:EDO2nL_4}) is:

\begin{equation}
u = \frac{\sqrt{-\alpha \psi}}{\alpha} \left[ Z + \frac{1}{\sqrt{-\alpha \psi}} Ln\left( e^{-2\sqrt{-\alpha \psi}Z} - e^{2\sqrt{-\alpha \psi}C_1} \right)  \right] + C_2.
\label{Eq:EDO2nL_5}
\end{equation}

Using the boundary condition in (\ref{Eq:CF}), renders a system of algebraic equations given by:

\begin{equation}
u(Z_1) = \frac{\sqrt{-\alpha \psi}}{\alpha} \left[ Z_1 + \frac{1}{\sqrt{-\alpha \psi}} Ln\left( e^{-2\sqrt{-\alpha \psi}Z_1} - e^{2\sqrt{-\alpha \psi}C_1} \right)  \right] + C_2,
\label{Eq:uZ1}
\end{equation}
\begin{equation}
u(Z_2) = \frac{\sqrt{-\alpha \psi}}{\alpha} \left[ Z_2 + \frac{1}{\sqrt{-\alpha \psi}} Ln\left( e^{-2\sqrt{-\alpha \psi}Z_2} - e^{2\sqrt{-\alpha \psi}C_1} \right)  \right] + C_2.
\label{Eq:uZ2}
\end{equation}
\
By subtracting (\ref{Eq:uZ1}) from (\ref{Eq:uZ2}), an expression is obtained from which the first integration constant $C_1$ can be calculated, which is:

\begin{equation}
e^{2\sqrt{-\alpha \psi}C_1} = \frac{e^{-2\sqrt{-\alpha \psi}Z_1} e^{\sqrt{-\alpha \psi}(Z_1-Z_2)} - e^{-2\sqrt{-\alpha \psi}Z_1}}{e^{\sqrt{-\alpha \psi}(Z_1-Z_2)} - 1},
\label{Eq:uC1}
\end{equation}
\
then, the second integration constant $C_2$ is:

\begin{equation}
C_2 = \frac{-\sqrt{-\alpha \psi}}{\alpha} \left[ Z_1 + \frac{1}{\sqrt{-\alpha \psi}} Ln \left( e^{-2\sqrt{-\alpha \psi}Z_1} - \right. \right. \\
\left. \left. \frac{e^{-2\sqrt{-\alpha \psi}Z_1} e^{\sqrt{-\alpha \psi}(Z_1-Z_2)} - e^{-2\sqrt{-\alpha \psi}Z_1}}{e^{\sqrt{-\alpha \psi}(Z_1-Z_2)} - 1} \right) \right].
\label{Eq:uC2}
\end{equation}

From this results, the solution for (\ref{Eq:EDO2nL_1}) is:

\begin{equation}
u = \frac{1}{\alpha} Ln \left( \frac{e^{\sqrt{-\alpha \psi}(Z_1(R)+Z_2(R)-Z)}}{e^{\sqrt{-\alpha \psi} Z_1(R)} + e^{\sqrt{-\alpha \psi} Z_2(R)}} \right. + \\
\left. \frac{e^{\sqrt{-\alpha \psi}(Z_1(R)+ Z)} + e^{\sqrt{-\alpha \psi}(Z_2(R)+ Z)}}{\left( e^{\sqrt{-\alpha \psi} Z_1(R)} + e^{\sqrt{-\alpha \psi} Z_2(R)} \right)^2 } \right).
\label{EC:usol}
\end{equation}
