\section*{Appendix B. Continuity equation} \label{appB}

To get an useful expression from mass conservation, (\ref{Eq:Cont_Adim}), we have the following steps \citep{HoriBOOK2006,RuangStonePRF2024}:

\begin{itemize}
\item First, (\ref{Eq:Cont_Adim}), is integrated with respect to the axial direction, as:
\begin{equation}
\int_{Z_1(R)}^{Z_2(R)} \left( \frac{1}{R} \frac{\partial}{\partial R}(Ru) + \frac{\partial w}{\partial Z} \right) \; dZ = 0.
\label{Eq:Cont_int_0exp}	
\end{equation}

\item Under the dimensionless boundary conditions from (\ref{Eq:CF}), i.e., $w(Z_1) = 0$ and $w(Z_2)= - 1$, (\ref{Eq:Cont_int_0exp}) renders as:

\begin{equation}
\frac{1}{R} \int_{Z_1(R)}^{Z_2(R)} \left( \frac{\partial}{\partial R}(Ru) \right) \; dZ - 1 = \frac{1}{R} \frac{\partial}{\partial R} \left( \int_{Z_1(R)}^{Z_2(R)} u \; RdZ \right) - 1 = 0.
\label{Eq:Cont_int_1exp}	
\end{equation}

\item Integrating (\ref{Eq:Cont_int_1exp}) with respect to radial direction:

\begin{equation}
\int_{Z_1(R)}^{Z_2(R)} u \; RdZ - \frac{R^2}{2} = 0.
\label{Eq:Cont_int_2exp}	
\end{equation}

\end{itemize}
\
Substituting the flow rate (\ref{Eq:flow1}) in the mass conservation (\ref{Eq:Cont_int_2exp}), the continuity equation may be re-cast as:

\begin{equation}
2\int_{Z_1(R)}^{Z_2(R)} u \; RdZ - R^2 = Q - R^2 = 0.
\end{equation}

