\section{Special Stable Range One Conditions}\label{sec:SSR1}

Let $R$ be a commutative ring with an involution $\theta$. Recall that a vector $(a, b, c) \in R^3$ is called \emph{special unitary completable} if it appears as the first row of some matrix in $SU(3, R)$. We say that $R$ satisfies the \emph{special stable range one condition} $(SSR_1)$ if, for every such vector, there exists $(z_1, z_2) \in \mathcal{A}(R)$ such that $a + b z_1 + c z_2$ is a unit in $R$.

\begin{thm}\label{thm:SSR_1}
    \normalfont
    Let $R$ be a commutative ring with an involution $\theta$. The following conditions are equivalent:
    \begin{enumerate}[(a)]
        \item $R$ satisfies $(SSR_1)$ condition.
        \item $SU(3,R) = T_{\sigma}(3, R)\, U^{-}_{\sigma}(3, R)\, U^{+}_{\sigma}(3, R)\, U^{-}_{\sigma}(3, R)$.
        \item $SU(3,R) = T_{\sigma}(3, R)\, U^{+}_{\sigma}(3, R)\, U^{-}_{\sigma}(3, R)\, U^{+}_{\sigma}(3, R)$.
    \end{enumerate}
\end{thm}

\begin{proof}
    \noindent $(a) \implies (b):$ Let $A = (a_{ij}) \in SU(3, R)$. Then the vector $(a_{11}, a_{12}, a_{13})$ is a special unitary completable. Since $R$ satisfies $(SSR_1)$, there exists $(z_1, z_2) \in \mathcal{A}(R)$ such that $a_{11} + a_{12} z_1 + a_{13} z_2 \in R^*$.
    Define the matrix $B = (b_{ij})$ by
    \[
        B = A \, x_{-}(\bar{z}_1, z_2).
    \]
    Since $(z_1, z_2) \in \mathcal{A}(R)$, it follows that $(\bar{z}_1, z_2) \in \mathcal{A}(R)$, and hence $x_{-}(\bar{z}_1, z_2) \in SU(3, R)$. Therefore, $B \in SU(3, R)$ as well. Moreover, we have $b_{11} = a_{11} + a_{12} z_1 + a_{13} z_2 \in R^*$.

    Now consider the matrix $C = (c_{ij})$ defined by
    \[
        C = x_{-} \left( -\frac{\overline{b_{21}}}{\overline{b_{11}}},\ -\frac{b_{31}}{b_{11}} + \frac{b_{21} \overline{{b}_{21}}}{b_{11} \overline{{b}_{11}}} \right) B.
    \]
    By (\ref{U11}), the pair $\left( -\frac{\overline{b_{21}}}{\overline{b_{11}}},\ -\frac{b_{31}}{b_{11}} + \frac{b_{21} \overline{{b}_{21}}}{b_{11} \overline{{b}_{11}}} \right) \in \mathcal{A}(R)$. Hence the matrix 
    \[
    x_{-} \left( -\frac{\overline{b_{21}}}{\overline{b_{11}}},\ -\frac{b_{31}}{b_{11}} + \frac{b_{21} \overline{{b}_{21}}}{b_{11} \overline{{b}_{11}}} \right) \in SU(3, R),
    \]
    and therefore $C \in SU(3, R)$.

    Observe that $c_{21} = c_{31} = 0$, and from equation (\ref{U'32}), it follows that $c_{32} = 0$ as well. Applying equations (\ref{U13}), (\ref{U22}) and the fact that $\det(C) = 1$, the matrix $C$ takes the form
    \[
        C = \begin{pmatrix}
            c_{11} & * & * \\
            0 & (c_{11})^{-1} \bar{c}_{11} & * \\
            0 & 0 & (\bar{c}_{11})^{-1}
        \end{pmatrix}
        = h(c_{11})\, x_{+}(*,*),
    \]
    where $x_{+}(*,*) \in U^{+}_{\sigma}(3, R)$.

    Therefore, we conclude that
    \[
        x_{-} \left( -\frac{\overline{b_{21}}}{\overline{b_{11}}},\ -\frac{b_{31}}{b_{11}} + \frac{b_{21} \overline{{b}_{21}}}{b_{11} \overline{{b}_{11}}} \right) \cdot A \cdot x_{-}(\bar{z}_1, z_2) = h(c_{11})\, x_{+}(*,*).
    \]
    Rewriting $A$ accordingly, we obtain:
    \begin{align*}
        A &= x_{-}(*,*) \cdot h(*) \cdot x_{+}(*,*) \cdot x_{-}(*,*) \\
        &= h(*) \cdot \left(h(*)^{-1} x_{-}(*,*) h(*)\right) \cdot x_{+}(*,*) \cdot x_{-}(*,*) \\
        &= h(*) \cdot x_{-}(*,*) \cdot x_{+}(*,*) \cdot x_{-}(*,*) \\
        &\in T_{\sigma}(3, R)\, U^{-}_{\sigma}(3, R)\, U^{+}_{\sigma}(3, R)\, U^{-}_{\sigma}(3, R),
    \end{align*}
    as required.

    \vspace{2mm}

    \noindent $(b) \implies (a):$ Let $(a, b, c) \in R^3$ be a special unitary completable vector. Then, by definition, there exists a matrix $A \in SU(3, R)$ of the form
    \[
        A = \begin{pmatrix}
            a & b & c \\
            * & * & * \\
            * & * & *
        \end{pmatrix}.
    \]
    By assumption, there exists $r \in R^*$ and $(z_1, z_2) \in \mathcal{A}(R)$ such that $A$ admits the factorization
    \[
        A = h(r)\, x_{-}(*,*)\, x_{+}(*,*)\, x_{-}(-\bar{z}_1, \bar{z_2}).
    \]
    Multiplying both sides on the right by $x_{-}(\bar{z}_1, z_2)$ yields
    \[
        A \, x_{-}(\bar{z}_1, z_2) = h(r) \, x_{-}(*,*) \, x_{+}(*,*).
    \]
    Comparing the $(1,1)$-entry on both sides, we obtain
    \[
        a + b z_1 + c z_2 = r \in R^*,
    \]
    as required.

    \vspace{2mm}

    \noindent $(b) \iff (c):$ The equivalence of these statements follows directly from the following identities:
    \begin{align*}
        w(1) \, SU(3, R) \, w(1)^{-1} &= SU(3, R) && \text{since } w(1) \in SU(3, R), \\
        w(1) \, T_{\sigma}(3, R) \, w(1)^{-1} &= T_{\sigma}(3, R) && \text{by equation (\ref{HW3})}, \\
        w(1) \, U^{+}_{\sigma}(3, R) \, w(1)^{-1} &= U^{-}_{\sigma}(3, R) && \text{by equation (\ref{W1})}, \\
        w(1) \, U^{-}_{\sigma}(3, R) \, w(1)^{-1} &= U^{+}_{\sigma}(3, R) && \text{by equation (\ref{W2})}.
    \end{align*}
    This completes the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{cor}\label{cor:SSR_1}
    \normalfont
    Let $R$ be a commutative ring with an involution $\theta$. The following are equivalent:
    \begin{enumerate}[(a)]
        \item $R$ satisfies $(SSR_1)$ condition.
        \item For every vector $(a,b,c) \in R^3$ that appears as the first column of some matrix in \( SU(3, R) \), there exists a pair $(z_1, z_2) \in \mathcal{A}(R)$ such that \( a + b z_1 + c z_2 \in R^* \).
        \item For every vector $(a,b,c) \in R^3$ that appears as the last row of some matrix in \( SU(3, R) \), there exists a pair $(z_1, z_2) \in \mathcal{A}(R)$ such that \( c + b z_1 + a z_2 \in R^* \).
        \item For every vector $(a,b,c) \in R^3$ that appears as the last column of some matrix in \( SU(3, R) \), there exists a pair $(z_1, z_2) \in \mathcal{A}(R)$ such that \( c + b z_1 + a z_2 \in R^* \).
    \end{enumerate}
\end{cor}

\begin{proof}
    \noindent $(a) \implies (b):$ Suppose $R$ satisfies $(SSR_1)$ condition. Let $(a,b,c) \in R^3$ be such that it forms the first column of some matrix $A \in SU(3, R)$. By Theorem~\ref{thm:SSR_1}, there exists $r \in R^*$ and $(z_1, z_2) \in \mathcal{A}(R)$ such that $A$ admits the factorization
    \[
        A = h(r) x_{+}(- r^{-2} \bar{r} z_1, (r \bar{r})^{-1} \bar{z}_2) x_{-}(*, *) x_{+}(*, *).
    \]
    Left-multiplying both sides by \( x_{+}(z_1, z_2) \), we get
    \begin{align*}
        x_{+}(z_1, z_2) A &= x_{+}(z_1, z_2) \left( h(r) x_{+}(- r^{-2} \bar{r} z_1, (r \bar{r})^{-1} \bar{z}_2) h(r)^{-1} \right) h(r) \, x_{-}(*, *) \, x_{+}(*, *) \\
        &= h(r) x_{-} (*, *) x_{+} (*, *).
    \end{align*}
    Looking at the \((1,1)\)-entry of both sides, we find
    \[
        a + b z_1 + c z_2 = r \in R^*,
    \]
    as desired.

    \vspace{2mm}

    \noindent $(b) \implies (a):$ By following the similar argument used in the $(a) \implies (b)$ direction of Theorem~\ref{thm:SSR_1}, we can obtain  
    \[
        SU(3, R) = T_{\sigma}(3, R) \, U^{+}_{\sigma}(3, R) \, U^{-}_{\sigma}(3, R) \, U^{+}_{\sigma}(3, R).
    \] 
    Since $(a)$ and $(c)$ of Theorem~\ref{thm:SSR_1} are equivalent, the conclusion follows.    

    \vspace{2mm}

    \noindent $(a) \iff (c) \ \text{and} \ (a) \iff (d):$ The proofs are analogous to that of $(a) \iff (b)$ and are therefore omitted.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Proposition~\ref{prop:semilocal has SSR_1} (stated below) illustrates a class of rings that satisfy the $(SSR_1)$ condition. Before presenting the proposition, we introduce some relevant notation.
For any $r \in R$, define
\[
    M_r := \{ \mathfrak{m} \in \mathrm{Max}(R) \mid r \in \mathfrak{m} \}.
\]
Note that $M_0 = \mathrm{Max}(R)$ and $M_1 = \emptyset$.
Now, define the set
\[
    J_r := \left( \bigcap_{\mathfrak{m} \in M_0 \setminus M_r} \mathfrak{m} \right) \setminus \left( \bigcup_{\mathfrak{m} \in M_r} \mathfrak{m} \right).
\]
Adopting the standard conventions that the intersection over the empty set is the entire ring $R$, and the union over the empty set is the empty set, we observe the following equivalences:
\begin{enumerate}[(a)]
    \item $r \in R^* \quad \Longleftrightarrow \quad M_r = \emptyset \quad \Longleftrightarrow \quad J_r = \mathrm{Jac}(R)$, the Jacobson radical of $R$.
    \item $r \in \mathrm{Jac}(R) \quad \Longleftrightarrow \quad M_r = M_0 \quad \Longleftrightarrow \quad J_r = R^*.$
\end{enumerate}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lemma}\label{lemma:I_r and J_r}
    \normalfont
    Let $R$ be a commutative ring with unity, and let $r \in R$.
    \begin{enumerate}[(a)]
        \item If $J_r \neq \emptyset$, then for any $s \in J_r$, we have $r + s \in R^*$.
        \item Assume that $R$ is semi-local ring. Then $J_r \neq \emptyset$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    \noindent (a) Let $s \in J_r$. Suppose, for the sake of contradiction, that $r + s \notin R^*$. 
    First, assume $r + s \in \bigcup_{\mathfrak{m} \in M_r} \mathfrak{m}$, that is, $r + s \in \mathfrak{m}_0$ for some $\mathfrak{m}_0 \in M_r$. Since $r \in \mathfrak{m}_0$, it follows that $s \in \mathfrak{m}_0$ as well. This contradicts the fact that $s \notin \bigcup_{\mathfrak{m} \in M_r} \mathfrak{m}$.

    Now assume $r + s \notin \bigcup_{\mathfrak{m} \in M_r} \mathfrak{m}$, that is, $r + s \notin \mathfrak{m}$ for every $\mathfrak{m} \in M_r$. However, since \( r + s \notin R^* \), it must lie in some maximal ideal \( \mathfrak{m}_0 \in M_0 \setminus M_r \). Since $s \in J_r$, we have $s \in \mathfrak{m}_0$, which implies that $r \in \mathfrak{m}_0$. This contradicts the fact that \( \mathfrak{m}_0 \in M_0 \setminus M_r \). 
    Therefore, $r + s \in R^*$, as desired.

    \medskip

    \noindent (b) Suppose, for contradiction, that $J_r = \emptyset$. Then, by definition,
    \[
        \bigcap_{\mathfrak{m} \in M_0 \setminus M_r} \mathfrak{m} \subseteq \bigcup_{\mathfrak{m} \in M_r} \mathfrak{m}.
    \]
    By the prime avoidance theorem, there exists $\mathfrak{m}_0 \in M_r$ such that
    \[
        \bigcap_{\mathfrak{m} \in M_0 \setminus M_r} \mathfrak{m} \subseteq \mathfrak{m}_0.
    \]
    For each $\mathfrak{m} \in M_0 \setminus M_r$, we have $\mathfrak{m} \neq \mathfrak{m}_0$, and hence $\mathfrak{m} + \mathfrak{m}_0 = R$. Therefore, for each such $\mathfrak{m}$, there exist elements $x_{\mathfrak{m}} \in \mathfrak{m}$ and $y_{\mathfrak{m}} \in \mathfrak{m}_0$ such that $x_{\mathfrak{m}} + y_{\mathfrak{m}} = 1$. 
    Define
    \[
        x := \prod_{\mathfrak{m} \in M_0 \setminus M_r} x_{\mathfrak{m}} = \prod_{\mathfrak{m} \in M_0 \setminus M_r} (1 - y_{\mathfrak{m}}) = 1 - y,
    \]
    for some $y \in \mathfrak{m}_0$. Since $x_{\mathfrak{m}} \in \mathfrak{m}$ for each $\mathfrak{m} \in M_0 \setminus M_r$, it follows that $x \in \bigcap_{\mathfrak{m} \in M_0 \setminus M_r} \mathfrak{m} \subseteq \mathfrak{m}_0$. However, $x = 1 - y$ with $y \in \mathfrak{m}_0$ implies $1 \notin \mathfrak{m}_0$, a contradiction. 
    Thus, the assumption $J_r = \emptyset$ is false, and we conclude that $J_r \neq \emptyset$, which proves $(b)$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop}\label{prop:semilocal has SSR_1}
    \normalfont
    Let $R$ be a semi-local ring with an involution $\theta$. Assume that $\bar{\mathfrak{m}} = \mathfrak{m}$ for every maximal ideal $\mathfrak{m} \in \mathrm{Max}(R)$ and $\mathcal{A}(R)^* \neq \emptyset$. Then $R$ satisfies $(SSR_1)$ condition.
\end{prop}

\begin{proof}
    Let $(a,b,c) \in R^3$ be a special unitary completable vector. Then, by definition, there exists a matrix $A \in SU(3, R)$ of the form 
    \[
        A = \begin{pmatrix}
            a & b & c \\
            * & * & * \\
            * & * & *
        \end{pmatrix}.
    \]
    From equations~(\ref{U'11}), (\ref{U'12}) and (\ref{U'21}), we deduce that $M_a \subset M_b$. Similarly, equations~(\ref{U'12}), (\ref{U'13}) and (\ref{U'23}) imply that $M_c \subset M_b$. Consequently, $(M_a \cup M_c) \subset M_b \subset M_0$. 
    Moreover, since $\det (A) = 1$, we can deduce that $M_a \cap M_c = \emptyset$. 
    Finally, observe that $M_{ac} = M_a \cup M_c$. 

    Since $\mathcal{A}(R)^* \neq \emptyset$, choose any $(z_1, z_2) \in \mathcal{A}(R)^*$.
    Define the set
    \[
        J = \left( \bigcap_{\mathfrak{m} \in M_0 \setminus M_{ac}} \mathfrak{m} \right) \setminus \left( \bigcup_{\mathfrak{m} \in M_a} \mathfrak{m} \right).
    \]
    Note that, $J_{ac} \subset J$. By Lemma~\ref{lemma:I_r and J_r}, part $(b)$, we have $J_{ac} \neq \emptyset$ and hence $J \neq \emptyset$. 
    Fix any $z \in J$. Then $(zz_1, z \bar{z} z_2) \in \mathcal{A}(R)$.
    We observe that $c z \bar{z} z_2 \in J_a$. By Lemma~\ref{lemma:I_r and J_r}, part $(a)$, we conclude that $a + c z \bar{z} z_2 \in R^*$. Also, observe that $b z z_1 \in \mathrm{Jac} (R)$. Hence $a + b z z_1 + c z \bar{z} z_2 \in R^*$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{cor}
    \normalfont
    Let $(R, \mathfrak{m}, k)$ be a local ring with an involution $\theta$. Assume that $\mathcal{A}(R)^* \neq \emptyset$. Then $R$ satisfies $(SSR_1)$ condition.
\end{cor}

\begin{cor}
    \normalfont
    Every field (with an involution) satisfies $(SSR_1)$ condition.
\end{cor}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop}\label{prop:prod of SSR1}
    \normalfont
    Let $\Gamma$ be a fixed index set, and for each $i \in \Gamma$, let $R_i$ be a ring equipped with an involution $\theta_i$. Suppose that each $R_i$ satisfies the $(SSR_1)$ condition. Then the product ring $R = \prod_{i \in \Gamma} R_i$, equipped with the componentwise involution $\theta = \prod_{i \in \Gamma} \theta_i$, also satisfies the $(SSR_1)$ condition.
\end{prop}

\begin{proof}
    Since $R = \prod_{i \in \Gamma} R_i$, it follows that
    \[
        SU(3, R) = \prod_{i \in \Gamma} SU(3, R_i).
    \]
    For any $r \in R$, let $r_i \in R_i$ denote its $i$-th component.  
    If $(a, b, c) \in R^3$ is special unitary completable, then each $(a_i, b_i, c_i) \in R_i^3$ is also special unitary completable.
    Thus, for each $i$, there exist $(z_1^{(i)}, z_2^{(i)}) \in \mathcal{A}(R_i)$ such that $a_i + b_i z_1^{(i)} + c_i z_2^{(i)} \in R_i^*$. 
    Define $z_1 = (z_1^{(i)})_{i \in \Gamma} \quad \text{and} \quad z_2 = (z_2^{(i)})_{i \in \Gamma}$. 
    Then $(z_1, z_2) \in \mathcal{A}(R)$, and $a + b z_1 + c z_2 \in R^*$, as required.
\end{proof}



