%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\section{\texorpdfstring{$\theta$}{theta}-complete Ring}\label{sec:theta-complete ring}

Let $R$ be a commutative ring with unity with an involution $\theta$.
As in Section~\ref{sec:intro}, we introduce the set
\[
\mathcal{B}_1(R) = \{ u \in R \mid \text{there exists } t \in R \text{ such that } (t,u) \in \mathcal{A}(R)^{*}\}.
\]
If $\mathcal{A}(R)^* \neq \emptyset$ (equivalently, $\mathcal{B}_1(R) \neq \emptyset$), then for any $k \in \mathbb{N}$, define
\[
\mathcal{B}_k(R) = \{ u \in R \mid \text{there exist } u_1, \dots, u_k \in \mathcal{B}_1(R) \text{ such that } u = u_1 \dots u_k \}.
\]
Otherwise, set $\mathcal{B}_k(R) = \emptyset$.  
Now, define the sets  
\[
\mathcal{C}_{\text{even}}(R) = \bigcup_{\ell \in \mathbb{N}} \mathcal{B}_{2\ell}(R)
\quad \text{and} \quad
\mathcal{C}_{\text{odd}}(R) = \bigcup_{\ell \in \mathbb{N}} \mathcal{B}_{2\ell - 1}(R).
\]
For the sake of completeness (though this will not be needed later) we define, for each $k \in \mathbb{N}$,  
\[
\mathcal{C}_k(R) = \bigcup_{\ell \in \mathbb{N}} \mathcal{B}_{k\ell}(R).
\]
It is evident that  
\[
\mathcal{C}_{\text{even}}(R) = \mathcal{C}_2(R).
\]

\begin{rmk}
    \normalfont
    The following properties follow immediately from the definitions:
    \begin{enumerate}[(a)]
        \item If $2 \in R^*$, then $\mathcal{B}_k(R) \neq \emptyset$ for all $k \in \mathbb{N}$, since $(2,2) \in \mathcal{A}(R)^*$. Consequently, $\mathcal{C}_k(R) \neq \emptyset$ for all $k \in \mathbb{N}$.

        \item \label{rmk:(b)} If $u$ is in $\mathcal{B}_k(R)$, then so are $\bar{u}, u^{-1}$ and $a \bar{a} u \ (a \in R^*)$.

        \item If $\mathcal{A}(R) \neq \emptyset$, then each $\mathcal{C}_k(R)$ forms a subgroup of the multiplicative group $R^*$ generated by $\mathcal{B}_k(R)$. In particular, $\mathcal{C}_{\text{even}}(R)$ is a subgroup of $R^*$.

        \item If $1 \in \mathcal{B}_k(R)$, then for all $m \in \mathbb{N}$, we have the inclusion  
        \[
        \mathcal{B}_m(R) \subset \mathcal{B}_{k+m}(R).
        \]
        In particular, since $1 \in \mathcal{B}_2(R)$ (provided $\mathcal{A}(R)^* \neq \emptyset$), it follows that  
        \[
        \mathcal{B}_1(R) \subset \mathcal{B}_3(R) \subset \mathcal{B}_5(R) \subset \cdots 
        \quad \text{and} \quad
        \mathcal{B}_2(R) \subset \mathcal{B}_4(R) \subset \mathcal{B}_6(R) \subset \cdots.
        \]
    \end{enumerate}
\end{rmk}

\begin{defn}
    \normalfont
    Let $R$ be a commutative ring with an involution $\theta$.
    \begin{enumerate}[(a)]
        \item We say that $R$ is \emph{$\theta$-complete} if
        \[
            \mathcal{C}_{\text{even}}(R) = R^*.
        \]

        \item We say that $R$ has \emph{finite $\mathcal{C}$-length} if there exists $k \in \mathbb{Z}^+$ such that
        \[
            \mathcal{C}_{\text{even}}(R) = \mathcal{B}_{2k}(R).
        \]
        The minimal such $k$ is called the \emph{$\mathcal{C}$-length} of $R$. If no such $k$ exists, we say that the $\mathcal{C}$-length of $R$ is $\infty$.

    \end{enumerate}
\end{defn}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop}\label{prop:field is theta-complete}
    \normalfont
    Every field is $\theta$-complete with $\mathcal{C}$-length $1$. 
\end{prop}

\begin{proof}
    Let $R$ be a field and let $u \in R^*$. 
    Suppose that $u \neq \bar{u}$. Then the element $u - \bar{u}$ is invertible in $R$. 
    In this case, define 
    \[
        u_1 = u - \bar{u} \quad \text{and} \quad u_2 = u (u_1)^{-1}.
    \]
    Clearly, we have $u = u_1 u_2$ with $u_1, u_2 \in \mathcal{B}_1(R)$, as $(0, u_1), (1, u_2) \in \mathcal{A} (R)^{*}$, respectively. Thus, $u \in \mathcal{B}_2(R)$, as desired. 

    Now, suppose that $u = \bar{u}$. Choose any element $a \in R^{-}_{\theta} \cap R^*$ (such an element always exist in the field) and set
    \[
        u_1 = a \quad \text{and} \quad u_2 = u (a)^{-1}.
    \]
    Again, we observe that $u = u_1 u_2$ with $u_1, u_2 \in \mathcal{B}_1(R)$, as $(0, u_1), (0, u_2) \in \mathcal{A} (R)^{*}$, respectively. 
    Hence, we conclude that $u \in \mathcal{B}_2(R)$,  completing the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop}
    \normalfont
    Let $(R, \mathfrak{m}, k)$ be a local ring. Assume that $2 \in R^*$ and that $R_\theta^{-} \cap R^* \neq \emptyset$. Then $R$ is $\theta$-complete with $\mathcal{C}$-length $\leq 2$.
\end{prop}

\begin{proof}
    Let $u \in R^*$. 
    Suppose that $u - \bar{u} \not \in \mathfrak{m}$. Then it is invertible in $R$. 
    In this case, define 
    \[
        u_1 = u - \bar{u} \quad \text{and} \quad u_2 = u (u_1)^{-1}.
    \]
    Clearly, we have $u = u_1 u_2$ with $u_1, u_2 \in \mathcal{B}_1(R)$, as $(0, u_1), (1, u_2) \in \mathcal{A} (R)^{*}$, respectively. Hence, we have $u \in \mathcal{B}_2(R)$, as desired. 

    Now, suppose that $u - \bar{u} \in \mathfrak{m}$. Then we must have that $u + \bar{u}$ is invertible in $R$. Choose any element $a \in R^{-}_{\theta} \cap R^*$ and set
    \[
        u_1 = a, \quad u_2 = \frac{u + \bar{u}}{2a}, \quad u_3 = \frac{u}{u + \bar{u}} \quad \text{and} \quad u_4 = 2.
    \]
    We observe that $u = u_1 u_2 u_3 u_4$ with $u_1, u_2, u_3, u_4 \in \mathcal{B}_1(R)$, as $(0, u_1), (0, u_2), (1, u_3), (2,2) \in \mathcal{A} (R)^{*}$, respectively. 
    Hence, we conclude that $u \in \mathcal{B}_4(R)$,  completing the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop}
    \normalfont
    Let $R$ be a semi-local ring with exactly two maximal ideals $\mathfrak{m}_1$ and $\mathfrak{m}_2$. Suppose that $2 \in R^*$, and $R_\theta^{-} \cap R^* \neq \emptyset$. Further, assume that $\bar{\mathfrak{m}}_1 = \mathfrak{m}_2$. Then $R$ is $\theta$-complete with $\mathcal{C}$-length $\leq 2$.
\end{prop}

\begin{proof}
    Let $u \in R^*$.  
    If $u - \bar{u} \in R^*$, we proceed exactly as in the proof of the previous proposition.  
    Now, suppose $u - \bar{u} \in \mathfrak{m}_1 \cup \mathfrak{m}_2$.  
    By assumption, $u - \bar{u} \in \mathfrak{m}_1 \cap \mathfrak{m}_2 = \mathrm{Jac}(R)$.  
    In that case, $u + \bar{u} \in R^*$.  
    Thus, we are again in the situation of the previous theorem, and the same argument applies.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop} 
    \normalfont
    Let $\Gamma$ be a fixed index set, and for each $i \in \Gamma$, let $R_i$ be a ring equipped with an involution $\theta_i$. Suppose that each $R_i$ is $\theta_i$-complete with $\mathcal{C}$-length $k_i$. The the product ring $R = \prod_{i \in \Gamma} R_i$, equipped with the componentwise involution $\theta = \prod_{i \in \Gamma} \theta_i$, is $\theta$-complete with $\mathcal{C}$-length $k = \text{Sup}_{i \in \Gamma} k_i$.
\end{prop}

\begin{proof}
    The proof is similar to that of Proposition~\ref{prop:prod of SSR1} and is therefore omitted.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop}\label{prop:T=H=H'}
    \normalfont
    Let $R$ be a $\theta$-complete ring. Then 
    \[
        T_{\sigma}(3, R) = H_{\sigma}(3, R) = H'_{\sigma}(3, R).
    \]
\end{prop}

\begin{proof}
    Since $H'_\sigma(3, R) \subset H_\sigma(3, R) \subset T_\sigma(3, R)$, it suffices to show that $T_\sigma(3, R) \subset H'_\sigma(3, R)$. By (\ref{H3}) and part~\ref{rmk:(b)} of the remark preceding Proposition~\ref{prop:field is theta-complete}, we know that for every $r \in \mathcal{B}_2(R)$, we have $h(r) \in H'_\sigma(3, R)$. 

    Now, since $R$ is $\theta$-complete, for any $r \in R^*$ there exists $k \in \mathbb{Z}^+$ such that $r \in \mathcal{B}_{2k}(R)$. By definition of $\mathcal{B}_{2k}(R)$, we can express $r$ as $r = r_1 \cdots r_k$ with each $r_i \in \mathcal{B}_2(R)$. It follows that
    \[
        h(r) = h(r_1) \cdots h(r_k),
    \]
    and since each $h(r_i) \in H'_\sigma(3, R)$, we conclude that $h(r) \in H'_\sigma(3, R)$. Thus, $T_\sigma(3, R) \subset H'_\sigma(3, R)$, completing the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{thm}\label{thm:T is as unitriangular}
    \normalfont
    Let $R$ be a $\theta$-complete ring with $\mathcal{C}$-length $k$. Then
    \[
        T_{\sigma}(3, R) \subset \left( U^{+}_\sigma (3, R) \, U^{-}_\sigma (3, R) \right)^{k+1} \quad \text{and} \quad T_{\sigma}(3, R) \subset \left( U^{-}_\sigma (3, R) \, U^{+}_\sigma (3, R) \right)^{k+1}.
    \]
\end{thm}

\begin{proof}
    Let $h(r) \in T_\sigma(3, R)$ for some $r \in R^*$. Since $R$ is $\theta$-complete, there exists $k \in \mathbb{Z}^+$ such that $r \in \mathcal{B}_{2k}(R)$. Choose the minimal such $k$. By definition of $\mathcal{B}_{2k}(R)$, there exist elements $r_1, \dots, r_{2k} \in \mathcal{B}_1(R)$ such that
    \[
        r = r_1 r_2 \cdots r_{2k}.
    \]

    Since each $r_{2i} \in \mathcal{B}_1(R)$, it follows that $r_{2i}^{-1} \in \mathcal{B}_1(R)$. Therefore, there exists $(z_1^{(i)}, z_2^{(i)}) \in \mathcal{A}(R)^*$ such that $z_2^{(i)} = r_{2(k - i) + 2}^{-1}$, for each $i = 1, \dots, k$.
    Similarly, since each $r_{2i - 1} \in \mathcal{B}_1(R)$, there exists $(y_1^{(i)}, y_2^{(i)}) \in \mathcal{A}(R)^*$ such that $y_2^{(i)} = r_{2(k - i) + 1}$, for each $i = 1, \dots, k$.
    Define
    \[
        x_1^{(i)} := \frac{y_1^{(i)}}{y_2^{(i)}} - \frac{z_1^{(i)}}{z_2^{(i)}} \quad \text{and} \quad
        x_2^{(i)} := \left( \frac{1}{y_2^{(i)}} - \frac{1}{z_2^{(i)}} \right) 
                 - \frac{z_1^{(i)}}{z_2^{(i)}} \left( \frac{\bar{y}_1^{(i)}}{\bar{y}_2^{(i)}} - \frac{\bar{z}_1^{(i)}}{\bar{z}_2^{(i)}} \right).
    \]
    Then $(x_1^{(i)}, x_2^{(i)}) \in \mathcal{A}(R)$ for each $i = 1, \dots, k$.

    Now define $C^{(0)} := h(r)$. For each $i \in {1, \dots, k}$, inductively define
    \begin{align*}
        A^{(i)} &:= C^{(i-1)} \cdot x_{+}(z_1^{(i)}, z_2^{(i)}), \\
        B^{(i)} &:= A^{(i)} \cdot x_{-}(x_1^{(i)}, x_2^{(i)}), \\
        C^{(i)} &:= B^{(i)} \cdot x_{+}(y_1^{(i)}, y_2^{(i)})^{-1}.
    \end{align*}

    For each $i = 1, \dots, k$, define
    \[
        s_i := r_1 r_2 \cdots r_{2(k - i) + 1} r_{2(k - i) + 2}, \quad \text{and} \quad s_{k+1} := 1.
    \]
    A straightforward computation shows that for each $i = 1, \dots, k$, the matrices $A^{(i)}$, $B^{(i)}$, and $C^{(i)}$ take the form:
    \[
        A^{(i)} = \begin{pmatrix}
            s_i & s_i z_1^{(i)} & s_i z_2^{(i)} \\
            * & * & * \\
            * & * & *
        \end{pmatrix}, \quad
        B^{(i)} = \begin{pmatrix}
            s_{i+1} & s_{i+1} y_1^{(i)} & s_{i+1} y_2^{(i)} \\
            * & * & * \\
            * & * & *
        \end{pmatrix}, \quad
        C^{(i)} = \begin{pmatrix}
            s_{i+1} & 0 & 0 \\
            * & * & * \\
            * & * & *
        \end{pmatrix}.
    \]

    Observe that
    \[
        C^{(k)} = \begin{pmatrix}
            1 & 0 & 0 \\
            c_{21} & c_{22} & c_{23} \\
            c_{31} & c_{32} & c_{33}
        \end{pmatrix}.
    \]
    By condition (\ref{U'23}), we have $c_{23} = 0$; by (\ref{U'11}), it follows that $c_{22} = 1$; and from (\ref{U'33}), we obtain $c_{33} = 1$. Therefore, $C^{(k)} \in U_{\sigma}^{-}(3, R)$.

    Moreover, by construction,
    \[
        C^{(k)} \in C^{(k-1)} \cdot U^{+}_{\sigma}(3, R) \cdot U^{-}_{\sigma}(3, R) \cdot U^{+}_{\sigma}(3, R).
    \]
    Hence, by iterating this relation,
    \[
        C^{(k)} \in C^{(0)} \cdot \left(U^{+}_{\sigma}(3, R) \cdot U^{-}_{\sigma}(3, R) \cdot U^{+}_{\sigma}(3, R)\right)^k = C^{(0)} \cdot \left(U^{+}_{\sigma}(3, R) \cdot U^{-}_{\sigma}(3, R)\right)^k \cdot U^{+}_{\sigma}(3, R).
    \]
    Since $C^{(0)} = h(r)$ and $C^{(k)} \in U^{-}_{\sigma}(3, R)$, we conclude that
    \[
        h(r) \in \left(U^{-}_{\sigma}(3, R) \cdot U^{+}_{\sigma}(3, R)\right)^{k+1}
    \]
    for every $r \in R^*$. Conjugating both sides by $w(1)$, we then obtain
    \[
        h(r) \in \left(U^{+}_{\sigma}(3, R) \cdot U^{-}_{\sigma}(3, R)\right)^{k+1}
    \]
    for every $r \in R^*$. 
\end{proof}

\begin{cor}\label{cor:unitriangular for SU(3,R)}
    \normalfont
    Let $R$ be a $\theta$-complete ring with $\mathcal{C}$-length $k$. Suppose $R$ satisfies $(SSR_1)$ condition. Then 
    \begin{align*}
        SU(3, R) = E_\sigma(3, R) = E'_\sigma(3,R) 
        &= \left( U^{+}_{\sigma} (3, R) \, U^{-}_{\sigma} (3, R) \right)^{k+1} U^{+}_{\sigma} (3, R) \\
        &= \left( U^{-}_{\sigma} (3, R) \, U^{+}_{\sigma} (3, R) \right)^{k+1} U^{-}_{\sigma} (3, R).
    \end{align*}
\end{cor}

\begin{proof}
    Immediate from Theorem~\ref{thm:SSR_1} and Theorem~\ref{thm:T is as unitriangular}.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Finally, we conclude this section by addressing the following question: under what conditions do $T_\sigma(\Phi, R)$ and $H'_\sigma(\Phi, R)$ coincide? This question has already been answered in the case where $\Phi_\rho \not\sim {}^2A_{2n}$; in such cases, the two subgroups coincide for any commutative ring $R$. However, when $\Phi_\rho \sim {}^2A_{2n} \ (n \geq 1)$, additional conditions are needed to ensure the subgroups coincide.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{prop}\label{prop:T=H=H' for general case}
    \normalfont
    Let $\Phi_\rho$ be a twisted root system of type ${}^2 A_{n} \ (n \geq 2), {}^2 D_{n} \ (n \geq 4), {}^2 E_6$, or ${}^3 D_4$.
    Let $R$ be a commutative ring with unity, and suppose there exists an automorphism $\theta: R \to R$ of order $2$ if $\Phi_\rho \not\sim {}^3D_4$, and of order $3$ if $\Phi_\rho \sim {}^3D_4$. 
    Assume further that $R$ is $\theta$-complete in the case where $\Phi_\rho \sim {}^2A_{2n}$. 
    Then
    \[
        T_\sigma(\Phi, R) = H_\sigma(\Phi, R) = H'_\sigma(\Phi, R).
    \]
\end{prop}

\begin{proof}
    Recall that it is well known that $T(\Phi, R) = H(\Phi, R)$ for all commutative ring $R$ when $\Phi \sim A_n \ (n \geq 2), D_n \ (n \geq 4), E_6$. 
    It follows that $T_\sigma (\Phi, R) = H_\sigma (\Phi, R)$ for all $R$ whenever $\Phi_\rho \sim {}^2 A_{n} \ (n \geq 2), {}^2 D_{n} \ (n \geq 4), {}^2 E_6$ or ${}^3 D_4$. 
    Moreover, it is also known that $H_\sigma(\Phi, R) = H'_\sigma(\Phi, R)$ for all $R$ whenever $\Phi_\rho \not\sim {}^2 A_{2n}$. 
    Therefore, to prove the proposition, it suffices to consider the case $\Phi_\rho \sim {}^2 A_{2n}$ and show that
    \[
        H_\sigma(A_{2n}, R) \subseteq H'_\sigma(A_{2n}, R)
    \]
    under the assumption that $R$ is $\theta$-complete.

    Let $h \in H_\sigma(A_{2n}, R)$. Then $h$ can be expressed as a product
    \[
        h = \prod_{[\alpha] \in \Phi_\rho} h_{[\alpha]}(t_{[\alpha]}),
    \]
    where each $t_{[\alpha]} \in R_{[\alpha]}^*$.  
    If $[\alpha] \sim A_1^2$, then it is immediate that $h_{[\alpha]}(t_{[\alpha]}) \in H'_\sigma(A_{2n}, R)$.  
    If $[\alpha] \sim A_2$, then by Proposition~\ref{prop:T=H=H'}, we also have $h_{[\alpha]}(t_{[\alpha]}) \in H'_\sigma(A_{2n}, R)$.  
    Hence, $h \in H'_\sigma(A_{2n}, R)$, completing the proof. 
\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{cor}\label{cor:E=E' for general case}
    \normalfont
    Let $\Phi$, $R$ and $\theta$ be as in Proposition~\ref{prop:T=H=H' for general case}. In addition, assume that $R$ is semi-local ring. Then 
    \[
        G_\sigma (\Phi, R) = E_\sigma (\Phi, R) = E'_\sigma (\Phi, R).
    \]
\end{cor}

\begin{proof}
    This follows immediately from Proposition~\ref{prop:T=H=H' for general case} and Proposition~5.8 in \cite{SG&DM1}.
\end{proof}



