\section{Triangular and Unitriangular Factorization}

We are now ready to prove Theorem~\ref{thm:triangular decomposition} and Theorem~\ref{thm:unitriangular decomposition}. The main tool is a rank reduction theorem due to O. Tavgen~\cite{OT1} (cf. Theorem~\ref{thm:rank reduction theorem} of the present paper). In the original paper~\cite{OT1}, this theorem is stated for all (twisted) root systems excluding the case of ${}^2 A_{2n}$. However, as observed by A. Smolensky~\cite{AS}, the statement remains valid even for ${}^2 A_{2n}$. For the convenience of the reader, we include a full proof here.

Let $\Phi_\rho$ be a twisted root system of type ${}^2 A_{n} \ (n \geq 2), {}^2 D_n \ (n \geq 4), {}^2 E_6$, or ${}^3 D_4$. Fix a simple system $\Delta_\rho = \{ [\alpha_1], \dots, [\alpha_\ell] \}$ of $\Phi_\rho$. We rearrange the simple roots such that $[\alpha_1], \dots, [\alpha_\ell]$ represent the positions of the roots in the Dynkin diagram from the leftmost to the rightmost end.
For any $[\alpha] \in \Phi_\rho$, write its expansion in terms of the simple roots as
\[
    [\alpha] = \sum_{k=1}^\ell m_k([\alpha]) [\alpha_k],
\]
where $m_k([\alpha])$ denotes the coefficient of $[\alpha_k]$.

For each $i \in \{ 1, \dots, \ell \}$, define the subset $S_i = \{ [\alpha] \in \Phi_\rho \mid m_i([\alpha]) \geq 0 \}$. Then $S_i$ is a closed subset of $\Phi_\rho$ (cf. Section~\ref{subsec:parabolic}).
Let
\[
    \Phi_i := S_i^r = \{ [\alpha] \in \Phi_\rho \mid m_i ([\alpha]) = 0 \}
    \quad \text{and} \quad
    \Sigma_i := S_i^u = \{ [\alpha] \in \Phi_\rho \mid m_i ([\alpha]) > 0 \}.
\]
By Levi decomposition, we have
\[
    E'_\sigma (S_i, R) = E'_\sigma (\Phi_i, R) \ltimes E'_\sigma (\Sigma_i, R).
\]
Note that $\Phi_i$ is a root subsystem of $\Phi_\rho$. Let $\Phi_i^{\pm} = \Phi_i \cap \Phi^{\pm}$, and define
\[
    U_\sigma^{\pm} (\Phi_i, R) = E'_\sigma (\Phi_i^{\pm}, R) 
    \quad \text{and} \quad 
    U^{\pm}_\sigma (\Sigma_i, R) = E'_\sigma (\pm \Sigma_i, R).
\]

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lemma}\label{lemma:Levi decomposition}
    \normalfont
    The group $\langle U_\sigma^{\pm}(\Phi_i, R), U_\sigma^{\pm}(\Sigma_i, R) \rangle$ is a semidirect product of $U_\sigma^{\pm}(\Phi_i, R)$ and $U_\sigma^{\pm}(\Sigma_i, R)$, with $U_\sigma^{\pm}(\Sigma_i, R)$ being a normal subgroup (this applies to all four possible combinations of signs). Moreover, 
    \[
        U_\sigma^{+} (\Phi, R) = U_\sigma^{+} (\Phi_i, R) \ltimes U_\sigma^{+} (\Sigma_i, R)
        \quad \text{and} \quad
        U_\sigma^{-} (\Phi, R) = U_\sigma^{-} (\Phi_i, R) \ltimes U_\sigma^{-} (\Sigma_i, R).
    \]
\end{lemma}

The proof of this lemma is well-known and follows directly from the Chevalley commutator formulas; we omit the details. 
Before we state the rank reduction theorem, we note the following auxiliary lemma, which is also well known.

\begin{lemma}\label{lemma:symmetric generator}
    Let $G$ be a group, and let $X \subset G$ be a symmetric generating set (i.e., $X^{-1} = X$). Suppose $Y \subset G$ is non-empty and satisfies $XY \subset Y$. Then $Y = G$.
\end{lemma}

\begin{proof}
    Since $Y$ is non-empty, choose an element $y_0 \in Y$. We aim to show that every element $g \in G$ lies in $Y$.  
    Consider $g' = g y_0^{-1} \in G$. Since $X$ generates $G$, there exist elements $x_1, \dotsc, x_n \in X$ such that $g' = x_1 \cdots x_n$.
    Thus, $g = g' y_0 = x_1 \cdots x_n y_0$.
    Since $XY \subset Y$ and $X$ is symmetric, it follows that multiplying elements of $Y$ on the left by elements of $X$ keeps the result in $Y$. Applying this inductively, we conclude that $g \in Y$. Therefore, $Y = G$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{thm}\label{thm:rank reduction theorem}
    \normalfont
    Let $\Phi_\rho$ be a twisted root system of type ${}^2 A_{n} \ (n \geq 2), {}^2 D_{n} \ (n \geq 4), {}^2 E_6$, or ${}^3 D_4$.
    Let $R$ be a commutative ring with unity, and suppose there exists an automorphism $\theta: R \to R$ of order $2$ if $\Phi_\rho \not\sim {}^3D_4$, and of order $3$ if $\Phi_\rho \sim {}^3D_4$. 
    \begin{enumerate}[(a)]
        \item Assume that for the subsystems $\Phi_i$ $(i = 1 \text{ and } \ell)$, the elementary twisted Chevalley group $E'_\sigma(\Phi_i, R)$ admits a triangular factorization of the form
        \[
            E'_\sigma(\Phi_i, R) = H'_\sigma(\Phi_i, R) \, \underbrace{U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R)}_{L_a \text{ factors}}
        \]
        of length $L_a$ for some $L_a \in \mathbb{N}$. Then the elementary twisted Chevalley group $E'_\sigma(\Phi, R)$ also admits a triangular factorization
        \[
            E'_\sigma(\Phi, R) = H'_\sigma(\Phi, R) \, \underbrace{U_\sigma^{+}(\Phi, R) \, U_\sigma^{-}(\Phi, R) \dotsm U_\sigma^{\pm}(\Phi, R)}_{L_a \text{ factors}}
        \]
        of the same length $L_a$.

        \item Assume that for the subsystems $\Phi_i$ $(i = 1 \text{ and } \ell)$, the elementary twisted Chevalley group $E'_\sigma(\Phi_i, R)$ admits a unitriangular factorization of the form
        \[
            E'_\sigma(\Phi_i, R) = \underbrace{U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R)}_{L_b \text{ factors}}
        \]
        of length $L_b$ for some $L_b \in \mathbb{N}$. Then the elementary twisted Chevalley group $E'_\sigma(\Phi, R)$ also admits a unitriangular factorization
        \[
            E'_\sigma(\Phi, R) = \underbrace{U_\sigma^{+}(\Phi, R) \, U_\sigma^{-}(\Phi, R) \dotsm U_\sigma^{\pm}(\Phi, R)}_{L_b \text{ factors}}
        \]
        of the same length $L_b$.
    \end{enumerate}
\end{thm}

\begin{proof}
    First, observe that the set
    \[
        X = \{ x_{[\alpha]}(t) \mid \pm [\alpha] \in \Delta_\rho, \, t \in R_{[\alpha]} \}
    \]
    is a symmetric generating set for the group $E'_\sigma(\Phi, R)$. 

    \medskip

    \noindent (a) Define the subsets
    \[
        Y_a = H'_\sigma(\Phi, R) \, \underbrace{U_\sigma^{+}(\Phi, R) \, U_\sigma^{-}(\Phi, R) \dotsm U_\sigma^{\pm}(\Phi, R)}_{L_a \text{ factors}} \subset E'_\sigma(\Phi, R).
    \]
    To prove part~(a), we need to show that $Y_a = E'_\sigma (\Phi, R)$.
    By Lemma~\ref{lemma:symmetric generator}, it suffices to prove that $X Y_a \subset Y_a$.

    Let $x_{[\alpha]}(t) \in X$. Since $\mathrm{rk}(\Phi) \geq 2$, the root $[\alpha]$ belongs to at least one of the subsystems $\Phi_i$ for $i = 1$ or $\ell$. Choose such an index $i$, and let $\Sigma_i$ be defined as above. Then, by Lemma~\ref{lemma:Levi decomposition}, we can write 
    \[
        U_\sigma^{\pm}(\Phi, R) = U_\sigma^{\pm}(\Phi_i, R) \, U_\sigma^{\pm}(\Sigma_i, R).
    \]
    Moreover, $U_{\sigma}^{\pm}(\Phi_i, R)$ normalizes $U_{\sigma}^{\pm}(\Sigma_i, R)$ (for all four possible sign combinations).
    Therefore, we have
    \[
        Y_a = H'_\sigma(\Phi, R) \, U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R) \cdot U_\sigma^{+}(\Sigma_i, R) \dotsm U_\sigma^{\pm}(\Sigma_i, R).
    \]
    Since $[\alpha] \in \Phi_i$, it follows that
    \[
        x_{[\alpha]}(a) \, E'_\sigma(\Phi_i, R) \subset E'_\sigma(\Phi_i, R),
    \]
    for every $a \in R_{[\alpha]}$. By our assumption of part (a),
    \[
        E'_\sigma(\Phi_i, R) = H'_\sigma(\Phi_i, R) \, U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R).
    \]
    Hence,
    \begin{align*}
        & \hspace{-10mm} x_{[\alpha]}(t) \, H'_\sigma(\Phi, R) \, U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R) \\
        &= x_{[\alpha]}(t) \, H'_\sigma(\Phi, R) \, E'_\sigma(\Phi_i, R) \\
        &= H'_\sigma(\Phi, R) \, x_{[\alpha]}(t') \, E'_\sigma(\Phi_i, R) \\
        &\subset H'_\sigma(\Phi, R) \, E'_\sigma(\Phi_i, R) \\
        &= H'_\sigma(\Phi, R) \, U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R).
    \end{align*}
    Therefore, $x_{[\alpha]}(t) Y_a \subset Y_a$.

    \medskip

    \noindent (b) Similarly, define the subsets 
    \[
        Y_b = \underbrace{U_\sigma^{+}(\Phi, R) \, U_\sigma^{-}(\Phi, R) \dotsm U_\sigma^{\pm}(\Phi, R)}_{L_b \text{ factors}} \subset E'_\sigma(\Phi, R).
    \]
    To prove part~$(b)$, we need to show that $Y_b = E'_\sigma (\Phi, R)$.
    By Lemma~\ref{lemma:symmetric generator}, it suffices to prove that $X Y_b \subset Y_b$.

    Let $x_{[\alpha]}(t) \in X$. Since $\mathrm{rk}(\Phi) \geq 2$, the root $[\alpha]$ belongs to at least one of the subsystems $\Phi_i$ for $i = 1$ or $\ell$. Choose such an index $i$, and let $\Sigma_i$ be defined as above. Then, by Lemma~\ref{lemma:Levi decomposition}, we can write 
    \[
        U_\sigma^{\pm}(\Phi, R) = U_\sigma^{\pm}(\Phi_i, R) \, U_\sigma^{\pm}(\Sigma_i, R).
    \]
    Moreover, $U_{\sigma}^{\pm}(\Phi_i, R)$ normalizes $U_{\sigma}^{\pm}(\Sigma_i, R)$ (for all four possible sign combinations).
    Therefore, we have
    \[
        Y_b = U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R) \cdot U_\sigma^{+}(\Sigma_i, R) \, U_\sigma^{-}(\Sigma_i, R) \dotsm U_\sigma^{\pm}(\Sigma_i, R).
    \]
    Again, since $[\alpha] \in \Phi_i$, we have
    \[
        x_{[\alpha]}(t) \, E'_\sigma(\Phi_i, R) \subset E'_\sigma(\Phi_i, R),
    \]
    for every $a \in R_{[\alpha]}$. By the assumption in part (b),
    \[
        E'_\sigma(\Phi_i, R) = U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R).
    \]
    Hence,
    \[
        x_{[\alpha]}(t) \, U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R)
        \subset U_\sigma^{+}(\Phi_i, R) \, U_\sigma^{-}(\Phi_i, R) \dotsm U_\sigma^{\pm}(\Phi_i, R).
    \]
    Therefore, $x_{[\alpha]}(t) Y_b \subset Y_b$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

To complete the proofs of Theorem~\ref{thm:triangular decomposition} and Theorem~\ref{thm:unitriangular decomposition}, it remains to verify the corresponding base cases. These are established by Lemma~\ref{lemma:base case for triangular} and Lemma~\ref{lemma:base case for unitriangular}, respectively. 

\begin{lemma}\label{lemma:base case for triangular}
    \normalfont
    Let $\Phi_\rho$ be a twisted root system of type ${}^2 A_n \ (n \geq 2), {}^2 D_n \ (n \geq 4), {}^2E_6$ or ${}^3 D_4$.
    Let $R$ be a commutative ring with unity, and suppose there exists a ring automorphism $\theta: R \longrightarrow R$ of order $2$ if $\Phi_\rho \not\sim {}^3 D_4$, or of order $3$ if $\Phi_\rho \sim {}^3 D_4$. 
    Fix a class $[\alpha] \in \Phi_\rho$, and let $\Phi_{[\alpha]}$ denote the root subsystem $\{ \pm[\alpha] \}$. Assume the following conditions:
    \begin{enumerate}[(a)]
        \item $R_\theta$ satisfies the $(SR_1)$ condition if $[\alpha] \sim A_1$;
        \item $R$ satisfies the $(SR_1)$ condition if $[\alpha] \sim A_1^2$ or $A_1^3$;
        \item $R$ satisfies the $(SSR_1)$ condition if $[\alpha] \sim A_2$.
    \end{enumerate}
    Then
    \[
        E'_\sigma(\Phi_{[\alpha]}, R) = H'_\sigma(\Phi_{[\alpha]}, R) \, U^{+}_\sigma(\Phi_{[\alpha]}, R) \, U^{-}_\sigma(\Phi_{[\alpha]}, R) \, U^{+}_\sigma(\Phi_{[\alpha]}, R).
    \]
\end{lemma}

\begin{proof}
    If $[\alpha] \sim A_1$, $A_1^2$, or $A_1^3$, the result follows from Lemma~2.1 of \cite{SSV2}. If $[\alpha] \sim A_2$, it follows from Theorem~\ref{thm:SSR_1}.
\end{proof}

\begin{lemma}\label{lemma:base case for unitriangular}
    \normalfont
    Let $\Phi_\rho$ be a twisted root system of type ${}^2 A_n \ (n \geq 2), {}^2 D_n \ (n \geq 4), {}^2E_6$ or ${}^3 D_4$.
    Let $R$ be a commutative ring with unity, and suppose there exists a ring automorphism $\theta: R \longrightarrow R$ of order $2$ if $\Phi_\rho \not\sim {}^3 D_4$, or of order $3$ if $\Phi_\rho \sim {}^3 D_4$. 
    Fix a class $[\alpha] \in \Phi_\rho$, and let $\Phi_{[\alpha]}$ denote the root subsystem $\{ \pm[\alpha] \}$. Assume the following conditions:
    \begin{enumerate}[(a)]
        \item $R_\theta$ satisfies the $(SR_1)$ condition if $[\alpha] \sim A_1$;
        \item $R$ satisfies the $(SR_1)$ condition if $[\alpha] \sim A_1^2$ or $A_1^3$;
        \item $R$ is $\theta$-complete with $\mathcal{C}$-length $k$ and satisfies the $(SSR_1)$ condition if $[\alpha] \sim A_2$.
    \end{enumerate}
    Then
    \[
        E'_\sigma(\Phi_{[\alpha]}, R) = 
        \begin{cases}
            \left( U^{+}_\sigma(\Phi_{[\alpha]}, R) \, U^{-}_\sigma(\Phi_{[\alpha]}, R) \right)^2 & \text{if } [\alpha] \sim A_1, A_1^2, \text{ or } A_1^3, \\
            \left( U^{+}_\sigma(\Phi_{[\alpha]}, R) \, U^{-}_\sigma(\Phi_{[\alpha]}, R) \right)^{k+1} \, U^{+}_\sigma(\Phi_{[\alpha]}, R) & \text{if } [\alpha] \sim A_2.
        \end{cases}
    \]
\end{lemma}

\begin{proof}
    If $[\alpha] \sim A_1$, $A_1^2$, or $A_1^3$, the result follows from Lemma~1 of \cite{SSV1}. If $[\alpha] \sim A_2$, it follows from Corollary~\ref{cor:unitriangular for SU(3,R)}.
\end{proof}




