    \includegraphics[width=1\linewidth]{trainingdiagram.pdf}
    \caption{Illustration of the HiPreNet training process. Each component is trained sequentially and are combined to form the final model.}
    \label{fig:model-diagram}
\end{figure}

While the accuracy of an individual refinement network does still depend on chosen hyperparameters, the overall framework contributes significantly to performance gains by systematically addressing model weaknesses. In contrast, the performance of a single large network highly depends on extensive hyperparameter tuning, of which the optimal configuration can vary dramatically across different tasks, making the training process much less predictable. This decentralization of models also contributes to more manageable memory and computational demands, making the training process more accessible and scalable, especially in resource-constrained environments.

\subsection{Algorithmic Formulation of HiPreNet Training}
Let $f(x):D  \to R$ be a continuous function with a compact domain $D \subset R^n$.  In this paper we are interested in approximating the unknown function $f(x)$ based on a given finite dataset of samples $ \{(x_k, f(x_k))\}^N_{k=1}$. We will train a sequence of neural networks $f^{NN}_i(x)$, $i=1,2,\ldots$, on this dataset to approximate the function and make a prediction for any $x \in D$, where the accuracy of the predictions will increase as $i$ increases.

To assess the accuracy of the neural network approximation, we measure the discrepancy between $f(x)$ and its neural network approximation $f^{NN}(x)$ using the $L^p$ norm over domain $D$:
\begin{equation*}
    \|f(x)-f^{NN}(x)\|_{L^p(D)}
\end{equation*}
We first choose $p=2$, where the squared $L^2$ norm is defined as
\begin{equation*}
    \|f(x)-f^{NN}(x)\|^2_{L^2(D)} = \int_D \left(f(x)-f^{NN}(x)\right)^2 dx
\end{equation*}
As we only have a finite amount of samples of $(x,f(x))$, we approximate this integral by the sample average over the dataset and then take the square root to obtain the root mean squared error (RMSE)
\begin{equation*}
    RMSE = \sqrt{\frac{\sum_{i=1}^N \left(f(x_i) - f^{NN}(x_i)\right)^2}{N}}
\end{equation*}
which converges to the true $L_2$ norm as $N\to\infty$.

We additionally consider the $L^{\infty}$ norm defined as
\begin{equation*}
    \|f(x)-f^{NN}(x)\|_{L^{\infty}(D)} = \underset{x \in D}{\max} \left|f(x) - f^{NN}(x)\right|,
\end{equation*}
which is approximated by the maximum prediction error on the given dataset
\begin{equation*}
    \|f(x)-f^{NN}(x)\|_{L^{\infty}(D)} \approx \underset{1\leq i \leq N}{\max} \left|f(x_i) - f^{NN}(x_i)\right|.
\end{equation*}
This metric allows us to evaluate the worst-case behavior of our trained neural network over the domain $D$.

Given a dataset $ \{(x_k, f(x_k))\}^N_{k=1}$, we will design a neural network based model with high approximation accuracy through an progressive training process based on the residuals. Each neural network will be trained using loss function $L$, which, for regression problems, is typically chosen to be MSE loss:
\begin{equation*}
    L_{MSE} = \frac{\sum_{i=1}^N \left(f(x_i) - f^{NN}(x_i)\right)^2}{N}
\end{equation*}

The process initiates with a neural network, $f_0^{NN}(x)$ to approximate $f(x)$. This initial network is usually of small size and low accuracy. 
Denote the initial approximation error $e_0$ as
\begin{equation*}
 e_0  \ = \    \|f(x) - f_0^{NN}(x)\|_{L^{\infty}} .
\end{equation*}

Next we introduce the residuals $r_0(x)$ and the normalized residuals  $\Hat{r}_0(x)$ as
\begin{eqnarray*}
 r_0(x) & = &  f(x) - f_0^{NN}(x), \ \
   \Hat{r}_0(x) \ = \ \frac{r_0(x)}{e_0}.
\end{eqnarray*}
Now, a new neural network,  $\Hat{r}_0^{NN}(x)$,  can be trained to approximate $\Hat{r}_0(x)$ with approximation error $\epsilon_0$ such that 
\begin{equation*}
    \|\Hat{r}_0(x) - \Hat{r}_0^{NN}(x)\|_\infty = \epsilon_0 < 1
\end{equation*}
This generates a new neural network approximation of function $f$ as
\[ f^{NN}_1(x) \ = \ f^{NN}_0(x)+ e_0\Hat{r}_0^{NN}(x),\]
with an approximation error
\begin{eqnarray*}
   e_1 = \|f(x) - f_1^{NN}(x)\|_\infty & = &   \|f_0^{NN}(x) +r_0(x) -  f^{NN}_0(x)- e_0\Hat{r}_0^{NN}(x)\|_\infty\\
   & = &   \|  e_0 \Hat{r}_0(x) - e_0\Hat{r}_0^{NN}(x)\|_\infty\\
   & = &   \epsilon_0 e_0 \ < \ e_0
\end{eqnarray*}
Thus, the new approximation $ f^{NN}_1(x) $ is more accurate than the initial neural network approximation $ f^{NN}_0(x) $.

Repeating this process we can generate a sequence of increasingly accurate neural network approximations of $f(x)$ as 
\begin{eqnarray*}
  f_{i+1}^{NN}(x) & = &  f^{NN}_i(x) + e_i\Hat{r}_i^{NN}(x), 
\end{eqnarray*}
where $e_i =\| f(x) - f_i^{NN}(x)\|_\infty$ is the previous approximation error and $\Hat{r}_i^{NN}$ is a newly trained neural network that approximates, $\Hat{r}_i$, the normalized residual from the previous step, i.e.,
\begin{eqnarray*}
\Hat{r}_i^{NN}\ \approx \ \Hat{ r}_i(x) & = & \frac{ f(x) - f_i^{NN}(x)}{e_i}.
\end{eqnarray*}

Suppose $\Hat{r}_i^{NN}$ is accurate enough so that 
\begin{equation*}
    \|\Hat{r}_i(x) - \Hat{r}_i^{NN}(x)\|_\infty = \epsilon_{i} < 1.
\end{equation*}
Then, we have
\begin{eqnarray*}
   e_{i+1} = \|f(x) - f_{i+1}^{NN}(x)\|_\infty & = &   \|f^{NN}_i(x)+ e_i\Hat{r}_i(x) -  f^{NN}_i(x)- e_i\Hat{r}_i^{NN}(x)\|_\infty\\
   & = &   \|  e_i \Hat{r}_i(x) - e_i\Hat{r}_i^{NN}(x)\|_\infty\\
   & = &   \epsilon_i e_i \ < \ e_i
\end{eqnarray*}
Thus, the accuracy of the new approximation model $ f^{NN}_{i+1}(x) $ keeps increasing with the number of iterations, provided the first neural network approximates the original function with error $e_0 < 1$ and that each residual neural network approximates the normalized residuals with error $\epsilon_i < 1$. Supposing we have $m$ total refinement networks, this gives a final approximation $f(x)$ as
\begin{equation*}
    f(x) \approx f^{NN}_m(x) = f_0^{NN}(x) + \sum_{i=0}^{m-1}e_i\hat{r}_i^{NN}(x)
\end{equation*}
which is the sum of the outputs of all of the trained model. This is visualized in the diagram given in Figure \ref{fig:evaldiagram}.
\begin{figure}
    \centering
    \includegraphics[width=0.55\linewidth]{evaldiagram.pdf}
    \caption{Illustration of making inferences with the trained model. The same input $x$ is the input to all of the trained networks, where their outputs are summed together to obtain the final prediction $f_m^{NN}(x)$.}
    \label{fig:evaldiagram}
\end{figure}

In practice, several factors can cause the condition of the approximation error of each network to be smaller than one to not be met. Firstly, the residuals may exhibit high-frequency, non-smooth behavior that is hard to approximate with standard architectures, meaning insufficient model capacity in deeper stages may limit residual learning. Additionally, as residuals become increasingly small and oscillatory, numerical precision and optimizer stability may also limit practical convergence. Furthermore, noisy training data or very limited sampling may degrade the estimated residual accuracy, which we do not investigate in this work. In all these cases, the reduction of $L^{\infty}$ norm error may stall or reverse. While we do observe convergence empirically in all of our experiments, formal guarantees remain an open area for future work. The pseudocode of the algorithm is given in Algorithm \ref{alg:res}.

\begin{algorithm}
    \caption{HiPreNet Training Algorithm}\label{alg:res}
    \begin{algorithmic}
        \Require Dataset $(\textbf{x}, \textbf{f}) = \{(x_k, f(x_k)))\}^N_{k=1}$, trained neural network $f_{0}^{NN}$, tolerance $tol$
        \State $error \gets L\left(\textbf{f}, f_{0}^{NN}(\textbf{x})\right)$
        \State $r_0 \gets \textbf{f} - f_{0}^{NN}(\textbf{x})$
        \State $e_0 \gets \max{|r_0|}$ \Comment{estimate of true $e_0$}
        \State $\Hat{r}_0(\textbf{x}) \gets \frac{r_0}{e_0}$
        \State  $\Hat{r}^{NN}_0(\textbf{x}) \gets train(\textbf{x},\Hat{r}_0(\textbf{x}))$
        \State $i \gets 1$
        \While{$error > tol$}
            \State  $f^{NN}_{i}(\textbf{x}) \gets f_{i-1}^{NN} + e_{i} \Hat{r}_{i}^{NN}(\textbf{x})$
            \State $r_{i}(\textbf{x}) \gets \textbf{f} - f^{NN}_{i}(\textbf{x})$
            \State $e_{i} \gets e_{i-1} \cdot \max{|r_{i}(\textbf{x})|}$ \Comment{estimate of true $e_{i}$}
            \State $\Hat{r}_{i}(\textbf{x}) \gets \frac{r_{i}(\textbf{x})}{e_{i}}$
            \State $\Hat{r}^{NN}_{i}(\textbf{x}) \gets train(\textbf{x}, \Hat{r}_{i}(\textbf{x}))$
            \State $error \gets L\left(\textbf{f}, f_{i}^{NN}(\textbf{x})\right)$
            \State $i \gets i + 1$
        \EndWhile
    \end{algorithmic}
\end{algorithm}

\begin{remark}
The total size of the model depends directly on the size of the neural networks used in each training iteration. Additionally, the architecture of the network used in each iteration does not have to remain fixed; the loss function, activation function, and number of layers and neurons used in the first iteration can be completely different from those used for the last iteration. This allows for increased adaptability to what is observed in the residuals, where different architectures may be better suited for different residual patterns.
\end{remark}

\begin{remark}
It is important to note that the true approximation error $e_i$ cannot be obtained in practice, as it is defined using the $L^{\infty}$ norm and we can only train the neural networks on a limited dataset. As such, in our algorithm, we estimate $e_0$ from residuals $r_0$ as
\begin{equation*}
    e_0 \approx \max |r_0|
\end{equation*}
and each $e_i$ from residuals $r_i$ as
\begin{equation*}
    e_i \approx e_{i-1} \cdot \max|r_i(\textbf{x})|
\end{equation*}
\end{remark}

