\title[Non-unique equilibrium measures and freezing phase transition]{Non-unique equilibrium measures
and freezing phase transitions for matrix cocycles for negative $t$}
\maketitle
\begin{abstract}
We consider a one-step matrix cocycle generated by a pair of non-negative parabolic matrices 
and study the equilibrium measures for $t\log \|\A\|$ as $t$ runs over the reals. We show 
that there is a freezing first order phase transition at some parameter value $t_c$ so that for $t<t_{c}$ the 
equilibrium measure is non-unique and supported on the two fixed points, while for $t>t_c$, the 
equilibrium measure is unique, non-atomic and fully supported. The phase transition 
closely resembles the classical Hofbauer example. In particular, our example shows that there may 
be non-unique equilibrium measures for negative $t$ even if the cocycle is strongly irreducible 
and proximal. 
\end{abstract}


\section{Introduction and statement of results}
In this paper, we study the thermodynamic formalism for matrix cocycles. We will show the 
existence of equilibrium measures of the logarithm of the $t$th power of the
norm of a particular matrix cocycle (that satisfies the strong irreducibility
and proximality conditions) for all $t \in \mathbb{R}$.

We say that $(X, T)$ is a topological dynamical system if $X$ is a compact metric 
space and $T$ is a continuous map from $X$ to $X$. We say that 
$\Phi:=(\log \phi_{n})_{n=1}^{\infty}$  is a \emph{sub-additive potential} 
over $(X, T)$ if each $\phi_{n}$ is a continuous positive-valued function on $X$ such that
\[
0<\phi_{n+m}(x) \leq \phi_{n}(x) \phi_{m}(T^{n}(x)) \quad \forall x\in X, m,n \in \N.
\]
Similarly, we call a sequence of continuous functions (potentials) $\Phi=(\log \phi_n)_{n \in \N}$
\emph{super-additive} if $-\Phi=(-\log \phi_n)_{n \in \N}$ is sub-additive.
Given a non-additive potential $\Phi$, an \emph{equilibrium measure} is a $T$-invariant
measure $\mu$ for which $p(\mu)=\sup_{\nu\in \M(T)}p(\nu)$
where $p(\nu)=h_{\nu}(T)+\lim_{n\to\infty}\frac 1n\int \log\phi_n\,d\nu$ and
$\M(T)$ denotes the collection of invariant measures. 

For sub-additive potentials over subshifts,  existence of equilibrium measures follows 
from upper semi-continuity (e.g., \cite{Barreira-eq, Falconer, CFH08}):
both $\mu\mapsto h_{\mu}(T)$ and $\mu\mapsto\lim_{n\to\infty}\frac 1n\int\log\phi_n\,d\mu$ are upper
semi-continuous and the existence of measures maximizing $h_{\mu}(T)+\lim_{n\to \infty}\frac 1n\int\log\phi_n\,d\mu$
follows from weak$^*$-compactness of the space of invariant measures. The super-additive case 
is more delicate because the entropy is upper semi-continuous, while the limit of the integrals is 
lower semi-continuous.




A \emph{matrix cocycle} $\A$ over a topological dynamical system $(X, T)$ is a continuous map 
$\A \colon X \to \glr$. For $n\in \N$ and $x \in X$, we define the product of $\A$ over
the orbit segment of length $n$ as
\[
\A^n(x):= \A(T^{n-1}(x)) \ldots \A(x).\]





A well-studied class of matrix cocycles are \emph{one-step cocycles} which are defined 
as follows. Assume that $\Si=\{1,...,k\}^{\Z}$ is a symbolic space and 
$T:\Si \rightarrow \Si$  is the shift map, i.e. $T(x_{l})_{l\in \Z}=(x_{l+1})_{l\in \Z}$. 
Given a $k$-tuple of matrices $\textbf{A}=(A_{1},\ldots,A_{k})\in \glr^{k}$ , 
we associate with it the locally constant map $\mathcal{A}:\Si \rightarrow \glr$ 
given by $\mathcal{A}(x)=A_{x_{0}}$.
The $k$-tuple of 
matrices $\textbf{A}$ is called the generator of the one-step cocycle $\A$. For any 
length $n$ word $I=i_{0}, \ldots, i_{n-1},$  we denote 
\[
\mathcal{A}_{I}:=A_{i_{n-1}}\ldots A_{i_{0}}.
\]
Therefore, when $\A$ is a one-step cocycle, 
\[ 
\A^n(x)=\A_{x|_{[0,n)}}=A_{x_{n-1}}\ldots A_{x_{0}}.
\] 
In this paper, we focus on the norm potential of matrix cocycles, which provide 
well-known examples of non-additive potentials.
If $\mathcal{A} : \Sigma \to \mathrm{GL}_d(\mathbb{R})$ is a matrix cocycle and $t\in \R$. 
Then, $t\Phi_{\A}:=(t\log \|\A^{n}\|)_{n=1}^{\infty}$ is sub-additive when $t \geq 0$ and 
super-additive when $t<0$. By the results mentioned above, when $t\geq 0$, there is an 
equilibrium measure for $t\Phi_{\A}$.
It is known that if a matrix cocycle $\A$ satisfies the quasi-multiplicativity property, 
then there is a unique equilibrium measure with the Gibbs property for $t\Phi_{\A}$ for all $t\in\R_+$
(see e.g., \cite{feng09, feng11,  park20, MP-uniqueequ}).








In the super-additive case, $t\Phi_{\mathcal{A}}$ for $t < 0$, much less is known. Apart from some 
well-understood cases, such as the strongly conformal, reducible, or dominated 
settings (see e.g., \cite[Proposition 5.8]{Moh22-Lyapunov}), there are
not many general results concerning 
equilibrium measures for $t\Phi_{\mathcal{A}}$ in the super-additive regime. An
exception is the recent result in \cite{Rush}, 
which applies for values of $t$ in a neighborhood of zero. 
%\color{red} In this paper, ....
%\color{black}


Our main results are as follows: 

\begin{thm}\label{t:mainresult1}
Let $\A:\{1,2\}^{\Z} \to \gl2$ be a one-step cocycle generated by 
\[
A_1 = \begin{bmatrix}
1 & 0 \\
1 & 1
\end{bmatrix}, \quad
A_2 = \begin{bmatrix}
1 & 1 \\
0 & 1
\end{bmatrix}.
\] 
Let  $-2.18<t^*<-2.17$ be the solution of $\sum_{i,j=1}^{\infty}(1+ij)^{t^*}=1$. 
Then, for $t<t^*$, the equilibrium measures for $t\Phi_{\A}$ are precisely 
$\delta_{\bar{1}}$ and $\delta_{\bar{2}}$.
\end{thm}

\begin{cor}\label{cor}
There exists a strongly irreducible and proximal one-step cocycle for which the 
equilibrium measure is for $t\Phi_{\A}$ is not unique for some $t<0$.
 \end{cor}
Theorem \ref{t:mainresult1} provides a counterpart to \cite[Theorem 1.1]{Rush}, where 
it is shown that there is a unique equilibrium measure for the potential $t\Phi_{\A}$ for all 
$t$ in some neighborhood of zero. Corollary \ref{cor} should be compared to \cite[Proposition 10.3]{Rush}, 
where an example of a one-step cocycle is given for which there does not exist an 
equilibrium measure satisfying the Gibbs property.
\begin{thm}\label{t:mainresult2}
Let $\A$ be the one-step cocycle given in Theorem \ref{t:mainresult1}. 
Let $-1.83<t'<-1.82$ be the solution of  $\sum_{i=1}^\infty(i+\frac{1}{i})^{t'}=1$. Then, for $t>t'$, 
$\delta_{\bar{1}}$ and $\delta_{\bar{2}}$ are not equilibrium measures for $t\Phi_{\A}$. 
\end{thm}

% \textcolor{red}{1) Since the proofs of T1.4 and C1.5 are very similar, we should probably combine the
% proofs. (2) I think the proof of T1.4 is only correct if $t_c<-2$. }

The following theorem gives a complete picture of the matrix equilibrium measures for $(t\Phi_\A)$
for all $t\in\R$. 

\begin{thm}\label{cor:phasetrans}
    Let $\A$ be the one-step cocycle given above. Then, the family of potentials 
    $(t\Phi_{\A})_{t\in \R}$ has a freezing phase transition: there exists $t_c\in(-2.18,-1.82)$
    such that 
    \begin{itemize}
        \item 
    for $t<t_c$ $P(t\Phi_{\A})=0$ and  the 
    only equilibrium measures are $\delta_{\bar{1}}$ and $\delta_{\bar{2}}$; 
    \item  for $t>t_c$ 
    $P(t\Phi_{\A})>0$ and there exists exactly one ergodic equilibrium measure $\mu_t$. This
    measure is fully supported on $\Sigma$. In particular $\mu_t(\{\bar 1,\bar 2\})=0$.
    % \item for $t=t_c$, $\delta_{\bar{1}}$ and $\delta_{\bar{2}}$ are ergodic equilibrium measures. 
    % \textcolor{lightgray}{Further, if $t_c<-2$, then there exists exactly one additional 
    % ergodic equilibrium measure and
    % there exists $m>0$ such that $P(t\Phi_{\A})\geq m(t-t_c)$ for $t>t_c$. 
    % In particular, $t\mapsto P(t\Phi_{\A})$ is not differentiable at $t_c$.}
\end{itemize}
