\section{preliminaries}
\subsection{Set-up}\label{set up}

For each $n\in\N$, we define $\Sig_{n}$ to be the set of all length $n$ words of $\Si$, 
and we define $\Sig_{\ast}:=\bigcup_{n\in \N}\Sig_{n}$ to be the set of all words. 
% The empty word $\left.i\right|_{0}$ is denoted by $\varnothing$. 
% The length of $i \in \Sig$ is denoted by $|i|$. The longest common prefix of 
% $i, j \in \Sig_{\ast} \cup \Si $ is denoted by $i \wedge j$. 
% The concatenation of two words 
% $i \in \Sig_{\ast} \cup \Si$ and $j \in \Sig $ is denoted by $ji$.   
For $m<0\le n$ and any sequence $a_m,\ldots,a_n$, we denote the \emph{cylinder set}
$\{x\colon x_i=a_i\text{ for $m\le i\le n$}\}$ by $[a_m\ldots a_{-1}.a_0\ldots a_n]$. 

The shift space $\Si$ is compact in the topology
generated by the cylinder sets. Moreover, the cylinder sets are open and closed in
this topology and they generate the Borel $\sigma$-algebra $\B$. 
%Moreover, we denote by $\B_{-}$ the $\sigma$-algebra generated by the past coordinates of a sequence.

 \subsection{Non-additive thermodynamic formalism}
Assume $\left(A_1, \ldots, A_k\right) \in GL(d, \R)^{k}$ generates a one-step cocycle 
$\A:\Sig \to GL(d, \R)$. For $t \in \R$, the {\em topological pressure} of $t\Phi_{\A}$ is defined by
\[ P(t\Phi_{\A}):=\lim_{n \to \infty}\frac{1}{n} \log s_n(t) , \]
where $s_{n}(t):=\sum_{I \in \Sig_n} \|\A_{I}\|^{t}$. Note that the existence 
of the limit follows from the sub-multiplicativity of $\|\cdot\|$.

% We denote by $\M(T)$ the space of all $T$-invariant Borel probability measures
% on $\Si$, and also we denote by $\E(T)$ the space of all ergodic measures
% on $\Si$.

Let $ \mu \in \M(T)$. We define the first Lyapunov exponent of $\A$ with respect
to $\mu$ and $T$ to be
\[\chi_1(\mu, \A):=\lim_{n\to \infty}\frac{1}{n} \int \log \|\A^{n}(x)\| d\mu(x),\]
where $\| \cdot \|$ denotes the operator norm. 
For simplicity, we denote $\chi(\mu, \A):=\chi_1(\mu, \A)$. 


We recall that the \textit{Kolmogorov-Sinai entropy} of $\mu$ with respect to $T$ is
$$
h_{\mu}(T):=\lim _{n \rightarrow \infty} \frac{1}{n} \sum_{I \in \Sigma_n} \mu([\I]) \log \mu([\I]).
$$

Cao, Feng and Huang \cite{CFH08} proved a variational principle formula for the topological 
pressure of sub-additive potentials, while the counterpart for super-additive potentials was 
established by Cao, Pesin and Zhao \cite{CPZ}. 
More recently,  \cite{Mohammadpour-Varandas, Moh23} proved a variational principle for the 
generalized singular value function, which is a generalization of the family of potentials $\Phi_\A$ 
and is neither sub-additive nor super-additive (we refer the reader to 
\cite[Theorem B]{Mohammadpour-Varandas} for more details).
Hence, for any $t \in \R$,
\begin{equation}\label{varitional}
P(t\Phi_{\A})=\sup \bigg\{h_{\mu}(T)+t\chi(\mu, \A): \mu \in \mathcal{M}_{\text{inv}}(T) \bigg\}.
\end{equation}


\medskip
Any invariant measure $\mu \in \mathcal{M}_{\text{inv}}(T)$ achieving the
supremum in \eqref{varitional} is called an \textit{equilibrium measure} of $t\Phi_{\A}$. 
In other words, we say that $\mu_t$ is an {\em equilibrium measure} for $t\Phi_{\A}$ if 
\begin{equation}\label{equilibrium measure}
    P(t\Phi_{\A})= h_{\mu_t}(T)+t\chi(\mu_t, \A).
\end{equation}
%We denote $P(t\Phi):=P(T, t\Phi)$, when there is no confusion about the base map.








We say that a probability measure $\mu_t \in \M(T)$ is a {\em Gibbs measure} for $t\Phi_{\A}$ 
if there exist $C_1, C_2>0$ such that for any $n \in \N$ and $I \in \Sigma_n$
\[
   C_1 \leq \frac{\mu_t\left([I]\right)}{e^{-nP(t\Phi_{\A}) }\|\A_{I}\|^t} \leq C_2.  
\]

\subsection{Induced maps}\label{subsec:induced}
We begin by recalling some definitions and fundamental properties of Kakutani towers.

Let $T$ be an ergodic, invertible, measure-preserving transformation on the probability space 
$(\Omega, \mathcal{B}, \mu)$, and let $D \subset \Omega$ be a measurable set with 
positive measure. For each $x \in D$, define the return time function $r_1(x):=r_D(x) = 
\inf \{ n > 0 : T^n(x) \in D \}$ and $r_k(x):=r_{k-1}(x)+r_1(T^{r_{k-1}(x)}(x))$ for each 
$k \in \mathbb{N}$. Also, for each $k\in \N$ let $D_k = \{ x \in D : r_D(x) = k \}$. 
The collection $\mathcal P_D=\{D_k\colon k\in\N\}$ forms a partition of $D$.
The induced transformation $T_D$ on the space $(D, \mathcal{B}_D, \mu_D)$ is given by 
$T_D(x) = T^{r_D(x)}(x)$. This map preserves the induced measure $\mu_D$, defined by 
$\mu_D(B) = \mu(D \cap B)/\mu(D)$, and the $\sigma$-algebra $\mathcal{B}_D$ 
consists of all sets of the form $B \cap D$, with $B \in \mathcal{B}$.

We will use the following three properties:
\begin{enumerate}
    \item The collection $\mathcal{P} = 
    \{ T^i D_k : k \in \mathbb{N},\ 0 < i < k \}$ forms a partition of $\Omega$;

    \item The measure $\mu_D$ is $T_D$-invariant and ergodic;

    \item The $\sigma$-algebra generated by $\mathcal{P_D}$ under the map $T_D$ 
    coincides with the restriction to $D$ of the $\sigma$-algebra generated by the collection 
    $\mathcal{Q} = \{ D, D^c \}$ under $T$.
\end{enumerate}

Let $\A:\Sigma \to \glr$ be a one-step cocycle and $D\subset \Sigma$ be as above.
We denote $\A_{D}(x)=\A^{r_1(x)}(x)$. We state the following facts that we use a number of times.
\begin{equation}\label{AbramovKnill}
\begin{aligned}
    h_{\mu}(T)&=\mu(D)h_{\mu_D}(T_{D})\text{; and}\\
    \chi(\mu,\A)&=\mu(D)\chi(\mu_D,\A_D).
\end{aligned}
\end{equation}
The first is Abramov's formula, and the second is due to Knill \cite{Knill1991}.

We recall that if $\nu_D$ is a $T_D$-invariant measure on $D$, there is a corresponding
$T$-invariant measure $\nu$ on $\Sigma$, called the \emph{lift} of $\nu_D$ to $\Sigma$. In the case
where $\int r_D\,d\nu_D$ is finite, the measure $\nu$ is a probability measure and $\nu_D$ satisfies
$\nu_D(A)=\nu(A\cap D)/\nu(D)$ as above. In the case where $\int r_D\,d\nu_D$ is infinite, the 
measure $\nu$ is a $\sigma$-finite invariant measure. See \cite[\S1.5]{Aaronson} for more details.


\section{Proofs of main results}
In this section, we fix $ \Sigma = \{1, 2\}^{\mathbb{Z}} $, the full shift $ T: \Sigma \to \Sigma $, 
and the locally constant map $ \A: \Sigma \to \gl2 $ generated by
\[
A_1 = \begin{bmatrix}
1 & 0 \\
1 & 1
\end{bmatrix}, \quad
A_2 = \begin{bmatrix}
1 & 1 \\
0 & 1
\end{bmatrix}.
\]


We need the following lemma to prove our results. This lemma can be seen as a generalization of \cite[Lemma 1.1]{Bow}.
\begin{lem}\label{Bowen's lemma}
    Suppose that $(a_n)$ is a strictly positive sequence
    such that $Q:=\sum_{n=1}^{\infty}a_n<\infty$ and $(p_n)$ is a non-negative sequence
    such that $\sum_{n=1}^{\infty}p_n=1$. Then
    \[
    \sum_{n=1}^{\infty}p_n(-\log p_n+\log a_n)\leq \log Q,
    \]
    where we apply the standard convention $0\log 0=0$. 
    Further, equality holds if and only if $p_n=a_n/Q$ for each $n\in \N.$
\end{lem}
\begin{proof}
Let  $v_n=a_n/Q$ for each $n$.
% We may assume without loss of generality that $p_n>0$ for each $n$ as otherwise we omit terms
% with $p_n=0$ without affecting the sum.
We shall apply the inequality $\log t\leq t-1 $ with equality if and only if $t=1$. We have
$$
\begin{aligned}
\sum_{n=1}^{\infty} p_n(-\log p_n+\log a_n)&=
\sum_{p_n>0} p_n(-\log p_n+\log a_n)\\
&=\sum_{p_n>0}p_n
\left(\log \frac{v_n}{p_n}+\log Q\right)\\
& \leq \sum_{p_n>0}p_{n}\left(\frac{v_n}{p_n}-1+\log Q\right)\\
&=\sum_{p_n>0}v_n+(\log Q-1)\sum_{p_n>0}p_n\\
&\le \sum_{n=1}^\infty v_n+(\log Q-1)=\log Q,
\end{aligned}
$$
where for the last line, we used $\sum_{p_n>0}v_n\le \sum_{n=1}^\infty v_n=1$ with equality if and
only if $p_n>0$ for all $n$, as well as the equality $\sum_{p_n>0}p_n=\sum_{n=1}^\infty p_n=1$. 
The conditions for equality in the overall inequality are that
$p_n>0$ for all $n$ and $\frac {v_n}{p_n}=1$ for all $n$ such that $p_n>0$. That is,
the inequality is strict unless $p_n=v_n$ for all $n$.
\end{proof}
\begin{lem}\label{lower bound}
Let $I = \bigl(1^{i_1} 2^{j_1} 1^{i_2}2^{j_2} \dots 1^{i_{k}} 2^{j_k}\bigr), $ where $i_\ell, j_\ell\in \mathbb{N}$. Then,
\[
\|\mathcal{A}_I\| \;\ge\; (1+i_1j_1)\ldots (1+i_kj_k).
\]
\end{lem}
\begin{proof}
Note that
\[
A_1^{i} = \begin{bmatrix}1 & 0 \\ i & 1\end{bmatrix}, \qquad
A_2^{j} = \begin{bmatrix}1 & j \\ 0 & 1\end{bmatrix}.
\]
Therefore, $B_k:=A_2^{j_k}A_1^{i_k}=\begin{bmatrix}1+i_kj_k & j_k \\ i_k & 1\end{bmatrix}$.

One may show by induction that $(B_k\ldots B_1)_{11}\geq (1+i_1j_1)\ldots (1+i_kj_k)$.
Hence, $\|B_k\ldots B_1\| \geq (1+i_1j_1)\ldots (1+i_kj_k)$. 
\end{proof}



\begin{proof}[Proof of Theorem \ref{t:mainresult1}]
We will show that $\delta_{\bar{1}}$ and $\delta_{\bar{2}}$ are the only 
ergodic equilibrium measures for $t\Phi_{\A}$ when $t<t_{\ast}$. 
We recall that $t_*<0$ so $t<0$ also. 
Note that $h_{\mu}(T)+t\chi(\mu, \A)=0$ when $\mu=\delta_{\bar{1}}, \delta_{\bar{2}}$. So,
\begin{equation}\label{proof of the lower bound for pressure}
  P(t\Phi_{\A})\geq 0.
\end{equation}
By the definition of equilibrium measures, it suffices to show that 
if $\mu\ne\delta_{\bar 1},\delta_{\bar 2}$ is an ergodic 
measure, then $h_\mu(T)+t\chi(\mu, \A)<0$.
Since $\mu\ne\delta_{\bar 1},\delta_{\bar 2}$, $\mu([1])$ and $\mu([2])$ are both positive. 
By ergodicity, this ensures that $\mu([21])>0$
(as if not $[1]$ would be a $T$-invariant set of measure strictly between 0 and 1).

Let $D=[2.1]$ and $X_{i,j}=[2.1^i2^j1]$ for $i,j\in\N$.
% =\Bigg\{x \in X: \quad \begin{aligned}
% & \\
%     &x_0, \ldots,x_{i-1}=1,\\
%     &x_i,\ldots x_{i+j-1}=2,\\
%     &x_{i+j}=1
% \end{aligned}    \Bigg\}.$  
By the Poincar\'e Recurrence Theorem, $\mathcal P_D=\{X_{i,j}:i,j\in\N\}$ forms a partition of $D$
up to a set of measure 0.
%We denote the return time function by $n_{D}$: $n_D(x)=\min\{n>0\colon T^nx\in D\}$.
We recall that $r_D$ denotes the return time to $D$
and the induced measure on $D$ is denoted by $\mu_D$. 
Observe that $\mathcal P_D$ is a generating partition for $T_D$: if the two-sided $T_D$-orbits 
of two points in $D$ lie in the same partition elements for all iterates, then the two points
agree. 
Since $\mathcal P_D$ is a generating partition for $T_D$,
$\frac 1n H_{\mu_D}(\bigvee_{j=0}^{n-1}T_D^{-j}\mathcal P_D)\to h_{\mu_D}(T_D)$,
and
\begin{equation}\label{entropy}
    h_{\mu_D}(T_D)\le H_{\mu_D}(\mathcal P_D).
\end{equation}
By \eqref{AbramovKnill},
\begin{equation}\label{relation between LE and entropies}
    h_{\mu_D}(T_D)+t\chi(\mu_D, \mathcal A_D)=\frac 1{\mu(D)}(h_\mu(T)+t\chi(\mu, \mathcal A)).
\end{equation}
% \begin{equation}
%     \frac{1}{k}\left(H_{\mu_{D}}\left(\bigvee_{n=0}^{k-1}T_{D}^{-n}(\mathcal{P}_D)\right)
%     -t\log\|\A^{n_k(x)}(x)\|\right)\to \frac{1}{\mu(D)}\left(h_{\mu}(T)-t\chi(\mu, \A)\right).
% \end{equation}
% Note that 
% \begin{equation}\label{entropy}
% %    \frac{1}{k}H_{\mu_{D}}\left(\bigvee_{n=0}^{k-1}T_{D}^{-n}(\mathcal{P}_D)\right)\leq H_{\mu_{D}}(\mathcal{P}_D)
% h_{\mu_{D}}(T_D)\leq H_{\mu_{D}}(\mathcal{P}_D)
% \end{equation}
We now find a lower bound for $\chi(\mathcal A_D,\mu_D)$ (and hence an upper bound for $t\chi(\mathcal A_D,\mu_D)$).
We have for $\mu_D$-a.e. $x$,
\begin{equation}\label{eq:chidef}
\begin{aligned}
    \chi(\mu_D, \mathcal A_D)&=\lim_{k\to\infty}\frac 1k\log \|\mathcal A_D^k(x)\|\\
    &=\lim_{k\to\infty}\frac 1k\log \|\mathcal A^{r_k(x)}(x)\|.
\end{aligned}
\end{equation}
By Lemma \ref{lower bound},
\begin{equation}\label{LE}
\begin{aligned}
    \log\|\A^{r_k(x)}(x)\|&\geq \log \left((i_0j_0+1)\ldots (i_{k-1}j_{k-1}+1)\right)\\
    &=\sum_{\ell=0}^{k-1} \log(1+i_\ell j_\ell),
\end{aligned}
\end{equation}
where the sequence $(i_\ell,j_\ell)$ is defined to be the sequence of
partition elements that the $T_D$-orbit of $x$ follows:
$T_D^{\ell}(x)\in X_{i_\ell,j_\ell}$.
We define $f(x)=\log(1+ij)$ if $x\in X_{i,j}$ and rewrite the inequality as
\begin{equation}\label{eq:flowerbd}
\log\|\A^{r_k(x)}(x)\|\geq \sum_{\ell=0}^{k-1}f(T_D^\ell x).
\end{equation}
By Kac's lemma, $\sum_{i,j=1}^\infty (i+j)\mu_D(X_{i,j})=1/\mu(D)<\infty$.
Since $\log(1+ij)\le \log\big((1+i)(1+j)\big)=\log(1+i)+\log(1+j)\le i+j$,
we see that $\sum_{i,j=1}^\infty \mu(X_{i,j})\log(1+ij)<\infty$; that is
$\int f\,d\mu_D<\infty$.
Hence, we may apply the Birkhoff ergodic theorem. For $\mu_D$-a.e. $x$,
\begin{equation}\label{Birkhoff}
  \frac1{k}  \sum_{l=0}^{k-1}f(T^lx)\to \int f\,d\mu_D=\sum_{i,j=1}^{\infty}\mu_{D}(X_{i,j})\log(1+ij).
\end{equation}
Combining \eqref{eq:chidef}, \eqref{eq:flowerbd} and \eqref{Birkhoff}, we obtain
\begin{equation}\label{eq:chibound}
    \chi(\mu_D, \mathcal A_D)\ge \sum_{i,j=1}^\infty\mu_D(X_{i,j})\log(1+ij).
\end{equation}
Combining \eqref{entropy} and \eqref{eq:chibound} (and recalling that $t<0$),
\begin{equation}\label{last eq}
\begin{aligned}
h_{\mu_D}(T_D)+t\chi(\mu_D, \mathcal A_D)&\le H(\mathcal P_D)+t\sum_{i,j=1}^\infty\mu_D(X_{i,j})\log(1+ij)\\
&=\sum_{i,j=1}^\infty p_{i,j}\big(-\log p_{i,j}+t\log(1+ij)\big),
\end{aligned}
\end{equation}
% \begin{equation}
%     \lim_{k\to \infty}\frac{1}{k}\left(H_{\mu_{D}}
%     \left(\bigvee_{n=0}^{k-1}T_{D}^{-n}(\mathcal{P}_D)\right)-t\log\|\A^{n_k(x)}(x)\|\right)
%     \leq \sum_{i,j=1}^{\infty}-p_{i,j}\log p_{i,j}-t(p_{i,j}\log(1+ij)),
% \end{equation}
where $p_{i,j}=\mu_{D}(X_{i,j})$.

By Lemma \ref{Bowen's lemma}, 
\[
\begin{aligned}
\sum_{i,j=1}^{\infty}p_{i,j}\big(-\log p_{i,j}+t\log(1+ij)\big)&
\leq \log\left(\sum_{i,j=1}^\infty (1+ij)^t\right)\\
&<0
\end{aligned}
\]
for each $t<t_{\ast}$. Therefore, by \eqref{relation between LE and entropies} and \eqref{last eq},
\begin{equation}\label{Proof of the upper bound for the pressure}
    h_{\mu}(T)+t\chi(\mu, \A)< 0
\end{equation}
for any ergodic measure $\mu$ other than $\delta_{\bar{1}}$ and $\delta_{\bar{2}}$, 
and any $t<t_{\ast}$. Hence, by \eqref{proof of the lower bound for pressure} and
\eqref{Proof of the upper bound for the pressure}, $P(t\Phi_{\A})=0$ for any 
$t<t_{\ast}$. This implies that $\delta_{\bar{1}}$ and $\delta_{\bar{2}}$ are the only
equilibrium measures for $t\Phi_{\A}$ when $t<t_{\ast}.$
\end{proof}
\begin{cor}\label{positive LE}
For any ergodic measure $\mu$ with $\mu(D)>0$, $\chi(\mu, \A)>0$.
\end{cor}
\begin{proof}
    The inequality \eqref{eq:chibound} in the proof of Theorem \ref{t:mainresult1} 
    holds for any ergodic measure where $\mu(D)>0$. In particular, 
    $\chi(\mu_D, \A_D)\geq \log 2$. Then the proof follows from \eqref{AbramovKnill}.
\end{proof}
