\begin{proof}[Proof of Theorem \ref{t:mainresult2}]
Let $t>t'$.  We show that $\delta_{\bar{1}}$ and $\delta_{\bar{2}}$ are not equilibrium measures 
for $t\Phi_{\A}$. 
We recall that $h_{\nu}(T)+t\chi(\nu, \A)=0$ for $\nu=\delta_{\bar1},\delta_{\bar 2}$.
If $t\ge 0$, then if $\mu$ is any ergodic measure with positive entropy,
we see $h_\mu(T)+t\chi(\mu,\A)>0$, showing that $\delta_{\bar 1}$ and $\delta_{\bar 2}$ 
are not equilibrium measures. Hence it suffices to consider the case $t'<t<0$.
We shall show that there is an invariant measure $\mu$ such that 
$$
h_{\mu}(T)+t\chi(\mu, \A)>0.
$$
By assumption,  $\sum_{n=1}^{\infty} \big(n + \frac{1}{n}\big)^{t}>1$. 
Let $N\in \N$ be such that $Q:=\sum_{k=1}^{N}\big(n + \frac{1}{n}\big)^{t}>1$. 
Let $p_k:=\frac 1Q\big(k + \frac{1}{k}\big)^{t}$ for $k=1, \ldots, N$. 
We build an invariant measure $\mu$ on $\Sigma$ consisting of concatenations of 
alternating 1-blocks and 2-blocks, where each block has length $k$ with probability 
$p_k$ independent of all other block lengths. 

We now give a more formal description of $\mu$ as the push-forward
of a suspension dynamical system. Let $Y=\{1,2,\ldots,N\}^\Z\times \{1,2\}$
and define a map $S$ on $Y$ by $S(y,m)=(T(y),3-m)$, the shift map in the first coordinate
and the flip between 1 and 2 in the second coordinate. We then define an ergodic invariant
measure $\nu$ on $Y$ by taking the product of the Bernoulli measure in the first coordinate
with weights $p_1,\ldots,p_N$; and the $(\frac 12,\frac 12)$ measure in the second coordinate. 
We build a suspension $\bar Y$ of $Y$ with tower height given by the zeroth
coordinate of $y$: let $\bar Y=\{(y,m,k)\colon 0\le k<y_0\}$ with the invertible
suspension map $\bar S$ given by
$$
\bar S(y,m,k)=\begin{cases}
    (y,m,k+1)&\text{if $k<y_0-1$;}\\
    (S(y,m),0)&\text{otherwise.}
\end{cases}
$$
This map preserves the lift $\bar\nu$ of $\nu$ defined by
$$
\bar\nu(C\times \{k\})=\frac{\nu(C)}W,
$$
for any $C\subseteq Y$ and $k$ such that $y_0>k$ for all $y\in C$.
Here, $W$ is the normalizing constant, $W=\sum_{k=1}^N kp_k$. 
Since $\nu$ is ergodic, its suspension $\bar\nu$ is also ergodic. 
Finally, we define a shift-commuting map $F$ from $\bar Y$ to 
$\{1,2\}^\Z$ and define the measure $\mu$ as the push-forward of $\bar\nu$ under $F$.

Let $f(y,m,k)=m$ and let $F(\bar y)=(f(\bar S^n(\bar y)))_{n\in\Z}$,
the sequence of $f$ values along the orbit. As described above informally,
the sequence obtained alternates between blocks of 1's and blocks of 2's
with the lengths of the blocks given by the sequence $y$. We let $\mu=F_*(\nu)$. 
The push-forward operation preserves ergodicity so $\mu$ is an ergodic invariant measure
on $\{1,2\}^\Z$. 

Let $D=[1.2]\cup [2.1]$. We consider 
the partition $\mathcal{P}_D$ of $D$ given by $\{D_k\}$, where $D_k:=\{x\in \Sigma: r_{D}(x)=k\}$. 
We may check that $F^{-1}(D)=Y\times\{0\}\times\{1,2\}$, so that inducing on $D$
amounts to undoing the suspension step, the induced map $T_D$ corresponds to the 
map $S$ and $\mu_D$ corresponds to $\bar\nu$. From the description of $\nu$, we see that the return times
to $D$ take values in $\{1,2,\ldots N\}$ with probabilities $p_1,\ldots,p_N$, independent of
all other return times.
As in the previous proof, $\mathcal P_D$ is a generating partition for $T_D$.
We let $\mathcal B_-$ denote the $\sigma$-algebra $\bigvee_{n=1}^\infty T_D^{-n}\mathcal P_D$.
Since $\mathcal P_D$ is generating, we have
$$
\begin{aligned}
h_{\mu_D}(T_D)&=
\lim_{n\to\infty}\frac 1n H_{\mu_D}\left(\bigvee_{j=0}^{n-1}T_D^{-j}\mathcal P_D\right)\\
&=H_{\mu_D}(\mathcal P_D|\mathcal B_-)
\end{aligned}
$$
%
%&=H(\mathcal P_D|\mathcal B_-).
%\end{align*}

By construction, $\mu_{D}(D_k|\B_{-})=p_k$ since each return time is independent 
of all of the others. Hence,
\begin{equation}\label{entropy1}
 h_{\mu_{D}}(T_{D})=-\sum_{k=1}^Np_{k}\log p_{k}.
\end{equation}

We now give an upper bound for $\chi(\mu, \A)$ (leading to a lower bound for $t\chi(\mu, \A)$).
The argument is quite similar to the one given in the proof of Theorem \ref{t:mainresult1}.
By \eqref{AbramovKnill}, $\chi(\mu, \A)=\mu(D)\chi(\mu_D, \A_D)$. We estimate $\chi(\mu_D, \A_D)$. 
Note that by construction $\A_D(x)=\A^{r_D(x)}(x)$ is either $A_1^{r_D(x)}$ or $A_2^{r_D(x)}$
according to whether the block starting at $x_0$ is a block of 1's or 2's. 
By explicit calculation, we see $\|A_1^n\|=\|A_2^n\|= \frac{n^2 + 2 + n\sqrt{n^2 + 4}}{2}$. 
Since $\sqrt{n^2 +4}\leq n+\frac{2}{n}$, we obtain $\|A_1^n\|=\|A_2^n\|\leq n+\frac{1}{n}$.

Accordingly, $\|\A_D(x)\|\le r_D(x)+1/r_D(x)$. Therefore, by sub-multiplicativity, 
\begin{equation}\label{eq:submult}
\|\A_D^k(x)\|\le \prod_{j=0}^{k-1}\left(\ell_j+\frac 1{\ell_j}\right),
\end{equation}
where $\ell_j$ is the length of the $j$th block, $\ell_j=r_D(T^{r_j(x)}(x))$.
Defining $f(x)=\log(r_D(x)+1/r_D(x))$, this can be expressed as
$$
\log\|\A_D^k(x)\|\le \sum_{j=0}^{k-1}f(T_D^j(x)).
$$
Dividing by $k$, and taking the limit as $k\to\infty$, the left side converges to $\chi(\mu_D, \A_D)$
and the right side converges to $\int f\,d\mu_D$ (where we are using 
ergodicity of $\mu_D$ and the boundedness of $f$).

Hence,
\begin{equation}\label{LE1}
\chi(\mu_D, \A_D)\le \int f\,d\mu_D=\sum_{k=1}^N p_k\log \left(k+\frac 1k\right).
\end{equation}


% \[
%     \log\|\A^{n_k([I])}_I\|\leq \log(\|\A^{k_1}\|\|\B^{k_2}\|\ldots \|\A^{k_n}\|)
% \]
% where $I=(1^{k_1}2^{k_2}\ldots 1^{k_{n}})$ or $I=(2^{k_1}1^{k_2}\ldots 2^{k_{n}})$. Hence
% \begin{equation}\label{LE1}
% \chi(\mu_{D}, \mathcal{A}_D) \le \sum_{k=1}^{N} p_{k} \log \left(k + \frac{1}{k}\right).
% \end{equation}

Therefore, by  \eqref{entropy1} and \eqref{LE1}, (recalling that $t<0$) we have
\begin{equation}
\begin{aligned}
   h_{\mu_{D}}(T_D)+t\chi(\mu_{D},\A_D)&\geq \sum_{k=1}^{N}p_{k}(-\log p_{k}+\log u_k)\\
   &=\sum_{k=1}^Np_k(-\log p_k+\log (Qp_k))\\
   &=\log Q>0,
\end{aligned}
\end{equation}
where $u_{k}=(k+\frac{1}{k})^{t}$. 
By \eqref{relation between LE and entropies},  $h_{\mu}(T)+t\chi(\mu,\A)\geq \mu(D)\log Q>0$.
\end{proof}

