In preparation for the proof of Theorem \ref{cor:phasetrans}, we prove an
almost additivity result. 

\begin{lem}[Almost additivity]\label{Almost additivity}
Let $\C:=\bigg\{\begin{bmatrix}1+mn & n \\ m & 1\end{bmatrix} : 
m,n \in \N \bigg\}$. For each $n, m \in \N$, and any sequence $B_1,\ldots,B_{n+m}$ in $\C$,
we have 
\[
\||B_{m+n} \ldots \B_{m+1}\|\|B_{m} \ldots \B_{1}\|
\geq
\|B_{m+n}\ldots B_1\| 
\geq
\tfrac{1}{2\sqrt{2}}\|B_{m+n} \ldots \B_{m+1}\| \|B_{m}\ldots B_1\|.
\]
\end{lem}

\begin{proof}
We prove the lemma in a series of claims. 
Let $P=\{(x, y): x\geq 0, y \geq 0\}$. Then we first claim 
\begin{equation}\label{eq:smallcone}
B_n\ldots B_1 P \subset \{(x,y): x\geq y \geq 0\}\text{ for any $B_1,\ldots B_n \in\C$}.
\end{equation}
To see this, since $B_1,\ldots,B_{n-1}$ are non-negative $B_{n-1}\ldots B_1P\subseteq P$. 
Then it is easy to check that $B_nP\subset\{(x,y)\colon x\geq y\ge 0\}$.

Next we claim 
\begin{equation}\label{eq:dom}
    B_n \ldots B_1 \e_1 \succeq B_n \ldots B_1 \e_2\text{ for any finite sequence 
of matrices in $\C$},
\end{equation}
where $(a, b)\succeq (c,d)$ means that $a\geq c$ and $b\geq d$.
To see this, since $B_1\e_1=(m_1n_1+1)\e_1+n_1\e_2$ and $B_1\e_2=m_1\e_1+1\e_2$, we see $B_1\e_1\succeq B_1\e_2$. 
If a matrix $B$ has non-negative entries, one can check $B\mathbf x\succeq B\mathbf y$ whenever
$\mathbf x\succeq \mathbf y$.

We next claim
\begin{equation}\label{eq:e1bound}
\|B_n \ldots B_1\e_1\|\ge \frac 1{\sqrt 2}\|B_n \ldots B_1\|
\text{ for any finite sequence of matrices in $\C$}.
\end{equation}

Since $(B_n\ldots B_1)^T(B_n\ldots B_1)$ has positive entries, by the Perron-Frobenius theorem,
the dominant eigenvector has positive entries. That is, there exists $\mathbf v$ with 
positive entries such that $\|\mathbf v\|=1$ and $\|B_n\ldots B_1\mathbf v\|=\|B_n\ldots B_1\|$.
Let $\mathbf v=\alpha\e_1+\beta\e_2$. Then by \eqref{eq:dom},
$B_n\ldots B_1((\alpha+\beta)\e_1)\succeq
B_n\ldots B_1\mathbf v$, so that taking norms, $(\alpha+\beta)\|B_n\ldots B_1\e_1\|
\ge \|B_n\ldots B_1\|$. Since $\|v\|=1$, we see $\alpha+\beta\le \sqrt 2$, so that
$\|B_n\ldots B_1\e_1\|\ge \frac 1{\sqrt 2}\|B_n\ldots B_1\|$ as required.    

We now complete the proof.
   Let $B_m\ldots B_1\e_1=\alpha e_1+\beta e_2$. By \eqref{eq:smallcone}, $\alpha\ge \beta$.
    Hence 
$$
\begin{aligned}
\alpha&=\|\alpha e_1\|\ge \tfrac 1{\sqrt 2}\|B_m\ldots B_1\e_1\|\\
&\ge\tfrac 12\|B_m\ldots B_1\|,
\end{aligned}
$$
where we used \eqref{eq:e1bound}. 
We then have $B_{m+n}\ldots B_1\e_1\succeq \alpha B_{m+n}\ldots B_{m+1}\e_1$,
so that 
$$
\begin{aligned}
\|B_{m+n}\ldots B_1\|&\ge \|B_{m+n}\ldots B_1\e_1\|\\
&\ge \alpha\|B_{m+n}\ldots B_{m+1}\e_1\|\\
&\ge \tfrac{\alpha}{\sqrt 2}\|B_{m+n}\ldots B_{m+1}\|.
\end{aligned}
$$
Substituting the earlier inequality for $\alpha$ establishes 
$$
\|B_{m+n}\ldots B_1\|\ge 
\tfrac{1}{2\sqrt{2}}\|B_{m+n} \ldots B_{m+1}\| \|B_{m}\ldots B_1\|.
$$ 
The other inequality follows from sub-multiplicativity. 
\end{proof}

The proof of Theorem \ref{cor:phasetrans} relies on the following theorem of
Iommi and Yayama.

\begin{thm}[{\cite[Proposition 3.1 and Theorem 4.1]{IommiYayama2012}}]\label{thm:IY}
Let $(\Omega,T)$ be a topologically mixing countable state Markov shift with the BIP
(big images and preimages)
property. Let $\Psi = (\log \psi_n)_{n\in\N}$ be an almost-additive 
Bowen sequence defined on $\Sigma$. Then we have
\begin{enumerate}
    \item $P(\Psi)=\sup \left\{
    P(\Psi_Y):\text{ $Y$ is a Markov subshift of $\Omega$ with finitely many symbols}\right\}$;
    \label{it:VP}
    \item If $\sum_a\sup \psi_1|_{[a]} < \infty$
then there is a mixing Gibbs measure $\mu$ for $\Psi$. Moreover, If
$h_{\mu}(T) < \infty$, then $\mu$ is the unique equilibrium measure for $\Psi$.
\label{it:Gibbs}
\end{enumerate}

\end{thm}

In our context, $\Omega$ will be a countable full shift (which automatically has the BIP property). 
In this case, in the first statement, we can consider systems $Y$ that are full subshifts
on finitely many symbols. 
For the potentials we consider, $\psi_n(\omega)$ only depends on $\omega_0,\ldots\omega_{n-1}$
which ensures that the Bowen property is satisied. So to apply Theorem \ref{thm:IY}, it suffices
to check the almost additivity and summability conditions in the theorem.

\begin{proof}[Proof of Theorem \ref{cor:phasetrans}]
Since $\|\A^n(x)\|>1$ for each $x$ and each $n\in\N$, one can see that 
$t\mapsto P(t\Phi_\A)$ is non-decreasing in $t$. Additionally, it follows that
$\chi(\mu, \A)\ge 0$ for any ergodic measure $\mu$ on $\{1,2\}^\Z$. 
% Corollary \ref{positive LE}
% shows that $\chi(\mu, \A)>0$ for any ergodic measure other than $\delta_{\bar 1}$ and $\delta_{\bar 2}$. 
We already established the existence of $-2.18<t_*<-2.17<-1.83<t'<-1.82$ so that for $t<t_*$, $P(t\Phi_\A)=0$, while for 
$t>t'$, $P(t\Phi_\A)>0$. \cite[Lemma 2.2]{feng09} shows that $t\mapsto P(t\Phi_\A)$ is 
convex (and hence continuous). Accordingly,
let $t_c=\max\{t\colon P(t\Phi_\A)=0\}$, so that $t_c\in (-2.18,-1.82)$. For $t>t_c$, $P(t\Phi_\A)>0$
and $\delta_{\bar 1}$ and $\delta_{\bar 2}$ are not equilibrium measures for $t\Phi_\A$. 
Meanwhile if $t<t_c$ and $\mu$ is an ergodic equilibrium measure for $t\Phi_\A$, 
then 
$$
\begin{aligned}
0&=h_{\mu}(T)+t\chi(\mu, \A)\\
&\le h_{\mu}(T)+t_c\chi(\mu, \A)\\
&\le P(t_c\A)=0,
\end{aligned}
$$
so that $\chi(\mu, \A)=0$. 
It follows from Corollary \ref{positive LE}
that $\mu$ is either $\delta_{\bar 1}$ or $\delta_{\bar 2}$ as claimed.

