\end{aligned}
$$
%\textcolor{red}{Fix notation: $n_k$ has 2 meanings! Maybe use $r_D$ and $r_k$ for return times?}
We introduce a simpler system related to $(D,T_D)$. Let $\Omega=(\N^2)^\Z$ and define the one-step 
matrix cocycle $\A_\Omega(\omega)$ by
$$
\A_\Omega(\omega)=B_{m,n}:=\begin{bmatrix}
    mn&n\\m&1
\end{bmatrix}\text{ if $\omega_0\in[(m,n)]$}
$$
over the shift map  $(\Omega, T_{\Omega})$.
This has the property that 
$$
\A_\Omega^k(\omega)=\A_D^k(x)\text{\quad if $T_D^jx\in X_{m_j,n_j}$ for $j=0,\ldots,k-1$.}
$$
We define a potential on $\Omega$ by $\Psi_{\Omega,s}=(\log\psi_{\Omega,s,k})_{k\in\N}$, with
$$
\psi_{\Omega,s,k}(\omega)=e^{-(M_k+N_k)P}\|\A_\Omega^k(\omega)\|^{s+t},
$$
where $M_k=m_0+\ldots+m_{k-1}$ and $N_k=n_0+\ldots+n_{k-1}$. 
%By construction, we have $P(\Psi_{\Omega,s})=P(\Psi_{D,s})$.
We make the following claims about $\Psi_{\Omega,s}$:
\begin{enumerate}
    \item $\Psi_{\Omega,s}$ is almost additive for each $s\in\R$;\label{claim:almost additive}
    \item $\sum_{m,n=1}^\infty \sup_{\omega\in[(m,n)]}\psi_{\Omega,s,1}(\omega)<\infty$ for all
    $s\in\R$; \label{claim:summability}
    \item $P(\Psi_{\Omega,s})<\infty$ for all $s\in\R$;\label{claim:finite pressure}
    \item $s\mapsto P(\Psi_{\Omega,s})$ is convex;\label{claim:convex}
    \item $P(\Psi_{\Omega,s})>0$ if and only if $P(\Psi_s)>0$;\label{claim:T correspondence}
    \item $P(\Psi_{\Omega,0})=0$.\label{claim:zero pressure}
\end{enumerate}

Claim \eqref{claim:almost additive} follows from Lemma \ref{Almost additivity}.

For claim \eqref{claim:summability}, notice that $\psi_{\Omega,s,1}(\omega)=
e^{-(n+m)P}\|B_{m,n}\|^{s+t}$ for all $\omega\in[(m,n)]$. A simple calculation shows 
\begin{equation*}
mn\leq \left\|\begin{bmatrix}1+mn & n \\ m & 1\end{bmatrix}\right\| \leq 4mn
\end{equation*}
for each $m,n \in \N$. 
Hence to establish \eqref{claim:summability}, it suffices to check that 
$$
\sum_{m,n=1}^\infty e^{-(n+m)P}(nm)^{s+t}<\infty.
$$
Since this quantity is the square of $\sum_{n=1}^\infty e^{-nP}n^{s+t}$ and $P>0$,
the claim holds. 

The deduction of \eqref{claim:finite pressure} from claims \eqref{claim:almost additive} and
\eqref{claim:summability} appears in \cite{IommiYayama2012}.
We give a self-contained proof. We have 
$$
\begin{aligned}
P(\Psi_{\Omega,s})
&=\lim_{k\to\infty}
\frac 1k\log\sum_{\mathbf m\in(\N^2)^k}e^{-(M_k+N_k)P}\|B_{m_{k-1},n_{k-1}}\cdots B_{m_0,n_0}\|^{s+t}\\
&\le\lim_{k\to\infty}
\frac 1k\log\sum_{\mathbf m\in(\N^2)^k}e^{-(M_k+N_k)P}\|B_{m_{k-1},n_{k-1}}\cdots B_{m_0,n_0}\|^{|s+t|}\\
&\le \lim_{k\to\infty}
\frac 1k\log\sum_{\mathbf m\in(\N^2)^k}\prod_{j=0}^{k-1}
e^{-(m_j+n_j)P}\|B_{m_j,n_j}\|^{|s+t|}\\
&=\lim_{k\to\infty}\frac 1k \log\left(\sum_{(m,n)\in \N^2}e^{-(m+n)P}\|B_{m,n}\|^{|s+t|}\right)^k\\
&=\log \sum_{(m,n)\in \N^2}e^{-(m+n)P}\|B_{m,n}\|^{|s+t|}\\
&\le\log\sum_{m,n=1}^\infty e^{-(m+n)P}\left((m+\tfrac1m)(n+\tfrac 1n)\right)^{|s+t|}\\
&=2\log\sum_{n=1}^\infty e^{-nP}(n+\tfrac 1n)^{|s+t|}<\infty.
\end{aligned}
$$
In the sixth line, we used \eqref{eq:submult}.

For claim \eqref{claim:convex}, convexity of $s\mapsto P(\Psi_{\Omega,s})$
follows from a standard argument (e.g., see \cite[Section 3]{PU}) using 
H\"older's inequality and the
fact that $\psi_{\Omega,\alpha s+(1-\alpha)s',k}=\psi_{\Omega,s,k}^\alpha\psi_{\Omega,s',k}^{1-\alpha}$.

For claim \eqref{claim:T correspondence}, if $P(\Psi_s)>0$, by the variational principle, there is an ergodic
invariant measure $\mu$ on $\Sigma$ such that \[h_{\mu}(T)+\lim_{n\to\infty}
\frac 1n\int\log\psi_{s,n}\,d\mu>0.\] Using \eqref{AbramovKnill}, one can check
$$
h_{\mu_D}(T_{D})+\lim_{k\to\infty}\frac 1k\int\log\psi_{D,s,k}\,d\mu_D=
\frac{1}{\mu(D)}\left(h_{\mu}(T)+\lim_{n\to\infty}
\frac 1n\int\log\psi_{s,n}\,d\mu\right),
$$
where $\mu_D$ is the induced measure as usual, so that $h_{\mu_D}(T_{D})+\lim_{k\to\infty}
\frac 1k\int\log\psi_{D,s,k}\,d\mu_D>0$.
Pushing forward $\mu_D$ under the isomorphism to a measure on $\Omega$,
and using the variational principle again, we see $P(\Psi_{\Omega,s})>0$. 

Now suppose that $P(\Psi_s)\le 0$. By Theorem \ref{thm:IY}\eqref{it:VP}, in order to
show $P(\Psi_{\Omega,s})\le 0$,
it suffices to show that $h_{\nu}(T_{\Omega})+\lim\frac 1k\int \log\psi_{\Omega,s,k}\,d\nu\le 0$
for all measures $\nu$ supported on a finite symbol full subshift 
of $\Sigma$. Let $\nu$ be such a measure. 
The measure $\nu$ corresponds to a $T_D$-invariant measure $\nu_D$ on $D$. 
Since there are finitely many symbols and $r_D(x)=m+n$ if $x\in X_{m,n}$, we see that $r_D$ is bounded. 
Hence $\int r_D\,d\nu_D<\infty$. By Subsection \ref{subsec:induced}, $\nu_D$
lifts to an invariant probability measure $\mu$ on $\Sigma$. Since we assumed that 
$P(\Psi_s)\le 0$, it follows from the variational principle that 
$$
h_{\mu}(T)+\lim_{n\to\infty}\frac 1n\int\log\psi_{s,n}\,d\mu\le 0.
$$
Using \eqref{AbramovKnill} again, we see that 
$$
h_{\nu}(T_{\Omega})+\lim_{k\to\infty}\frac 1k\int\log\psi_{\Omega,s,k}\,d\nu\le 0.
$$
Hence $P(\Psi_{\Omega,s})\le 0$. 


For claim \eqref{claim:zero pressure}, $s\mapsto P(\Psi_{\Omega,s})$ and $s\mapsto
P(\Psi_s)$ are convex (and hence continuous) functions defined for $s\in\R$. 
Applying claim \eqref{claim:T correspondence}, we see that $P(\Psi_{\Omega,s})>0$ for all
$s>0$ and $P(\Psi_{\Omega,s})\le 0$ for all $s<0$. It follows that $P(\Psi_{\Omega,0})=0$
as required. 



