\title[risk and reward of a zonal electricity market in Great Britain]{risk and reward of transitioning from a national to a zonal electricity market in Great Britain}%%%%%%%%%%%%
\author[]{Lukas Franken$^{1}$}
\author[]{Andrew Lyden$^{1}$}
