In the following, we discuss some properties of weighted varextropy, including its behavior for weighted distributions and its changes under monotonic transformations.
\begin{proposition}
Let $X$ be a non-negative absolutely  continuous random variable with $\mu=E(X)$. Then considering the equilibrium function $f_Y(x)=\frac{\overline F(x)}{\mu}, \, 0<x<+\infty$ where $\overline F(x)=1-F(x)$ is survival function of $X$, we have
\begin{align}
VJ^w(Y)=\frac{1}{4}\left[\int_{0}^{1}\frac{(1-u)^3}{\mu^3}\frac{(F^{-1}(u))^2}{f(F^{-1}(u))}du-\left(\int_{0}^1\frac{(1-u)^2}{\mu^2}\frac{F^{-1}(u)}{f(F^{-1}(u))}du\right)^2\right].
\end{align}
\end{proposition}
\begin{proposition}
Let $Y$ is an absolutely continuous random variable with weighted distribution $f_Y(x)=\frac{\delta(x)f(x)}{E[\delta(X)]}, x\in \mathbb{R}$ with $0<E[\delta(X)]<+\infty$. Then 
\begin{align}
VJ^w(Y)=\frac{1}{4E^2[\delta(Y)]}Var[Y\delta(Y)f(Y)].
\end{align}
\end{proposition}
\begin{proposition}
Let $Y=g(X)$ is a strictly increasing function of $X$, then
\begin{align}
VJ^w(Y)=\frac{1}{4}Var\left[\frac{g(X)}{g^{\prime}(X)}f(X)\right].
\end{align}
Note that if $Y=aX+b$, with assumption $a\ne 0$, then $VJ^w(Y)=VJ^w(X)+\frac{b^2}{a^2}VJ(X).$ Clearly, if $b=0$ then $VJ^w(Y)=VJ^w(X)$.
Also, if $Y=F_X(X)$ then we obtain $VJ^w(Y)=\frac{1}{48}$.
\end{proposition}
\begin{exmp}\label{egnor}
Let $Z$ have a standard normal distribution, then $VJ^w(Z)=\frac{1}{72}\frac{\sqrt 3}{\pi}$ and $VJ(Z)=\frac{1}{24}\frac{\sqrt 3}{\pi}-\frac{1}{16\pi}$, and thus weighted varextropy of $X=\sigma Z+\mu$ where $-\infty<\mu<\infty, \sigma>0$ is $VJ^w(X)=\frac{1}{72}\frac{\sqrt 3}{\pi}+\frac{\mu^2}{\sigma^2}(\frac{1}{24}\frac{\sqrt 3}{\pi}-\frac{1}{16\pi})$. Furthermore, if $X\sim N(0, \sigma^2)$ then $VJ^w(X)=\frac{1}{72}\frac{\sqrt 3}{\pi}$.
\end{exmp}
\begin{proposition}
If $X$ is a symmetric random variable with respect to a finite mean $\mu=E[X]$,  i.e.,  $F(x+\mu)=1-F(\mu-x)$, then  $VJ^w(X-\mu)=VJ^w(\mu-X)$.
\end{proposition}
\begin{exmp}
Consider  a random variable $X$ with piecewise constant probability density function  
\[f(x)=\sum_{j=1}^na_j1_{[j-1, j)}(x),\]
where $a_j\geq 0, j=1, \ldots, n, \sum_{j=1}^na_j=1$, and $1_{[j-1, j)}(x)$ is the indicator function.
Then, the varextropy and the weighted varextropy of $X$ are  
\begin{align}
VJ(X)&=\frac{1}{4}\left[\int_{0}^n\sum_{j=1}^na_j^31_{[j-1, j)}(x)dx\right]-(J(X))^2\nonumber
\\&=\frac{1}{4}\left[
\sum_{j=1}^n\int_{k-1}^ka_j^3dx
\right]-(J(X))^2=\frac{1}{4}\left[\sum_{j=1}^na_j^3-(\sum_{j=1}^na_j^2)^2\right],
\end{align}
\begin{align}
VJ^w(X)&=\frac{1}{4}\left[\int_0^n x^2\sum_{j=1}^na_j^31_{[j-1, j)}(x)dx\right]-(J^w(X))^2\nonumber\\&=
\frac{1}{4}\left[\sum_{j=1}^n\int_{j-1}^j x^2a_j^3dx\right]-(J^w(X))^2\nonumber\\&=\frac{1}{12}\sum_{j=1}^n(3j^2-3j+1)a_j^3-\left(\frac{1}{4}\sum_{j=1}^n(2j-1)a_j^2\right)^2.
\end{align}
If for every $j=1, \ldots, n$, $a_j=\frac{1}{n}$, then the values of varextropy and weighted varextropy will be $0$ and $\frac{1}{48}$, respectively.
\end{exmp}
\begin{definition}
If $X$ and $Y$ are absolutely continuous random variables, we define the bivariate version of weighted varextropy, as follows
\begin{align}
VJ^w(X, Y)=\frac{1}{16}\left[\int_{-\infty}^{+\infty}\int_{-\infty}^{+\infty}x^2y^2f^3_{X, Y}(x, y)dxdy-{\left(\int_{-\infty}^{+\infty}\int_{-\infty}^{+\infty}xyf^2_{X, Y}(x,y)dxdy\right)}^2\right], 
\end{align}
If $X$ and $Y$ are independent then we will have
\begin{align}
VJ^w(X, Y)=VJ^w(X)\left[VJ^w(Y)+(J^w(Y))^2\right]+\left[(J^w(X))^2\right]VJ^w(Y).
\end{align}
\end{definition}
