\begin{remark}
If hazard rate function $r(t)$ is increasing, then we can obtain 
\begin{align*}
VJ^w(X_t)+(J^w(X_t))^2&=\frac{1}{4\overline F^3(t)}\int_{t}^{+\infty}x^2{r}^3(x)\overline F^3(x)dx\\&\geq 
\frac{t^2 r^3(t)}{4}\int_{t}^{+\infty}\left(\frac{\overline F(x)}{\overline F(t)}\right)^3dx.
\end{align*}
\end{remark}
\begin{remark}
If we assume the reversed hazard rate function $\tilde{r}(t)$ is decreasing, then
%\begin{align}\label{wvap} 
%VJ^w(X_{(t)})+{(J^w(X_{(t)}))^2}\leq \frac{\tilde{r}^2(t)}{6}\left(\frac{t^2}{2}-\int_{0}^tx\left(\frac{F(x)}{F(t)}\right)^3dx\right)
%\end{align}
%By  utilizing \eqref{wvap} and decreasing reversed hazard rate, 
we have 
\begin{align*}
VJ^w(X_{(t)})+{(J^w(X_{(t)}))^2}&=\frac{1}{4F^3(t)}\int_{0}^{t}x^2\tilde{r}^2(x)F^2(x)f(x)dx\nonumber\\&=\frac{1}{4F^3(t)}\left[\frac{x^2\tilde{r}^2(x)F^3(x)}{3}\Big|_{0}^{t}-\int_{0}^{t}\frac{F^3(x)}{3}\left(2x\tilde{r}^2(x)+2x^2\tilde{r}(x)\tilde{r}^{\prime}(x)\right)dx\right]
\\&\geq
\frac{\tilde{r}^2(t)t^2}{12}-\frac{1}{6}\int_{0}^tx\tilde{r}^2(x)\left(\frac{F(x)}{F(t)}\right)^3dx.
\end{align*}
\end{remark}
We now aim to analyze the behavior of the residual varextropy and the past varextropy. %To this end, we take their derivatives with respect to t.
\begin{definition}
A random variable is said to be increasing (decreasing) in weighted residual varextropy if $VJ^w_{\phi}(X_t)$ is an increasing (decreasing) function of $t$.
\end{definition}
\begin{theorem}
Let $X$ is a non-negative random variable, then for $t>0$, $VJ^w_{\phi}(X_{t})$ is incresing  (decreasing) if and only if 
\begin{align}
VJ^w_{\phi}(X_{t})\geq (\leq) \frac{1}{12}\phi^2(t)(r(t))^2+\frac{1}{3}r(t)J^w_{\phi}(X_{t})\left[J^w_{\phi}(X_{t})+\phi(t)r(t)\right].
\end{align}
\end{theorem}
\begin{proof}
Differentiating \eqref{wrve1} with respect to $t$ leads to 
\begin{align}
\frac{d}{dt}VJ^{w}_{\phi}(X_{t})&=\frac{1}{4}\left\{-\phi^2(t)\left(\frac{f(t)}{\overline F(t)}\right)^3+\frac{3f(t)}{\overline F(t)}\int_{t}^{+\infty}\phi^2(x)\left(\frac{f(x)}{\overline F(t)}\right)^3dx\right.\nonumber
\\&+2\phi(t)\left(\frac{f(t)}{\overline F(t)}\right)^2\int_{t}^{+\infty}\phi(x)\left(\frac{f(x)}{\overline F(t)}\right)^2dx\nonumber
\left.-4\frac{f(t)}{\overline F(t)}\left(\int_{t}^{+\infty}\phi(x)\left(\frac{f(x)}{\overline F(t)}\right)^2dx\right)^2\right\}\nonumber
\\&=-\frac{1}{4}{\phi}^2(t)(r(t))^3+3r(t)VJ^w_{\phi}(X_{t})-r(t)J^w_{\phi}(X_{t})\left[J^w_{\phi}(X_{t})+\phi(t)r(t)\right].
\end{align}
Then $VJ^{w}_{\phi}(X_{t})$ is increasing (decreasing) if and only if 
\[-\frac{1}{4}{\phi}^2(t)(r(t))^3+3r(t)VJ^w_{\phi}(X_{t})-r(t)J^w_{\phi}(X_{t})\left[J^w_{\phi}(X_{t})+\phi(t)r(t)\right]\geq(\leq) 0,\]
but $r(t)\geq 0$, so the desired result is obtaind.
\end{proof}
\begin{remark}
Similarly, if $VJ^w_{\phi}(X_{(t)})$ is an increasing (decreasing) function of $t$ then we can obtain bounds for it as follows  
\begin{align}
VJ^w_{\phi}(X_{(t)})\leq (\geq) \frac{1}{12}\phi^2(t)(\tilde r(t))^2+\frac{1}{3}\tilde r{(t)}J^w_{\phi}(X_{(t)})\left[J^w_{\phi}(X_{(t)})+\phi(t)r(t)\right].
\end{align}
\end{remark}
Now, in the following theorem,  we obtain upper bound for the weighted residual varextropy $VJ^w_{\phi}(X_t)$, using mean residual life $m(t)$, given as
\[m(t)=E(X_t)=E(X-t|X>t).\]
\begin{theorem}
Let $X$ be a non-negative random variable with density function $f (x)$ and survival function $\overline F(x) = 1 - F(x)$. Then an upper bound for $VJ^w_{\phi}(X_t)$ is given by
\begin{align}
VJ^w_{\phi}(X_t)\leq \frac{1}{(\overline F(t))^2}E\left\{\Big[\phi(X_{t}+t)f^{\prime}(X_{t}+t)+\phi^{\prime}(X_t+t)f(X_{t}+t)\Big]^2\,\frac{m(t+X_{t})-m(t)+X_{(t)}}{r(t+X_{(t)})}\right\}.
\end{align}
\end{theorem}
\begin{proof}
In Proposition 1 of  \cite{Goodd}, we can show 
\begin{align}
\int_{x}^{+\infty}(y-m(t))\frac{f(t+y)}{\overline F(t)}dy=\frac{\overline F(t+x)}{\overline F(t)}\left\{m(t+x)-m(t)+x\right\},
\end{align}
are therefore by Lemma 1 in \cite{Goodd}, we have
\begin{align}
VJ&^w_{\phi}(X_{(t)})\leq \int_{0}^{+\infty}\left[\phi(y+t)\frac{f^{\prime}(y+t)}{\overline F(t)}+\phi^{\prime}(y+t)\frac{f(y+t)}{\overline F(t)}\right]^2\frac{\overline F(t+x)}{\overline F(t)}\left\{m(t+x)-m(t)+x\right\}dx\nonumber
\\&=\int_{0}^{+\infty}\left[\phi(y+t)\frac{f^{\prime}(y+t)}{\overline F(t)}+\phi^{\prime}(y+t)\frac{f(y+t)}{\overline F(t)}\right]^2\frac{1}{r(t+x)}\left\{m(t+x)-m(t)+x\right\}\frac{f(x+t)}{\overline F(t)}dx.
\end{align}
\end{proof}
