In the following, we  provides a useful expression for the varextropy of the lifetime of coherent systems. Coherent systems offer a mathematical model for complex technical devices made of simple components. Notably, a structure consisting of $n$ components is known as a coherent system if it has no irrelevant components (a component is irrelevant if it does notmatter whether or not it is working)
and the system is monotone in every component.  

Let $X_1$, $\ldots$, $X_n$ be independent and identically distributed random variables with distribution function $F(t)$ and probability density function $f(t)$. They represent the lifetimes of the components of an $n$-component coherent system with lifetime $T$, and signature vector ${\bf s}=(s_1, s_2, \ldots, s_n)$, where $s_i=P(T=X_{i: n})$ for $i=1, \ldots, n$ is 
the probability that the $i$th component in the system is the last failed component and $\sum_{i=1}^ns_i=1$.
\cite{Saman} showed that the probability density function of $T$
%the lifetime of the coherent system 
is $f_T(t)=\sum_{i=1}^ns_if_{i: n}(t)$ where
\[f_{i: n}(t)=\frac{\Gamma(n+1)}{\Gamma(i)\Gamma(n-i+1)}[F(t)]^{i-1}[\overline F(t)]^{n-i}f(t), \, \, t\geq 0.\] Hence, 
the varextroy of the system with lifetime $T$ can be expressed as follows
\begin{align}
VJ(T)&=\frac{1}{4}\left[\int_{0}^{+\infty}(f_T(x))^3dx-\left(\int_{0}^{+\infty}(f_T(x))^2dx\right)^2\right]\nonumber\\&=\frac{1}{4}\left[\int_{0}^{+\infty}\left(\sum_{i=1}^ns_if_{i:n}(x)\right)^3dx-\left(\int_{0}^{+\infty}\left(\sum_{i=1}^ns_if_{i:n}(x)\right)^2dx\right)^2\right]\nonumber
\\&=\frac{1}{4}\left[\int_{0}^{1}\left(\sum_{i=1}^n s_ig_{i}(u)\right)^3f^2(F^{-1}(u))du-\left(\int_{0}^{1}\left(\sum_{i=1}^n s_ig_{i}(u)\right)^2f(F^{-1}(u))du\right)^2\right]\nonumber
\\&=\frac{1}{4}\left[\int_{0}^{1}g_V^3(u)f^2(F^{-1}(u))du-\left(\int_{0}^{1}g_V^2(u)f(F^{-1}(u))du\right)^2\right],
\end{align}
where $g_V(u)=\sum_{i=1}^n s_ig_{i}(u)$.
%\end{thm}
\begin{exmp}
Consider a coherent system of order 3 with lifetime components identically independent distributed, which have common exponential distribution with mean $\frac{1}{\lambda}$.  We consider  signature vector ${\bf s}=(\frac{1}{3}, \frac{2}{3}, 0)$ for the cohorent sysytem. It can be easily shown that $g_V(u)=(1-u)(1+3u)$, hence
\begin{align*}
J(T)=-\frac{\lambda}{2}\int_{0}^1{(1-u)}^3{(1+3u)}^2du=-0.35\lambda.
\end{align*} 
On the other hand, since 
$\frac{1}{4}\int_{0}^{+\infty}f^3_T(x)dx=\frac{\lambda^2}{4}\int_{0}^1(1-u)^5(1+3u)^3du=\frac{25}{168}\lambda^2$, thus
$VJ(T)=0.0263\lambda^2$.
\end{exmp}
When the structure of the engineering system is highly complex and contains a large number of components, calculating  $J(T)$ and consequently $VJ(T)$ becomes difficult or very time-consuming. In the following, we derive an upper bound on the %find the upper limit for the 
lifetime of the coherent system, which can be useful for investigating the uncertainty behavior of its lifetime. 
%of this system.
\begin{theorem}\label{harth}
Let $T$ is lifetime of a cohorent system, consisting of $n$  independent and identically distributed components with  lifetimes  $X_1$, $\ldots$,  $X_n$  and a common distribution $F$ with probability density function $f$. Also, suppose that  signature of  the system is ${\bf s} = (s_1, ..., s_n)$. In this case, we have the following statement:  
\begin{align}
J(T)\leq \frac{-1}{8}\int_{0}^{1}\frac{1}{(F^{-1}(u))^2}\left(\sum_{i=1}^{n}s_iG_i(u)\right)^2dF^{-1}(u),
\end{align}
where $G_i(u)=\sum_{j=i}^n{n\choose j}u^j(1-u)^{n-j}$.
\end{theorem}
\begin{proof}
By using of Hardy's inequality  \eqref{T1.1} and equation \eqref{ex} for non-negative random variable, we have 
\begin{align*}
\int_{0}^{+\infty}f_T^2(x)dx&\geq \frac{1}{4}\int_{0}^{+\infty}{\left(\frac{1}{x}\int_{0}^{x}f_T(t)dt\right)}^2dx
= \frac{1}{4}\int_{0}^{+\infty}\frac{1}{x^2}\left(\int_{0}^x\sum_{i=1}^ns_if_{i: n}(t)dt\right)^2dx
\\&=\frac{1}{4}\int_{0}^{+\infty}\frac{1}{x^2}\left(\sum_{i=1}^ns_i\int_{0}^xf_{i: n}(t)dt\right)^2dx\\&=
\frac{1}{4}\int_{0}^{+\infty}\frac{1}{x^2}\left(\sum_{i=1}^ns_i\sum_{j=i}^n{n\choose j}F^j(x){(1-F(x))}^{n-j}\right)^2dx
\\&=\frac{1}{4}\int_0^1\frac{1}{{(F^{-1}(u))}^2}\left(\sum_{i=1}^ns_i\sum_{j=i}^n{n\choose j}u^j{(1-u)}^{n-j}\right)^2dF^{-1}(u),
\end{align*}
and thus, by utilizing of definition $G_i(u)$, the proof is completed. 
\end{proof}
