\section{Stochastic comparisons }
In this section, we propose a new stochastic order derived from the weighted varextropy measure.
\begin{definition}
The random variable $X$ is said to be smaller than $Y$ in the weighted varextropy order, denoted $X\overset{VJ^w}{\leq}Y$, if $VJ^w(X)\leq VJ^w(Y)$.
\end{definition}
In the following example, we get some comparisons about the weighted varextropy.
\begin{exmp}
\begin{enumerate}
\item[(a)] If $X$ has given Laplace distribution in Example \ref{eglap} with $\beta=1$ and $Y$ has standard exponential distribution then $VJ^W(x)=\frac{1}{216}$ and  $VJ^w(Y)=\frac{5}{1728}$ and thus $Y\overset{VJ^w}{\leq}X$.
\item[(b)] If $X$ and $Y$ follow Weibull distribution with $\lambda=1$ and $\alpha=2$ and $\lambda=1$ and $\alpha=1$, respectively. Then $VJ^w(X)=0.058$ and $VJ^w(Y)=0.0029$,  then $Y\overset{VJ^w}{\leq}X$.
\item[(c)] If $X\sim N(\mu_1, \sigma^2)$ and $Y\sim N(\mu_2, \sigma^2)$  and $\mu_1\leq \mu_2$ then using Example \ref{egnor} $X\overset{VJ^w}{\leq}Y$.  Also if $X\sim N(\mu, \sigma_1^2)$ and $Y\sim N(\mu, \sigma_2^2)$ and $\sigma_1\leq \sigma_2$ then $Y\overset{VJ^w}{\leq}X$.
\end{enumerate}
\end{exmp}
\begin{remark}
According to the above example and the results obtained from Example 6 in \cite{Vaselabadi}, it can be concluded that the varextropy order does not imply the weighted varextropy order.
\end{remark}
\begin{proposition}\label{p2.22}
The random variable $X$ has reciprocal distribution with probability distribution function 
\begin{align}\label{recip}
f(x)=\frac{1}{x[\ln(b)-\ln(a)]},\, a<x<b, \, \, a>0, 
\end{align}
if and only if $VJ^w(X)=0$.
\end{proposition}
\begin{proof}
The sufficiency part of the proof is straightforward. To prove of  necessity, we assume that $VJ^w(X)=0$, hence 
$xf(x)=E(Xf(X))=constant=c$ and therefore $f(x)=\frac{c}{x}$. Now, if we assume that $X$ has finite support $(a, b)$, then we conclude that $X$ has a reciprocal distribution with the probability density function given in \eqref{recip}. 
\end{proof}
\begin{corollary}
If $X$ has a reciprocal distribution, then for any continuous random variable $Y$,  we have $X\overset{VJ^w}{\leq}Y$, 
\end{corollary}
\begin{proposition}
Let $X_{k:n}$ denote the kth order statistic of the reciprocal distribution. Then 
\begin{itemize}
\item[a)] $X_{k:n}\overset{VJ^w}{\leq}X_{1:n}$ and $X_{k:n}\overset{VJ^w}{\leq}X_{n:n}$ for all $1\leq k\leq n$.
\item[b)] when $n$ is even, we have $X_{\frac{n}{2}: n}\overset{VJ^w}{\leq} X_{k:n}$ for all $1\leq k\leq n$.
\item[c)] when $n$ is odd, we have $X_{\frac{n+1}{2}: n}\overset{VJ^w}{\leq} X_{k:n}$ for all $1\leq k\leq n$.
\end{itemize}
\end{proposition}
\begin{proposition}
Let $X_1, X_2, \ldots, X_n$ be a random sample from a distribution with an absolutely continuous cumulative distribution  $F(x)$ and probability density function $f(x)$, then
\begin{align}
VJ^w(X_{r:n})&=\frac{B(3r-2, 3(n-r)+1)}{4B^3(r, n-r+1)} E[(F^{-1}(V1))^2f^2(F^{-1}(V1))]\nonumber\\&-
\frac{B^2(2r-1, 2(n-r)+1)}{4B^3(r, n-r+1)} E^2[F^{-1}(V2)f(F^{-1}(V2))].
\end{align}
where $V_1\sim Beta(3r-2, 3(n-r)+1)$ and $V_2\sim Beta(2r-1, 2(n-r)+1)$.
\end{proposition}
\begin{proposition}
Let $X_1, X_2, \ldots, X_n$ be a random sample from a symmetric distribution around zero with an absolutely continuous cumulative distribution  $F(x)$ and probability density function $f(x)$, then
\begin{align}
VJ^w(X_{r:n})=VJ^w(X_{n-r+1:n}).
\end{align}
\end{proposition}
\begin{proof}
We have 
\begin{align}
VJ^w(X_{r:n})=&\frac{1}{B(r, n-r+1)}\int_{-\infty}^{+\infty}x^2(F(x))^{r-1}(1-F(x))^{n-r}f(x)dx\\&=\frac{1}{B(r, n-r+1)}\int_{-\infty}^{+\infty}y^2(F(-y))^{r-1}(1-F(-y))^{n-r}f(-y)dy.
\end{align}
Now, since $F(-y)=1-F(y)$ and $f(-y)=f(y)$, hence
\begin{align}
VJ^w(X_{r:n})&=\frac{1}{B(n-r+1, r)}\int_{-\infty}^{+\infty}y^2(F(y))^{n-r}(1-F(y))^{r-1}f(y)dy=VJ^w(X_{n-r+1:n}),
\end{align}
and hence the desired result is obtained.
\end{proof}
The following examples are presented to demonstrate the weighted varextropy of the order statistics $X_{r: n}$ derived from selected probability distributions.
