\left[\frac{B(3r-2, 3(n-r)+1)}{B^3(r,n-r+1)}-\frac{B^2(2r-1, 2(n-r)+1)}{B^4(r,n-r+1)}\right]
\\&+\frac{a}{2(b-a)}\left[\frac{B(3r-1, 3(n-r)+1)}{B^3(r,n-r+1)}-\frac{B(2r, 2(n-r)+1)B(2r-1, 2(n-r)+1)}{B^4(r,n-r+1)}\right].
\end{align*}
\end{exmp}
\begin{exmp}
If $X$ has exponential distribution with mean $\theta$, then 
\end{exmp}
