\section{Kernel estimation}
Let $X_1,\ldots, X_n$ be non-negative independent observations from density function $f$. The kernel density estimator for $f$ is defined by \cite{Parzen1962} as 
\begin{equation}\label{eq1}
f_n(x)=\frac{1}{nh_n}\sum_{i=1}^{n}K\big(\frac{x-X_i}{h_n}\big),
\end{equation}
where $K$ is a density kernel function and $h_n\rightarrow 0$ as $n\rightarrow \infty$ is a bandwidth sequence. Based on $f_n(x)$ \cite{Zhang2025} proposed the following plug-in estimator for $VJ^w(X)$ as bellow
\begin{equation}\label{eq2}
\hat{V}J_n^w(X)=\frac{1}{4}\left(\int_{0}^{+\infty}x^2f_n^3(x) dx-{\Big(\int_{0}^{+\infty}xf_n^2(x) dx\Big)}^2\right).
\end{equation}
\cite{Zhang2025} investigated some asymptotic properties for $\hat{V}J_n^w(X)$ in $\eqref{eq2}.$ $\hat{V}J_n^w(X)$ can be estimated by using numerical integration. When the dimensionality of random variable $X$ is high, numerical integration becomes unstable and computationally demanding. \cite{Joe} suggested using the second form of estimation that is resubstitution instead of numerical integration. Inspired by the estimator proposed by \cite{Joe}, we propose the following estimator for ${V}J^w(X)$:
\begin{align}\label{eq3}
\tilde{V}J^w(X) &=\frac{1}{4}\left(\int_0^{+\infty}x^2 {(f_n(x))}^2 dF_n(x)-{\Big(\int_0^{+\infty}x f_n(x) dF_n(x)\Big)}^2\right)\nonumber\\
&= \frac{1}{4n}\sum_{i=1}^{n}X_i^2{(\tilde{f}_{n}(X_i))}^2-\frac{1}{4}{\Big(\frac{1}{n}\sum_{i=1}^{n}X_i \tilde{f}_n(X_i)\Big)}^2,
\end{align}
where $F_n(x)=\frac{1}{n}\sum_{i=1}^{n}I(X_i\leq x)$ is the empirical distribution function and 
\begin{equation}\label{eq4}
\tilde{f}_n(X_i)=\frac{1}{(n-1)h_{n-1}}\sum_{j=1, j\neq i}^{n}K\Big(\frac{X_i-X_j}{h_{n-1}}\Big).
\end{equation} 
The weighted varextropy $VJ^w(X)$ can be rewritten as
\begin{equation}\label{eq5}
VJ^w(X)=\frac{1}{4}\left(\int_0^1 \frac{{(Q(u))}^2}{{(q(u))}^2} du-{\Big(\int_0^1 \frac{Q(u)}{q(u)} du\Big)}^2\right),
 \end{equation}
 where $Q(u)=\inf \{x ; F(x)\geq u\}, ~ 0\leq u \leq 1,$ is the quantile function corresponding to the distribution function $F(x)$ and $q(u)=Q'(u)=\frac{1}{f(Q(u))}$ is its quantile density function. Let $X_{(i)}$ be the $ith$ order statistic, a kernel estimator for $q(u)$ is given by \cite{Soni} as 
 \begin{equation}\label{eq6}
 \tilde{q}_n(u)=\frac{1}{h_n}\int_0^1 \frac{K(\frac{t-u}{h_n})}{f_n(Q_n(t))}dt=\frac{1}{nh_n}\sum_{i=1}^{n}
 \frac{K(\frac{S_i-u}{h_n})}{f_n(X_{(i)})},
 \end{equation} 
 where $S_i$ is the proportion of observations less than or equal to $X_{(i)}$ and $Q_n(u)=\inf\{ x; F_n(x)\geq u\}, 0\leq u \leq 1,$ is the empirical estimator of $Q(u).$ Weighted varextropy in the form of $\eqref{eq5}$ proposes the third estimator for weighted varextropy based on $\tilde{q}_n(u)$ and $Q_n(u)$ as
\begin{equation}\label{eq7}
\bar{V}J^w(X)=\frac{1}{4}\left(\int_0^1 \frac{{(Q_n(u))}^2}{{(\tilde{q}_n(u))}^2} du-{\Big(\int_0^1\frac{Q_n(u)}{\tilde{q}_n(u)}du\Big)}^2\right).
\end{equation}
We list the assumptions used in this section:
%{\bf Assumptions}
\begin{description}
\item[$(1)$]
$K(\cdot)$ has finite support.
\item[$(2)$]
$K$ is symmetric about zero.

\item[$(3)$]
There is a positive constant $M$ such that 
$ 
\left|K(x)-K(y)\right|\leq M \left|x-y\right|.
$
\end{description}
In the following, we investigate the almost sure (a.s.) consistency of the proposed estimators.
\begin{theorem}
If $f$ is bounded and $E(X^2)<\infty,$ then we have
\begin{equation*}
\lim_{n \rightarrow \infty}\tilde{V}J^w(X)=VJ^w(X) ~ a.s.
\end{equation*}
\end{theorem}
\begin{proof}
\begin{align}\label{eq8}
\tilde{V}J^w(X)-VJ^w(X) &\leq \frac{1}{4} \sup_x\left|f_n^2(x)-f^2(x)\right|\int_0^{+\infty} x^2 dF_n(x)\nonumber\\
&+\frac{1}{4} \left(\int_0^{+\infty} x^2 f^2(x) dF_n(x)- \int_{0}^{+\infty} x^2 f^3(x) dx\right)\nonumber\\
&+ \frac{1}{4}\left({\Big(\int_0^{+\infty}xf(x)dF(x)\Big)}^2-{\Big(\int_{0}^{+\infty}xf_n(x)dF_n(x)\Big)}^2\right)\nonumber\\
&:=I_1+I_2+I_3. 
\end{align}
The Kolmogorov law of large numbers implies that
\begin{align}\label{eq9}
\int_0^{+\infty}x^2 dF_n(x)=\frac{1}{n}\sum_{i=1}^{n}X_i^2\rightarrow E(X^2)~ a.s.,
\end{align}
\begin{align}\label{eq10}
\int_{0}^{+\infty}x^2 f^2(x)dF_n(x)=\frac{1}{n}\sum_{i=1}^{n}X_i^2 f^2(X_i)\rightarrow \int_0^{+\infty}x^2 f^3(x) dx<\infty~ a.s.
\end{align}
For $n\rightarrow \infty,$ $\sup_x\left|f_n(x)-f(x)\right|\rightarrow 0,$ (see \cite{Prakas}). This last result, $\eqref{eq9}$ and $\eqref{eq10}$ conclude that
\begin{align}\label{eq11}
\lim_{n \rightarrow \infty}I_1=0~a.s.,
\end{align}
and 
\begin{align}\label{eq12}
\lim_{n \rightarrow \infty}I_2=0~a.s.,
\end{align}
In a similar way we can see that 
\begin{equation*}
\lim_{n \rightarrow \infty}\int_{0}^{\infty}xf_n(x) dF_n(x)=\int_{0}^{\infty}x f(x) dF(x),
\end{equation*}
and hence
\begin{align}\label{eq13}
\lim_{n \rightarrow \infty}I_3=0~a.s.,
\end{align}
$\eqref{eq8}, \eqref{eq11}, \eqref{eq12}$ and $\eqref{eq13}$ complete the proof.
\end{proof}
\begin{theorem}
Suppose that $f$ is bounded and $\tau=\sup\{x ; F(x)<1\}<\infty.$

Then as $n \rightarrow \infty$
\begin{align*}
\bar{V}J^w(X)\rightarrow VJ^w(X).
\end{align*}
\end{theorem}
\begin{proof}
\begin{align}\label{I}
\bar{V}J^w(X)-VJ^w(X)&= \frac{1}{4}\int_{0}^1 \frac{1}{{(\tilde{q}_n(u))}^2}\left({(Q_n(u))}^2-{(Q(u))}^2\right) du\nonumber\\
&+\frac{1}{4}\int_0^1 {(Q(u))}^2\left[\frac{1}{{(\tilde{q}_n(u))}^2}-\frac{1}{{(q(u))}^2}\right]du\nonumber\\
&+\frac{1}{4}\left({\Big(\int_0^1 \frac{Q(u)}{q(u)}du\Big)}^2-{\Big(\int_0^1 \frac{Q_n(u)}{\tilde{q}_n(u)}du\Big)}^2\right)\nonumber\\
&:=\frac{1}{4}I_{n1}+\frac{1}{4}I_{n2}+\frac{1}{4}I_{n3}.
\end{align}
On the other hand
\begin{align*}
\frac{1}{{(\tilde{q}_n (u))}^2}-\frac{1}{{(q(u))}^2}=\left(q(u)-\tilde{q}_n(u)\right)\frac{q(u)+\tilde{q}_n(u)}{{(\tilde{q}_n(u))}^2{(q(u))}^2}.
\end{align*}
Using the proof of Theorem $3.4$ of \cite{Subh}, $\sup_u\left|\tilde{q}_n(u)-q(u)\right|\rightarrow 0$ as $n \rightarrow \infty,$ which implies that
\begin{align}\label{II}
\lim_{n \rightarrow \infty}\sup_u \left| \frac{1}{{(\tilde{q}_n (u))}^2}-\frac{1}{{(q(u))}^2}\right|
\leq 2 \lim_{n \rightarrow \infty}\sup_u \left|q(u)-\tilde{q}_n(u)\right|{(\sup_x f(x))}^3=0.
\end{align}
To deal with the term $I_{n2}$  we can observe that
\begin{align}\label{III}
\lim_{n \rightarrow \infty}\left|I_{n2}\right|\leq \lim_{n \rightarrow \infty}\sup_u \left| \frac{1}{{(\tilde{q}_n (u))}^2}-\frac{1}{{(q(u))}^2}\right|\int_0^1 x^2 f(x) dx=0.
\end{align}
Next
\begin{align*}
\sup_{0<u<1}\left|Q_n^2(u)-Q^2(u)\right|&\leq
\sup_{0<u<1}\left|Q_n(u)-Q(u)\right|\{2|Q_n(u)|+\sup_{0<u<1}|Q(u)-Q_n(u)|\}\nonumber\\
&\leq \sup_{0<u<1}\left|Q_n(u)-Q(u)\right|\{2\tau+\sup_{0<u<1}\left|Q(u)-Q_n(u)\right|\}.
\end{align*}
For $n \rightarrow \infty, \sup_{0<u<1}\left|Q_n(u)-Q(u)\right|\rightarrow 0$ which implies that
\begin{align}\label{IV}
\lim_{n \rightarrow \infty}\sup_{0<u<1} \left| Q_n^2(u)-Q^2(u)\right|=0.
\end{align}
Now
\begin{align*}
|I_{n1}|\leq\sup_{0<u<1}\left|Q_n^2(u)-Q^2(u)\right|\left(\left|\int_0^1 \big(\frac{1}{{(\tilde{q}_n(u))}^2}-\frac{1}{{(q(u))}^2}\big)du\right|+{|sup_x f(x)|}^2\right).
\end{align*}
This last result, $\eqref{II}$ and $\eqref{IV}$ imply that
\begin{align}\label{V}
\lim_{n \rightarrow \infty}I_{n1}=0.
\end{align}
In a similar way we can show that
\begin{align}\label{VI}
\lim_{n \rightarrow \infty}\int_0^1 \frac{Q_n(u)}{\tilde{q}_n(u)}du=\int_{0}^1 \frac{Q(u)}{q(u)}du,
\end{align}
which implies that
\begin{align}\label{VII}
\lim_{n \rightarrow \infty}I_{n3}=0.
\end{align}
$\eqref{I}, \eqref{III}, \eqref{V}$ and $\eqref{VII}$ complete the proof.
\end{proof}
