\subsubsection{Landweber iteration (gradient-descent)}%{{{
\label{sssec_LandweberIteration}

The Landweber iteration for solving inverse problems arises from performing gradient descent
updates with learning rate \( \omega < 1 / \| A \|^{2} \) on the least squares problem  
\( \min_{f \in \mathbb{R}^{p}} \| Y - A f \|^{2} \), i.e., 
\begin{align}
  \widehat{f}^{(0)}: = 0, 
  \qquad 
  \widehat{f}^{(m + 1)}: = \widehat{f}^{(m)} + \omega A^{\top} (Y - A \widehat{f}^{(m)}) 
                         = (I - \omega A^{\top} A) \widehat{f}^{(m)} + \omega A^{\top} Y, 
\end{align}
for \( m \geq 0 \).
In terms of an approximating family as in Equation \eqref{eq_ApproximationFunctionGAlpha}, it is
given by 
$ g_{ \alpha }( \lambda ): = \lambda^{-1} ( 1 - ( 1 - \learningrate \lambda  )^{ 1 / \alpha } ) $,
and the discretisation \( \alpha_{\iteration} = \iteration^{-1} \).
If $A^{\top}A$ is invertible, the estimators have the non-recursive representation
\begin{equation*}
    \estimator^{ (\iteration) }
  = 
    \learningrate 
    \sum_{ i = 0 }^{ \iteration - 1 } 
    ( I - \learningrate \designmatrix^{\top} \designmatrix )^{i} \designmatrix^{\top} \response 
  =
    (I-(I-\omega\designmatrix^{\top}\designmatrix)^{m})(\designmatrix^{\top}\designmatrix)^{-1}\designmatrix^{\top}\response, 
  \qquad m \geq 0. 
\end{equation*}
leading to the explicit error decomposition \eqref{eq:strong_risk} and \eqref{eq:weak_risk} of the strong and weak risk: 
\begin{equation}
\label{eq:bias_variance_landweber}
\begin{aligned}
\mathcal{R}(\estimator^{(\iteration)}, \truesignal) &=b_\iteration^{2}(\truesignal)+s_\iteration =
  \Vert (I-\omega
  \designmatrix^{\top}\designmatrix)^{m}\truesignal\Vert^{2}+\noiselevel^{2}\mathrm{tr}((\designmatrix^{\top}\designmatrix)^{-1}(I-(I-\omega\designmatrix^{\top}\designmatrix)^{\iteration})^{2}),\\
\mathcal{R}_{\designmatrix} (\estimator^{(\iteration)}, \truesignal) &= b_{\iteration,
  \designmatrix}^{2}(\truesignal) + s_{\iteration,\designmatrix} = \Vert \designmatrix(I-\omega
  \designmatrix^{\top}\designmatrix)^{\iteration}\truesignal \Vert^{2} +
  \delta^{2}\mathrm{tr}((I-(I-\omega\designmatrix^{\top}\designmatrix)^{\iteration})^{2}).
\end{aligned}
\end{equation}

\begin{remark}[Numerical implementation]
In the \package, the weak and strong biases are updated iteratively through
\begin{align*}
b_\iteration^{2}(\truesignal) = \Vert (I-\omega\designmatrix^{\top}\designmatrix)(\truesignal-\mathbb{E}\estimator^{(\iteration-1)}) \Vert^{2}, \quad 
b_{\iteration, \designmatrix}^{2}(\truesignal) =
\Vert \designmatrix(I-\omega\designmatrix^{\top}\designmatrix)(\truesignal-\mathbb{E}\estimator^{(\iteration-1)}) \Vert^{2},
\end{align*}
while the weak and strong variance can only be updated sequentially by computing the powers of the
  matrix $I-\omega \designmatrix^{\top}\designmatrix$.
The weak and strong variance can then be evaluated via
\begin{equation*}
\begin{aligned}
  s_m 
  =
  \noiselevel^{2} \omega^{2}\mathrm{tr}\Big( \Big(\sum_{i=1}^{m-1}(I-\omega
  \designmatrix^{\top}\designmatrix)^{i}\Big)^{2} A^{\top}A\Big),
  \quad
  s_{m,A} 
  =
  \noiselevel^{2}\omega^{2}\mathrm{tr}\Big( \Big(A\sum_{i=1}^{m-1}(I-\omega
  \designmatrix^{\top}\designmatrix)^{i}A^{\top}\Big)^{2} \Big),
\end{aligned}
\end{equation*}
which is even possible if $A$ is not injective.
\end{remark}

