\subsubsection{Conjugate gradient descent}%{{{
\label{sssec_ConjugateGradientDescent}

In this section, we consider conjugate gradient descent for the normal equation
\begin{align}
  \label{eq_NormalEquation}
  A^{\top} Y = A^{\top} A f
\end{align}
as stylised in \Cref{alg:conjugate_gradient_descent}. 
In the \package{}, the algorithm is computed in a more efficient manner as proposed in
\citet[Algorithm~7.4.1]{bjoerck1996}.
\begin{center}
\begin{minipage}{0.9\linewidth}
\begin{algorithm}[H]
\caption{Conjugate gradient descent for the normal equation}
\label{alg:conjugate_gradient_descent}
\begin{algorithmic}[1]
\State \( 
               \estimator^{(0)} \gets 0, \quad \mathbf{r}^{(0)}\gets\response-\designmatrix \estimator^{(0)}, \quad q^{(0)} \gets\designmatrix^T \mathbf{r}^{(0)}
\)
\For{ \( m = 0, 1, 2, \dots \) }
\State \(
    \alpha_\iteration \gets\|\designmatrix^{\top} \mathbf{r}^{(\iteration)}\|^2 /\|\designmatrix q^{(\iteration)}\|^2 \quad (\text{learning rate})
\)
\State \( 
\estimator^{(\iteration+1)}\gets\estimator^{(\iteration)}+\alpha_{\iteration} q^{(\iteration)}
\)
\State  \(
d^{(\iteration+1)} \gets \mathbf{r}^{(\iteration)}-\alpha_\iteration \designmatrix q^{(\iteration)} \quad \text{(residual vector)}
\)
\State \(
  q^{(\iteration+1)} \gets \designmatrix^{\top}\mathbf{r}^{(\iteration+1)}+
  \frac{\|\designmatrix^{\top} \mathbf{r}^{(\iteration+1)}\|^2}{\|\designmatrix^T \mathbf{r}^{(\iteration)}\|^2}   q^{(\iteration)} \quad \text{(search direction)}
\)
\EndFor
\end{algorithmic}
\end{algorithm}
\end{minipage}
\end{center}
% {\color{red} 
% Let $\estimator^{(0)}=\estimator_0$ be the initial value of the algorithm. The conjugate gradient estimator is updated through
% \begin{equation*}
% \estimator^{(\iteration+1)}=\estimator^{(\iteration)}+\alpha_{\iteration} p^{(\iteration)},
% \end{equation*}
% where
% \begin{alignat*}{3}
% \alpha_\iteration&=\|\designmatrix^T r^{(\iteration)}\|_2^2 /\|\designmatrix p^{(\iteration)}\|_2^2, &&\text{  }\quad &&\text{(learning rate)}  \\
%   r^{(\iteration+1)}&=r^{(\iteration)}-\alpha_\iteration \designmatrix p^{(\iteration)}, \quad &&r^{(0)}=\response-\designmatrix \estimator^{(0)} \quad &&\text{(residual vector)}\\
%  p^{(\iteration+1)}&=\designmatrix^{\top}r^{\iteration+1}+ \frac{\|\designmatrix^T r^{(\iteration+1)}\|_2^2}{\|\designmatrix^T r^{(\iteration)}\|_2^2}   p^{(\iteration)}, \quad &&p^{(0)}=\designmatrix^T r^{(0)} \quad &&\text{(search direction)}.
% \end{alignat*}
% }
% \EZ{Formulate CG also in an algorithm block to stress that it's numerically explicit.}

The conjugate gradient algorithm does not have a direct representation in terms of a simple
approximating family \( (g_{\alpha})_{\alpha > 0} \).
Nevertheless, a similar representation based on the residual polynomials is presented in
\citet{hucker2025comparingregularisationpathsconjugate}.

We present the approach to early stopping for conjugate gradients following \citet{hucker2024early}. 
Under suitable assumptions on the design matrix $\designmatrix$ and the observation $\response$,
there is another formulation of the conjugate gradient algorithm obtained through minimising
residual polynomials, which we use for the theoretical analysis. 
Recall the convention that $g(\designmatrix \designmatrix^{\top})=\sum_{j=1}^n g(\lambda_j^{2}) v_j$ 
for a function \( g \) in terms of the SVD of $\designmatrix$ in \eqref{eq:SVD:designmatrix}.
The residual polynomial $r_\iteration$ with $\iteration \in \{0,\dots,n \}$ is then defined as
\begin{equation*}
r_{\iteration} \coloneqq \argmin_{p_{\iteration}} \Vert p_{\iteration}(\designmatrix \designmatrix^{\top}) \response\Vert^{2},
\end{equation*}
where the argmin is taken over all polynomials $p_{\iteration}$ of degree at most $\iteration$ satisfying $p_{\iteration}(0)=1$. The conjugate gradient estimator can now be expressed as
\begin{equation*}
\estimator^{(\iteration)} \coloneqq \designmatrix^{+}(I_{\samplesize}- r_{\iteration}(\designmatrix \designmatrix^{\top}))\response
\end{equation*}
with $A^+$ denoting the Moore--Penrose pseudoinverse of $A$. 
For the precise definition, we refer to \citet*[Definition 3.1]{hucker2024early}. For $t=\iteration
+\alpha$, with $\iteration \in \{0,\dots,n-1 \}$, $\alpha \in (0,1]$, the residual polynomial may be interpolated through $r_t \coloneqq (1-\alpha)r_{\iteration} + \alpha r_{\iteration +1}$, giving rise to the interpolated CG estimator $\estimator^{(t)} = (1-\alpha)\estimator^{(\iteration)} + \alpha \estimator^{(\iteration +1)}$.
\begin{remark}
\label{remark:interpolation}
To avoid the effect of \textit{overshooting} (see \citet{hucker2024early, miftachov2025early}), we interpolate linearly between the residual polynomials. In the \package{}, the default is set to the non-interpolated estimator and the interpolated estimator is also available as an option. From a computational perspective, the interpolation comes at a negligible additional cost since the required quantities are calculated in either case.
\end{remark}
Let $x_{1,t}$ be the smallest zero on $[0,\infty)$ of the $t$-th residual polynomial $r_t$ and denote by $r_{t,<}(x) \coloneqq r_t(x) \mathbf{1}(x<x_{1,t})$ the polynomial up to the first zero. 
Based on the residual polynomial, it is now possible to find a weak risk bound consisting of
an approximation and a stochastic error, which are data-dependent. 
The bound is given by
\begin{equation}
\label{eq:upperbound_error_decomposition_cg}
  \mathcal{R}_{A}(f^{*}, m): 
  = 
  \Vert \designmatrix (\estimator^{(t)} - \truesignal) \Vert^{2} 
  \leq
  2 (b_{t, \designmatrix} + s_{t, \designmatrix})
\end{equation}
with
\begin{align*}
  b_{t,A} 
  &\coloneqq
  \Vert r_{t,<}^{1/2}(\designmatrix \designmatrix^{\top})\designmatrix \truesignal \Vert^2 
  +
  \| Y - A \widehat{f}^{(t)} \|^{2}
  -
  \Vert r_{t,<}^{1/2}(\designmatrix \designmatrix^\top)\response \Vert^2, \\
\qquad s_{t,A} 
  &\coloneqq
  \Vert (1-r_{t,<})^{1/2}(\designmatrix \designmatrix^\top)\noise \Vert^2.
\end{align*}
Note that as $b_{t,A}$ does not correspond exactly to the squared bias, it also does not need to be positive. The (data-dependent) balanced oracle is given by
\begin{equation*}
t_w^{\mathfrak{b}} \coloneqq \inf \{t \in [0, d] \colon b_{t,A} \leq s_{t,A}\}.
\end{equation*}
In contrast to the other algorithms, even with knowledge of the true signal, the balanced oracle is
not available to the user since it depends on the residual polynomial, which is very hard to compute
in practice. 
In the \package{}, we instead compute an empirical version of the weak classical oracle
\begin{equation*}
  t^{\mathfrak{o}} 
  =
  t^{\mathfrak{o}}(f^{*}) 
  =
  \argmin_{t \in [0,d]} \Vert\designmatrix (\estimator^{(t)} - \truesignal)\Vert.
\end{equation*}
Analogously to before, we consider the discrepancy stopping time 
\begin{equation*}
  \DP \coloneqq \inf\{ t \in [0,d] \colon \| Y - A \widehat{f}^{(t)} \|^{2} \leq \kappa\}.
\end{equation*}
Even though we do not have a classical bias-variance decomposition, the prediction risk of the discrepancy stop satisfies the weakly balanced oracle inequality \cite[Theorem~6.8]{hucker2024early}
\begin{equation}
\mathcal{R}_{\designmatrix}(\truesignal, \DP) \lesssim \mathbb{E}(s_{t_w^{\mathfrak{b}}, A}) + \sqrt{n}\delta^2 + |\kappa - n\delta^{2}|. \label{eq:bal:oracle:CG}
\end{equation}
Note that the right-hand side involves the expected stochastic error at the balanced oracle and not the risk $\mathcal{R}_{\designmatrix}(\truesignal, t_w^{\mathfrak{b}})$ as in \eqref{eq:bal:oracle:truncated:SVD}, since \eqref{eq:upperbound_error_decomposition_cg} only provides an upper bound. Nevertheless, it is possible to retrieve the optimal rate for $\mathcal{R}_{\designmatrix}(\truesignal, \DP)$ by controlling $\mathbb{E}(s_{t_w^{\mathfrak{b}}, A})$, see \citet[Corollary~6.9]{hucker2024early}. The result shows that the critical value $\threshold$ should be chosen such that $|\kappa - n\delta^{2}| \lesssim \sqrt{n}\delta^{2}$ as for truncated SVD. 
For the reconstruction error $\mathcal{R}((\truesignal)^+, \DP)$, where $(\truesignal)^+ = A^+ A \truesignal$, there is no immediate analogue to the oracle inequality \eqref{eq:bal:oracle:CG}. 
Instead, the reconstruction error at $\DP$ has a relatively rough bound involving the error terms at $\DP$ and the intrinsic regularising quantity $\abs{r_{\DP}'(0)}$. 
Still, under a source condition on $\truesignal$ and polynomial spectral decay of order $p$, an optimal rate for $\mathcal{R}((\truesignal)^+, \DP)$ can be shown over a given regime of regularity parameters, see \citet[Theorem~7.10]{hucker2024early}.

