        \centering
          \includegraphics[width=\textwidth]{figures/demonstration_weak_quantities_plot.png}
          \caption{Weak error decomposition}
          \label{fig:error_demonstration_weak}
    \end{subfigure}
    \hfill
    \begin{subfigure}[b]{0.49\textwidth}
        \centering
          \includegraphics[width=\textwidth]{figures/demonstration_strong_quantities_plot.png}
          \caption{Strong error decomposition}
          \label{fig:error_demonstration_strong}
    \end{subfigure}
    \hfill
    \begin{subfigure}[b]{0.49\textwidth}
        \centering
  \includegraphics[width=\textwidth]{figures/signals_new.png}
  \caption{Signals}
  \label{fig:signals}
    \end{subfigure}
    \hfill
    \begin{subfigure}[b]{0.49\textwidth}
        \centering
        \includegraphics[width=\textwidth]{figures/boxplot_efficiency_SVD.png}
        %\vspace{-1px}
