\section{Additional results on Theorem \ref{thm:main}}\label{sec:technical.discussion}

We now discuss the main proof steps of Theorem \ref{thm:main}.
\paragraph*{Step 1} Preparations. To ease notational burden, for any function
$f$, let $f_{i}:=f(Z_{i})$, and write 
\begin{align*}
\hat{A}_{n} & =\frac{1}{n}\sum_{i=1}^{n}\hat{\xi}_{i}p_{i}p_{i}^{\prime}, & \hat{B}_{n}=\frac{1}{n}\sum_{i=1}^{n}\hat{\xi}_{i}p_{i}\mathbf{1}\left\{ \hat{\tau}_{i}\geq0\right\} ,\\
A_{n} & =\frac{1}{n}\sum_{i=1}^{n}\xi_{i}p_{i}p_{i}^{\prime}, & B_{n}=\frac{1}{n}\sum_{i=1}^{n}\xi_{i}p_{i}\mathbf{1}\left\{ \tau_{i}\geq0\right\} ,\\
A & =\mathbb{E}\left[\xi_{i}p_{i}p_{i}^{\prime}\right].
\end{align*}
Pick any $0<\varepsilon<\min\left\{ \underline{\lambda},6\tilde{C}_{\xi}\zeta_{p}^{2},3C_{\xi}\zeta_{p}^{2}/2\right\} $.
Define event 
\[
\mathcal{E}_{n}:=\left\{ \lambda_{\min}\left(A_{n}\right)\geq\underline{\lambda}-\varepsilon,\lambda_{\min}\left(\hat{A}_{n}\right)\geq\underline{\lambda}-\varepsilon\right\} .
\]
On event $\mathcal{E}_{n}$, note the problem of (\ref{eq:our.proposal})
is convex with a unique solution $\hat{\delta}(w)=\hat{\beta}^{\prime}p(w)$, where
$\hat{\beta}=\hat{A}_{n}^{-1}\hat{B}_{n}$. Furthermore, the oracle
problem  $\min_{\delta=\beta^{\prime}p,\beta\in\mathbb{R}^{\sieved}}L_{n}^{o}(\delta)$
is also convex with a unique solution $\tilde{\delta}(w)=\tilde{\beta}^{\prime}p(w)$,
$\tilde{\beta}=A_{n}^{-1}B_{n}$. 
Next, we decompose 
\begin{align*}
 & \mathbb{E}_{P_{n}}\left[L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\right]=\mathcal{P}_{1}E_{1,n}+\left(1-\mathcal{P}_{1}\right)E_{2,n},
\end{align*}
where 
\begin{align*}
\mathcal{P}_{1}:= & Pr\{\mathcal{E}_{n}\}\leq1,\\
E_{1,n}:= & \mathbb{E}_{P_{n}}\left[L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\mid\mathcal{E}_{n}\text{ holds}\right],\\
E_{2,n}:= & \mathbb{E}_{P_{n}}\left[L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\mid\mathcal{E}_{n}\text{ does not hold}\right].
\end{align*}

\paragraph*{Step 2} We invoke Lemmas \ref{lem:remainder.1} and \ref{lem:remainder.2}
to conclude that, for each $n$ such that 
\[
4C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right)<\varepsilon,
\]
we have 
\[
P\{\mathcal{E}_{n}\}\geq1-2d_{p}\left[\exp\left(\frac{-n\varepsilon^{2}}{4C_{\xi}^{2}\zeta_{p}^{4}}\right)+K\exp\left(\frac{-n\varepsilon^{2}}{16K\tilde{C}_{\xi}^{2}\zeta_{p}^{4}}\right)\right].
\]
Also, note $E_{2,n}\leq2C_{\xi}$ under Assumptions \ref{asm:unconfounded}, \ref{asm:reg} and due to trimming. Conclude that
\[
\left(1-\mathcal{P}_{1}\right)E_{2,n}\leq4C_{\xi}d_{p}\left[\exp\left(\frac{-n\varepsilon^{2}}{4C_{\xi}^{2}\zeta_{p}^{4}}\right)+K\exp\left(\frac{-n\varepsilon^{2}}{16K\tilde{C}_{\xi}^{2}\zeta_{p}^{4}}\right)\right].
\]
\paragraph*{Step 3} 
We now bound $E_{1,n}$. To simplify notation, for the rest of the paper, whenever we use ``$\mathbb{E}_{P^{n}}[\cdot]$'' on event $\mathcal{E}_n$, we  mean ``$\mathbb{E}_{P^{n}}[\cdot\mid\mathcal{E}_{n}\text{ holds}]$''. Note
for each $x\in\mathcal{X}$, 
\[
\tau^{2}(x)\left(\mathbf{1}\left\{ \tau(x)\geq0\right\} -\hat{\delta}^{\mathcal{T}}(w)\right)^{2}\leq\tau^{2}(x)\left(\mathbf{1}\left\{ \tau(x)\geq0\right\} -\hat{\delta}(w)\right)^{2}.
\]
Therefore, $L(\hat{\delta}^{\mathcal{T}},\tau)\leq L(\hat{\delta},\tau)$, implying on event $\mathcal{E}_n$,
\[
\mathbb{E}_{P^{n}}\left[L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\right]\leq\mathbb{E}_{P^{n}}\left[L(\hat{\delta},\tau)-L(\delta^{*},\tau)\right].
\]
Therefore, it suffices to bound $\mathbb{E}_{P^{n}}\left[L(\hat{\delta},\tau)-L(\delta^{*},\tau)\right]$ on event $\mathcal{E}_n$. To this end, observe
\begin{align}
 & L(\hat{\delta},\tau)-L(\delta^{*},\tau)\nonumber \\
= & \underset{T_{1n}}{\underbrace{L(\hat{\delta},\tau)-L(\delta^{*},\tau)-2\left[L_{n}^{o}(\hat{\delta},\eta_{0})-L_{n}^{o}(\delta^{*},\eta_{0})\right]}}+2\left(\underset{T_{2n}}{\underbrace{L_{n}^{o}(\tilde{\delta},\eta_{0})-L_{n}^{o}(\delta^{*},\eta_{0})}}\right)\nonumber \\
+ & 2\left(\underset{T_{3n}}{\underbrace{L_{n}^{o}(\hat{\delta},\eta_{0})-L_{n}^{o}(\tilde{\delta},\eta_{0})}}\right),\label{pf:lem1.1}
\end{align}
where for term $T_{2n}$, we have $L_{n}^{o}(\tilde{\delta},\eta_{0})=\inf_{\delta\in\mathcal{D}}L_{n}^{o}(\delta,\eta_{0})$
on event $\mathcal{E}_{n}$. Therefore,
on event $\mathcal{E}_{n}$,
\begin{align}
\mathbb{E}_{P^{n}}[T_{2n}] & =\mathbb{E}_{P^{n}}\left[\inf_{\delta\in\mathcal{D}}L_{n}^{o}(\delta,\eta_{0})-L_{n}^{o}(\delta^{*},\eta_{0})\right]\nonumber \\
 & \leq\inf_{\delta\in\mathcal{D}}\left\{ \mathbb{E}_{P^{n}}\left[L_{n}^{o}(\delta,\eta_{0})-L_{n}^{o}(\delta^{*},\eta_{0})\right]\right\} \nonumber \\
 & =\underset{\text{approximation error}}{\underbrace{\inf_{\delta\in\mathcal{D}}\left[L(\delta,\tau)-L(\delta^{*},\tau)\right]}},\label{pf:lem1.2}
\end{align}
where the equality used the observation that $L^{o}(\delta,\eta_{0})=L(\delta,\tau)$
for all $\delta\in\mathcal{D}$ and for $\delta^{*}$ as well. Conclude with the following lemma.

\begin{lem}
\label{lem:basic} On event $\mathcal{E}_{n}$, the following holds
for each $P^{n}\in\mathcal{P}^{n}$: 
\begin{align*}
\mathbb{E}_{P^{n}}\left[L(\hat{\delta},\tau)-L(\delta^{*},\tau)\right]
\leq \underset{\text{oracle rate}}{\underbrace{\mathbb{E}_{P^{n}}\left[T_{1n}\right]+2\sup_{P^{n}}\inf_{\delta\in\mathcal{D}}\left[L(\delta,\tau)-L(\delta^{*},\tau)\right]}+}\underset{\text{remainder estimation error}}{2\underbrace{\mathbb{E}_{P^{n}}\left[T_{3n}\right]}}.
\end{align*}
\end{lem}
\paragraph*{Step 4} We bound $\mathbb{E}_{P^{n}}\left[T_{1n}\right]$ and $\mathbb{E}_{P^{n}}\left[T_{3n}\right]$
on event $\mathcal{E}_n$ by establishing the following two lemmas below, and the conclusion
of the theorem follows immediately. 
\begin{lem}
\label{lem:main.1} Under Assumptions \ref{asm:unconfounded}-\ref{asm:stability}
and on event $\mathcal{E}_{n}$, we have, for some constant $\mathcal{C}_{1}$,
\begin{equation}
\sup_{P^{n}\in\mathcal{P}^{n}}\mathbb{E}_{P^{n}}\left[T_{1n}\right]\leq\mathcal{C}_{1}\frac{\sievedstar}{n}.\label{eq:fast.rate}
\end{equation}
\end{lem}
\begin{lem}
\label{lem:main.2} Under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}
and on event $\mathcal{E}_{n}$, the following statements hold:
\begin{itemize}
\item[(i)] For some constant $\mathcal{C}_{2}$, we have
\[
\sup_{P_{n}}\mathbb{E}_{P_{n}}\left[T_{3n}\right]\leq\mathcal{C}_{2}\left(R_{n,B}+R_{n,V}^{\text{}}\right).
\]
 %that depends on and $K$, $\underline{\pi}$,  $C_e$, $C_\gamma$, $C_\xi$, $\tilde{C}_\xi$, $C_M$ and  $\tilde{C}_M$.
\item[(ii)] The above rate improves to

\[
\sup_{P_{n}}\mathbb{E}_{P_{n}}\left[T_{3n}\right]\leq\mathcal{C}_{3}\left(R_{n,B}+R_{n,V}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)^{\frac{\alpha}{\alpha+2}}\right),
\]
with a suitably refined constant $\mathcal{C}_{3}$, if in addition,
Assumption \ref{asm:margin} holds and $n$ is also such that 
\[
\left(4C_{M}C_{\tau}^{-1}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)\right)^{\frac{1}{\alpha+2}}<t^{*}.
\]

\end{itemize}
\end{lem}

For completeness, we also restate
the result of \citet[Theorem 2]{KOHLER20001} below. 
\begin{lem}
\label{lem:kohler} Let $Z,Z_{1},\ldots Z_{n}$ be iid random variables
with support $\mathscr{Z}$. Let $K_{1},K_{2}\geq1$ and let $\mathscr{F}$
be a permissible class of functions $f:\mathscr{Z}\rightarrow\mathbb{R}$
such that 
\[
\left|f(z)\right|\leq K_{1},\text{ and }\mathbb{E}f^{2}(Z)\leq K_{2}\mathbb{E}f(Z).
\]
Denote by $N(\epsilon,\mathcal{G},d_{2,n})$ the $\epsilon-$covering
number of function class $\mathcal{G}$ with respect to the empirical
$L_{2}$ distance 
\[
d_{2,n}(g_{1},g_{2}):=\left\{ \frac{1}{n}\sum_{i=1}^{n}\left[g_{1}(Z_{i})-g_{1}(Z_{i})\right]^{2}\right\} ^{1/2},\text{ }g_{1},g_{2}\in\mathcal{G}.
\]
Let $0<\varepsilon<1$ and $\alpha>0$. Assume that 
\[
\sqrt{n}\varepsilon\sqrt{1-\varepsilon}\sqrt{\alpha}\geq288\max\left\{ 2K_{1},\sqrt{2K_{2}}\right\} ,
\]
and for all $z_{1},\ldots,z_{n}\in\mathscr{Z}$ and all $\delta\geq\frac{\alpha}{4}$,
\[
\sqrt{n}\varepsilon\left(1-\varepsilon\right)\delta\gtrsim288\max\left\{ K_{1},2K_{2}\right\} \int_{0}^{\sqrt{\delta}}\left(\log N\left(u,\left\{ f\in\mathscr{F}:\frac{1}{n}\sum_{i=1}^{n}f^{2}(Z_{i})\leq4\delta\right\} ,d_{2,n}\right)\right)^{1/2}du.
\]
Then, 
\begin{align*}
 & Pr\left\{ \sup_{f\in\mathscr{F}}:\frac{\left|\mathbb{E}f(Z)-\frac{1}{n}\sum_{i=1}^{n}f(Z_{i})\right|}{\alpha+\mathbb{E}f(Z)}>\varepsilon\right\}
\leq 50\exp\left(-\frac{n\alpha}{128\cdotp2304\max\left\{ K_{1}^{2},K_{2}\right\} }\right).
\end{align*}
\end{lem}


\section{Structural properties of B-splines}\label{sec:Bspline}
The performance of our proposal depends on the choice of the basis functions via $\sievedstar$, $\zeta_k$ and validity of Assumption \ref{asm:stability}.   If $W$ is bounded, the B-splines basis functions have the following important properties:\footnote{See, e.g.,  Lemmas 14.2,  14.4 and 15.2 in \cite*{gyorfi2006distribution} for a detailed discussion of the properties of univariate and multivariate B-splines.}
\begin{enumerate}
    \item[i)] $p_j(w)\geq0$ for all $j=1,...\sieved$ and all $w\in\mathcal{W}$,
    \item[ii)] $\sum_{j=1}^{\sieved}p_{j}(w)=1$ for all $w\in\mathcal{W}$,
\end{enumerate}
implying  that $\zeta_{p} \leq 1$ for B-splines. With the above two properties, we can verify that Assumption \ref{asm:stability} holds.  Note 
\[\sup_{w\in\mathcal{W}}|\hat{\delta}(w)|\leq\left\Vert \hat{\beta}\right\Vert _{\infty}\sup_{w\in\mathcal{W}}\left(\sum_{j=1}^{\sieved}|p_{j}(w)|\right),\]
where 
$\sup_{w\in\mathcal{W}}\left(\sum_{j=1}^{\sieved}|p_{j}(w)|\right)=1$ by i) and ii) above. Conclude that \[
\left\Vert \hat{B}_{n}\right\Vert _{1}\leq\tilde{C}_{\xi}\sup_{w\in\mathcal{W}}\left(\sum_{j=1}^{\sieved}|p_{j}(w)|\right)\leq\tilde{C}_{\xi}.\] 
Let  $\left\Vert A\right\Vert _{\max}:=\max_{i,j}{\left| a_{ij}\right|}$ for matrix $A=\{a_{ij}\}$. Suppose now $\hat{A}_n$ is positive definite with a  minimum eigenvalue bounded away from a constant $\underline{\lambda}_\varepsilon>0$. Then, we have
\begin{align*}
\left\Vert \hat{\beta}\right\Vert _{\infty} & \leq\left\Vert \hat{A}_{n}^{-1}\right\Vert _{\max}\left\Vert \hat{B}_{n}\right\Vert _{1}\leq\tilde{C}_{\xi}/\underline{\lambda}_\varepsilon.
\end{align*}
Therefore, $\sup_{w\in\mathcal{W}}|\hat{\delta}(w)|\cdot\mathbf{1}\{\lambda_{\text{min}}(\hat{A}_n)\geq\underline{\lambda}_\varepsilon\}\leq C_L:=\tilde{C}_{\xi}/\underline{\lambda}_\varepsilon$ as required by Assumption \ref{asm:stability}.  Moreover, for B-splines, each $f\in\mathcal{D}$ is a multivariate piecewise polynomial  with respect to some partition in $\mathcal{W}$. This implies that $f^{2}$ is also a multivariate piecewise polynomial with respect to the same partition. Thus, $\sievedstar\leq c_{B}\sieved$ for some constant $c_{B}$ that depends on the degree of the polynomial as well as the dimension of $W$. See also  \citet[][proof of Lemma 2 on p.11]{KOHLER20001} for additional discussions.



\section{Proofs of main propositions}

\subsection*{Proof of Proposition \ref{prop:population}}

Since $\delta$ can only condition on $W$, (\ref{eq:population.optimal})
can be solved by conditioning on almost all $w\in\mathcal{W}$:
\begin{equation}
\min_{\delta(w)\in[0,1]}\int\left\{ \tau(x)\left[\mathbf{1}\left\{ \tau(x)\geq0\right\} -\delta(w)\right]\right\} ^{\alpha}dF_{X|W}(x\mid w),\label{eq:population.optimal.conditioning}
\end{equation}
where $F_{X|W}(\cdotp\mid\cdotp)$ denotes the conditional cdf of
$X$ given $W$.

\textbf{Proof of statement (i)}. When $\alpha>1$, the objective function (\ref{eq:population.optimal.conditioning})
is convex and differentiable in $\delta(w)$. If  $\delta^*(w)\in(0,1)$, it 
must satisfy the following FOC:
\begin{equation}
-\int\left\{ \tau(x)\left[\mathbf{1}\left\{ \tau(x)\geq0\right\} -\delta^{*}(w)\right]\right\} ^{\alpha-1}\tau(x)dF_{X|W}(x\mid w)=0,\label{pf:prop.frac.1}
\end{equation}
for almost all $w\in\mathcal{W}$. Moreover, even if $\delta^*(w)\in\{0,1\}$, (\ref{pf:prop.frac.1}) still holds, as the LHS of (\ref{pf:prop.frac.1})
can be written as 
\begin{align*}
- & \int_{\tau(x)>0}\left\{ \tau(x)\left[1-\delta(w)\right]\right\} ^{\alpha-1}\tau(x)dF_{X|W}(x\mid w)\\
- & \int_{\tau(x)<0}\left\{ -\tau(x)\delta(w)\right\} ^{\alpha-1}\tau(x)dF_{X|W}(x\mid w).
\end{align*}
At $\delta(w)=1$, the FOC becomes 
\begin{align}\label{pf:foc.1}
- & \int_{\tau(x)<0}\underset{>0}{\underbrace{\left\{ -\tau(x)\right\} ^{\alpha-1}}}\tau(x)dF_{X|W}(x\mid w)\geq0,
\end{align}
implying $\delta(w)=1$ solves 
\eqref{eq:population.optimal} only when \eqref{pf:prop.frac.1} holds. Analogously, when $\delta(w)=0$, the FOC becomes 
\begin{align}\label{pf:foc.0}
- & \int_{\tau(x)>0}\underset{>0}{\underbrace{\left\{ \tau(x)\right\} ^{\alpha}}}dF_{X|W}(x\mid w)\leq0,
\end{align}
implying $\delta(w)=0$ solves 
\eqref{eq:population.optimal} also only when \eqref{pf:prop.frac.1} holds. Finally, note the inequality in \eqref{pf:foc.1} is strict unless $\int_{\tau(x)<0}dF_{X|W}(x\mid w)=0$, and  the inequality in \eqref{pf:foc.0} is strict unless $\int_{\tau(x)>0}dF_{X|W}(x\mid w)=0$.
This completes the proof for statement (i). 

\textbf{Proof of statement (ii)}. When $\alpha=1$, (\ref{eq:population.optimal.conditioning})
is written as 
\[
\min_{\delta(w)\in[0,1]}\int\tau(x)\mathbf{1}\left\{ \tau(x)\geq0\right\} dF_{X|W}(x\mid w)-\delta(w)\int\tau(x)dF_{X|W}(x\mid w).
\]
%leading to an optimal rule  $\mathbf{1}\left\{ \int\tau(x)dF_{X|W}(x\mid w)\geq0\right\}
%$,

The conclusion follows by noting, due to law of iterated expectations, 
\begin{align*}
\int\tau(x)dF_{X|W}(x\mid w) & =\mathbb{E}\left[\mathbb{E}\left[Y(1)-Y(0)|X\right]\mid W=w\right]\\
 & =\mathbb{E}\left[Y(1)-Y(0)\mid W=w\right]=\tau(w).
\end{align*}

\subsection*{Proof of Proposition \ref{prop:debias}}
% We view $L(\delta,\tau)$ as a finite dimensional parameter $\theta\in\mathbb{R}$
