where 
\begin{align*}
 & D_{1}(z,\gamma_{1}+t(\tilde{\gamma}_{1}-\gamma_{1}))\\
:= & 2\left(\gamma_{1}(x)-\gamma_{0}(x)\right)\left(\mathbf{1}\left\{ \gamma_{1}(x)-\gamma_{0}(x)\geq0\right\} -\delta(w)\right)^{2}\left(\gamma_{1}(x)+t(\tilde{\gamma}_{1}(x)-\gamma_{1}(x))\right).
