:= & -2\left(\gamma_{1}(x)-\gamma_{0}(x)\right)\left(\mathbf{1}\left\{ \gamma_{1}(x)-\gamma_{0}(x)\geq0\right\} -\delta(w)\right)^{2}\left(\gamma_{0}(x)+t(\tilde{\gamma}_{0}(x)-\gamma_{0}(x))\right).
\end{align*}

\paragraph{Step 2} Derive the integral forms of $\mathbb{E}\left[D_{1}(Z,\cdotp)\right]$
and $\mathbb{E}\left[D_{0}(Z,\cdotp)\right]$. In our case, for all $\tilde{\gamma}_{1}\in\mathcal{H}_1$, we have
