\end{align*}
where $\varsigma_{0}(d,x):=-2\left(\gamma_{1}(x)-\gamma_{0}(x)\right)\left(\mathbf{1}\left\{ \gamma_{1}(x)-\gamma_{0}(x)\geq0\right\} -\delta(w)\right)^{2}\frac{1-d}{1-\pi(x)}$
is such that 
\[
\mathbb{E}_{t}\left[\varsigma_{0}(d,x)\gamma_{0}(X,t)\right]=\mathbb{E}_{t}\left[\varsigma_{0}(d,x)Y\right],
\]
and $\gamma_{0}(X,t):=\arg\min_{\tilde{\gamma}_{0}\in\mathcal{H}_{0}}\mathbb{E}_{t}\left[\left(Y-\tilde{\gamma}_{0}(x)\right)^{2}\right]$. The conclusion then follows by invoking \citet[][Proposition 4]{newey1994asymptotic}. 

