\subsection*{Proof of Proposition \ref{prop:parametric}}

Statement (i) and the first part of statement (ii) directly follows
from applying Theorem \ref{thm:main}. We show the asymptotic
distribution result under Assumptions \ref{asm:unconfounded}-\ref{asm:margin}. With a slight abuse of notation, let $\delta^{*}(w)=\left(\beta^{*}\right)^{\prime}p(w)$,
where $\beta^{*}=A^{-1}B$. Note this $\delta^*$ is the unique rule in $\mathcal{D}$ that solves \eqref{eq:loss.proposal}. Moreover, note
\begin{align*}
A & =\mathbb{E}\left[\tau^{2}(Z)p(W)p(W)^{\prime}\right]=\mathbb{E}\left[\xi(Z)p(W)p(W)^{\prime}\right],\\
B & =\mathbb{E}\left[\tau^{2}p(W)\mathbf{1}\left\{ \tau(X)\geq0\right\} \right]=\mathbb{E}\left[\xi(Z)p(W)\mathbf{1}\left\{ \tau(X)\geq0\right\} \right].
\end{align*}
\paragraph*{Step 1:} Conclude from Lemmas \ref{lem:remainder.1}, \ref{lem:remainder.2},
\ref{lem:remainder.5} and \ref{lem:remainder.6} that 
$\sqrt{n}\left\Vert \hat{\beta}-\tilde{\beta}\right\Vert =o_{p}(1)$,$\sqrt{n}\left(\tilde{\beta}-\beta^{*}\right)\overset{d}{\rightarrow}N(0,A^{-1}VA^{-1})$,
implying $\sqrt{n}\left(\hat{\beta}-\beta^{*}\right)\overset{d}{\rightarrow}N(0,A^{-1}VA^{-1})$ and $\hat{\beta}-\beta^{*}=O_{p}\left(\frac{1}{\sqrt{n}}\right)$.

\paragraph*{Step 2:}  We show that $\hat{\mathbf{p}}:=\int_{w:\hat{\delta}(w)\notin[0,1]}dF_{W}(w)=o_{p}(1)$.
Note $\left|\hat{\delta}(w)-\delta^{*}(w)\right|\leq\left\Vert \hat{\beta}-\beta^{*}\right\Vert \zeta_{p}$
for all $w\in\mathcal{W}$. With the conclusions of step 1, we have
\[
\sup_{w\in\mathcal{W}}\left|\hat{\delta}(w)-\delta^{*}(w)\right|=O_{p}\left(\frac{1}{\sqrt{n}}\right),
\]
implying that for some $C_{\epsilon}>0$ and all $n$ sufficiently
large,
\[
Pr\left\{ \sup_{w\in\mathcal{W}}\left|\hat{\delta}(w)-\delta^{*}(w)\right|>\frac{C_{\epsilon}}{\sqrt{n}}\right\} <\epsilon
\]
for any $\epsilon>0$. Let $\mathcal{E}_{\hat{\delta}}$ be the event
that $\sup_{w\in\mathcal{W}}\left|\hat{\delta}(w)-\delta^{*}(w)\right|\leq\frac{C_{\epsilon}}{\sqrt{n}}$.
Then, for any $\nu>0$
\begin{align*}
Pr\left\{ \hat{\mathbf{p}}>\nu\right\} \leq & Pr\left\{ \hat{\mathbf{p}}>\nu\mid\mathcal{E}_{1,n}\right\} Pr\left\{ \mathcal{E}_{1,n}\right\} +\left(1-Pr\left\{ \mathcal{E}_{1,n}\right\} \right)\\
\leq & Pr\left\{ \hat{\mathbf{p}}>\nu\mid\mathcal{E}_{1,n}\right\} +\epsilon.
\end{align*}
Of note,
\begin{align*}
Pr\left\{ \hat{\mathbf{p}}>\nu\mid\mathcal{E}_{1,n}\right\} = & Pr\left\{ \int_{w:\hat{\delta}(w)\in\left[-\frac{C_{\epsilon}}{\sqrt{n}},0\right]\cup\left[1,\frac{C_{\epsilon}}{\sqrt{n}}+1\right]}dF_{W}(w)>\nu\mid\mathcal{E}_{1,n}\right\}\leq \epsilon
\end{align*}
for $n$ sufficiently large. Therefore, for all $n$ sufficiently large,
$Pr\left\{ \hat{\mathbf{p}}>\nu\right\} \leq2\epsilon.$ Conclude
$\hat{\mathbf{p}}=o_{p}(1)$ by the arbitrariness of $\nu$ and $\epsilon$. 
\paragraph{Step 3:} We now analyze the asymptotic behavior of $n\left(L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\right)$.
Note $\delta^{*}$ satisfies the following condition, 
\[
\mathbb{E}\left[\tau^{2}(X)\left(\mathbf{1}\left\{ \tau(X)\geq0\right\} -\delta^{*}(W)\right)\mid W\right]=0,
\]
implying $n\left(L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\right) =n\mathbb{E}\left[\tau^{2}(X)\left(\hat{\delta}^{\mathcal{T}}(W)-\delta^{*}(W)\right)^{2}\right]$
by Taylor's theorem. Conclude that 
\begin{align*}
n\left(L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\right) & =T_{4,n}+T_{5,n},
\end{align*}
where 
\begin{align*}
T_{4,n} & =n\mathbb{E}\left[\tau^{2}(X)\left(\hat{\delta}^{\mathcal{T}}(W)-\delta^{*}(W)\right)^{2}\mathbf{1}\left\{ \hat{\delta}(W)\in[0,1]\right\} \right],\\
T_{5,n} & =n\mathbb{E}\left[\tau^{2}(X)\left(\hat{\delta}^{\mathcal{T}}(W)-\delta^{*}(W)\right)^{2}\mathbf{1}\left\{ \hat{\delta}(W)\notin[0,1]\right\} \right].
\end{align*}
For $T_{5,n}$, note 
\begin{align*}
\left|T_{5,n}\right| & \leq n\mathbb{E}\left[\tau^{2}(X)\left(\hat{\delta}(W)-\delta^{*}(W)\right)^{2}\mathbf{1}\left\{ \hat{\delta}(W)\notin[0,1]\right\} \right]\\
 & \leq n\left(\hat{\beta}-\beta^{*}\right)^{\prime}\hat{\mathcal{A}}\left(\hat{\beta}-\beta^{*}\right),
\end{align*}
where
\[
\hat{\mathcal{A}}:=\mathbb{E}\left[\tau^{2}(X)p(W)p^{\prime}(W)\mathbf{1}\left\{ \hat{\delta}(W)\notin[0,1]\right\} \right].
\]
Furthermore, note $\left\Vert \hat{\mathcal{A}}\right\Vert \leq C_{\xi}\zeta_{p}^{2}\hat{\mathbf{p}}=o_{p}(1)$
by conclusions of Step 2, and $\hat{\beta}-\beta^{*}=O_{p}\left(\frac{1}{\sqrt{n}}\right)$
by conclusions from Step 1. Conclude that $T_{5,n}=o_{p}(1)$. For term $T_{4,n}$, note 
\begin{align*}
T_{4,n} & =\mathbb{E}\left[\tau^{2}(X)\left(\hat{\delta}(W)-\delta^{*}(W)\right)^{2}\mathbf{1}\left\{ \hat{\delta}(W)\in[0,1]\right\} \right]=T_{4,1,n}-T_{4,2,n},
\end{align*}
where
\begin{align*}
T_{4,1,n} & :=\left(\sqrt{n}\left(\hat{\beta}-\beta^{*}\right)\right)^{\prime}A\left(\sqrt{n}\left(\hat{\beta}-\beta^{*}\right)\right)\overset{d}{\rightarrow}N(0,\Omega)AN(0,\Omega),
\end{align*}
and 
\begin{align*}
T_{4,2,n} & :=\left(\sqrt{n}\left(\hat{\beta}-\beta^{*}\right)\right)^{\prime}\hat{\mathcal{A}}\left(\sqrt{n}\left(\hat{\beta}-\beta^{*}\right)\right) =o_{p}(1)
\end{align*}
by conclusions from step 2. As $T_{5,n}=o_{p}(1),$ $T_{4,2,n}=o_{p}(1)$,
we conclude that the asymptotic distribution of $n\left(L(\hat{\delta}^{\mathcal{T}},\tau)-L(\delta^{*},\tau)\right)$
is determined by $T_{4,1,n}$, completing the proof. 



\section{Minimax lower bound}\label{sec:lower.bound}

To gauge the optimality of the convergence rate derived in Theorem \ref{thm:main} in case of a nonparametric $\delta^*$, a minimax lower bound is needed. To proceed, we introduce the following standard class of smooth functions.  
\begin{defn}[smoothness]
Let $s=s_{0}+t$ for some $s_{0}\in\mathbb{N}_{+}$ and $0<t\leq1$,
and let $C>0$. A function $f:\mathbb{R}^{d}\rightarrow\mathbb{R}$
is $(s,C)$-smooth if for every $\alpha=(\alpha_{1},\ldots,\alpha_{d})$,
$\alpha_{i}\in\mathbb{N}_{+}$, $\sum_{i=1}^{d}\alpha_{i}=s_{0}$,
the partial derivative $\frac{\partial^{s_{0}}}{\partial x_{1}^{\alpha_{1}}\cdots\partial x_{d}^{\alpha_{d}}}$
exists and satisfies 
\[
\left|\frac{\partial^{s_{0}}f}{\partial x_{1}^{\alpha_{1}}\cdots\partial x_{d}^{\alpha_{d}}}(x)-\frac{\partial^{s_{0}}f}{\partial x_{1}^{\alpha_{1}}\cdots\partial x_{d}^{\alpha_{d}}}(z)\right|\leq C\left\Vert x-z\right\Vert ^{t},x,z\in\mathbb{R}^{d}.
\]
Denote by $\mathcal{F}^{(s,C)}$ the set of all $(s,C)$-smooth functions
$f:\mathbb{R}^{d}\rightarrow\mathbb{R}$. 
\end{defn}
We then consider the following class of distributions,  a subset of $\mathcal{P}$, in which the form of $\delta^*$ is simple and smooth and $W$ is uniformly distributed in $[0,1]^{d_W}$. 

\begin{defn}\label{def:DGP_lower_bound}
Let $X=\left(X_{1},W\right)$. Denote by $\mathcal{P}(s,C)\subseteq\mathcal{P}$
the class of distributions of $(Y(1),Y(0),D,X)$ such that:
\begin{itemize}
\item[(i)] $W$ is uniformly distributed in $[0,1]^{d_{W}}$; 
\item[(ii)] $X_{1}=\text{sgn}\left(m(W)+\varepsilon\right)$,\footnote{We define $\text{sgn}(0):=1$ as a convention.}
where $m:\mathbb{R}^{d_{W}}\rightarrow[0,1]$ is such that $m\in\mathcal{F}(s,C)$,
and $\varepsilon$ is uniformly distributed in $[-1,0]$ and independent
of $W$;
\item[(iii)] $\tau(x_{1},w)=x_{1}$ for all $x_{1}\in\left\{ -1,1\right\} $,
$w\in[0,1]^{d_{W}}$, where 
\begin{align*}
\tau(x_{1},w) & =\mathbb{E}[Y(1)\mid X_{1}=x_{1},W=w]-\mathbb{E}[Y(0)\mid X_{1}=x_{1},W=w];
\end{align*}
\item[(iv)] The joint distribution of $(Y(1),Y(0),D,X)$ satisfies Assumption \ref{asm:unconfounded}. 
\end{itemize}
In the $\mathcal{P}(s,C)$ class defined above, $\tau(x)=\tau(x_{1},w)=x_{1}\in\{-1,1\}$,
so that $\tau^{2}(x)=1$ for all $x$. It follows the optimal rule
($\alpha=2$) becomes 
\begin{align*}
\delta^{*}(W) & =\mathbb{E}\left[\mathbf{1}\{X_{1}\geq0\}\mid W\right] =Pr\left\{ X_{1}=1\mid W\right\} =m(W),
\end{align*}
a conditional expectation of a bounded outcome $\mathbf{1}\{X_{1}\geq0\}$. Thus, we can  study a minimax lower bound for $\delta^*$ by assessing a minimax lower bound for the conditional expectation function, for which we know relatively well.  Inspired by \citet[][Theorem 3.2 and Problem 3.3]{gyorfi2006distribution}, we derive the following
result. 
\end{defn}

\begin{thm}\label{thm:lower.bound}
For the class $\mathcal{P}(s,C)$, consider any rule
$\delta_{n}$ that depends on data $Z^{n}$. Then, we have
\[
\liminf_{n\rightarrow\infty}\frac{\sup_{P\in\mathcal{P}(s,c)}\mathbb{E}_{P_{n}}\left[L(\delta_{n},\tau)-L(\delta^{*},\tau)\right]}{C^{\frac{2d_{W}}{6s+3d_{W}}}n^{-\frac{2s}{2s+d_{W}}}}\geq C_{1}
\]
for some $C_{1}>0$ independent of $C$.
\end{thm}

Theorem \ref{thm:lower.bound} is established with the following useful lemma.

\begin{lem}\label{lem:Bayes_classification}
Let $u=(u_{1},\ldots, u_{N})$ be a vector of dimension $N$
such that $u_{j}\in[0,1]$ for all $j=1\ldots N$, and let $\mathrm{C}$
be a random variable taking values in $\left\{ -1,1\right\} $ with
equal probability. Write $\mathbf{Y}=(Y_{1},\ldots,Y_{N})^{\prime}$,
where 
\[
Y_{j}=\text{ \ensuremath{\frac{1}{2}}+\ensuremath{\frac{1}{2}}}\mathrm{C}u_{j}+\varepsilon_{j},j=1\ldots N,
\]
and $\left\{ \varepsilon_{j}\right\} _{j=1}^{N}$ are iid with a uniform
distribution in $[-1,0].$ Let $g^{*}:\mathbb{R}^{N}\rightarrow\left\{ -1,1\right\} $
be the Bayes  decision for $\mathrm{C}$ based on \textup{$\mathbf{Y}$}.
It follows 
\[
Pr\left\{ g^{*}(\mathbf{Y})\neq\mathrm{C}\right\} \geq 1-N\left\Vert u\right\Vert .
\]
\end{lem}




