\subsection{Proof of Lemma \ref{lem:main.1}}

Recall
\[
T_{1n}=L(\hat{\delta},\tau)-L(\delta^{*},\tau)-2\left[L_{n}^{o}(\hat{\delta},\eta_{0})-L_{n}^{o}(\delta^{*},\eta_{0})\right].
\]
And note for all $\delta\in\mathcal{D}$ as well as $\delta^{*}$,
\[
L^{o}(\delta,\eta_{0})=L(\delta,\tau),\quad L^{o}(\delta^{*},\eta_{0})=L(\delta^{*},\tau).
\]
To ease notational burden, in what follows, we write $L^{o}(\delta):=L^{o}(\delta,\eta_{0})$,
$L(\delta):=L(\delta,\tau)$ for any $\delta$. On event $\mathcal{E}_n$, the minimum eigenvalue of $\hat{A}_n$ is bounded away from $\underline{\lambda}-\varepsilon$. Therefore, Assumption \ref{asm:stability} implies that, for some $C_L$, $\hat{\delta}$ is an element of the space 
\[
\mathcal{D}_{C_L}:=\mathcal{D}_{n,C_L}:=\left\{ f(w)=\sum_{j=1}^{\sieved}\beta_{j}p_{j}(w):\sup_{w}|f(w)|\leq C_L\right\} .
\] 
Then, for all $t>0$ and on event $\mathcal{E}_{n}$, we have\footnote{The corresponding probability refers to the conditional probability on event $\mathcal{E}_{n}$.} 
\begin{align*}
Pr\{T_{1n}>t\} & \leq Pr\left\{ \exists\delta\in\mathcal{D}_{C_L}:L(\delta)-L(\delta^{*})-2\left[L_{n}^{o}(\delta)-L_{n}^{o}(\delta^{*})\right]>t\right\} \\
 & =Pr\left\{ \exists\delta\in\mathcal{D}_{C_L}:L^{o}(\delta)-L^{o}(\delta^{*})-2\left[L_{n}^{o}(\delta)-L_{n}^{o}(\delta^{*})\right]>t\right\} \\
 & =Pr\{\exists\delta\in\mathcal{D}_{C_L}:2\left[L^{o}(\delta)-L^{o}(\delta^{*})\right]-2\left[L_{n}^{o}(\delta)-L_{n}^{o}(\delta^{*})\right]\\
 & >t+L^{o}(\delta)-L^{o}(\delta^{*})\}\\
 & =Pr\left\{ \exists\delta\in\mathcal{D}_{C_L}:\frac{L^{o}(\delta)-L^{o}(\delta^{*})-\left[L_{n}^{o}(\delta)-L_{n}^{o}(\delta^{*})\right]}{t+L^{o}(\delta)-L^{o}(\delta^{*})}>\frac{1}{2}\right\} \\
 & \leq Pr\left\{ \sup_{\delta\in\mathcal{D}_{C_L}}\frac{\left|L^{o}(\delta)-L^{o}(\delta^{*})-\left[L_{n}^{o}(\delta)-L_{n}^{o}(\delta^{*})\right]\right|}{t+L^{o}(\delta)-L^{o}(\delta^{*})}>\frac{1}{2}\right\} .
\end{align*}
We now apply Lemma \ref{lem:kohler} to bound the above term and to
derive an upper bound for $\mathbb{E}_{P^{n}}T_{1n}$. Let $\left(Z_{1},Z_{2},\ldots Z_{n}\right)$
be iid copies of $Z=(Y,D,X)$. For each $f\in\mathcal{D}_{C_L}$, write
\[
g_{f}(z):=\xi(z)\left(\mathbf{1}\{\tau(x)\geq0\}-f(w))\right)^{2}-\xi(z)\left(\mathbf{1}\{\tau(x)\geq0\}-\delta^{*}(w)\right)^{2},
\]
where recall 
\begin{align*}
\xi(z) & =\left[\gamma_{1}(x)-\gamma_{0}(x)\right]^{2}+d\omega_{1}(x)(y-\gamma_{1}(x))-\left(1-d\right)\omega_{0}(x)(y-\gamma_{0}(x)),\\
f(w) & =\beta^{\prime}p(w),\sup_{w\in\mathcal{W}}\left|f(w)\right|\leq C_L.
\end{align*}
Consider the following functional class $\mathcal{G}:=\left\{ g=g_{f}(z)\mid f\in\mathcal{D}_{C_L}\right\}$. Under Assumptions \ref{asm:unconfounded} and \ref{asm:reg}, there
exists some finite $K_{1}\geq1$ such that 
\begin{align*}
\left|g_{f}(z)\right| & \leq\left|\xi(z)\right|\left(1+L\right)^{2}+\left|\xi(z)\right|\leq K_{1},
\end{align*}
for all $g_{f}\in\mathcal{G}$ and $z\in\mathcal{Z}$. Furthermore, we can equivalently write each $g_{f}\in\mathcal{G}$ as 
\begin{align*}
g_{f}(z) & =\xi(z)\left[\left(\delta^{*}(w)-f(w)\right)^{2}+2\left(\mathbf{1}\{\tau(x)\geq0\}-\delta^{*}(w)\right)\left(\delta^{*}(w)-f(w)\right)\right].
\end{align*}
Moreover, for each $g_{f}\in\mathcal{G}$, 
\begin{align*}
 & \mathbb{E}\xi(Z)\left[\left(\mathbf{1}\{\tau(X)\geq0\}-\delta^{*}(W)\right)\left(\delta^{*}(W)-f(W)\right)\right]\\
= & \mathbb{E}\left[\tau(X)^{2}\left(\mathbf{1}\{\tau(X)\geq0\}-\delta^{*}(W)\right)\left(\delta^{*}(W)-f(W)\right)\right]=  0,
\end{align*}
where the last equality follows from the fact that $\delta^{*}$ must
satisfy the following condition (due to Proposition \ref{prop:population}(i))
\begin{align*}
\mathbb{E}\left[\tau(X)^{2}\left(\mathbf{1}\{\tau(X)\geq0\}-\delta^{*}(W)\right)\mid W\right]=0.
\end{align*}
As a result, we conclude 
\begin{align*}
\mathbb{E}[g_{f}(Z)] & =\mathbb{E}\left[\xi(Z)\left(\delta^{*}(W)-f(W)\right)^{2}\right]=\mathbb{E}\left[\tau^{2}(X)\left(\delta^{*}(W)-f(W)\right)^{2}\right],\forall g_{f}\in\mathcal{G}.
\end{align*}
Moreover, note 
\[
g_{f}^{2}(z)=\xi^{2}(z)\left(\delta^{*}(w)-f(w)\right)^{2}\left[\left(\delta^{*}(w)-f(w)\right)+2\left(\mathbf{1}\{\tau(x)\geq0\}-\delta^{*}(w)\right)\right]^{2}.
\]
It follows then 
\begin{align*}
\mathbb{E}[g_{f}^{2}(Z)] & =\mathbb{E}\left\{ \xi^{2}(Z)\left[2\mathbf{1}\{\tau(X)\geq0\}-f(W)-\delta^{*}(W)\right]^{2}\left[\delta^{*}(W)-f(W)\right]^{2}\right\} \\
 & \leq\left(3+L\right)^{2}\mathbb{E}\left\{ \xi^{2}(Z)\left[\delta^{*}(W)-f(W)\right]^{2}\right\} ,
\end{align*}
where note 
\begin{align*}
 & \mathbb{E}\left\{ \xi^{2}(Z)\left[\delta^{*}(W)-f(W)\right]^{2}\right\} \\
= & \mathbb{E}\left\{ \tau^{4}(X)\left[\delta^{*}(W)-f(W)\right]^{2}\right\} \\
+ & \mathbb{E}\left\{ \left(\frac{2De_{1}}{\pi(X)}-\frac{\left(1-D\right)2e_{0}}{1-\pi(X)}\right)^{2}\tau^{2}(X)\left[\delta^{*}(W)-f(W)\right]^{2}\right\} .
\end{align*}
Furthermore, under Assumptions \ref{asm:unconfounded} and \ref{asm:reg},
observe that 
\[
\mathbb{E}\left\{ \tau^{4}(X)\left[\delta^{*}(W)-f(W)\right]^{2}\right\} \leq\sup_{x\in\mathcal{X}}\tau^{2}(x)\mathbb{E}[g_{f}(Z)],
\]
and 
\begin{align*}
 & \mathbb{E}\left\{ \left(\frac{2De_{1}}{\pi(X)}-\frac{\left(1-D\right)2e_{0}}{1-\pi(X)}\right)^{2}\tau^{2}(X)\left[\delta^{*}(W)-f(W)\right]^{2}\right\} \\
\leq & \sup_{x\in\mathcal{X}}\left(\frac{4\mathbb{E}[e_{1}^{2}\mid X=x]}{\pi^{2}(x)}+\frac{4\mathbb{E}[e_{1}^{2}\mid X=x]}{\left(1-\pi(x)\right)}\right)\mathbb{E}[g_{f}(Z)].
\end{align*}
Thus, we conclude that there exists a finite number $K_{2}\geq1$
such that 
$\mathbb{E}[g_{f}^{2}(Z)]\leq K_{2}\mathbb{E}g_{f}(Z)
$.
Denote by $N(\epsilon,\mathcal{G},d_{2,n})$ the covering number for
$\mathcal{G}$ with respect to the empirical $L_{2}$ distance 
\[
d_{2,n}(g_{f_{1}},g_{f_{2}}):=\left\{ \frac{1}{n}\sum_{i=1}^{n}\left[g_{f_{1}}(Z_{i})-g_{f_{2}}(Z_{i})\right]^{2}\right\} ^{1/2}.
\]
Note for each $g_{f}\in\mathcal{G}$, 
\begin{align*}
g_{f}(z) & =\xi(z)\left(\mathbf{1}\{\tau(x)\geq0\}-f(w)\right)^{2}-\xi(z)\left(\mathbf{1}\{\tau(x)\geq0\}-\delta^{*}(w)\right)^{2}\\
 & =\xi(z)\left(\mathbf{1}\{\tau(x)\geq0\}-2f(w)+f^{2}(w)\right)-\xi(z)\left(\mathbf{1}\{\tau(x)\geq0\}-\delta^{*}(w)\right)^{2},
\end{align*}
implying $\mathcal{G}$ is a subset of a linear vector space with dimension $d_\mathcal{G}$, where $d_\mathcal{G}\leq1+\sieved+\sievedstar\leq1+2\sievedstar$. 
%Denote
%by $d_{p}^{*}$ the dimension of $\mathcal{G}$. Each $f\in\mathcal{D}_{C_L}$
%is a multivariate piecewise polynomial with respect to some partition
%in $\mathcal{W}$. This implies that $f^{2}$ is also a multivariate
%piecewise polynomial with respect to the same partition. Thus, $d_{p}^{*}\leq c_{B}\sieved$
%for some constant $c_{B}$ that depends on the degree of the polynomial
%as well as the dimension of $W$. 
It follows from \citet[Corollary 2.6]{geer2000empirical}
that 
\[
N\left(\epsilon,\left\{ g_{f}\in\mathcal{G}:\frac{1}{n}\sum_{i=1}^{n}\left[g_{f}(Z_{i})\right]^{2}\leq4\delta\right\} ,d_{2,n}\right)\leq\left(\frac{8\sqrt{\delta}+\epsilon}{\epsilon}\right)^{d_\mathcal{G}+1},
\]
Hence, integration by change-of-variable yields 
\begin{align*}
 & \int_{0}^{\sqrt{\delta}}\left\{ \log N\left(\epsilon,\left\{ g_{f}\in\mathcal{G}:\frac{1}{n}\sum_{i=1}^{n}\left[g_{f}(Z_{i})\right]^{2}\leq4\delta\right\} ,d_{2,n}\right)\right\} ^{1/2}d\epsilon\\
\leq & \left(d_\mathcal{G}+1\right)^{1/2}\int_{0}^{\sqrt{\delta}}\left\{ \log\left(\frac{8\sqrt{\delta}+\epsilon}{\epsilon}\right)\right\} ^{1/2}d\epsilon\\
= & \left(d_\mathcal{G}+1\right)^{1/2}\sqrt{\delta}\int_{0}^{1}\left\{ \log\left(1+\frac{8}{t}\right)\right\} ^{1/2}dt\\
= & \left(d_\mathcal{G}+1\right)^{1/2}\sqrt{\delta}\int_{1}^{\infty}\frac{\sqrt{\log\left(1+8u\right)}}{u^{2}}du\\
\leq & \left(d_\mathcal{G}+1\right)^{1/2}\sqrt{\delta}\int_{1}^{\infty}\frac{\sqrt{8u}}{u^{2}}du(\log\left(1+x\right)\leq x\text{ for }x>0)\\
= & 2\sqrt{2}\left(d_\mathcal{G}+1\right)^{1/2}\sqrt{\delta}\int_{1}^{\infty}u^{-\frac{3}{2}}du\\
= & 4\sqrt{2}\left(d_\mathcal{G}+1\right)^{1/2}\sqrt{\delta}.
\end{align*}
Thus, for $\varepsilon=\frac{1}{2}$ in the conditions of Lemma \ref{lem:kohler},
there exists some finite constant $c_{K_{1},K_{2}}>0$ such that and
for all 
\[
\alpha\geq c_{K_{1},K_{2}}\frac{d_\mathcal{G}+1}{n},\delta\geq4\alpha,
\]
all the conditions of Lemma \ref{lem:kohler} are met so that we conclude
for all $\alpha=c_{K_{1},K_{2}}\frac{d_\mathcal{G}+1}{n}$, we have that
there exists some finite constant $\overline{c}_{K_{1},K_{2}}>0$
such that for all $t\geq c_{K_{1},K_{2}}\frac{d_\mathcal{G}+1}{n}$, we
have 
\begin{align*}
Pr\{T_{1n}>t\}\leq & 50\exp\left(-\frac{nt}{\overline{c}_{K_{1},K_{2}}}\right).
\end{align*}
Then, for each $P^{n}\in\mathcal{P}^{n}$, 
\begin{align*}
\mathbb{E}_{P^{n}}[T_{1n}] & \leq\int_{0}^{\infty}Pr\{T_{1n}>t\}dt\\
 & \leq c_{K_{1},K_{2}}\frac{d_\mathcal{G}+1}{n}+\int_{C_{K_{1},K_{2}}\frac{d_\mathcal{G}+1}{n}}^{\infty}50\exp\left(-\frac{nt}{\overline{c}_{K_{1},K_{2}}}\right)dt\\
 & =c_{K_{1},K_{2}}\frac{d_\mathcal{G}+1}{n}+\frac{50\overline{c}_{K_{1},K_{2}}}{n}\exp\left(-\frac{c_{K_{1},K_{2}}\left(d_\mathcal{G}+1\right)}{\overline{c}_{K_{1},K_{2}}}\right),
\end{align*}
implying there exists some constant $\mathcal{C}_{1}$ that only depends
on $K_{1}$, $K_{2}$ %and $c_{B}$ 
such that 
\[
\mathbb{E}_{P^{n}}[T_{1n}]\leq\mathcal{C}_{1}\frac{\sievedstar}{n}.
\]
As $\sievedstar$ and $\mathcal{C}_{1}$ does not depend on $P^{n}$,
the conclusion of the lemma follows.




\subsection{Proof of Lemma \ref{lem:main.2}}
On event $\mathcal{E}_{n}$, we have
\[
\hat{\beta}=\hat{A}_{n}^{-1}\hat{B}_{n},\quad\tilde{\beta}=A_{n}^{-1}B_{n},
\]
and  $\tilde{\delta}$ solves the oracle
problem  $\min_{\delta=\beta^{\prime}p,\beta\in\mathbb{R}^{\sieved}}L_{n}^{o}(\delta)$, satisfying the following FOC:
\[
\frac{1}{n}\sum_{i=1}^{n}\left[\xi_{i}\left(\mathbf{1}\left\{ \tau_{i}\geq0\right\} -\tilde{\delta}_{i}\right)p_i\right]=0.
\]
Then, Taylor's theorem implies
\begin{align*}
 0\leq& L_{n}^{o}(\hat{\delta},\eta_{0})-L_{n}^{o}(\tilde{\delta},\eta_{0})\\
= & \frac{1}{n}\sum_{i=1}^{n}\xi_{i}\left(\mathbf{1}\left\{ \tau_{i}\geq0\right\} -\hat{\delta}_{i}\right)^{2}-\frac{1}{n}\sum_{i=1}^{n}\xi_{i}\left(\mathbf{1}\left\{ \tau_{i}\geq0\right\} -\tilde{\delta}_{i}\right)^{2}\\
= & (\hat{\beta}-\tilde{\beta})^{\prime}A_{n}(\hat{\beta}-\tilde{\beta}),
\end{align*}
where 
\[
\hat{\beta}-\tilde{\beta}=A_{n}^{-1}\left(A_{n}-\hat{A}_{n}\right)\hat{A}_{n}^{-1}\hat{B}_{n}+A_{n}^{-1}\left(\hat{B}_{n}-B_{n}\right).
\]
Furthermore, on event $\mathcal{E}_{n}$, algebra shows 
\begin{align*}
 L_{n}^{o}(\hat{\delta},\eta_{0})-L_{n}^{o}(\tilde{\delta},\eta_{0})= & \hat{B}_{n}^{\prime}\hat{A}_{n}^{-1}\left(A_{n}-\hat{A}_{n}\right)A_{n}^{-1}\left(A_{n}-\hat{A}_{n}\right)\hat{A}_{n}^{-1}\hat{B}_{n}\\
+&2\hat{B}_{n}^{\prime}\hat{A}_{n}^{-1}\left(A_{n}-\hat{A}_{n}\right)A_{n}^{-1}\left(\hat{B}_{n}-B_{n}\right)\\
+&\left(\hat{B}_{n}-B_{n}\right)^{\prime}A_{n}^{-1}\left(\hat{B}_{n}-B_{n}\right).
\end{align*}
Also note $\left\Vert \hat{B}_{n}\right\Vert \leq\tilde{C}_{\xi}\zeta_{p}$.
Applying triangle and Cauchy-Schwarz inequalities yields:
\begin{align*}
 & \mathbb{E}_{P^{n}}\left[L_{n}^{o}(\hat{\delta},\eta_{0})-L_{n}^{o}(\tilde{\delta},\eta_{0})\right]\\
\leq & \left(\frac{\tilde{C}_{\xi}^{2}\zeta_{p}^2}{\left(\underline{\lambda}-\varepsilon\right)^{3}}+\frac{\tilde{C}_{\xi}\zeta_{p}}{\left(\underline{\lambda}-\varepsilon\right)^{2}}\right)\mathbb{E}_{P^{n}}\left\Vert \hat{A}_{n}-A_{n}\right\Vert ^{2}\\
+ & \left(\frac{1}{\underline{\lambda}-\varepsilon}+\frac{\tilde{C}_{\xi}\zeta_{p}}{\left(\underline{\lambda}-\varepsilon\right)^{2}}\right)\mathbb{E}_{P^{n}}\left\Vert \hat{B}_{n}-B_{n}\right\Vert ^{2}\\
\leq & c_1\left(\zeta_{p}^2\mathbb{E}_{P^{n}}\left\Vert \hat{A}_{n}-A_{n}\right\Vert ^{2}+\zeta_{p}\mathbb{E}_{P^{n}}\left\Vert \hat{B}_{n}-B_{n}\right\Vert ^{2}\right),
\end{align*}
where $c_1$ is a constant that depends on $\tilde{C}_{\xi}$, $\varepsilon$
and $\underline{\lambda}$. Then, the conclusion of statement (i)
follows from invoking Lemmas \ref{lem:remainder.5} and \ref{lem:remainder.6}(i), and that of statement (ii) follows from Lemmas \ref{lem:remainder.5} and \ref{lem:remainder.6}(ii).



\subsection{Additional Lemmas supporting Theorem \ref{thm:main}}

\begin{lem}\label{lem:remainder.1}
Under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}, we have 
\[
P\left\{ \lambda_{\min}\left(A_{n}\right)<\underline{\lambda}-\varepsilon\right\} \leq2\sieved\exp\left(\frac{-n\varepsilon^{2}}{4C_{\xi}^{2}\zeta_{p}^{4}}\right),
\]
for all $0<\varepsilon\leq\min\left\{ 3C_{\xi}\zeta_{p}^{2}/2,\underline{\lambda}\right\} $. 
\end{lem}

\begin{proof}
As $\left|\lambda_{\min}\left(A_{n}\right)-\underline{\lambda}\right|\leq\left\Vert A_{n}-A\right\Vert $,
we have 
\begin{align*}
P\left\{ \lambda_{\min}\left(A_{n}\right)<\underline{\lambda}-\varepsilon\right\}  & \leq P\left\{ \left|\lambda_{\min}\left(A_{n}\right)-\underline{\lambda}\right|>\varepsilon\right\} \leq P\left\{ \left\Vert A_{n}-A\right\Vert >\varepsilon\right\} .
\end{align*}
Note $\left\Vert \xi_{i}p(W_{i})p^{\prime}(W_{i})\right\Vert\leq C_{\xi}\zeta_{p}^{2}$, $\left\Vert \mathbb{E}\xi_{i}^{2}p(W_{i})p^{\prime}(W_{i})p(W_{i})p^{\prime}(W_{i})\right\Vert  \leq C_{\xi}^{2}\zeta_{p}^{4}$.
%\begin{align*}
%\left\Vert \xi_{i}p(W_{i})p^{\prime}(W_{i})\right\Vert  & \leq C_{\xi}\zeta_{p}^{2},\\
%\left\Vert \mathbb{E}\xi_{i}^{2}p(W_{i})p^{\prime}(W_{i})p(W_{i})p^{\prime}(W_{i})\right\Vert  & \leq C_{\xi}^{2}\zeta_{p}^{4}.
%\end{align*}
\citet[][Corollary 6.2.1]{tropp2015introduction} implies that 
\[
P\left\{ \left\Vert A_{n}-A\right\Vert >\varepsilon\right\} \leq2\sieved\exp\left(\frac{-n\varepsilon^{2}/2}{\left(C_{\xi}^{2}\zeta_{p}^{4}+C_{\xi}\zeta_{p}^{2}\varepsilon/3\right)}\right).
\]
The conclusion follows by picking $\varepsilon<\underline{\lambda}$
such that $2C_{\xi}\zeta_{p}^{2}\varepsilon/3<C_{\xi}^{2}\zeta_{p}^{4}$,
i.e., $\varepsilon<\min\left\{ 3C_{\xi}\zeta_{p}^{2}/2,\underline{\lambda}\right\} $. 
\end{proof}
\begin{lem}\label{lem:remainder.2}
Under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}, for all $0<\varepsilon<\min\left\{ \underline{\lambda},6\tilde{C}_{\xi}\zeta_{p}^{2}\right\} $
and all $n$ such that 
\[
4C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right)<\varepsilon,
\]
we have
\[
P\left\{ \lambda_{\min}\left(\widehat{A}_{n}\right)<\underline{\lambda}-\varepsilon\right\} \leq2\sieved K\exp\left(\frac{-n\varepsilon^{2}}{16K\tilde{C}_{\xi}^{2}\zeta_{p}^{4}}\right).
\]
\end{lem}

\begin{proof}
Note 
\[
\widehat{A}_{n}=\frac{1}{K}\sum_{k=1}^{K}\left[\frac{1}{m}\sum_{i\in I_{k}}\hat{\xi}_{i}p_{i}p_{i}^{\prime}\right]=\frac{1}{K}\sum_{k=1}^{K}\left[\frac{1}{m}\sum_{i\in I_{k}}\hat{\xi}_{i}^{k}p_{i}p_{i}^{\prime}\right].
\]
Weyl\textquoteright s inequality implies
\[
\lambda_{\min}\left(\widehat{A}_{n}\right)\geq\frac{1}{K}\sum_{k=1}^{K}\lambda_{\min}\left[\frac{1}{m}\sum_{i\in I_{k}}\hat{\xi}_{i}^{k}p_{i}p_{i}^{\prime}\right].
\]
First, fix $0<\varepsilon<\underline{\lambda}$, and  write $\hat{A}_{k}:=\sum_{i\in I_{k}}\frac{\hat{\xi}_{i}^{k}p(W_{i})p^{\prime}(W_{i})}{m}$
and $P_{k}\left\{ \cdotp\right\} :=P_{k}\left\{ \cdotp\mid\left\{ Z_{j}\right\} _{j\in[n]\setminus I_{k}}\right\} $.
Also recall $\mathbb{E}_{k}\left[\cdotp\right]=\mathbb{E}_{k}\left[\cdotp\mid\left\{ Z_{j}\right\} _{j\in[n]\setminus I_{k}}\right]$.
We have
\begin{align*}
&P\left\{ \lambda_{\min}\left(\widehat{A}_{n}\right)<\underline{\lambda}-\varepsilon\right\}  \leq P\left\{ \frac{1}{K}\sum_{k=1}^{K}\lambda_{\min}\left[\hat{A}_{k}\right]<\underline{\lambda}-\varepsilon\right\} \\
 \leq & P\left\{ \lambda_{\min}\left[\hat{A}_{k}\right]<\underline{\lambda}-\varepsilon,\text{for some }k\in[K]\right\}  \leq\sum_{k=1}^{K}P\left\{ \lambda_{\min}\left[\hat{A}_{k}\right]<\underline{\lambda}-\varepsilon\right\} \\
  =&\sum_{k=1}^{K}\mathbb{E}\left[P_{k}\left\{ \lambda_{\min}\left(\hat{A}_{k}\right)<\underline{\lambda}-\varepsilon\right\} \right].
\end{align*}
Then, it suffices to bound $P_{k}\left\{ \lambda_{\min}\left(\hat{A}_{k}\right)<\underline{\lambda}-\varepsilon\right\} $
for each $\forall k\in[K]$. To this end, note Lemma \ref{lem:remainder.3} implies that
\begin{equation}
P_{k}\left\{ \lambda_{\min}\left(\hat{A}_{k}\right)<\underline{\lambda}-\varepsilon\right\} \leq P_{k}\left\{ \lambda_{\min}\left(\hat{A}_{k}\right)<\lambda_{\min}\left(\mathbb{E}_{k}\left[\widehat{A}_{k}\right]\right)-\varepsilon/2\right\} \label{pf:min.eigen.estimated.1}
\end{equation}
for all $n$ such that 
\[
4C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right)<\varepsilon.
\]
Furthermore, 

\begin{equation}
P_{k}\left\{ \lambda_{\min}\left[\hat{A}_{k}\right]<\lambda_{\min}\left(\mathbb{E}_{k}\left[\widehat{A}_{k}\right]\right)-\varepsilon/2\right\} \leq P_{k}\left\{ \left\Vert \widehat{A}_{k}-\mathbb{E}_{k}\widehat{A}_{k}\right\Vert >\varepsilon/2\right\} .\label{pf:min.eigen.estimated.2}
\end{equation}
And for each $k\in[K]$ and conditional on $\left\{ Z_{j}\right\} _{j\in[n]\setminus I_{k}}$,
$\hat{A}_{k}$ is a sum of $m$ random matrices with independent entries.
Since
\begin{align*}
\left\Vert \hat{\xi}_{i}^{k}p_{i}p_{i}^{\prime}\right\Vert  & \lesssim\tilde{C}_{\xi}\zeta_{p}^{2},\quad
\left\Vert \mathbb{E}_{k}\left[\left(\hat{\xi}_{i}^{k}\right)^{2}p_{i}p_{i}^{\prime}p_{i}p_{i}^{\prime}\right]\right\Vert   \lesssim\zeta_{p}^{4}\tilde{C}_{\xi}^{2},
\end{align*}
it follows by \citet[][Corollary 6.2.1]{tropp2015introduction}  that 
\begin{align*}
P\left\{ \left\Vert \widehat{A}_{k}-\mathbb{E}_{k}\widehat{A}_{k}\right\Vert >\varepsilon\right\}  & \leq2d_{p}\exp\left(\frac{-\frac{n}{K}\frac{\varepsilon^{2}}{8}}{\left(\zeta_{p}^{4}\tilde{C}_{\xi}^{2}+\tilde{C}_{\xi}\zeta_{p}^{2}\varepsilon/6\right)}\right).
\end{align*}
Thus, picking $\varepsilon<\min\left\{ \underline{\lambda},6\tilde{C}_{\xi}\zeta_{p}^{2}\right\} $,
we conclude that 
\begin{equation}
P_{k}\left\{ \left\Vert \widehat{A}_{k}-\mathbb{E}_{k}\widehat{A}_{k}\right\Vert >\varepsilon/2\right\} \leq2d_{p}\exp\left(-\frac{\varepsilon^{2}n}{16K\tilde{C}_{\xi}^{2}\zeta_{p}^{4}}\right)\label{pf:min.eigen.estimated.3}
\end{equation}
for all $k\in[K]$. The conclusion follows by  combining (\ref{pf:min.eigen.estimated.1}),
(\ref{pf:min.eigen.estimated.2}), and (\ref{pf:min.eigen.estimated.3})
%that 
%\[
%P_{k}\left\{ \lambda_{\min}\left(\hat{A}_{k}\right)<\underline{\lambda}-\varepsilon\right\} \leq2d_{p}\exp\left(-\frac{\varepsilon^{2}n}{16K\tilde{C}_{\xi}^{2}\zeta_{p}^{4}}\right)
%\]
% for all $0<\varepsilon<\min\left\{ \underline{\lambda},6\tilde{C}_{\xi}\zeta_{p}^{2}\right\} $
%and all $n$ such that 
%\[
%4C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right)<\varepsilon.
%\]
\end{proof}
\begin{lem}\label{lem:remainder.3}
Suppose Assumptions \ref{asm:unconfounded}-\ref{asm:quality} hold. For each $\varepsilon>0$, and for each $n$ such that
\[
4C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right)<\varepsilon,
\]
we have, for all $k\in[K]$,
\[
\lambda_{\min}\left(\mathbb{E}_{k}\left[\widehat{A}_{k}\right]\right)\geq\underline{\lambda}-\frac{\varepsilon}{2}.
\]
\end{lem}

\begin{proof}
Note $\mathbb{E}_{k}\left[\widehat{A}_{k}\right]=\mathbb{E}_{k}\left[\sum_{i\in I_{k}}\frac{\hat{\xi}_{i}^{k}p_{i}p_{i}^{\prime}}{m}\right]=\mathbb{E}_{k}\left[\hat{\xi}^{k}pp^{\prime}\right]$.
Thus,
\begin{align*}
\lambda_{\min}\left(\mathbb{E}_{k}\left[\widehat{A}_{k}\right]\right) & \geq\lambda_{\min}\left(\mathbb{E}_{k}\left[\xi pp^{\prime}\right]\right)+\lambda_{\min}\left(\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)pp^{\prime}\right]\right)\\
 & =\underline{\lambda}+\lambda_{\min}\left(\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)pp^{\prime}\right]\right),
\end{align*}
and
\begin{align*}
 & \left|\lambda_{\min}\left(\mathbb{E}_{k}\left(\hat{\xi}^{k}-\xi\right)pp^{\prime}\right)\right|= \left|\min_{\left\Vert a\right\Vert =1}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)\left(a^{\prime}p\right)^{2}\right]\right|\\
\leq & \sup_{\left\Vert a\right\Vert =1}\left|\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)\left(a^{\prime}p\right)^{2}\right]\right|
\leq 2C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right),
\end{align*}
where the last inequality follows by Lemma \ref{lem:remainder.4}. The conclusion follows
by picking 
\[
2C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right)\leq\varepsilon/2.
\]
\end{proof}
\begin{lem}\label{lem:remainder.4}
Under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}, we have for each $i\in I_{k}$, $k\in[K]$,
\begin{align*}
\sup_{\left\Vert a\right\Vert =1}\left|\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)\left(a^{\prime}p_{i}\right)^{2}\right]\right| & \leq2C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right).
\end{align*}
\end{lem}

\begin{proof}
For each $k\in[K]$, the following decomposition holds:
\begin{align*}
\hat{\xi}^{k}-\xi= & \left[2\left(\gamma_{1}-\gamma_{0}\right)-D\omega_{1}\right]\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)+\left[(1-D)\omega_{0}-2\left(\gamma_{1}-\gamma_{0}\right)\right]\left(\hat{\gamma}_{0}^{k}-\gamma_{0}\right)\\
+ & \left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}-\gamma_{1}+\gamma_{0}\right)^{2}\\
+ & D\left(\hat{\omega}_{1}^{k}-\omega_{1}\right)e_{1}+D\left(\hat{\omega}_{1}^{k}-\omega_{1}\right)(\gamma_{1}-\hat{\gamma}_{1}^{k})\\
- & (1-D)\left(\hat{\omega}_{0}^{k}-\omega_{0}\right)e_{0}-(1-D)\left(\hat{\omega}_{0}^{k}-\omega_{0}\right)(\gamma_{0}-\hat{\gamma}_{0}^{k}).
\end{align*}
For each $a$ such that $\left\Vert a\right\Vert =1$, note:
\begin{align*}
\mathbb{E}_{k}\left[\left[2\left(\gamma_{1}-\gamma_{0}\right)-D\omega_{1}\right]\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)\left(a^{\prime}p\right)^{2}\right] & =0,\\
\mathbb{E}_{k}\left[\left[(1-D)\omega_{0}-2\left(\gamma_{1}-\gamma_{0}\right)\right]\left(\hat{\gamma}_{0}^{k}-\gamma_{0}\right)\left(a^{\prime}p\right)^{2}\right] & =0,\\
\mathbb{E}_{k}\left[D\left(\hat{\omega}_{1}^{k}-\omega_{1}\right)e_{1}\left(a^{\prime}p\right)^{2}\right] & =0,\\
\mathbb{E}_{k}\left[(1-D)\left(\hat{\omega}_{0}^{k}-\omega_{0}\right)e_{0}\left(a^{\prime}p\right)^{2}\right] & =0.
\end{align*}
The conclusion follows by noting 
\begin{align*}
 & \sup_{\left\Vert a\right\Vert =1}\left|\mathbb{E}_{k}\left[\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}-\gamma_{1}+\gamma_{0}\right)^{2}\left(a^{\prime}p\right)^{2}\right]\right|\\
\leq & \zeta_{p}^{2}\left|\mathbb{E}_{k}\left[\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}-\gamma_{1}+\gamma_{0}\right)^{2}\right]\right|\\
\leq & 2\zeta_{p}^{2}\left(\mathbb{E}_{k}\left[\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)^{2}\right]+\mathbb{E}_{k}\left[\left(\hat{\gamma}_{0}^{k}-\gamma_{0}\right)^{2}\right]\right)\\
\leq & 2C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right),
\end{align*}
and 
\[
\begin{aligned}\sup_{\left\Vert a\right\Vert =1}\left|\mathbb{E}_{k}\left[D\left(\hat{\omega}_{1}^{k}-\omega_{1}\right)(\gamma_{1}-\hat{\gamma}_{1}^{k})\left(a^{\prime}p\right)^{2}\right]\right| & \leq C_{M}\zeta_{p}^{2}n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}},\\
\sup_{\left\Vert a\right\Vert =1}\left|\mathbb{E}_{k}\left[(1-D)\left(\hat{\omega}_{0}^{k}-\omega_{0}\right)(\gamma_{0}-\hat{\gamma}_{0}^{k})\right]\right| & \leq C_{M}\zeta_{p}^{2}n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}.
\end{aligned}
\]
\end{proof}
\begin{lem}\label{lem:remainder.5}
Under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}, we have
\begin{align*}
\mathbb{E}\left\Vert \hat{A}_{n}-A_{n}\right\Vert ^{2} & \leq c_3\left(\log2d_{p}\right)^{2}\zeta_{p}^{4}\left(n^{-2r_{\gamma_{1}}}+n^{-2r_{\gamma_{0}}}+n^{-\left(r_{\omega_{1}}+r_{\gamma_{1}}\right)}+n^{-\left(r_{\omega_{0}}+r_{\gamma_{0}}\right)}\right),
\end{align*}
where $c_3$ is a constant that depends on $K$, $\underline{\pi}$, $C_{e},C_{\gamma}$,
$\tilde{C}_{M}$ and $C_{M}$.
\end{lem}
\begin{proof}
As 
\begin{align*}
\hat{A}_{n}-A_{n} & =\frac{1}{K}\sum_{k=1}^{K}\left(\frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}-\xi_{i}\right)p_{i}p_{i}^{\prime}\right) =\frac{1}{K}\sum_{k=1}^{K}\left(\frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}^{k}-\xi_{i}\right)p_{i}p_{i}^{\prime}\right),
\end{align*}
triangle inequality implies 
\[
\mathbb{E}_{P^{n}}\left\Vert \hat{A}_{n}-A_{n}\right\Vert ^{2}\leq\frac{1}{K}\sum_{k=1}^{K}\mathbb{E}_{P^{n}}\left[\left\Vert \frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}^{k}-\xi_{i}\right)p_{i}p_{i}^{\prime}\right\Vert ^{2}\right].
\]
Furthermore, for each $k\in[K]$,
\[
\mathbb{E}_{P^{n}}\left[\left\Vert \frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}^{k}-\xi_{i}\right)p_{i}p_{i}^{\prime}\right\Vert ^{2}\right]\leq\mathbb{E}_{P^{n}}\left\{ \mathbb{E}_{k}\left[\left\Vert S_{k,1}\right\Vert ^{2}\right]+\left\Vert S_{k,2}\right\Vert ^{2}\right\} ,
\]
where 
\begin{align*}
S_{k,1} & =\frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}^{k}-\xi_{i}\right)p_{i}p_{i}^{\prime}-\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)pp^{\prime}\right],\\
S_{k,2} & =\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)pp^{\prime}\right].
\end{align*}
Conditional on $\left\{ Z_{j}\right\} _{j\in[n]\setminus I_{k}}$,
$S_{k,1}$ is a centered random matrix with independent entries. We
calculate:
\begin{align*}
v_{1} & :=\frac{1}{m}\left\Vert \mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)^{2}pp^{\prime}pp^{\prime}\right]\right\Vert \leq\frac{\zeta_{p}^{4}}{m}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)^{2}\right],\\
v_{2} & :=\mathbb{E}_{k}\left[\max_{i\in I_{k}}\left\Vert \frac{\left(\hat{\xi}_{i}^{k}-\xi_{i}\right)p_{i}p_{i}^{\prime}}{m}\right\Vert ^{2}\right] \leq\frac{\mathbb{E}_{k}\left[\left\Vert \left(\hat{\xi}^{k}-\xi\right)pp^{\prime}\right\Vert ^{2}\right]}{m} \leq\frac{\zeta_{p}^{4}}{m}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)^{2}\right].
\end{align*}
Applying \citet[][Theorem A.1]{chen2012masked} yields
\begin{align*}
\mathbb{E}_{k}\left[\left\Vert S_{k,1}\right\Vert ^{2}\right] & \leq2\left[2ev_{1}\log2d_{p}+16e^{2}v_{2}\left(\log2d_{p}\right)^{2}\right]\\
 & \leq2\left[2e\frac{\zeta_{p}^{4}}{m}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)^{2}\right]\log2d_{p}+16e^{2}\left(\frac{\zeta_{p}^{4}}{m}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)^{2}\right]\right)\left(\log2d_{p}\right)^{2}\right]\\
 & =\left[4e\log2d_{p}+16e^{2}\left(\log2d_{p}\right)^{2}\right]\frac{\zeta_{p}^{4}K}{n}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)^{2}\right],
\end{align*}
where note under Assumptions \ref{asm:unconfounded}-\ref{asm:quality},
\[
\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)^{2}\right]\leq c_2C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-r_{\omega_{1}}}+n^{-r_{\omega_{0}}}\right)
\]
for some constant $c_2$ that only depends on $\underline{\pi},C_{e},C_{\gamma}$,
and $\tilde{C}_{M}$. For $\left\Vert S_{k,2}\right\Vert$, note Lemma \ref{lem:remainder.4} implies
\begin{align*}
\left\Vert S_{k,2}\right\Vert  & =\sup_{\left\Vert a\right\Vert =1}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)\left(a^{\prime}p\right)^{2}\right]\\
 & \leq\sup_{\left\Vert a\right\Vert =1}\left|\mathbb{E}_{k}\left[\left(\hat{\xi}^{k}-\xi\right)\left(a^{\prime}p\right)^{2}\right]\right|\\
 & \leq2C_{M}\zeta_{p}^{2}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right).
\end{align*}
Thus, we conclude
\begin{align*}
\mathbb{E}\left\Vert \hat{A}_{n}-A_{n}\right\Vert ^{2} & \leq\left[4e\log2d_{p}+16e^{2}\left(\log2d_{p}\right)^{2}\right]\frac{Kc_{2}C_{M}\zeta_{p}^{4}}{n}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-r_{\omega_{1}}}+n^{-r_{\omega_{0}}}\right)\\
 & +16C_{M}^{4}\zeta_{p}^{4}\left(n^{-2r_{\gamma_{1}}}+n^{-2r_{\gamma_{0}}}+n^{-\left(r_{\omega_{1}}+r_{\gamma_{1}}\right)}+n^{-\left(r_{\omega_{0}}+r_{\gamma_{0}}\right)}\right)\\
 & \leq c\left(\log2d_{p}\right)^{2}\zeta_{p}^{4}\left(n^{-2r_{\gamma_{1}}}+n^{-2r_{\gamma_{0}}}+n^{-\left(r_{\omega_{1}}+r_{\gamma_{1}}\right)}+n^{-\left(r_{\omega_{0}}+r_{\gamma_{0}}\right)}\right),
\end{align*}
where $c_3$ depends on $K,c_{2}$ and $C_{M}$.
\end{proof}

\begin{lem}\label{lem:remainder.6}
\begin{itemize}
\item[(i)] Under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}, we have
\begin{align*}
\mathbb{E}\left\Vert \hat{B}_{n}-B_{n}\right\Vert ^{2} & \leq c_4\left[\frac{\zeta_{p}^{2}}{n}+\sieved\zeta_{p}^{2}\left[\left(n^{-2r_{\gamma_{1}}}+n^{-2r_{\gamma_{0}}}\right)+n^{-(r_{\omega_{1}}+r_{\gamma_{1}})}+n^{-(r_{\omega_{0}}+r_{\gamma_{0}})}\right]\right]
\end{align*}
for some $c_4$ that depends on $K$, $C_{M}$, $C_{\xi}$ and $\tilde{C}_{\xi}$.

\item[(ii)] Suppose in addition,  Assumption \ref{asm:margin} also holds, and  $n$ is such that
\[
\left(4C_{M}C_{\tau}^{-1}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)\right)^{\frac{1}{\alpha+2}}<t^{*}.
\]
Then, we have
\begin{align*}
\mathbb{E}\left\Vert \hat{B}_{n}-B_{n}\right\Vert ^{2} & \leq\frac{c_5\zeta_{p}^{2}}{n}\left[\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)^{\frac{\alpha}{\alpha+2}}+n^{-r_{\omega_{1}}}+n^{-r_{\omega_{0}}}\right]\\
 & +c_5d_{p}\zeta_{p}^{2}\left[\left(n^{-2r_{\gamma_{1}}}+n^{-2r_{\gamma_{0}}}\right)+n^{-(r_{\omega_{1}}+r_{\gamma_{1}})}+n^{-(r_{\omega_{0}}+r_{\gamma_{0}})}\right],
\end{align*}
where $c_5$ is a suitably redefined constant that also depends on $\underline{\pi},C_{\tau},C_{e}$,
$\tilde{C}_{M}$, $C_{\tau}$ and $\alpha$.
\end{itemize}
\end{lem}

\begin{proof}
\textbf{Statement (i)}. As
\begin{align*}
\hat{B}_{n}-B_{n} & =\left[\frac{1}{K}\sum_{k=1}^{K}\frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}\mathbf{1}\left\{ \hat{\tau}_{i}\geq0\right\} -\xi_{i}\mathbf{1}\left\{ \tau_{i}\geq0\right\} \right)p_{i}\right]\\
 & =\left[\frac{1}{K}\sum_{k=1}^{K}\frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}^{k}\mathbf{1}\left\{ \hat{\tau}_{i}^{k}\geq0\right\} -\xi_{i}\mathbf{1}\left\{ \tau_{i}\geq0\right\} \right)p_{i}\right],
\end{align*}
analogous arguments to Lemma \ref{lem:remainder.4} imply that it suffices to bound for each $k\in[K]$
\begin{align*}
 & \mathbb{E}_{k}\left\Vert \frac{1}{m}\sum_{i\in I_{k}}\left(\hat{\xi}_{i}^{k}\mathbf{1}\left\{ \hat{\tau}_{i}^{k}\geq0\right\} -\xi_{i}\mathbf{1}\left\{ \tau_{i}\geq0\right\} \right)p_{i}\right\Vert ^{2}
\leq \left|\mathbb{E}_{k}\left[S_{k,3}\right]\right|+\left|\mathbb{E}_{k}\left[S_{k,4}\right]\right|,
\end{align*}
where
\begin{align*}
\mathbb{E}_{k}\left[S_{k,3}\right] & :=\frac{1}{m}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k,+}-\xi^{+}\right)^{2}p^{\prime}p\right],\\
\mathbb{E}_{k}\left[S_{k,4}\right] & :=\frac{1}{m(m-1)}\sum_{i,j\in I_{k},i\neq j}\mathbb{E}_{k}\left(\hat{\xi}_{i}^{k,+}-\xi_{i}^{+}\right)\left(\hat{\xi}_{j}^{k,+}-\xi_{j}^{+}\right)p_{i}^{\prime}p_{j},\\
\hat{\xi}^{k,+} & :=\hat{\xi}^{k}\mathbf{1}\left\{ \hat{\tau}^{k}(X)\geq0\right\} ,\\
\xi^{+} & :=\xi\mathbf{1}\left\{ \tau(X)\geq0\right\} .
\end{align*}
For term $S_{k,3}$, note under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}:
\begin{align}
\left|\mathbb{E}_{k}\left[S_{k,3}\right]\right| & \leq\frac{\zeta_{p}^{2}}{m}\mathbb{E}_{k}\left[\left(\hat{\xi}^{k,+}-\xi^{+}\right)^{2}\right]\leq\frac{K\zeta_{p}^{2}}{n}\left(2C_{\xi}^{2}+2\tilde{C}_{\xi}^{2}\right).\label{pf:hat.B.1}
\end{align}
For term $S_{k,4}$, note conditional on $\left\{ Z_{j}\right\} _{j\in[n]\setminus I_{k}}$,
$\left(\hat{\xi}_{i}^{k,+}-\xi_{i}^{+}\right)p_{i}$ and $\left(\hat{\xi}_{j}^{k,+}-\xi_{j}^{+}\right)p_{j}$
are independent. Therefore, for each $i,j\in I_{k},i\neq j$:
\begin{align*}
 & \mathbb{E}_{k}\left(\hat{\xi}_{i}^{k,+}-\xi_{i}^{+}\right)\left(\hat{\xi}_{j}^{k,+}-\xi_{j}^{+}\right)p_{i}^{\prime}p_{j}\\
= & \left[\mathbb{E}_{k}\left(\hat{\xi}_{i}^{k,+}-\xi_{i}^{+}\right)p_{i}\right]^{\prime}\mathbb{E}_{k}\left[\left(\hat{\xi}_{j}^{k,+}-\xi_{j}^{+}\right)p_{j}\right]\\
= & \sum_{t=1}^{d_{p}}\mathbb{E}_{k}\left[\left(\hat{\xi}_{i}^{k,+}-\xi_{i}^{+}\right)p_{t,i}\right]\mathbb{E}_{k}\left[\left(\hat{\xi}_{j}^{k,+}-\xi_{j}^{+}\right)p_{t,j}\right]\\
= & \sum_{t=1}^{d_{p}}\left\{ \mathbb{E}_{k}\left[\left(\hat{\xi}^{k,+}-\xi^{+}\right)p_{t}\right]\right\} ^{2}.
\end{align*}
Applying Lemma \ref{lem:remainder.7} yields
\begin{equation}
\sum_{t=1}^{d_{p}}\left\{ \mathbb{E}_{k}\left[\left(\hat{\xi}^{k,+}-\xi^{+}\right)p_{t}\right]\right\} ^{2}\leq d_{p}\zeta_{p}^{2}C_{M}^{2}\left[12\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)+n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}\right]^{2}.\label{pf:hat.B.2}
\end{equation}
The conclusion follows by combining (\ref{pf:hat.B.1}) and (\ref{pf:hat.B.2}).

\noindent \textbf{Statement (ii)}. The proof is analogous to that of statement (i), but with a new upper bound for term $\mathbb{E}_{k}\left[S_{k,3}\right]$ established in Lemma \ref{lem:remainder.8}. 
\end{proof}

\begin{lem}\label{lem:remainder.7}
Under Assumptions \ref{asm:unconfounded}-\ref{asm:quality}, we have, for all $k\in[K]$ and each $j\in[\sieved]$:
\[
\left|\mathbb{E}_{k}\left[\left(\hat{\xi}^{k,+}-\xi^{+}\right)p_{j}\right]\right|\leq\zeta_{p}C_{M}\left[n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}}+n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}}+12\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)\right]
\]
\end{lem}

\begin{proof}
Since the function $f(x)=x^{2}\mathbf{1}\{x\geq0\}$ is continuously
differentiable, first order Taylor expansion yields, for each $k\in[K]$:
\begin{align*}
 & \left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\right)^{2}\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}-\left(\gamma_{1}-\gamma_{0}\right)^{2}\mathbf{1}\{\gamma_{1}-\gamma_{0}\geq0\}\\
= & \left(\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\right)\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\geq0\}\left(\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)-\left(\hat{\gamma}_{0}^{k}-\gamma_{0}\right)\right),
\end{align*}
where 
\begin{align*}
\tilde{\gamma}_{1}^{k}(x) & :=\gamma_{1}(x)+\tilde{t}^{k}(x)(\hat{\gamma}_{1}^{k}(x)-\gamma_{1}(x)),\\
\tilde{\gamma}_{0}^{k}(x) & :=\gamma_{0}(x)+\tilde{t}^{k}(x)(\hat{\gamma}_{0}^{k}(x)-\gamma_{0}(x)),
\end{align*}
and $\tilde{t}^{k}(x)\in(0,1)$ for all $x\in\mathcal{X}$. After
lengthy algebra, we arrive at the following decomposition:
\begin{align*}
\hat{\xi}^{k,+}-\xi^{+}= & \Delta_{k,1}+\Delta_{k,2}+\Delta_{k,3}+\Delta_{k,4}+\Delta_{k,5}+\Delta_{k,6}\\
- & \Delta_{k,7}-\Delta_{k,8}-\Delta_{k,9}-\Delta_{k,10},
\end{align*}
where
\begin{align*}
\Delta_{k,1} & :=\left(2\left(\gamma_{1}-\gamma_{0}\right)-D\omega_{1}\right)\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\},\\
\Delta_{k,2} & =D\omega_{1}e_{1}\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}-D\omega_{1}e_{1}\mathbf{1}\{\gamma_{1}-\gamma_{0}\geq0\},\\
\Delta_{k,3} & =D\left(\hat{\omega}_{1}^{k}-\omega_{1}\right)e_{1}\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\},\\
\Delta_{k,4} & =D\left(\hat{\omega}_{1}^{k}-\omega_{1}\right)(\gamma_{1}-\hat{\gamma}_{1}^{k})\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\},\\
\Delta_{k,5} & =2\left[\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}-\left(\gamma_{1}-\gamma_{0}\right)\right)^{2}\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}\right],\\
\Delta_{k,6} & =\left[\left(\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\right)\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\geq0\}-\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\right)\mathbf{1}\{\hat{\gamma}_{1}-\hat{\gamma}_{0}\geq0\}\right]\left(\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)-\left(\hat{\gamma}_{0}^{k}-\gamma_{0}\right)\right),
\end{align*}
and 
\begin{align*}
\Delta_{k,7} & :=\left(2\left(\gamma_{1}-\gamma_{0}\right)-(1-D)\omega_{0})(\hat{\gamma}_{0}^{k}-\gamma_{0})\right)\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\},\\
\Delta_{k,8} & :=(1-D)\omega_{0}e_{0}\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}-(1-D)\omega_{0}e_{0}\mathbf{1}\{\gamma_{1}-\gamma_{0}\geq0\},\\
\Delta_{k,9} & :=(1-D)(\hat{\omega}_{0}^{k}-\omega_{0})e_{0}\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\},\\
\Delta_{k,10} & :=(1-D)(\hat{\omega}_{0}^{k}-\omega_{0})(\gamma_{0}-\hat{\gamma}_{0}^{k})\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}.
\end{align*}
Note 
\begin{align*}
\mathbb{E}_{k}\left[\Delta_{k,1}p_{j}\right] & =0, & \mathbb{E}_{k}\left[\Delta_{k,7}p_{j}\right],=0,\\
\mathbb{E}_{k}\left[\Delta_{k,2}p_{j}\right] & =0, & \mathbb{E}_{k}\left[\Delta_{k,8}p_{j}\right]=0,\\
\mathbb{E}_{k}\left[\Delta_{k,3}p_{j}\right] & =0, & \mathbb{E}_{k}\left[\Delta_{k,9}p_{j}\right]=0.
\end{align*}
Thus, $\left|\mathbb{E}_{k}\left[\left(\hat{\xi}^{k,+}-\xi^{+}\right)p_{j}\right]\right|$
is determined by
\begin{align*}
\mathbb{E}_{k}\left[\Delta_{k,4}p_{j}\right] & , & \mathbb{E}_{k}\left[\Delta_{k,5}p_{j}\right],\\
\mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\right] & =0, & \mathbb{E}_{k}\left[\Delta_{k,10}p_{j}\right].
\end{align*}
It is straigtforward to show
\begin{align*}
\left|\mathbb{E}_{k}\left[\Delta_{k,4}p_{j}\right]\right| & \leq\zeta_{p}C_{M}n^{-\frac{r_{\omega_{1}}+r_{\gamma_{1}}}{2}},\\
\left|\mathbb{E}_{k}\left[\Delta_{k,10}p_{j}\right]\right| & \leq\zeta_{p}C_{M}n^{-\frac{r_{\omega_{0}}+r_{\gamma_{0}}}{2}},\\
\left|\mathbb{E}_{k}\left[\Delta_{k,5}p_{j}\right]\right| & \leq4\zeta_{p}C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right).
\end{align*}
For tem $\left|\mathbb{E}_{k}\left[\Delta_{k,6}p_{t}\right]\right|$,
note
\begin{align*}
\mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\right]= & \mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\geq0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}\right]\\
+ & \mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}<0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}<0\}\right]\\
+ & \mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\geq0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}<0\}\right]\\
+ & \mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}<0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}<0\}\right].
\end{align*}
Furthermore, we have
\begin{align*}
 & \left|\mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\geq0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}\right]\right|\\
\leq & \mathbb{E}_{k}\left[\left(\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)-\left(\hat{\gamma}_{0}^{k}-\gamma_{0}\right)\right)^{2}\left|p_{j}\right|\right]\\
\leq & 4\zeta_{p}C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right),
\end{align*}
and 
\[
\mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}<0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}<0\}\right]=0.
\]
When $\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\geq0$ and $\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}<0$,
note
\[
\left|\Delta_{k,6}\right|\leq\left(\left(\hat{\gamma}_{1}^{k}-\gamma_{1}\right)-\left(\hat{\gamma}_{0}^{k}-\gamma_{0}\right)\right)^{2}.
\]
Thus, 
\begin{align*}
 & \mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}\geq0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}<0\}\right]
\leq 2\zeta_{p}C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right),
\end{align*}
and analogously, 
\begin{align*}
 & \mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\mathbf{1}\{\tilde{\gamma}_{1}^{k}-\tilde{\gamma}_{0}^{k}<0,\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}\right]
\leq  2\zeta_{p}C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right).
\end{align*}
Therefore, we conclude
\begin{align*}
 & \left|\mathbb{E}_{k}\left[\Delta_{k,6}p_{j}\right]\right|\leq8\zeta_{p}C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right).
\end{align*}

\end{proof}
\begin{lem}\label{lem:remainder.8}
Suppose Assumptions \ref{asm:unconfounded}-\ref{asm:margin} hold. Then, for all $n$ such that
\[
\left(4C_{M}C_{\tau}^{-1}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)\right)^{\frac{1}{\alpha+2}}<t^{*},
\]
we have
\begin{align*}
\left|\mathbb{E}_{k}\left[S_{k,3}\right]\right|\leq\frac{\zeta_{p}^{2}K}{n} & c_{1}^{+}C_{M}\left\{ n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-r_{\omega_{1}}}+n^{-r_{\omega_{0}}}\right\} \\
+\frac{\zeta_{p}^{2}K}{n} & c_{3}^{+}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)^{\frac{\alpha}{\alpha+2}},
\end{align*}
for some finite constants $c_{1}^{+}$ and $c_{3}^{+}$ defined below
in the proof. 
\end{lem}

\begin{proof}
By the decomposition result for $\hat{\xi}^{k,+}-\xi^{+}$, and under
Assumptions \ref{asm:unconfounded}-\ref{asm:quality}, it is straightforward to see that
\begin{align*}
\mathbb{E}_{k}\left[\left(\hat{\xi}^{k,+}-\xi^{+}\right)^{2}\right] & \leq c_{1}^{+}C_{M}\left\{ n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}+n^{-r_{\omega_{1}}}+n^{-r_{\omega_{0}}}\right\} \\
 & +c_{2}^{+}\mathbb{E}_{k}\left[\left(\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}-\mathbf{1}\{\gamma_{1}-\gamma_{0}\geq0\}\right)^{2}\right],
\end{align*}
where, $c_{1}^{+}$ and $c_{2}^{+}$ are some constants that depend
on $\underline{\pi},C_{\tau},C_{e}$ and $\tilde{C}_{M}$. With  Assumption
\ref{asm:margin}, we have
\begin{align*}
 & \mathbb{E}_{k}\left[\left(\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}-\mathbf{1}\{\gamma_{1}-\gamma_{0}\geq0\}\right)^{2}\right]\\
= & \mathbb{E}_{k}\left[\mathbf{1}\left\{ \text{sgn}\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\right)\neq\text{sgn}\left(\tau\right)\right\} \right]\\
\leq & \mathbb{E}_{k}\left[\mathbf{1}\left\{ \text{sgn}\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\right)\neq\text{sgn}\left(\tau\right)\right\} \mathbf{1}\left\{ \left|\tau\right|\leq t\right\} \right]\\
+ & \mathbb{E}_{k}\left[\mathbf{1}\left\{ \text{sgn}\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\right)\neq\text{sgn}\left(\tau\right)\right\} \mathbf{1}\left\{ \left|\tau\right|>t\right\} \right]\\
\leq & P\left\{ \left|\tau(X)\right|\leq t\right\} +P\left\{ \left|\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}-\tau\right|>t\right\} \\
\leq & C_{\tau}t^{\alpha}+\frac{\mathbb{E}_{k}\left[\left(\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}-\tau\right)^{2}\right]}{t^{2}}\\
\leq & C_{\tau}t^{\alpha}+\frac{2C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)}{t^{2}}.
\end{align*}
Optimizing over $t$ and choosing $n$ large enough so that 
\[
\left(\frac{4C_{M}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)}{C_{\tau}}\right)^{\frac{1}{\alpha+2}}<t^{*}
\]
 yields 
\begin{align*}
 & \mathbb{E}_{k}\left[\left(\mathbf{1}\{\hat{\gamma}_{1}^{k}-\hat{\gamma}_{0}^{k}\geq0\}-\mathbf{1}\{\gamma_{1}-\gamma_{0}\geq0\}\right)^{2}\right]\\
\leq & c_{3}^{+}\left(n^{-r_{\gamma_{1}}}+n^{-r_{\gamma_{0}}}\right)^{\frac{\alpha}{\alpha+2}},
\end{align*}
where $c_{3}^{+}$ is a finite constant that depends on $C_{M}$,
$C_{\tau}$ and $\alpha$. The conclusion follows by combining the
above results with (\ref{pf:hat.B.1}). 
\end{proof}

\section{Computational details}\label{sec:compute}
% To construct estimators for $\omega_{1}$ and $\omega_{0}$, denote
% by $b(x):=(b_{1}(x),\ldots,b_{\text{dim}(b)}(x))^{\prime}$ a vector
% of $\text{dim}(b)$ basis functions. Note \eqref{eq:balancing} implies
% \[
% \mathbb{E}\left[D\omega_{1}(X)b(X)\right]=\mathbb{E}\left[2\left(\gamma_{1}(X)-\gamma_{0}(X)\right)b(X)\right],
% \]
%  suggesting we may estimate $\omega_1$  by solving 
% \[
% \min_{\omega_{1}\in\Theta_{n}}\left\Vert \mathbb{E}_{n}\left[2\left(\hat{\gamma}_{1}(X)-\hat{\gamma}_{0}(X)\right)b(X)-D\omega_{1}(X)b(X)\right]\right\Vert +\lambda_{1,n}\mathbb{E}_{n}\left[D\omega_{1}^{2}(X)\right],
% \]
% where $\hat{\gamma}_{1},\hat{\gamma}_{0}$ are estimated versions
% of $\gamma_{1}$ and $\gamma_{0}$, 
% \[
% \Theta_{n}=\left\{ f:\mathcal{X}\rightarrow\mathbb{R}\mid f(x)=a^{\prime}b(x),a\in\mathbb{R}^{\text{dim}(b)}\right\} ,
% \]
% and $\lambda_{1,n}\geq0$ is a tuning parameter specified by the researcher.
Our practical procedure for selecting $\lambda_{1,n}$ in \eqref{eq:practical.omega} is motivated by the following simple observation: $\omega_1$ also satisfies
\begin{equation}
\mathbb{E}\left[D\omega_{1}(X)Y\right]=\mathbb{E}\left[2\left(\gamma_{1}(X)-\gamma_{0}(X)\right)\gamma_{1}(X)\right].\label{eq:cv.criterion}
\end{equation}
Thus, we select $\lambda_{1,n}$ via cross-validation to minimize
an out-of-sample prediction error criterion that mimics (\ref{eq:cv.criterion}) detailed in the algorithm below. %Such a criterion gives the estimated design matrix (..) the best chance
%to be positive definite. 

We now explain how to calculate $\hat{\xi}(Z_{i})$
given in our main proposal. For each $I_{k}$,
$k\in[K]$, calculation of $\hat{\gamma}_{1}^{k}$ and $\hat{\gamma}_{0}^{k}$
is straightforward and any machine learnt estimators can be applied.
We construct $\hat{\omega}_{1}^{k}$ and $\hat{\omega}_{0}^{k}$ for
$k\in[K]$ using the following $10$-fold cross validation procedure
(other number of folds can be considered completely analogously).
Let $\Lambda=\left\{ 0.1,0.2,0.3\ldots,4.9,5\right\} $ be a set of
penalty candidates. For each $k\in[K]$:
\begin{enumerate}
\item Split $I_{k}^{c}$ into approximately equal sized 10 folds, call them
$I_{k,1}^{c}$, $I_{k,2}^{c}$,..., $I_{k,10}^{c}$. For each fold
$I_{k,j}^{c}$, $j=1\ldots10$:
\begin{itemize}
\item[(a)] Estimate $\gamma_{1}$ and $\gamma_{0}$ using any estimator\footnote{It should be the same procedure that produced $\hat{\gamma}_{1}^{k}$
and $\hat{\gamma}_{0}^{k}$. For example, in our empirical application,
$\gamma_{1}$ and $\gamma_{0}$ are estimated via 10-fold cross-validated
lasso in glmnet package.} with data in $I_{k}^{c}$ but \textit{not} in $I_{k,j}^{c}$. Denote
by $\hat{\gamma}_{1}^{k,j}$ and $\hat{\gamma}_{0}^{k,j}$ the estimated
functional forms. Their predicted values for observations in $I_{k,j}^{c}$
are denoted as $\hat{\gamma}_{1}^{k,j}(X_{i}),\hat{\gamma}_{0}^{k,j}(X_{i}),i\in I_{k,j}^{c}.$
\item[(b)] For each $\lambda\in\Lambda$, calculate
\[
\hat{a}_{1}^{k,j}=\left(\hat{G}_{1}^{k,j}\hat{G}_{1}^{k,j}+\lambda\hat{G}_{1}^{k,j}\right)^{-}\hat{G}_{1}^{k,j}\hat{P}^{k,j},
\]
where 
\begin{align*}
\hat{G}_{1}^{k,j} & =\frac{\sum_{i\in I_{k}^{c},i\notin I_{k,j}^{c}}\left[D_{i}b(X_{i})b^{\prime}(X_{i})\right]}{\sum_{i\in I_{k}^{c},i\notin I_{k,j}^{c}}\mathbf{1}\left\{ i\in I_{k}^{c},i\notin I_{k,j}^{c}\right\} },\\
\hat{P}^{k,j} & =\frac{\sum_{i\in I_{k}^{c},i\notin I_{k,j}^{c}}\left[2\left(\hat{\gamma}_{1}^{k,j}(X_{i})-\hat{\gamma}_{0}^{k,j}(X_{i})\right)b(X_{i})\right]}{\sum_{i\in I_{k}^{c},i\notin I_{k,j}^{c}}\mathbf{1}\left\{ i\in I_{k}^{c},i\notin I_{k,j}^{c}\right\} },
\end{align*}
and
\[
\hat{a}_{0}^{k,j}=\left(\hat{G}_{0}^{k,j}\hat{G}_{0}^{k,j}+\lambda\hat{G}_{0}^{k,j}\right)^{-}\hat{G}_{1}^{k,j}\hat{P}^{k,j},
\]
where 
\begin{align*}
\hat{G}_{0}^{k,j} & =\frac{\sum_{i\in I_{k}^{c},i\notin I_{k,j}^{c}}\left[(1-D_{i})b(X_{i})b^{\prime}(X_{i})\right]}{\sum_{i\in I_{k}^{c},i\notin I_{k,j}^{c}}\mathbf{1}\left\{ i\in I_{k}^{c},i\notin I_{k,j}^{c}\right\} }.
\end{align*}
\item[(c)] Then, for each observation $i$ in $I_{k,j}^{c}$, calculate
\begin{equation*}
\hat{\omega}_{1}^{k,j}(\lambda,X_{i})  =\left[\hat{a}_{1}^{k,j}\right]^{\prime}b(X_{i}),\quad \hat{\omega}_{0}^{k,j}(\lambda,X_{i})  =\left[\hat{a}_{0}^{k,j}\right]^{\prime}b(X_{i}).
\end{equation*}
\item[(d)] For $\omega_{1}$, the cross-validation error in fold $I_{k,j}^{c}$
is 
\begin{align*}
CV_{1}(\lambda,j,k)= & \sum_{i\in I_{k,j}^{c}}\left[D_{i}\hat{\omega}_{1}^{k,j}(\lambda,X_{i})Y_{i}-2\left(\hat{\gamma}_{1}^{k,j}(X_{i})-\hat{\gamma}_{0}^{k,j}(X_{i})\right)\hat{\gamma}_{1}^{k,j}(X_{i})\right]^{2},
\end{align*}
and for $\omega_{0}$, the cross-validation error for fold $I_{k,j}^{c}$
is
\begin{align*}
CV_{0}(\lambda,j,k)= & \sum_{i\in I_{k,j}^{c}}\left[(1-D_{i})\hat{\omega}_{0}^{k,j}(\lambda,X_{i})Y_{i}-2\left(\hat{\gamma}_{1}^{k,j}(X_{i})-\hat{\gamma}_{0}^{k,j}(X_{i})\right)\hat{\gamma}_{0}^{k,j}(X_{i})\right]^{2}.
\end{align*}
\end{itemize}
\item For $\omega_{1}$, the total cross-validation error across all folds
$j=1\ldots 10$ is
$
TCV_{1}(\lambda,k)=\sum_{j=1}^{10}CV(\lambda,j,k)$, and analogously for $\omega_{0}$, 
%the total cross-validation error across all
%folds $j=1\ldots 10$ 
$
TCV_{0}(\lambda,k)=\sum_{j=1}^{10}CV(\lambda,j,k)$.

\item Let $\hat{\lambda}_{k}^{1}$ solve $\min_{\lambda\in\Lambda}TCV_{1}(\lambda,k)$.
The fitted value of the cross validated estimator for $\omega_{1}$
(constructed using data from $I_{k}^{c}$) for each observation in
fold $I_{k}$ is then
\begin{align*}
\hat{\omega}_{1}(X_{i}) & =b^{\prime}(X_{i})\hat{a}_{1}^{k},\text{ for all }i\in I_{k},\\
\hat{a}_{1}^{k} & =\left(\hat{G}_{1}^{k}\hat{G}_{1}^{k}+\hat{\lambda}_{k}^{1}\hat{G}_{1}^{k}\right)^{-}\hat{G}_{1}^{k}\hat{P}^{k},\\
\hat{G}^{k} & =\frac{\sum_{i\in I_{k}^{c}}\left[D_{i}b(X_{i})b(X_{i}^{\prime})\right]}{\sum_{i\in I_{k}^{c}}\mathbf{1}\left\{ i\in I_{k}^{c}\right\} },\\
\hat{P}^{k} & =\frac{\sum_{i\in I_{k}^{c}}\left[2\left(\hat{\gamma}_{1}^{k}(X_{i})-\hat{\gamma}_{0}^{k}(X_{i})\right)b(X_{i})\right]}{\sum_{i\in I_{k}^{c}}\mathbf{1}\left\{ i\in I_{k}^{c}\right\} }.
\end{align*}
\item Let $\hat{\lambda}_{k}^{0}$ solve $\min_{\lambda\in\Lambda}TCV_{0}(\lambda,k)$.
The fitted value of the cross validated estimator for $\omega_{0}$
(constructed using data from $I_{k}^{c}$) for each observation in
fold $I_{k}$ is then
\begin{align*}
\hat{\omega}_{0}(X_{i}) & =b^{\prime}(X_{i})\hat{a}_{0}^{k},\text{ for all }i\in I_{k},\\
\hat{a}_{0}^{k} & =\left(\hat{G}_{0}^{k}\hat{G}_{0}^{k}+\hat{\lambda}_{k}^{0}\hat{G}_{0}^{k}\right)^{-}\hat{G}_{0}^{k}\hat{P}^{k},\\
\hat{G}_{0}^{k} & =\frac{\sum_{i\in I_{k}^{c}}\left[(1-D_{i})b(X_{i})b^{\prime}(X_{i})\right]}{\sum_{i\in I_{k}^{c}}\mathbf{1}\left\{ i\in I_{k}^{c}\right\} },\\
\hat{P}^{k} & =\frac{\sum_{i\in I_{k}^{c}}\left[2\left(\hat{\gamma}_{1}^{k}(X_{i})-\hat{\gamma}_{0}^{k}(X_{i})\right)b(X_{i})\right]}{\sum_{i\in I_{k}^{c}}\mathbf{1}\left\{ i\in I_{k}^{c}\right\} }.
\end{align*}
\item %The final output is 
%\[
%\left\{ \hat{\gamma}_{1}^{k}(X_{i}),\hat{\gamma}_{0}^{k}(X_{i}),\hat{\omega}_{1}^{k}(X_{i}),\hat{\omega}_{0}^{k}(X_{i}),Y_{i},D_{i}\right\} ,i\in I_{k},k=1\ldots K.
%\]
For each $i\in I_{k}$, the debiased weight is
\begin{align*}
\hat{\xi}(Z_i) & =\left[\hat{\gamma}_{1}^{k}(X_{i})-\hat{\gamma}_{0}^{k}(X_{i})\right]^{2}\\
 & +\left[D_{i}\hat{\omega}_{1}^{k}(X_{i})(Y_{i}-\hat{\gamma}_{1}^{k}(X_{i}))-\left(1-D_{i}\right)\hat{\omega}_{0}^{k}(X_{i})(Y_{i}-\hat{\gamma}_{0}^{k}(X_{i}))\right].
\end{align*}
\end{enumerate}



\section{Additional results for Appendix \ref{sec:lower.bound}}

\subsection{Proof of Lemma \ref{lem:Bayes_classification}}
Let $\mathbf{y}=(y_{1},\ldots,y_{N})^{\prime}$ be a realization of
$\mathbf{Y}$. For each $\mathbf{y}$ in the support of $\mathbf{Y}$,
the Bayes decision is
\[
g^{*}(\mathbf{y})=\begin{cases}
1 & Pr\{\mathrm{C}=1\mid\mathbf{y}\}\geq\frac{1}{2},\\
-1 & Pr\{\mathrm{C}=1\mid\mathbf{y}\}<\frac{1}{2},
\end{cases}
\]
and $Pr\left\{ g^{*}(\mathbf{Y})\neq\mathrm{C}\right\} =\mathbb{E}\left[\min\left\{ Pr\{\mathrm{C}=1\mid\mathbf{\mathbf{Y}}\},1-Pr\{\mathrm{C}=1\mid\mathbf{\mathbf{Y}}\}\right\} \right]$,
where $\mathbb{E}[\cdotp]$ is with respect to the marginal distribution
of $\mathbf{\mathbf{\mathbf{Y}}}$. Applying Bayes rule yields
\[
\begin{aligned} & Pr\{\mathrm{C}=1\mid\mathbf{y}\}
%= & \frac{Pr\{\mathrm{C}=1\}f\{\mathbf{y}\mid\mathrm{C}=1\}}{Pr\{\mathrm{C}=1\}f\{\mathbf{y}\mid\mathrm{C}=1\}+Pr\{\mathrm{C}=1\}f\{\mathbf{y}\mid\mathrm{C}=-1\}}\\
=  \frac{f\{\mathbf{y}\mid\mathrm{C}=1\}}{f\{\mathbf{y}\mid\mathrm{C}=1\}+f\{\mathbf{y}\mid\mathrm{C}=-1\}},
\end{aligned}
\]
where $f\{\mathbf{y}\mid\mathrm{C}=1\}$ is the pdf of $\mathbf{Y}$
given $\mathrm{C}=1$, and $f\{\mathbf{y}\mid\mathrm{C}=-1\}$ is
the pdf of $\mathbf{Y}$ given $\mathrm{C}=-1$. Algebra shows 
\begin{align*}
f\{\mathbf{y}\mid\mathrm{C}=1\}) & =\Pi_{j=1}^{N}f(y_{j}\mid\mathrm{C}=1)\\
 & =\begin{cases}
1, & \text{\ensuremath{y_{j}}}\in\left[\text{ \ensuremath{\frac{u_{j}-1}{2}}},\text{ \ensuremath{\frac{u_{j}+1}{2}}}\right],j=1\ldots N,\\
0, & \text{otherwise},
\end{cases}
\end{align*}
and
\begin{align*}
f\{\mathbf{y}\mid\mathrm{C}=-1\}) & =\Pi_{j=1}^{N}f(y_{j}\mid\mathrm{C}=-1)\\
 & =\begin{cases}
1, & \text{\ensuremath{y_{j}}}\in\left[\text{ \ensuremath{\frac{\mathrm{-}u_{j}-1}{2}}},\text{ \ensuremath{\frac{-u_{j}+1}{2}}}\right],j=1\ldots N,\\
0, & \text{otherwise}.
\end{cases}
\end{align*}
Therefore, 
\begin{align*}
 & \min\left\{ Pr\{\mathrm{C}=1\mid\mathbf{\mathbf{Y}}\},1-Pr\{\mathrm{C}=1\mid\mathbf{\mathbf{Y}}\}\right\} \\
= & \begin{cases}
\frac{1}{2}, & \text{\ensuremath{y_{j}}}\in\left[\text{ \ensuremath{\frac{u_{j}-1}{2}}},\frac{-u_{j}+1}{2}\right],j=1,\ldots N,\\
0, & \text{otherwise}.
\end{cases}
\end{align*}
It follows 
\begin{align*}
Pr\left\{ g^{*}(\mathbf{Y})\neq\mathrm{C}\right\}  & =\frac{1}{2}Pr\left\{ \text{\ensuremath{Y_{j}}}\in\left[\text{ \ensuremath{\frac{u_{j}-1}{2}}},\frac{-u_{j}+1}{2}\right],j=1,\ldots N\right\} \\
 & =\frac{1}{2}\prod_{i=1}^{N}Pr\left\{ \text{\ensuremath{Y_{j}}}\in\left[\text{ \ensuremath{\frac{u_{j}-1}{2}}},\frac{-u_{j}+1}{2}\right]\right\} 
\end{align*}
where for all $j=1\ldots N$,
\begin{align*}
 & Pr\left\{ \text{\ensuremath{Y_{j}}}\in\left[\text{ \ensuremath{\frac{u_{j}-1}{2}}},\frac{-u_{j}+1}{2}\right]\right\} \\
= & \frac{1}{2}Pr\left\{ \text{\ensuremath{Y_{j}}}\in\left[\text{ \ensuremath{\frac{u_{j}-1}{2}}},\frac{-u_{j}+1}{2}\right]\mid C=1\right\} \\
+ & \frac{1}{2}Pr\left\{ \text{\ensuremath{Y_{j}}}\in\left[\text{ \ensuremath{\frac{u_{j}-1}{2}}},\frac{-u_{j}+1}{2}\right]\mid C=-1\right\} \\
= & 1-u_{j}.
\end{align*}
We then conclude 
\begin{align*}
Pr\left\{ g^{*}(\mathbf{Y})\neq\mathrm{C}\right\}  & =\prod_{j=1}^{N}\left(1-u_{j}\right) \geq\left(1-\max_{j\in\left\{ 1,\ldots,N\right\} }u_{j}\right)^{N}\\
 & \geq1-N\max_{j\in\left\{ 1,\ldots,N\right\} }u_{j}\geq1-N\left\Vert u\right\Vert .
\end{align*}

