\paragraph*{Step 3}

For an arbitrary rule $\delta_{n}$, we show that its excess risk
can be lowered bounded by classification problem. First note that,
for all $P\in\mathcal{P}(s,C)$, we have 
\begin{align*}
L(\delta_{n},\tau) & =\mathbb{E}\left[\tau^{2}(X)\left(\mathbf{1}\left\{ \tau(X)\geq0\right\} -\delta_{n}(W)\right)^{2}\right] =\mathbb{E}\left[\left(\mathbf{1}\left\{ X_{1}\geq0\right\} -\delta_{n}(W)\right)^{2}\right].
\end{align*}
%where $\mathbb{E}[\cdotp]$ is expectation with respect to $P$. 
As
a result, 
$\delta^{*}(w)=Pr\left\{ X_{1}=1\mid W=w\right\} =m(w)$, and
\[
L(\delta_{n},\tau)-L(\delta^{*},\tau)=\int\left(\delta_{n}(w)-m(w)\right)^{2}dF_{W}(w).
\]
Then, we have
\begin{align*}
 & \sup_{P\in\mathcal{P}(s,c)}\mathbb{E}_{P_{n}}\left[L(\delta_{n},\tau)-L(\delta^{*},\tau)\right]\\
\geq & \sup_{P\in\mathcal{P}^{\mathcal{C}_{n}}}\mathbb{E}_{P_{n}}\left[L(\delta_{n},\tau)-L(\delta^{*},\tau)\right]\\
= & \sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\mathbb{E}_{P_{n}}\left[\int\left(\delta_{n}(w)-m^{(c_{n})}(w)\right)^{2}dF_{W}(w)\right].
\end{align*}
Furthermore, we can write each $\delta_{n}$ as $\delta_{n}=\frac{1}{2}+\frac{1}{2}m_{n}$
for some $m_{n}\in[-1,1]$, and we can also write $m^{(c_{n})}(w)=\frac{1}{2}+\frac{1}{2}\tilde{m}^{(c_{n})}(w),$where
$\tilde{m}^{(c_{n})}(w)=\sum_{j=1}^{S_{n}}c_{n,j}g_{n,j}(w)\in[-1,1].$
Therefore,
\begin{align*}
 & \sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\mathbb{E}_{P_{n}}\left[\int\left(\delta_{n}(w)-m^{(c_{n})}(w)\right)^{2}dF_{W}(w)\right]\\
= & \frac{1}{4}\sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\mathbb{E}_{P_{n}}\left[\int\left(m_{n}(w)-\tilde{m}^{(c_{n})}(w)\right)^{2}dF_{W}(w)\right].
\end{align*}
Denote by $\hat{m}_{n}(x)=\sum_{j=1}^{S_{n}}\hat{c}_{n,j}g_{n,j}(w)$
the least squares projection of $m_{n}$ onto $\left\{ \tilde{m}^{(c_{n})}:c_{n}\in\mathcal{C}_{n}\right\} $,
which we note is an orthogonal system. Then,
\begin{align*}
 & \int\left(m_{n}(w)-\tilde{m}^{(c_{n})}(w)\right)^{2}dF_{W}(w)\\
\geq & \int\left(\hat{m}_{n}(w)-\tilde{m}^{(c_{n})}(w)\right)^{2}dF_{W}(w)\\
= & \sum_{j=1}^{S_{n}}\int_{A_{n,j}}\left(\hat{c}_{n,j}-c_{n,j}\right)^{2}g_{n,j}^{2}(w)dw\\
= & M_{n}^{-2s}M_{n}^{-d_{W}}\left(\sum_{j=1}^{S_{n}}\left(\hat{c}_{n,j}-c_{n,j}\right)^{2}\right)\int g^{2}(w)dw.
\end{align*}
Let $\tilde{c}_{n,j}=1$ if $\hat{c}_{n,j}\geq0$ and $-1$ otherwise.
As 
$\left|\hat{c}_{n,j}-c_{n,j}\right|\geq\frac{\left|\tilde{c}_{n,j}-c_{n,j}\right|}{2}$,
we have 
\[
\sum_{j=1}^{S_{n}}\left(\hat{c}_{n,j}-c_{n,j}\right)^{2}\geq\frac{1}{4}\sum_{j=1}^{S_{n}}\left(\tilde{c}_{n,j}-c_{n,j}\right)^{2}=\sum_{j=1}^{S_{n}}\mathbf{1}\left\{ \tilde{c}_{n,j}\neq c_{n,j}\right\} .
\]
In summary, we have 
\begin{align*}
 & \sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\mathbb{E}_{P_{n}}\left[\int\left(m_{n}(w)-\tilde{m}^{(c_{n})}(w)\right)^{2}dF_{W}(w)\right]\\
\geq & M_{n}^{-(2s+d_{W})}\int g^{2}(w)d(w)\sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\mathbb{E}_{P_{n}}\left[\sum_{j=1}^{S_{n}}\mathbf{1}\left\{ \tilde{c}_{n,j}\neq c_{n,j}\right\} \right]\\
\geq & M_{n}^{-(2s+d_{W})}S_{n}C^{2}\int\bar{g}^{2}(x)dx\sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\mathbb{E}_{P_{n}}\left[\frac{1}{S_{n}}\left(\sum_{j=1}^{S_{n}}\mathbf{1}\left\{ \tilde{c}_{n,j}\neq c_{n,j}\right\} \right)\right],
\end{align*}
where note 
\[
\liminf_{n\rightarrow\infty}\frac{M_{n}^{-(2s+d_{W})}S_{n}C^{2}}{C^{\frac{2d_{W}}{6s+3d_{W}}}n^{-\frac{2s}{(2s+d_{W})}}}>0,\int\bar{g}^{2}(x)dx>0.
\]
Thus, it suffices to show
\[
\liminf_{n\rightarrow\infty}\sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\left[\frac{1}{S_{n}}\left(\sum_{j=1}^{S_{n}}Pr\left\{ \tilde{c}_{n,j}\neq c_{n,j}\right\} \right)\right]>0
\]
and does not depend on $C$. To this end, let $C_{n,1},\ldots C_{n,M_{n}^{d}}$
be a sequence of iid random variables independent of data $Z^{n}=\left\{ Y_{i},D_{i},X_{1i},W_{i}\right\} _{i}^{n}$,
and satisfy $Pr\{C_{n,1}=1\}=Pr\{C_{n,1}=-1\}=1/2$. Let $C_{n}:=(C_{n,1},\ldots,C_{n,S_{n}})$.
Then,
\begin{align*}
\sup_{m^{(c_{n})}\in\mathcal{F}^{\mathcal{C}_{n}}}\left[\frac{1}{S_{n}}\left(\sum_{j=1}^{S_{n}}Pr\left\{ \tilde{c}_{n,j}\neq c_{n,j}\right\} \right)\right]\geq\frac{1}{S_{n}}\left(\sum_{j=1}^{S_{n}}Pr\left\{ \tilde{c}_{n,j}\neq C_{n,j}\right\} \right),
\end{align*}
where $\tilde{c}_{n,j}$ can be viewed as a binary decision using
data $Z^{n}$ on $C_{n,j}$. For each $j=1,\ldots,S_{n}$:
\[
Pr\left\{ \tilde{c}_{n,j}\neq C_{n,j}\right\} =\mathbb{E}_{P_{n}}\left[Pr\left\{ \tilde{c}_{n,j}\neq C_{n,j}\mid Y_{i},D_{i},W_{i},i=1,\ldots,n\right\} \right].
\]
Denote by $\left\{ \left\{ Y_{i_{1}},D_{i_{1}},W_{i_{1}}\right\} ,\ldots,\left\{ Y_{i_{l}},D_{i_{l}},W_{i_{l}}\right\} \right\} $
those units such that $W_{i}\in A_{n,j}$. Note 
$X_{1i_{q}}=\text{sgn}\left(V_{1i_{q}}\right)$,
where 
$
\text{ \ensuremath{V_{1i_{q}}}=\ensuremath{\frac{1}{2}}+\ensuremath{\frac{1}{2}C_{n,j}}}g_{n,j}(W_{i_{q}})+\varepsilon_{i_{q}}$
for all $q=1\ldots l$, and $\left\{ \varepsilon_{i_{q}}\right\} _{q=1\ldots l}$
are iid and uniformly distributed in $[-1,0]$. In addition, $\left((X_{1i,i=1\ldots n}\setminus(X_{1i_{1}},\ldots,X_{1i_{l}})\right)$
depends only on $C\setminus\left\{ C_{n,j}\right\} $ and on $W_{i}$
for those $i\notin\left\{ i_{1},\ldots i_{l}\right\} $. Therefore,
the following must hold:
\begin{align*}
 & Pr\left\{ \tilde{c}_{n,j}\neq C_{n,j}\mid Y_{i},D_{i},W_{i},i=1,\ldots,n\right\} \\
\geq & Pr\left\{ C_{n,j}^{B}\neq C_{n,j}\mid Y_{i},D_{i},W_{i},i=1,\ldots,n\right\} ,
\end{align*}
where $C_{n,j}^{B}$ is the conditional Bayes decision for $C_{n,j}$
that only uses data $\left\{ W_{i_{1}}\ldots W_{i_{l}}\right\} $
and $\left\{ V_{i_{1}},\ldots,V_{i_{l}}\right\} $. 

\paragraph*{Step 4}

We derive the Bayes risk of the conditional Bayes rule $C_{n,j}^{B}$
defined in Step 3. Applying Lemma \ref{lem:Bayes_classification}, we have 
\begin{align*}
 & Pr\left\{ C_{n,j}^{B}\neq C_{n,j}\mid Y_{i},D_{i},W_{i},i=1,\ldots,n\right\} \\
\geq & 1-l\sqrt{\sum_{q=1}^{l}g_{n,j}^{2}(W_{i_{q}})}
\geq  1-n\sqrt{\sum_{i=1}^{n}g_{n,j}^{2}(W_{i})}.
\end{align*}
 Then, law of iterated expectations and Jensen's inequality together
yields
\begin{align*}
Pr\left\{ C_{n,j}^{B}\neq C_{n,j}\right\}  & =\mathbb{E}\left\{ Pr\left\{ C_{n,j}^{B}\neq C_{n,j}\mid Y_{i},D_{i},W_{i},i=1,\ldots,n\right\} \right\} \\
 & \geq1-n\sqrt{n\mathbb{E}\left[g_{n,j}^{2}(W)\right]}\\
 & =1-\sqrt{n^{3}M_{n}^{-\left(2s+d_{W}\right)}\int g^{2}(x)dx}\\
 & \geq1-\sqrt{\int\bar{g}^{2}(x)dx}>0.
\end{align*}





