	\section{Upper and lower bounds on the distance between $\l_1$ and $\l_n$}
	We use the same notation as in the previous section. Notably, $p(x)$ is a monic polynomial given by
	\begin{equation*}
		p(x) = a_nx^n+a_{n-1}x^{n-1}+ \dots +a_0, \text{~~with~~} a_0 \neq 0 \text{~~and~~} n \geq 2,
	\end{equation*}
	and $q(x)$ is its monic reversal polynomial. Let $\l_1, \l_2, \dots, \l_n$ be the roots of $p(x)$ not necessary distinct and listed in non-decreasing order of their absolute values, i.e.,
	$$|\l_1| \leq |\l_2| \leq \dots \leq |\l_n|.$$
	We let $C_1$ and $C_2$ be companion matrices associated, respectively, with $p(x)$ and $q(x)$. We let $N_1$ and $N_2$ be any two matrix norms (not necessarily distinct) on the set of $n\times n$ complex matrices.

	Two quantities that are useful in the numerical analysis of polynomials are the root spread and the absolute root spread of $p(x)$.  The first is the largest distance between two roots of $p(x)$ and has the form $\max_{i,j} |\l_j - \l_i|$, \cite{ED}.  The second one is also called the modulus root spread of $p(x)$ and consists of the largest difference between two absolute values of the roots of $p(x)$ which is simply $|\l_n| - |\l_1|$. Each of these has an upper bound that is an immediate consequence of Theorem \ref{t1}.
	%
	\begin{theorem}\label{t4}
		For every $(k_1, k_2) \in \mathbb{N}^2$, we have
		\begin{equation}
			|\l_n| - |\l_1| \leq \sqrt[k_1]{N_1(C_1^{k_1})} - \sqrt[-k_2]{N_2(C_2^{k_2})},
		\end{equation}
		and
		\begin{equation}
			\max_{i,j} |\l_j - \l_i| \leq 2 \sqrt[k_1]{N_1(C_1^{k_1})}.
		\end{equation}
	\end{theorem}

	The next theorem is about the quantity $|\l_n - \l_1|$ which can be bounded based on Theorem \ref{t1}. It can be regarded as an upper bound on the minimal root distance $\Big(\displaystyle{\min_{i,j}|\l_j - \l_i|}\Big)$, which is useful in analyzing the stability and sensitivity of $p(x)$.
	\begin{theorem} \label{t3}
		For every $(k_1, k_2) \in \mathbb{N}^2$, we have the following.
		\begin{enumerate}
			\item If the points corresponding to $\l_1$ and $\l_n$ in the complex plane lie on the same ray extending from the origin, then
			%for every $\xi > 0$, there exists a positive integer $k_0$ such that  for $k\geq k_0$ we have
			\begin{equation}
				|\l_n-\l_1| \leq \sqrt[k_1]{N_1(C_1^{k_1})} ~~- \sqrt[-k_2]{N_2(C_2^{k_2})}.
			\end{equation}
			\item If the points corresponding to  $\l_1, \l_n$ and 0 are collinear, but  $\l_1$ and $\l_n$ lie on opposite rays extending from the origin, then for every $\varepsilon > 0$ there exists a positive integer $k_0$ such that
			\begin{equation*}\
				|\l_n-\l_1| > \sqrt[k]{N_1(C_1^{k})} + \sqrt[-k]{N_2(C_2^{k})} - \varepsilon,
			\end{equation*}
			for every integer $k > k_0$.
			\item If the points corresponding to $\l_1, \l_n$ and $0$ are not collinear, then there exist positive numbers $\gamma_1$ and $\gamma_2$ such that for every $\varepsilon_1 \in [0, \gamma_1)$
			and  every $\varepsilon_2 \in [0, \gamma_2)$, there exists an integer $k_0$ such that
			\begin{equation}\label{ff28}
				\sqrt[k]{N_1(C_1^{k})} - \sqrt[-k]{N_2(C_2^{k})} ~+~ \varepsilon_1 < |\l_n - \l_1| < \sqrt[k]{N_1(C_1^{k})} + \sqrt[-k]{N_2(C_2^{k})} ~-~ \varepsilon_2,
			\end{equation}
			for every integer $k > k_0$.
			\item The above three assertions remain valid if $C_1$ is any nonsingular $n \times n$ complex matrix with $n\geq2$ and $C_2$ is its inverse matrix or any other square complex matrix for which the largest and smallest eigenvalues in absolute values are, respectively, $1/\l_1 \text{~ and ~} 1/\l_n$.
			\end{enumerate}
		%
	\end{theorem}
	\begin{proof}
		To relax the notation, we let $U_k = \sqrt[k]{N_1(C_1^{k})}$ and $L_k = \sqrt[-k]{N_2(C_2^{k})}$.  It follows from (\ref{ff24}) that $|\l_n|-|\l_1| \leq U_k - L_k$.  If $\l_1$ and $\l_n$ lie on the same ray extending from the origin, then $|\l_n|-|\l_1| = |\l_n - \l_1|$ and the first assertion follows.

		By (\ref{ff22}), for every positive $\varepsilon$, there exists a positive integer $k_0$ such that $U_k - |\l_n| < \varepsilon$ for every integer $k > k_0$. Combining this with the fact that $|\l_1| \geq L_k$, we obtain $|\l_n| + |\l_1| > U_k + L_k - \varepsilon$. Then the inequality in the second assertion is obtained by using the fact that $|\l_n|+|\l_1| = |\l_n - \l_1|$ when $\l_1, \l_n$ and $0$ are collinear with $0$ lying between $\l_1$ and $\l_n$.

		To prove the third assertion, recall that, in general, $|\l_n|-|\l_1| \leq |\l_n-\l_1| \leq |\l_n| + |\l_1|$ . However, if $\l_1, \l_n$ and $0$ are not collinear in the complex plane, then the inequalities in the above expression become strict, i.e.,
		\begin{equation}\label{ff27}
			|\l_n|-|\l_1| < |\l_n-\l_1| < |\l_n| + |\l_1|.
		\end{equation}
		Note that (\ref{ff27}) is assumed here to be a well-known fact that can be verified by either algebraic or geometric arguments.  Therefore, the numbers $\gamma_1 = |\l_n-\l_1| + |\l_1| - |\l_n|$ and $\gamma_2 = |\l_1| + |\l_n| - |\l_n-\l_1|$ are strictly positive.  Let $a$ be any number in $(0,\gamma_1]$. Then by (\ref{ff22}), there exists a positive integer $k_1$ such that $\big|U_k - |\l_n|\big| < a / 2 ~$ and $~\big||\l_1|-L_k\big| < a / 2~$ for every integer $k>k_1$. Since $U_k \geq |\l_n|$ and $|\l_1| \geq L_k$, it follows that $U_k - |\l_n| < a / 2$ and $ |\l_1|-L_k < a/2$. Consequently we obtain $U_k-L_k - a < |\l_n|-|\l_1| = |\l_n-\l_1| - \gamma_1$ which leads to $U_k-L_k + \gamma_1 - a < |\l_n-\l_1|$. Now set $\varepsilon_1 = \gamma_1 - a$ and notice that since $a\in (0, \gamma_1]$, $\varepsilon_1$ takes all the values in $[0,\gamma_1)$. This is to prove the left inequality in the third assertion.

		To prove the right inequality, let $b$ be any real number in $(0 , \gamma_2]$. There exists a positive integer $k_2$ such that $|\l_1| < L_k + b$ for every integer $k > k_2$. Combine this with the fact that $ |\l_n| \leq U_k$ to get $|\l_n| + |\l_1| < U_k + L_k + b$. Since $|\l_n| + |\l_1| =|\l_n - \l_1| + \gamma_2$, it follows that $|\l_n - \l_1| < U_k + L_k - (\gamma_2 - b)$. Then set $\varepsilon_2 = \gamma_2 - b$ and notice that $\varepsilon_2$ takes all the values in $[0,\gamma_2)$. To complete the proof of the third assertion, take $k_0 = \max \{k_1, k_2\}$.  The fourth assertion follows from Remark \ref{r1}.
	\end{proof}

	\begin{rem}\leavevmode
		\begin{enumerate}
			\item It turns out for some polynomials that $\displaystyle{\max_{ij}|\l_j - \l_i| = |\l_n - \l_1|}$. In this case, Theorem \ref{t3} is providing bounds for the root spread of the polynomial.
			\begin{comment}
			\item Theorem \ref{t3} tells us that if $\l_1$ and $\l_n$ are not aligned with the origin, then the distance $d$ between them remains comprised between\\
			$ b_1 = \displaystyle{\sqrt[k]{N_1(C_1^{k})} - \sqrt[-k]{N_2(C_2^{k})}}$
			and
			$ b_2 =\displaystyle{\sqrt[k]{N_1(C_1^{k})} + \sqrt[-k]{N_2(C_2^{k})}}$.\\
			That is, $b_1 \leq d \leq b2$.
			If $\l_1$ and $\l_n$ lie on the same ray extending from the origin, then the distance $d \leq b1$. However Theorem \ref{t2} implies that $d$ gets closer to $b_1$ as the powers of $C_1$ and $C_2$ increases.
			If $\l_1$ and $\l_n$ lie on opposite rays extending from the origin, then with higher power $k$ of each of $C_1$ and $C_2$, the distance $d$ move closer to $b_2$ but may stay in one side of it $d \geq b_2$, or may change in terms of $k$. This behavior depends on the degree and coefficient of $p(x)$.
			\end{comment}
			\item The bounds given by Theorem \ref{t4} and Theorem \ref{t3} can be improved using Matrix Balancing in the same way as in the previous section.
		\end{enumerate}
	\end{rem}

